local 战斗处理类 = class()
local jhf = string.format

function 战斗处理类:初始化()
end

function 战斗处理类:设置断线玩家(id)
	for n = 1, #self.参战玩家 do
		if self.参战玩家[n].id == id then
			self.参战玩家[n].断线 = true
		end
	end
end

function 战斗处理类:设置重连玩家(id)
	local 编号 = 0

	for n = 1, #self.参战玩家 do
		if self.参战玩家[n].id == id then
			self.参战玩家[n].断线 = false
			self.参战玩家[n].断线等待 = true
			self.参战玩家[n].连接id = 玩家数据[id].连接id
			编号 = n
		end
	end

	if 编号 == 0 then
		玩家数据[id].战斗 = 0

		return
	end

	发送数据(self.参战玩家[编号].连接id, 5501.1, {
		天气 = self.天气
	})

	local 战斗单位编号 = self:取参战编号(self.参战玩家[编号].id, "角色")

	发送数据(self.参战玩家[编号].连接id, 5501, {
		音乐 = 50,
		id = self.参战玩家[编号].队伍,
		总数 = #self.参战单位
	})

	local x待发送数据 = {}

	for i = 1, #self.参战单位 do
		x待发送数据[i] = self:取加载信息(i)
	end

	发送数据(self.参战玩家[编号].连接id, 5515, x待发送数据)

	local 血量 = {}

	for n = 1, #self.参战单位 do
		血量[n] = self:取加载信息(n)
	end

	发送数据(self.参战玩家[编号].连接id, 5520, 血量)

	x待发送数据 = {}
	self.参战玩家[编号].重连加载 = true

	if self.回合进程 == "命令回合" then
		local 剩余命令时间 = 服务端参数.回合命令时间 - (os.time() - self.等待起始)
		local 目标 = {
			战斗单位编号
		}

		if self.参战单位[战斗单位编号].召唤兽 ~= nil then
			目标[2] = self.参战单位[战斗单位编号].召唤兽
		end

		if self.参战单位[战斗单位编号].助战明细 ~= nil then
			for i = 1, #self.参战单位[战斗单位编号].助战明细 do
				目标[#目标 + 1] = self.参战单位[战斗单位编号].助战明细[i]
			end
		end

		发送数据(self.参战玩家[编号].连接id, 5503.1, {
			目标,
			self.回合数,
			math.floor(剩余命令时间 / 10),
			剩余命令时间 % 10
		})
	end

	if self.回合进程 == "执行回合" and #self.参战玩家 == 1 then
		self.执行等待 = 0
	end

	if self.执行等待 == 0 then
		self.执行等待 = self.执行等待 + 5

		发送数据(self.参战玩家[编号].连接id, 38, {
			频道 = "xt",
			内容 = format("#G你已经重新加入战斗，预计将在#Y%s#G秒后同步战斗操作。", 5)
		})
	else
		发送数据(self.参战玩家[编号].连接id, 38, {
			频道 = "xt",
			内容 = format("#G你已经重新加入战斗，预计将在#Y%s#G秒后可以下达战斗指令。当其他玩家进入下达命令回合时，您将提前结束等待。", self.执行等待 - os.time())
		})
	end
end

function 战斗处理类:设置断线重连(id)
	local 编号 = 0

	for n = 1, #self.参战玩家 do
		if self.参战玩家[n].id == id then
			self.参战玩家[n].断线 = false
			self.参战玩家[n].断线等待 = true
			self.参战玩家[n].连接id = 玩家数据[id].连接id
		end

		编号 = n
	end

	local 死亡计算 = {
		0,
		0
	}

	for n = 1, #self.参战单位 do
		if self.参战单位[n].气血 <= 0 or self.参战单位[n].捕捉 or self.参战单位[n].逃跑 then
			if self.参战单位[n].队伍 == self.队伍区分[1] then
				死亡计算[1] = 死亡计算[1] + 1
			else
				死亡计算[2] = 死亡计算[2] + 1
			end
		end
	end

	if self.队伍数量[1] <= 死亡计算[1] then
		self.回合进程 = "结束回合"

		self:结束战斗(self.队伍区分[2], self.队伍区分[1])

		return
	elseif self.队伍数量[2] <= 死亡计算[2] then
		self.回合进程 = "结束回合"

		self:结束战斗(self.队伍区分[1], self.队伍区分[2])

		return
	end

	self.参战玩家[编号].重连加载 = true

	if self.执行等待 == 0 then
		self.执行等待 = self.执行等待 + 5

		发送数据(self.参战玩家[编号].连接id, 38, {
			频道 = "xt",
			内容 = format("#G你已经重新加入战斗，预计将在#Y%s#G秒后同步战斗操作。", self.执行等待 - os.time())
		})
	else
		发送数据(self.参战玩家[编号].连接id, 38, {
			频道 = "xt",
			内容 = format("#G你已经重新加入战斗，预计将在#Y%s#G秒后可以下达战斗指令。当其他玩家进入下达命令回合时，您将提前结束等待。", self.执行等待 - os.time())
		})
	end
end

function 战斗处理类:设置观战玩家(观战id, id)
	local 编号 = 0

	for n = 1, #self.参战玩家 do
		if self.参战玩家[n].id == 观战id then
			编号 = n
		end
	end

	发送数据(玩家数据[id].连接id, 5501, {
		id = self.参战玩家[编号].队伍,
		音乐 = self.战斗类型,
		总数 = #self.参战单位
	})

	local x待发送数据 = {}

	for i = 1, #self.参战单位 do
		x待发送数据[i] = self:取加载信息(i)
	end

	发送数据(玩家数据[id].连接id, 5516, x待发送数据)

	self.观战玩家[id] = {
		数字id = id,
		连接id = 玩家数据[id].连接id
	}

	if self.执行等待 == 0 then
		self.执行等待 = os.time() + 5

		发送数据(玩家数据[id].连接id, 38, {
			频道 = "xt",
			内容 = format("#G你已经进入观战，预计将在#Y%s#G秒后同步观战方战斗操作。", self.执行等待 - os.time())
		})
	else
		发送数据(玩家数据[id].连接id, 38, {
			频道 = "xt",
			内容 = format("#G你已经进入观战，预计将在#Y%s#G秒后同步观战方战斗操作。", self.执行等待 - os.time())
		})
	end
end

function 战斗处理类:删除观战玩家(观战id)
	self.观战玩家[观战id] = nil
end

function 战斗处理类:进入战斗(玩家id, 序号, 任务id, 地图)
	self.待消除状态 = {}
	self.击退列表 = {}
	self.忽视防御 = 1
	self.薪火相传血量 = 0
	self.召唤加回合 = 0
	self.连击判定 = false
	self.反击挨打返回 = 0
	self.普攻被反击流程 = 0
	self.法术吸血流程 = {}
	self.物攻流程 = 0
	self.不施法 = false
	self.可捕捉变异 = {}
	self.逍遥游增伤 = 0
	self.恐吓击飞 = 0
	self.战斗前附加状态 = 0
	self.五行加成 = 0
	self.战斗类型 = 序号
	self.任务id = 任务id
	self.玩家胜利 = true
	self.战斗发言数据 = {}
	self.队长单位 = {}
	self.同门派减伤 = {}
	self.战斗失败 = false
	self.观战玩家 = {}
	self.中断计算 = false
	self.参战单位 = {}
	self.助攻列表 = {}
	self.法术助攻列表 = {}
	self.临时属性 = {}
	self.参战玩家 = {}
	self.进入战斗玩家id = 玩家id
	self.飞升序号 = 0
	self.战斗计时 = os.time()
	self.加载等待 = 7
	self.回合进程 = "加载回合"
	self.等待时间 = {
		延迟 = 2,
		初始 = 60
	}
	self.队伍数量 = {
		[1.0] = 0,
		[2.0] = 0
	}
	self.观战方 = 玩家id
	self.对战方 = 任务id
	self.防卡战斗 = {
		执行 = false,
		回合 = 0,
		时间 = os.time()
	}
	self.pk战斗 = false
	self.阵法使用 = true
	self.结束等待 = 0
	self.好友度列表 = {}
	self.助战好友度 = {}
	self.队伍战神 = {}
	self.战斗地图 = 玩家数据[玩家id].角色.数据.地图数据.编号

	if 天气地图[tostring(self.战斗地图)] ~= nil then
		self.天气 = 地区天气[天气地图[tostring(self.战斗地图)]] + 0
	else
		self.天气 = 0
	end

	self.加载数量 = 0
	self.等待起始 = 0
	self.战斗类型 = 序号
	self.执行等待 = 0
	self.最低执行时间 = 0
	self.回合数 = 0
	self.同门死亡 = false
	self.是否执行行动 = {}
	self.执行中复活单位 = {}
	self.回合中复活 = false
	self.溅射排除单位 = {}

	if 玩家数据[玩家id].队伍 == 0 then
		self.发起id = 玩家id
	else
		self.发起id = 玩家数据[玩家id].队伍
	end

	self.队伍区分 = {
		self.发起id,
		[2.0] = 0
	}
	self.战斗脚本 = nil
	local 战斗脚本名 = "BattleScripts/battle_" .. 序号

	if 文件是否存在(战斗脚本名 .. ".lua") then
		self.战斗脚本 = require(战斗脚本名)(玩家数据[玩家id].战斗)
	end

	self.玩家数据 = {}

	if 玩家数据[玩家id].队伍 == 0 then
		self.玩家数据[1] = {
			位置 = 1,
			id = 玩家id,
			队伍 = 玩家id
		}
	else
		local 临时队伍 = 玩家数据[玩家id].队伍

		for n = 1, #队伍数据[临时队伍].成员数据 do
			if 队伍处理类:取是否助战(玩家数据[玩家id].队伍, n) == 0 then
				self.玩家数据[#self.玩家数据 + 1] = {
					id = 队伍数据[临时队伍].成员数据[n],
					队伍 = 临时队伍,
					位置 = n
				}
				local 我的id = 队伍数据[临时队伍].成员数据[n]

				for i = n + 1, #队伍数据[临时队伍].成员数据 do
					local 你的id = 队伍数据[临时队伍].成员数据[i]

					if 我的id ~= 你的id and 队伍处理类:取是否助战(玩家数据[玩家id].队伍, i) == 0 then
						for a = 1, #玩家数据[我的id].角色.数据.好友数据.好友 do
							if 玩家数据[我的id].角色.数据.好友数据.好友[a].id == 你的id then
								for w = 1, #玩家数据[你的id].角色.数据.好友数据.好友 do
									if 玩家数据[你的id].角色.数据.好友数据.好友[w].id == 我的id then
										玩家数据[你的id].角色.数据.好友数据.好友[w].好友度 = (玩家数据[你的id].角色.数据.好友数据.好友[w].好友度 or 0) + 1
										玩家数据[我的id].角色.数据.好友数据.好友[a].好友度 = (玩家数据[我的id].角色.数据.好友数据.好友[a].好友度 or 0) + 1

										if 玩家数据[我的id].角色.数据.好友数据.好友[a].好友度 ~= 玩家数据[你的id].角色.数据.好友数据.好友[w].好友度 then
											玩家数据[我的id].角色.数据.好友数据.好友[a].好友度 = math.min(玩家数据[我的id].角色.数据.好友数据.好友[a].好友度,
												玩家数据[你的id].角色.数据.好友数据.好友[w].好友度)
											玩家数据[你的id].角色.数据.好友数据.好友[w].好友度 = 玩家数据[我的id].角色.数据.好友数据.好友[a].好友度 + 0
										end

										if self.好友度列表[我的id] == nil then
											self.好友度列表[我的id] = {}
										end

										self.好友度列表[我的id][你的id] = 玩家数据[我的id].角色.数据.好友数据.好友[a].好友度 + 0

										if self.好友度列表[你的id] == nil then
											self.好友度列表[你的id] = {}
										end

										self.好友度列表[你的id][我的id] = 玩家数据[你的id].角色.数据.好友数据.好友[w].好友度 + 0
									end
								end
							end
						end
					end
				end
			else
				local 助战编号 = 队伍处理类:取助战编号(玩家数据[玩家id].队伍, n)
				local rzm = 玩家数据[玩家id].助战.数据[助战编号].认证码
				玩家数据[玩家id].助战.数据[助战编号].好友度 = (玩家数据[玩家id].助战.数据[助战编号].好友度 or 0) + 1

				if 玩家数据[玩家id].角色.数据.助战好友度 == nil then
					玩家数据[玩家id].角色.数据.助战好友度 = {}
				end

				玩家数据[玩家id].角色.数据.助战好友度[rzm] = (玩家数据[玩家id].角色.数据.助战好友度[rzm] or 0) + 1

				if 玩家数据[玩家id].角色.数据.助战好友度[rzm] ~= 玩家数据[玩家id].助战.数据[助战编号].好友度 then
					玩家数据[玩家id].角色.数据.助战好友度[rzm] = math.min(玩家数据[玩家id].角色.数据.助战好友度[rzm], 玩家数据[玩家id].助战.数据[助战编号].好友度)
					玩家数据[玩家id].助战.数据[助战编号].好友度 = 玩家数据[玩家id].角色.数据.助战好友度[rzm] + 0
				end

				if self.好友度列表[玩家id] == nil then
					self.好友度列表[玩家id] = {}
				end

				if self.好友度列表[rzm] == nil then
					self.好友度列表[rzm] = {}
				end

				self.好友度列表[玩家id][rzm] = 玩家数据[玩家id].助战.数据[助战编号].好友度 + 0
				self.好友度列表[rzm][玩家id] = 玩家数据[玩家id].助战.数据[助战编号].好友度 + 0
				self.助战好友度[rzm] = 助战编号
			end
		end

		for k, v in pairs(self.助战好友度) do
			for w, z in pairs(self.助战好友度) do
				if z ~= v and self.好友度列表[k][w] == nil then
					if 玩家数据[玩家id].助战.数据[v].助战好友度 == nil then
						玩家数据[玩家id].助战.数据[v].助战好友度 = {}
					end

					if 玩家数据[玩家id].助战.数据[z].助战好友度 == nil then
						玩家数据[玩家id].助战.数据[z].助战好友度 = {}
					end

					玩家数据[玩家id].助战.数据[v].助战好友度[w] = (玩家数据[玩家id].助战.数据[v].助战好友度[w] or 0) + 1
					玩家数据[玩家id].助战.数据[z].助战好友度[k] = (玩家数据[玩家id].助战.数据[z].助战好友度[k] or 0) + 1

					if 玩家数据[玩家id].助战.数据[v].助战好友度[w] ~= 玩家数据[玩家id].助战.数据[z].助战好友度[k] then
						玩家数据[玩家id].助战.数据[v].助战好友度[w] = math.min(玩家数据[玩家id].助战.数据[v].助战好友度[w],
							玩家数据[玩家id].助战.数据[z].助战好友度[k])
						玩家数据[玩家id].助战.数据[z].助战好友度[k] = 玩家数据[玩家id].助战.数据[v].助战好友度[w]
					end

					self.好友度列表[k][w] = 玩家数据[玩家id].助战.数据[v].助战好友度[w]
					self.好友度列表[w][k] = 玩家数据[玩家id].助战.数据[v].助战好友度[w]
				end
			end
		end

		self.助战好友度 = nil
	end

	if 序号 >= 200000 then
		self.挑战id = 任务id
		self.队伍区分[2] = self.挑战id

		if 玩家数据[self.挑战id].队伍 == 0 then
			self.玩家数据[#self.玩家数据 + 1] = {
				位置 = 1,
				id = self.挑战id,
				队伍 = self.挑战id
			}
		else
			for n = 1, #队伍数据[玩家数据[self.挑战id].队伍].成员数据 do
				if 队伍处理类:取是否助战(玩家数据[self.挑战id].队伍, n) == 0 then
					self.玩家数据[#self.玩家数据 + 1] = {
						id = 队伍数据[玩家数据[self.挑战id].队伍].成员数据[n],
						队伍 = self.挑战id,
						位置 = n
					}
					local 我的id = 队伍数据[玩家数据[self.挑战id].队伍].成员数据[n]

					for i = n, #队伍数据[玩家数据[self.挑战id].队伍].成员数据 do
						local 你的id = 队伍数据[玩家数据[self.挑战id].队伍].成员数据[i]

						if 我的id ~= 你的id then
							for a = 1, #玩家数据[我的id].角色.数据.好友数据.好友 do
								if 玩家数据[我的id].角色.数据.好友数据.好友[a].id == 你的id then
									for w = 1, #玩家数据[你的id].角色.数据.好友数据.好友 do
										if 玩家数据[你的id].角色.数据.好友数据.好友[w].id == 我的id then
											if 玩家数据[你的id].角色.数据.好友数据.好友[w].好友度 == nil then
												玩家数据[你的id].角色.数据.好友数据.好友[w].好友度 = 1
											else
												玩家数据[你的id].角色.数据.好友数据.好友[w].好友度 = 玩家数据[你的id].角色.数据.好友数据.好友[w].好友度 + 1
											end

											if 玩家数据[我的id].角色.数据.好友数据.好友[a].好友度 == nil then
												玩家数据[我的id].角色.数据.好友数据.好友[a].好友度 = 1
											else
												玩家数据[我的id].角色.数据.好友数据.好友[a].好友度 = 玩家数据[我的id].角色.数据.好友数据.好友[a].好友度 + 1
											end
										end
									end
								end
							end
						end
					end
				end
			end
		end
	end

	self.加载数量 = #self.玩家数据

	if 序号 < 200000 then
		if 序号 == 100001 then
			self:加载野外单位()
		elseif 序号 == 100007 then
			self:加载野外单位1()
		else
			self:加载指定单位(地图, 任务id)
		end
	end

	for n, v in pairs(self.玩家数据) do
		self.参战玩家[#self.参战玩家 + 1] = {
			断线 = false,
			退出 = false,
			队伍 = self.玩家数据[n].队伍,
			id = self.玩家数据[n].id,
			连接id = 玩家数据[self.玩家数据[n].id].连接id
		}

		self:加载单个玩家(self.玩家数据[n].id, self.玩家数据[n].位置)
	end

	self:重置单位属性()

	local 队伍御兽 = {}
	local 队伍静心 = {}
	local 队伍风行 = {}
	local 队伍贯通 = {}
	local 队伍忘形 = {}

	for i = 1, #self.参战单位 do
		if self.参战单位[i].待加属性 ~= nil and not 判断是否为空表(self.参战单位[i].待加属性) then
			for k, v in pairs(self.参战单位[i].待加属性) do
				self.参战单位[i][k] = (self.参战单位[i][k] or 0) + v
			end

			self.参战单位[i].待加属性 = nil
		end

		if self:取奇经八脉是否有(i, "静心", {
				落伽神女 = 1,
				莲台仙子 = 1,
				五行咒师 = 1
			}) then
			队伍静心[self.参战单位[i].队伍] = 3
		end

		if self:取奇经八脉是否有(i, "忘形") then
			队伍忘形[self.参战单位[i].队伍] = 3
		end

		if self:取奇经八脉是否有(i, "贯通") then
			队伍贯通[self.参战单位[i].队伍] = 0.04
		end

		if self:取奇经八脉是否有(i, "障眼") then
			if self.队伍障眼 == nil then
				self.队伍障眼 = {}
			end

			if self.队伍障眼[self.参战单位[i].队伍] == nil then
				self.队伍障眼[self.参战单位[i].队伍] = {}
			end

			self.队伍障眼[self.参战单位[i].队伍][i] = 1
		end

		if self:取奇经八脉是否有(i, "结阵") then
			if self.队伍结阵 == nil then
				self.队伍结阵 = {}
			end

			self.队伍结阵[self.参战单位[i].队伍] = 1
		end

		if self:取奇经八脉是否有(i, "利刃") then
			if self.队伍利刃 == nil then
				self.队伍利刃 = {}
			end

			self.队伍利刃[self.参战单位[i].队伍] = 1
		end

		if self:取奇经八脉是否有(i, "风行", "绝代妖娆") then
			队伍风行[self.参战单位[i].队伍] = (队伍风行[self.参战单位[i].队伍] or 0) + 10
		end

		if self:取奇经八脉是否有(i, "汲魂") then
			if self.汲魂单位 == nil then
				self.汲魂单位 = {}
			end

			self.汲魂单位[#self.汲魂单位 + 1] = i
		end

		if self:取奇经八脉是否有(i, "阎罗", "六道魍魉") then
			if self.阎罗单位 == nil then
				self.阎罗单位 = {}
			end

			self.阎罗单位[#self.阎罗单位 + 1] = i
		end

		if self:取奇经八脉是否有(i, "驭兽") and self:取是否有师门技能(i, "训兽诀") then
			队伍御兽[self.参战单位[i].队伍] = math.max(队伍御兽[self.参战单位[i].队伍] or 0, self.参战单位[i].被动技能.训兽诀)
		end
	end

	for i = 1, #self.参战单位 do
		if self.参战单位[i].类型 == "bb" then
			if 队伍御兽[self.参战单位[i].队伍] ~= nil then
				self.参战单位[i].伤害 = qz(self.参战单位[i].伤害 + 队伍御兽[self.参战单位[i].队伍] * 0.4)
				self.参战单位[i].防御 = qz(self.参战单位[i].防御 + 队伍御兽[self.参战单位[i].队伍] * 0.4)
				self.参战单位[i].灵力 = qz(self.参战单位[i].灵力 + 队伍御兽[self.参战单位[i].队伍] * 0.2)
				self.参战单位[i].法伤 = qz(self.参战单位[i].法伤 + 队伍御兽[self.参战单位[i].队伍] * 0.2)
				self.参战单位[i].法防 = qz(self.参战单位[i].法防 + 队伍御兽[self.参战单位[i].队伍] * 0.2)
			end
		else
			if 队伍静心[self.参战单位[i].队伍] ~= nil and self.参战单位[i].类型 == "角色" and self.参战单位[i].玩家id ~= 0 then
				self.参战单位[i].封印抵抗率 = (self.参战单位[i].封印抵抗率 or 0) + 队伍静心[self.参战单位[i].队伍]
			end

			if 队伍忘形[self.参战单位[i].队伍] ~= nil and self.参战单位[i].类型 == "角色" and self.参战单位[i].玩家id ~= 0 then
				self.参战单位[i].必杀 = (self.参战单位[i].必杀 or 0) + 队伍忘形[self.参战单位[i].队伍]
				self.参战单位[i].法暴 = (self.参战单位[i].法暴 or 0) + 队伍忘形[self.参战单位[i].队伍]
			end

			if 队伍风行[self.参战单位[i].队伍] ~= nil and self.参战单位[i].类型 == "角色" and self.参战单位[i].玩家id ~= 0 then
				self.参战单位[i].速度 = self.参战单位[i].速度 + 队伍风行[self.参战单位[i].队伍]
			end

			if 队伍贯通[self.参战单位[i].队伍] ~= nil and self.参战单位[i].类型 == "角色" and self.参战单位[i].玩家id ~= 0 then
				self.参战单位[i].法伤增加 = (self.参战单位[i].法伤增加 or 1) + 队伍贯通[self.参战单位[i].队伍]
				self.参战单位[i].物伤增加 = (self.参战单位[i].物伤增加 or 1) + 队伍贯通[self.参战单位[i].队伍]
			end
		end
	end

	if self:取玩家战斗() == true then
		for i = 1, #self.参战单位 do
			if self.参战单位[i].类型 == "bb" then
				self.参战单位[i].伤害 = qz(self.参战单位[i].伤害 * 0.5)
				self.参战单位[i].防御 = qz(self.参战单位[i].防御 * 0.5)
				self.参战单位[i].速度 = qz(self.参战单位[i].速度 * 0.5)
				self.参战单位[i].灵力 = qz(self.参战单位[i].灵力 * 0.5)
				self.参战单位[i].法防 = qz(self.参战单位[i].法防 * 0.5)
				self.参战单位[i].法伤 = qz(self.参战单位[i].法伤 * 0.5)
			else
				self.参战单位[i].伤害 = qz(self.参战单位[i].伤害 * 0.7)
				self.参战单位[i].防御 = qz(self.参战单位[i].防御 * 0.7)
				self.参战单位[i].速度 = qz(self.参战单位[i].速度 * 0.7)
				self.参战单位[i].灵力 = qz(self.参战单位[i].灵力 * 0.7)
				self.参战单位[i].法防 = qz(self.参战单位[i].法防 * 0.7)
				self.参战单位[i].法伤 = qz(self.参战单位[i].法伤 * 0.7)
			end
		end
	end

	for n = 1, #self.参战玩家 do
		发送数据(self.参战玩家[n].连接id, 5501, {
			id = self.参战玩家[n].队伍,
			音乐 = self.战斗类型,
			总数 = #self.参战单位
		})

		for i = 1, #self.参战单位 do
			发送数据(self.参战玩家[n].连接id, 5502, self:取加载信息(i))
		end
	end

	if self.直接添加状态 ~= nil and not 判断是否为空表(self.直接添加状态) then
		for i = 1, #self.直接添加状态 do
			self:客户端添加状态1(self.直接添加状态[i][1], self.直接添加状态[i][2])
		end
	end

	self.直接添加状态 = nil

	if self.战斗脚本 and self.战斗脚本.战斗准备后 then
		__gge.safecall(self.战斗脚本.战斗准备后, self)
	end

	self:发送天气数据()
end

function 战斗处理类:添加bb法宝属性(编号, id)
	local 主人 = self.参战单位[编号].主人或助战

	if 主人 == nil then
		return
	end

	for n = 1, #self.参战单位[主人].法宝佩戴 do
		local 名称 = self.参战单位[主人].法宝佩戴[n].名称
		local 境界 = self.参战单位[主人].法宝佩戴[n].境界
		local 五行加成 = self.参战单位[主人].法宝佩戴[n].五行加成
		境界 = 境界 + 五行加成

		if 主人 ~= nil and n ~= nil then
			if 名称 == "九黎战鼓" and self:扣除法宝灵气(主人, n, 1) then
				self.参战单位[编号].伤害 = self.参战单位[编号].伤害 + qz1(境界 * 5 + 5)
			elseif 名称 == "盘龙壁" and self:扣除法宝灵气(主人, n, 1) then
				self.参战单位[编号].防御 = self.参战单位[编号].防御 + qz1(境界 * 5 + 5)
			elseif 名称 == "神行飞剑" and self:扣除法宝灵气(主人, n, 1) then
				self.参战单位[编号].速度 = self.参战单位[编号].速度 + qz1(境界 * 3 + 8)
			elseif 名称 == "汇灵盏" and self:扣除法宝灵气(主人, n, 1) then
				self.参战单位[编号].灵力 = self.参战单位[编号].灵力 + qz1(境界 * 3 + 3)
				self.参战单位[编号].法伤 = self.参战单位[编号].法伤 + qz1(境界 * 3 + 3)
				self.参战单位[编号].法防 = self.参战单位[编号].法防 + qz1(境界 * 3 + 3)
			elseif 名称 == "兽王令" and self.参战单位[主人].门派 == "狮驼岭" and self:扣除法宝灵气(主人, n, 1) then
				self.参战单位[编号].伤害 = self.参战单位[编号].伤害 + qz1(境界 * 2)
				self.参战单位[编号].防御 = self.参战单位[编号].防御 + qz1(境界 * 2)
				self.参战单位[编号].速度 = self.参战单位[编号].速度 + qz1(境界 * 2)
				self.参战单位[编号].灵力 = self.参战单位[编号].灵力 + qz1(境界 * 2)
				self.参战单位[编号].法伤 = self.参战单位[编号].法伤 + qz1(境界 * 2)
				self.参战单位[编号].法防 = self.参战单位[编号].法防 + qz1(境界 * 2)
			elseif 名称 == "重明战鼓" and self:扣除法宝灵气(主人, n, 1) then
				self.参战单位[编号].伤害 = self.参战单位[编号].伤害 + qz1(境界 * 6 + 42)
				self.参战单位[编号].法伤 = self.参战单位[编号].法伤 + qz1(境界 * 5 + 20)
			elseif 名称 == "梦云幻甲" and self:扣除法宝灵气(主人, n, 1) then
				self.参战单位[编号].伤害 = self.参战单位[编号].伤害 + qz1(境界 * 3 + 21)
				self.参战单位[编号].法伤 = self.参战单位[编号].法伤 + qz1(境界 * 2.5 + 10)
			end
		end
	end
end

function 战斗处理类:取奇经八脉是否有(编号, 名称, 流派)
	if self.参战单位[编号] ~= nil and self.参战单位[编号].奇经八脉 ~= nil and self.参战单位[编号].奇经八脉[名称] ~= nil and self.参战单位[编号].奇经八脉[名称] == 1 then
		if 流派 ~= nil then
			if type(流派) == "table" then
				if self.参战单位[编号].经脉流派 ~= nil and 流派[self.参战单位[编号].经脉流派] ~= nil then
					return true
				end
			elseif self.参战单位[编号].经脉流派 == 流派 then
				return true
			end
		else
			return true
		end
	end

	return false
end

function 战斗处理类:加载法宝(编号, id, 助战编号)
	local 角色数据 = nil

	if 助战编号 ~= nil then
		角色数据 = 玩家数据[id].助战.数据[助战编号]
	else
		角色数据 = 玩家数据[id].角色.数据
	end

	if 角色数据.法宝佩戴 == nil or 判断是否为空表(角色数据.法宝佩戴) then
		return
	end

	self.参战单位[编号].法宝佩戴 = {}

	for n = 1, 法宝最大携带数量 do
		local 符合 = false

		if 角色数据.法宝佩戴[n] ~= nil then
			local 道具id = 角色数据.法宝佩戴[n]

			if 玩家数据[id].道具.数据[道具id] ~= nil then
				local 名称 = 玩家数据[id].道具.数据[道具id].名称
				local 境界 = 玩家数据[id].道具.数据[道具id].气血
				local 灵气 = 玩家数据[id].道具.数据[道具id].魔法
				local 五行 = 玩家数据[id].道具.数据[道具id].五行
				local 特技 = 玩家数据[id].道具.数据[道具id].特技
				local 五行加成 = 0
				local 法宝类型 = 取法宝类型(名称)

				if 法宝五行加成[法宝类型] ~= nil and 法宝五行加成[法宝类型][五行] ~= nil then
					五行加成 = 法宝五行加成[法宝类型][五行]
				end

				local 临时数据 = 取物品数据(名称)
				self.参战单位[编号].法宝佩戴[#self.参战单位[编号].法宝佩戴 + 1] = {
					名称 = 名称,
					境界 = 境界,
					五行 = 五行,
					玩家id = id,
					序列 = 角色数据.法宝佩戴[n],
					五行加成 = 五行加成
				}

				if self.参战单位[编号].法宝境界 == nil then
					self.参战单位[编号].法宝境界 = {}
				end

				if self.参战单位[编号].法宝境界[名称] == nil then
					self.参战单位[编号].法宝境界[名称] = {
						境界 + 五行加成
					}
				else
					self.参战单位[编号].法宝境界[名称][#self.参战单位[编号].法宝境界[名称] + 1] = 境界 + 五行加成
				end

				if 名称 == "救命毫毛" then
					if self:取奇经八脉是否有(编号, "宝诀") then
						self.参战单位[编号].法伤增加 = (self.参战单位[编号].法伤增加 or 1) + (境界 + 五行加成) / 200
					end

					if self:取奇经八脉是否有(编号, "妙用") then
						self.参战单位[编号].法伤增加 = (self.参战单位[编号].法伤增加 or 1) + (境界 + 五行加成) / 200
					end

					if self:取奇经八脉是否有(编号, "不灭") then
						self.参战单位[编号].法伤增加 = (self.参战单位[编号].法伤增加 or 1) + (境界 + 五行加成) / 200
					end
				end

				if self.参战单位[编号].法宝列表[名称] == nil then
					self.参战单位[编号].法宝列表[名称] = {}
				end

				self.参战单位[编号].法宝列表[名称][#self.参战单位[编号].法宝列表[名称] + 1] = #self.参战单位[编号].法宝佩戴
				local 法宝序列 = #self.参战单位[编号].法宝佩戴

				if 编号 ~= nil and 法宝序列 ~= nil then
					self:加载法宝属性(编号, 法宝序列)
				end
			end
		end
	end
end

function 战斗处理类:加载奇经八脉1(编号, id, 助战编号)
	if 玩家数据[id].助战.数据[助战编号].奇经八脉 ~= nil then
		self.参战单位[编号].奇经八脉 = 玩家数据[id].助战.数据[助战编号].奇经八脉
		self.参战单位[编号].经脉流派 = 玩家数据[id].助战.数据[助战编号].奇经八脉.经脉流派
	end
end

function 战斗处理类:法宝判断(法宝名称, 编号)
	if self.参战单位[编号].法术状态.番天印 ~= nil or self.参战单位[编号].法术状态.娉婷袅娜 ~= nil then
		return false
	end

	if self.参战单位[编号] ~= nil and self.参战单位[编号].法宝列表 == nil then
		self.参战单位[编号].法宝列表 = {}
	end

	if self.参战单位[编号] ~= nil and self.参战单位[编号].法宝列表[法宝名称] ~= nil and not 判断是否为空表(self.参战单位[编号].法宝列表[法宝名称]) then
		return #self.参战单位[编号].法宝列表[法宝名称]
	end

	return false
end

function 战斗处理类:法宝概率判断(法宝名称, 编号, 法宝位置, 数额, 扣除, 判断概率, 自定义几率公式)
	if 判断概率 == nil then
		判断概率 = 100
	end

	local 境界 = self:取指定法宝境界(编号, 法宝名称, 法宝位置)

	if 境界 == false then
		return false
	end

	local 自定义几率 = nil
	self.五行加成 = self.参战单位[编号].法宝佩戴[法宝位置].五行加成
	local 概率 = qz1(取随机数(1, 判断概率 * 100) / 100)
	local 额外 = 0

	if self.五行加成 ~= nil and self.五行加成 ~= 0 then
		概率 = 概率 - self.五行加成
		境界 = 境界 + self.五行加成
	end

	if 法宝名称 == "嗜血幡" then
		if 概率 > 境界 * 2 + 5 then
			return false
		end
	elseif 法宝名称 == "救命毫毛" then
		local jc = 0

		if self:取奇经八脉是否有(编号, "宝诀") and self.回合数 <= 8 then
			jc = jc + 境界 * 2 * (0.8 - (self.回合数 - 1) * 0.1)
		end

		if self:取奇经八脉是否有(编号, "妙用") then
			jc = jc + 境界 * 2 * 0.15
		end

		if self:取奇经八脉是否有(编号, "不倦") then
			jc = jc + 境界 * 2 * 0.15
		end

		if self:取奇经八脉是否有(编号, "精炼") and self.回合数 <= 8 then
			jc = jc + 境界 * 2 * (0.8 - (self.回合数 - 1) * 0.1)
		end

		if 概率 > 境界 * 2 + jc then
			return false
		end
	elseif 法宝名称 == "降魔斗篷" then
		if 概率 > 境界 * 1 + 8 then
			return false
		end
	elseif 法宝名称 == "蟠龙玉璧" then
		if 概率 > 境界 * 1 + 7 then
			return false
		end
	elseif 法宝名称 == "澄空净铃" then
		if 概率 > 境界 * 1.1 + 8.2 then
			return false
		end
	elseif 法宝名称 == "金甲仙衣" then
		if 概率 > 境界 * 1 + 4 then
			return false
		end
	elseif 法宝名称 == "普渡" then
		if self:取奇经八脉是否有(编号, "普渡") then
			额外 = 额外 + 20
		end

		if self:取奇经八脉是否有(编号, "度厄") then
			额外 = 额外 - 10
		end

		if 概率 > 境界 * 3 + 5 + 额外 then
			return false
		end
	elseif 法宝名称 == "分水" and 概率 > 境界 * 1 + 8 then
		return false
	end

	if self:取指定法宝(编号, 法宝名称, 法宝位置, 数额, 扣除) == true then
		return 境界
	end

	return false
end

function 战斗处理类:取指定法宝境界(编号, 法宝, 法宝位置)
	if self.参战单位[编号].类型 ~= "角色" then
		return false
	end

	if self.参战单位[编号].法宝佩戴[法宝位置] ~= nil and self.参战单位[编号].法宝佩戴[法宝位置].名称 == 法宝 then
		return self.参战单位[编号].法宝佩戴[法宝位置].境界
	end

	return false
end

function 战斗处理类:取指定法宝(编号, 法宝, 法宝位置, 数额, 扣除)
	if self.参战单位[编号] == nil or self.参战单位[编号].类型 ~= "角色" then
		return false
	end

	local id = self.参战单位[编号].玩家id

	if self.参战单位[编号].法宝佩戴[法宝位置] ~= nil and self.参战单位[编号].法宝佩戴[法宝位置].名称 == 法宝 then
		if 扣除 ~= nil then
			return true
		else
			local 扣除id = self.参战单位[编号].法宝佩戴[法宝位置].序列

			if 玩家数据[id].道具.数据[扣除id] == nil then
				return false
			elseif 玩家数据[id].道具.数据[扣除id].魔法 < 数额 then
				return false
			elseif self.参战单位[编号].法宝已扣 ~= nil and self.参战单位[编号].法宝已扣[法宝] ~= nil then
				return true
			else
				玩家数据[id].道具.数据[扣除id].魔法 = 玩家数据[id].道具.数据[扣除id].魔法 - 数额

				if 玩家数据[id].角色.数据.战斗提示 ~= false then
					local js = "你"

					if self.参战单位[编号].助战编号 ~= nil then
						js = "#P(助战)#Y" .. self.参战单位[编号].名称 .. "#W"
					end

					发送数据(玩家数据[id].连接id, 38, {
						内容 = js .. "的法宝[#R" .. 玩家数据[id].道具.数据[扣除id].名称 .. "#W]灵气减少了#Y" .. 数额 .. "#W点"
					})
				end

				if self.参战单位[编号].法宝已扣 == nil then
					self.参战单位[编号].法宝已扣 = {}
				end

				self.参战单位[编号].法宝已扣[法宝] = true

				return true
			end
		end
	end

	return false
end

function 战斗处理类:扣除法宝灵气(编号, 序列, 数额, 类型)
	local 扣除id = self.参战单位[编号].法宝佩戴[序列].序列
	local id = self.参战单位[编号].玩家id

	if 类型 == nil then
		if self.战斗类型 == 100001 or self.战斗类型 == 100005 or self.战斗类型 == 100007 or self.战斗类型 == 100221 or self.战斗类型 == 100225 then
			return true
		end

		if 玩家数据[id].道具.数据[扣除id].魔法 < 数额 then
			return false
		else
			玩家数据[id].道具.数据[扣除id].魔法 = 玩家数据[id].道具.数据[扣除id].魔法 - 数额
			local js = "你"

			if self.参战单位[编号].助战编号 ~= nil then
				js = "#P(助战)#Y" .. self.参战单位[编号].名称 .. "#W"
			end

			if not 判断是否为空表(self.战斗流程) then
				self:添加战斗流程提示(js .. "的法宝[#R" .. 玩家数据[id].道具.数据[扣除id].名称 .. "#W]灵气减少了#Y" .. 数额 .. "#W点")
			elseif 玩家数据[id].角色.数据.战斗提示 ~= false then
				发送数据(玩家数据[id].连接id, 38, {
					内容 = js .. "的法宝[#R" .. 玩家数据[id].道具.数据[扣除id].名称 .. "#W]灵气减少了#Y" .. 数额 .. "#W点"
				})
			end

			return true
		end
	elseif 玩家数据[id].道具.数据[扣除id].魔法 < 取灵气上限(玩家数据[id].道具.数据[扣除id].分类) then
		玩家数据[id].道具.数据[扣除id].魔法 = 玩家数据[id].道具.数据[扣除id].魔法 + 数额

		if 玩家数据[id].角色.数据.战斗提示 ~= false then
			发送数据(玩家数据[id].连接id, 38, {
				内容 = "你的法宝[#R" .. 玩家数据[id].道具.数据[扣除id].名称 .. "#W]灵气增加了#Y" .. 数额 .. "#W点"
			})
		end
	elseif 玩家数据[id].角色.数据.战斗提示 ~= false then
		发送数据(玩家数据[id].连接id, 38, {
			内容 = "你的法宝[#R" .. 玩家数据[id].道具.数据[扣除id].名称 .. "#W]灵气已经满了，无法再获得灵气"
		})
	end
end

function 战斗处理类:加载奇经八脉(编号, id)
	if 玩家数据[id].角色.数据.奇经八脉 ~= nil then
		self.参战单位[编号].奇经八脉 = 玩家数据[id].角色.数据.奇经八脉
		self.参战单位[编号].经脉流派 = 玩家数据[id].角色.数据.奇经八脉.经脉流派
	end
end

