			self.参战单位[编号].待加属性 = self.参战单位[编号].待加属性 or {}
			self.参战单位[编号].待加属性.伤害 = (self.参战单位[编号].待加属性.伤害 or 0) + 境界 * 3 + 21
		end
	elseif 名称 == "血魄元幡" and self:扣除法宝灵气(编号, 法宝序列, 1) then
		self:给全部队友加属性(编号, "法伤", "角色", 境界 * 1.5 + 13)

		if 队伍数据[玩家数据[self.参战单位[编号].玩家id].队伍] ~= nil and 队伍数据[玩家数据[self.参战单位[编号].玩家id].队伍].成员数据[5] ~= nil and self:与全部队友比较属性(编号, "法伤", "角色", 1) then
			self.参战单位[编号].待加属性 = self.参战单位[编号].待加属性 or {}
			self.参战单位[编号].待加属性.法伤 = (self.参战单位[编号].待加属性.法伤 or 0) + 境界 * 2.5 + 15
		end
	elseif 名称 == "翠碧玉箫" and self:扣除法宝灵气(编号, 法宝序列, 1) then
		if 队伍数据[玩家数据[self.参战单位[编号].玩家id].队伍] ~= nil and 队伍数据[玩家数据[self.参战单位[编号].玩家id].队伍].成员数据[5] ~= nil and self:与全部队友比较属性(编号, "速度", "角色", 1) then
			self:给全部队友加属性(编号, "封印抵抗率", "角色", 境界 * 0.5 + 3)
		else
			self:给全部队友加属性(编号, "封印抵抗率", "角色", 境界 * 0.25 + 1.5)
		end
	elseif 名称 == "冷龙石磐" and self:扣除法宝灵气(编号, 法宝序列, 1) then
		if 队伍数据[玩家数据[self.参战单位[编号].玩家id].队伍] ~= nil and 队伍数据[玩家数据[self.参战单位[编号].玩家id].队伍].成员数据[5] ~= nil and self:与全部队友比较属性(编号, "防御", "角色", 1) then
			self:给全部队友加属性(编号, "防御", "角色", 境界 * 1.5 + 13)
		else
			self:给全部队友加属性(编号, "防御", "角色", 境界 * 1 + 8)
		end
	elseif 名称 == "琉璃云罩" and self:扣除法宝灵气(编号, 法宝序列, 1) then
		if 队伍数据[玩家数据[self.参战单位[编号].玩家id].队伍].成员数据[5] ~= nil and self:与全部队友比较属性(编号, "法防", "角色", 1) then
			self:给全部队友加属性(编号, "法防", "角色", 境界 * 1.5 + 13)
		else
			self:给全部队友加属性(编号, "法防", "角色", 境界 * 1 + 8)
		end
	end
end

function 战斗处理类:给全部队友加属性(编号, 属性, 类型, 数值)
	local 目标组 = self:取全体敌友方目标(编号, nil, nil, 类型)

	if 目标组 == 0 or 判断是否为空表(目标组) then
		return true
	end

	for i = 1, #目标组 do
		self.参战单位[目标组[i]][属性] = (self.参战单位[目标组[i]][属性] or 0) + (数值 or 0)
	end
end

function 战斗处理类:与全部队友比较属性(编号, 属性, 类型, 比较值倍率)
	local 目标组 = self:取全体敌友方目标(编号, nil, 1, 类型)

	if 目标组 == 0 or 判断是否为空表(目标组) then
		return true
	end

	for i = 1, #目标组 do
		if (self.参战单位[目标组[i]][属性] or 0) + (比较值 or 1) > (self.参战单位[编号][属性] or 0) then
			return false
		end
	end

	return true
end

function 战斗处理类:取装备宝石(角色数据, 编号)
	if 编号 == nil or self.参战单位[编号] == nil then
		return
	end

	if self.参战单位[编号].装备宝石 == nil then
		self.参战单位[编号].装备宝石 = {}

		for i, v in pairs(角色数据.装备) do
			if v ~= nil and 玩家数据[self.参战单位[编号].玩家id].道具.数据[v] ~= nil and 玩家数据[self.参战单位[编号].玩家id].道具.数据[v].镶嵌类型 ~= nil then
				for n = 1, #玩家数据[self.参战单位[编号].玩家id].道具.数据[v].镶嵌类型 do
					self.参战单位[编号].装备宝石[玩家数据[self.参战单位[编号].玩家id].道具.数据[v].镶嵌类型[n]] = (self.参战单位[编号].装备宝石[玩家数据[self.参战单位[编号].玩家id].道具.数据[v].镶嵌类型[n]] or 0) +
					1
				end
			end
		end
	end
end

function 战斗处理类:宝石效果提高(角色数据, 编号, 提高效果)
	self:取装备宝石(角色数据, 编号)

	for i, v in pairs(提高效果) do
		if self.参战单位[编号].装备宝石[i] ~= nil then
			local 加成属性 = 宝石列表1[i]

			for k, w in pairs(加成属性) do
				self.参战单位[编号][k] = qz1(self.参战单位[编号][k] + w * v / 100 * self.参战单位[编号].装备宝石[i])
			end
		end
	end
end

function 战斗处理类:添加师门技能(角色数据, 编号, 是否助战)
	local 临时套装 = {}

	if self:取奇经八脉是否有(编号, "月光") or self:取奇经八脉是否有(编号, "狂月") or self:取奇经八脉是否有(编号, "铁骨") then
		self:宝石效果提高(角色数据, 编号, {
			月亮石 = 40
		})
	elseif self:取奇经八脉是否有(编号, "灵光") then
		self:宝石效果提高(角色数据, 编号, {
			舍利子 = 25
		})
	elseif self:取奇经八脉是否有(编号, "纯净") then
		self:宝石效果提高(角色数据, 编号, {
			光芒石 = 70
		})
	elseif self:取奇经八脉是否有(编号, "舍利", "无量尊者") then
		self:取装备宝石(角色数据, 编号)

		if self.参战单位[编号].装备宝石.舍利子 ~= nil then
			self.参战单位[编号].无量尊者舍利 = self.参战单位[编号].装备宝石.舍利子 * 4
		end
	end

	for i, v in pairs(角色数据.装备) do
		if v ~= nil and 玩家数据[self.参战单位[编号].玩家id].道具.数据[v] ~= nil then
			if i == 3 then
				if 玩家数据[self.参战单位[编号].玩家id].道具.数据[v].五行 == nil then
					玩家数据[self.参战单位[编号].玩家id].道具.数据[v].五行 = 取五行()
				end

				self.参战单位[编号].攻击五行 = 玩家数据[self.参战单位[编号].玩家id].道具.数据[v].五行

				if self.参战单位[编号].攻击五行 == "水" then
					if self:取奇经八脉是否有(编号, "龙慑") then
						self.参战单位[编号].龙慑 = (self.参战单位[编号].龙慑 or 0) + 1
					end

					if self:取奇经八脉是否有(编号, "水漾") then
						self.参战单位[编号].水漾 = (self.参战单位[编号].水漾 or 1) + 0.04
					end

					if self:取奇经八脉是否有(编号, "惊涛") then
						self.参战单位[编号].惊涛 = (self.参战单位[编号].惊涛 or 0) + 4
					end
				elseif self.参战单位[编号].攻击五行 == "土" then
					if self:取奇经八脉是否有(编号, "焦土") then
						self.参战单位[编号].焦土 = (self.参战单位[编号].焦土 or 0) + 1
					end

					if self:取奇经八脉是否有(编号, "填海") then
						self.参战单位[编号].填海 = (self.参战单位[编号].填海 or 0) + 5
					end
				elseif self.参战单位[编号].攻击五行 == "火" then
					if self:取奇经八脉是否有(编号, "焰星") then
						self.参战单位[编号].焰星 = (self.参战单位[编号].焰星 or 0) + 1
					end

					if self:取奇经八脉是否有(编号, "薪火") then
						self.参战单位[编号].薪火 = (self.参战单位[编号].薪火 or 0) + 2
					end

					if self:取奇经八脉是否有(编号, "焚尽") then
						self.参战单位[编号].法暴 = (self.参战单位[编号].法暴 or 基础法暴率) + 4
					end
				elseif self.参战单位[编号].攻击五行 == "木" then
					if self:取奇经八脉是否有(编号, "神木") then
						self.参战单位[编号].法伤增加 = (self.参战单位[编号].法伤增加 or 1) + 0.04
					end
				elseif self.参战单位[编号].攻击五行 == "金" then
					if self:取奇经八脉是否有(编号, "钢牙") then
						self.参战单位[编号].钢牙 = (self.参战单位[编号].钢牙 or 0) + 1
					end

