				end
			end

			local 特效判断 = {}

			if 玩家数据[self.参战单位[编号].玩家id].道具.数据[v].特效 ~= nil then
				特效判断 = 列表模式转换(玩家数据[self.参战单位[编号].玩家id].道具.数据[v].特效)
