					elseif 新特效列表[i] == "法术穿透" then
						self.参战单位[编号].法穿 = math.min((self.参战单位[编号].法穿 or 0) + 通用新特效1[新特效列表[i]],
							通用新特效1[新特效列表[i]] * 新特效叠加[新特效列表[i]])
					end
				end
			end

			local 临时人物装备 = 玩家数据[self.参战单位[编号].玩家id].道具.数据[v]

			if 临时人物装备.套装效果 ~= nil then
				if 判断是否为空表(临时套装) then
					临时套装[#临时套装 + 1] = {
						临时人物装备.套装效果[1],
						临时人物装备.套装效果[2],
						数量 = 1
					}
				else
					local 新套装效果 = true

					for i = 1, #临时套装 do
						if 临时套装[i][2] == 临时人物装备.套装效果[2] then
							临时套装[i].数量 = 临时套装[i].数量 + 1
							新套装效果 = false
						end
					end

					if 新套装效果 then
						临时套装[#临时套装 + 1] = {
							临时人物装备.套装效果[1],
							临时人物装备.套装效果[2],
							数量 = 1
						}
					end
				end
			end
		end

		if v ~= nil and 玩家数据[self.参战单位[编号].玩家id].道具.数据[v] ~= nil and 玩家数据[self.参战单位[编号].玩家id].道具.数据[v].临时附魔 ~= nil then
			if 是否助战 ~= nil then
				玩家数据[self.参战单位[编号].玩家id].助战:附魔装备刷新(self.参战单位[编号].助战编号, v)
			else
				玩家数据[self.参战单位[编号].玩家id].角色:附魔装备刷新(self.参战单位[编号].玩家id, v)
			end

			if i + 0 == 5 and 玩家数据[self.参战单位[编号].玩家id].道具.数据[v].临时附魔.愤怒 ~= nil and 玩家数据[self.参战单位[编号].玩家id].道具.数据[v].临时附魔.愤怒.数值 > 0 then
				self:增加愤怒(编号, 玩家数据[self.参战单位[编号].玩家id].道具.数据[v].临时附魔.愤怒.数值)
			elseif i + 0 == 2 and 玩家数据[self.参战单位[编号].玩家id].道具.数据[v].临时附魔.法防 ~= nil and 玩家数据[self.参战单位[编号].玩家id].道具.数据[v].临时附魔.法防.数值 > 0 then
				self.参战单位[编号].法防 = self.参战单位[编号].法防 + 玩家数据[self.参战单位[编号].玩家id].道具.数据[v].临时附魔.法防.数值
			elseif i + 0 == 2 and 玩家数据[self.参战单位[编号].玩家id].道具.数据[v].临时附魔.灵力 ~= nil and 玩家数据[self.参战单位[编号].玩家id].道具.数据[v].临时附魔.灵力.数值 > 0 then
				self.参战单位[编号].灵力 = self.参战单位[编号].灵力 + 玩家数据[self.参战单位[编号].玩家id].道具.数据[v].临时附魔.灵力.数值
				self.参战单位[编号].法伤 = self.参战单位[编号].法伤 + 玩家数据[self.参战单位[编号].玩家id].道具.数据[v].临时附魔.灵力.数值
				self.参战单位[编号].法防 = self.参战单位[编号].法防 + 玩家数据[self.参战单位[编号].玩家id].道具.数据[v].临时附魔.灵力.数值
			end
		end
	end

	if not 判断是否为空表(临时套装) then
		for i = 1, #临时套装 do
			if 临时套装[i][1] == "追加法术" then
				if self.参战单位[编号].所有追加法术 == nil then
					self.参战单位[编号].所有追加法术 = {}
				end

				self.参战单位[编号].所有追加法术[#self.参战单位[编号].所有追加法术 + 1] = {
					名称 = 临时套装[i][2],
					等级 = self.参战单位[编号].等级,
					数量 = 临时套装[i].数量 or 1
				}
			end

			if 角色套装a <= 临时套装[i].数量 then
				local 等级 = self.参战单位[编号].等级

				if 角色套装b <= 临时套装[i].数量 then
					等级 = 等级 + 10
				end

				if 临时套装[i][1] ~= "变身术之" then
					self.参战单位[编号][临时套装[i][1]][#self.参战单位[编号][临时套装[i][1]] + 1] = {
						名称 = 临时套装[i][2],
						等级 = 等级,
						数量 = 临时套装[i].数量 or 角色套装a
					}
				end
			end
		end

		if self:取奇经八脉是否有(编号, "烈光") and #self.参战单位[编号].所有追加法术 > 0 then
			self.参战单位[编号].烈光 = 1 + #self.参战单位[编号].所有追加法术 * 0.015
		end
	end

	if 角色数据.等级 < 19 then
		self:添加主动技能(self.参战单位[编号], "牛刀小试", 角色数据.等级 + 10)
	end

	if 角色数据.技能 ~= nil then
		for i = 1, #角色数据.技能 do
			local 名称 = 角色数据.技能[i].名称
			local 等级 = 角色数据.技能[i].等级

			if 等级 == 0 then
				等级 = 1
			end

			if self.参战单位[编号].替换技能 ~= nil and self.参战单位[编号].替换技能[名称] ~= nil then
			elseif self:恢复技能(名称) or self:法攻技能(名称) or self:物攻技能(名称) or self:封印技能(名称) or self:群体封印技能(名称) or self:减益技能(名称) or self:增益技能(名称) then
				self:添加主动技能(self.参战单位[编号], 名称, 等级)
			else
				if self.参战单位[编号].被动技能 == nil then
					self.参战单位[编号].被动技能 = {}
				end

				self.参战单位[编号].被动技能[名称] = 等级

				if 名称 == "黎魂" then
					self.参战单位[编号].黎魂 = 2

					if 取随机数(1, 1000) <= (九黎城三次概率 + (self.参战单位[编号].黎魂加成 or 0)) * 10 then
						self.参战单位[编号].黎魂 = self.参战单位[编号].黎魂 + 1
					end
				elseif 名称 == "战鼓" then
					self.参战单位[编号].战鼓 = 1
				elseif 名称 == "如意神通" then
					self:取神通技能(编号)
				end
			end
		end
	end
end

function 战斗处理类:添加bb套装效果(bb数据, 编号)
	local n = 编号 + 0
	local 套装判断 = {
		追加 = {},
		附加 = {}
	}
	local 追加列表 = {}
	local 数量列表 = {}
	local 附加列表 = {}

	for j = 1, 3 do
		if bb数据.装备[j] ~= nil and bb数据.装备[j].套装效果 ~= nil then
			local 套装效果 = bb数据.装备[j].套装效果

			if 套装效果[1] == "追加法术" then
				套装判断.追加[套装效果[2]] = (套装判断.追加[套装效果[2]] or 0) + 1
			elseif 套装效果[1] == "附加状态" then
				套装判断.附加[套装效果[2]] = (套装判断.附加[套装效果[2]] or 0) + 1
			end
		end
	end

	for k, v in pairs(套装判断.附加) do
		if bb套装生效件数 <= v then
			附加列表[#附加列表 + 1] = k
		end
	end

	for k, v in pairs(套装判断.追加) do
		if bb套装生效件数 <= v then
			追加列表[#追加列表 + 1] = k
			数量列表[#数量列表 + 1] = v
		end
	end

	if #附加列表 > 0 then
		self:添加技能属性(self.参战单位[n], 附加列表)
	end

	if #追加列表 > 0 then
		for i = 1, #追加列表 do
			self.参战单位[n].追加法术[#self.参战单位[n].追加法术 + 1] = {
				召唤兽 = 1,
				名称 = 追加列表[i],
				等级 = self.参战单位[n].等级,
				数量 = 数量列表[i]
			}
		end

		if 追加法术是否添加主动技能 then
			self:添加技能属性(self.参战单位[n], 追加列表)
		end
	end
end

function 战斗处理类:删除主动技能(单位数据, 技能名称组)
	if type(技能名称组) ~= "table" or 判断是否为空表(技能名称组) then
		return
	end

	local 删除 = {}

	for i = 1, #单位数据.主动技能 do
		if 技能名称组[单位数据.主动技能[i].名称] ~= nil then
			删除[#删除 + 1] = i + 0
		end
	end

	无错误删除列表多个元素(单位数据.主动技能, 删除)
end

function 战斗处理类:添加主动技能(单位数据, 技能名称, 等级)
	if 单位数据 ~= nil and 技能名称 ~= nil then
		if 技能前置冷却[技能名称] ~= nil then
			单位数据[技能名称] = 技能前置冷却[技能名称] + 0

			if 技能名称 == "秘传飞砂走石" or 技能名称 == "秘传三昧真火" and self:取奇经八脉是否有(单位数据.战斗编号, "烈火真言") then
				单位数据[技能名称] = 技能前置冷却[技能名称] + 1
			end
		end

		单位数据.主动技能[#单位数据.主动技能 + 1] = {
			名称 = 技能名称,
			等级 = 等级 or 1
		}
		单位数据.主动技能1[技能名称] = 等级 or 1
	end
end

function 战斗处理类:添加角色变身卡数据(n, 角色数据)
	self.参战单位[n].变身数据 = 角色数据.变身数据
	self.参战单位[n].变身卡技能 = 角色数据.变身卡技能

	if self.参战单位[n].变身数据 ~= nil and 变身卡数据[self.参战单位[n].变身数据] ~= nil and (self.参战单位[n].变身卡技能 ~= nil or 变身卡数据[self.参战单位[n].变身数据].技能 ~= "") then
		self:添加技能属性(self.参战单位[n], {
			self.参战单位[n].变身卡技能 or 变身卡数据[self.参战单位[n].变身数据].技能
		})
	end
end

function 战斗处理类:添加BB技能属性(n)
	if self.参战单位[n] == nil then
		return
	end

	if self.参战单位[n].法术认证 ~= nil then
		self:添加认证法术属性(self.参战单位[n], self.参战单位[n].法术认证)
	end

	if self.参战单位[n].护符附带技能 ~= nil and #self.参战单位[n].护符附带技能 > 0 then
		self:添加护符技能属性(self.参战单位[n], self.参战单位[n].护符附带技能)
	end

	if self.参战单位[n].门派法术 ~= nil and #self.参战单位[n].门派法术 > 0 then
		self:添加护符技能属性(self.参战单位[n], self.参战单位[n].门派法术)
	end

	if self.参战单位[n].玩家id ~= 0 and self.参战单位[n - 1] ~= nil and self.参战单位[n - 1].特效指挥 ~= nil then
		self:添加状态("指挥", self.参战单位[n], self.参战单位[n], self.参战单位[n].等级, n)
	end

	if 玩家数据[self.参战单位[n].玩家id] ~= nil then
		for i = 1, #玩家数据[self.参战单位[n].玩家id].召唤兽.数据 do
			if 玩家数据[self.参战单位[n].玩家id].召唤兽.数据[i].认证码 ~= nil and self.参战单位[n].认证码 ~= nil and 玩家数据[self.参战单位[n].玩家id].召唤兽.数据[i].认证码 == self.参战单位[n].认证码 then
				self:添加bb套装效果(玩家数据[self.参战单位[n].玩家id].召唤兽.数据[i], n)
			end
		end
	end

	if self.参战单位[n].统御 ~= nil and self.参战单位[n].预置bb == nil then
		local 坐骑编号 = self.参战单位[n].统御
		local 玩家id = self.参战单位[n].玩家id

		if 玩家数据[玩家id].角色.数据.坐骑列表[坐骑编号] ~= nil then
			local 通过 = false

			if 玩家数据[玩家id].角色.数据.坐骑列表[坐骑编号].忠诚 <= 50 and 玩家数据[玩家id].角色.数据.坐骑列表[坐骑编号].忠诚 > 2 then
				玩家数据[玩家id].角色.数据.坐骑列表[坐骑编号].忠诚 = 玩家数据[玩家id].角色.数据.坐骑列表[坐骑编号].忠诚 - 2

				发送数据(玩家数据[玩家id].连接id, 38, {
					内容 = "你的坐骑#R" .. 玩家数据[玩家id].角色.数据.坐骑列表[坐骑编号].名称 .. "#W减少了2点饱食度"
				})

				通过 = true
			elseif 玩家数据[玩家id].角色.数据.坐骑列表[坐骑编号].忠诚 > 50 then
				玩家数据[玩家id].角色.数据.坐骑列表[坐骑编号].忠诚 = 玩家数据[玩家id].角色.数据.坐骑列表[坐骑编号].忠诚 - 1

				发送数据(玩家数据[玩家id].连接id, 38, {
					内容 = "你的坐骑#R" .. 玩家数据[玩家id].角色.数据.坐骑列表[坐骑编号].名称 .. "#W减少了1点饱食度"
				})

				通过 = true
			end

			if 通过 == false then
				玩家数据[玩家id].角色:坐骑刷新(坐骑编号)
				发送数据(玩家数据[玩家id].连接id, 38, {
					内容 = "你的坐骑#R" .. 玩家数据[玩家id].角色.数据.坐骑列表[坐骑编号].名称 .. "#W已经饥饿难耐无法给予统御召唤兽加成了"
				})
			else
				local 坐骑技能列表 = 玩家数据[玩家id].角色.数据.坐骑列表[坐骑编号].技能 or {}
				local 坐骑技能等级 = 玩家数据[玩家id].角色.数据.坐骑列表[坐骑编号].技能等级 or {}
				local 坐骑技能列表1 = {}

				for i = 1, #坐骑技能列表 do
					if 坐骑技能等级[i] == nil or 坐骑技能等级[i] == 3 or 坐骑技能等级[i] == 0 then
						坐骑技能列表1[#坐骑技能列表1 + 1] = 坐骑技能列表[i]
					end
				end

				self:添加技能属性(self.参战单位[n], 坐骑技能列表1)
			end
		end
	end

	self:添加技能属性(self.参战单位[n], self.参战单位[n].技能, "正式添加")

	if self.参战单位[n].队伍 ~= 0 then
		self.参战单位[n].攻击修炼 = 玩家数据[self.参战单位[n].玩家id].角色.数据.bb修炼.攻击控制力[1]
		self.参战单位[n].法术修炼 = 玩家数据[self.参战单位[n].玩家id].角色.数据.bb修炼.法术控制力[1]
		self.参战单位[n].防御修炼 = 玩家数据[self.参战单位[n].玩家id].角色.数据.bb修炼.防御控制力[1]
		self.参战单位[n].抗法修炼 = 玩家数据[self.参战单位[n].玩家id].角色.数据.bb修炼.抗法控制力[1]
	end

	self:添加bb法宝属性(n, self.参战单位[n].玩家id)

	if self.参战单位[n].特性 ~= nil and self.参战单位[n].特性 == "御风" then
		self:添加状态特性(n)
	end

	if self.参战单位[n].内丹 ~= nil then
		self:添加内丹属性(self.参战单位[n], self.参战单位[n].内丹)
	end
end

function 战斗处理类:重置单位属性()
	self.战斗流程 = {}

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 == 0 or self.参战单位[n].类型 == "系统角色" then
			self.参战单位[n].战意 = 999
		else
			self.参战单位[n].战意 = 0
		end

		if self.同门派减伤[self.参战单位[n].队伍] == nil then
			self.同门派减伤[self.参战单位[n].队伍] = {}
		end

		self.参战单位[n].法暴 = 1
		self.参战单位[n].必杀 = 基础暴击率 + 0
		self.参战单位[n].奋勇当先 = 0
		self.参战单位[n].物理暴伤 = 2
		self.参战单位[n].法术暴伤 = 2
		self.参战单位[n].治疗暴伤 = 1.5
		self.参战单位[n].溅射 = 0
		self.参战单位[n].溅射人数 = 0
		self.参战单位[n].驱怪 = 0
		self.参战单位[n].高山流水 = 0
		self.参战单位[n].百无禁忌 = 0
		self.参战单位[n].天降大任 = 0
		self.参战单位[n].飞檐走壁 = 0
		self.参战单位[n].慈悲效果 = 0
		self.参战单位[n].攻击修炼 = 0
		self.参战单位[n].法术修炼 = 0
		self.参战单位[n].防御修炼 = 0
		self.参战单位[n].抗法修炼 = 0
		self.参战单位[n].猎术修炼 = 0
		self.参战单位[n].怒击效果 = false
		self.参战单位[n].毫毛次数 = 0
		self.参战单位[n].攻击五行 = self.参战单位[n].攻击五行 or self.参战单位[n].五行 or 取五行()
		self.参战单位[n].防御五行 = self.参战单位[n].防御五行 or self.参战单位[n].五行 or 取五行()
		self.参战单位[n].修炼数据 = {
			猎术 = 0,
			抗法 = 0,
			攻击 = 0,
			法修 = 0
		}

		if self.参战单位[n].怪物修炼 ~= nil then
			self.参战单位[n].攻击修炼 = self.参战单位[n].怪物修炼.攻击修炼 or 0
			self.参战单位[n].法术修炼 = self.参战单位[n].怪物修炼.法术修炼 or 0
			self.参战单位[n].防御修炼 = self.参战单位[n].怪物修炼.防御修炼 or 0
			self.参战单位[n].抗法修炼 = self.参战单位[n].怪物修炼.抗法修炼 or 0
		end

		if self.参战单位[n].命中 == nil then
			self.参战单位[n].命中 = self.参战单位[n].伤害
		end

		if self.参战单位[n].法术伤害结果 == nil then
			self.参战单位[n].法术伤害结果 = 0
		end

		self:加载单位通用属性(n + 0, 4)

		self.参战单位[n].气血 = math.max(self.参战单位[n].气血 or 0, 1)

		if self.参战单位[n].队伍 ~= 0 and self.参战单位[n].系统队友 == nil then
			if self.参战单位[n].类型 == "角色" and self.参战单位[n].助战编号 == nil then
				self.参战单位[n].攻击修炼 = 玩家数据[self.参战单位[n].玩家id].角色.数据.修炼.攻击修炼[1]
				self.参战单位[n].法术修炼 = 玩家数据[self.参战单位[n].玩家id].角色.数据.修炼.法术修炼[1]
				self.参战单位[n].防御修炼 = 玩家数据[self.参战单位[n].玩家id].角色.数据.修炼.防御修炼[1]
				self.参战单位[n].抗法修炼 = 玩家数据[self.参战单位[n].玩家id].角色.数据.修炼.抗法修炼[1]
				self.参战单位[n].猎术修炼 = 玩家数据[self.参战单位[n].玩家id].角色.数据.修炼.猎术修炼[1]

				if self.参战单位[n].通真达灵 ~= nil then
					self.参战单位[n].法防 = self.参战单位[n].法防 * (1 + self.参战单位[n].通真达灵 / 100)
				end

				local 特技 = 玩家数据[self.参战单位[n].玩家id].角色:取特技()

				for i = 1, #特技 do
					self.参战单位[n].特技技能[i] = {
						等级 = 0,
						名称 = 特技[i]
					}
				end

				if self:取符石组合效果(n, "无心插柳") then
					self.参战单位[n].溅射 = (self.参战单位[n].溅射 or 0) + self:取符石组合效果(n, "无心插柳")
					local 溅射基数 = 0
					if self:取无心插柳词条个数(n) then
						溅射基数 = self:取无心插柳词条个数(n)
					end
					self.参战单位[n].溅射人数 = self.参战单位[n].溅射人数 + 2*溅射基数
					self.参战单位[n].无心插柳 = 1
				end

				for i = 1, #灵饰战斗属性 do
					self.参战单位[n][灵饰战斗属性[i]] = 玩家数据[self.参战单位[n].玩家id].角色.数据[灵饰战斗属性[i]]
				end

				self:加载奇经八脉(n, self.参战单位[n].玩家id)
				self:加载法宝(n, self.参战单位[n].玩家id)

				for i = 1, #玩家数据[self.参战单位[n].玩家id].角色.数据.剧情技能 do
					if 玩家数据[self.参战单位[n].玩家id].角色.数据.剧情技能[i].名称 == "妙手空空" and (self.战斗类型 ~= 100001 or self.战斗类型 ~= 100007) then
						self:添加主动技能(self.参战单位[n], 玩家数据[self.参战单位[n].玩家id].角色.数据.剧情技能[i].名称,
							玩家数据[self.参战单位[n].玩家id].角色.数据.剧情技能[i].等级)
					end
				end

				self:添加师门技能(玩家数据[self.参战单位[n].玩家id].角色.数据, n)
				self:添加角色变身卡数据(n, 玩家数据[self.参战单位[n].玩家id].角色.数据)
				self:添加技能属性(self.参战单位[n], self.参战单位[n].技能, "正式添加")
				self:经脉属性处理(n)
			elseif self.参战单位[n].类型 == "角色" and self.参战单位[n].助战编号 ~= nil then
				self.参战单位[n].攻击修炼 = 玩家数据[self.参战单位[n].玩家id].助战.数据[self.参战单位[n].助战编号].修炼.攻击修炼
				self.参战单位[n].法术修炼 = 玩家数据[self.参战单位[n].玩家id].助战.数据[self.参战单位[n].助战编号].修炼.法术修炼
				self.参战单位[n].防御修炼 = 玩家数据[self.参战单位[n].玩家id].助战.数据[self.参战单位[n].助战编号].修炼.防御修炼
				self.参战单位[n].抗法修炼 = 玩家数据[self.参战单位[n].玩家id].助战.数据[self.参战单位[n].助战编号].修炼.抗法修炼
				self.参战单位[n].猎术修炼 = 0

				self:加载奇经八脉1(n, self.参战单位[n].玩家id, self.参战单位[n].助战编号)
				self:加载法宝(n, self.参战单位[n].玩家id, self.参战单位[n].助战编号)

				local 特技 = 玩家数据[self.参战单位[n].玩家id].助战.数据[self.参战单位[n].助战编号].特殊技能

				for k, v in pairs(特技) do
					self.参战单位[n].特技技能[#self.参战单位[n].特技技能 + 1] = {
						等级 = 0,
						名称 = v.名称
					}
				end

				if self:取符石组合效果(n, "无心插柳") then
					self.参战单位[n].溅射 = (self.参战单位[n].溅射 or 0) + self:取符石组合效果(n, "无心插柳")
					local 溅射基数 = 0
					if self:取无心插柳词条个数(n) then
						溅射基数 = self:取无心插柳词条个数(n)
					end
					self.参战单位[n].溅射人数 = self.参战单位[n].溅射人数 + 2*溅射基数
					self.参战单位[n].无心插柳 = 1
				end

				for i = 1, #灵饰战斗属性 do
					self.参战单位[n][灵饰战斗属性[i]] = 玩家数据[self.参战单位[n].玩家id].助战.数据[self.参战单位[n].助战编号][灵饰战斗属性[i]]
				end

				self:添加师门技能(玩家数据[self.参战单位[n].玩家id].助战.数据[self.参战单位[n].助战编号], n, true)
				self:添加角色变身卡数据(n, 玩家数据[self.参战单位[n].玩家id].助战.数据[self.参战单位[n].助战编号])
				self:添加技能属性(self.参战单位[n], self.参战单位[n].技能, "正式添加")
				self:经脉属性处理(n)
			end
		end

		if self.参战单位[n].类型 == "bb" then
			self:添加BB技能属性(n)
			self:经脉属性处理(n)
		end

		if self:取奇经八脉是否有(n, "激怒") and ygsj() <= 10 then
			self:添加状态("蚀天", self.参战单位[n])

			self.参战单位[n].法术状态.蚀天.回合 = 4
		end

		if self:取奇经八脉是否有(n, "道果") then
			self:刷新人参娃娃(n, 1)
		end

		if self.参战单位[n].动物套属性 ~= nil and self.参战单位[n].动物套属性.名称 ~= "无" then
			local 取概率 = 取动物套概率(self.参战单位[n].动物套属性.名称, self.参战单位[n].动物套属性.件数)

			if self.参战单位[n].变身数据 == nil and ygsj() <= 取概率 then
				self.执行等待 = self.执行等待 + 3

				if 变身卡数据[self.参战单位[n].动物套属性.名称] ~= nil and 变身卡数据[self.参战单位[n].动物套属性.名称].技能 ~= "" then
					self:添加技能属性(self.参战单位[n], {
						变身卡数据[self.参战单位[n].动物套属性.名称].技能
					}, "正式添加")
				end

				self.战斗流程[#self.战斗流程 + 1] = {
					流程 = 707,
					攻击方 = n,
					参数 = self.参战单位[n].动物套属性.名称
				}
			end
		end

		if #self.参战单位[n].附加状态 > 0 then
			for i = 1, #self.参战单位[n].附加状态 do
				local 状态 = self.参战单位[n].附加状态[i]
				self.参战单位[n].指令 = {
					参数 = 状态.名称,
					目标 = n
				}
				self.不走流程 = true

				self:法术计算(n, 1)

				self.不走流程 = nil
				self.战斗前附加状态 = 1

				if self.参战单位[n].法术状态[状态.名称] ~= nil then
					local 回合数 = 1

					if tonumber(状态.数量 or 角色套装a) >= 角色套装b + 0 then
						回合数 = 2
					end

					if 角色附加状态回合[状态.名称] ~= nil then
						回合数 = 角色附加状态回合[状态.名称][回合数] + 0
					else
						local aa = {
							3,
							6
						}
						回合数 = aa[回合数] + 0
					end

					self.参战单位[n].法术状态[状态.名称].回合 = 回合数

					if 状态.名称 == "变身" and self:取奇经八脉是否有(n, "宁息") then
						self.参战单位[n].法术状态.变身.回合 = self.参战单位[n].法术状态.变身.回合 + 1
					end
				end

				self:客户端直接添加状态(n, 状态.名称)
			end
		end

		if self.战斗类型 == 134481.6 and self.参战单位[n].队伍 == 0 and self.参战单位[n].名称 == "后土" then
			self:执行怪物召唤(n, 10.3, 0, 2)
		elseif self.战斗类型 == 134481.7 and self.参战单位[n].队伍 == 0 and self.参战单位[n].名称 == "帝江" then
			self.参战单位[n].指令 = {
				参数 = "镜之阳",
				目标 = self:取单个友方目标(n)
			}

			self:法术计算(n, 1)
		elseif self.战斗类型 == 134481.9 and self.参战单位[n].队伍 == 0 and self.参战单位[n].名称 == "句芒" then
			self.参战单位[n].指令 = {
				参数 = "句芒光环",
				目标 = n
			}

			self:法术计算(n, 1)
		end

		if self.参战单位[n].队伍 == 0 and self.参战单位[n].气血 >= 1 and self.战斗类型 == 100009 and self:取阵营数量1(0) <= 5 and string.find(self.参战单位[n].名称, "星宿") == nil then
			self:执行怪物召唤(n, 1, 0, 5 - self:取阵营数量(0))
		end

		if n ~= nil and self:取奇经八脉是否有(n, "迅捷") and self:取玩家战斗() == false and self.参战单位[n].法术状态.变身 == nil then
			self.参战单位[n].指令 = {
				参数 = "变身",
				目标 = n
			}
			self.参战单位[n].迅捷 = 1
			self.不走流程 = true

			self:法术计算(n, 1)

			self.不走流程 = nil
			self.战斗前附加状态 = 1
			self.参战单位[n].迅捷 = nil

			if self.参战单位[n].法术状态.变身 ~= nil then
				self.参战单位[n].法术状态.变身.回合 = 3

				if self:取奇经八脉是否有(n, "宁息") then
					self.参战单位[n].法术状态.变身.回合 = self.参战单位[n].法术状态.变身.回合 + 1
				end
			end

			self:客户端直接添加状态(n, "变身")
		end

		if self.参战单位[n].隐身 ~= nil then
			self:添加状态("修罗隐身", self.参战单位[n], self.参战单位[n], self.参战单位[n].等级)

			if self.参战单位[n].法术状态.修罗隐身 ~= nil then
				self.参战单位[n].法术状态.修罗隐身.回合 = self.参战单位[n].隐身
			end

			self:客户端直接添加状态(n, "修罗隐身")
		end

		if self.参战单位[n].焰火烁星 ~= nil then
			self:添加状态("焰火烁星", self.参战单位[n])
			self:客户端直接添加状态(n, "焰火烁星")
		end

		if self.参战单位[n].与生俱来 ~= nil then
			self:添加护盾(n, self.参战单位[n].最大气血 * self.参战单位[n].与生俱来, n, 1)
			self:客户端直接添加状态(n, "护盾")
		end

		if self.参战单位[n].盾气 ~= nil then
			self:添加状态("盾气", self.参战单位[n], self.参战单位[n], self.参战单位[n].等级, n, self.参战单位[n].盾气)

			if self.参战单位[n].法术状态.盾气 ~= nil and (self.参战单位[n].法术状态.盾气.回合 or 0) < 5 then
				self.参战单位[n].法术状态.盾气.回合 = 5
			end

			self:客户端直接添加状态(n, "盾气")
		end

		if self:取奇经八脉是否有(n, "狂怒") then
			local gl = 5

			if self:取奇经八脉是否有(n, "焦躁") then
				gl = gl + 5
			end

			if ygsj() <= gl + (self.参战单位[n].忿忿 or 0) then
				self:添加状态("狂怒", self.参战单位[n])
				常规提示(self.参战单位[n].玩家id, "#P(狂怒)#R" .. self.参战单位[n].名称 .. "#W进入了#S狂怒#W状态")
			elseif self:取奇经八脉是否有(n, "忿忿") then
				self.参战单位[n].忿忿 = (self.参战单位[n].忿忿 or 0) + 1
			end
		end

		self.参战单位[n].冷却技能列表 = {}

		for i = 1, #冷却技能减回合 do
			if self.参战单位[n][冷却技能减回合[i]] ~= nil and self.参战单位[n][冷却技能减回合[i]] > 0 then
				self.参战单位[n].冷却技能列表[冷却技能减回合[i]] = self.参战单位[n][冷却技能减回合[i]]
			end
		end
	end
end

function 战斗处理类:取飞升技能(技能)
	local 临时名称 = {
		魔息术 = 1,
		还阳术 = 1,
		佛法无边 = 1,
		金刚镯 = 1,
		黄泉之息 = 1,
		一笑倾城 = 1,
		雷霆万钧 = 1,
		摇头摆尾 = 1,
		天魔解体 = 1,
		灵动九天 = 1,
		天地同寿 = 1,
		乾坤妙法 = 1,
		二龙戏珠 = 1,
		飞花摘叶 = 1,
		血雨 = 1,
		镇魂诀 = 1,
		金身舍利 = 1,
		颠倒五行 = 1,
		舍身取义 = 1,
		火甲术 = 1,
		腾雷 = 1,
		分身术 = 1,
		摧心术 = 1,
		安神诀 = 1,
		瘴气 = 1,
		碎甲符 = 1,
		破釜沉舟 = 1,
		幻镜术 = 1,
		神龙摆尾 = 1
	}

	if 临时名称[名称] ~= nil then
		return true
	end

	return false
end

function 战斗处理类:还原单位模型(编号组)
	if type(编号组) == "table" then
		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 707.2,
			攻击方 = 编号组[1],
			挨打方 = {}
		}

		for i = 1, #编号组 do
			local cs = self:取加载信息(编号组[i])
			self.战斗流程[#self.战斗流程].挨打方[#self.战斗流程[#self.战斗流程].挨打方 + 1] = {
				挨打方 = 编号组[i],
				参数 = cs
			}
		end
	else
		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 707.2,
			攻击方 = 编号组,
			挨打方 = {}
		}
		self.战斗流程[#self.战斗流程].挨打方[#self.战斗流程[#self.战斗流程].挨打方 + 1] = {
			挨打方 = 编号组,
			参数 = self:取加载信息(编号组)
		}
	end
end

function 战斗处理类:取加载信息(id)
	if self.参战单位[1].玩家战斗 == nil then
		self.参战单位[1].玩家战斗 = self:取玩家战斗()
	end

	local 临时数据 = {
		气血 = self.参战单位[id].气血,
		气血上限 = self.参战单位[id].气血上限 or self.参战单位[id].最大气血,
		最大气血 = self.参战单位[id].最大气血,
		魔法 = self.参战单位[id].魔法,
		最大魔法 = self.参战单位[id].最大魔法,
		愤怒 = self.参战单位[id].愤怒 or "无",
		名称 = self.参战单位[id].名称,
		模型 = self.参战单位[id].模型,
		队伍 = self.参战单位[id].队伍,
		位置 = self.参战单位[id].位置,
		染色方案 = self.参战单位[id].染色方案,
		染色组 = self.参战单位[id].染色组,
		模型染色 = self.参战单位[id].模型染色,
		饰品染色方案 = self.参战单位[id].饰品染色方案,
		饰品染色组 = self.参战单位[id].饰品染色组,
		武器染色方案 = self.参战单位[id].武器染色方案,
		武器染色组 = self.参战单位[id].武器染色组,
		武器 = self.参战单位[id].武器,
		变异 = self.参战单位[id].变异,
		类型 = self.参战单位[id].类型,
		附加阵法 = self.参战单位[id].附加阵法,
		主动技能 = self.参战单位[id].主动技能,
		特技技能 = self.参战单位[id].特技技能,
		战意 = self.参战单位[id].战意,
		自动指令 = self.参战单位[id].自动指令,
		自动战斗 = self.参战单位[id].自动战斗,
		九黎自动 = self.参战单位[id].九黎自动,
		智能目标 = self.参战单位[id].智能目标,
		九黎组合技能 = self.参战单位[id].九黎组合技能,
		默认法术 = self.参战单位[id].默认法术,
		id = self.参战单位[id].玩家id,
		变身数据 = self.参战单位[id].变身数据,
		显示饰品 = self.参战单位[id].饰品,
		锦衣数据 = self.参战单位[id].锦衣,
		战斗类型 = self.战斗类型,
		助战编号 = self.参战单位[id].助战编号,
		等级 = self.参战单位[id].等级,
		伤害 = self.参战单位[id].伤害 or "无",
		灵力 = self.参战单位[id].灵力 or "无",
		法伤 = self.参战单位[id].法伤 or "无",
		法防 = self.参战单位[id].法防 or "无",
		防御 = self.参战单位[id].防御 or "无",
		躲避 = self.参战单位[id].躲避 or "无",
		速度 = self.参战单位[id].速度 or "无",
		门派 = self.参战单位[id].门派 or "无",
		逃跑 = self.参战单位[id].逃跑,
		死亡状态 = self.参战单位[id].死亡状态,
		玩家战斗 = self.参战单位[1].玩家战斗,
		更新指令 = self.参战单位[id].更新指令,
		冷却技能列表 = self.参战单位[id].冷却技能列表,
		披坚执锐 = self.参战单位[id].披坚执锐
	}
	self.参战单位[id].更新指令 = nil
	local aaa = {
		"愤怒",
		"伤害",
		"灵力",
		"法伤",
		"法防",
		"防御",
		"躲避",
		"速度",
		"气血",
		"最大气血",
		"魔法",
		"最大魔法"
	}

	for i = 1, #aaa do
		if 临时数据[aaa[i]] ~= nil and 临时数据[aaa[i]] ~= "无" then
			临时数据[aaa[i]] = qz(临时数据[aaa[i]])
		end
	end

	if self.参战单位[id].门派 == "九黎城" then
		if self.参战单位[id].黎魂 ~= nil then
			临时数据.黎魂 = self.参战单位[id].黎魂
		end

		if self.参战单位[id].战鼓 ~= nil then
			临时数据.战鼓 = self.参战单位[id].战鼓
		end
	elseif self.参战单位[id].门派 == "花果山" then
		临时数据.神通技能 = self.参战单位[id].神通技能
	end

	if self.参战单位[id].类型 == "角色" then
		local 玩家id = self.参战单位[id].玩家id

		if self.参战单位[id].队伍 ~= 0 and self.参战单位[id].助战编号 == nil then
			if self.参战单位[id].装备[3] ~= nil and 玩家数据[玩家id] ~= nil and 玩家数据[玩家id].角色 ~= nil and 玩家数据[玩家id].角色.数据.装备 ~= nil and 玩家数据[玩家id].角色.数据.装备[3] ~= nil then
				local 装备id = 玩家数据[玩家id].角色.数据.装备[3]

				if 玩家数据[玩家id].道具.数据[装备id].耐久 <= 0 then
					临时数据.武器 = nil
				else
					临时数据.武器 = {
						光武拓印 = 玩家数据[玩家id].道具.数据[装备id].光武拓印,
						名称 = 玩家数据[玩家id].道具.数据[装备id].名称,
						子类 = 玩家数据[玩家id].道具.数据[装备id].子类,
						级别限制 = 玩家数据[玩家id].道具.数据[装备id].级别限制,
						染色方案 = 玩家数据[玩家id].道具.数据[装备id].染色方案,
						染色组 = 玩家数据[玩家id].道具.数据[装备id].染色组
					}
				end
			end

			if self.参战单位[id].装备[4] ~= nil and self.参战单位[id].模型 == "影精灵" and 玩家数据[玩家id] ~= nil and 玩家数据[玩家id].角色 ~= nil and 玩家数据[玩家id].角色.数据.装备 ~= nil and 玩家数据[玩家id].角色.数据.装备[4] ~= nil and 玩家数据[玩家id].道具.数据[玩家数据[玩家id].角色.数据.装备[4]].子类 == 911 then
				local 装备id = 玩家数据[玩家id].角色.数据.装备[4]

				if 玩家数据[玩家id].道具.数据[装备id].耐久 <= 0 then
					临时数据.副武器 = nil
				else
					临时数据.副武器 = {
						光武拓印 = 玩家数据[玩家id].道具.数据[装备id].光武拓印,
						名称 = 玩家数据[玩家id].道具.数据[装备id].名称,
						子类 = 玩家数据[玩家id].道具.数据[装备id].子类,
						级别限制 = 玩家数据[玩家id].道具.数据[装备id].级别限制,
						染色方案 = 玩家数据[玩家id].道具.数据[装备id].染色方案,
						染色组 = 玩家数据[玩家id].道具.数据[装备id].染色组
					}
				end
			end
		elseif self.参战单位[id].队伍 ~= 0 and self.参战单位[id].助战编号 ~= nil then
			if self.参战单位[id].装备[3] ~= nil then
				if self.参战单位[id].装备[3].耐久 <= 0 then
					临时数据.武器 = nil
				else
					临时数据.武器 = {
						光武拓印 = self.参战单位[id].装备[3].光武拓印,
						名称 = self.参战单位[id].装备[3].名称,
						子类 = self.参战单位[id].装备[3].子类,
						级别限制 = self.参战单位[id].装备[3].级别限制,
						染色方案 = self.参战单位[id].装备[3].染色方案,
						染色组 = self.参战单位[id].装备[3].染色组
					}
				end
			end

			if self.参战单位[id].装备[4] ~= nil and self.参战单位[id].模型 == "影精灵" and self.参战单位[id].装备[4].子类 == 911 then
				if self.参战单位[id].装备[4].耐久 <= 0 then
					临时数据.副武器 = nil
				else
					临时数据.副武器 = {
						光武拓印 = self.参战单位[id].装备[4].光武拓印,
						名称 = self.参战单位[id].装备[4].名称,
						子类 = self.参战单位[id].装备[4].子类,
						级别限制 = self.参战单位[id].装备[4].级别限制,
						染色方案 = self.参战单位[id].装备[4].染色方案,
						染色组 = self.参战单位[id].装备[4].染色组
					}
				end
			end
		end
	elseif self.参战单位[id].类型 == "系统角色" then
		临时数据.武器 = self.参战单位[id].武器
	elseif self.参战单位[id].类型 == "系统PK角色" then
		临时数据.武器 = self.参战单位[id].武器
	end

	return 临时数据
end

function 战斗处理类:增加阵法属性(编号, 名称, 位置, 阵法加成)
	local 临时队伍id = self.参战单位[编号].队伍

	if 队伍数据[临时队伍id] ~= nil and #队伍数据[临时队伍id].成员数据 >= 1 then
		local x阵法加成 = 1

		if 阵法加成 ~= nil then
			x阵法加成 = 1 + 阵法加成
		end

		if 名称 == "天覆阵" then
			self.参战单位[编号].速度 = qz(self.参战单位[编号].速度 * (1 - 0.1 * x阵法加成))
			self.参战单位[编号].物理加成 = 1.2 * x阵法加成
			self.参战单位[编号].灵力加成 = 1.2 * x阵法加成
		elseif 名称 == "风扬阵" then
			if 位置 == 1 then
				self.参战单位[编号].物理加成 = 1.2 * x阵法加成
				self.参战单位[编号].灵力加成 = 1.2 * x阵法加成
			elseif 位置 == 2 or 位置 == 3 then
				self.参战单位[编号].物理加成 = 1.1 * x阵法加成
				self.参战单位[编号].灵力加成 = 1.1 * x阵法加成
			else
				self.参战单位[编号].速度 = qz(self.参战单位[编号].速度 * 1.1 * x阵法加成)
			end
		elseif 名称 == "虎翼阵" then
			if 位置 == 1 then
				self.参战单位[编号].物理加成 = 1.25 * x阵法加成
				self.参战单位[编号].灵力加成 = 1.25 * x阵法加成
			elseif 位置 == 2 or 位置 == 3 then
				self.参战单位[编号].防御 = qz(self.参战单位[编号].防御 * 1.1 * x阵法加成)
				self.参战单位[编号].法防 = qz(self.参战单位[编号].法防 * 1.1 * x阵法加成)
			else
				self.参战单位[编号].物理加成 = 1.1 * x阵法加成
			end
		elseif 名称 == "云垂阵" then
			if 位置 == 1 then
				self.参战单位[编号].防御 = qz(self.参战单位[编号].防御 * 1.4 * x阵法加成)
				self.参战单位[编号].法防 = qz(self.参战单位[编号].法防 * 1.4 * x阵法加成)
				self.参战单位[编号].速度 = qz(self.参战单位[编号].速度 * (1 - 0.3 * x阵法加成))
			elseif 位置 == 2 then
				self.参战单位[编号].防御 = qz(self.参战单位[编号].防御 * 1.1 * x阵法加成)
				self.参战单位[编号].法防 = qz(self.参战单位[编号].法防 * 1.1 * x阵法加成)
			elseif 位置 == 3 then
				self.参战单位[编号].物理加成 = 1.2 * x阵法加成
				self.参战单位[编号].灵力加成 = 1.2 * x阵法加成
			else
				self.参战单位[编号].速度 = qz(self.参战单位[编号].速度 * 1.15 * x阵法加成)
			end
		elseif 名称 == "鸟翔阵" then
			if 位置 == 1 then
				self.参战单位[编号].速度 = qz(self.参战单位[编号].速度 * 1.2 * x阵法加成)
			elseif 位置 == 2 or 位置 == 3 then
				self.参战单位[编号].速度 = qz(self.参战单位[编号].速度 * 1.2 * x阵法加成)
			else
				self.参战单位[编号].速度 = qz(self.参战单位[编号].速度 * 1.2 * x阵法加成)
			end
		elseif 名称 == "地载阵" then
			if 位置 == 1 or 位置 == 3 or 位置 == 4 then
				self.参战单位[编号].防御 = qz(self.参战单位[编号].防御 * 1.15 * x阵法加成)
				self.参战单位[编号].法防 = qz(self.参战单位[编号].法防 * 1.15 * x阵法加成)
			elseif 位置 == 2 then
				self.参战单位[编号].物理加成 = 1.15 * x阵法加成
				self.参战单位[编号].灵力加成 = 1.15 * x阵法加成
			else
				self.参战单位[编号].速度 = qz(self.参战单位[编号].速度 * 1.1 * x阵法加成)
			end
		elseif 名称 == "龙飞阵" then
			if 位置 == 1 then
				self.参战单位[编号].法防 = qz(self.参战单位[编号].法防 * 1.2 * x阵法加成)
			elseif 位置 == 2 then
				self.参战单位[编号].防御 = qz(self.参战单位[编号].防御 * 1.2 * x阵法加成)
			elseif 位置 == 3 then
				self.参战单位[编号].灵力加成 = 1.3 * x阵法加成
				self.参战单位[编号].速度 = qz(self.参战单位[编号].速度 * (1 - 0.3 * x阵法加成))
			elseif 位置 == 4 then
				self.参战单位[编号].速度 = qz(self.参战单位[编号].速度 * 1.15 * x阵法加成)
			elseif 位置 == 5 then
				self.参战单位[编号].物理加成 = 1.2 * x阵法加成
				self.参战单位[编号].灵力加成 = 1.2 * x阵法加成
			end
		elseif 名称 == "鹰啸阵" then
			if 位置 == 1 then
				self.参战单位[编号].防御 = qz(self.参战单位[编号].防御 * 1.1 * x阵法加成)
			elseif 位置 == 2 then
				self.参战单位[编号].速度 = qz(self.参战单位[编号].速度 * 1.15 * x阵法加成)
			elseif 位置 == 3 then
				self.参战单位[编号].速度 = qz(self.参战单位[编号].速度 * 1.15 * x阵法加成)
			elseif 位置 == 4 then
				self.参战单位[编号].物理加成 = 1.15 * x阵法加成
				self.参战单位[编号].灵力加成 = 1.15 * x阵法加成
			else
				self.参战单位[编号].物理加成 = 1.1 * x阵法加成
				self.参战单位[编号].灵力加成 = 1.1 * x阵法加成
			end
		elseif 名称 == "蛇蟠阵" then
			if 位置 == 1 then
				self.参战单位[编号].法防 = qz(self.参战单位[编号].法防 * 1.15 * x阵法加成)
			elseif 位置 == 2 then
				self.参战单位[编号].法防 = qz(self.参战单位[编号].法防 * 1.15 * x阵法加成)
			elseif 位置 == 3 then
				self.参战单位[编号].法防 = qz(self.参战单位[编号].法防 * 1.15 * x阵法加成)
			elseif 位置 == 4 then
				self.参战单位[编号].物理加成 = 1.1 * x阵法加成
				self.参战单位[编号].灵力加成 = 1.1 * x阵法加成
			else
				self.参战单位[编号].物理加成 = 1.1 * x阵法加成
				self.参战单位[编号].灵力加成 = 1.1 * x阵法加成
			end
		elseif 名称 == "雷绝阵" then
			if 位置 == 1 then
				self.参战单位[编号].固伤加成 = 1.2 * x阵法加成
				self.参战单位[编号].bb伤害加成 = 1.1 * x阵法加成
				self.参战单位[编号].bb灵力加成 = 1.1 * x阵法加成
			elseif 位置 == 2 then
				self.参战单位[编号].固伤加成 = 1.2 * x阵法加成
				self.参战单位[编号].bb伤害加成 = 1.1 * x阵法加成
				self.参战单位[编号].bb灵力加成 = 1.1 * x阵法加成
			elseif 位置 == 3 then
				self.参战单位[编号].固伤加成 = 1.2 * x阵法加成
				self.参战单位[编号].bb伤害加成 = 1.1 * x阵法加成
				self.参战单位[编号].bb灵力加成 = 1.1 * x阵法加成
			elseif 位置 == 4 then
				self.参战单位[编号].物理加成 = 1.1 * x阵法加成
				self.参战单位[编号].灵力加成 = 1.1 * x阵法加成
				self.参战单位[编号].bb伤害加成 = 1.1 * x阵法加成
				self.参战单位[编号].bb灵力加成 = 1.1 * x阵法加成
			else
				self.参战单位[编号].物理加成 = 1.1 * x阵法加成
				self.参战单位[编号].灵力加成 = 1.1 * x阵法加成
				self.参战单位[编号].bb伤害加成 = 1.1 * x阵法加成
				self.参战单位[编号].bb灵力加成 = 1.1 * x阵法加成
			end
		end
	end
end

单位通用属性 = {
	"法术状态",
	"法宝列表",
	"被动技能",
	"主动技能",
	"主动技能1",
	"奇经八脉",
	"追加法术",
	"附加状态",
	"已加技能",
	"特技技能",
	"法宝佩戴",
	"符石组合",
	"符石技能效果"
}

function 战斗处理类:加载单位通用属性(编号, 测试)
	if self.参战单位[编号] ~= nil then
		self.临时属性[编号] = {}
		self.参战单位[编号].战斗编号 = 编号 + 0
		self.参战单位[编号].封印命中率 = self.参战单位[编号].封印命中率 or 0
		self.参战单位[编号].封印抵抗率 = self.参战单位[编号].封印抵抗率 or 0
		self.参战单位[编号].武器伤害 = self.参战单位[编号].武器伤害 or 0

		if self.参战单位[编号].法伤 == nil then
			self.参战单位[编号].法伤 = self.参战单位[编号].灵力
		end

		self.参战单位[编号].愤怒 = self.参战单位[编号].愤怒 or 0

		for i = 1, #单位通用属性 do
			if self.参战单位[编号][单位通用属性[i]] == nil then
				self.参战单位[编号][单位通用属性[i]] = {}
			end
		end

		for i = 1, #灵饰战斗属性 do
			if self.参战单位[编号][灵饰战斗属性[i]] == nil then
				self.参战单位[编号][灵饰战斗属性[i]] = 0
			end
		end

		for i = 1, #五维列表 do
			if self.参战单位[编号][五维列表[i]] == nil then
				self.参战单位[编号][五维列表[i]] = self.参战单位[编号].等级 * 2 + 20
			end
		end

		self.临时属性[编号].攻击五行 = self.临时属性[编号].五行 or self.临时属性[编号].攻击五行 or 取五行()
		self.临时属性[编号].防御五行 = self.临时属性[编号].五行 or self.临时属性[编号].防御五行 or 取五行()
	end
end

function 战斗处理类:加载预置单位(id, 位置, 队伍id, 父编号)
	if #玩家数据[id].召唤兽.数据 >= 1 then
		self.参战单位[#self.参战单位 + 1] = {}
		self.参战单位[#self.参战单位] = table.loadstring(玩家数据[id].召唤兽:获取指定数据(1))
		self.参战单位[#self.参战单位].队伍 = 队伍id
		self.参战单位[#self.参战单位].认证码 = nil
		self.参战单位[#self.参战单位].位置 = 位置 + 5
		self.参战单位[#self.参战单位].主人 = #self.参战单位 - 1
		self.参战单位[#self.参战单位].类型 = "bb"
		self.参战单位[#self.参战单位].玩家id = id
		self.参战单位[#self.参战单位].技能 = {}
		self.参战单位[#self.参战单位].护符附带技能 = {}
		self.参战单位[#self.参战单位].主人或助战 = #self.参战单位 - 1
		self.参战单位[#self.参战单位].死亡状态 = 1
		self.参战单位[#self.参战单位].逃跑 = true
		self.参战单位[#self.参战单位].忠诚 = 0
		self.参战单位[#self.参战单位].预置bb = 1

		if 父编号 ~= nil then
			self.参战单位[父编号].助战明细[#self.参战单位[父编号].助战明细 + 1] = #self.参战单位 + 0
		end

		self:加载单位通用属性(#self.参战单位 + 0)
		self:设置队伍区分(队伍id)
	end
end

function 战斗处理类:加载召唤兽加成属性(编号)
	self:更新五维数据(编号)

	local 主人编号 = 0

	if self.参战单位[编号].主人或助战 ~= nil and self.参战单位[self.参战单位[编号].主人或助战号] ~= nil then
		主人编号 = self.参战单位[编号].主人或助战
		self.参战单位[编号].附加阵法 = self.参战单位[主人编号].附加阵法

		if self.参战单位[主人编号].愤怒 ~= nil and self.参战单位[主人编号].愤怒 > 150 and 服务端参数.愤怒超限 ~= 1 and self.参战单位[主人编号].类型 == "角色" then
			self.参战单位[主人编号].愤怒 = 150
		end

		if self:取奇经八脉是否有(主人编号, "御兽") and self.参战单位[编号].速度 >= self.参战单位[编号].等级 * 3 then
			self.参战单位[编号].速度 = self.参战单位[编号].速度 + qz(self.参战单位[编号].等级 * 0.7)
			self.参战单位[编号].法防 = self.参战单位[编号].法防 + qz(self.参战单位[编号].等级 * 1)
		end

		if self:取奇经八脉是否有(主人编号, "国色") and self.参战单位[编号].速度 >= self.参战单位[编号].等级 * 5 then
			self.参战单位[编号].速度 = qz1(self.参战单位[编号].速度 * 1.12)
		end

		if self:取奇经八脉是否有(主人编号, "共鸣") then
			self.参战单位[编号].共鸣 = 1.12
		end

		if self:取奇经八脉是否有(主人编号, "电掣") and self.参战单位[主人编号].召唤数量 ~= nil then
			self.参战单位[编号].电掣 = 1 + #self.参战单位[主人编号].召唤数量 * 0.05
		end

		if self:取奇经八脉是否有(主人编号, "协同") and (self.同门派减伤[self.参战单位[主人编号].队伍].狮驼岭 or 0) <= 1 then
			self.参战单位[编号].协同 = 1.25
		end

		if self:取奇经八脉是否有(主人编号, "健壮") then
			self.参战单位[编号].防御 = self.参战单位[编号].防御 * 1.1
			self.参战单位[编号].法防 = self.参战单位[编号].法防 * 1.1
		end

		if self:取奇经八脉是否有(主人编号, "守势") then
			self.参战单位[编号].守势 = 0.9
		end

		if self:取奇经八脉是否有(主人编号, "嗜血", "万兽之王") then
			self.参战单位[编号].嗜血 = 1
		end

		if self:取奇经八脉是否有(主人编号, "救主") then
			self.参战单位[编号].救主 = 主人编号
		end

		if self:取奇经八脉是否有(主人编号, "报恩") then
			self.参战单位[编号].报恩 = 主人编号
		end

		if self:取奇经八脉是否有(主人编号, "矫健", "万兽之王") then
			self.参战单位[编号].矫健 = 1.1
		end

		if self:取奇经八脉是否有(主人编号, "狂化") then
			self.参战单位[编号].狂化 = 主人编号
		end

		if self:取奇经八脉是否有(主人编号, "羁绊") then
			self.参战单位[编号].羁绊 = 主人编号
		end

		if self:取奇经八脉是否有(主人编号, "朝拜") then
			local 猴类召唤兽 = {
				自在心猿 = 1,
				美猴王 = 1,
				巨力神猿 = 1,
				通臂猿猴 = 1,
				砍刀猴 = 1,
				超级神猴 = 1,
				超级金猴 = 1,
				新孙悟空 = 1,
				黑悟空 = 1,
				孙悟空 = 1,
				神兽孙小圣 = 1,
				孙行者 = 1,
				长眉灵猴 = 1,
				齐天小圣 = 1,
				超级六耳猕猴 = 1
			}

			if 猴类召唤兽[string.gsub(self.参战单位[编号].最初模型 or self.参战单位[编号].模型, "进阶", "")] ~= nil then
				self.参战单位[编号].朝拜 = 1.1
			end
		end

		if self:取奇经八脉是否有(主人编号, "生克") then
			self.参战单位[编号].灵力 = self.参战单位[编号].灵力 * 1.15
			self.参战单位[编号].法伤 = self.参战单位[编号].法伤 * 1.15
			self.参战单位[编号].法防 = self.参战单位[编号].法防 * 1.15

			if self.参战单位[主人编号].生克 == nil then
				self.参战单位[主人编号].灵力 = self.参战单位[主人编号].灵力 * 1.15
				self.参战单位[主人编号].法伤 = self.参战单位[主人编号].法伤 * 1.15
				self.参战单位[主人编号].法防 = self.参战单位[主人编号].法防 * 1.15
				self.参战单位[主人编号].法伤 = self.参战单位[主人编号].法伤 * 1.15
				self.参战单位[主人编号].生克 = 1
			end
		end

		if self.参战单位[主人编号].驯兽师 ~= nil then
			self.参战单位[编号].驯兽 = 1

			self:添加主动技能(self.参战单位[编号], "幼狮之搏", self.参战单位[主人编号].被动技能.生死搏 or self.参战单位[主人编号].等级)

			if self.参战单位[编号].夜战 == nil then
				self.参战单位[编号].夜战 = 1
			end
		end

		if self.参战单位[主人编号].驭兽 ~= nil then
			self.参战单位[编号].伤害 = qz(self.参战单位[编号].伤害 + self.参战单位[主人编号].驭兽 * 0.4)
			self.参战单位[编号].防御 = qz(self.参战单位[编号].防御 + self.参战单位[主人编号].驭兽 * 0.4)
			self.参战单位[编号].灵力 = qz(self.参战单位[编号].灵力 + self.参战单位[主人编号].驭兽 * 0.2)
			self.参战单位[编号].法伤 = qz(self.参战单位[编号].法伤 + self.参战单位[主人编号].驭兽 * 0.2)
			self.参战单位[编号].法防 = qz(self.参战单位[编号].法防 + self.参战单位[主人编号].驭兽 * 0.2)
		end

		if self.参战单位[主人编号].bb伤害加成 ~= nil then
			self.参战单位[编号].物理加成 = self.参战单位[主人编号].bb伤害加成
		end

		if self.参战单位[主人编号].bb灵力加成 ~= nil then
			self.参战单位[编号].灵力加成 = self.参战单位[主人编号].bb灵力加成
		end

		if self.参战单位[主人编号].特效指挥 ~= nil then
			self:添加状态("指挥", self.参战单位[编号], self.参战单位[编号], self.参战单位[编号].等级, 编号)
		end
	end

	if self.参战单位[编号].法伤 == nil then
		self.参战单位[编号].法伤 = self.参战单位[编号].灵力
	end

	self.参战单位[编号].法伤 = qz1(self.参战单位[编号].法伤 + self.参战单位[编号].伤害 * 0.1)
	self.参战单位[编号].灵伤差 = self.参战单位[编号].法伤 - self.参战单位[编号].灵力

	if self.参战单位[编号].法防 == nil then
		self.参战单位[编号].法防 = self.参战单位[编号].灵力
	end

	self.参战单位[编号].命中 = self.参战单位[编号].伤害
	self.参战单位[编号].躲避 = self.参战单位[编号].躲避 or 0
	self.参战单位[编号].法暴 = 基础法暴率 + 0

	self:加载单位通用属性(编号 + 0)

	if self.参战单位[编号].最大气血 < self.参战单位[编号].气血 then
		self.参战单位[编号].气血 = self.参战单位[编号].最大气血
	end

	if self.参战单位[编号].最大魔法 < self.参战单位[编号].魔法 then
		self.参战单位[编号].魔法 = self.参战单位[编号].最大魔法
	end

	self:添加召唤兽特性(编号)
end

function 战斗处理类:更新五维数据(编号)
	for i = 1, #五维列表 do
		if self.参战单位[编号]["计算" .. 五维列表[i]] ~= nil then
			self.参战单位[编号][五维列表[i]] = self.参战单位[编号]["计算" .. 五维列表[i]] + 0
		end
	end

	if self.参战单位[编号].装备属性 ~= nil then
		self.参战单位[编号].武器伤害 = qz((self.参战单位[编号].装备属性.伤害 or 0) + (self.参战单位[编号].装备属性.命中 or 0) / 3)
	end
end

function 战斗处理类:取门派减伤(编号, 队伍id)
	if self.参战单位[编号].门派 ~= nil and 门派名称1[self.参战单位[编号].门派] ~= nil then
		self.同门派减伤[队伍id][self.参战单位[编号].门派] = (self.同门派减伤[队伍id][self.参战单位[编号].门派] or 0) + 1
		self.同门派减伤[队伍id].减伤 = 1
		local 全不同 = 0

		for i, v in pairs(self.同门派减伤[队伍id]) do
			if v == 1 then
				全不同 = 全不同 + 1
			end

			if i ~= "九黎城" and 门派名称1[i] ~= nil and v >= 2 then
				if v == 2 then
					self.同门派减伤[队伍id].减伤 = self.同门派减伤[队伍id].减伤 - 同门派减伤列表[v]
				elseif v == 3 then
					self.同门派减伤[队伍id].减伤 = self.同门派减伤[队伍id].减伤 - 同门派减伤列表[v]
				elseif v == 4 then
					self.同门派减伤[队伍id].减伤 = self.同门派减伤[队伍id].减伤 - 同门派减伤列表[v]
				else
					self.同门派减伤[队伍id].减伤 = self.同门派减伤[队伍id].减伤 - 同门派减伤列表[v]
				end
			end
		end

		if 全不同 == 5 then
			self.同门派减伤[队伍id].减伤 = 1.05
		end
	end
end

function 战斗处理类:加载单个玩家(id, 位置)
	local 扶阵个数 = 0

	系统处理类:进入战斗检测(id)

	self.参战单位[#self.参战单位 + 1] = {}
	self.参战单位[#self.参战单位] = table.loadstring(table.tostring(玩家数据[id].角色:取总数据()))

	self:加载单位通用属性(#self.参战单位 + 0, 1)

	local 队伍id = 玩家数据[id].队伍
	self.参战单位[#self.参战单位].附加阵法 = "普通"

	if 队伍数据[队伍id] ~= nil and #队伍数据[队伍id].成员数据 == 5 then
		self.参战单位[#self.参战单位].附加阵法 = 队伍数据[队伍id].阵型
	end

	if 队伍id == 0 then
		队伍id = id
	else
		self.参战单位[#self.参战单位].附加阵法 = 队伍数据[队伍id].阵型
	end

	self.参战玩家[#self.参战玩家].队伍 = 队伍id
	self.参战单位[#self.参战单位].队伍 = 队伍id

	if self.队长单位[队伍id] == nil then
		self.队长单位[队伍id] = #self.参战单位 + 0
	end

	if self.同门派减伤[队伍id] == nil then
		self.同门派减伤[队伍id] = {}
	end

	self:取门派减伤(#self.参战单位, 队伍id)

	self.参战单位[#self.参战单位].位置 = 位置
	self.参战单位[#self.参战单位].类型 = "角色"
	self.参战单位[#self.参战单位].玩家id = id
	self.参战单位[#self.参战单位].召唤兽 = nil

	self:更新五维数据(#self.参战单位)

	self.参战单位[#self.参战单位].灵力 = self.参战单位[#self.参战单位].灵力

	if self.参战单位[#self.参战单位].法伤 == nil then
		self.参战单位[#self.参战单位].法伤 = self.参战单位[#self.参战单位].灵力
	else
		self.参战单位[#self.参战单位].法伤 = self.参战单位[#self.参战单位].法伤
	end

	self.参战单位[#self.参战单位].灵伤差 = self.参战单位[#self.参战单位].法伤 - self.参战单位[#self.参战单位].灵力

	if self.参战单位[#self.参战单位].法防 == nil then
		self.参战单位[#self.参战单位].法防 = self.参战单位[#self.参战单位].灵力
	else
		self.参战单位[#self.参战单位].法防 = self.参战单位[#self.参战单位].法防
	end

	self.参战单位[#self.参战单位].躲避 = self.参战单位[#self.参战单位].躲避
	self.参战单位[#self.参战单位].召唤数量 = {}
	self.参战单位[#self.参战单位].召唤总数量 = {}

	if 玩家数据[id].角色.数据.自动战斗 then
		self.参战单位[#self.参战单位].自动战斗 = true
	end

	self.参战单位[#self.参战单位].攻击指挥 = self.参战单位[#self.参战单位].bb修炼.攻击控制力[1]
	self.参战单位[#self.参战单位].法术指挥 = self.参战单位[#self.参战单位].bb修炼.法术控制力[1]
	self.参战单位[#self.参战单位].防御指挥 = self.参战单位[#self.参战单位].bb修炼.防御控制力[1]
	self.参战单位[#self.参战单位].抗法指挥 = self.参战单位[#self.参战单位].bb修炼.抗法控制力[1]
	self.参战单位[#self.参战单位].真仙元神 = 玩家数据[id].角色.数据.真仙元神

	self:设置队伍区分(队伍id)

	if self.参战单位[#self.参战单位].类型 == "角色" and self.参战单位[#self.参战单位].助战编号 ~= nil then
		for i, v in pairs(玩家数据[self.参战单位[#self.参战单位].玩家id].助战.数据[self.参战单位[#self.参战单位].助战编号].装备) do
			if v ~= nil and 玩家数据[self.参战单位[#self.参战单位].玩家id].道具.数据[v] ~= nil and 玩家数据[self.参战单位[#self.参战单位].玩家id].道具.数据[v].级别限制 >= 90 and 玩家数据[self.参战单位[#self.参战单位].玩家id].道具.数据[v].制造者 == "商城购买" then
				self.参战单位[#self.参战单位].防御 = self.参战单位[#self.参战单位].防御 - 99999
				local 账号 = 玩家数据[id].账号
				local 封禁机器码 = f函数.读配置(程序目录 .. "data\\" .. 账号 .. "\\账号信息.txt", "账号配置", "机器码")

				f函数.写配置(程序目录 .. "机器码封禁.ini", "机器码", 封禁机器码, "1")
				__S服务:输出("玩家" .. id .. " 非法使用外挂警告！！！")
				写配置("./ip封禁.ini", "ip", 玩家数据[id].ip, 1)
				写配置("./ip封禁.ini", "ip", 玩家数据[id].ip .. " 非法使用外挂,玩家ID:" .. id, 1)
				发送数据(玩家数据[id].连接id, 998, "请注意你的角色异常！已经对你进行封IP")
				__S服务:连接退出(玩家数据[id].连接id)
			end
		end
	end

	if self.战斗类型 == 110002 then
		self.参战单位[#self.参战单位].附加阵法 = "云垂阵"
	end

	if self.战斗类型 == 110002 then
		self.战斗发言数据[#self.战斗发言数据 + 1] = {
			内容 = [[
#G/门派师傅们
我#Y/已将神力
全部灌注与你们
你们上吧]],
			id = #self.参战单位
		}
	end

	if 玩家数据[id].角色.数据.奇经八脉.开启奇经八脉 ~= nil and 玩家数据[id].角色.数据.奇经八脉.开启奇经八脉 then
		self.参战单位[#self.参战单位].经脉有无 = 玩家数据[id].角色.数据.奇经八脉.开启奇经八脉
	end

	if 玩家数据[id].队伍 ~= nil and self:取奇经八脉是否有(#self.参战单位, "扶阵") then
		扶阵个数 = 扶阵个数 + 1
	end

	if self.参战单位[#self.参战单位].参战信息 ~= nil and 玩家数据[id].召唤兽.数据[玩家数据[id].召唤兽:取编号(玩家数据[id].角色.数据.参战宝宝.认证码)] ~= nil then
		local 编号 = 玩家数据[id].召唤兽:取编号(玩家数据[id].角色.数据.参战宝宝.认证码)
		local 临时bb = 玩家数据[id].召唤兽.数据[编号]
		local 参战 = true

		玩家数据[id].召唤兽:月卡自动喂养处理(id, 编号)

		if 临时bb ~= nil and (临时bb.忠诚 <= 70 and ygsj() >= 50 or 临时bb.忠诚 <= 60) then
			常规提示(id, "你的召唤兽" .. 临时bb.名称 .. "由于忠诚过低，不愿意参战")

			参战 = false
		elseif 临时bb ~= nil and 临时bb.种类 ~= "神兽" and 临时bb.寿命 <= 50 then
			常规提示(id, "你的召唤兽" .. 临时bb.名称 .. "由于寿命过低，不愿意参战")

			参战 = false
		end

		if 临时bb ~= nil and 参战 and 临时bb.种类 ~= "神兽" and 临时bb.种类 ~= "孩子" then
			玩家数据[id].召唤兽.数据[玩家数据[id].召唤兽:取编号(玩家数据[id].角色.数据.参战宝宝.认证码)].寿命 = 玩家数据[id].召唤兽.数据
			[玩家数据[id].召唤兽:取编号(玩家数据[id].角色.数据.参战宝宝.认证码)].寿命 - 1

			if 忠诚度开启 then
				玩家数据[id].召唤兽.数据[玩家数据[id].召唤兽:取编号(玩家数据[id].角色.数据.参战宝宝.认证码)].忠诚 = 玩家数据[id].召唤兽.数据
				[玩家数据[id].召唤兽:取编号(玩家数据[id].角色.数据.参战宝宝.认证码)].忠诚 - 0.5
			end
		end

		if 参战 then
			self.参战单位[#self.参战单位 + 1] = {}
			self.参战单位[#self.参战单位] = table.loadstring(玩家数据[id].召唤兽:获取指定数据(玩家数据[id].召唤兽:取编号(玩家数据[id].角色.数据.参战宝宝.认证码)))
			self.参战单位[#self.参战单位].队伍 = 队伍id
			self.参战单位[#self.参战单位].位置 = 位置 + 5
			self.参战单位[#self.参战单位].主人 = #self.参战单位 - 1
			self.参战单位[#self.参战单位].主人或助战 = #self.参战单位 - 1
			self.参战单位[#self.参战单位].类型 = "bb"
			self.参战单位[#self.参战单位].玩家id = id
			self.参战单位[#self.参战单位 - 1].召唤兽 = #self.参战单位
			self.参战单位[#self.参战单位].自动战斗 = self.参战单位[#self.参战单位 - 1].自动战斗
			self.参战单位[#self.参战单位 - 1].召唤数量[1] = 玩家数据[id].召唤兽:取编号(玩家数据[id].角色.数据.参战宝宝.认证码)
			self.参战单位[#self.参战单位 - 1].召唤总数量[1] = self.参战单位[#self.参战单位 - 1].召唤数量[1]

			self:加载召唤兽加成属性(#self.参战单位)
			self:设置队伍区分(队伍id)
		else
			self:加载预置单位(id, 位置, 队伍id)
		end

		local 临时技能 = {}
	else
		self:加载预置单位(id, 位置, 队伍id)
	end

	if self.战斗类型 ~= 200004 and 玩家数据[id].队伍 ~= 0 and 玩家数据[id].队长 then
		local 父编号 = self:取参战编号(id, "角色")

		for i = 1, #队伍数据[玩家数据[id].队伍].成员数据 do
			if 队伍处理类:取是否助战(玩家数据[id].队伍, i) ~= 0 then
				local 助战编号 = 队伍处理类:取助战编号(玩家数据[id].队伍, i)

				if self.参战单位[父编号].助战明细 == nil then
					self.参战单位[父编号].助战明细 = {}
				end

				self.参战单位[父编号].助战明细[#self.参战单位[父编号].助战明细 + 1] = #self.参战单位 + 1
				self.参战单位[#self.参战单位 + 1] = {}
				self.参战单位[#self.参战单位] = table.loadstring(table.tostring(玩家数据[id].助战:取总数据(助战编号)))
				self.参战单位[#self.参战单位].锦衣 = self.参战单位[#self.参战单位].锦衣名称

				self:加载单位通用属性(#self.参战单位 + 0, 2)

				self.参战单位[#self.参战单位].附加阵法 = "普通"

				if #队伍数据[玩家数据[id].队伍].成员数据 > 1 then
					self.参战单位[#self.参战单位].附加阵法 = 队伍数据[玩家数据[id].队伍].阵型
				end

				self.参战单位[#self.参战单位].队伍 = 队伍id
				self.参战单位[#self.参战单位].位置 = i
				self.参战单位[#self.参战单位].类型 = "角色"
				self.参战单位[#self.参战单位].玩家id = id
				self.参战单位[#self.参战单位].助战编号 = 助战编号
				self.参战单位[#self.参战单位].召唤兽 = nil
				self.参战单位[#self.参战单位].主人 = 父编号
				self.参战单位[#self.参战单位].召唤数量 = {}

				self:更新五维数据(#self.参战单位)

				if self.参战单位[#self.参战单位].法伤 == nil then
					self.参战单位[#self.参战单位].法伤 = self.参战单位[#self.参战单位].灵力
				else
					self.参战单位[#self.参战单位].法伤 = self.参战单位[#self.参战单位].法伤
				end

				self.参战单位[#self.参战单位].灵伤差 = self.参战单位[#self.参战单位].法伤 - self.参战单位[#self.参战单位].灵力

				if self.参战单位[#self.参战单位].法防 == nil then
					self.参战单位[#self.参战单位].法防 = self.参战单位[#self.参战单位].灵力
				else
					self.参战单位[#self.参战单位].法防 = self.参战单位[#self.参战单位].法防
				end

				self.参战单位[#self.参战单位].躲避 = self.参战单位[#self.参战单位].躲避 or 0
				self.参战单位[#self.参战单位].自动战斗 = self.参战单位[父编号].自动战斗

				self:设置队伍区分(队伍id)

				if self.同门派减伤[队伍id] == nil then
					self.同门派减伤[队伍id] = {}
				end

				self:取门派减伤(#self.参战单位, 队伍id)

				self.参战单位[#self.参战单位].攻击指挥 = 玩家数据[id].角色.数据.bb修炼.攻击控制力[1]
				self.参战单位[#self.参战单位].法术指挥 = 玩家数据[id].角色.数据.bb修炼.法术控制力[1]
				self.参战单位[#self.参战单位].防御指挥 = 玩家数据[id].角色.数据.bb修炼.防御控制力[1]
				self.参战单位[#self.参战单位].抗法指挥 = 玩家数据[id].角色.数据.bb修炼.抗法控制力[1]

				if self:取奇经八脉是否有(#self.参战单位, "扶阵") then
					扶阵个数 = 扶阵个数 + 1
				end

				if self.参战单位[#self.参战单位].宠物认证码 ~= nil then
					local 编号 = 玩家数据[id].召唤兽:取编号(self.参战单位[#self.参战单位].宠物认证码)

					if 编号 ~= 0 then
						local 临时bb = 玩家数据[id].召唤兽.数据[编号]
						local 参战 = true

						玩家数据[id].召唤兽:月卡自动喂养处理(id, 编号)

						if 临时bb ~= nil and (临时bb.忠诚 <= 70 and ygsj() >= 50 or 临时bb.忠诚 <= 60) then
							常规提示(id, "你的助战召唤兽" .. 临时bb.名称 .. "由于忠诚过低，不愿意参战")

							参战 = false
						elseif 临时bb ~= nil and 临时bb.种类 ~= "神兽" and 临时bb.寿命 <= 50 then
							常规提示(id, "你的助战召唤兽" .. 临时bb.名称 .. "由于寿命过低，不愿意参战")

							参战 = false
						end

						if 临时bb ~= nil and 参战 and 临时bb.种类 ~= "神兽" and 临时bb.种类 ~= "孩子" then
							玩家数据[id].召唤兽.数据[编号].寿命 = 玩家数据[id].召唤兽.数据[编号].寿命 - 1

							if 忠诚度开启 then
								玩家数据[id].召唤兽.数据[编号].忠诚 = 玩家数据[id].召唤兽.数据[编号].忠诚 - 0.5
							end
						end

						if 参战 then
							self.参战单位[父编号].助战明细[#self.参战单位[父编号].助战明细 + 1] = #self.参战单位 + 1
							self.参战单位[#self.参战单位 + 1] = {}
							self.参战单位[#self.参战单位] = table.loadstring(玩家数据[id].召唤兽:获取指定数据(编号))
							self.参战单位[#self.参战单位].队伍 = 队伍id
							self.参战单位[#self.参战单位].位置 = i + 5
							self.参战单位[#self.参战单位].类型 = "bb"
							self.参战单位[#self.参战单位].玩家id = id
							self.参战单位[#self.参战单位].分类 = "野怪"
							self.参战单位[#self.参战单位].助战编号 = 助战编号 + 5
							self.参战单位[#self.参战单位].主人 = 父编号
							self.参战单位[#self.参战单位].主人或助战 = #self.参战单位 - 1
							self.参战单位[#self.参战单位 - 1].召唤兽 = #self.参战单位
							self.参战单位[#self.参战单位].自动战斗 = self.参战单位[父编号].自动战斗
							self.参战单位[#self.参战单位 - 1].召唤数量[1] = 编号
