function 战斗处理类:添加召唤兽特性(编号)
	if self.参战单位[编号].特性 ~= nil then
		local 特性 = self.参战单位[编号].特性
		local 几率 = self.参战单位[编号].特性几率

		if 特性 == "预知" then
			self.参战单位[编号].预知特性 = 几率
			self.参战单位[编号].预知次数 = 0
			self.参战单位[编号].伤害 = qz(self.参战单位[编号].伤害 * 0.95)
			self.参战单位[编号].防御 = qz(self.参战单位[编号].防御 * 0.95)
			self.参战单位[编号].灵力 = qz(self.参战单位[编号].灵力 * 0.95)
			self.参战单位[编号].法伤 = qz(self.参战单位[编号].法伤 * 0.95)
			self.参战单位[编号].速度 = qz(self.参战单位[编号].速度 * 0.95)
			self.参战单位[编号].法防 = qz(self.参战单位[编号].法防 * 0.95)
		elseif 特性 == "灵动" then
			self.参战单位[编号].灵动特性 = 几率
			self.参战单位[编号].灵动次数 = 0
			self.参战单位[编号].伤害 = qz(self.参战单位[编号].伤害 * 0.95)
			self.参战单位[编号].防御 = qz(self.参战单位[编号].防御 * 0.95)
			self.参战单位[编号].灵力 = qz(self.参战单位[编号].灵力 * 0.95)
			self.参战单位[编号].法伤 = qz(self.参战单位[编号].法伤 * 0.95)
			self.参战单位[编号].速度 = qz(self.参战单位[编号].速度 * 0.95)
			self.参战单位[编号].法防 = qz(self.参战单位[编号].法防 * 0.95)
		elseif 特性 == "识物" then
			local 概率 = {
				5,
				8,
				10,
				13,
				16
			}
			local 降属性 = {
				0.92,
				0.92,
				0.96,
				0.96,
				0.96
			}
			self.参战单位[编号].识物特性 = 概率[几率]
			self.参战单位[编号].伤害 = qz(self.参战单位[编号].伤害 * 降属性[几率])
			self.参战单位[编号].防御 = qz(self.参战单位[编号].防御 * 降属性[几率])
			self.参战单位[编号].灵力 = qz(self.参战单位[编号].灵力 * 降属性[几率])
			self.参战单位[编号].法伤 = qz(self.参战单位[编号].法伤 * 降属性[几率])
			self.参战单位[编号].速度 = qz(self.参战单位[编号].速度 * 降属性[几率])
			self.参战单位[编号].法防 = qz(self.参战单位[编号].法防 * 降属性[几率])
		elseif 特性 == "抗法" then
			self.参战单位[编号].抗法特性 = 几率
		elseif 特性 == "抗物" then
			self.参战单位[编号].抗物特性 = 几率
		elseif 特性 == "洞察" then
			self.参战单位[编号].洞察特性 = 几率
			self.参战单位[编号].伤害 = qz(self.参战单位[编号].伤害 * 0.95)
			self.参战单位[编号].防御 = qz(self.参战单位[编号].防御 * 0.95)
			self.参战单位[编号].灵力 = qz(self.参战单位[编号].灵力 * 0.95)
			self.参战单位[编号].法伤 = qz(self.参战单位[编号].法伤 * 0.95)
			self.参战单位[编号].速度 = qz(self.参战单位[编号].速度 * 0.95)
			self.参战单位[编号].法防 = qz(self.参战单位[编号].法防 * 0.95)
		elseif 特性 == "弑神" then
			self.参战单位[编号].弑神特性 = 几率
		elseif 特性 == "顺势" then
			self.参战单位[编号].顺势特性 = 几率
		elseif 特性 == "复仇" then
			self.参战单位[编号].复仇特性 = 几率
			self.参战单位[编号].复仇次数 = 0
		elseif 特性 == "自恋" then
			self.参战单位[编号].自恋特性 = 几率
		elseif 特性 == "暗劲" then
			self.参战单位[编号].暗劲特性 = 几率
		elseif 特性 == "识药" then
			self.参战单位[编号].识药特性 = 几率
		elseif 特性 == "吮魔" then
			self.参战单位[编号].吮魔特性 = 几率
		elseif 特性 == "争锋" then
			self.参战单位[编号].争锋特性 = 几率
		elseif 特性 == "力破" then
			self.参战单位[编号].力破特性 = 几率
