		end
	end
end

function 战斗处理类:添加状态特性(编号)
	local 特性 = self.参战单位[编号].特性
	local 几率 = self.参战单位[编号].特性几率

	if 特性 == "御风" then
		self:添加状态(特性, self.参战单位[self.参战单位[编号].主人或助战 or self.参战单位[编号].主人], self.参战单位[编号], 0, 编号)
	elseif 特性 == "灵刃" then
		local 触发 = 0

		if 几率 == 1 then
			触发 = 33
		elseif 几率 == 2 then
			触发 = 50
		elseif 几率 == 3 then
			触发 = 66
		elseif 几率 == 4 then
			触发 = 83
		elseif 几率 == 5 then
			触发 = 100
		end

		if ygsj() <= 触发 then
			local 气血 = qz(self.参战单位[编号].气血 * 0.3)
			self.战斗流程[#self.战斗流程 + 1] = {
				气血 = 0,
				击退 = 1,
				流程 = 102,
				攻击方 = 编号,
				挨打方 = {}
			}
			local 精准战斗流程 = #self.战斗流程 + 0
			self.战斗流程[精准战斗流程].死亡 = self:减少气血(编号, 气血, nil, nil, nil, nil, 1)
			self.战斗流程[精准战斗流程].气血 = 气血

			self:添加状态("灵刃", self.参战单位[编号], self.参战单位[编号], 0, 编号)
		end
	elseif 特性 == "灵法" then
		self:添加状态("灵法", self.参战单位[编号], self.参战单位[编号], 几率, 编号)
		self:添加状态("灵法1", self.参战单位[编号], self.参战单位[编号], 几率, 编号)
	elseif 特性 == "阳护" then
		local 触发 = 0

		if 几率 == 1 then
			触发 = 33
		elseif 几率 == 2 then
			触发 = 50
		elseif 几率 == 3 then
			触发 = 66
		elseif 几率 == 4 then
			触发 = 83
		elseif 几率 == 5 then
			触发 = 100
		end

		if ygsj() <= 触发 then
			for i = 1, #self.参战单位 do
				if i ~= 编号 and self.参战单位[i] ~= nil and self.参战单位[i].队伍 == self.参战单位[编号].队伍 and self.参战单位[编号].法术状态.死亡召唤 then
					self.参战单位[编号].法术状态.死亡召唤.回合 = self.参战单位[编号].法术状态.死亡召唤.回合 - 2

					if self.参战单位[编号].法术状态.死亡召唤.回合 <= 0 then
						self.参战单位[编号].法术状态.死亡召唤.回合 = 1
					end
				end
			end
		end
	elseif 特性 == "护佑" then
		if 取随机数(1, 10) < 几率 then
			self:添加状态(特性, self.参战单位[self:取我方气血最低(编号)], self.参战单位[编号], 几率, 编号)
		end
	elseif 特性 == "怒吼" then
		if 取随机数(1, 10) < 几率 then
			self.参战单位[编号].防御 = qz(self.参战单位[编号].防御 * 0.9)

			self:添加状态(特性, self.参战单位[self:取我方伤害最高(编号)], self.参战单位[编号], 0, 编号)
			self:添加状态("怒吼1", self.参战单位[编号], self.参战单位[编号], 0, 编号)
		end
	elseif 特性 == "灵断" then
		local 触发 = 0

		if 几率 == 1 then
			触发 = 33
		elseif 几率 == 2 then
			触发 = 50
		elseif 几率 == 3 then
			触发 = 66
		elseif 几率 == 4 then
			触发 = 83
		elseif 几率 == 5 then
			触发 = 100
		end

		if ygsj() <= 触发 then
			local 气血 = qz(self.参战单位[编号].气血 * 0.3)
			self.战斗流程[#self.战斗流程 + 1] = {
				气血 = 0,
				击退 = 1,
				流程 = 102,
				攻击方 = 编号,
				挨打方 = {}
			}
			local 精准战斗流程 = #self.战斗流程 + 0
			self.战斗流程[精准战斗流程].死亡 = self:减少气血(编号, 气血, nil, nil, nil, nil, 1)
			self.战斗流程[精准战斗流程].气血 = 气血

			self:添加状态("灵断", self.参战单位[编号], self.参战单位[编号], 0, 编号)
		end
	elseif 特性 == "瞬击" then
		local 触发 = 0
		local 防御 = 10

		if 几率 == 1 then
			触发 = 33
		elseif 几率 == 2 then
			触发 = 50
		elseif 几率 == 3 then
			触发 = 66
			防御 = 5
		elseif 几率 == 4 then
			触发 = 83
			防御 = 5
		elseif 几率 == 5 then
			触发 = 100
			防御 = 5
		end

		if ygsj() <= 触发 then
			self.参战单位[编号].防御 = qz(self.参战单位[编号].防御 * (1 - 防御 / 100))
			self.参战单位[编号].指令.目标 = self:取单个敌方目标(编号)

			self:普通攻击计算(编号, 1)
		end
	elseif 特性 == "瞬法" then
		local 防御 = 10

		if 几率 == 1 then
			触发 = 33
		elseif 几率 == 2 then
			触发 = 50
		elseif 几率 == 3 then
			触发 = 66
			防御 = 5
		elseif 几率 == 4 then
			触发 = 83
			防御 = 5
		elseif 几率 == 5 then
			触发 = 100
			防御 = 5
		end

		local 名称 = self:取召唤兽可用法术(编号)

		if ygsj() <= 触发 and 名称 ~= nil then
			self.参战单位[编号].最大气血 = qz(self.参战单位[编号].最大气血 * (1 - 防御 / 100))

			if self.参战单位[编号].最大气血 < self.参战单位[编号].气血 then
				self.参战单位[编号].气血 = self.参战单位[编号].最大气血
			end

			self.参战单位[编号].指令.目标 = self:取单个敌方目标(编号)

			self:法攻技能计算(编号, 名称, self:取技能等级(编号, 名称), 1)
		end
	end
end

function 战斗处理类:取对方伤害最高(编号)
	local 目标组 = {}
	local 伤害 = {
		id = 0,
		伤害 = 0
	}

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 ~= self.参战单位[编号].队伍 and self:取目标状态(编号, n, 1) and 伤害.伤害 < self.参战单位[n].伤害 then
			伤害.伤害 = self.参战单位[n].伤害
			伤害.id = n
		end
	end

	if 伤害.id == 0 then
		return 编号
	else
		return 伤害.id
	end
end

function 战斗处理类:取对方气血百分比最低(编号)
	local 目标组 = {}
	local 伤害 = {
		id = 0,
		伤害 = 2
	}

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 ~= self.参战单位[编号].队伍 and self:取目标状态(编号, n, 1) and self.参战单位[n].气血 / self.参战单位[n].最大气血 < 伤害.伤害 then
			伤害.伤害 = self.参战单位[n].气血 / self.参战单位[n].最大气血
			伤害.id = n
		end
	end

	if 伤害.id == 0 then
		return 编号
	else
		return 伤害.id
	end
end

