function 战斗处理类:取我方可复活(编号, 只取鬼魂)
	local 目标组 = {}

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 == self.参战单位[编号].队伍 and self.参战单位[n].死亡状态 == 2 and self.参战单位[n].已复活 == nil and (只取鬼魂 == nil and self.参战单位[n].鬼魂 == nil or 只取鬼魂 ~= nil and self.参战单位[n].鬼魂 ~= nil) then
			目标组[#目标组 + 1] = n
		end
	end

	return 目标组
end

