	}

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 == self.参战单位[编号].队伍 and self:取目标状态(编号, n, 1) and self.参战单位[n].气血 < 伤害.伤害 then
			伤害.伤害 = self.参战单位[n].气血
			伤害.id = n
		end
	end

	if 伤害.id == 0 then
		return 编号
	else
		return 伤害.id
	end
end

function 战斗处理类:取召唤兽可用法术(编号)
	local 法术名称 = {
		天降灵葫 = 1,
		上古灵符 = 1,
		雷击 = 1,
		泰山压顶 = 1,
		食指大动 = 1,
		落岩 = 1,
		水漫金山 = 1,
		超级泰山压顶 = 1,
		地狱烈火 = 1,
		超级水漫金山 = 1,
		奔雷咒 = 1,
		水攻 = 1,
		叱咤风云 = 1,
		八凶法阵 = 1,
		月光 = 1,
		烈火 = 1,
		超级奔雷咒 = 1,
		流沙轻音 = 1,
		超级地狱烈火 = 1
	}
	local 技能组 = {}

	for n = 1, #self.参战单位[编号].主动技能 do
		if 法术名称[self.参战单位[编号].主动技能[n].名称] ~= nil then
			技能组[#技能组 + 1] = self.参战单位[编号].主动技能[n].名称
		end
	end

	if #技能组 == 0 then
		return
	else
		return 技能组[取随机数(1, #技能组)]
	end
end

