		难度系数[5] = 1
	end

	if 难度系数[6] == nil or 难度系数[1] == "空" or tonumber(难度系数[6]) == nil or 难度系数[1] == "" then
		难度系数[6] = 1
	end

	return 难度系数
end

function 战斗处理类:加载怪物通常属性(参战数据, 单位数据, 编号)
	参战数据.封印抵抗率 = 单位数据.封印抵抗率
	参战数据.封印命中率 = 单位数据.封印命中率
	参战数据.物伤减少 = 单位数据.物伤减少
	参战数据.法伤减少 = 单位数据.法伤减少
	参战数据.召唤减少 = 单位数据.召唤减少
	参战数据.角色减少 = 单位数据.角色减少
	参战数据.物伤免疫 = 单位数据.物伤免疫
	参战数据.法伤免疫 = 单位数据.法伤免疫
	参战数据.增伤百分比 = 单位数据.增伤百分比
	参战数据.受伤百分比 = 单位数据.受伤百分比
	参战数据.普攻躲避率 = 单位数据.普攻躲避率
	参战数据.不可封印 = 单位数据.不可封印
	参战数据.开场发言 = 单位数据.开场发言
	参战数据.门派 = 单位数据.门派 or "无门派"
	参战数据.奇经八脉 = 单位数据.奇经八脉 or {}
	参战数据.附加状态 = 单位数据.附加状态 or {}
	参战数据.追加法术 = 单位数据.追加法术 or {}
	参战数据.武器伤害 = 单位数据.武器伤害 or 0
	参战数据.法宝佩戴 = 单位数据.法宝 or {}

	if 单位数据.五维属性 ~= nil then
		参战数据.体质 = 单位数据.五维属性.体质 or 0
		参战数据.魔力 = 单位数据.五维属性.魔力 or 0
		参战数据.力量 = 单位数据.五维属性.力量 or 0
		参战数据.耐力 = 单位数据.五维属性.耐力 or 0
		参战数据.敏捷 = 单位数据.五维属性.敏捷 or 0
	end

	参战数据.攻击修炼 = 单位数据.攻击修炼 or 0
	参战数据.法术修炼 = 单位数据.法术修炼 or 0
	参战数据.防御修炼 = 单位数据.防御修炼 or 0
	参战数据.抗法修炼 = 单位数据.抗法修炼 or 0
	参战数据.怪物修炼 = {
		攻击修炼 = 单位数据.攻击修炼,
		防御修炼 = 单位数据.防御修炼,
		法术修炼 = 单位数据.法术修炼,
		抗法修炼 = 单位数据.抗法修炼
	}
	参战数据.内丹数据 = 单位数据.内丹数据
	参战数据.指定攻击目标 = 单位数据.指定攻击目标
	参战数据.不攻击 = 单位数据.不攻击
	参战数据.无需变身 = 单位数据.无需变身
	参战数据.特殊标记 = 单位数据.特殊标记
	参战数据.饰品 = 单位数据.显示饰品
	参战数据.召唤物 = 单位数据.召唤物
	参战数据.召唤主人 = 单位数据.召唤主人

	if 单位数据.发言 ~= nil then
		self.战斗发言数据[#self.战斗发言数据 + 1] = {
			id = 编号,
			内容 = 单位数据.发言
		}
	end
end

function 战斗处理类:加载指定单位(单位组, 任务id)
	local 难度系数 = self:取难度系数(任务id)
	local 临时气血 = 难度系数[1]
	local 临时伤害 = 难度系数[2]
	local 临时防御 = 难度系数[3]
	local 临时灵力 = 难度系数[4]
	local 临时速度 = 难度系数[5]
	local 临时法防 = 难度系数[6]

	for n = 1, #单位组 do
		self.参战单位[#self.参战单位 + 1] = {}
		self.参战单位[#self.参战单位].名称 = 单位组[n].名称
		self.参战单位[#self.参战单位].模型 = 单位组[n].模型
		self.参战单位[#self.参战单位].等级 = 单位组[n].等级
		self.参战单位[#self.参战单位].变异 = 单位组[n].变异
		self.参战单位[#self.参战单位].捉鬼变异 = 单位组[n].捉鬼变异
		self.参战单位[#self.参战单位].队伍 = 0
		self.参战单位[#self.参战单位].位置 = 单位组[n].位置 or n
		self.参战单位[#self.参战单位].真实编号 = #self.参战单位
		self.参战单位[#self.参战单位].类型 = 单位组[n].类型 or "bb"
		self.参战单位[#self.参战单位].武器 = 单位组[n].武器
		self.参战单位[#self.参战单位].染色方案 = 单位组[n].染色方案
		self.参战单位[#self.参战单位].染色组 = 单位组[n].染色组
		self.参战单位[#self.参战单位].锦衣 = 单位组[n].锦衣
		self.参战单位[#self.参战单位].武器染色方案 = 单位组[n].武器染色方案
		self.参战单位[#self.参战单位].武器染色组 = 单位组[n].武器染色组
		self.参战单位[#self.参战单位].行走开关 = 单位组[n].行走开关
		self.参战单位[#self.参战单位].玩家id = 0
		self.参战单位[#self.参战单位].分类 = "野怪"
		self.参战单位[#self.参战单位].附加阵法 = 单位组[1].附加阵法 or "普通"
		self.参战单位[#self.参战单位].伤害 = 单位组[n].伤害 * 服务端参数.难度 * 临时伤害
		self.参战单位[#self.参战单位].命中 = 单位组[n].伤害 * 服务端参数.难度
		self.参战单位[#self.参战单位].防御 = 单位组[n].防御 * 服务端参数.难度 * 临时防御
		self.参战单位[#self.参战单位].速度 = 单位组[n].速度 * 服务端参数.难度 * 临时速度
		self.参战单位[#self.参战单位].灵力 = 单位组[n].灵力 * 服务端参数.难度 * 临时灵力

		if 单位组[n].法伤 == nil then
			self.参战单位[#self.参战单位].法伤 = self.参战单位[#self.参战单位].灵力
		else
			self.参战单位[#self.参战单位].法伤 = 单位组[n].法伤 * 服务端参数.难度 * 临时法伤
		end

		self.参战单位[#self.参战单位].灵伤差 = self.参战单位[#self.参战单位].法伤 - self.参战单位[#self.参战单位].灵力

		if 单位组[n].法防 == nil then
			self.参战单位[#self.参战单位].法防 = self.参战单位[#self.参战单位].灵力
		else
			self.参战单位[#self.参战单位].法防 = 单位组[n].法防 * 服务端参数.难度 * 临时法防
		end

		self.参战单位[#self.参战单位].躲避 = 单位组[n].躲避 * 服务端参数.难度
		self.参战单位[#self.参战单位].气血 = math.floor(单位组[n].气血 * 服务端参数.难度 * 临时气血)
		self.参战单位[#self.参战单位].最大气血 = math.floor(单位组[n].气血 * 服务端参数.难度 * 临时气血)
		self.参战单位[#self.参战单位].魔法 = 单位组[n].魔法
		self.参战单位[#self.参战单位].愤怒 = 单位组[n].愤怒 or 0
		self.参战单位[#self.参战单位].最大魔法 = 单位组[n].魔法
		self.参战单位[#self.参战单位].技能 = 单位组[n].技能

		self:加载单位通用属性(#self.参战单位 + 0, 3)
		self:加载怪物通常属性(self.参战单位[#self.参战单位], 单位组[n], #self.参战单位)

		if self.参战单位[#self.参战单位].捉鬼变异 then
			self.战斗发言数据[#self.战斗发言数据 + 1] = {
				内容 = "其实我内心是很善良得，你们可千万不要错杀好鬼呀#52",
				id = #self.参战单位
			}
		elseif self.参战单位[#self.参战单位].开场发言 ~= nil then
			self.战斗发言数据[#self.战斗发言数据 + 1] = {
				id = #self.参战单位,
				内容 = self.参战单位[#self.参战单位].开场发言
			}
		end

		if self.参战单位[#self.参战单位].名称 == "灵感分身" then
			self.战斗发言数据[#self.战斗发言数据 + 1] = {
				内容 = "别以为你们人多，看我分身大法",
				id = #self.参战单位
			}
		end

		if 单位组[n].角色 then
			self.参战单位[#self.参战单位].类型 = "系统角色"
		end

		if 单位组[n].角色分类 == "角色" then
			self.参战单位[#self.参战单位].类型 = "系统PK角色"
		end

		if 单位组.阵法 ~= nil then
			self.参战单位[#self.参战单位].附加阵法 = 单位组.阵法
		else
			self.参战单位[#self.参战单位].附加阵法 = "普通"
		end

		if self.战斗类型 == 100005 then
			if 单位组[n].变异 then
				self.参战单位[#self.参战单位].分类 = "变异"
			else
				self.参战单位[#self.参战单位].分类 = "宝宝"
			end
		elseif self.战斗类型 == 100018 then
			self.参战单位[#self.参战单位].乾坤袋 = true
		end

		if 单位组[n].主动技能 ~= nil and not 判断是否为空表(单位组[n].主动技能) then
			for i = 1, #单位组[n].主动技能 do
				self.参战单位[#self.参战单位].主动技能[i] = {
					名称 = 单位组[n].主动技能[i],
					等级 = 单位组[n].等级 + 10
				}
			end
		end

		self:设置队伍区分(0)
	end
end

function 战斗处理类:取阵法克制(攻击方, 挨打方)
	local 攻击阵法 = self.参战单位[攻击方].附加阵法
	local 挨打阵法 = self.参战单位[挨打方].附加阵法
	local 阵法克制 = 0

	if 挨打阵法 == "普通" then
		if 攻击阵法 == "普通" then
			阵法克制 = 0
		elseif 攻击阵法 == "天覆阵" then
			阵法克制 = 0.05
		elseif 攻击阵法 == "地载阵" then
			阵法克制 = -0.05
		elseif 攻击阵法 == "风扬阵" then
			阵法克制 = 0.05
		elseif 攻击阵法 == "云垂阵" then
			阵法克制 = -0.05
		elseif 攻击阵法 == "龙飞阵" then
			阵法克制 = 0.05
		elseif 攻击阵法 == "虎翼阵" then
			阵法克制 = -0.05
		elseif 攻击阵法 == "鸟翔阵" then
			阵法克制 = 0.05
		elseif 攻击阵法 == "蛇蟠阵" then
			阵法克制 = -0.05
		elseif 攻击阵法 == "鹰啸阵" then
			阵法克制 = 0.05
		elseif 攻击阵法 == "雷绝阵" then
			阵法克制 = -0.05
		end
	elseif 挨打阵法 == "天覆阵" then
		if 攻击阵法 == "普通" then
			阵法克制 = -0.05
		elseif 攻击阵法 == "天覆阵" then
			阵法克制 = 0
		elseif 攻击阵法 == "地载阵" then
			阵法克制 = -0.1
		elseif 攻击阵法 == "风扬阵" then
			阵法克制 = 0.1
		elseif 攻击阵法 == "云垂阵" then
			阵法克制 = 0.05
		elseif 攻击阵法 == "龙飞阵" then
			阵法克制 = -0.1
		elseif 攻击阵法 == "虎翼阵" then
			阵法克制 = 0.05
		elseif 攻击阵法 == "鸟翔阵" then
			阵法克制 = -0.05
		elseif 攻击阵法 == "蛇蟠阵" then
			阵法克制 = 0.1
		elseif 攻击阵法 == "鹰啸阵" then
			阵法克制 = -0.05
		elseif 攻击阵法 == "雷绝阵" then
			阵法克制 = 0.05
		end
	elseif 挨打阵法 == "地载阵" then
		if 攻击阵法 == "普通" then
			阵法克制 = 0.05
		elseif 攻击阵法 == "天覆阵" then
			阵法克制 = 0.1
