function 战斗处理类:加载野外单位()
	local 加载数量 = 0

	if 玩家数据[self.发起id].队伍 == 0 then
		加载数量 = 取随机数(2, 3)
	else
		local 队伍数量 = #队伍数据[玩家数据[self.发起id].队伍].成员数据
		加载数量 = 取随机数(队伍数量 + 1, 队伍数量 * 2 + 1)

		if 加载数量 > 10 then
			加载数量 = 10
		end
	end

	local 临时信息 = 取野怪(self.战斗地图, qz(self.天气))
	local 队伍id = 0
	local 临时等级 = 0
	local 临时等级1 = 0
	临时等级, 临时等级1 = 取场景等级(self.战斗地图)
	self.等级上限 = 临时等级1
	self.等级下限 = 临时等级
	self.地图等级 = qz((self.等级下限 + self.等级上限) / 2)
	self.精灵数量 = 0
	self.头领数量 = 0
	self.敌人数量 = 加载数量
	local 任务id = 玩家数据[self.发起id].角色:取任务(13)
	local 修炼任务bb = nil

	if 任务id ~= 0 and 任务数据[任务id] ~= nil and 任务数据[任务id].bb ~= nil and (任务数据[任务id].bb次数 or 0) < 10 and 临时等级 <= 玩家数据[self.发起id].角色.数据.等级 and 玩家数据[self.发起id].角色.数据.等级 <= 临时等级1 and 取随机数(1, 10000) <= 传说遇变异几率 * 100 * (1 - (任务数据[任务id].bb次数 or 0) / 10) then
		任务数据[任务id].bb次数 = (任务数据[任务id].bb次数 or 0) + 1
		修炼任务bb = 任务数据[任务id].bb
	end

	local 特殊野怪数量 = {}
	local 临时野怪编号 = nil

	for n = 1, 加载数量 do
		local 通过 = false

		while not 通过 do
			临时野怪编号 = 临时信息[取随机数(1, #临时信息)]

			if 天气野怪[临时野怪编号] ~= nil and ygsj() > 10 then
				临时野怪编号 = 临时信息[取随机数(1, #临时信息)]

				if 天气野怪[临时野怪编号] ~= nil and ygsj() > 5 then
					临时野怪编号 = 临时信息[取随机数(1, #临时信息)]
				end

				通过 = true
			elseif 特殊野怪1[math.abs(临时野怪编号)] ~= nil then
				if 特殊野怪数量[math.abs(临时野怪编号)] == nil then
					特殊野怪数量[math.abs(临时野怪编号)] = 0
				end

				if 特殊野怪数量[math.abs(临时野怪编号)] < 1 then
					特殊野怪数量[math.abs(临时野怪编号)] = 特殊野怪数量[math.abs(临时野怪编号)] + 1
					通过 = true
				elseif 特殊野怪数量[math.abs(临时野怪编号)] < 特殊野怪1[math.abs(临时野怪编号)] and ygsj() <= 50 then
					特殊野怪数量[math.abs(临时野怪编号)] = 特殊野怪数量[math.abs(临时野怪编号)] + 1
					通过 = true
				end
			else
				通过 = true
			end
		end

		local 临时野怪 = 取敌人信息(临时野怪编号)
		self.地图等级 = 取随机数(self.等级上限 - 5, self.等级上限)
		self.生成等级 = self.地图等级
		self.临时等级 = 取随机数(self.等级下限, self.等级上限)
		local 变异 = false

		if 取随机数(1, 10000) <= 野外变异概率 then
			变异 = true
		end

		local 宝宝 = false

		if 取随机数(1, 10000) <= 野外宝宝概率 then
			宝宝 = true
		end

		local 特殊怪 = 取特殊野怪()

		if 特殊怪 ~= nil then
			临时野怪 = 取敌人信息(特殊怪)

			if not 变异 then
				宝宝 = (not 宝宝 or false) and true
			end
		end

		if 变异 or 宝宝 then
			self.临时等级 = 1
			self.生成等级 = 1
		end

		self.参战单位[#self.参战单位 + 1] = {}
		self.参战单位[#self.参战单位].名称 = 临时野怪[2]

		if 变异 then
			self.参战单位[#self.参战单位].名称 = "变异" .. 临时野怪[2]
		end

		self.参战单位[#self.参战单位].模型 = 临时野怪[2]

		if 修炼任务bb ~= nil and n == 1 then
			self.参战单位[#self.参战单位].名称 = "变异" .. 修炼任务bb
			self.参战单位[#self.参战单位].模型 = 修炼任务bb
			变异 = true
			self.临时等级 = 1
			self.生成等级 = 0
		end

		self.参战单位[#self.参战单位].等级 = self.临时等级
		self.参战单位[#self.参战单位].参战等级 = 临时野怪[3]
		self.参战单位[#self.参战单位].队伍 = 队伍id
		self.参战单位[#self.参战单位].位置 = n
		self.参战单位[#self.参战单位].变异 = 变异
		self.参战单位[#self.参战单位].类型 = "bb"
		self.参战单位[#self.参战单位].玩家id = 0
		self.参战单位[#self.参战单位].分类 = "野怪"
		self.参战单位[#self.参战单位].附加阵法 = "普通"
		self.参战单位[#self.参战单位].伤害 = math.floor((self.生成等级 + 1) * 6.8)
		self.参战单位[#self.参战单位].命中 = self.参战单位[#self.参战单位].伤害
		self.参战单位[#self.参战单位].防御 = math.floor((self.生成等级 + 1) * 0.5)
		self.参战单位[#self.参战单位].速度 = math.floor((self.生成等级 + 1) * 1.5)
		self.参战单位[#self.参战单位].灵力 = math.floor((self.生成等级 + 1) * 4.85)
		self.参战单位[#self.参战单位].法防 = self.参战单位[#self.参战单位].灵力 / 2
		self.参战单位[#self.参战单位].法伤 = self.参战单位[#self.参战单位].灵力
		self.参战单位[#self.参战单位].灵伤差 = self.参战单位[#self.参战单位].法伤 - self.参战单位[#self.参战单位].灵力
		self.参战单位[#self.参战单位].躲避 = math.floor((self.生成等级 + 1) * 1.5)
		self.参战单位[#self.参战单位].气血 = math.floor((self.生成等级 + 1) * 17.5) + 10
		self.参战单位[#self.参战单位].最大气血 = math.floor((self.生成等级 + 1) * 17.5) + 10
		self.参战单位[#self.参战单位].魔法 = math.floor((self.生成等级 + 1) * 7.5) + 10
		self.参战单位[#self.参战单位].最大魔法 = math.floor((self.生成等级 + 1) * 7.5) + 10
		self.参战单位[#self.参战单位].魔力 = self.参战单位[#self.参战单位].参战等级 * 2
		self.参战单位[#self.参战单位].技能 = {}

		if 变异 then
			self.参战单位[#self.参战单位].分类 = "变异"

			if 修炼任务bb == nil then
				self.战斗发言数据[#self.战斗发言数据 + 1] = {
					内容 = "诶啊..我..我..我什么变态了,不对是换色了,你们别抓我呀!#52",
					id = #self.参战单位
				}
			else
				self.战斗发言数据[#self.战斗发言数据 + 1] = {
					id = #self.参战单位,
					内容 = "我就是传说中的#R变异" .. 修炼任务bb .. "#G你们别抓我呀!#52"
				}
			end
		elseif 宝宝 then
			self.参战单位[#self.参战单位].分类 = "宝宝"
			self.参战单位[#self.参战单位].名称 = self.参战单位[#self.参战单位].模型 .. "宝宝"
			self.战斗发言数据[#self.战斗发言数据 + 1] = {
				内容 = "其实我一个小小的宝宝,你们别抓我呀!#52",
				id = #self.参战单位
			}
		end

		local 临时技能 = 临时野怪[14]
		self.参战单位[#self.参战单位].技能 = 取洗宠技能(临时野怪[2], nil, 临时技能)

		if self.精灵数量 == 0 and ygsj() <= 3 then
			self.精灵数量 = 1
			self.参战单位[#self.参战单位].精灵 = true
			self.参战单位[#self.参战单位].不可封印 = true
			self.参战单位[#self.参战单位].技能 = {
				"自爆"
			}
			self.参战单位[#self.参战单位].气血 = self.参战单位[#self.参战单位].气血 * 3
			self.参战单位[#self.参战单位].名称 = self.参战单位[#self.参战单位].模型 .. "精灵"
			self.参战单位[#self.参战单位].速度 = 0
			self.战斗发言数据[#self.战斗发言数据 + 1] = {
				内容 = "我是一只小精灵,小啊小精灵!#52",
				id = #self.参战单位
			}
		elseif 变异 == false and 宝宝 == false and ygsj() <= 20 then
			self.参战单位[#self.参战单位].名称 = self.参战单位[#self.参战单位].模型 .. "头领"
			self.头领数量 = self.头领数量 + 1
			self.参战单位[#self.参战单位].气血 = qz(self.参战单位[#self.参战单位].气血 * 1.25)
			self.参战单位[#self.参战单位].防御 = qz(self.参战单位[#self.参战单位].防御 * 1.2)
			self.参战单位[#self.参战单位].伤害 = qz(self.参战单位[#self.参战单位].伤害 * 1.25)
			self.参战单位[#self.参战单位].灵力 = qz(self.参战单位[#self.参战单位].灵力 * 1.25)
			self.参战单位[#self.参战单位].法防 = qz(self.参战单位[#self.参战单位].法防 * 1.25)
			self.参战单位[#self.参战单位].法伤 = qz(self.参战单位[#self.参战单位].法伤 * 1.25)
		end

		self.参战单位[#self.参战单位].最大气血 = self.参战单位[#self.参战单位].气血 + 0
		self.参战单位[#self.参战单位].攻击五行 = 五行固定召唤兽[self.参战单位[#self.参战单位].模型] or 取五行()
		self.参战单位[#self.参战单位].防御五行 = self.参战单位[#self.参战单位].攻击五行

		self:加载单位通用属性(#self.参战单位 + 0)
		self:设置队伍区分(队伍id)
	end
end

function 战斗处理类:加载野外单位1()
	local 加载数量 = 0

	if 玩家数据[self.发起id].队伍 == 0 then
		加载数量 = 取随机数(2, 3)
	else
		local 队伍数量 = #队伍数据[玩家数据[self.发起id].队伍].成员数据
		加载数量 = 取随机数(队伍数量 + 1, 队伍数量 * 2 + 1)

		if 加载数量 > 10 then
			加载数量 = 10
		end
	end

	local 临时信息 = 取野怪(self.战斗地图, qz(self.天气))
	local 队伍id = 0
	local 临时等级 = 0
	local 临时等级1 = 0
	临时等级, 临时等级1 = 取场景等级(self.战斗地图)
	self.等级上限 = 临时等级1
	self.等级下限 = 临时等级
	self.地图等级 = qz((self.等级下限 + self.等级上限) / 2)
	self.精灵数量 = 0
	self.头领数量 = 0
	self.敌人数量 = 加载数量
	local 特殊野怪数量 = {}
	local 临时野怪编号 = nil

	for n = 1, 加载数量 do
		local 通过 = false

		while not 通过 do
			临时野怪编号 = 临时信息[取随机数(1, #临时信息)]

			if 天气野怪[临时野怪编号] ~= nil and ygsj() > 10 then
				临时野怪编号 = 临时信息[取随机数(1, #临时信息)]

				if 天气野怪[临时野怪编号] ~= nil and ygsj() > 5 then
					临时野怪编号 = 临时信息[取随机数(1, #临时信息)]
				end

				通过 = true
			elseif 特殊野怪1[math.abs(临时野怪编号)] ~= nil then
				if 特殊野怪数量[math.abs(临时野怪编号)] == nil then
					特殊野怪数量[math.abs(临时野怪编号)] = 0
				end

				if 特殊野怪数量[math.abs(临时野怪编号)] < 1 then
					特殊野怪数量[math.abs(临时野怪编号)] = 特殊野怪数量[math.abs(临时野怪编号)] + 1
					通过 = true
				elseif 特殊野怪数量[math.abs(临时野怪编号)] < 特殊野怪1[math.abs(临时野怪编号)] and ygsj() <= 50 then
					特殊野怪数量[math.abs(临时野怪编号)] = 特殊野怪数量[math.abs(临时野怪编号)] + 1
					通过 = true
				end
			else
				通过 = true
			end
		end

		local 临时野怪 = 取敌人信息(临时野怪编号)

		if n == 1 then
			for i = 1, #临时信息 do
				local 序列数据 = 取敌人信息(临时信息[i])

				if 序列数据[2] == 任务数据[self.任务id].模型 then
					临时野怪 = 取敌人信息(临时信息[i])
				end
			end
		end

		self.地图等级 = 取随机数(self.等级上限 - 5, self.等级上限)
		self.生成等级 = self.地图等级
		self.临时等级 = 取随机数(self.等级下限, self.等级上限)
		local 变异 = false

		if 取随机数(1, 10000) <= 野外变异概率 then
			变异 = true
		end

		local 宝宝 = false

		if 取随机数(1, 10000) <= 野外宝宝概率 then
			宝宝 = true
		end

		local 特殊怪 = 取特殊野怪()

		if n > 1 and 特殊怪 ~= nil then
			临时野怪 = 取敌人信息(特殊怪)

			if not 变异 then
				宝宝 = (not 宝宝 or false) and true
			end
		end

		if 变异 or 宝宝 then
			self.临时等级 = 1
			self.生成等级 = 1
		end

		self.参战单位[#self.参战单位 + 1] = {}
		self.参战单位[#self.参战单位].名称 = 临时野怪[2]

		if 变异 then
			self.参战单位[#self.参战单位].名称 = "变异" .. 临时野怪[2]
		end

		self.参战单位[#self.参战单位].模型 = 临时野怪[2]
		self.参战单位[#self.参战单位].等级 = self.临时等级
		self.参战单位[#self.参战单位].队伍 = 队伍id
		self.参战单位[#self.参战单位].位置 = n
		self.参战单位[#self.参战单位].变异 = 变异
		self.参战单位[#self.参战单位].类型 = "bb"
		self.参战单位[#self.参战单位].玩家id = 0
		self.参战单位[#self.参战单位].分类 = "野怪"
		self.参战单位[#self.参战单位].附加阵法 = "普通"
		self.参战单位[#self.参战单位].伤害 = math.floor((self.生成等级 + 1) * 6.8)
		self.参战单位[#self.参战单位].命中 = self.参战单位[#self.参战单位].伤害
		self.参战单位[#self.参战单位].防御 = math.floor((self.生成等级 + 1) * 0.5)
		self.参战单位[#self.参战单位].速度 = math.floor((self.生成等级 + 1) * 1.5)
		self.参战单位[#self.参战单位].灵力 = math.floor((self.生成等级 + 1) * 4.85)
		self.参战单位[#self.参战单位].法防 = self.参战单位[#self.参战单位].灵力 / 2
		self.参战单位[#self.参战单位].法伤 = self.参战单位[#self.参战单位].灵力
		self.参战单位[#self.参战单位].灵伤差 = self.参战单位[#self.参战单位].法伤 - self.参战单位[#self.参战单位].灵力
		self.参战单位[#self.参战单位].躲避 = math.floor((self.生成等级 + 1) * 1.5)
		self.参战单位[#self.参战单位].气血 = math.floor((self.生成等级 + 1) * 17.5) + 10
		self.参战单位[#self.参战单位].最大气血 = math.floor((self.生成等级 + 1) * 17.5) + 10
		self.参战单位[#self.参战单位].魔法 = math.floor((self.生成等级 + 1) * 7.5) + 10
		self.参战单位[#self.参战单位].最大魔法 = math.floor(self.生成等级 * 7.5) + 10
		self.参战单位[#self.参战单位].技能 = {}
		self.参战单位[#self.参战单位].魔力 = self.临时等级 * 2

		if 变异 then
			self.参战单位[#self.参战单位].分类 = "变异"
			self.战斗发言数据[#self.战斗发言数据 + 1] = {
				内容 = "诶啊..我..我..我什么变态了,不对是换色了,你们别抓我呀!#52",
				id = #self.参战单位
			}
		elseif 宝宝 then
			self.参战单位[#self.参战单位].分类 = "宝宝"
			self.参战单位[#self.参战单位].名称 = self.参战单位[#self.参战单位].模型 .. "宝宝"
			self.战斗发言数据[#self.战斗发言数据 + 1] = {
				内容 = "其实我一个小小的宝宝,你们别抓我呀!#52",
				id = #self.参战单位
			}
		end

		local 临时技能 = 临时野怪[14]
		self.参战单位[#self.参战单位].技能 = 取洗宠技能(临时野怪[2], nil, 临时技能)

		if self.精灵数量 == 0 and ygsj() <= 3 then
			self.精灵数量 = 1
			self.参战单位[#self.参战单位].精灵 = true
			self.参战单位[#self.参战单位].不可封印 = true
			self.参战单位[#self.参战单位].技能 = {
				"自爆"
			}
			self.参战单位[#self.参战单位].气血 = self.参战单位[#self.参战单位].气血 * 3
			self.参战单位[#self.参战单位].名称 = self.参战单位[#self.参战单位].模型 .. "精灵"
			self.参战单位[#self.参战单位].速度 = 0
			self.战斗发言数据[#self.战斗发言数据 + 1] = {
				内容 = "我是一只小精灵,小啊小精灵!#52",
				id = #self.参战单位
			}
		elseif 变异 == false and 宝宝 == false and ygsj() <= 20 then
			self.参战单位[#self.参战单位].名称 = self.参战单位[#self.参战单位].模型 .. "头领"
			self.头领数量 = self.头领数量 + 1
			self.参战单位[#self.参战单位].气血 = qz(self.参战单位[#self.参战单位].气血 * 1.25)
			self.参战单位[#self.参战单位].防御 = qz(self.参战单位[#self.参战单位].防御 * 1.2)
			self.参战单位[#self.参战单位].伤害 = qz(self.参战单位[#self.参战单位].伤害 * 1.25)
			self.参战单位[#self.参战单位].灵力 = qz(self.参战单位[#self.参战单位].灵力 * 1.25)
			self.参战单位[#self.参战单位].法防 = qz(self.参战单位[#self.参战单位].法防 * 1.25)
			self.参战单位[#self.参战单位].法伤 = qz(self.参战单位[#self.参战单位].法伤 * 1.25)
		end

		self.参战单位[#self.参战单位].最大气血 = self.参战单位[#self.参战单位].气血 + 0
		self.参战单位[#self.参战单位].攻击五行 = 五行固定召唤兽[self.参战单位[#self.参战单位].模型] or 取五行()
		self.参战单位[#self.参战单位].防御五行 = self.参战单位[#self.参战单位].攻击五行

		self:加载单位通用属性(#self.参战单位 + 0)
		self:设置队伍区分(队伍id)
	end
end

function 战斗处理类:添加内丹属性(单位, 内丹1)
	if 单位.灵力 == nil then
		单位.灵力 = 0
	end

	if 单位.法伤 == nil then
		单位.法伤 = 单位.灵力 or 0
	end

	if 单位.法防 == nil then
		单位.法防 = 单位.灵力 or 0
	end

	local 内丹 = {}

	for n = 1, #内丹1 do
		内丹[n] = 内丹1[n]
	end

	for i = 1, #内丹 do
		local 等级 = 内丹[i].等级
		local 技能 = 内丹[i].技能

		if 技能 == "深思" and (self:取技能重复(单位, "高级冥思") ~= false or self:取技能重复(单位, "冥思") ~= false) then
			单位.冥思 = 等级 * 5 + (单位.冥思 or 0)
		end

		if 技能 == "淬毒" and (self:取技能重复(单位, "毒") ~= false or self:取技能重复(单位, "高级毒") ~= false) then
			单位.毒 = (单位.毒 or 0) + 5 * 等级
		end

		if 技能 == "连环" and (self:取技能重复(单位, "连击") ~= false or self:取技能重复(单位, "高级连击") ~= false or self:取技能重复(单位, "超级连击") ~= false) then
			单位.连击 = (单位.连击 or 0) + 2 * 等级
		end

		if 技能 == "圣洁" and (self:取技能重复(单位, "驱鬼") ~= false or self:取技能重复(单位, "高级驱鬼") ~= false or self:取技能重复(单位, "超级驱鬼") ~= false) then
			单位.驱鬼 = math.floor(等级 * 10 / 100) + (单位.驱鬼 or 0)
		end

		if 技能 == "狂怒" then
			if 等级 == 1 then
				单位.狂怒 = 80
			elseif 等级 == 2 then
				单位.狂怒 = 100
			elseif 等级 == 3 then
				单位.狂怒 = 120
			elseif 等级 == 4 then
				单位.狂怒 = 140
			elseif 等级 == 5 then
				单位.狂怒 = 160
			end
		end

		if 技能 == "阴伤" then
			if 等级 == 1 then
				单位.阴伤 = 50
			elseif 等级 == 2 then
				单位.阴伤 = 60
			elseif 等级 == 3 then
				单位.阴伤 = 70
			elseif 等级 == 4 then
				单位.阴伤 = 80
			elseif 等级 == 5 then
				单位.阴伤 = 90
			end
		end

		if 技能 == "撞击" then
			单位.撞击 = 等级
		end

		if 技能 == "钢化" then
			if self:取技能重复(单位, "防御") or self:取技能重复(单位, "高级防御") then
				单位.防御 = math.floor(单位.防御 + 单位.等级 * 0.2 * 等级)
			end

			单位.钢化 = 1
		end

		if 技能 == "玄武躯" then
			单位.玄武躯 = 1
		end

		if 技能 == "龙胄铠" then
			单位.龙胄铠 = 1
		end

		if 技能 == "擅咒" then
			单位.法术伤害结果 = (单位.法术伤害结果 or 0) + qz1(12 * 等级)
		end

		if 技能 == "狙刺" then
			单位.灵力 = 单位.灵力 + math.floor(单位.等级 * 0.15) * 等级
			单位.法伤 = 单位.法伤 + math.floor(单位.等级 * 0.15) * 等级
		end

		if 技能 == "碎甲刃" then
			单位.碎甲刃 = 等级
		end

		if 技能 == "舍身击" then
			单位.舍身击 = 等级
		end

		if 技能 == "生死决" then
			单位.狂暴概率 = (单位.狂暴概率 or 0) + qz1((0.03 + 0.0075 * 等级) * 200)
		end

		if 技能 == "催心浪" and 单位.法波 ~= nil and 单位.法波 ~= 0 then
			单位.法波下 = 单位.法波下 + 等级 * 3
			单位.法波 = 单位.法波 + 10
		end

		if 技能 == "隐匿击" then
			单位.隐匿击 = 等级
		end

		if 技能 == "灵身" then
			if 等级 == 1 then
				单位.灵身 = 1
			elseif 等级 == 2 then
				单位.灵身 = 2
			elseif 等级 == 3 then
				单位.灵身 = 3
			elseif 等级 == 4 then
				单位.灵身 = 4
			elseif 等级 == 5 then
				单位.灵身 = 5
			end
		end

		if 技能 == "血债偿" then
			单位.血债偿 = (单位.魔力 - 单位.等级) * 0.04 * 等级
		end

		if 技能 == "通灵法" then
			if 等级 == 1 then
				单位.通灵法 = 1
			elseif 等级 == 2 then
				单位.通灵法 = 2
			elseif 等级 == 3 then
				单位.通灵法 = 3
			elseif 等级 == 4 then
				单位.通灵法 = 4
			elseif 等级 == 5 then
				单位.通灵法 = 5
			end
		end

		if 技能 == "慧心" then
			if 等级 == 1 then
				单位.慧心 = 1
			elseif 等级 == 2 then
				单位.慧心 = 2
			elseif 等级 == 3 then
				单位.慧心 = 3
			elseif 等级 == 4 then
				单位.慧心 = 4
			elseif 等级 == 5 then
				单位.慧心 = 5
			end
		end

		if 技能 == "无畏" then
			if 等级 == 1 then
				单位.无畏 = 1.02
			elseif 等级 == 2 then
				单位.无畏 = 1.04
			elseif 等级 == 3 then
				单位.无畏 = 1.06
			elseif 等级 == 4 then
				单位.无畏 = 1.08
			elseif 等级 == 5 then
				单位.无畏 = 1.1
			end
		end

		if 技能 == "愤恨" then
			if 等级 == 1 then
				单位.愤恨 = 1.02
			elseif 等级 == 2 then
				单位.愤恨 = 1.04
			elseif 等级 == 3 then
				单位.愤恨 = 1.06
			elseif 等级 == 4 then
				单位.愤恨 = 1.08
			elseif 等级 == 5 then
				单位.愤恨 = 1.1
			end
		end

		if 技能 == "玉砥柱" then
			if 等级 == 1 then
				单位.玉砥柱 = 0.07
			elseif 等级 == 2 then
				单位.玉砥柱 = 0.14
			elseif 等级 == 3 then
				单位.玉砥柱 = 0.21
			elseif 等级 == 4 then
				单位.玉砥柱 = 0.28
			elseif 等级 == 5 then
				单位.玉砥柱 = 0.35
			end
		end

		if 技能 == "双星爆" then
			if 等级 == 1 then
				单位.双星爆 = 0.1
			elseif 等级 == 2 then
				单位.双星爆 = 0.2
			elseif 等级 == 3 then
				单位.双星爆 = 0.3
			elseif 等级 == 4 then
				单位.双星爆 = 0.4
			elseif 等级 == 5 then
				单位.双星爆 = 0.5
			end
		end

		if 技能 == "坚甲" and (self:取技能重复(单位, "高级反震") ~= false or self:取技能重复(单位, "反震") ~= false) then
			单位.反震1 = 100 * 等级
		end
	end
end

function 战斗处理类:添加护符技能属性(单位, 技能组)
	self:添加技能属性(单位, 技能组)
end

function 战斗处理类:添加认证法术属性(单位, 技能组)
	for n = 1, #技能组 do
		local 名称 = 技能组[n]

		if 法术认证列表[名称] ~= nil then
			self:添加主动技能(单位, 名称, 单位.等级)
		end
	end
end

function 战斗处理类:去除低级技能效果(单位, 技能名称, dj, gj, 属性名称)
	if self:取技能重复(单位, 技能名称) and 单位[属性名称 or 技能名称] ~= nil then
		单位[属性名称 or 技能名称] = 单位[属性名称 or 技能名称] - dj
		单位.已加技能[技能名称] = nil
	end
end

function 战斗处理类:添加技能属性(单位, 技能组, 正式添加)
	if 单位.治疗暴伤 == nil then
		单位.治疗暴伤 = 1.5
	end

	if 单位.物理暴伤 == nil then
		单位.物理暴伤 = 2
	end

	if 单位.法术暴伤 == nil then
		单位.法术暴伤 = 2
	end

	if 单位.普攻躲避率 == nil then
		单位.普攻躲避率 = 0
	end

	if 单位.物伤减少 == nil then
		单位.物伤减少 = 1
	end

	if 单位.法伤减少 == nil then
		单位.法伤减少 = 1
	end

	if 单位.奋勇当先 == nil then
		单位.奋勇当先 = 0
	end

	if 单位.赶尽杀绝 == nil then
		单位.赶尽杀绝 = 0
	end

	if 单位.魔之心 == nil then
		单位.魔之心 = 1
	end

	if 单位.法术状态 == nil then
		单位.法术状态 = {}
	end

	if 单位.特效神速 ~= nil then
		单位.速度 = qz(单位.速度 * (1 + 单位.特效神速 / 100))
		单位.特效神速 = nil
	end

	if 单位.特效聚怒 ~= nil then
		单位.愤怒 = 单位.愤怒 + 单位.特效聚怒
		单位.特效聚怒 = nil

		if 单位.愤怒 > 150 and 服务端参数.愤怒超限 ~= 1 and 单位.类型 == "角色" then
			单位.愤怒 = 150
		end
	end

	if 单位.等级 == 0 then
		单位.等级 = 1
	end

	if 单位.已加技能 == nil then
		单位.已加技能 = {}
	end

	if 单位.待添加技能 == nil then
		单位.待添加技能 = {}
	end

	if 技能组 ~= nil and #技能组 > 0 then
		单位.待添加技能 = 列表2加入到列表1(单位.待添加技能, 技能组, 1, 1)
	end

	if 正式添加 == nil then
		return
	end

	local dj, gj, cj = nil
	技能组 = 删除互斥技能(删除重复(单位.待添加技能), 单位)
	单位.待添加技能 = nil

	for n = 1, #技能组 do
		local 名称 = 技能组[n]

		if 单位.类型 == "bb" and 单位.玩家id ~= 0 and (单位.临时超级技能数量 or 0) < 战斗升超级技能数量 and 超级技能列表[名称] ~= nil and ygsj() <= 战斗升超级技能概率 then
			local aa = 超级技能列表[超级技能列表[名称]]

			常规提示(单位.玩家id, "#P(超级技能)#Y喜从天降！你的#G" .. 单位.名称 .. "#Y本场战斗中#R" .. 名称 .. "#Y升级为了#Z" .. aa)

			if 超级技能列表[名称] >= 38 and 超级技能列表[名称] <= 42 then
				self:添加主动技能(单位, 名称, 单位.等级)
			end

			名称 = aa
			单位.临时超级技能数量 = (单位.临时超级技能数量 or 0) + 1
		end

		if 单位.已加技能[名称] == nil then
			if 单位.类型 == "bb" and 装备特技[名称] == nil and (名称 == "观照万象" or self:物攻技能(名称) or self:法攻技能(名称) or self:恢复技能(名称) or self:增益技能(名称) or self:减益技能(名称) or self:封印技能(名称) or self:群体封印技能(名称)) then
				self:添加主动技能(单位, 名称, 单位.等级)

				if 名称 == "叱咤风云" then
					单位.叱咤风云 = 1
				elseif 名称 == "迅风出击" then
					self:添加状态("迅风出击", 单位, 单位, 1, 单位.战斗编号)
					self:更新单个法术状态(单位.战斗编号, "迅风出击")
				elseif 名称 == "超级永恒" then
					单位.永恒 = 1
					单位.超级永恒 = 0
				elseif 名称 == "焰火烁星" then
					if ygsj() <= 30 then
						单位.焰火烁星 = 1
					end
				elseif 名称 == "灵能激发" and ygsj() <= 33 then
					self.召唤加回合 = 1

					self:添加状态(名称, 单位, 单位)
				end
			elseif 名称 == "法术防御" then
				单位.法伤减少 = (单位.法伤减少 or 1) * 0.8
			elseif 名称 == "观照万象" or self:物攻技能(名称) or self:法攻技能(名称) or self:恢复技能(名称) or self:增益技能(名称) or self:减益技能(名称) or self:封印技能(名称) or self:群体封印技能(名称) then
				self:添加主动技能(单位, 名称, 单位.等级)
			elseif 名称 == "浮云神马" then
				self.召唤加回合 = 1

				self:添加状态(名称, 单位)

				self.召唤加回合 = 1

				self:添加状态(名称, self.参战单位[单位.主人或助战 or 单位.主人])
			elseif 名称 == "盾气" or 名称 == "高级盾气" or 名称 == "超级盾气" then
				dj = 1
				gj = 2
				cj = 2

				if 名称 == "盾气" then
					if self:取技能重复(单位, "高级盾气") == false and self:取技能重复(单位, "超级盾气") == false then
						单位.盾气 = (单位.盾气 or 0) + dj
					end
				elseif 名称 == "高级盾气" and self:取技能重复(单位, "超级盾气") == false then
					单位.盾气 = (单位.盾气 or 0) + gj

					self:去除低级技能效果(单位, "盾气", dj, gj)
				else
					单位.盾气 = (单位.盾气 or 0) + cj

					self:去除低级技能效果(单位, "高级盾气", gj, cj, "盾气")
					self:去除低级技能效果(单位, "盾气", dj, gj)

					单位.超级盾气 = 1
					local zr = 单位.主人或助战

					if zr ~= nil and self.参战单位[zr] ~= nil then
						if 单位.玩家id ~= 0 then
							常规提示(单位.玩家id,
								"#P(超级盾气)#R" .. 单位.名称 .. "#W为主人#R" .. self.参战单位[zr].名称 .. "#W添加了#G5#W回合#R盾气#W效果。")
						end

						self:添加状态("盾气", self.参战单位[zr], self.参战单位[zr], self.参战单位[zr].等级, zr, dj)

						self.参战单位[zr].法术状态.盾气.回合 = 5
					end
				end
			elseif 名称 == "花好月圆" then
				单位.花好月圆 = 8 * 单位.等级
			elseif 名称 == "神出鬼没" then
				单位.隐身 = 5
				单位.神出鬼没 = 1.1

				if 单位.面板技能 == nil or 单位.面板技能.神出鬼没 == nil then
					单位.躲避 = qz(单位.躲避 * 1.1)
				end
			elseif 名称 == "昼伏夜出" then
				单位.昼伏夜出 = 1
				单位.普攻躲避率 = 单位.普攻躲避率 + 10
			elseif 名称 == "出其不意" then
				单位.夜光复活 = 100
			elseif 名称 == "赶尽杀绝" then
				单位.赶尽杀绝 = 赶尽杀绝概率
			elseif 名称 == "冲击" or 名称 == "高级冲击" then
				dj = 冲击概率
				gj = 高级冲击概率

				if 名称 == "冲击" then
					if self:取技能重复(单位, "高级冲击") == false then
						单位.冲击 = (单位.冲击 or 0) + dj
					end
				else
					单位.冲击 = (单位.冲击 or 0) + gj

					self:去除低级技能效果(单位, "冲击", dj, gj)
				end
			elseif 名称 == "审判" or 名称 == "高级审判" then
				if BB技能削弱 then
					dj = 1.05
					gj = 1.1
				else
					dj = 1.1
					gj = 1.2
				end

				if 名称 == "审判" then
					if self:取技能重复(单位, "高级审判") == false then
						单位.审判 = (单位.审判 or 0) + dj
					end
				else
					单位.审判 = (单位.审判 or 0) + gj

					self:去除低级技能效果(单位, "审判", dj, gj)
				end
			elseif 名称 == "恐吓" or 名称 == "高级恐吓" then
				if 名称 == "恐吓" then
					if self:取技能重复(单位, "高级恐吓") == false then
						单位.恐吓 = 1
					end
				else
					单位.恐吓 = 2
				end
			elseif 名称 == "恐怖" or 名称 == "高级恐怖" then
				dj = 恐怖概率
				gj = 高级恐怖概率

				if 名称 == "恐怖" then
					if self:取技能重复(单位, "高级恐怖") == false then
						单位.恐怖 = (单位.恐怖 or 0) + dj
					end
				else
					单位.恐怖 = (单位.恐怖 or 0) + gj

					self:去除低级技能效果(单位, "恐怖", dj, gj)
				end
			elseif 名称 == "勇敢" or 名称 == "高级勇敢" then
				if 名称 == "勇敢" then
					if self:取技能重复(单位, "高级勇敢") == false then
						if BB技能削弱 then
							单位.勇敢 = 1.07
						else
							单位.勇敢 = 1.1
						end
					end
				else
					if BB技能削弱 then
						单位.勇敢 = 1.15
					else
						单位.勇敢 = 1.2
					end

					单位.高级勇敢 = 1
				end
			elseif 名称 == "魔法反击" or 名称 == "高级魔法反击" then
				dj = 0.5
				gj = 1

				if 名称 == "魔法反击" then
					if self:取技能重复(单位, "高级魔法反击") == false then
						单位.魔法反击 = (单位.魔法反击 or 0) + dj
					end
				else
					单位.魔法反击 = (单位.魔法反击 or 0) + gj

					self:去除低级技能效果(单位, "魔法反击", dj, gj)
				end
			elseif 名称 == "保命" or 名称 == "高级保命" then
				dj = 保命概率
				gj = 高级保命概率

				if 名称 == "保命" then
					if self:取技能重复(单位, "高级保命") == false then
						单位.保命 = (单位.保命 or 0) + dj
					end
				else
					单位.保命 = (单位.保命 or 0) + gj
					单位.高级保命 = 1

					self:去除低级技能效果(单位, "保命", dj, gj)
				end
			elseif 名称 == "冰霜" or 名称 == "高级冰霜" then
				dj = 10
				gj = 20

				if 名称 == "冰霜" then
					if self:取技能重复(单位, "高级冰霜") == false then
						单位.冰霜 = (单位.冰霜 or 0) + dj
					end
				else
					单位.冰霜 = (单位.冰霜 or 0) + dj

					self:去除低级技能效果(单位, "冰霜", dj, gj)

					单位.高级冰霜 = 15
				end
			elseif 名称 == "泡泡相伴" then
				单位.泡泡相伴 = 1
			elseif 名称 == "奋勇当先" then
				self.召唤加回合 = 1

				self:添加状态(名称, 单位)

				单位.奋勇当先 = 1
			elseif 名称 == "逍遥游" then
				单位.逍遥游 = 1

				if 单位.面板技能 == nil or 单位.面板技能.逍遥游 == nil then
					单位.速度 = qz(单位.速度 * 1.2)
				end
			elseif 名称 == "虎虎生风" then
				单位.物理暴伤 = 单位.物理暴伤 + 1
				单位.法术暴伤 = 单位.法术暴伤 + 1
			elseif 名称 == "风起龙游" then
				单位.物理暴伤 = 单位.物理暴伤 + 0.5
				单位.法术暴伤 = 单位.法术暴伤 + 0.5
				单位.治疗暴伤 = 单位.治疗暴伤 + 0.5
			elseif 名称 == "焚天陨火" then
				单位.焚天陨火 = 0
			elseif 名称 == "好梦连连" then
				local aa = 1

				if ygsj() <= 50 then
					aa = 2
				end

				self:添加状态("好梦连连", 单位, 单位, aa)
				self:更新单个法术状态(单位.战斗编号, "好梦连连")

				if 单位.法术状态.好梦连连.睡梦 ~= nil then
					if 判断模型是否是(单位, "癸卯神兔") then
						if string.find(单位.模型, "进阶") then
							单位.模型 = "进阶癸卯神兔_睡梦"
						else
							单位.模型 = "癸卯神兔_睡梦"
						end
					end

					self.战斗发言数据[#self.战斗发言数据 + 1] = {
						id = 单位.战斗编号,
						内容 = "#Y" .. 单位.名称 .. "#进入了#P睡梦#状态#36#36"
					}
				else
					self.战斗发言数据[#self.战斗发言数据 + 1] = {
						id = 单位.战斗编号,
						内容 = "#Y" .. 单位.名称 .. "#进入了#P惊梦#状态#41#41"
					}
				end
			elseif 名称 == "清风之华" then
				单位.清风之华 = 1
			elseif 名称 == "雨露之泽" then
				单位.雨露之泽 = 1
			elseif 名称 == "映雪棱镜" then
				单位.映雪棱镜 = 1
			elseif 名称 == "神来气旺" then
				单位.神来气旺 = 50
			elseif 名称 == "桀骜自恃" then
				单位.桀骜自恃 = 1
			elseif 名称 == "凭风借力" then
				单位.凭风借力 = 1
			elseif 名称 == "气贯长虹" then
				单位.气贯长虹 = 1
			elseif 名称 == "拘魂索命" then
				单位.拘魂索命 = 0
			elseif 名称 == "乘胜追击" then
				单位.乘胜追击 = 0
			elseif 名称 == "风沙之盾" then
				self:添加状态("风沙之盾", 单位, 单位)
				self:客户端添加状态(单位.战斗编号, "风沙之盾")
			elseif 名称 == "进击必杀" or 名称 == "高级进击必杀" or 名称 == "超级进击必杀" then
				if 名称 == "进击必杀" then
					if self:取技能重复(单位, "高级进击必杀") == false and self:取技能重复(单位, "超级进击必杀") == false then
						单位.进击必杀 = 1
						self.召唤加回合 = 1

						self:添加状态("进击必杀", 单位, 单位, 单位.进击必杀)
					end
				elseif 名称 == "高级进击必杀" and self:取技能重复(单位, "超级进击必杀") == false then
					单位.进击必杀 = 2
					self.召唤加回合 = 1

					self:取消状态("进击必杀", 单位)
					self:添加状态("进击必杀", 单位, 单位, 单位.进击必杀)
				else
					单位.进击必杀 = 2
					单位.超级进击必杀 = 1
					self.召唤加回合 = 1

					self:取消状态("进击必杀", 单位)
					self:添加状态("进击必杀", 单位, 单位, 单位.进击必杀)
				end
			elseif 名称 == "进击法爆" or 名称 == "高级进击法爆" or 名称 == "超级进击法爆" then
				if 名称 == "进击法爆" then
					if self:取技能重复(单位, "高级进击法爆") == false and self:取技能重复(单位, "超级进击法爆") == false then
						单位.进击法爆 = 1
						self.召唤加回合 = 1

						self:添加状态("进击法爆", 单位, 单位, 单位.进击法爆)
					end
				elseif 名称 == "高级进击法爆" and self:取技能重复(单位, "超级进击法爆") == false then
					单位.进击法爆 = 2
					self.召唤加回合 = 1

					self:取消状态("进击法爆", 单位)
					self:添加状态("进击法爆", 单位, 单位, 单位.进击法爆)
				else
					单位.进击法爆 = 2
					单位.超级进击法爆 = 1
					self.召唤加回合 = 1

					self:取消状态("进击法爆", 单位)
					self:添加状态("进击法爆", 单位, 单位, 单位.进击法爆)
				end
			elseif 名称 == "千锤百炼" then
				if 单位.面板技能 == nil or 单位.面板技能.千锤百炼 == nil then
					单位.最大气血 = 单位.最大气血 + 540
					单位.气血 = 单位.最大气血
				end

				if not 单位.物伤减少 then
					单位.物伤减少 = 1
				end

				单位.物伤减少 = 单位.物伤减少 * 0.85
			elseif 名称 == "赴汤蹈火" then
				if 单位.面板技能 == nil or 单位.面板技能.赴汤蹈火 == nil then
					单位.最大气血 = 单位.最大气血 + 540
					单位.气血 = 单位.最大气血
				end

				if not 单位.法伤减少 then
					单位.物伤减少 = 1
				end

				单位.法伤减少 = 单位.物伤减少 * 0.9
			elseif 名称 == "开门见山" then
				if 单位.面板技能 == nil or 单位.面板技能.开门见山 == nil then
					单位.伤害 = 单位.伤害 + 100
					单位.最大气血 = 单位.最大气血 + 380
					单位.气血 = 单位.最大气血
				end
			elseif 名称 == "张弛有道" then
				if 单位.面板技能 == nil or 单位.面板技能.张弛有道 == nil then
					单位.法伤 = 单位.法伤 + 100
					单位.最大气血 = 单位.最大气血 + 380
					单位.气血 = 单位.最大气血
				end
			elseif 名称 == "龙魂" then
				单位.龙魂 = 5
				self.召唤加回合 = 1

				self:添加状态(名称, 单位, 单位, 单位.龙魂)
				self:更新单个法术状态(单位.战斗编号, 名称)

				self.召唤加回合 = 1

				self:添加状态(名称, self.参战单位[单位.主人或助战 or 单位.主人], 单位, 单位.龙魂)
				self:更新单个法术状态(单位.主人或助战 or 单位.主人, 名称)
			elseif 名称 == "千钧一怒" then
				单位.千钧一怒 = 1
			elseif 名称 == "从天而降" then
				单位.从天而降 = 1
			elseif 名称 == "津津有味" then
				单位.津津有味 = 1

				if 单位.玩家id ~= 0 and 扣除道具(单位.玩家id, "包子", 1) then
					self:添加状态(名称, 单位)
				end
			elseif 名称 == "大快朵颐" then
				单位.大快朵颐连击 = 大快朵颐参数[1]
				单位.大快朵颐法连 = 大快朵颐参数[2]
				单位.必杀 = (单位.必杀 or 基础暴击率) + 大快朵颐暴击参数[1] + 0
