						单位.高级强力 = nil
					end

					if 单位.低级强力 ~= nil then
						单位.伤害 = qz(单位.伤害 - 单位.等级 * 0.4)
						单位.低级强力 = nil
					end

					if 单位.面板技能 == nil or 单位.面板技能.超级强力 == nil then
						单位.伤害 = qz(单位.伤害 + 单位.等级 * 0.7)
					end

					单位.超级强力 = 10
				end
			elseif 名称 == "毒" or 名称 == "高级毒" or 名称 == "超级毒" then
				dj = 毒概率
				gj = 高级毒概率
				cj = 超级毒概率

				if 名称 == "毒" then
					if self:取技能重复(单位, "高级毒") == false and self:取技能重复(单位, "超级毒") == false then
						单位.毒 = (单位.毒 or 0) + dj
					end
				elseif 名称 == "高级毒" and self:取技能重复(单位, "超级毒") == false then
					单位.毒 = (单位.毒 or 0) + gj
					单位.高级毒 = 1

					self:去除低级技能效果(单位, "毒", dj, gj)
				else
					单位.毒 = (单位.毒 or 0) + cj

					self:去除低级技能效果(单位, "高级毒", gj, cj, "毒")
					self:去除低级技能效果(单位, "毒", dj, gj)

					单位.高级毒 = 1
					单位.超级毒 = 1
				end
			elseif 名称 == "驱鬼" or 名称 == "高级驱鬼" or 名称 == "超级驱鬼" then
				if 名称 == "驱鬼" then
					if self:取技能重复(单位, "高级驱鬼") == false and self:取技能重复(单位, "超级驱鬼") == false then
						单位.驱鬼 = 1.5
					end
				elseif 名称 == "高级驱鬼" and self:取技能重复(单位, "超级驱鬼") == false then
					单位.驱鬼 = 2
				else
					单位.驱鬼 = 2.5
				end
			elseif 名称 == "鬼魂术" or 名称 == "高级鬼魂术" and 单位.类型 == "bb" then
				if 名称 == "鬼魂术" then
					if self:取技能重复(单位, "高级鬼魂术") == false then
						单位.鬼魂 = 5
					end
				else
					单位.鬼魂 = 4
				end
			elseif 名称 == "魔之心" or 名称 == "高级魔之心" or 名称 == "超级魔之心" then
				if 名称 == "魔之心" then
					if self:取技能重复(单位, "高级魔之心") == false and self:取技能重复(单位, "超级魔之心") == false then
						单位.魔之心 = 单位.魔之心 * 1.1
					end
				elseif 名称 == "高级魔之心" and self:取技能重复(单位, "超级魔之心") == false then
					if self:取技能重复(单位, "魔之心") then
						单位.魔之心 = 单位.魔之心 / 1.1
						单位.已加技能.魔之心 = nil
					end

					单位.魔之心 = 单位.魔之心 * 1.2
				else
					if self:取技能重复(单位, "魔之心") then
						单位.魔之心 = 单位.魔之心 / 1.1
						单位.已加技能.魔之心 = nil
					end

					if self:取技能重复(单位, "高级魔之心") then
						单位.魔之心 = 单位.魔之心 / 1.2
						单位.已加技能.高级魔之心 = nil
					end

					单位.魔之心 = 单位.魔之心 * 1.3
				end
			elseif 名称 == "神佑复生" or 名称 == "高级神佑复生" or 名称 == "超级神柚复生" then
				dj = 神佑概率
				gj = 高级神佑概率
				cj = 40

				if 名称 == "神佑复生" then
					if self:取技能重复(单位, "高级神佑复生") == false and self:取技能重复(单位, "超级神柚复生") == false then
						单位.神佑 = (单位.神佑 or 0) + dj
					end
				elseif 名称 == "高级神佑复生" and self:取技能重复(单位, "超级神柚复生") == false then
					单位.神佑 = (单位.神佑 or 0) + gj
					单位.高级神佑 = 1

					if self:取技能重复(单位, "神佑复生") then
						单位.神佑 = 单位.神佑 - dj
					end
				else
					单位.神佑 = (单位.神佑 or 0) + cj
					单位.高级神佑 = 1

					if self:取技能重复(单位, "高级神佑复生") then
						单位.神佑 = 单位.神佑 - gj
					end

					单位.超级神佑 = 1
				end
			elseif 名称 == "精神集中" or 名称 == "高级精神集中" or 名称 == "超级精神集中" then
				if 名称 == "精神集中" then
					if self:取技能重复(单位, "高级精神集中") == false and self:取技能重复(单位, "超级精神集中") == false then
						单位.精神 = 0.8
					end
				elseif 名称 == "高级精神集中" and self:取技能重复(单位, "超级精神集中") == false then
					单位.精神 = 0.8

					if 单位.面板技能 == nil or 单位.面板技能.高级精神集中 == nil then
						单位.躲避 = qz(单位.躲避 * 1.1)
						单位.高级精神集中 = 1
					end
				else
					单位.精神 = 0.8
					单位.超级精神集中 = 1

					if 单位.高级精神集中 ~= nil then
						单位.躲避 = qz(单位.躲避 / 1.1)
						单位.高级精神集中 = nil
					end

					if 单位.面板技能 == nil or 单位.面板技能.超级精神集中 == nil then
						单位.躲避 = qz(单位.躲避 * 1.1)
					end
				end
			elseif 名称 == "否定信仰" or 名称 == "高级否定信仰" or 名称 == "超级否定信仰" then
				if 名称 == "否定信仰" then
					if self:取技能重复(单位, "高级否定信仰") == false and self:取技能重复(单位, "超级否定信仰") == false then
						单位.信仰 = 1.2
					end
				elseif 名称 == "高级否定信仰" and self:取技能重复(单位, "超级否定信仰") == false then
					单位.信仰 = 1.2
					单位.法伤减少 = (单位.法伤减少 or 1) * 0.8
				else
					if self:取技能重复(单位, "高级否定信仰") == true then
						单位.已加技能.高级否定信仰 = nil
						单位.法伤减少 = 单位.法伤减少 / 0.8
					end

					单位.信仰 = 1.2
					单位.法伤减少 = (单位.法伤减少 or 1) * 0.8
					单位.超级信仰 = 1
				end
			elseif 名称 == "法术暴击" or 名称 == "高级法术暴击" or 名称 == "超级法术暴击" then
				dj = 10
				gj = 15
				cj = 25

				if 名称 == "法术暴击" then
					if self:取技能重复(单位, "高级法术暴击") == false and self:取技能重复(单位, "超级法术暴击") == false then
						单位.法暴 = (单位.法暴 or 基础法暴率) + dj
					end
				elseif 名称 == "高级法术暴击" and self:取技能重复(单位, "超级法术暴击") == false then
					单位.法暴 = (单位.法暴 or 基础法暴率) + gj

					if self:取技能重复(单位, "法术暴击") then
						单位.法暴 = 单位.法暴 - dj
						单位.已加技能.法术暴击 = nil
					end
				else
					单位.法暴 = (单位.法暴 or 基础法暴率) + cj

					if self:取技能重复(单位, "法术暴击") then
						单位.法暴 = 单位.法暴 - dj
						单位.已加技能.法术暴击 = nil
					end

					if self:取技能重复(单位, "高级法术暴击") then
						单位.法暴 = 单位.法暴 - gj
						单位.已加技能.高级法术暴击 = nil
					end
				end
			elseif 名称 == "法术连击" or 名称 == "高级法术连击" or 名称 == "超级法术连击" then
				dj = 20
				gj = 30
				cj = 30

				if 名称 == "法术连击" then
					if self:取技能重复(单位, "高级法术连击") == false and self:取技能重复(单位, "超级法术连击") == false then
						单位.法连 = (单位.法连 or 0) + dj
					end
				elseif 名称 == "高级法术连击" and self:取技能重复(单位, "超级法术连击") == false then
					单位.法连 = (单位.法连 or 0) + dj
					单位.高级法连 = 1

					if self:取技能重复(单位, "法术连击") then
						单位.法连 = 单位.法连 - dj
						单位.已加技能.法术连击 = nil
					end
				else
					单位.超级法连 = 1
					单位.高级法连 = nil
					单位.法连 = (单位.法连 or 0) + cj

					if self:取技能重复(单位, "法术连击") then
						单位.法连 = 单位.法连 - dj
						单位.已加技能.法术连击 = nil
					end

					if self:取技能重复(单位, "高级法术连击") then
						单位.法连 = 单位.法连 - gj
						单位.已加技能.高级法术连击 = nil
					end
				end
			elseif 名称 == "法术波动" or 名称 == "高级法术波动" or 名称 == "超级法术波动" then
				if 名称 == "法术波动" then
					if self:取技能重复(单位, "高级法术波动") == false and self:取技能重复(单位, "超级法术波动") == false then
						单位.法波 = 法波上限
						单位.法波下 = 法波下限
					end
				elseif 名称 == "高级法术波动" and self:取技能重复(单位, "超级法术波动") == false then
					单位.法波 = 高法波上限
					单位.法波下 = 高法波下限
				else
					单位.法波 = 超法波上限
					单位.法波下 = 超法波下限
				end
			elseif 名称 == "水属性吸收" or 名称 == "高级水属性吸收" or 名称 == "超级水属性吸收" then
				if 名称 == "水属性吸收" then
					if self:取技能重复(单位, "高级水属性吸收") == false and self:取技能重复(单位, "超级水属性吸收") == false then
						单位.水吸 = 1
					end
				elseif 名称 == "高级水属性吸收" and self:取技能重复(单位, "超级水属性吸收") == false then
					单位.水吸 = 2
				else
					单位.水吸 = 3
				end
			elseif 名称 == "雷属性吸收" or 名称 == "高级雷属性吸收" or 名称 == "超级雷属性吸收" then
				if 名称 == "雷属性吸收" then
					if self:取技能重复(单位, "高级雷属性吸收") == false and self:取技能重复(单位, "超级雷属性吸收") == false then
						单位.雷吸 = 1
					end
				elseif 名称 == "高级雷属性吸收" and self:取技能重复(单位, "超级雷属性吸收") == false then
					单位.雷吸 = 2
				else
					单位.雷吸 = 3
				end
			elseif 名称 == "火属性吸收" or 名称 == "高级火属性吸收" or 名称 == "超级火属性吸收" then
				if 名称 == "火属性吸收" then
					if self:取技能重复(单位, "高级火属性吸收") == false and self:取技能重复(单位, "超级火属性吸收") == false then
						单位.火吸 = 1
					end
				elseif 名称 == "高级火属性吸收" and self:取技能重复(单位, "超级火属性吸收") == false then
					单位.火吸 = 2
				else
					单位.火吸 = 3
				end
			elseif 名称 == "土属性吸收" or 名称 == "高级土属性吸收" or 名称 == "超级土属性吸收" then
				if 名称 == "土属性吸收" then
					if self:取技能重复(单位, "高级土属性吸收") == false and self:取技能重复(单位, "超级土属性吸收") == false then
						单位.土吸 = 1
					end
				elseif 名称 == "高级土属性吸收" and self:取技能重复(单位, "超级土属性吸收") == false then
					单位.土吸 = 2
				else
					单位.土吸 = 3
				end
			elseif 名称 == "真灵(金)" or 名称 == "真灵(木)" or 名称 == "真灵(水)" or 名称 == "真灵(火)" or 名称 == "真灵(土)" then
				单位.真灵 = 0.95
			elseif 名称 == "健壮(金)" or 名称 == "健壮(木)" or 名称 == "健壮(水)" or 名称 == "健壮(火)" or 名称 == "健壮(土)" then
				单位.五行健壮 = 0.95
			elseif 名称 == "力大无穷(金)" or 名称 == "力大无穷(木)" or 名称 == "力大无穷(水)" or 名称 == "力大无穷(火)" or 名称 == "力大无穷(土)" then
				单位.力大无穷 = 0.05
			elseif 名称 == "万物之灵(金)" or 名称 == "万物之灵(木)" or 名称 == "万物之灵(水)" or 名称 == "万物之灵(火)" or 名称 == "万物之灵(土)" then
				单位.万物之灵 = 0.05
			elseif 名称 == "义薄云天" then
				单位.义薄云天 = qz(单位.等级 * 0.55)
			elseif 名称 == "凝光炼彩" then
				单位.凝光炼彩 = 1
			elseif 名称 == "弱点雷" then
				单位.弱点雷 = 1
			elseif 名称 == "弱点火" then
				单位.弱点火 = 1
			elseif 名称 == "弱点水" then
				单位.弱点水 = 1
			elseif 名称 == "弱点土" then
				单位.弱点土 = 1
			elseif 名称 == "嗜血追击" then
				单位.嗜血追击 = 1
			elseif 名称 == "须弥真言" then
				if 单位.面板技能 == nil or 单位.面板技能.须弥真言 == nil then
					单位.法伤 = 单位.法伤 + qz1((单位.魔力 or 单位.等级 * 3) * 0.4)
				end
			elseif 名称 == "圣婴大王" then
				if 单位.面板技能 == nil or 单位.面板技能.圣婴大王 == nil then
					单位.法伤 = 单位.法伤 + qz1((单位.魔力 or 单位.等级 * 3) * 0.5)
				end
			elseif 名称 == "诸天正法" and (单位.面板技能 == nil or 单位.面板技能.诸天正法 == nil) then
				单位.伤害 = 单位.伤害 + qz1((单位.魔力 or 单位.等级 * 3) * (单位.成长 or 1) * 0.2)
				单位.防御 = 单位.防御 - qz1((单位.魔力 or 单位.等级 * 3) * 0.2)
			end

			单位.已加技能[名称] = 1
		end
	end
end

删除互斥技能 = function(技能组, 单位数据)
	local 技能列表 = 列表模式转换(技能组)
	local 删除技能 = {}

	if 技能列表.否定信仰 ~= nil or 技能列表.高级否定信仰 ~= nil or 技能列表.超级否定信仰 ~= nil or 技能列表.天狐之舞 ~= nil and 判断模型是否是(单位数据, "觉醒涂山雪") then
		删除技能 = {
			超级感知 = 1,
			高级驱鬼 = 1,
			超级隐身 = 1,
			高级神迹 = 1,
			雷属性吸收 = 1,
			神迹 = 1,
			超级水属性吸收 = 1,
			鬼魂术 = 1,
			神佑复生 = 1,
			高级雷属性吸收 = 1,
			隐身 = 1,
			高级隐身 = 1,
			土属性吸收 = 1,
			高级水属性吸收 = 1,
			感知 = 1,
			高级火属性吸收 = 1,
			超级雷属性吸收 = 1,
			高级土属性吸收 = 1,
			水属性吸收 = 1,
			高级鬼魂术 = 1,
			超级神柚复生 = 1,
			超级火属性吸收 = 1,
			驱鬼 = 1,
			超级鬼魂术 = 1,
			火属性吸收 = 1,
			超级神迹 = 1,
			高级神佑复生 = 1,
			高级感知 = 1,
			超级驱鬼 = 1,
			超级土属性吸收 = 1
		}
	elseif 技能列表.鬼魂术 ~= nil or 技能列表.高级鬼魂术 ~= nil or 技能列表.超级鬼魂术 ~= nil then
		删除技能 = 加入删除技能(删除技能, {
			"神佑复生"
		})
	end

	if 技能列表.欣欣向荣 ~= nil or 技能列表.茁壮 ~= nil then
		local sc = {
			"鬼魂术",
			"神佑复生",
			"出其不意"
		}

		if 技能列表.欣欣向荣 ~= nil then
			sc[#sc + 1] = "茁壮"
		end

		删除技能 = 加入删除技能(删除技能, sc)
	end

	local 五行 = {
		"金",
		"木",
		"水",
		"火",
		"土"
	}
	local 五行技能 = {
		"真灵",
		"力大无穷",
		"万物之灵",
		"健壮"
	}

	for i = 1, #五行技能 do
		for n = 1, #五行 do
			local aa = 五行技能[i] .. "(" .. 五行[n] .. ")"

			if 技能列表[aa] ~= nil and 单位数据.五行 ~= 五行[n] then
				删除技能[aa] = 1
			end
		end
	end

	local ts = {
		神佑复生 = "超级神柚复生",
		饕餮盛宴 = "饕餮盛宴·觉醒",
		剑气四射 = "剑气四射·觉醒"
	}
	local ts1 = {}
	local sc = {}

	for i = 1, #技能组 do
		if 删除技能[技能组[i]] ~= nil then
			sc[#sc + 1] = i
		elseif 技能列表["高级" .. 技能组[i]] ~= nil or ts[技能组[i]] ~= nil and 技能列表[ts[技能组[i]]] ~= nil or ts1[技能组[i]] == nil and 技能列表["超级" .. string.gsub(技能组[i], "高级", "")] ~= nil then
			sc[#sc + 1] = i
		end
	end

	if #sc > 0 then
		技能组 = 无错误删除列表多个元素(技能组, sc)
	end

	return 技能组
end

加入删除技能 = function(删除技能, 技能组)
	local ts = {
		神佑复生 = "超级神柚复生"
	}

	if type(技能组) == "table" then
		for i = 1, #技能组 do
			local 技能 = 技能组[i]
			删除技能[技能] = 1

			if ts[技能] ~= nil then
				删除技能[ts[技能]] = 1
			end

			if 全部兽决1["高级" .. 技能] ~= nil then
				删除技能["高级" .. 技能] = 1
			end

			if 超级技能列表1["超级" .. 技能] ~= nil then
				删除技能["超级" .. 技能] = 1
			end
		end
	end

	return 删除技能
end

function 战斗处理类:取技能重复(单位, 技能)
	if 单位.已加技能 == nil then
		单位.已加技能 = {}
	end

	if 单位.已加技能[技能] ~= nil then
		return true
	else
		return false
	end
end

function 战斗处理类:设置队伍区分(id)
	if self.队伍区分[1] == id then
		self.队伍数量[1] = self.队伍数量[1] + 1
	else
		self.队伍数量[2] = self.队伍数量[2] + 1
		self.队伍区分[2] = id
	end
end

function 战斗处理类:日月乾坤结束战斗()
	local 死亡计算 = {
		0,
		0
	}

	for n = 1, #self.参战单位 do
		if self.参战单位[n].气血 <= 0 or self.参战单位[n].捕捉 or self.参战单位[n].逃跑 then
			if self.参战单位[n].队伍 == self.队伍区分[1] then
				死亡计算[1] = 死亡计算[1] + 1
			else
				死亡计算[2] = 死亡计算[2] + 1
			end
		end

		if 日月乾坤结束战斗 == true and self.参战单位[n].气血 > 0 and self.参战单位[n].法术状态.日月乾坤 ~= nil then
			if self.参战单位[n].队伍 == self.队伍区分[1] then
				死亡计算[1] = 死亡计算[1] + 1
			else
				死亡计算[2] = 死亡计算[2] + 1
			end
		end
	end

	if self.队伍数量[1] <= 死亡计算[1] then
		self.回合进程 = "结束回合"

		self:结束战斗(self.队伍区分[2], self.队伍区分[1])

		return
	elseif self.队伍数量[2] <= 死亡计算[2] then
		self.回合进程 = "结束回合"

		self:结束战斗(self.队伍区分[1], self.队伍区分[2])

		return
	end
end

function 战斗处理类:流程处理气血魔法(编号, 说明组)
	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 1024,
		攻击方 = 编号,
		挨打方 = {}
	}
	local 精准战斗流程 = #self.战斗流程 + 0

	for i = 1, #说明组 do
		self.战斗流程[精准战斗流程].挨打方[#self.战斗流程[精准战斗流程].挨打方 + 1] = 说明组[i]
	end
end

function 战斗处理类:流程处理全部状态(编号组)
	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 1024,
		攻击方 = 编号组[1],
		挨打方 = {}
	}
	local 精准战斗流程 = #self.战斗流程 + 0

	for i = 1, #编号组 do
		if self.参战单位[编号组[i]] ~= nil and self.参战单位[编号组[i]].法术状态 ~= nil then
			local 状态 = DeepCopy(self.参战单位[编号组[i]].法术状态)

			if (self.参战单位[编号组[i]].战意 or 0) > 0 then
				状态.战意 = self.参战单位[编号组[i]].战意
			end

			if (self.参战单位[编号组[i]].超级战意 or 0) > 0 then
				状态.超级战意 = self.参战单位[编号组[i]].超级战意
			end

			self.战斗流程[精准战斗流程].挨打方[#self.战斗流程[精准战斗流程].挨打方 + 1] = {
				挨打方 = 编号组[i],
				全部状态 = 状态
			}
		end
	end
end

function 战斗处理类:流程退场处理(编号, 退场特效)
	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 707.32,
		攻击方 = 编号,
		退场特效 = 退场特效,
		挨打方 = {}
	}
	local 精准战斗流程 = #self.战斗流程 + 0

	if self.参战单位[编号] ~= nil then
		self.参战单位[编号].气血 = 0
		self.参战单位[编号].死亡状态 = 1
		self.参战单位[编号].法术状态 = {}
	end
end

function 战斗处理类:流程处理状态(编号, 状态组)
	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 1024,
		攻击方 = 编号,
		挨打方 = {}
	}
	local 精准战斗流程 = #self.战斗流程 + 0

	for i = 1, #状态组 do
		local 状态 = {}

		if 状态组[i].状态 ~= nil then
			if type(状态组[i].状态) ~= "table" then
				状态组[i].状态 = {
					状态组[i].状态
				}
			end

			for n = 1, #状态组[i].状态 do
				local 状态名称 = 状态组[i].状态[n]

				if 状态名称 == "战意" then
					状态[状态名称] = self.参战单位[状态组[i].挨打方].战意

					if (self.参战单位[状态组[i].挨打方].超级战意 or 0) > 0 then
						状态.超级战意 = self.参战单位[状态组[i].挨打方].超级战意
					end
				else
					状态[状态名称] = self.参战单位[状态组[i].挨打方].法术状态[状态名称]
				end
			end

			状态组[i].状态 = DeepCopy(状态)
		end

		self.战斗流程[精准战斗流程].挨打方[#self.战斗流程[精准战斗流程].挨打方 + 1] = 状态组[i]
	end
end

function 战斗处理类:更新单个法术状态(编号, 状态名称)
	if self.参战单位[编号] == nil then
		return
	end

	if self.待消除状态[编号] ~= nil and self.待消除状态[编号][状态名称] ~= nil then
		self:取消状态(编号, 状态名称)

		self.待消除状态[编号][状态名称] = nil

		self:流程处理状态(编号, {
			{
				挨打方 = 编号,
				取消状态 = 状态名称,
				状态 = {
					状态名称
				}
			}
		})

		return
	end

	self:流程处理状态(编号, {
		{
			挨打方 = 编号,
			状态 = {
				状态名称
			}
		}
	})
end

function 战斗处理类:客户端取消状态(编号, 状态名称)
	self:流程处理状态(编号, {
		{
			挨打方 = 编号,
			取消状态 = 状态名称,
			状态 = {
				状态名称
			}
		}
	})
end

function 战斗处理类:客户端添加状态(编号, 状态名称)
	if self.待消除状态[编号] ~= nil and self.待消除状态[编号][状态名称] ~= nil then
		self:取消状态(编号, 状态名称)

		self.待消除状态[编号][状态名称] = nil

		return
	end

	self:流程处理状态(编号, {
		{
			挨打方 = 编号,
			增加状态 = 状态名称,
			状态 = {
				状态名称
			}
		}
	})
end

