function 战斗处理类:去除待消除状态(编号)
	if self.参战单位[编号] ~= nil and self.待消除状态[编号] ~= nil and not 判断是否为空表(self.待消除状态[编号]) then
		for k, v in pairs(self.待消除状态[编号]) do
			self.参战单位[编号].法术状态[k] = nil
		end
	end
end

function 战斗处理类:取神通技能(编号)
	local n = 编号

	if self.参战单位[n].门派 == "花果山" and self.参战单位[n].被动技能.如意神通 ~= nil then
		local 如意神通 = {}

		if self.参战单位[n].经脉流派 == "通天行者" then
			如意神通 = {
				"棒掀北斗",
				"兴风作浪",
				"棍打诸神",
				"意马心猿",
				"九幽除名",
				"云暗天昏",
				"铜头铁臂",
				"无所遁形"
			}
		elseif self.参战单位[n].棒打雄风 == nil then
			如意神通 = {
				"当头一棒",
				"神针撼海",
				"杀威铁棒",
				"泼天乱棒",
				"九幽除名",
				"云暗天昏",
				"铜头铁臂",
				"无所遁形"
			}
		else
			如意神通 = {
				"当头一棒",
				"神针撼海",
				"棒打雄风",
				"泼天乱棒",
				"九幽除名",
				"云暗天昏",
				"铜头铁臂",
				"无所遁形"
			}
		end

		if self.参战单位[n].显圣 == 1 then
			self.参战单位[n].显圣 = 0
			self.参战单位[n].神通数 = #如意神通 + 0
			self.参战单位[n].神通技能 = 列表模式转换(如意神通)
		elseif self.参战单位[n].顽心 == 1 then
			self.参战单位[n].顽心 = 0
		else
			local 排除技能 = {}
			local 加入技能 = {}
			local 技能数 = 3

			if self:取奇经八脉是否有(编号, "闹海", "通天行者") and self:取玩家战斗() == false then
				排除技能[#排除技能 + 1] = "兴风作浪"
				加入技能[#加入技能 + 1] = "兴风作浪"
				技能数 = 技能数 - 1
			end

			if (self.参战单位[n].斗志 ~= nil or self.参战单位[n].变通 ~= nil) and self.参战单位[n].实时神通 ~= nil then
				排除技能[#排除技能 + 1] = self.参战单位[n].实时神通
			end

			if self.参战单位[n].贪天 ~= nil and self.参战单位[n].实时神通 ~= nil and ygsj() <= 50 then
				排除技能[#排除技能 + 1] = self.参战单位[n].实时神通
				加入技能[#加入技能 + 1] = self.参战单位[n].实时神通
				技能数 = 技能数 - 1
			end

			if self.参战单位[n].自在 ~= nil and self.参战单位[n].实时神通 ~= nil and ygsj() <= self.参战单位[n].自在 then
				技能数 = 技能数 + 1
			end

			if self.参战单位[n].变通 ~= nil and self.参战单位[n].实时神通 ~= nil and ygsj() <= self.参战单位[n].变通 then
				技能数 = 技能数 + 1
			end

			if self.参战单位[n].战神 ~= nil then
				技能数 = 技能数 + 1
				self.参战单位[n].战神 = nil
			end

			if self.参战单位[n].顽性 ~= nil and self.参战单位[n].实时神通 ~= nil and ygsj() <= self.参战单位[n].顽性 then
				排除技能[#排除技能 + 1] = self.参战单位[n].实时神通
				加入技能[#加入技能 + 1] = self.参战单位[n].实时神通
			end

			if #排除技能 > 0 then
				local aa = 列表模式转换(排除技能)
				local pc = {}

				for i = 1, #如意神通 do
					if aa[如意神通[i]] ~= nil then
						pc[#pc + 1] = i
					end
				end

				如意神通 = 无错误删除列表多个元素(如意神通, pc)
			end

			local st = 删除重复(列表2加入到列表1(取列表多项(如意神通, 技能数), 加入技能))
			self.参战单位[n].神通数 = #st + 0
			self.参战单位[n].神通技能 = 列表模式转换(st)
		end
	end
end

function 战斗处理类:结算处理()
	local 死亡计算 = {
		0,
		0
	}

	for n = 1, #self.参战单位 do
		if self.参战单位[n].气血 <= 0 or self.参战单位[n].捕捉 or self.参战单位[n].逃跑 then
			if self.参战单位[n].队伍 == self.队伍区分[1] then
				死亡计算[1] = 死亡计算[1] + 1
			else
				死亡计算[2] = 死亡计算[2] + 1
			end
		end

		if 日月乾坤结束战斗 == true and self.参战单位[n].气血 > 0 and self.参战单位[n].法术状态.日月乾坤 ~= nil then
			if self.参战单位[n].队伍 == self.队伍区分[1] then
				死亡计算[1] = 死亡计算[1] + 1
			else
				死亡计算[2] = 死亡计算[2] + 1
			end
		end
	end

	if self.队伍数量[1] <= 死亡计算[1] then
		self.回合进程 = "结束回合"

		self:结束战斗(self.队伍区分[2], self.队伍区分[1])

		return
	elseif self.队伍数量[2] <= 死亡计算[2] then
		self.回合进程 = "结束回合"

		self:结束战斗(self.队伍区分[1], self.队伍区分[2])

		return
	end

	local 观战状态 = {}
	local 法术状态 = {}
	local 血量 = {}

	self:击退处理()

	for n = 1, #self.参战单位 do
		if self.参战单位[n].轮回 ~= nil then
			local gs = self:取敌方拥有指定状态人数(n, "尸腐毒")

			if gs >= 6 then
				self:添加状态("轮回", self.参战单位[n], self.参战单位[n], nil, n)
			end
		end

		if self.参战单位[n].生杀予夺判定 ~= nil then
			local gs = self:取敌方拥有指定状态人数(n, "尸腐毒") * 2
			local gs1 = 0

			if self:取玩家战斗() then
				for i = 1, #self.参战单位 do
					if self.参战单位[i].死亡状态 == 2 and self.参战单位[i].队伍 ~= self.参战单位[n].队伍 and self.参战单位[i].类型 ~= "bb" then
						gs1 = gs1 + 2
					end
				end
			end

			self:减少技能冷却(n, "生杀予夺", gs + gs1)
		end
	end

	for n = 1, #self.参战单位 do
		if self.参战单位[n].类型 == "角色" and self.参战单位[n].助战编号 == nil then
			if self.参战单位[n].最大气血 < self.参战单位[n].气血上限 then
				self.参战单位[n].气血上限 = self.参战单位[n].最大气血
			end

			if self.参战单位[n].气血上限 < self.参战单位[n].气血 then
				self.参战单位[n].气血 = self.参战单位[n].气血上限
			end
		end

		if self.参战单位[n].法术状态 == nil then
			self.参战单位[n].法术状态 = {}
		end

		if self.参战单位[n].法宝已扣 ~= nil then
			self.参战单位[n].法宝已扣 = {}
		end

		self.参战单位[n].冷却技能列表 = {}

		for i = 1, #冷却技能减回合 do
			if self.参战单位[n][冷却技能减回合[i]] ~= nil and self.参战单位[n][冷却技能减回合[i]] > 0 then
				self.参战单位[n].冷却技能列表[冷却技能减回合[i]] = self.参战单位[n][冷却技能减回合[i]]
			end
		end

		self:去除待消除状态(n)

		if self.参战单位[n].神迹 == 1 then
			local 异常状态名称 = self:取异常状态法术()

			for m = 1, #异常状态名称 do
				if self.参战单位[n].法术状态[异常状态名称[m]] ~= nil then
					for w = 1, #self.参战玩家 do
						发送数据(self.参战玩家[w].连接id, 5507, {
							id = n,
							名称 = 异常状态名称[m]
						})
					end

					观战状态[#观战状态 + 1] = {
						序号 = 5507,
						id = n,
						名称 = 异常状态名称[m]
					}

					self:取消状态(异常状态名称[m], self.参战单位[n])
				end
			end
		elseif self.参战单位[n].苏醒 ~= nil then
			if self.参战单位[n].死亡状态 ~= nil then
				if self.参战单位[n].苏醒 == 0 then
					self.参战单位[n].苏醒 = self.参战单位[n].最大气血 + 0
				end

				if math.floor(self.参战单位[n].最大气血 * 0.3) <= self.参战单位[n].苏醒 - self.参战单位[n].气血 then
					local 异常状态名称 = self:解除状态结果(self.参战单位[n], self:取异常封印法术状态(), "苏醒")

					for m = 1, #异常状态名称 do
						if self.参战单位[n].法术状态[异常状态名称[m]] ~= nil then
							for w = 1, #self.参战玩家 do
								发送数据(self.参战玩家[w].连接id, 5507, {
									id = n,
									名称 = 异常状态名称[m]
								})
							end

							观战状态[#观战状态 + 1] = {
								序号 = 5507,
								id = n,
								名称 = 异常状态名称[m]
							}

							self:取消状态(异常状态名称[m], self.参战单位[n])
						end
					end
				end

				self.参战单位[n].苏醒 = self.参战单位[n].气血 + 0
			else
				self.参战单位[n].苏醒 = 1
			end
		end

		if self.参战单位[n].风灵 ~= nil and self:取奇经八脉是否有(n, "法身") == false and self.回合数 % 2 == 0 then
			self:刷新风灵(n, 1)
		end

		if self.参战单位[n].黎魂 ~= nil and self.参战单位[n].门派 == "九黎城" then
			self.参战单位[n].黎魂 = 2
			local gl = 九黎城三次概率 + (self.参战单位[n].黎魂加成 or 0)

			if (self.参战单位[n].九黎连击次数 or 0) > 0 then
				gl = gl + self.参战单位[n].九黎连击次数 * 3
			end

			if self.参战单位[n].凌人概率 ~= nil then
				gl = gl + self.参战单位[n].凌人概率
				self.参战单位[n].凌人概率 = nil
			end

			if 取随机数(1, 1000) <= gl * 10 or self.参战单位[n].野蛮生效 ~= nil then
				self.参战单位[n].黎魂 = self.参战单位[n].黎魂 + 1
				self.参战单位[n].野蛮生效 = nil
			end
		end

		self:取神通技能(n)

		if self:取奇经八脉是否有(n, "旋阳") and (self.回合数 + 1) % 2 == 0 then
			self:减少技能冷却(n, "秘传飞砂走石", 1)
			self:减少技能冷却(n, "秘传三昧真火", 1)
		end

		if self:取奇经八脉是否有(n, "慈心") then
			local 添加列表 = {}

			for i = 1, #self.参战单位 do
				if i ~= n and (self.参战单位[i].法术状态.死亡召唤 ~= nil or self.参战单位[i].法术状态.锢魂术 ~= nil) then
					local 判定回合 = 2

					if n < i then
						判定回合 = 判定回合 + 1
					end

					if self.参战单位[i].法术状态.死亡召唤 ~= nil and self.参战单位[i].法术状态.死亡召唤.回合 <= 判定回合 then
						self.参战单位[i].法术状态.死亡召唤 = nil
						添加列表.死亡召唤 = 1
					end

					if self.参战单位[i].法术状态.锢魂术 ~= nil and self.参战单位[i].法术状态.锢魂术.回合 <= 判定回合 then
						self.参战单位[i].法术状态.锢魂术 = nil
						添加列表.锢魂术 = 1
					end
				end
			end

			for k, v in pairs(添加列表) do
				self:添加状态(k, self.参战单位[n])

				self.参战单位[n].法术状态[k].回合 = 6
			end
		end

		if self.参战单位[n].咒符 then
			if self.参战单位[n].法术状态.咒符 == nil then
				self:添加状态("咒符", self.参战单位[n])
			elseif self.参战单位[n].法术状态.咒符.层数 < 5 then
				local xx = 1
				local sx = 5

				if self:取奇经八脉是否有(n, "咒诀") then
					local zl = self:取符咒种类(n)

					if zl ~= nil and #zl == 0 then
						xx = 3
					end
				end

				if self:取奇经八脉是否有(n, "造化") and ygsj() <= 37 then
					xx = xx + 1
				end

				local cs = 取随机数(xx, sx)
				self.参战单位[n].法术状态.咒符.层数 = math.min(self.参战单位[n].法术状态.咒符.层数 + cs, 5)
			end
		end

		if self:取奇经八脉是否有(n, "剑气") then
			self.参战单位[n].物理暴击等级 = self.参战单位[n].物理暴击等级 + 4
		end

		if self:取奇经八脉是否有(n, "冲霄", "通天行者") then
			self.参战单位[n].法伤 = self.参战单位[n].法伤 + 4
		end

		if self:取奇经八脉是否有(n, "蓄志") and self.参战单位[n].法术状态.炼气化神 ~= nil and self.参战单位[n].法术状态.生命之泉 ~= nil then
			self:增加愤怒(n, 3)
		end

		if self:取奇经八脉是否有(n, "灵威") then
			self:增加愤怒(n, ygsj(2))
		end

		if self:取奇经八脉是否有(n, "心浪") and self.参战单位[n].愤怒 ~= nil and self.参战单位[n].愤怒 < 50 then
			self:增加愤怒(n, ygsj(15))
		end

		if self:取奇经八脉是否有(n, "燎原") and self.参战单位[n].法术状态.牛劲 ~= nil then
			self:减少技能冷却(n, "秘传飞砂走石", 1)
			self:减少技能冷却(n, "秘传三昧真火", 1)
		end

		if qz(self.天气) == 2 and self:取奇经八脉是否有(n, "波濤") and self:取奇经八脉是否有(n, "龍骇") then
			self:添加状态("龍骇", self.参战单位[n])

			self.参战单位[n].法术状态.龍骇.层数 = math.min((self.参战单位[n].法术状态.龍骇.层数 or 0) + 1, 龍骇最高层数)
		end

		if self.参战单位[n].法术状态.津津有味 ~= nil and self.参战单位[n].玩家id ~= 0 and 扣除道具(self.参战单位[n].玩家id, "包子", 1) == false then
			self:取消状态("津津有味", self.参战单位[n])
			常规提示(self.参战单位[n].玩家id, "#P(津津有味)#W你身上的#Y包子#W不足、#R" .. self.参战单位[n].名称 .. "#W的#P津津有味#W效果消失")
		end

		if self.参战单位[n].法术状态.护盾 == nil then
			for w = 1, #self.参战玩家 do
				发送数据(self.参战玩家[w].连接id, 5507, {
					名称 = "护盾",
					id = n
				})
			end

			观战状态[#观战状态 + 1] = {
				名称 = "护盾",
				序号 = 5507,
				id = n
			}
		end

		if self.参战单位[n].倩影 ~= nil then
			if self.参战单位[n].速度 < self.参战单位[n].倩影.初速度 then
				local sd = qz1((self.参战单位[n].倩影.初速度 - self.参战单位[n].速度) * 0.12)
				self.参战单位[n].倩影.恢复速度 = self.参战单位[n].倩影.恢复速度 + sd
				self.参战单位[n].速度 = self.参战单位[n].速度 + sd
			else
				local sd = self.参战单位[n].速度 - self.参战单位[n].倩影.初速度

				if self.参战单位[n].倩影.恢复速度 > 0 then
					if self.参战单位[n].倩影.恢复速度 <= sd then
						self.参战单位[n].速度 = self.参战单位[n].速度 - self.参战单位[n].倩影.恢复速度
						self.参战单位[n].倩影.恢复速度 = 0
					else
						self.参战单位[n].速度 = self.参战单位[n].速度 - sd
						self.参战单位[n].倩影.恢复速度 = self.参战单位[n].倩影.恢复速度 - sd
					end
				end
			end
		end

		if self.参战单位[n].致命 ~= nil and self.参战单位[n].气血 < self.参战单位[n].最大气血 * 0.08 then
			local hp = self.参战单位[n].气血

			if self.参战单位[n].玩家id == 0 then
				hp = math.min(hp, self.参战单位[n].等级 * 20)
			end

			local sw = self:减少气血(n, hp)

			for w = 1, #self.参战玩家 do
				发送数据(self.参战玩家[w].连接id, 5508.2, {
					id = n,
					气血 = hp,
					死亡 = sw
				})
			end

			观战状态[#观战状态 + 1] = {
				序号 = 5508.2,
				id = n,
				气血 = hp,
				死亡 = sw
			}
		end

		if self.参战单位[n].威仪九霄 ~= nil then
			self.参战单位[n].威仪九霄 = self.参战单位[n].威仪九霄 + 1
		end

		if self.参战单位[n].薪火 ~= nil then
			self.参战单位[n].法伤 = self.参战单位[n].法伤 + self.参战单位[n].薪火
		end

		if self.参战单位[n].磐石 ~= nil then
			self.参战单位[n].磐石 = {
				伤害 = 0,
				单位 = {}
			}
		end

		self.队伍救人 = {}
		self.参战单位[n].扑袭 = nil
		self.参战单位[n].制怒 = nil
		self.参战单位[n].魂飞 = nil
		self.参战单位[n].炼魂 = nil
		self.参战单位[n].摧心 = nil
		self.参战单位[n].跃动 = nil
		self.参战单位[n].致命 = nil
		self.参战单位[n].焰威 = nil
		self.参战单位[n].傀儡 = nil
		self.参战单位[n].玲珑愤怒 = nil
		self.参战单位[n].溅射记录 = nil
		self.参战单位[n].恐怖判定 = false
		self.参战单位[n].爪印判定 = nil
		self.参战单位[n].守势判定 = nil
		self.参战单位[n].释放炎魂 = nil
		self.参战单位[n].浮空人数 = nil
		self.参战单位[n].怒火 = nil
		self.参战单位[n].助攻次数 = nil
		self.参战单位[n].法术助攻次数 = nil
		self.参战单位[n].九黎记录目标 = nil
		self.参战单位[n].不追击 = nil
		self.参战单位[n].临时速度 = 0
		self.参战单位[n].自动保护 = nil
		self.参战单位[n].柳暗花明防多次 = nil
		self.队伍战神 = {}

		if self.参战单位[n].披坚执锐 ~= nil then
			self.参战单位[n].披坚执锐 = self.参战单位[n].所有追加法术[ygsj(#self.参战单位[n].所有追加法术)].名称
		end

		if self.参战单位[n].宿幕星河 ~= nil then
			self.参战单位[n].宿幕星河法爆 = math.max(qz((self.参战单位[n].宿幕星河 + self.回合数) / 3), self.参战单位[n].宿幕星河法爆)
			self.参战单位[n].宿幕星河法爆 = math.min(self.参战单位[n].宿幕星河法爆, 30)
		end

		if self.参战单位[n].千斗金樽 ~= nil then
			self.参战单位[n].千斗金樽暴击 = math.max(qz((self.参战单位[n].千斗金樽 + self.回合数) / 3), self.参战单位[n].千斗金樽暴击)
			self.参战单位[n].千斗金樽暴击 = math.min(self.参战单位[n].千斗金樽暴击, 30)
		end

		if self.参战单位[n].待回复愤怒 ~= nil then
			self:增加愤怒(n, self.参战单位[n].待回复愤怒)

			self.参战单位[n].待回复愤怒 = nil
		end

		self.参战单位[n].破势 = nil

		if self:取奇经八脉是否有(n, "破势") then
			for i = 1, #self.参战单位 do
				if self.参战单位[i].队伍 ~= self.参战单位[n].队伍 and self.参战单位[i].死亡状态 == 2 then
					self.参战单位[n].破势 = 1

					break
				end
			end
		end

		if self:取奇经八脉是否有(n, "夜行") then
			if 昼夜参数 == 1 then
				if self.参战单位[n].夜行 == nil then
					self.参战单位[n].速度 = self.参战单位[n].速度 + 40
					self.参战单位[n].伤害 = self.参战单位[n].伤害 + 40
					self.参战单位[n].夜行 = 1
				end
			elseif self.参战单位[n].夜行 ~= nil then
				self.参战单位[n].速度 = self.参战单位[n].速度 - 40
				self.参战单位[n].伤害 = self.参战单位[n].伤害 - 40
				self.参战单位[n].夜行 = nil
			end
		end

		if self.参战单位[n].逍遥游 ~= nil then
			self.参战单位[n].逍遥游 = 1
		end

		if self.参战单位[n].上善若水 ~= nil then
			self.参战单位[n].上善若水 = 1
		end

		self.参战单位[n].已复活 = nil
		self.参战单位[n].出手 = 0
		self.参战单位[n].九幽回血 = nil
		self.参战单位[n].返回流程 = nil

		for k, v in pairs(判断护盾值状态) do
			if self.参战单位[n].法术状态[k] ~= nil and self.参战单位[n].法术状态[k].护盾值 ~= nil then
				self.参战单位[n].法术状态[k].护盾值 = qz(self.参战单位[n].法术状态[k].护盾值 * 0.85)

				if self.参战单位[n].法术状态[k].护盾值 < 1 then
					self:取消状态(k, self.参战单位[n])
				end
			end
		end

		if self:取奇经八脉是否有(n, "静岳") and self.参战单位[n].法术状态.护盾 == nil then
			self:添加护盾(n, self.参战单位[n].等级 * 3, n)
		end

		self.临时属性[n] = {}

		if self:取是否有指定状态(n, n, "天眼神通") then
			self:刷新战意(n, 1)
		end

		if self:取是否有指定状态(n, n, "真君显灵") then
			self:刷新战意(n, 1)
		end

		if self.参战单位[n].龍魂 ~= nil and self.参战单位[n].龍魂 >= 3 and (self.参战单位[n].法术状态.龍魂 == nil or self.参战单位[n].法术状态.龍魂.回合 <= 1) then
			self:添加状态("龍魂", self.参战单位[n])

			self.参战单位[n].法术状态.龍魂.回合 = 4

			if self:取奇经八脉是否有(n, "叱咤") then
				self.参战单位[n].法术状态.龍魂.造成法术伤害 = 15
			else
				self.参战单位[n].法术状态.龍魂.造成法术伤害 = 5
			end

			self.参战单位[n].龍魂 = 0
		end

		if self:取奇经八脉是否有(n, "普照") then
			self:取消状态("普照", self.参战单位[n])

			local gs = self:取我方拥有指定状态人数(n, "普渡众生", nil, "结算模式")

			if gs > 0 then
				self:添加状态("普照", self.参战单位[n], self.参战单位[n], gs, n)
			end
		end

		if self:取奇经八脉是否有(n, "庄严") then
			self:取消状态("庄严", self.参战单位[n])

			local gs = self:取敌方拥有指定状态人数(n, "紧箍咒", nil, "结算模式")

			if gs > 0 then
				self:添加状态("庄严", self.参战单位[n], self.参战单位[n], gs, n)
			end
		end

		if self:取奇经八脉是否有(n, "激怒") and ygsj() <= 10 then
			self:添加状态("蚀天", self.参战单位[n])

			self.参战单位[n].法术状态.蚀天.回合 = 5
		end

		if self.参战单位[n].法术状态.瘴气 ~= nil and self.参战单位[n].法术状态.天罗地网 ~= nil and self.队伍障眼 ~= nil then
			for k, v in pairs(self.队伍障眼) do
				if k ~= self.参战单位[n].队伍 and v[self.参战单位[n].法术状态.天罗地网.攻击编号] ~= nil and ygsj() <= 32 then
					self.参战单位[n].法术状态.天罗地网.回合 = self.参战单位[n].法术状态.天罗地网.回合 + 1
				end
			end
		end

		if self.参战单位[n].法术状态.含情脉脉 ~= nil and self.参战单位[n].法术状态.含情脉脉.安抚 ~= nil or self.参战单位[n].法术状态.魔音摄魂 ~= nil and self.参战单位[n].法术状态.魔音摄魂.安抚 ~= nil then
			local aa = {}

			if self.参战单位[n].法术状态.含情脉脉 ~= nil and self.参战单位[n].法术状态.含情脉脉.安抚 ~= nil then
				local bh = self.参战单位[n].法术状态.含情脉脉.安抚 + 0

				if self:取目标状态(bh, bh, 2) then
					aa[#aa + 1] = bh
				end
			end

			if self.参战单位[n].法术状态.魔音摄魂 ~= nil and self.参战单位[n].法术状态.魔音摄魂.安抚 ~= nil then
				local bh = self.参战单位[n].法术状态.魔音摄魂.安抚 + 0

				if self:取目标状态(bh, bh, 2) then
					aa[#aa + 1] = bh
				end
			end

			删除重复(aa)

			for i = 1, #aa do
				self:增加愤怒(aa[i], 4)
			end
		end

		if self.队伍利刃 ~= nil then
			for k, v in pairs(self.队伍利刃) do
				if k ~= self.参战单位[n].队伍 then
					self:减少魔法(n, 30)
				end
			end
		end

		if self.队伍结阵 ~= nil and self:取是否玩家角色(n) then
			for k, v in pairs(self.队伍结阵) do
				if k ~= self.参战单位[n].队伍 then
					if self.参战单位[n].结阵初速度 == nil then
						self.参战单位[n].结阵初速度 = self.参战单位[n].速度 + 0
					end

					if self.参战单位[n].结阵减少速度 == nil then
						self.参战单位[n].结阵减少速度 = 0
					end

					local js = 2

					if qz(self.参战单位[n].结阵初速度 * 0.2) < self.参战单位[n].结阵减少速度 + 2 then
						js = qz(self.参战单位[n].结阵初速度 * 0.2) - self.参战单位[n].结阵减少速度
					end

					if js > 0 then
						self.参战单位[n].结阵减少速度 = self.参战单位[n].结阵减少速度 + js
						self.参战单位[n].速度 = self.参战单位[n].速度 - js
					end
				end
			end
		end

		if (self.参战单位[n].法术状态.狂怒 == nil or self.参战单位[n].法术状态.狂怒.回合 <= 1) and self:取奇经八脉是否有(n, "狂怒") then
			self.参战单位[n].法术状态.狂怒 = nil
			local gl = 5

			if self:取奇经八脉是否有(n, "焦躁") then
				gl = gl + 5
			end

			if ygsj() <= gl + (self.参战单位[n].忿忿 or 0) or self.参战单位[n].困兽之斗 ~= nil then
				self:添加状态("狂怒", self.参战单位[n])
				常规提示(self.参战单位[n].玩家id, "#P(狂怒)#R" .. self.参战单位[n].名称 .. "#W进入了#S狂怒#W状态")

				self.参战单位[n].法术状态.狂怒.回合 = self.参战单位[n].法术状态.狂怒.回合 + 1
				self.参战单位[n].忿忿 = nil
				self.参战单位[n].困兽之斗 = nil

				if self.参战单位[n].激变 ~= nil then
					self.参战单位[n].法术状态.变身.回合 = self.参战单位[n].法术状态.变身.回合 + 1
					self.参战单位[n].激变 = nil
				end
			elseif self:取奇经八脉是否有(n, "忿忿") then
				self.参战单位[n].忿忿 = (self.参战单位[n].忿忿 or 0) + 1
			end
		end

		if self.参战单位[n].法术状态.偷龙转凤 ~= nil then
			local 魔法 = self.参战单位[n].法术状态.偷龙转凤.魔法 + 0

			self:增加魔法(n, 魔法)
		end

		if self.参战单位[n].法术状态.瘴气 ~= nil and self.参战单位[n].法术状态.瘴气.绝殇 ~= nil then
			self:增加愤怒(n, -1)
		end

		for i, v in pairs(self.参战单位[n].法术状态) do
			if self.战斗前附加状态 ~= 1 then
				self.参战单位[n].法术状态[i].回合 = self.参战单位[n].法术状态[i].回合 - 1
			end

			if self.参战单位[n].法术状态[i].回合 > 0 then
				if i == "进击必杀" or i == "进击法爆" and self.参战单位[n].法术状态[i].回合 < 5 and self.参战单位[n].法术状态[i].回合 > 0 then
					local 剩余回合 = self.参战单位[n].法术状态[i].回合 + 0

					self:取消状态(i, self.参战单位[n])
					self:添加状态(i, self.参战单位[n], self.参战单位[n], self.参战单位[n][i] or 1, n, 剩余回合 * 0.2)

					if self.参战单位[n].法术状态[i] ~= nil then
						self.参战单位[n].法术状态[i].回合 = 剩余回合 + 0
					else
						print(self.参战单位[n].名称 .. i .. tostring(self.参战单位[n][i]) .. 剩余回合)
						table.print(self.参战单位[n].已加技能)
					end
				elseif i == "龙魂" and self.参战单位[n].法术状态[i].回合 < 5 and self.参战单位[n].法术状态[i].回合 > 0 then
					local 剩余回合 = self.参战单位[n].法术状态[i].回合 + 0

					self:取消状态(i, self.参战单位[n])
					self:添加状态(i, self.参战单位[n], self.参战单位[n], 5 * 剩余回合 * 0.2)

					self.参战单位[n].法术状态[i].回合 = 剩余回合 + 0
				elseif i == "盾气" and self.参战单位[n].法术状态[i].回合 < 5 and self.参战单位[n].法术状态[i].回合 > 0 then
					local 剩余回合 = self.参战单位[n].法术状态[i].回合 + 0

					self:取消状态(i, self.参战单位[n])
					self:添加状态(i, self.参战单位[n], self.参战单位[n], self.参战单位[n].等级, n, (self.参战单位[n][i] or 2) * 剩余回合 * 0.2)

					self.参战单位[n].法术状态[i].回合 = 剩余回合 + 0
				elseif i == "魍魉追魂" then
					self.参战单位[n].法术状态[i].回合 = 999
					local gs = self:取我方拥有指定状态人数(n, i)
					self.参战单位[n].法术状态[i].造成物理伤害 = 4 + gs * 2
					self.参战单位[n].法术状态[i].造成法术伤害 = 4 + gs * 2
				elseif i == "明光宝烛" or i == "金身舍利" then
					if self.参战单位[n].法术状态[i].精进 ~= nil then
						local dj = self.参战单位[n].法术状态[i].等级 + 0
						local bh = self.参战单位[n].法术状态[i].攻击编号 + 0
						local hh = self.参战单位[n].法术状态[i].回合 + 0

						if self:取玩家战斗() then
							self.精进经脉 = self.参战单位[n].法术状态[i].精进 - 0.4
						else
							self.精进经脉 = self.参战单位[n].法术状态[i].精进 - 0.1
						end

						self:取消状态(i, self.参战单位[n])

						if self.精进经脉 <= 0 then
							self.精进经脉 = nil
						end

						self:添加状态(i, self.参战单位[n], self.参战单位[bh], dj, bh, 3447)

						self.参战单位[n].法术状态[i].回合 = hh + 0
					end

					if self.参战单位[n].法术状态[i].救人 ~= nil then
						if self.队伍救人 == nil then
							self.队伍救人 = {}
						end

						if self.队伍救人[self.参战单位[n].队伍] == nil then
							self.队伍救人[self.参战单位[n].队伍] = {}
						end

						self.队伍救人[self.参战单位[n].队伍][#self.队伍救人[self.参战单位[n].队伍] + 1] = n
					end
				elseif i == "碎甲符" and self.参战单位[n].法术状态[i].碎甲经脉 ~= nil then
					local dj = self.参战单位[n].法术状态[i].等级 + 0
					local bh = self.参战单位[n].法术状态[i].攻击编号 + 0
					local hh = self.参战单位[n].法术状态[i].回合 + 0
					self.碎甲经脉 = self.参战单位[n].法术状态[i].碎甲经脉 - 0.2

					self:取消状态(i, self.参战单位[n])

					if self.碎甲经脉 <= 1 then
						self.碎甲经脉 = nil
					end

					self:添加状态(i, self.参战单位[n], self.参战单位[bh], dj, bh, 3447)

					self.参战单位[n].法术状态[i].回合 = hh + 0
				elseif self.参战单位[n].法术状态[i].灵咒 ~= nil and self.参战单位[n].法术状态[i].回合 > 0 and (i == "失魂符" or i == "失心符" or i == "定身符") then
					local hh = self.参战单位[n].法术状态[i].回合 + 0
					local bh = self.参战单位[n].法术状态[i].攻击编号 + 0
					local dj = self.参战单位[n].法术状态[i].等级

					self:取消状态(i, self.参战单位[n])
					self:添加状态(i, self.参战单位[n], self.参战单位[bh], dj, bh, 3447)

					self.参战单位[n].法术状态[i].回合 = hh + 0
				end
			end

			if self.参战单位[n].法术状态[i] ~= nil then
				if self.参战单位[n].法术状态[i].回合 <= 0 then
					if i ~= "复活" then
						for w = 1, #self.参战玩家 do
							发送数据(self.参战玩家[w].连接id, 5507, {
								id = n,
								名称 = i
							})
						end

						观战状态[#观战状态 + 1] = {
							序号 = 5507,
							id = n,
							名称 = i
						}

						self:取消状态(i, self.参战单位[n], "正常消除")
					end

					if i == "超级永恒" and self.参战单位[n].超级永恒记录 ~= nil and self:取目标状态(n, n, 2) then
						self.参战单位[n].气血 = self.参战单位[n].超级永恒记录.气血 + 0
						self.参战单位[n].魔法 = self.参战单位[n].超级永恒记录.魔法 + 0
						self.参战单位[n].超级永恒记录 = nil
					elseif i == "渡劫金身" and self.参战单位[n].死亡状态 ~= 1 and self.参战单位[n].逃跑 ~= true then
						for w = 1, #self.参战玩家 do
							发送数据(self.参战玩家[w].连接id, 5508, {
								id = n,
								气血 = self.参战单位[n].最大气血
							})
						end

						self.参战单位[n].气血 = self.参战单位[n].最大气血
						self.参战单位[n].气血上限 = self.参战单位[n].最大气血 + 0

						if self.参战单位[n].类型 == "bb" then
							self.参战单位[n].气血上限 = nil
						end

						self.参战单位[n].法术状态.复活 = nil
					elseif i == "钟馗论道" then
						if self.参战单位[n].法术状态.锢魂术 ~= nil then
							self.参战单位[n].法术状态.锢魂术.回合 = self.参战单位[n].法术状态.锢魂术.回合 - 1
						end

						if self.参战单位[n].法术状态.死亡召唤 ~= nil then
							self.参战单位[n].法术状态.死亡召唤.回合 = self.参战单位[n].法术状态.死亡召唤.回合 - 1
						end
					elseif i == "复活" then
						self.参战单位[n].死亡状态 = nil
						self.参战单位[n].法术状态[i] = nil
						self.参战单位[n].气血 = self.参战单位[n].最大气血 + 0
						self.参战单位[n].气血上限 = self.参战单位[n].最大气血 + 0

						if self.参战单位[n].类型 == "bb" then
							self.参战单位[n].气血上限 = nil
						end

						for w = 1, #self.参战玩家 do
							发送数据(self.参战玩家[w].连接id, 5508, {
								id = n,
								气血 = self.参战单位[n].最大气血
							})
						end
					end
				elseif i == "渡劫金身" and self.参战单位[n].法术状态[i].回合 > 0 and self.参战单位[n].死亡状态 == 2 and self.参战单位[n].逃跑 ~= true then
					for w = 1, #self.参战玩家 do
						发送数据(self.参战玩家[w].连接id, 5508, {
							id = n,
							气血 = self.参战单位[n].最大气血
						})
					end

					self.参战单位[n].气血 = self.参战单位[n].最大气血
					self.参战单位[n].气血上限 = self.参战单位[n].最大气血 + 0

					if self.参战单位[n].类型 == "bb" then
						self.参战单位[n].气血上限 = nil
					end

					self.参战单位[n].法术状态.复活 = nil
					self.参战单位[n].法术状态[i] = nil
				elseif i == "分身术" then
					self.参战单位[n].法术状态[i].破解 = nil
				elseif i == "无尘扇" and self.参战单位[n].愤怒 ~= nil then
					local 愤怒 = v.愤怒

					if self.参战单位[n].法术状态.乾坤玄火塔 ~= nil then
						愤怒 = 愤怒 + 3
					end

					self:增加愤怒(n, -愤怒)
				elseif i == "乾坤玄火塔" then
					local 愤怒 = v.愤怒

					self:增加愤怒(n, 愤怒)
				end
			else
				print(i .. "_无状态")
			end
		end

		if self.参战单位[n].超级神迹 ~= nil and self:取目标状态(n, n, 2) then
			local 主人编号 = self.参战单位[n].超级神迹 + 0

			if self.参战单位[主人编号] ~= nil and self.参战单位[主人编号].类型 == "角色" and self.参战单位[主人编号].气血 <= 0 then
				self.参战单位[n].气血 = 0
				self.参战单位[n].死亡状态 = 1
				self.参战单位[n].超级神迹 = nil
				local hp = math.min(self.参战单位[主人编号].等级 * 20, self.参战单位[主人编号].最大气血)
				self.参战单位[主人编号].气血 = hp
				self.参战单位[主人编号].死亡状态 = nil

				for w = 1, #self.参战玩家 do
					发送数据(self.参战玩家[w].连接id, 5508, {
						id = 主人编号,
						气血 = hp
					})
					发送数据(self.参战玩家[w].连接id, 5508.1, {
						id = n
					})
				end

				观战状态[#观战状态 + 1] = {
					序号 = 5508,
					id = 主人编号,
					气血 = hp
				}
				观战状态[#观战状态 + 1] = {
					序号 = 5508.1,
					id = n
				}
				local 异常状态名称 = self:取异常封印法术状态()

				for m = 1, #异常状态名称 do
					if self.参战单位[主人编号].法术状态[异常状态名称[m]] ~= nil then
						for w = 1, #self.参战玩家 do
							发送数据(self.参战玩家[w].连接id, 5507, {
								id = 主人编号,
								名称 = 异常状态名称[m]
							})
						end

						观战状态[#观战状态 + 1] = {
							序号 = 5507,
							id = 主人编号,
							名称 = 异常状态名称[m]
						}

						self:取消状态(异常状态名称[m], self.参战单位[主人编号])
					end
				end

				if self.参战单位[主人编号].玩家id ~= 0 then
					常规提示(self.参战单位[主人编号].玩家id,
						"#P(超级神迹)#R" .. self.参战单位[n].名称 .. "#W牺牲了自己、复活了主人#R" .. self.参战单位[主人编号].名称 .. "#W且清除了#Y所有封印状态")
				end

				血量[主人编号] = self:取加载信息(主人编号)
			end
		end

		法术状态[n] = DeepCopy(self.参战单位[n].法术状态)

		if self.参战单位[n].门派 == "凌波城" then
			if 法术状态[n] == nil then
				法术状态[n] = {}
			end

			法术状态[n].战意 = self.参战单位[n].战意

			if (self.参战单位[n].超级战意 or 0) > 0 then
				法术状态[n].超级战意 = self.参战单位[n].超级战意
			end
		end

		血量[n] = self:取加载信息(n)

		if self.参战单位[n].陌宝 == true and self.参战单位[n].法术状态.日月乾坤 == nil then
			self.参战单位[n].陌宝 = nil
		end
	end

	法术状态[99] = {
		内容 = 2
	}

	for n = 1, #self.参战玩家 do
		self.参战玩家[n].断线等待 = nil

		发送数据(self.参战玩家[n].连接id, 5519, 法术状态)
		发送数据(self.参战玩家[n].连接id, 5520, 血量)
	end

	self:设置命令回合()

	self.战斗前附加状态 = 0

	if #观战状态 >= 1 then
		for n = 1, #观战状态 do
			for i, v in pairs(self.观战玩家) do
				if 玩家数据[i] ~= nil then
					发送数据(玩家数据[i].连接id, 观战状态[n].序号, 观战状态[n])
					发送数据(玩家数据[i].连接id, 5519, 法术状态)
				end
			end
		end
	end
end

function 战斗处理类:自动战斗目标处理(编号, 内容)
	self.参战单位[编号].指令 = table.loadstring(table.tostring(self.参战单位[编号].自动指令))

	if self.参战单位[编号] == nil then
		return
	elseif 内容.类型 == nil or 内容.类型 == "" then
		内容.类型 = "攻击"
	elseif 内容.类型 == "逃跑" then
		内容.目标 = 编号

		return
	end

	if 内容.类型 == "法术" then
		if 内容.技能名 == nil or 内容.技能名 == "" or self.参战单位[编号].主动技能1[内容.技能名] == nil and 通用特技1[内容.技能名] == nil then
			if type(内容.技能名) == "table" then
				for i = 1, #内容.技能名 do
					if self.参战单位[编号].主动技能1[内容.技能名[i][1]] == nil then
						内容.类型 = "攻击"

						break
					end
				end
			else
				内容.类型 = "攻击"
			end
		elseif self.参战单位[编号].智能目标 == true then
			if 通用特技1[内容.技能名] ~= nil and self:取特技状态(编号, 1) == false then
				内容.类型 = "攻击"
			elseif self:取法术状态(编号, 内容.技能名, 1) == false and 通用特技1[内容.技能名] == nil and (内容.技能名 ~= "雨落寒沙" or not self:取奇经八脉是否有(编号, "花影")) then
				内容.类型 = "攻击"
			end
		end
	end

	if 内容.类型 == "攻击" and self:取攻击状态(编号, 1) == false and self.参战单位[编号].智能目标 == true then
		内容.类型 = "防御"
	end

	if (玩家数据[self.参战单位[编号].玩家id].角色.数据.自动捉宠 or false) == true and 玩家数据[self.参战单位[编号].玩家id].角色:取新增宝宝数量() and (self.战斗类型 == 100001 or self.战斗类型 == 100005 or self.战斗类型 == 100007 or self.战斗类型 == 100221 or self.战斗类型 == 100225) then
		if self.参战单位[编号].类型 == "角色" and self.参战单位[编号].玩家id ~= 0 then
			if 判断是否为空表(self.可捕捉变异) and self.可捕捉列表添加 == nil then
				for n = 1, #self.参战单位 do
					if self.参战单位[n].队伍 ~= self.参战单位[编号].队伍 and (self.战斗类型 == 100225 or self.参战单位[n].变异 and self.参战单位[n].分类 == "变异" and string.find(self.参战单位[n].名称, "变异")) then
						self.可捕捉变异[#self.可捕捉变异 + 1] = n
					end
				end

				self.可捕捉列表添加 = 1
			end

			if #self.可捕捉变异 >= 1 then
				local i = math.ceil(取随机数(1, #self.可捕捉变异 * 1000) / 1000)
				local aa = true

				while aa do
					if self.参战单位[self.可捕捉变异[i]] ~= nil and self.参战单位[self.可捕捉变异[i]].气血 > 0 and not self.参战单位[self.可捕捉变异[i]].捕捉 and not self.参战单位[self.可捕捉变异[i]].逃跑 and self.参战单位[self.可捕捉变异[i]].死亡状态 == nil then
						内容.类型 = "捕捉"
						self.参战单位[编号].指令.目标 = self.可捕捉变异[i]
						aa = false
					else
						table.remove(self.可捕捉变异, i)

						if #self.可捕捉变异 >= 1 then
							i = math.ceil(取随机数(1, #self.可捕捉变异 * 1000) / 1000)
						else
							aa = false
						end
					end
				end
			end
		elseif self.战斗类型 == 100225 then
			内容.类型 = "防御"
		end
	end

	self.参战单位[编号].指令.类型 = 内容.类型

	if 内容.类型 == "法术" then
		if 内容.相对目标 ~= nil and (self:增益技能(内容.技能名) == true or self:恢复技能(内容.技能名) == true) then
			local dz = self.队长单位[self.参战单位[编号].队伍]
			内容.目标 = dz + 内容.相对目标
			self.参战单位[编号].自动指令.目标 = dz + 内容.相对目标
		end

		self.参战单位[编号].指令.参数 = 内容.技能名

		if 内容.目标 == nil or self.参战单位[内容.目标] == nil then
			if self:增益技能(内容.技能名) == true then
				self.参战单位[编号].指令.目标 = self:取单个友方无指定增益目标(编号, nil, 内容.技能名)

				if self.参战单位[编号].指令.目标 == 0 then
					self.参战单位[编号].指令.目标 = 编号

					if self.参战单位[编号].智能目标 == true then
						self.参战单位[编号].指令.类型 = "攻击"
					end
				end
			elseif self:封印技能(内容.技能名) == true then
				self.参战单位[编号].指令.目标 = self:取单个敌方可封印目标(编号)
			elseif self:恢复技能(内容.技能名) == true then
				if 复活技能[内容.技能名] ~= nil then
					local aa = nil

					if 内容.技能名 == "莲花心音" then
						aa = 1
					end

					local fh = self:取我方可复活(编号, aa)

					if #fh > 0 then
						local 判断 = false

						for i = 1, #fh do
							if 内容.目标 == fh[i] then
								self.参战单位[编号].指令.目标 = 内容.目标
								判断 = true

								break
							end
						end

						if not 判断 then
							self.参战单位[编号].指令.目标 = fh[ygsj(#fh)]
						end
					else
						self.参战单位[编号].指令.目标 = self:取单个友方目标(编号)

						if self.参战单位[编号].智能目标 == true then
							self.参战单位[编号].指令.类型 = "攻击"
						end
					end
				else
					self.参战单位[编号].指令.目标 = self:取我方气血百分比最低(编号)
				end
			else
				self.参战单位[编号].指令.目标 = self:取单个敌方目标(编号)
			end
		elseif self:增益技能(内容.技能名) == true then
			if self.参战单位[内容.目标].队伍 ~= self.队伍区分[1] or self.参战单位[内容.目标].法术状态[内容.技能名] ~= nil and self.参战单位[编号].智能目标 == true then
				self.参战单位[编号].指令.目标 = self:取单个友方无指定增益目标(编号, nil, 内容.技能名)

				if self.参战单位[编号].指令.目标 == 0 then
					self.参战单位[编号].指令.目标 = self:取单个友方目标(编号)

					if self.参战单位[编号].智能目标 == true then
						self.参战单位[编号].指令.类型 = "攻击"
					end
				end
			else
				self.参战单位[编号].指令.目标 = 内容.目标
			end
		elseif self:封印技能(内容.技能名) == true then
			if self.参战单位[内容.目标].队伍 == self.队伍区分[1] then
				self.参战单位[编号].指令.目标 = self:取单个敌方可封印目标(编号)
			else
				self.参战单位[编号].指令.目标 = 内容.目标

				if self:取封印状态(内容.目标) and self.参战单位[编号].智能目标 == true then
					self.参战单位[编号].指令.目标 = self:取单个敌方可封印目标(编号)

					if self.参战单位[编号].指令.目标 == 0 then
						self.参战单位[编号].指令.类型 = "攻击"
					end
				end
			end
		elseif self:恢复技能(内容.技能名) == true then
			if 复活技能[内容.技能名] ~= nil then
				if self.参战单位[编号].智能目标 == true then
					local aa = nil

					if 内容.技能名 == "莲花心音" then
						aa = 1
					end

					local fh = self:取我方可复活(编号, aa)

					if #fh > 0 then
						local 判断 = false

						for i = 1, #fh do
							if 内容.目标 == fh[i] then
								self.参战单位[编号].指令.目标 = 内容.目标
								判断 = true

								break
							end
						end

						if not 判断 then
							self.参战单位[编号].指令.目标 = fh[ygsj(#fh)]
						end
					else
						self.参战单位[编号].指令.类型 = "攻击"
						self.参战单位[编号].指令.目标 = self:取单个敌方目标(编号)
					end
				elseif self.参战单位[内容.目标].队伍 ~= self.队伍区分[1] then
					local aa = nil

					if 内容.技能名 == "莲花心音" then
						aa = 1
					end

					local fh = self:取我方可复活(编号, aa)

					if #fh > 0 then
						self.参战单位[编号].指令.目标 = fh[ygsj(#fh)]
					else
						self.参战单位[编号].指令.类型 = "防御"
					end
				else
					self.参战单位[编号].指令.目标 = 内容.目标
				end
			elseif self.参战单位[内容.目标].队伍 ~= self.队伍区分[1] then
				self.参战单位[编号].指令.目标 = self:取我方气血百分比最低(编号)
			else
				self.参战单位[编号].指令.目标 = 内容.目标

				if self.参战单位[编号].智能目标 == true then
					self.参战单位[编号].指令.目标 = self:取我方气血百分比最低(编号)
				end
			end
		elseif self.参战单位[内容.目标].队伍 == self.队伍区分[1] then
			self.参战单位[编号].指令.目标 = self:取单个敌方目标(编号)
		else
			self.参战单位[编号].指令.目标 = 内容.目标
		end
	elseif 内容.类型 == "攻击" then
		if 内容.目标 == nil or self.参战单位[内容.目标] == nil then
			self.参战单位[编号].指令.目标 = self:取单个敌方目标(编号)
		else
			self.参战单位[编号].指令.目标 = 内容.目标
		end
	elseif 内容.类型 == "保护" then
		if 内容.相对目标 ~= nil then
			local dz = self.队长单位[self.参战单位[编号].队伍]
			内容.目标 = dz + 内容.相对目标
			self.参战单位[编号].自动指令.目标 = dz + 内容.相对目标
		end

		if 内容.目标 == nil or self.参战单位[内容.目标] == nil or self.参战单位[内容.目标].队伍 ~= self.队伍区分[1] then
			self.参战单位[编号].指令.目标 = self:取单个友方目标(编号)
		else
			self.参战单位[编号].指令.目标 = 内容.目标
		end
	end

	self.参战单位[编号].指令.下达 = true

	if self.参战单位[编号].指令.目标 and self.参战单位[编号].自动指令.目标 == nil or self.参战单位[编号].自动指令.目标 == 0 then
		self.参战单位[编号].自动指令.目标 = self.参战单位[编号].指令.目标 + 0
	end
end

function 战斗处理类:数据处理(玩家id, 序号, 内容, 参数)
	if 序号 == 5506 then
		self:逃跑事件处理(玩家id)

		return
	elseif 序号 == 5510 then
		if 玩家数据[玩家id].观战 ~= nil and self.观战玩家[玩家id] ~= nil then
			if 自动遇怪[玩家id] ~= nil then
				自动遇怪[玩家id] = os.time()
			end

			if 自动捉鬼[玩家id] ~= nil then
				自动捉鬼[玩家id] = os.time()
			end

			发送数据(玩家数据[玩家id].连接id, 5505)

			玩家数据[玩家id].战斗 = 0
			玩家数据[玩家id].观战 = nil
			玩家数据[玩家id].遇怪时间 = os.time() + 取随机数(10, 20)
		end

		self.观战玩家[玩家id] = nil

		return
	elseif 序号 == 5598 then
		local 编号 = self:取参战编号(玩家id, "角色")
		local 目标 = {
			编号
		}

		if self.参战单位[编号].召唤兽 ~= nil then
			目标[2] = self.参战单位[编号].召唤兽
		end

		if self.参战单位[编号].助战明细 ~= nil then
			for i = 1, #self.参战单位[编号].助战明细 do
				目标[#目标 + 1] = self.参战单位[编号].助战明细[i]
			end
		end

		for n = 1, #内容 do
			if 内容[n] ~= nil and 内容[n][2] ~= "啊" and self.参战单位[目标[n]] ~= nil then
				if self.参战单位[目标[n]].类型 == "角色" and self.参战单位[目标[n]].助战编号 == nil then
					self.参战单位[目标[n]].默认法术 = 内容[n][2]
					玩家数据[self.参战单位[目标[n]].玩家id].角色.数据.默认法术 = 内容[n][2]
				elseif self.参战单位[目标[n]].类型 == "角色" and self.参战单位[目标[n]].助战编号 ~= nil then
					self.参战单位[目标[n]].默认法术 = 内容[n][2]
					玩家数据[self.参战单位[目标[n]].玩家id].助战.数据[self.参战单位[目标[n]].助战编号].默认法术 = 内容[n][2]
				else
					self.参战单位[目标[n]].默认法术 = 内容[n][2]

					if self.参战单位[目标[n]].类型 == "bb" and self.参战单位[目标[n]].认证码 ~= nil and self.参战单位[目标[n]].玩家id ~= 0 then
						local bb编号 = 玩家数据[self.参战单位[目标[n]].玩家id].召唤兽:取编号(self.参战单位[目标[n]].认证码)

						if bb编号 > 0 and 玩家数据[self.参战单位[目标[n]].玩家id].召唤兽.数据[bb编号] ~= nil then
							玩家数据[self.参战单位[目标[n]].玩家id].召唤兽.数据[bb编号].默认法术 = 内容[n][2]
						end
					end
				end
			end
		end

		return
	elseif 序号 == 5507.1 then
		local 编号 = 内容.单位
		local 目标单位 = 内容.目标

		if self.参战单位[编号].自动指令 == nil then
			self.参战单位[编号].自动指令 = {
				参数 = "",
				敌我 = 0,
				附加 = "",
				类型 = "",
				目标 = 0,
				下达 = false
			}
		end

		if self.参战单位[编号].玩家id == 玩家id then
			self.参战单位[编号].自动指令.目标 = 内容.目标

			if 内容.相对目标 ~= nil then
				self.参战单位[编号].自动指令.相对目标 = 内容.相对目标
			end

			self.参战单位[编号].自动指令.类型 = 内容.类型
			self.参战单位[编号].自动指令.参数 = 内容.技能名 or ""
			self.参战单位[编号].自动指令.下达 = true
			self.参战单位[编号].更新指令 = 1

			发送数据(玩家数据[玩家id].连接id, 5513, {
				{
					id = 内容.单位,
					自动 = self.参战单位[编号].自动指令
				}
			})

			if 内容.类型 == "道具" then
				self.参战单位[编号].自动指令.附加 = self.参战单位[编号].道具类型 or "道具"
			end

			if self.参战单位[编号].类型 == "角色" and self.参战单位[编号].助战编号 == nil then
				玩家数据[self.参战单位[编号].玩家id].角色.数据.自动指令 = table.loadstring(table.tostring(self.参战单位[编号].自动指令))
			elseif self.参战单位[编号].类型 == "角色" and self.参战单位[编号].助战编号 ~= nil then
				玩家数据[self.参战单位[编号].玩家id].助战.数据[self.参战单位[编号].助战编号].自动指令 = table.loadstring(table.tostring(self.参战单位[编号]
				.自动指令))
			else
				local bb编号 = 玩家数据[self.参战单位[编号].玩家id].召唤兽:取编号(self.参战单位[编号].认证码)

				if bb编号 ~= nil and bb编号 > 0 then
					玩家数据[self.参战单位[编号].玩家id].召唤兽.数据[bb编号].自动指令 = table.loadstring(table.tostring(self.参战单位[编号].自动指令))
				end
			end
		end

		return
	elseif 序号 == 5507.5 then
		local 编号 = 内容.编号

		if self.参战单位[编号].智能目标 == true then
			self.参战单位[编号].智能目标 = false

			常规提示(玩家id, "#R" .. self.参战单位[编号].名称 .. "#Y关闭了#P智能选择攻击施法目标")
		else
			self.参战单位[编号].智能目标 = true

			常规提示(玩家id, "#R" .. self.参战单位[编号].名称 .. "#Y开启了#P智能选择攻击施法目标")
		end

		发送数据(玩家数据[玩家id].连接id, 5508.5, {
			单位 = 编号,
			智能目标 = self.参战单位[编号].智能目标
		})

		if self.参战单位[编号].类型 == "bb" and self.参战单位[编号].认证码 ~= nil and self.参战单位[编号].预置bb == nil then
			local bh = 玩家数据[玩家id].召唤兽:取编号(self.参战单位[编号].认证码)

			if bh ~= 0 then
				local bb数据 = 玩家数据[玩家id].召唤兽.数据[bh]
				bb数据.智能目标 = self.参战单位[编号].智能目标
			end
		end
	elseif 序号 == 5507.4 then
		local 编号 = 内容.单位

		if self.参战单位[编号].九黎自动 == true then
			self.参战单位[编号].九黎自动 = false

			常规提示(玩家id, "#R" .. self.参战单位[编号].名称 .. "#Y关闭了#P自动使用组合技能")
		end

		发送数据(玩家数据[玩家id].连接id, 5508.4, {
			单位 = 编号,
			九黎自动 = self.参战单位[编号].九黎自动
		})
	elseif 序号 == 5507.3 then
		local 编号 = 内容.单位

		if self.参战单位[编号].门派 == "九黎城" then
			if self.参战单位[编号].九黎组合技能 == nil then
				self.参战单位[编号].九黎组合技能 = {}
			end

			if 内容.双技能 ~= nil then
				self.参战单位[编号].九黎组合技能.双技能 = DeepCopy(内容.双技能)
			end

			if 内容.三技能 ~= nil then
				self.参战单位[编号].九黎组合技能.三技能 = DeepCopy(内容.三技能)
			end

			if 内容.四技能 ~= nil then
				self.参战单位[编号].九黎组合技能.四技能 = DeepCopy(内容.四技能)
			end

			if 内容.不开启 == nil then
				self.参战单位[编号].九黎自动 = true

				常规提示(玩家id, "#R" .. self.参战单位[编号].名称 .. "#Y开启了#P自动使用组合技能#Y(当前自动栏若选择非门派法术则无效 如特技或攻击、防御则优先使用它们)")
			end

			发送数据(玩家数据[玩家id].连接id, 5508.4, {
				单位 = 编号,
				九黎自动 = self.参战单位[编号].九黎自动,
				九黎组合技能 = self.参战单位[编号].九黎组合技能
			})
		end
	elseif 序号 == 5597 then
		常规提示(玩家id, "遇到不可挽回的错误，为避免卡死、本次战斗自动结束。")
		print(玩家id .. "遇到不可挽回的错误，为避免卡死、本次战斗自动结束。")
		self:结束战斗2()
	elseif 序号 == 5599 then
		local 编号 = self:取参战编号(玩家id, "角色")

		if 内容 ~= nil and 内容.实时单位 ~= nil then
			编号 = 内容.实时单位
		end

		self.参战单位[编号].道具类型 = "道具"

		发送数据(玩家数据[玩家id].连接id, 5509.1, {
			类型 = "道具"
		})
		发送数据(玩家数据[玩家id].连接id, 5509, 玩家数据[玩家id].道具:索要道具2(玩家id))
	elseif 序号 == 5504 then
		发送数据(玩家数据[玩家id].连接id, 5509.1, {
			类型 = "道具"
		})
		发送数据(玩家数据[玩家id].连接id, 5509, 玩家数据[玩家id].道具:索要道具2(玩家id))
	elseif 序号 == 5508 then
		local 编号 = self:取参战编号(玩家id, "角色")

		if 内容 ~= nil and 内容.编号 ~= nil then
			编号 = 内容.编号 + 编号 - 1
		elseif 内容 ~= nil and 内容.实时单位 ~= nil then
			编号 = 内容.实时单位
		end

		self.参战单位[编号].道具类型 = "法宝"

		发送数据(玩家数据[玩家id].连接id, 5509.1, {
			类型 = "法宝"
		})
		发送数据(玩家数据[玩家id].连接id, 5509, 玩家数据[玩家id].道具:索要法宝1(玩家id, self.回合数))

		return
	elseif 序号 == 5505 then
		local 编号 = 0

		for n = 1, #self.参战单位 do
			if self.参战单位[n].类型 == "角色" and self.参战单位[n].玩家id == 玩家id and self.参战单位[n].助战编号 == nil then
				编号 = n
			end
		end

		if 编号 == 0 then
			return
		end

		发送数据(玩家数据[玩家id].连接id, 5510, {
			玩家数据[玩家id].召唤兽.数据,
			self.参战单位[编号].召唤总数量
		})

		return
	end

	if self.回合进程 == "加载回合" then
		if 序号 == 5501 then
			self.加载数量 = self.加载数量 - 1

			if self.加载数量 <= 0 then
				if self.战斗流程 ~= nil and #self.战斗流程 == 0 then
					self:设置命令回合()
				else
					self:发送加载流程()
				end
			end
		end
	elseif self.回合进程 == "命令回合" then
		if 序号 == 5502 then
			self.加载数量 = self.加载数量 - 1
			local 编号 = self:取参战编号(玩家id, "角色")
			local 目标 = {
				编号
			}

			if self.参战单位[编号].召唤兽 ~= nil then
				目标[2] = self.参战单位[编号].召唤兽
			end

			if self.参战单位[编号].助战明细 ~= nil then
				for i = 1, #self.参战单位[编号].助战明细 do
					目标[#目标 + 1] = self.参战单位[编号].助战明细[i]
				end
			end

			for n = 1, #内容 do
				if self.参战单位[目标[n]].逃跑 ~= true and self:减少气血(目标[n], 0) ~= 1 then
					self.参战单位[目标[n]].指令 = 内容[n]
					self.参战单位[目标[n]].指令.下达 = true
					self.参战单位[目标[n]].自动指令 = table.loadstring(table.tostring(内容[n]))

					if self.参战单位[目标[n]].类型 == "角色" and self.参战单位[目标[n]].助战编号 == nil then
						玩家数据[self.参战单位[目标[n]].玩家id].角色.数据.自动指令 = table.loadstring(table.tostring(内容[n]))
					elseif self.参战单位[目标[n]].类型 == "角色" and self.参战单位[目标[n]].助战编号 ~= nil then
						玩家数据[self.参战单位[目标[n]].玩家id].助战.数据[self.参战单位[目标[n]].助战编号].自动指令 = table.loadstring(table.tostring(
						内容[n]))
					else
						local bb编号 = 玩家数据[self.参战单位[目标[n]].玩家id].召唤兽:取编号(self.参战单位[目标[n]].认证码)
						玩家数据[self.参战单位[目标[n]].玩家id].召唤兽.数据[bb编号].自动指令 = table.loadstring(table.tostring(内容[n]))
					end

					if self.参战单位[目标[n]].指令.类型 == "攻击" and self.参战单位[目标[n]].指令.目标 == 0 then
						self.参战单位[目标[n]].指令.目标 = self:取单个敌方目标(目标[n])
					end
				end
			end

			if self.加载数量 <= 0 then
				self.回合进程 = "计算回合"

				self:设置执行回合()
			end
		elseif 序号 == 5507.2 then
			local 更改内容 = {}
			local 指令内容 = {}
			玩家数据[玩家id].角色.数据.自动战斗 = nil

			for n = 1, #self.参战单位 do
				if self.参战单位[n].玩家id == 玩家id then
					if self.参战单位[n].自动指令 ~= nil then
						self:自动战斗目标处理(n, {
							类型 = self.参战单位[n].自动指令.类型,
							技能名 = self.参战单位[n].自动指令.参数,
							目标 = self.参战单位[n].自动指令.目标,
							相对目标 = self.参战单位[n].自动指令.相对目标
						})
					else
						self.参战单位[n].指令.类型 = "攻击"
						self.参战单位[n].指令.目标 = self:取单个敌方目标(n)
					end

					self.参战单位[n].更新指令 = 1
					指令内容[#指令内容 + 1] = {
						id = n,
						自动 = self.参战单位[n].自动指令
					}
				end
			end

			常规提示(玩家id, "#Y/你刷新了自动指令技能")
			发送数据(玩家数据[玩家id].连接id, 5513, 指令内容)
		elseif 序号 == 5507 then
			local 更改内容 = {}
			local 指令内容 = {}

			if 玩家数据[玩家id].角色.数据.自动战斗 then
				for n = 1, #self.参战单位 do
					if self.参战单位[n].玩家id == 玩家id then
						self.参战单位[n].自动战斗 = nil
						更改内容[#更改内容 + 1] = {
							id = n,
							自动 = self.参战单位[n].自动战斗
						}
					end
				end

				常规提示(玩家id, "#Y/你取消了自动战斗")

				玩家数据[玩家id].角色.数据.自动战斗 = nil

				发送数据(玩家数据[玩家id].连接id, 5514, 更改内容)
			else
				玩家数据[玩家id].角色.数据.自动战斗 = true
				local 更改 = false

				for n = 1, #self.参战单位 do
					if self.参战单位[n].玩家id == 玩家id then
						self.参战单位[n].自动战斗 = true

						if self.参战单位[n].自动指令 ~= nil then
							self:自动战斗目标处理(n, {
								类型 = self.参战单位[n].自动指令.类型,
								技能名 = self.参战单位[n].自动指令.参数,
								目标 = self.参战单位[n].自动指令.目标,
								相对目标 = self.参战单位[n].自动指令.相对目标
							})
						else
							self.参战单位[n].指令.类型 = "攻击"
							self.参战单位[n].指令.目标 = self:取单个敌方目标(n)
						end

						self.参战单位[n].指令.下达 = true
						更改 = true
						指令内容[#指令内容 + 1] = {
							id = n,
							自动 = self.参战单位[n].自动指令
						}
						更改内容[#更改内容 + 1] = {
							id = n,
							自动 = self.参战单位[n].自动战斗
						}
					end
				end

				常规提示(玩家id, "#Y/你开启了自动战斗")
				发送数据(玩家数据[玩家id].连接id, 5511)
				发送数据(玩家数据[玩家id].连接id, 5513, 指令内容)
				发送数据(玩家数据[玩家id].连接id, 5514, 更改内容)

				if 更改 then
					self.加载数量 = self.加载数量 - 1

					if self.加载数量 <= 0 then
						self.回合进程 = "计算回合"

						self:设置执行回合()
					end
				end
			end
		end
	elseif self.回合进程 == "执行回合" then
		if 序号 == 5503 then
			self.加载数量 = self.加载数量 - 1
			self.执行等待 = os.time() + 10
			local 断线数量 = 0

			for n = 1, #self.参战玩家 do
				if self.参战玩家[n].断线等待 then
					断线数量 = 断线数量 + 1
				end
			end

			if self.加载数量 <= 0 and self.回合进程 ~= "结束回合" then
				self.回合进程 = "结束回合"

				self:结算处理()
			elseif self.加载数量 <= 断线数量 and self.回合进程 ~= "结束回合" then
				self.回合进程 = "结束回合"

				self:结算处理()
			end
		elseif 序号 == 5507 then
			local 更改内容 = {}
			local 指令内容 = {}

			if 玩家数据[玩家id].角色.数据.自动战斗 then
				for n = 1, #self.参战单位 do
					if self.参战单位[n].玩家id == 玩家id then
						self.参战单位[n].自动战斗 = nil
						更改内容[#更改内容 + 1] = {
							id = n,
							自动 = self.参战单位[n].自动战斗
						}
					end
				end

				常规提示(玩家id, "#Y/你取消了自动战斗")

				玩家数据[玩家id].角色.数据.自动战斗 = nil

				发送数据(玩家数据[玩家id].连接id, 5514, 更改内容)
			else
				玩家数据[玩家id].角色.数据.自动战斗 = true

				for n = 1, #self.参战单位 do
					if self.参战单位[n].玩家id == 玩家id then
						self.参战单位[n].自动战斗 = true
						更改内容[#更改内容 + 1] = {
							id = n,
							自动 = self.参战单位[n].自动战斗
						}
						指令内容[#指令内容 + 1] = {
							id = n,
							自动 = self.参战单位[n].自动指令
						}
					end
				end

				常规提示(玩家id, "#Y/你开启了自动战斗")
				发送数据(玩家数据[玩家id].连接id, 5513, 指令内容)
				发送数据(玩家数据[玩家id].连接id, 5514, 更改内容)
			end
		end
	end
end

function 战斗处理类:临时速度计算(编号)
	if self.参战单位[编号] ~= nil then
		self.参战单位[编号].临时速度 = self.参战单位[编号].临时速度 or 0

		if self.参战单位[编号].指令 ~= nil then
			if self.参战单位[编号].指令.参数 == "先发制人" then
				self.参战单位[编号].临时速度 = self.参战单位[编号].临时速度 + self.参战单位[编号].速度 * 0.8
			elseif self.参战单位[编号].指令.参数 == "长驱直入" then
				self.参战单位[编号].临时速度 = self.参战单位[编号].临时速度 + self.参战单位[编号].速度 * 1
			elseif self.参战单位[编号].指令.参数 == "雨润丰泽" then
				self.参战单位[编号].临时速度 = self.参战单位[编号].临时速度 + self.参战单位[编号].速度 * 0.5
			elseif self.参战单位[编号].玩家id ~= 0 and self.参战单位[编号].指令.参数 == "毁灭之光" then --and 毁灭之光测试通杀 then
				self.参战单位[编号].临时速度 = self.参战单位[编号].临时速度 + 0
			end
		end
	end
end

function 战斗处理类:设置执行回合()
	local 临时速度 = {}
	self.执行对象 = {}
	local 临时速度1 = {}

	for n = 1, #self.参战单位 do
		self.参战单位[n].九黎法术列表 = nil

		if self.参战单位[n].经脉有无 ~= nil and self.参战单位[n].经脉有无 then
			self:经脉回合开始处理(n)
		end

		if self.参战单位[n].洞察特性 ~= nil and ygsj() <= self.参战单位[n].洞察特性 * 5 and self:取玩家战斗() and self.参战单位[n].主人或助战 ~= nil and self.参战单位[self.参战单位[n].主人或助战] ~= nil then
			local 临时敌人 = self:取单个敌方目标(n)
			local 关键字 = "气血"

			if 取随机数(1, 2) == 1 then
				关键字 = "魔法"
			end

			if 临时敌人 ~= 0 then
				常规提示(self.参战单位[self.参战单位[n].主人或助战].玩家id,
					"#Y/你的召唤兽发现#G/" ..
					self.参战单位[临时敌人].名称 .. "#Y/当前#G/" .. 关键字 .. "#Y/剩余#G/" .. self.参战单位[临时敌人][关键字] .. "点")
			end
		elseif self.参战单位[n].灵动特性 ~= nil and self.参战单位[n].灵动次数 < 3 and ygsj() <= self.参战单位[n].灵动特性 * 5 then
			local 临时友方 = self:取单个友方目标(n)

			if 临时友方 ~= 0 then
				self.参战单位[n].灵动次数 = self.参战单位[n].灵动次数 + 1
				self.战斗发言数据[#self.战斗发言数据 + 1] = {
					id = n,
					内容 = self.参战单位[临时友方].名称 .. "大傻吊你睡觉了么#24"
				}
			end
		end

		if self.参战单位[n].指令 == nil then
			self.参战单位[n].指令 = {
				参数 = "",
				敌我 = 0,
				附加 = "",
				类型 = "",
				目标 = 0,
				下达 = false
			}
		end

		if self.参战单位[n].指令.下达 == false then
			self.参战单位[n].指令.下达 = true
			self.参战单位[n].指令.类型 = "攻击"
			self.参战单位[n].指令.目标 = self:取单个敌方目标(n)
		end

		self:临时速度计算(n)

		if self.参战单位[n].法术状态 ~= nil and self.参战单位[n].法术状态.齐天神通 ~= nil and ygsj() <= 50 and 神通技能列表[self.参战单位[n].指令.参数] ~= nil then
			临时速度[n] = {
				额外行动 = true,
				速度 = self.参战单位[n].速度 + (self.参战单位[n].临时速度 or 0),
				编号 = n
			}
		elseif self.参战单位[n].超级敏捷 ~= nil and self.参战单位[n].指令.参数 ~= "观照万象" and ygsj() <= self.参战单位[n].超级敏捷 then
			临时速度[n] = {
				额外行动 = true,
				速度 = self.参战单位[n].速度 + (self.参战单位[n].临时速度 or 0),
				编号 = n
			}

			if self.参战单位[n].玩家id ~= 0 then
				常规提示(self.参战单位[n].玩家id, "#P(超级敏捷)#R" .. self.参战单位[n].名称 .. "#W本回合将#Y额外行动一次")
			end
		elseif self.参战单位[n].门派 == "九黎城" and self.参战单位[n].指令.类型 == "法术" and self.参战单位[n].黎魂 ~= nil then
			临时速度[n] = {
				速度 = self.参战单位[n].速度 + (self.参战单位[n].临时速度 or 0),
				编号 = n,
				九黎次数 = self.参战单位[n].黎魂 - 1
			}
			self.参战单位[n].九黎法术列表 = {}

			if self.参战单位[n].九黎自动 == true and self.参战单位[n].九黎组合技能 ~= nil and self.参战单位[n].自动战斗 == true and self.参战单位[n].指令.类型 == "法术" and (九黎城攻击技能[self.参战单位[n].指令.参数] ~= nil or type(self.参战单位[n].指令.参数) == "table" and 九黎城攻击技能[self.参战单位[n].指令.参数[1][1]] ~= nil) then
				local aa = self.参战单位[n].九黎组合技能.双技能

				if self.参战单位[n].黎魂 == 3 then
					aa = self.参战单位[n].九黎组合技能.三技能
				elseif self.参战单位[n].黎魂 == 4 then
					aa = self.参战单位[n].九黎组合技能.四技能
				end

				for w = 1, #aa do
					if w <= self.参战单位[n].黎魂 then
						self.参战单位[n].九黎法术列表[#self.参战单位[n].九黎法术列表 + 1] = {
							aa[w],
							self.参战单位[n].指令.目标
						}
					else
						break
					end
				end
			elseif type(self.参战单位[n].指令.参数) == "table" then
				for w = 1, math.max(#self.参战单位[n].指令.参数, self.参战单位[n].黎魂) do
					if w <= self.参战单位[n].黎魂 then
						if self.参战单位[n].指令.参数[w] ~= nil then
							self.参战单位[n].九黎法术列表[#self.参战单位[n].九黎法术列表 + 1] = DeepCopy(self.参战单位[n].指令.参数[w])
						else
							self.参战单位[n].九黎法术列表[#self.参战单位[n].九黎法术列表 + 1] = DeepCopy(self.参战单位[n].指令.参数
							[#self.参战单位[n].指令.参数])
						end
					else
						break
					end
				end
			elseif 九黎城攻击技能[self.参战单位[n].指令.参数] ~= nil then
				for w = 1, self.参战单位[n].黎魂 do
					self.参战单位[n].九黎法术列表[#self.参战单位[n].九黎法术列表 + 1] = {
						self.参战单位[n].指令.参数,
						self.参战单位[n].指令.目标
					}
				end
			else
				临时速度[n].九黎次数 = nil
			end

			if self:取奇经八脉是否有(n, "飞扬") then
				self.参战单位[n].飞扬生效 = nil
				local aa = {}
				local aa1 = {
					"力辟苍穹",
					"三荒尽灭",
					"三荒尽灭"
				}

				if #self.参战单位[n].九黎法术列表 >= 3 then
					for w = 1, #self.参战单位[n].九黎法术列表 do
						if self.参战单位[n].九黎法术列表[#self.参战单位[n].九黎法术列表 - w + 1] == "力辟苍穹" then
							aa = {
								"力辟苍穹"
							}
						elseif self.参战单位[n].九黎法术列表[#self.参战单位[n].九黎法术列表 - w + 1] == "三荒尽灭" and #aa > 0 then
							aa[#aa + 1] = "三荒尽灭"
						end

						if #aa == 3 then
							for r = 1, 3 do
								if aa[r] ~= aa1[r] then
									aa = {}

									break
								elseif r == 3 then
									self.参战单位[n].飞扬生效 = 1
								end
							end
						end

						if self.参战单位[n].飞扬生效 ~= nil then
							break
						end
					end
				end
			end
		else
			临时速度[n] = {
				速度 = self.参战单位[n].速度 + (self.参战单位[n].临时速度 or 0),
				编号 = n
			}
		end

		if self.参战单位[n].队伍 == 0 then
			local 临时数据 = self:NPC智能施法(self.战斗类型, n, self.参战单位[n].主动技能)

			if self.战斗脚本 and self.战斗脚本.NPC智能施法 then
				local 脚本执行结果 = __gge.safecall(self.战斗脚本.NPC智能施法, self, n, self.参战单位[n], self.回合数)

				if 脚本执行结果 and 脚本执行结果.下达 == true then
					临时数据 = 脚本执行结果
				end
			end

			if 临时数据.下达 then
				self.参战单位[n].指令.类型 = 临时数据.类型
				self.参战单位[n].指令.参数 = 临时数据.参数
				self.参战单位[n].指令.目标 = 临时数据.目标
			end
		end
	end

	table.sort(临时速度, function(a, b)
		return b.速度 < a.速度
	end)

	for n = 1, #临时速度 do
		self.执行对象[#self.执行对象 + 1] = 临时速度[n].编号

		if 临时速度[n].额外行动 then
			self.执行对象[#self.执行对象 + 1] = 临时速度[n].编号
		elseif 临时速度[n].九黎次数 ~= nil then
			for w = 1, 临时速度[n].九黎次数 do
				self.执行对象[#self.执行对象 + 1] = 临时速度[n].编号
			end
		end
	end

	self.战斗流程 = {}
	self.执行等待 = 0

	self:执行计算()

	if self.回合中复活 then
		self.回合中复活 = false
		local 速度减少 = {}
		local 最后出手 = {}
		self.执行中复活单位 = 数组去重(self.执行中复活单位)

		if #self.是否执行行动 == 0 then
			self.执行中复活单位 = {}
		else
			for i = 1, #self.执行中复活单位 do
				for n = 1, #self.是否执行行动 do
					if self.执行中复活单位[i] == self.是否执行行动[n] then
						速度减少[#速度减少 + 1] = self.是否执行行动[n]

						break
					end

					if n == #self.是否执行行动 then
						最后出手[#最后出手 + 1] = self.是否执行行动[n]
					end
				end
			end

			table.sort(速度减少, function(a, b)
				return self.参战单位[a].速度 + (self.参战单位[a].临时速度 or 0) > self.参战单位[b].速度 + (self.参战单位[b].临时速度 or 0)
			end)
			table.sort(最后出手, function(a, b)
				return self.参战单位[a].速度 + (self.参战单位[a].临时速度 or 0) > self.参战单位[b].速度 + (self.参战单位[b].临时速度 or 0)
			end)

			self.执行对象 = {}

			for n = 1, #速度减少 do
				for i = 1, #临时速度 do
					if 速度减少[n] == 临时速度[i].编号 then
						self.执行对象[#self.执行对象 + 1] = 临时速度[i].编号

						if 临时速度[i].额外行动 then
							self.执行对象[#self.执行对象 + 1] = 临时速度[i].编号
						end
					end
				end
			end

			for n = 1, #最后出手 do
				for i = 1, #临时速度 do
					if 最后出手[n] == 临时速度[i].编号 then
						self.执行对象[#self.执行对象 + 1] = 临时速度[i].编号

						if 临时速度[i].额外行动 then
							self.执行对象[#self.执行对象 + 1] = 临时速度[i].编号
						end
					end
				end
			end

			速度减少 = {}
			最后出手 = {}

			self:执行计算1(true)
		end
	end

	self.执行中复活单位 = {}
	self.是否执行行动 = {}

	self:执行计算3()

	for n = 1, #self.参战单位 do
		if self.参战单位[n].救主 ~= nil and self.参战单位[n].玩家id ~= 0 and self.参战单位[self.参战单位[n].救主].死亡状态 == 2 and ygsj() <= 50 then
			local zr = self.参战单位[n].救主

			if self.参战单位[zr].法术状态.死亡召唤 == nil and self.参战单位[zr].法术状态.锢魂术 == nil then
				local 九转位置 = 取指定道具背包位置(self.参战单位[n].玩家id, "九转回魂丹")

				if 九转位置 ~= 0 then
					self.参战单位[n].道具类型 = "道具"
					local aa = DeepCopy({
						self.参战单位[n].指令.目标,
						self.参战单位[n].指令.参数,
						self.参战单位[n].指令.类型
					})
					self.参战单位[n].指令.目标 = zr
					self.参战单位[n].指令.参数 = 九转位置
					self.参战单位[n].指令.类型 = "道具"

					self:道具计算(n)

					self.参战单位[n].指令.目标 = aa[1]
					self.参战单位[n].指令.参数 = aa[2]
					self.参战单位[n].指令.类型 = aa[3]
				end
			end
		end
	end

	self.执行等待 = self.执行等待 + os.time()
	local 法术状态 = {}

	for i = 1, #self.参战玩家 do
		local 血量数据 = {}

		for n = 1, #self.参战单位 do
			if self.参战单位[n].气血 < 0 then
				self.参战单位[n].气血 = 0
			end

			if self.参战单位[n].气血上限 == nil then
				self.参战单位[n].气血上限 = self.参战单位[n].最大气血
			end

			if self.参战单位[n].气血上限 < 0 then
				self.参战单位[n].气血上限 = 0
			end

			if self.参战单位[n].最大气血 < self.参战单位[n].气血上限 then
				self.参战单位[n].气血上限 = self.参战单位[n].最大气血
			end

			if self.参战单位[n].气血上限 < self.参战单位[n].气血 then
				self.参战单位[n].气血 = self.参战单位[n].气血上限
			end

			if self.参战单位[n].魔法 < 0 then
				self.参战单位[n].魔法 = 0
			end

			if self.参战单位[n].类型 == "bb" then
				self.参战单位[n].气血上限 = nil
			end

			法术状态[n] = DeepCopy(self.参战单位[n].法术状态)

			if self.参战单位[n].门派 == "凌波城" then
				法术状态[n].战意 = self.参战单位[n].战意
			end
		end

		法术状态[99] = {
			内容 = 3
		}

		发送数据(self.参战玩家[i].连接id, 5504, self.战斗流程)
		发送数据(self.参战玩家[i].连接id, 5519, 法术状态)
	end

	for i, v in pairs(self.观战玩家) do
		if 玩家数据[i] ~= nil then
			发送数据(玩家数据[i].连接id, 5504, self.战斗流程)
			发送数据(玩家数据[i].连接id, 5519, 法术状态)
		end
	end

	self.加载数量 = #self.参战玩家
	self.执行等待 = os.time() + 10 + #self.战斗流程 * 6
	self.最低执行时间 = os.time() + #self.战斗流程 * 1 - 5
	self.回合进程 = "执行回合"
end

function 战斗处理类:取首回合增益技能(技能列表)
	local aa = {}

	for i = 1, #技能列表 do
		if 首回合增益技能[技能列表[i]] ~= nil then
			aa[#aa + 1] = 技能列表[i]
		end
	end

	if #aa > 0 then
		return aa[ygsj(#aa)]
	else
		return false
	end
end

function 战斗处理类:NPC智能施法(战斗类型, 编号, 怪物技能)
	local 返回数据 = {
		类型 = "",
		目标 = 0,
		参数 = "",
		下达 = false
	}
	local 临时封印技能 = {}
	local 临时特技技能 = {}
	local 临时辅助技能 = {}
	local 临时恢复技能 = {}
	local 临时增益技能 = {}
	local 临时伤害技能 = {}
	local 临时变身技能 = {}
	local 临时复活技能 = {}
	local 是否选择技能 = false

	if #怪物技能 > 0 then
		for i = 1, #怪物技能 do
			if 装备特技[怪物技能[i].名称] ~= nil and self:取特技状态(编号, 1) then
				if self.参战单位[编号].愤怒 == nil or self.参战单位[编号].愤怒 < 150 then
					self.参战单位[编号].愤怒 = 9999
				end

				if 复活技能[怪物技能[i].名称] ~= nil then
					临时复活技能[#临时复活技能 + 1] = 怪物技能[i].名称
				else
					临时特技技能[#临时特技技能 + 1] = 怪物技能[i].名称
				end
			elseif self:封印技能(怪物技能[i].名称) and self:取法术状态(编号, 怪物技能[i].名称, 1) then
				临时封印技能[#临时封印技能 + 1] = 怪物技能[i].名称
			elseif self:变身技能(怪物技能[i].名称) and self:取法术状态(编号, 怪物技能[i].名称, 1) then
				临时变身技能[#临时变身技能 + 1] = 怪物技能[i].名称
			elseif self:恢复技能(怪物技能[i].名称) and self:取法术状态(编号, 怪物技能[i].名称, 1) then
				if 复活技能[怪物技能[i].名称] ~= nil then
					临时复活技能[#临时复活技能 + 1] = 怪物技能[i].名称
				else
					临时辅助技能[#临时辅助技能 + 1] = 怪物技能[i].名称
					临时恢复技能[#临时恢复技能 + 1] = 怪物技能[i].名称
				end
			elseif (self:增益技能(怪物技能[i].名称) or self:减益技能(怪物技能[i].名称)) and self:取法术状态(编号, 怪物技能[i].名称, 1) then
				临时辅助技能[#临时辅助技能 + 1] = 怪物技能[i].名称
				临时增益技能[#临时增益技能 + 1] = 怪物技能[i].名称
			elseif self:取法术状态(编号, 怪物技能[i].名称, 1) then
				临时伤害技能[#临时伤害技能 + 1] = 怪物技能[i].名称
			end
		end
	end

	if not 判断是否为空表(self.参战单位[编号].追加法术) and self:取攻击状态(编号, 1) then
		返回数据.类型 = "攻击"
		返回数据.参数 = ""

		if self.参战单位[编号].指定攻击目标 ~= nil then
			返回数据.目标 = self:取单个敌方指定目标(编号, self.参战单位[编号].指定攻击目标[1], self.参战单位[编号].指定攻击目标[2])
		else
			返回数据.目标 = self:取单个敌方目标(编号)
		end

		返回数据.下达 = true
	elseif #怪物技能 > 0 then
		if not 判断是否为空表(临时复活技能) and not 返回数据.下达 then
			local fh = self:取我方可复活(编号)
			local n, mb, jn = nil
			local zx = false

			if #fh > 0 then
				local 临时复活 = 列表模式转换(临时复活技能)
				local 次数 = 1

				while #fh > 0 and zx == false do
					mb = 取随机数(1, #fh)
					n = fh[mb]

					if 次数 == 1 then
						for w = 1, #fh do
							if fh[w] == 1 then
								mb = w + 0
								n = 1

								break
							end
						end
					end

					if self.参战单位[n].法术状态.死亡召唤 ~= nil or self.参战单位[n].法术状态.锢魂术 ~= nil then
						if 临时复活.杨柳甘露 ~= nil and (self.参战单位[n].法术状态.死亡召唤 == nil or self.参战单位[n].法术状态.死亡召唤.回合 <= 2) and (self.参战单位[n].法术状态.锢魂术 == nil or self.参战单位[n].法术状态.锢魂术.回合 <= 2) then
							jn = "杨柳甘露"

							if self:取奇经八脉是否有(编号, "甘露") then
								self.参战单位[n].甘露 = 1
							end

							zx = true
						end
					elseif self.参战单位[n].鬼魂 ~= nil then
						if 临时复活.莲花心音 ~= nil then
							jn = "莲花心音"
							zx = true
						end
					else
						local 临时复活技能1 = 列表2加入到列表1({}, 临时复活技能)

						if 临时复活.莲花心音 ~= nil then
							table.remove(临时复活技能1, 临时复活.莲花心音)
						end

						if #临时复活技能1 > 0 then
							jn = 临时复活技能1[取随机数(1, #临时复活技能1)]
							zx = true
						end
					end

					if zx then
						返回数据.类型 = "法术"
						返回数据.参数 = jn
						返回数据.目标 = n
						返回数据.下达 = true
						self.参战单位[n].已复活 = 1
					else
						table.remove(fh, mb)

						次数 = 次数 + 1
					end
				end
			end
		end

		if not 判断是否为空表(临时封印技能) and not 返回数据.下达 then
			local 当前技能 = 临时封印技能[取随机数(1, #临时封印技能)]
			local 取目标 = self:NPC_AI取敌方可封印单位(编号)

			if 取目标 ~= 0 then
				返回数据.类型 = "法术"
				返回数据.参数 = 当前技能
				返回数据.目标 = 取目标
				返回数据.下达 = true
			end
		end

		if not 判断是否为空表(临时变身技能) and self.参战单位[编号].法术状态.变身 == nil and not 返回数据.下达 and self.参战单位[编号].无需变身 == nil then
			local 当前技能 = 临时变身技能[取随机数(1, #临时变身技能)]
			local 技能类型 = 取法术技能(当前技能)
			local 取目标 = 0

			if 技能类型[3] == 4 then
				取目标 = self:NPC_AI取目标队伍无指定增益状态(编号, 当前技能, "敌方")
			else
				取目标 = self:NPC_AI取目标队伍无指定增益状态(编号, 当前技能, "友方")
			end

			if 取目标 ~= 0 then
				返回数据.类型 = "法术"
				返回数据.参数 = 当前技能
				返回数据.目标 = 取目标
				返回数据.下达 = true
			end
		end

		if not 判断是否为空表(临时辅助技能) and not 返回数据.下达 then
			local 当前技能 = 临时辅助技能[取随机数(1, #临时辅助技能)]

			if self.回合数 == 1 and #临时增益技能 > 0 then
				当前技能 = self:取首回合增益技能(临时增益技能)
			end

			if self.回合数 == 1 and #临时增益技能 > 0 and 当前技能 ~= false then
			elseif #临时增益技能 > 0 and #临时恢复技能 > 0 then
				if ygsj() <= 80 then
					当前技能 = 临时恢复技能[取随机数(1, #临时恢复技能)]
				else
					当前技能 = 临时增益技能[取随机数(1, #临时增益技能)]
				end
			end

			local 技能类型 = 取法术技能(当前技能)
			local 取目标 = 0

			if 技能类型[3] == 4 then
				取目标 = self:NPC_AI取目标队伍无指定增益状态(编号, 当前技能, "敌方")
			else
				取目标 = self:NPC_AI取目标队伍无指定增益状态(编号, 当前技能, "友方")
			end

			if 取目标 ~= 0 then
				返回数据.类型 = "法术"
				返回数据.参数 = 当前技能
				返回数据.目标 = 取目标
				返回数据.下达 = true
			end
		end

		if not 判断是否为空表(临时伤害技能) and (not 返回数据.下达 or ygsj() >= 50) then
			local 当前技能 = 临时伤害技能[取随机数(1, #临时伤害技能)]
			local 技能类型 = 取法术技能(当前技能)
			local 取目标 = 0

			if 技能类型[3] == 4 then
				if self.参战单位[编号].指定攻击目标 ~= nil then
					取目标 = self:取单个敌方指定目标(编号, self.参战单位[编号].指定攻击目标[1], self.参战单位[编号].指定攻击目标[2])
				else
					取目标 = self:取单个敌方目标(编号)
				end
			else
				取目标 = self:取单个友方目标(编号)
			end

			if 取目标 ~= 0 then
				返回数据.类型 = "法术"
				返回数据.参数 = 当前技能
				返回数据.目标 = 取目标
				返回数据.下达 = true
			end
		end

		if 返回数据.下达 and 返回数据.类型 == "法术" and self:技能消耗(self.参战单位[编号], 5, 返回数据.参数, 编号) == false then
			返回数据.下达 = false
		end

		if not 返回数据.下达 then
			if self:取攻击状态(编号, 1) or self:取休息状态(编号) then
				返回数据.类型 = "攻击"
				返回数据.参数 = ""
				返回数据.目标 = self:取单个敌方目标(编号)
				返回数据.下达 = true
			else
				返回数据.类型 = "防御"
				返回数据.参数 = ""
				返回数据.目标 = 0
				返回数据.下达 = true
			end
		end
	end

	if self.参战单位[编号].智能感知 == nil and self:取隐身单位比例() then
		for n = 1, #self.参战单位 do
			if self.参战单位[n].智能感知 == nil and self.参战单位[n].气血 >= 1 and self.参战单位[n].队伍 == self.队伍区分[2] then
				self.参战单位[n].感知 = 1.3
				self.参战单位[n].智能感知 = 1
			end
		end

		self.战斗发言数据[#self.战斗发言数据 + 1] = {
			内容 = "躲躲藏藏算什么英雄好汉！\n你们已经#P无所遁形#W啦#18",
			id = 编号
		}
	end

	if 战斗类型 == 100004 and self.参战单位[编号].变异 and self.回合数 >= 2 then
		返回数据.类型 = "逃跑"
		返回数据.目标 = 0
		返回数据.参数 = ""
		返回数据.下达 = true
	elseif self.战斗类型 == 110002 and self.参战单位[编号].名称 == "蚩尤" and self.回合数 == 1 then
		self.战斗发言数据[#self.战斗发言数据 + 1] = {
			内容 = "不要做无畏挣扎\n赶紧#R/受死吧!",
			id = 编号
		}
	elseif self.战斗类型 == 110005 and self.参战单位[编号].名称 == "妖风" and self.回合数 == 1 then
		self.战斗发言数据[#self.战斗发言数据 + 1] = {
			内容 = "不不不\n这#R/不可能!",
			id = 编号
		}
	elseif self.战斗类型 == 110009 and self.参战单位[编号].名称 == "白琉璃" and self.回合数 == 9 then
		self.战斗发言数据[#self.战斗发言数据 + 1] = {
			内容 = "小东西\n你#Y/完蛋了!",
			id = 编号
		}
	elseif self.战斗类型 == 100225 and self.参战单位[编号].门派 == "神兽" and self.回合数 == 1 then
		self.战斗发言数据[#self.战斗发言数据 + 1] = {
			内容 = "小吊毛\n想抓我?#3",
			id = 编号
		}
	elseif self.战斗类型 == 100225 and self.参战单位[编号].门派 == "神兽" and self.回合数 == 3 then
		self.战斗发言数据[#self.战斗发言数据 + 1] = {
			内容 = "拜拜了\n看我逃跑#4",
			id = 编号
		}
	elseif self.战斗类型 == 134481.6 and self.回合数 % 2 == 0 and self.参战单位[编号].队伍 == 0 and (self.参战单位[编号].名称 == "舍身取义·惧法" or self.参战单位[编号].名称 == "金刚不坏·惧物") and self.参战单位[编号].气血 > 0 then
		if self.参战单位[编号].名称 == "舍身取义·惧法" then
			返回数据.类型 = "法术"
			返回数据.下达 = true
			local fh = self:取我方可复活(编号)

			if #fh > 0 and ygsj() <= 50 then
				返回数据.目标 = fh[1]
				返回数据.参数 = "起死回生"
			else
				返回数据.目标 = self:取单个友方目标(编号)
				返回数据.参数 = "牺牲·舍身取义"
			end
		else
			返回数据.类型 = "法术"
			返回数据.下达 = true
			返回数据.目标 = self:取单个友方目标(编号)
			返回数据.参数 = "牺牲·菩提心佑"
		end
