function 战斗处理类:发送加载流程()
	local 法术状态 = {}

	for i = 1, #self.参战玩家 do
		local 血量数据 = {}

		for n = 1, #self.参战单位 do
			if self.参战单位[n].玩家id == self.参战玩家[i].id then
				if self.参战单位[n].类型 == "角色" and self.参战单位[n].助战编号 == nil then
					血量数据[1] = {
						气血 = self.参战单位[n].气血,
						最大气血 = self.参战单位[n].最大气血,
						气血上限 = self.参战单位[n].气血上限 or self.参战单位[n].最大气血,
						魔法 = self.参战单位[n].魔法,
						最大魔法 = self.参战单位[n].最大魔法,
						愤怒 = self.参战单位[n].愤怒
					}
				elseif self.参战单位[n].类型 == "bb" then
					血量数据[2] = {
						气血 = self.参战单位[n].气血,
						最大气血 = self.参战单位[n].最大气血,
						魔法 = self.参战单位[n].魔法,
						最大魔法 = self.参战单位[n].最大魔法
					}
				end
			end

			法术状态[n] = DeepCopy(self.参战单位[n].法术状态)

			if self.参战单位[n].门派 == "凌波城" then
				法术状态[n].战意 = self.参战单位[n].战意
			end
		end

		法术状态[99] = {
			内容 = 1
		}

		发送数据(self.参战玩家[i].连接id, 5504, self.战斗流程)
		发送数据(self.参战玩家[i].连接id, 5506, 血量数据)
		发送数据(self.参战玩家[i].连接id, 5519, 法术状态)
	end

	self.执行等待 = self.执行等待 + os.time()
	self.加载数量 = #self.参战玩家
	self.回合进程 = "执行回合"
end

function 战斗处理类:执行计算()
	for n = 1, #self.参战单位 do
		if self:法宝判断("七宝玲珑灯", n) ~= false then
			local 法宝名称 = "七宝玲珑灯"

			for i = 1, #self.参战单位[n].法宝列表[法宝名称] do
				local 法宝位置 = self.参战单位[n].法宝列表[法宝名称][i]
				local 境界 = self:法宝概率判断(法宝名称, n, 法宝位置, 1)

				if 境界 ~= false then
					local 目标2 = 0
					目标2 = self:取单个友方目标1(n)

					if self.参战单位[n].气血 > 0 and 目标2 ~= 0 and 目标2 ~= 0 then
						self:恢复技能计算(n, "七宝玲珑灯", 境界)
					end
				end
			end
		end
	end

	local 生命之泉回复 = {}
	local 再生回复 = {}
	local 普渡众生回复 = {}
	local 宝烛回复 = {}
	local 毒扣血 = {}
	local 机巧扣血 = {}
	local 轻霜扣血 = {}
	local 雾杀扣血 = {}

	for n = 1, #self.参战单位 do
		if qz(self.天气) == 1 and self:取奇经八脉是否有(n, "灵归") then
			self:刷新风灵(n, 1)
		end

		if self.参战单位[n].逃跑 ~= true and self.参战单位[n].死亡状态 ~= 1 then
			if self.参战单位[n].法术状态.分身术 ~= nil then
				local 编号 = self.参战单位[n].法术状态.分身术.攻击编号

				if 编号 ~= nil and self:取奇经八脉是否有(编号, "调息") and self:取目标状态(n, n, 2) then
					气血 = qz(self.参战单位[n].最大气血 * 0.05)

					self:增加气血(n, 气血)
					self:增加魔法(n, qz(self.参战单位[n].最大魔法 * 0.03))

					self.战斗流程[#self.战斗流程 + 1] = {
						流程 = 100,
						攻击方 = n,
						气血 = 气血,
						挨打方 = {}
					}
				end
			end

			if self.参战单位[n].法术状态.天煞 ~= nil then
				local 境界 = self.参战单位[n].法术状态.天煞.境界

				if self:取目标状态(n, n, 2) then
					self:增加魔法(n, qz(50 + self.参战单位[n].等级 * (0.6 + 境界 * 0.2)))

					if self.参战单位[n].法术状态.天煞.回合 == 1 and 境界 == 12 then
						self:刷新战意(n, 1)
						self:添加提示(self.参战单位[n].玩家id, n, "#Y/(天煞)你的战意增加了#R1#Y点。")
					end
				end
			end

			if self.参战单位[n].法术状态.含情脉脉 ~= nil and self.参战单位[n].法术状态.含情脉脉.忘忧 ~= nil then
				local 减少 = self:减少魔法(n, 90)
				local aa = {
					魔法类型 = 1,
					挨打方 = n,
					魔法 = 减少
				}

				if self.参战单位[n].魔法 <= 0 then
					local hp = self.参战单位[n].等级 * 4
					local 死亡 = self:减少气血(n, hp, nil, nil, nil, nil, 1)
					aa.气血 = hp
					aa.气血类型 = 1
					aa.死亡 = 死亡
				end

				self:流程处理气血魔法(n, {
					aa
				})
			end

			if self.参战单位[n].法术状态.瘴气 ~= nil and self.参战单位[n].法术状态.瘴气.迷意 ~= nil then
				local 减少 = self:减少魔法(n, 40)
			end

			if self.参战单位[n].法术状态.赤焰 ~= nil then
				local 境界 = self.参战单位[n].法术状态.赤焰.境界

				if self:取目标状态(n, n, 2) then
					self:增加魔法(n, qz(100 + self.参战单位[n].等级 * (0.6 + 境界 * 0.25)))
				end
			end

			if self.参战单位[n] ~= nil and self.参战单位[n].法术状态 ~= nil and self.参战单位[n].法术状态.生命之泉 ~= nil then
				local 编号 = self.参战单位[n].法术状态.生命之泉.攻击编号

				if self:取目标状态(n, n, 2) then
					local 气血 = 0
					气血 = self.参战单位[n].法术状态.生命之泉.等级 * 0.5 + self.参战单位[编号].灵力 * 0.1
					气血 = self:取恢复气血(self.参战单位[n].法术状态.生命之泉.编号, n, 气血, "生命之泉")

					if self:取奇经八脉是否有(编号, "运转") then
						气血 = qz(气血 * 1.3)
					end

					self:恢复伤势(n, qz1(气血 / 2))
					self:增加气血(n, 气血)

					生命之泉回复.攻击方 = n
					生命之泉回复[#生命之泉回复 + 1] = {
						挨打方 = n,
						恢复气血 = 气血,
						恢复伤势 = qz1(气血 / 2)
					}
				end
			end

			if self.参战单位[n] ~= nil and self.参战单位[n].法术状态 ~= nil and self.参战单位[n].法术状态.煞气诀1 ~= nil and self:取目标状态(n, n, 2) then
				local 气血 = 0
				气血 = self.参战单位[n].法术状态.煞气诀1.等级 + 15
				气血 = self:取恢复气血(self.参战单位[n].法术状态.煞气诀1.编号, n, 气血, "煞气诀1")
				self.战斗流程[#self.战斗流程 + 1] = {
					流程 = 100,
					攻击方 = n,
					气血 = 气血,
					挨打方 = {}
				}

				self:增加气血(n, 气血)
			end

			if self.参战单位[n] ~= nil and self.参战单位[n].法术状态 ~= nil and self.参战单位[n].法术状态.普渡众生 ~= nil then
				local 编号 = self.参战单位[n].法术状态.普渡众生.攻击编号

				if self:取目标状态(n, n, 2) then
					local 气血 = 0
					气血 = self.参战单位[n].法术状态.普渡众生.等级 * 2 + self.参战单位[编号].灵力 * 0.1
					气血 = self:取恢复气血(self.参战单位[n].法术状态.普渡众生.编号, n, 气血, "普渡众生")

					self:恢复伤势(n, 气血)
					self:增加气血(n, 气血)

					普渡众生回复.攻击方 = n
					普渡众生回复[#普渡众生回复 + 1] = {
						挨打方 = n,
						恢复气血 = 气血,
						恢复伤势 = 气血
					}
				end
			end

			if (self.参战单位[n].再生 ~= nil or self.参战单位[n].花好月圆 ~= nil) and self:取目标状态(n, n, 2) then
				local 气血 = self.参战单位[n].再生 or 0

				if self.参战单位[n].超级再生 ~= nil and ygsj() <= 10 then
					气血 = self.参战单位[n].超级再生
				end

				if self.参战单位[n].花好月圆 ~= nil and ygsj() <= 25 then
					气血 = 气血 + self.参战单位[n].花好月圆
				end

				if 气血 > 0 then
					self:增加气血(n, 气血)

					再生回复.攻击方 = n
					再生回复[#再生回复 + 1] = {
						挨打方 = n,
						恢复气血 = 气血
					}
				end
			end

			if ygsj() < 33 and n ~= nil and self:取奇经八脉是否有(n, "破浪") then
				self:添加状态("破浪", self.参战单位[n], self.参战单位[n], self.参战单位[n].等级, n)
			end

			if self:取奇经八脉是否有(n, "昂扬") and self.回合数 % 8 == 1 and self.参战单位[n].所有追加法术 ~= nil and #self.参战单位[n].所有追加法术 > 1 then
				self.参战单位[n].追加法术 = {
					self.参战单位[n].所有追加法术[ygsj(#self.参战单位[n].所有追加法术)]
				}
				self.参战单位[n].追加法术[1].数量 = 5
				self.参战单位[n].追加法术[1].等级 = self.参战单位[n].等级 + 10

				if self.参战单位[n].玩家id ~= 0 then
					常规提示(self.参战单位[n].玩家id,
						"#P(昂扬)#W在接下来的#Y8#W回合#R" ..
						self.参战单位[n].名称 .. "#W的套装追加法术固定为#R" .. self.参战单位[n].追加法术[1].名称 .. "#W五件套效果！")
				end
			end

			if self.参战单位[n].生命守护 ~= nil and self:取目标状态(n, n, 2) and ygsj() <= self.参战单位[n].生命守护 then
				local i = self.参战单位[n].主人或助战 or self.参战单位[n].主人

				if self.参战单位[i] ~= nil and self:取目标状态(i, i, 2) then
					local 气血 = self.参战单位[n].等级 * 5

					self:增加气血(i, 气血, true)

					再生回复.攻击方 = i
					再生回复[#再生回复 + 1] = {
						挨打方 = i,
						恢复气血 = 气血
					}

					常规提示(self.参战单位[i].玩家id,
						"#P(生命守护)#R" .. self.参战单位[n].名称 .. "#W为主人#R" .. self.参战单位[i].名称 .. "#W恢复了#R" .. 气血 .. "点气血")
				end
			end

			if self:取奇经八脉是否有(n, "龙息") then
				self.参战单位[n].法暴 = (self.参战单位[n].法暴 or 基础法暴率) + 0.2
			end

			if self.参战单位[n].法术状态.炼气化神 ~= nil and self:取目标状态(n, n, 2) then
				self:增加魔法(n, qz(self.参战单位[n].法术状态.炼气化神.等级 / 2))
			end

			if self.参战单位[n].法术状态.魔息术 ~= nil and self:取目标状态(n, n, 2) then
				self:增加魔法(n, qz(self.参战单位[n].法术状态.魔息术.等级 / 2))
			end

			if self.参战单位[n].冥思 ~= nil and self:取目标状态(n, n, 2) then
				self:增加魔法(n, qz(self.参战单位[n].冥思))
			end

			if self.参战单位[n].法术状态.冥思 ~= nil and self:取目标状态(n, n, 2) then
				self:增加魔法(n, qz(self.参战单位[n].等级 * 0.25))
			end

			if self.参战单位[n].法术状态.尸腐毒 ~= nil then
				local 编号 = self.参战单位[n].法术状态.尸腐毒.攻击编号
				local 气血 = 0
				local 精准战斗流程 = 0

				if self:取目标状态(n, n, 2) then
					气血 = qz(self.参战单位[n].法术状态.尸腐毒.等级 * 4 + self.参战单位[编号].法伤 * 0.1 + (self.参战单位[编号].固定伤害 or 0) * 0.3)

					if self:取符石组合效果(n, "柳暗花明") then
						气血 = qz(气血 * (100 - self:取符石组合效果(n, "柳暗花明")) / 100)
					end

					气血 = math.min(气血, self.参战单位[n].等级 * 15)
					self.战斗流程[#self.战斗流程 + 1] = {
						气血 = 0,
						流程 = 102,
						攻击方 = n,
						挨打方 = {}
					}
					精准战斗流程 = #self.战斗流程 + 0
					self.战斗流程[精准战斗流程].死亡 = self:减少气血(n, 气血, nil, nil, nil, nil, 1)
					self.战斗流程[精准战斗流程].气血 = 气血

					self:造成伤势(n, qz(气血 * 0.3))

					self.战斗流程[精准战斗流程].伤势 = qz(气血 * 0.3)

					if self:法宝判断("九幽", 编号) ~= false then
						local 法宝名称 = "九幽"

						for i = 1, #self.参战单位[编号].法宝列表[法宝名称] do
							local 法宝位置 = self.参战单位[编号].法宝列表[法宝名称][i]
							local 境界 = self:法宝概率判断(法宝名称, 编号, 法宝位置, 1, 1)

							if 境界 ~= false then
								local 目标 = self:取多个友方目标(编号, 编号, 10, "尸腐毒")

								if #目标 == 0 then
									return
								end

								local 目标数 = #目标
								self.战斗流程[精准战斗流程].受益方 = {}

								for i = 1, 目标数 do
									if self.参战单位[目标[i]].九幽回血 == nil then
										if 编号 ~= nil and self:取奇经八脉是否有(编号, "幽光") then
											self.参战单位[目标[i]].九幽回血 = self.参战单位[目标[i]].等级 * 3 + 120
										else
											self.参战单位[目标[i]].九幽回血 = self.参战单位[目标[i]].等级 * 3
										end
									end

									if self.参战单位[目标[i]].九幽回血 > 0 then
										local 气血 = 0
										local 法宝层数 = 境界 + 1
										气血 = qz(self.战斗流程[精准战斗流程].气血 * (0.08 + 法宝层数 * 0.02))
										气血 = self:取恢复气血(编号, 目标[i], 气血, "九幽")
										气血 = math.min(气血, self.参战单位[目标[i]].九幽回血)
										self.战斗流程[精准战斗流程].受益方[i] = {
											受益方 = 目标[i],
											伤害 = 气血
										}

										self:增加气血(目标[i], 气血)

										self.参战单位[目标[i]].九幽回血 = self.参战单位[目标[i]].九幽回血 - 气血
									end
								end
							end
						end
					end
				end
			end

			if self:法宝判断("宝烛", n) ~= false then
				local 法宝名称 = "宝烛"

				for i = 1, #self.参战单位[n].法宝列表[法宝名称] do
					local 法宝位置 = self.参战单位[n].法宝列表[法宝名称][i]
					local 境界 = self:法宝概率判断(法宝名称, n, 法宝位置, 1, 1)

					if 境界 ~= false and self:取目标状态(n, n, 2) and self.参战单位[n].气血 <= self.参战单位[n].最大气血 * 0.7 then
						气血 = self:取恢复气血(n, n, 境界 * 10 + 20, "宝烛")

						self:增加气血(n, 气血)

						宝烛回复.攻击方 = n

						if i == 1 then
							宝烛回复[#宝烛回复 + 1] = {
								挨打方 = n,
								恢复气血 = 气血
							}
						else
							宝烛回复[#宝烛回复].恢复气血 = 宝烛回复[#宝烛回复].恢复气血 + 气血
						end
					end
				end
			end

			if self.参战单位[n].法术状态.紧箍咒 ~= nil then
				local 编号 = self.参战单位[n].法术状态.紧箍咒.攻击编号

				if self:取目标状态(n, n, 2) then
					local 气血 = self.参战单位[n].法术状态.紧箍咒.等级 * 4

					if 编号 ~= nil and self.参战单位[n].法术状态.紧箍咒.默诵 ~= nil then
						气血 = 气血 * 2 + (self.参战单位[编号].固定伤害 or 0) + (self.参战单位[编号].魔力 or 0)

						self:增加愤怒(n, -self.参战单位[n].法术状态.紧箍咒.默诵)
					end

					if self:取玩家战斗() == true then
						气血 = 气血 * 0.5
					end

					气血 = qz(气血)
					self.战斗流程[#self.战斗流程 + 1] = {
						气血 = 0,
						流程 = 102,
						攻击方 = n,
						挨打方 = {}
					}
					local 精准战斗流程 = #self.战斗流程 + 0

					self:造成伤势(n, qz(气血 * 0.3))

					self.战斗流程[精准战斗流程].死亡 = self:减少气血(n, 气血, 编号, "紧箍咒", nil, nil, 1)
					self.战斗流程[精准战斗流程].气血 = 气血
					self.战斗流程[精准战斗流程].伤势 = qz(气血 * 0.3)
				end
			end

			if self.参战单位[n].法术状态.忘忧 ~= nil and self:取目标状态(n, n, 2) then
				local 气血 = qz(self.参战单位[n].等级 * 3)
				self.战斗流程[#self.战斗流程 + 1] = {
					气血 = 0,
					流程 = 102,
					攻击方 = n,
					挨打方 = {}
				}
				local 精准战斗流程 = #self.战斗流程 + 0
				self.战斗流程[精准战斗流程].死亡 = self:减少气血(n, 气血, "忘忧", nil, nil, nil, 1)
				self.战斗流程[精准战斗流程].气血 = 气血
			end

			if self.参战单位[n].法术状态.利刃 ~= nil and self:取目标状态(n, n, 2) then
				local 气血 = 30

				self:减少魔法(n, 30)
			end

			if self.参战单位[n].法术状态.夺魄令 ~= nil then
				local 编号 = self.参战单位[n].法术状态.夺魄令.攻击编号
			end

			if self.参战单位[n].气血 <= 0 and self.参战单位[n].类型 == "角色" and self.参战单位[n].门派 == "方寸山" and (self.参战单位[n].毫毛次数 or 0) < 3 and self:法宝判断("救命毫毛", n) ~= false then
				local 法宝名称 = "救命毫毛"

				for i = 1, #self.参战单位[n].法宝列表[法宝名称] do
					local 法宝位置 = self.参战单位[n].法宝列表[法宝名称][i]
					local 境界 = self:法宝概率判断(法宝名称, n, 法宝位置, 1)

					if 境界 ~= false then
						气血 = qz(self.参战单位[n].最大气血 * 0.2)
						self.战斗流程[#self.战斗流程 + 1] = {
							技能 = "救命毫毛",
							流程 = 111,
							攻击方 = n,
							名称 = self.参战单位[n].名称
						}

						self:恢复伤势(n, 气血)
						self:增加气血(n, 气血)

						self.战斗流程[#self.战斗流程 + 1] = {
							流程 = 110,
							攻击方 = n,
							气血 = 气血,
							挨打方 = {}
						}
						self.参战单位[n].毫毛次数 = self.参战单位[n].毫毛次数 + 1

						if self:取奇经八脉是否有(n, "不灭") then
							self.参战单位[n].法伤 = self.参战单位[n].法伤 + 40

							if self.参战单位[n].不灭 == nil then
								self.参战单位[n].不灭 = 1
								self.参战单位[n].毫毛次数 = self.参战单位[n].毫毛次数 - 3
							end
						end
					end
				end
			end

			if self.参战单位[n].法术状态.摇头摆尾 ~= nil and self:取目标状态(n, n, 2) then
				local 气血 = self.参战单位[n].法术状态.摇头摆尾.等级 * 5
				self.战斗流程[#self.战斗流程 + 1] = {
					气血 = 0,
					流程 = 102,
					攻击方 = n,
					挨打方 = {}
				}
				local 精准战斗流程 = #self.战斗流程 + 0
				self.战斗流程[精准战斗流程].死亡 = self:减少气血(n, 气血, nil, nil, nil, nil, 1)
				self.战斗流程[精准战斗流程].气血 = 气血
				local 死亡状态 = self:减少气血(n, 气血)
			end

			if self.参战单位[n].法术状态.毒 ~= nil or self.参战单位[n].法术状态.猛毒 ~= nil then
				local 状态 = ""
				local 倍率 = 1
				local 猛毒 = false

				if self.参战单位[n].法术状态.猛毒 ~= nil then
					状态 = self.参战单位[n].法术状态.猛毒
					倍率 = 2
					猛毒 = true
				else
					状态 = self.参战单位[n].法术状态.毒
				end

				local 施加方 = 状态.攻击编号

				if self:取目标状态(n, n, 2) then
					local 气血 = qz(self.参战单位[n].气血 * 0.1 * 倍率)
					local 魔法 = qz(self.参战单位[n].魔法 * 0.05 * 倍率)

					if self.参战单位[n].强壮 ~= nil then
						气血 = qz(气血 * 1.3)
						魔法 = qz(魔法 * 1.3)
					end

					if 状态.暗器毒 ~= nil and self:取奇经八脉是否有(施加方, "余韵", "花雨伊人") then
						魔法 = 魔法 + 30
					end

					if 魔法 < 1 then
						魔法 = 0
					end

					if 气血 < 1 then
						气血 = 1
					elseif 气血 > 状态.等级 * 20 * 倍率 then
						气血 = 状态.等级 * 20 * 倍率
					end

					if self:取符石组合效果(n, "柳暗花明") then
						气血 = qz(气血 * (100 - self:取符石组合效果(n, "柳暗花明")) / 100)
						魔法 = qz(魔法 * (100 - self:取符石组合效果(n, "柳暗花明")) / 100)
					end

					local 魔法1 = self:减少魔法(n, 魔法)
					local 死亡状态 = self:减少气血(n, 气血)
					毒扣血.攻击方 = n
					毒扣血[#毒扣血 + 1] = {
						气血类型 = 1,
						魔法类型 = 1,
						挨打方 = n,
						气血 = 气血,
						魔法 = 魔法1,
						死亡 = 死亡状态
					}

					if 猛毒 then
						毒扣血[#毒扣血].增加状态 = "猛毒"
					else
						毒扣血[#毒扣血].增加状态 = "毒"
					end
				end
			end

			if self.参战单位[n].法术状态.机巧 ~= nil and self:取目标状态(n, n, 2) then
				local 气血 = self.参战单位[n].法术状态.机巧.等级
				local 死亡状态 = self:减少气血(n, 气血)
				机巧扣血.攻击方 = n
				机巧扣血[#机巧扣血 + 1] = {
					挨打方 = n,
					气血 = 气血,
					死亡 = 死亡状态
				}
			end

			if self.参战单位[n].法术状态.机巧 ~= nil and self:取目标状态(n, n, 2) then
				local 气血 = self.参战单位[n].法术状态.机巧.等级
				local 死亡状态 = self:减少气血(n, 气血)
				机巧扣血.攻击方 = n
				机巧扣血[#机巧扣血 + 1] = {
					挨打方 = n,
					气血 = 气血,
					死亡 = 死亡状态
				}
			end

			if self.参战单位[n].法术状态.轻霜 ~= nil and self:取目标状态(n, n, 2) then
				local 气血 = self.参战单位[n].法术状态.轻霜.等级
				local 死亡状态 = self:减少气血(n, 气血)
				轻霜扣血.攻击方 = n
				轻霜扣血[#轻霜扣血 + 1] = {
					挨打方 = n,
					气血 = 气血,
					死亡 = 死亡状态
				}
			end

			if self.参战单位[n].法术状态.雾杀 ~= nil then
				local 编号 = self.参战单位[n].法术状态.雾杀.攻击编号

				if self:取目标状态(n, n, 2) then
					local 气血 = qz1((self.参战单位[n].法术状态.雾杀.等级 * 2 + self.参战单位[编号].法伤 * 0.2) * self.参战单位[n].法术状态.雾杀.层数 *
					self.参战单位[n].法术状态.雾杀.伤害比例)

					if self.参战单位[n].法术状态.雾杀.回合 == 1 then
						气血 = 气血 * 2
					end

					local 死亡状态 = self:减少气血(n, 气血)
					雾杀扣血.攻击方 = n
					雾杀扣血[#雾杀扣血 + 1] = {
						挨打方 = n,
						气血 = 气血,
						死亡 = 死亡状态
					}
				end
			end
		end
	end

	if 判断是否为空表(生命之泉回复) ~= true then
		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 1000,
			攻击方 = 生命之泉回复.攻击方,
			挨打方 = {}
		}
		local 精准战斗流程 = #self.战斗流程 + 0

		for n = 1, #生命之泉回复 do
			self.战斗流程[精准战斗流程].挨打方[n] = {
				气血 = 生命之泉回复[n].恢复气血,
				挨打方 = 生命之泉回复[n].挨打方
			}
		end
	end

	if 判断是否为空表(再生回复) ~= true then
		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 1000,
			攻击方 = 再生回复.攻击方,
			挨打方 = {}
		}
		local 精准战斗流程 = #self.战斗流程 + 0

		for n = 1, #再生回复 do
			self.战斗流程[精准战斗流程].挨打方[n] = {
				气血 = 再生回复[n].恢复气血,
				挨打方 = 再生回复[n].挨打方
			}
		end
	end

	if 判断是否为空表(普渡众生回复) ~= true then
		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 1000,
			攻击方 = 普渡众生回复.攻击方,
			挨打方 = {}
		}
		local 精准战斗流程 = #self.战斗流程 + 0

		for n = 1, #普渡众生回复 do
			self.战斗流程[精准战斗流程].挨打方[n] = {
				气血 = 普渡众生回复[n].恢复气血,
				伤势 = 普渡众生回复[n].恢复伤势,
				挨打方 = 普渡众生回复[n].挨打方
			}
		end
	end

	if 判断是否为空表(宝烛回复) ~= true then
		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 1000,
			攻击方 = 宝烛回复.攻击方,
			挨打方 = {}
		}
		local 精准战斗流程 = #self.战斗流程 + 0

		for n = 1, #宝烛回复 do
			self.战斗流程[精准战斗流程].挨打方[n] = {
				气血 = 宝烛回复[n].恢复气血,
				挨打方 = 宝烛回复[n].挨打方
			}
		end
	end

	if 判断是否为空表(毒扣血) ~= true then
		self.战斗流程[#self.战斗流程 + 1] = {
			气血 = 0,
			流程 = 1024,
			攻击方 = 毒扣血.攻击方,
			挨打方 = {}
		}
		local 精准战斗流程 = #self.战斗流程 + 0

		for n = 1, #毒扣血 do
			self.战斗流程[精准战斗流程].挨打方[n] = DeepCopy(毒扣血[n])
		end
	end

	if 判断是否为空表(机巧扣血) ~= true then
		self.战斗流程[#self.战斗流程 + 1] = {
			气血 = 0,
			流程 = 1022,
			攻击方 = 机巧扣血.攻击方,
			挨打方 = {}
		}
		local 精准战斗流程 = #self.战斗流程 + 0

		for n = 1, #机巧扣血 do
			self.战斗流程[精准战斗流程].挨打方[n] = {
				气血 = 机巧扣血[n].气血,
				挨打方 = 机巧扣血[n].挨打方,
				死亡 = 机巧扣血[n].死亡
			}
		end
	end

	if 判断是否为空表(轻霜扣血) ~= true then
		self.战斗流程[#self.战斗流程 + 1] = {
			气血 = 0,
			流程 = 1022,
			攻击方 = 轻霜扣血.攻击方,
			挨打方 = {}
		}
		local 精准战斗流程 = #self.战斗流程 + 0

		for n = 1, #轻霜扣血 do
			self.战斗流程[精准战斗流程].挨打方[n] = {
				气血 = 轻霜扣血[n].气血,
				挨打方 = 轻霜扣血[n].挨打方,
				死亡 = 轻霜扣血[n].死亡
			}
		end
	end

	if 判断是否为空表(雾杀扣血) ~= true then
		self.战斗流程[#self.战斗流程 + 1] = {
			气血 = 0,
			流程 = 1022,
			攻击方 = 雾杀扣血.攻击方,
			挨打方 = {}
		}
		local 精准战斗流程 = #self.战斗流程 + 0

		for n = 1, #雾杀扣血 do
			self.战斗流程[精准战斗流程].挨打方[n] = {
				气血 = 雾杀扣血[n].气血,
				挨打方 = 雾杀扣血[n].挨打方,
				死亡 = 雾杀扣血[n].死亡
			}
		end
	end

	for n = 1, #self.参战单位 do
		if self.战斗类型 == 134481.5 and self.参战单位[n].队伍 == 0 and self.参战单位[n].名称 == "烛九阴" and self.回合数 % 2 == 1 then
			local gs = 0

			for i = 1, #self.参战单位 do
				if self.参战单位[i].队伍 == 0 and self.参战单位[i].名称 == "神伞·惧法" and self:取目标状态(i, i, 2) then
					gs = gs + 1
				end
			end

			if gs < 5 then
				self:执行怪物召唤(n, 10.2, 0, 5 - gs)
			end
		end

		if self.参战单位[n].队伍 == 0 and self.参战单位[n].气血 >= 1 then
			if self.战斗类型 == 100009 then
				if self:取阵营数量1(0) <= 5 and string.find(self.参战单位[n].名称, "星宿") == nil then
					self:执行怪物召唤(n, 1, 0, 5 - self:取阵营数量(0))
				end
			elseif self.战斗类型 == 100008.2 then
				if self.参战单位[n].名称 == "梦靥夜叉" and 任务数据[self.任务id].画魂奖励 == true then
					self.参战单位[n].指令.类型 = "逃跑"
					self.参战单位[n].必定逃跑 = 1
				end
			elseif self.战斗类型 == 100125 then
				if self:取阵营数量(0) <= 5 and self.参战单位[n].名称 ~= "灵感分身小弟" then
					self:执行怪物召唤(n, 5, 0, 5 - self:取阵营数量(0))
				end
			elseif self.战斗类型 == 110014 and self.回合数 == 6 then
				if self:取阵营数量(0) <= 5 then
					self:执行怪物召唤(n, 8, 0, 5 - self:取阵营数量(0))
				end
			elseif self.战斗类型 == 134481.2 and self.参战单位[n].队伍 == 0 and self.参战单位[n].名称 == "翕兹" and self.参战单位[n].气血 > self.参战单位[n].最大气血 * 0.5 then
				if self:取阵营数量1(0) <= 15 then
					self:执行怪物召唤(n, 10, 0, 1)
				end
			elseif self.战斗类型 == 100001 then
				if self.参战单位[n].模型 == "狂豹兽形" and self.参战单位[n].最大气血 * 0.5 <= self.参战单位[n].气血 and ygsj() <= 10 then
					self.参战单位[n].模型 = "狂豹人形"
					self.参战单位[n].名称 = "狂豹人形"
					self.战斗流程[#self.战斗流程 + 1] = {
						参数 = "狂豹人形",
						流程 = 623,
						攻击方 = n
					}
				elseif self.参战单位[n].模型 == "猫灵兽形" and self.参战单位[n].最大气血 * 0.5 <= self.参战单位[n].气血 and ygsj() <= 10 then
					self.参战单位[n].模型 = "猫灵人形"
					self.参战单位[n].名称 = "猫灵人形"
					self.战斗流程[#self.战斗流程 + 1] = {
						参数 = "猫灵人形",
						流程 = 623,
						攻击方 = n
					}
				elseif self.参战单位[n].模型 == "犀牛将军兽形" and self.参战单位[n].最大气血 * 0.5 <= self.参战单位[n].气血 and ygsj() <= 10 then
					self.参战单位[n].模型 = "犀牛将军人形"
					self.参战单位[n].名称 = "犀牛将军人形"
					self.战斗流程[#self.战斗流程 + 1] = {
						参数 = "犀牛将军人形",
						流程 = 623,
						攻击方 = n
					}
				end
			elseif self.战斗类型 == 110014 and self.参战单位[n].名称 == "李彪" and self.回合数 == 5 then
				self.参战单位[n].模型 = "骷髅怪"
				self.参战单位[n].名称 = "李彪"
				self.战斗流程[#self.战斗流程 + 1] = {
					参数 = "骷髅怪",
					流程 = 623,
					攻击方 = n
				}
			end
		end

		if self.回合数 > 1 and self.回合数 % 4 == 0 and self.参战单位[n].法术状态.好梦连连 ~= nil then
			local aa = self.参战单位[n].法术状态.好梦连连.等级 + 0

			self:取消状态("好梦连连", self.参战单位[n])

			aa = aa == 1 and 2 or 1

			self:添加状态("好梦连连", self.参战单位[n], self.参战单位[n], aa, n)
			self:更新单个法术状态(n, "好梦连连")

			if self.参战单位[n].法术状态.好梦连连.睡梦 ~= nil then
				if 判断模型是否是(self.参战单位[n], "癸卯神兔") then
					if string.find(self.参战单位[n].模型, "进阶") then
						self.战斗流程[#self.战斗流程 + 1] = {
							参数 = "进阶癸卯神兔_睡梦",
							流程 = 707.9,
							攻击方 = n
						}
					else
						self.战斗流程[#self.战斗流程 + 1] = {
							参数 = "癸卯神兔_睡梦",
							流程 = 707.9,
							攻击方 = n
						}
					end
				end

				self.战斗发言数据[#self.战斗发言数据 + 1] = {
					id = n,
					内容 = "#Y" .. self.参战单位[n].名称 .. "#进入了#P睡梦#状态#36#36"
				}
			else
				if 判断模型是否是(self.参战单位[n], "癸卯神兔") then
					if string.find(self.参战单位[n].模型, "进阶") then
						self.战斗流程[#self.战斗流程 + 1] = {
							参数 = "进阶癸卯神兔",
							流程 = 707.9,
							攻击方 = n
						}
					else
						self.战斗流程[#self.战斗流程 + 1] = {
							参数 = "癸卯神兔",
							流程 = 707.9,
							攻击方 = n
						}
					end
				end

				self.战斗发言数据[#self.战斗发言数据 + 1] = {
					id = n,
					内容 = "#Y" .. self.参战单位[n].名称 .. "#进入了#P惊梦#状态#41#41"
				}
			end
		end
	end

	self:执行计算1()
end

function 战斗处理类:取阵营数量(队伍)
	local 数量 = 0

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 == 队伍 and self.参战单位[n].气血 >= 1 and self.参战单位[n].捕捉 == nil and self.参战单位[n].逃跑 == nil then
			数量 = 数量 + 1
		end
	end

	return 数量
end

function 战斗处理类:取阵营数量1(队伍)
	local 数量 = 0

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 == 队伍 and (self.参战单位[n].气血 >= 1 or self.参战单位[n].死亡状态 == 2) and self.参战单位[n].捕捉 == nil and self.参战单位[n].逃跑 == nil then
			数量 = 数量 + 1
		end
	end

	return 数量
end

function 战斗处理类:取阵营倒地单位数量(队伍)
	local 数量 = 0

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 == 队伍 and self.参战单位[n].气血 <= 0 and self.参战单位[n].死亡状态 == 2 and self.参战单位[n].捕捉 == nil and self.参战单位[n].逃跑 == nil then
			数量 = 数量 + 1
		end
	end

	return 数量
end

function 战斗处理类:加载召唤单位1(单位组, id, 队伍)
	local 位置记录1 = 0
	local 位置记录2 = 0
	local 位置 = 0
	local 数量 = 0

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 == 队伍 then
			for i = 12, 20 do
				if self.参战单位[n].位置 == i and self.参战单位[n].气血 <= 0 then
					位置记录1 = i

					break
				elseif self.参战单位[n].位置 == i and self.参战单位[n].气血 >= 1 then
					位置记录2 = i
				end
			end
		end
	end

	if 位置记录1 ~= 0 then
		位置 = 位置记录1
	elseif 位置记录2 ~= 0 then
		位置 = 位置记录2
	else
		位置 = 12
	end

	self.参战单位[id] = {
		名称 = 单位组.名称,
		模型 = 单位组.模型,
		等级 = 单位组.等级,
		变异 = 单位组.变异,
		队伍 = 队伍,
		位置 = 位置,
		类型 = "召唤",
		法防 = 单位组.法防,
		法伤 = 单位组.法伤,
		玩家id = 0,
		分类 = "野怪",
		附加阵法 = "普通",
		伤害 = 单位组.伤害,
		命中 = 单位组.伤害,
		防御 = 单位组.防御,
		速度 = 单位组.速度,
		灵力 = 单位组.灵力
	}

	if 单位组.法伤 == nil then
		self.参战单位[id].法伤 = self.参战单位[id].灵力
	else
		self.参战单位[id].法伤 = 单位组.法伤
	end

	self.参战单位[id].灵伤差 = self.参战单位[id].法伤 - self.参战单位[id].灵力

	if 单位组.法防 == nil then
		self.参战单位[id].法防 = self.参战单位[id].灵力
	else
		self.参战单位[id].法防 = 单位组.法防
	end

	self.参战单位[id].躲避 = 单位组.躲避
	self.参战单位[id].气血 = 单位组.气血
	self.参战单位[id].最大气血 = 单位组.气血
	self.参战单位[id].魔法 = 单位组.魔法
	self.参战单位[id].最大魔法 = 单位组.魔法
	self.参战单位[id].躲避 = 单位组.躲避
	self.参战单位[id].技能 = 单位组.技能

	self:加载单位通用属性(id)
	self:加载怪物通常属性(self.参战单位[id], 单位组, id)

	for i = 1, #单位组.主动技能 do
		self.参战单位[id].主动技能[i] = {
			名称 = 单位组.主动技能[i],
			等级 = 单位组.等级 + 10
		}
	end

	self.参战单位[id].战意 = 0
