function 战斗处理类:取阵亡id组(队伍)
	local 队伍表 = {}

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 == 队伍 and self.参战单位[n].法术状态.复活 == nil and (self.参战单位[n].气血 <= 0 or self.参战单位[n].逃跑 ~= nil or self.参战单位[n].捕捉 ~= nil) then
			队伍表[#队伍表 + 1] = n
		end
	end

	return 队伍表
end

function 战斗处理类:召唤数据设置(类型, 等级, 编号)
	if 类型 == 1 then
		return self:取召唤类型1(等级, 编号)
	elseif 类型 == 2 then
		return self:取召唤类型2(等级, 编号)
	elseif 类型 == 3 then
		return self:取召唤类型3(等级, 编号)
	elseif 类型 == 4 then
		return self:取召唤类型4(等级, 编号)
	elseif 类型 == 5 then
		return self:取召唤类型5(等级, 编号)
	elseif 类型 == 6 then
		return self:取召唤类型6(等级, 编号)
	elseif 类型 == 7 then
		return self:取召唤类型7(等级, 编号)
	elseif 类型 == 8 then
		return self:取召唤类型8(等级, 编号)
	elseif 类型 == 9.1 then
		return self:取召唤类型9(等级, 编号, 1)
	elseif 类型 == 9.2 then
		return self:取召唤类型9(等级, 编号, 2)
	elseif 类型 == 9.3 then
		return self:取召唤类型9(等级, 编号, 3)
	elseif 类型 == 10 then
		return self:取召唤类型10(等级, 编号, 1)
	elseif 类型 == 10.1 then
		return self:取召唤类型10(等级, 编号, 2)
	elseif 类型 == 10.2 then
		return self:取召唤类型10(等级, 编号, 3)
	elseif 类型 == 10.3 then
		return self:取召唤类型10(等级, 编号, 4)
	end
end

