function 战斗处理类:取召唤类型1(等级, 编号)
	等级 = qz1((等级 - 5) / 10) * 10

	if 等级 < 1 then
		等级 = 10
	end

	local mc = "星宿"
	local 位置 = {
		[2] = 夜光随机法术,
		[4] = 夜光随机物理法术,
		[7] = 夜光随机恢复法术,
		[6] = 夜光随机封印法术
	}
	local 怪物名称 = {
		[2] = {
			mc .. "法师",
			"天兵",
			{
				"高级法术连击",
				"高级夜战",
				"高级法术暴击",
				"高级法术波动"
			},
			夜光随机法术(3),
			{}
		},
		[3] = {
			mc .. "战士",
			"天兵",
			{
				"高级连击",
				"高级必杀",
				"高级夜战",
				"高级蛮劲",
				"高级法术抵抗",
				"烈焰斩",
				"影袭"
			},
			{},
			{}
		},
		[4] = {
			mc .. "战士",
			"天兵",
			{
				"高级必杀",
				"高级夜战",
				"高级蛮劲",
				"高级招架",
				"高级法术抵抗"
			},
			夜光随机物理法术(3),
			{}
		},
		[5] = {
			mc .. "阴魂",
			"天兵",
			{
				"高级鬼魂术",
				"高级法术抵抗",
				"高级防御",
				"高级招架"
			},
			夜光随机固伤法术(3),
			{
				固伤加成 = 0.5
			}
		},
		[6] = {
			mc .. "巫师",
			"天兵",
			{
				"高级招架",
				"高级法术抵抗",
				"高级再生",
				"敏捷",
				"神佑复生"
			},
			夜光随机封印法术(3),
			{
				速度 = 2
			}
		},
		[7] = {
			mc .. "巫医",
			"天兵",
			{
				"法术连击",
				"夜战",
				"法术暴击",
				"法术波动",
				"神佑复生"
			},
			夜光随机恢复法术(3),
			{
				速度 = 1.5,
				灵力 = 10
			}
		}
	}
	local aa = qsj(2, 7)
	local 召唤单位 = {
		愤怒 = 9999,
		召唤物 = true,
		模型 = "天兵",
		名称 = 怪物名称[aa][1],
		伤害 = 阶段属性[等级].伤害 * 1.5,
		气血 = 阶段属性[等级].气血 * 5 + 20000,
		灵力 = 阶段属性[等级].法伤 * 1.5,
		速度 = 阶段属性[等级].速度 * 3,
		防御 = 阶段属性[等级].防御 * 2,
		法防 = 阶段属性[等级].法防 * 2,
		躲避 = 阶段属性[等级].伤害,
		魔法 = 阶段属性[等级].魔法 * 50,
		等级 = 等级,
		攻击修炼 = math.max(qz1(阶段属性[等级].修炼), 10),
		防御修炼 = math.max(qz1(阶段属性[等级].修炼), 10),
		法术修炼 = math.max(qz1(阶段属性[等级].修炼), 10),
		抗法修炼 = math.max(qz1(阶段属性[等级].修炼), 10),
		技能 = 怪物名称[aa][3],
		主动技能 = 怪物名称[aa][4]
	}

	if not 判断是否为空表(怪物名称[aa][5]) then
		for k, v in pairs(怪物名称[aa][5]) do
			召唤单位[k] = (召唤单位[k] or 1) * v
		end
	end

	return 召唤单位
end

function 战斗处理类:取召唤类型2(等级, 编号)
	等级 = 等级 - 5

