	end

	local 召唤单位 = {
		魔法 = 200,
		召唤物 = true,
		模型 = "进阶幽灵",
		名称 = "怨灵",
		伤害 = 等级 * 5,
		气血 = 等级 * 等级,
		灵力 = 等级 * 5,
		速度 = 等级 * 3,
		防御 = 等级 * 2,
		法防 = 等级 * 0.6,
		躲避 = 等级 * 2,
		等级 = 等级,
		技能 = {},
		主动技能 = {}
	}

	if 编号 ~= nil and self:取奇经八脉是否有(编号, "腐蚀") then
		召唤单位.伤害 = qz(召唤单位.伤害 * 1.1)
