	local id = self.发起id
	等级 = 玩家数据[id].角色.数据.等级

	if 等级 < 1 then
		等级 = 1
	end

	local 召唤单位 = {
		召唤物 = true,
		模型 = "牛幺",
		名称 = "牛幺",
		伤害 = 玩家数据[id].角色.数据.伤害,
		气血 = 玩家数据[id].角色.数据.最大气血,
		灵力 = 玩家数据[id].角色.数据.灵力,
		法伤 = 玩家数据[id].角色.数据.法伤,
		速度 = 玩家数据[id].角色.数据.速度,
		防御 = 玩家数据[id].角色.数据.防御,
		法防 = 玩家数据[id].角色.数据.法防,
		躲避 = 等级 * 4,
		魔法 = 玩家数据[id].角色.数据.最大魔法,
		等级 = 等级,
		技能 = {
			"法术连击",
			"法术暴击"
		},
		主动技能 = {
			"烈火"
		}
	}

	return 召唤单位
end

function 战斗处理类:取召唤类型8(等级, 编号, id)
