function 战斗处理类:取追加法术概率(编号, 技能名称, 套装数量, 召唤兽)
	套装数量 = 套装数量 or 5
	local 级别 = 0
	local 触发概率 = 0

	if 召唤兽 == nil then
		if 角色套装b <= 套装数量 then
			级别 = 2
		elseif 角色套装a <= 套装数量 then
			级别 = 1
		end

		local aa = 角色追加法术概率[技能名称]

		if aa == nil then
			aa = {
				4,
				10
			}
		end

		触发概率 = aa[级别] + 0
	else
		级别 = 1
		触发概率 = 追加法术技能表[技能名称] or 10
	end

	if 级别 > 0 then
		local 额外概率 = 0

		if self.参战单位[编号].法术状态.潜心 ~= nil then
			额外概率 = 额外概率 + 触发概率 * 1
		end

		if self:取奇经八脉是否有(编号, "昂扬") then
			额外概率 = 额外概率 + 触发概率 * 0.5
		end

		if self:取奇经八脉是否有(编号, "笃志") then
			额外概率 = 额外概率 + 8
		end

		if self:取奇经八脉是否有(编号, "破刃") then
			额外概率 = 额外概率 + self.回合数 * 0.8
		end

		if self.参战单位[编号].法术状态.杀气决 ~= nil and self:取奇经八脉是否有(编号, "肃杀") then
			额外概率 = 额外概率 + 触发概率 * 0.32
		end

		if self.参战单位[编号].识物特性 ~= nil and 识物特性生效技能列表[技能名称] ~= nil then
			额外概率 = 额外概率 + self.参战单位[编号].识物特性
		end

		触发概率 = 触发概率 + 额外概率
	end

	return 触发概率
end

function 战斗处理类:触发套装效果(编号, 目标, 特殊)
	if self:取目标状态(目标, 目标, 3) == false then
		return
	elseif self.参战单位[编号].逐胜 ~= nil then
		return
	end

	套装目标 = 目标 + 0

	if self.参战单位[编号].套装追加使用次数 == nil then
		self.参战单位[编号].套装追加使用次数 = {}
	end

	self.参战单位[编号].套装追加 = 1

	if 特殊 == "幸运一击" and self.参战单位[编号].所有追加法术 ~= nil and #self.参战单位[编号].所有追加法术 > 0 then
		for i = 1, #self.参战单位[编号].所有追加法术 do
			self.参战单位[编号].指令.类型 = "法术"
			self.参战单位[编号].指令.参数 = self.参战单位[编号].所有追加法术[i].名称

			if self:取奇经八脉是否有(编号, "效法") then
				self.参战单位[编号].追加增伤 = (self.参战单位[编号].追加增伤 or 1) * 1.04
			end

			if self:取奇经八脉是否有(编号, "追戮") and self.参战单位[编号].所有追加法术[i].数量 >= 3 then
				self.参战单位[编号].追加增伤 = (self.参战单位[编号].追加增伤 or 1) * 1.05
			end

			if self.参战单位[编号].霊能 ~= nil then
				self.参战单位[编号].追加增伤 = (self.参战单位[编号].追加增伤 or 1) * 1.12
				self.参战单位[编号].霊能 = nil
			end

			if self.参战单位[编号].烈光 ~= nil then
				self.参战单位[编号].追加增伤 = (self.参战单位[编号].追加增伤 or 1) * self.参战单位[编号].烈光
			end

			if self.参战单位[编号].套装追加使用次数[self.参战单位[编号].所有追加法术[i].名称] == nil and self:取奇经八脉是否有(编号, "诛伤") then
				self.参战单位[编号].诛伤增伤 = 1
			end

			self.参战单位[编号].套装追加使用次数[self.参战单位[编号].所有追加法术[i].名称] = (self.参战单位[编号].套装追加使用次数[self.参战单位[编号].所有追加法术[i].名称] or 0) +
			1

			self:法术计算(编号, 1)

			if self:取奇经八脉是否有(编号, "攻伐") and self.参战单位[编号].法术状态.攻伐 == nil then
				self:添加状态("攻伐", self.参战单位[编号])
			end

			self.参战单位[编号].催迫增伤 = nil
			self.参战单位[编号].诛伤增伤 = nil
			self.参战单位[编号].追加增伤 = nil

			self:添加战斗流程提示("#P(幸运一击)#R" .. self.参战单位[编号].名称 .. "#Y追加使用了【#R" .. self.参战单位[编号].指令.参数 .. "#Y】")

			if self:取目标状态(套装目标, 套装目标, 3) == false then
				return
			end
		end

		return
	end

	if #self.参战单位[编号].追加法术 > 0 and self:取目标状态(编号, 目标, 1) and self:取攻击状态(编号) and self.参战单位[编号].逐胜 == nil then
		if 追加法术模式 == 1 and 特殊 ~= "摧枯拉朽" then
			for i = 1, #self.参战单位[编号].追加法术 do
				local 触发概率 = self.参战单位[编号].追加法术[i].概率 or
				self:取追加法术概率(编号, self.参战单位[编号].追加法术[i].名称, self.参战单位[编号].追加法术[i].数量, self.参战单位[编号].追加法术[i].召唤兽)

				if ygsj(1000) <= 触发概率 * 10 * 追加法术概率倍率 then
					self.参战单位[编号].指令.类型 = "法术"
					self.参战单位[编号].指令.参数 = self.参战单位[编号].追加法术[i].名称

					if self:取奇经八脉是否有(编号, "效法") then
						self.参战单位[编号].追加增伤 = (self.参战单位[编号].追加增伤 or 1) * 1.04
					end

					if self:取奇经八脉是否有(编号, "追戮") and self.参战单位[编号].追加法术[i].数量 >= 3 then
						self.参战单位[编号].追加增伤 = (self.参战单位[编号].追加增伤 or 1) * 1.05
					end

					if self.参战单位[编号].霊能 ~= nil then
						self.参战单位[编号].追加增伤 = (self.参战单位[编号].追加增伤 or 1) * 1.12
						self.参战单位[编号].霊能 = nil
					end

					if self.参战单位[编号].烈光 ~= nil then
						self.参战单位[编号].追加增伤 = (self.参战单位[编号].追加增伤 or 1) * self.参战单位[编号].烈光
					end

					if self.参战单位[编号].套装追加使用次数[self.参战单位[编号].追加法术[i].名称] == nil and self:取奇经八脉是否有(编号, "诛伤") then
						self.参战单位[编号].诛伤增伤 = 1
					end

					self.参战单位[编号].套装追加使用次数[self.参战单位[编号].追加法术[i].名称] = (self.参战单位[编号].套装追加使用次数[self.参战单位[编号].追加法术[i].名称] or 0) +
					1

					self:法术计算(编号, 1)

					if self:取奇经八脉是否有(编号, "攻伐") and self.参战单位[编号].法术状态.攻伐 == nil then
						self:添加状态("攻伐", self.参战单位[编号])
					end

					self.参战单位[编号].催迫增伤 = nil
					self.参战单位[编号].诛伤增伤 = nil
					self.参战单位[编号].追加增伤 = nil

					self:添加战斗流程提示("#P(套装追加)#R" .. self.参战单位[编号].名称 .. "#Y追加使用了【#R" .. self.参战单位[编号].指令.参数 .. "#Y】")

					if self:取目标状态(套装目标, 套装目标, 3) == false then
						return
					end
				end
			end
		else
			local 追加 = ygsj(#self.参战单位[编号].追加法术)
			local 追加法术 = self.参战单位[编号].追加法术[追加].名称
			local 套装数量 = self.参战单位[编号].追加法术[追加].数量
			local 触发概率 = self.参战单位[编号].追加法术[追加].概率 or self:取追加法术概率(编号, 追加法术, 套装数量, self.参战单位[编号].追加法术[追加].召唤兽)

			if ygsj(1000) <= 触发概率 * 10 * 追加法术概率倍率 or 特殊 == "摧枯拉朽" or self.参战单位[编号].法术状态.潜心 ~= nil and 披坚执锐模式 == 0 then
				self.参战单位[编号].指令.类型 = "法术"
				self.参战单位[编号].指令.参数 = 追加法术

				if self:取奇经八脉是否有(编号, "效法") then
					self.参战单位[编号].追加增伤 = (self.参战单位[编号].追加增伤 or 1) * 1.04
				end

				if self:取奇经八脉是否有(编号, "追戮") and 套装数量 >= 3 then
					self.参战单位[编号].追加增伤 = (self.参战单位[编号].追加增伤 or 1) * 1.05
				end

				if self.参战单位[编号].霊能 ~= nil then
					self.参战单位[编号].追加增伤 = (self.参战单位[编号].追加增伤 or 1) * 1.12
					self.参战单位[编号].霊能 = nil
				end

				if self.参战单位[编号].烈光 ~= nil then
					self.参战单位[编号].追加增伤 = (self.参战单位[编号].追加增伤 or 1) * self.参战单位[编号].烈光
				end

				if self.参战单位[编号].套装追加使用次数[追加法术] == nil and self:取奇经八脉是否有(编号, "诛伤") then
					self.参战单位[编号].诛伤增伤 = 1
				end

				self.参战单位[编号].套装追加使用次数[追加法术] = (self.参战单位[编号].套装追加使用次数[追加法术] or 0) + 1

				self:法术计算(编号, 1)

				if self:取奇经八脉是否有(编号, "攻伐") and self.参战单位[编号].法术状态.攻伐 == nil then
					self:添加状态("攻伐", self.参战单位[编号])
				end

				self.参战单位[编号].催迫增伤 = nil
				self.参战单位[编号].诛伤增伤 = nil
				self.参战单位[编号].追加增伤 = nil

				self:添加战斗流程提示("#P(套装追加)#R" .. self.参战单位[编号].名称 .. "#Y追加使用了【#R" .. self.参战单位[编号].指令.参数 .. "#Y】")

				if self:取目标状态(套装目标, 套装目标, 3) == false then
					return
				end
			end
		end
	end

	self.参战单位[编号].追加增伤 = nil
	self.参战单位[编号].套装追加 = nil
end

function 战斗处理类:是否可逃跑(编号)
	if self.参战单位[编号] ~= nil and (self.参战单位[编号].勇敢 ~= nil or self.参战单位[编号].桀骜自恃 ~= nil or self.参战单位[编号].义薄云天 ~= nil) then
		return false
	end

	return true
end

function 战斗处理类:嗜血追击判定(编号, n)
	if self.参战单位[编号].不追击 ~= true and self.参战单位[编号].可追击 == true and self.参战单位[编号].嗜血追击 ~= nil and self:取行动状态(self.执行对象[n]) then
		local 怒击 = {}

		for i = 1, #self.参战单位 do
			if self.参战单位[编号].可追击 == true and self:取行动状态(self.执行对象[n]) then
				local 目标 = self:取单个敌方目标(编号)

				if 目标 ~= 0 then
					self.参战单位[self.执行对象[n]].指令.目标 = 目标

					self:添加战斗流程提示("#P(嗜血追击)#R" .. self.参战单位[编号].名称 .. "#W将要对#R" .. self.参战单位[目标].名称 .. "#W进行#S追击")

					怒击[#怒击 + 1] = self:普通攻击计算(self.执行对象[n], 1, nil, false, {
						追击 = true
					})
					提示内容x = self.参战单位[编号].名称 .. "触发了" .. "嗜血追击"
					self.战斗流程[#self.战斗流程].提示 = {
						类型 = "法术",
						允许 = true,
						名称 = 提示内容x
					}

					self:触发套装效果(编号, self.参战单位[self.执行对象[n]].指令.目标)
				else
					break
				end
			else
				break
			end
		end

		self.参战单位[编号].不追击 = true

		if #怒击 > 0 then
			for i = 1, #怒击 do
				if 怒击[i] == true then
					return true
				end
			end
		end
	end
end

function 战斗处理类:流程更新气血魔法愤怒(编号, 类型)
	local 组 = {}

	if type(编号) == "table" then
		for i = 1, #编号 do
			if self.参战单位[编号[i]] ~= nil then
				组[#组 + 1] = 编号[i] + 0
			end
		end
	elseif self.参战单位[编号] ~= nil then
		组[#组 + 1] = 编号 + 0
	end

	if #组 > 0 then
		local 结果 = {}

		for i = 1, #组 do
			if 类型 == nil then
				结果[#结果 + 1] = {
					挨打方 = 组[i],
					同步魔法 = self.参战单位[组[i]].魔法,
					同步愤怒 = self.参战单位[组[i]].愤怒 or 0,
					同步气血 = {
						气血 = math.max(self.参战单位[组[i]].气血, 0),
						最大气血 = self.参战单位[组[i]].最大气血,
						气血上限 = self.参战单位[组[i]].气血上限
					}
				}
			elseif 类型 == 1 then
				结果[#结果 + 1] = {
					挨打方 = 组[i],
					同步气血 = {
						气血 = math.max(self.参战单位[组[i]].气血, 0),
						最大气血 = self.参战单位[组[i]].最大气血,
						气血上限 = self.参战单位[组[i]].气血上限
					}
				}
			elseif 类型 == 2 then
				结果[#结果 + 1] = {
					挨打方 = 组[i],
					同步魔法 = self.参战单位[组[i]].魔法
				}
			elseif 类型 == 3 and self.参战单位[组[i]].气血 > 0 then
				结果[#结果 + 1] = {
					挨打方 = 组[i],
					同步愤怒 = self.参战单位[组[i]].愤怒
				}
			elseif 类型 == 4 and self.参战单位[组[i]].气血 > 0 then
				结果[#结果 + 1] = {
					挨打方 = 组[i],
					同步伤势 = self.参战单位[组[i]].气血上限
				}
			elseif 类型 == 5 then
				结果[#结果 + 1] = {
					挨打方 = 组[i],
					同步死亡 = self.参战单位[组[i]].死亡状态
				}
			end
		end

		if #结果 > 0 then
			self:流程处理状态(组[1], 结果)
		end
	end
end

function 战斗处理类:流程封印单位(攻击, 被封, 封印技能, 等级)
	if self.参战单位[被封] == nil then
		return
	end

	self:添加状态(封印技能, self.参战单位[被封], self.参战单位[攻击], 等级 or self.参战单位[攻击].等级, 攻击)
	self:流程处理状态(被封, {
		{
			挨打方 = 被封,
			增加状态 = 封印技能,
			状态 = {
				封印技能
			}
		}
	})
end

function 战斗处理类:流程解封单位(编号)
	local 异常状态名称 = self:取异常封印法术状态()
	local 解封状态 = {}

	for m = 1, #异常状态名称 do
		if self.参战单位[编号].法术状态[异常状态名称[m]] ~= nil then
			self:取消状态(异常状态名称[m], self.参战单位[主人编号])

			解封状态[#解封状态 + 1] = 异常状态名称[i]
		end
	end

	if #解封状态 > 0 then
		self:流程处理状态(编号, {
			{
				挨打方 = 编号,
				取消状态 = 解封状态,
				状态 = 解封状态
			}
		})
	end
end

function 战斗处理类:执行计算1(复活计算)
	for n = 1, #self.执行对象 do
		local 编号 = self.执行对象[n]

		if self.参战单位[编号].法术状态.后发制人 ~= nil then
			self.参战单位[编号].指令.类型 = ""

			self:物攻技能计算(编号, "后发制人", self:取技能等级(编号, "后发制人"))
		end

		if self.参战单位[编号].法术状态.恐怖 ~= nil and self.参战单位[编号].法术状态.恐怖.回合 == 1 then
			self.参战单位[编号].指令.类型 = "防御"
			self.参战单位[编号].指令.目标 = 0
		end

		if self:是否可逃跑(编号) == true and self:取是否召唤兽(编号) and (self.参战单位[编号].气血 <= self.参战单位[编号].最大气血 * 0.4 and ygsj() <= 10 or self.参战单位[编号].忠诚 < 70 and ygsj() <= 10) then
			self.参战单位[编号].指令.类型 = "逃跑"
			self.参战单位[编号].指令.目标 = 0
		end

		for i = 1, #冷却技能减回合 do
			if self.参战单位[编号][冷却技能减回合[i]] ~= nil then
				self.参战单位[编号][冷却技能减回合[i]] = self.参战单位[编号][冷却技能减回合[i]] - 1

				if self.参战单位[编号][冷却技能减回合[i]] < 0 then
					self.参战单位[编号][冷却技能减回合[i]] = nil
				end
			end
		end
	end

	for n = 1, #self.执行对象 do
		if self.全局结束 == nil and self:取行动状态1(self.执行对象[n]) == false and 复活计算 == nil then
			local 编号1 = self.执行对象[n]
			self.是否执行行动[#self.是否执行行动 + 1] = 编号1
		end

		if self.全局结束 == nil and self:取行动状态(self.执行对象[n]) then
			local 编号 = self.执行对象[n]

			if self.参战单位[编号].指令 == nil then
				self.参战单位[编号].指令 = {
					参数 = "",
					敌我 = 0,
					附加 = "",
					类型 = "",
					目标 = 0,
					下达 = false
				}
			end

			if self.参战单位[编号].指令.下达 then
				if self.参战单位[编号].模型 == "牛幺" or self.参战单位[编号].标记 == 100080 then
					if math.random(1, 1) == 1 then
						if self.参战单位[编号].主动技能[1] ~= "" then
							self.参战单位[编号].指令.类型 = "法术"
						else
							self.参战单位[编号].指令.类型 = "攻击"
						end
					else
						self.参战单位[编号].指令.类型 = "攻击"
					end
				end

				if self.参战单位[编号].九黎法术列表 ~= nil and #self.参战单位[编号].九黎法术列表 > 0 then
					if self.参战单位[编号].释放炎魂 == nil and self.参战单位[编号].魔法 >= 20 then
						self.参战单位[编号].释放炎魂 = 1

						self:增益技能计算(编号, "炎魂")
					end

					self.参战单位[编号].指令.参数 = self.参战单位[编号].九黎法术列表[1][1] .. ""
					self.参战单位[编号].指令.目标 = tonumber(self.参战单位[编号].九黎法术列表[1][2])
					self.参战单位[编号].指令.类型 = "法术"

					table.remove(self.参战单位[编号].九黎法术列表, 1)

					if #self.参战单位[编号].九黎法术列表 > 0 and self.参战单位[编号].指令.参数 ~= "三荒尽灭" and self.参战单位[编号].指令.参数 ~= "力辟苍穹" and self.参战单位[编号].指令.参数 ~= "魔神之刃" and self.参战单位[编号].魔法 >= 40 then
						self.参战单位[编号].允许返回 = false

						if self.参战单位[编号].九黎法术列表[1][1] == "力辟苍穹" or self.参战单位[编号].九黎法术列表[1][1] == "魔神之刃" then
							self.参战单位[编号].允许返回 = true
						end
					else
						self.参战单位[编号].允许返回 = true
					end
				end

				if self.参战单位[编号].法术状态.反间之计 ~= nil and ygsj() <= 50 then
					local 临时友方 = self:取单个友方目标(编号)

					if ygsj() <= 50 then
						临时友方 = self:取单个敌方目标(编号)
					end

					if 临时友方 ~= 0 then
						self.参战单位[编号].指令.类型 = "攻击"
						self.参战单位[编号].指令.目标 = 临时友方
					else
						self.参战单位[编号].指令.类型 = "防御"
						self.参战单位[编号].指令.目标 = 0
					end
				end

				if self.参战单位[编号].法术状态.发瘟匣 ~= nil and self.参战单位[编号].指令.类型 ~= "防御" then
					self.参战单位[编号].指令.类型 = "攻击"
					self.参战单位[编号].指令.目标 = self:取单个友方目标(编号)
				end

				if self.参战单位[编号].法术状态.疯狂 ~= nil and ygsj() <= 50 then
					self.参战单位[编号].指令.类型 = "攻击"

					if ygsj() <= 50 then
						self.参战单位[编号].指令.目标 = self:取单个敌方目标(编号)
					else
						self.参战单位[编号].指令.目标 = self:取单个友方目标(编号)
					end
				end

				if self.参战单位[编号].法术状态.落魄符 ~= nil and ygsj() <= 50 then
					self.参战单位[编号].指令.类型 = "攻击"

					if ygsj() <= 50 then
						self.参战单位[编号].指令.目标 = self:取单个敌方目标(编号)
					else
						self.参战单位[编号].指令.目标 = self:取单个友方目标(编号)
					end
				end

				if self.参战单位[编号].法术状态.错乱 ~= nil and ygsj() <= 50 then
					self.参战单位[编号].指令.类型 = "攻击"

					if ygsj() <= 50 then
						self.参战单位[编号].指令.目标 = self:取单个敌方目标(编号)
					else
						self.参战单位[编号].指令.目标 = self:取单个友方目标(编号)
					end
				end

				if self.参战单位[编号].法术状态.锋芒毕露 ~= nil then
					self.参战单位[编号].指令.目标 = self.参战单位[编号].法术状态.目标id
				end

				if self.参战单位[编号].法术状态.诱袭 ~= nil then
					self.参战单位[编号].指令.类型 = "攻击"
					self.参战单位[编号].指令.目标 = self.参战单位[编号].法术状态.目标id
				end

				if self.参战单位[编号].法术状态.无魂傀儡 ~= nil and 取随机数(1, 10000) <= 3000 or self.参战单位[编号].法术状态.断线木偶 ~= nil and 取随机数(1, 10000) <= 3000 then
					self.参战单位[编号].指令.类型 = "攻击"
					self.参战单位[编号].指令.目标 = self.参战单位[编号].法术状态.攻击编号
					self.参战单位[编号].傀儡 = 1
				end

				if self:是否可逃跑(编号) == true and self.参战单位[编号].法术状态.鬼泣 ~= nil and self.参战单位[编号].类型 ~= "角色" and 取随机数(1, 10000) <= self.参战单位[编号].法术状态.鬼泣.概率逃跑 * 100 then
					self.参战单位[编号].指令.类型 = "逃跑"
					self.参战单位[编号].必定逃跑 = 1
				elseif self:是否可逃跑(编号) == true and self.参战单位[编号].法术状态.惊魂铃 ~= nil and self.参战单位[编号].类型 ~= "角色" and 取随机数(1, 10000) <= self.参战单位[编号].法术状态.惊魂铃.概率逃跑 * 100 then
					self.参战单位[编号].指令.类型 = "逃跑"
					self.参战单位[编号].必定逃跑 = 1
				end

				if self.参战单位[编号].法术状态.恐怖 ~= nil and self.参战单位[编号].法术状态.恐怖.回合 == 1 then
					self.参战单位[编号].指令.类型 = "防御"
					self.参战单位[编号].指令.目标 = 0
				end

				if self.参战单位[编号].指令.类型 == "攻击" and self.参战单位[self.执行对象[n]].指令.附加 == "友伤" then
					local 目标1 = self.参战单位[self.执行对象[n]].指令.目标

					if self:取攻击状态(self.执行对象[n]) then
						self:普通攻击计算(self.执行对象[n], 1, true)
					end
				end

				if self.参战单位[编号].愈勇 ~= nil and 装备特技[self.参战单位[编号].指令.参数] ~= nil then
					self.参战单位[编号].愈勇 = 0
				end

				if self.参战单位[编号].指令.类型 == "法术" and 神通技能列表[self.参战单位[编号].指令.参数] ~= nil then
					self.参战单位[编号].实时神通 = self.参战单位[编号].指令.参数 .. ""
				else
					self.参战单位[编号].实时神通 = nil
					self.参战单位[编号].连续神通 = 0
				end

				if self.参战单位[编号].指令.类型 == "攻击" then
					if self.参战单位[编号].顽心 ~= nil then
						self.参战单位[编号].顽心 = 1
					end

					local 怒击 = false
					local 目标1 = self.参战单位[self.执行对象[n]].指令.目标

					if self:取攻击状态(self.执行对象[n]) then
						if self.参战单位[self.参战单位[self.执行对象[n]].指令.目标] ~= nil and self.参战单位[self.执行对象[n]].法术状态.反间之计 == nil and self.参战单位[self.参战单位[self.执行对象[n]].指令.目标].队伍 == self.参战单位[编号].队伍 then
							self.参战单位[self.执行对象[n]].指令.目标 = self:取单个敌方目标(编号)
							目标1 = self.参战单位[self.执行对象[n]].指令.目标 + 0
						end

						if self:取目标状态(self.执行对象[n], 目标1, 1) == false then
							self.参战单位[self.执行对象[n]].指令.目标 = self:取单个敌方目标(编号)
							目标1 = self.参战单位[self.执行对象[n]].指令.目标 + 0
						end

						if self.参战单位[self.执行对象[n]].狂莽一击 ~= nil then
							self.参战单位[self.执行对象[n]].狂莽一击 = 目标1 + 0
						end

						local 怒击判定 = {}
						local 不返回 = false
						local 触发理直气壮 = false
						local 触发连击 = false

						if self.参战单位[编号].理直气壮 ~= nil and ygsj() <= 40 then
							触发理直气壮 = true
							不返回 = true
							self.连击判定 = true
						elseif self.参战单位[self.参战单位[self.执行对象[n]].指令.目标] ~= nil and self.参战单位[self.参战单位[self.执行对象[n]].指令.目标].反震 == nil and self.参战单位[编号].连击 ~= nil and self.参战单位[编号].连击 ~= 0 and ygsj() <= self.参战单位[编号].连击 + (self.参战单位[编号].大快朵颐连击 or 0) then
							触发连击 = true
							不返回 = true
							self.连击判定 = true
						end

						if self.参战单位[self.执行对象[n]].狂莽一击 ~= nil and ygsj() <= 50 then
							self.参战单位[self.执行对象[n]].指令.目标 = self:取单个敌方目标(编号, nil, self.参战单位[self.执行对象[n]].狂莽一击)
						end

						怒击判定[#怒击判定 + 1] = self:普通攻击计算(self.执行对象[n], 1, nil, 不返回)

						self:触发套装效果(编号, self.参战单位[self.执行对象[n]].指令.目标)

						if 触发理直气壮 then
							local f = 2

							for i = 1, f do
								if self:取攻击状态(self.执行对象[n]) and self:取目标状态(self.执行对象[n], self.参战单位[self.执行对象[n]].指令.目标, 1) == true then
									怒击判定[#怒击判定 + 1] = true

									if i == f then
										不返回 = false
										self.连击判定 = false
									end

									if self.参战单位[self.执行对象[n]].狂莽一击 ~= nil then
										if ygsj() <= 50 then
											self.参战单位[self.执行对象[n]].指令.目标 = self:取单个敌方目标(编号, nil,
												self.参战单位[self.执行对象[n]].狂莽一击)
										else
											self.参战单位[self.执行对象[n]].指令.目标 = self.参战单位[self.执行对象[n]].狂莽一击 + 0
										end
									end

									self:普通攻击计算(self.执行对象[n], 1, nil, 不返回, {
										连击 = 1
									})

									if i == 1 then
										self:添加战斗流程提示("#P(理直气壮)#R" .. self.参战单位[编号].名称 .. "#Y触发了#R理直气壮")
									end

									self:触发套装效果(编号, self.参战单位[self.执行对象[n]].指令.目标)
								else
									self.连击判定 = false

									break
								end
							end

							self.连击判定 = false
						elseif 触发连击 then
							local f = 1

							if self.参战单位[编号].超级连击 ~= nil and ygsj() <= 30 then
								f = f + 1
							end

							for i = 1, f do
								怒击判定[#怒击判定 + 1] = true

								if self:取攻击状态(self.执行对象[n]) and self:取目标状态(self.执行对象[n], self.参战单位[self.执行对象[n]].指令.目标, 1) == true then
									if i == f then
										不返回 = false
										self.连击判定 = false
									end

									local 倍率 = 1

									if self.参战单位[编号].气贯长虹 ~= nil then
										倍率 = 1.25

										if self.参战单位[编号].高级连击 ~= nil or self.参战单位[编号].超级连击 ~= nil then
											倍率 = 1.5

											if self.参战单位[编号].超级连击 ~= nil and i == 2 then
												倍率 = 1.75
											end
										end
									end

									if self.参战单位[self.执行对象[n]].狂莽一击 ~= nil then
										if ygsj() <= 50 then
											self.参战单位[self.执行对象[n]].指令.目标 = self:取单个敌方目标(编号, nil,
												self.参战单位[self.执行对象[n]].狂莽一击)
										else
											self.参战单位[self.执行对象[n]].指令.目标 = self.参战单位[self.执行对象[n]].狂莽一击 + 0
										end
									end

									self:普通攻击计算(self.执行对象[n], 倍率, nil, 不返回, {
										连击 = 1
									})

									if i == 1 then
										self:添加战斗流程提示("#P(连击)#R" .. self.参战单位[编号].名称 .. "#Y触发了#R连击")
									end

									if i == 2 then
										self:添加战斗流程提示("#P(超级连击)#R" .. self.参战单位[编号].名称 .. "#Y触发了#R超级连击")
									end

									self:触发套装效果(编号, self.参战单位[self.执行对象[n]].指令.目标)
								else
									self.连击判定 = false

									break
								end
							end

							self.连击判定 = false
						end

						if self.参战单位[编号].乘胜追击 ~= nil and self.参战单位[编号].乘胜追击 >= 4 and self.参战单位[编号].乘胜追击 >= 4 then
							不返回 = true

							for i = 1, 2 do
								if self:取攻击状态(self.执行对象[n]) and self:取目标状态(self.执行对象[n], self.参战单位[self.执行对象[n]].指令.目标, 1) == true then
									if i == 2 then
										不返回 = false
									end

									if self.参战单位[self.执行对象[n]].狂莽一击 ~= nil then
										if ygsj() <= 50 then
											self.参战单位[self.执行对象[n]].指令.目标 = self:取单个敌方目标(编号, nil,
												self.参战单位[self.执行对象[n]].狂莽一击)
										else
											self.参战单位[self.执行对象[n]].指令.目标 = self.参战单位[self.执行对象[n]].狂莽一击 + 0
										end
									end

									self:普通攻击计算(编号, 0.4, nil, 不返回, {
										乘胜追击 = 1
									})

									if i == 1 then
										self.参战单位[编号].乘胜追击 = self.参战单位[编号].乘胜追击 - 4

										self:添加战斗流程提示("#P(乘胜追击)#R" .. self.参战单位[编号].名称 .. "#W触发了#R乘胜追击")
									end

									self:触发套装效果(编号, self.参战单位[self.执行对象[n]].指令.目标)
								end
							end
						end

						怒击判定[#怒击判定 + 1] = self:嗜血追击判定(编号, n)

						if 编号 ~= nil and self.参战单位[编号].如意神通 ~= nil then
							local 排除 = {
								self.参战单位[self.执行对象[n]].指令.目标 + 0
							}

							for i = 1, self.参战单位[编号].如意神通 do
								目标 = self:取单个敌方目标(编号, nil, 排除)

								if 目标 ~= 0 then
									排除[#排除 + 1] = 目标 + 0
									self.参战单位[self.执行对象[n]].指令.目标 = 目标

									if self:取目标状态(self.执行对象[n], 目标, 1) and self:取行动状态(self.执行对象[n]) then
										怒击判定[#怒击判定 + 1] = self:普通攻击计算(self.执行对象[n], 1)

										self:触发套装效果(编号, self.参战单位[self.执行对象[n]].指令.目标)

										怒击判定[#怒击判定 + 1] = self:嗜血追击判定(编号, n)
									end
								end
							end

							self.参战单位[self.执行对象[n]].指令.目标 = 目标1
						end

						if self:法宝判断("嗜血幡", 编号) ~= false and self.参战单位[编号].逐胜 == nil then
							local 法宝名称 = "嗜血幡"

							for i = 1, #self.参战单位[编号].法宝列表[法宝名称] do
								local 法宝位置 = self.参战单位[编号].法宝列表[法宝名称][i]
								local 境界 = self:法宝概率判断(法宝名称, 编号, 法宝位置, 1, 1)

								if 境界 ~= false then
									目标 = self:取单个敌方目标(编号, self.参战单位[self.执行对象[n]].指令.目标)

									if 目标 ~= 0 then
										self.战斗流程[#self.战斗流程].返回 = false
										self.参战单位[self.执行对象[n]].指令.目标 = 目标

										self:扣除法宝灵气(编号, 法宝位置, 1)

										怒击判定[#怒击判定 + 1] = self:普通攻击计算(self.执行对象[n], 1)

										self:触发套装效果(编号, self.参战单位[self.执行对象[n]].指令.目标)
										self:添加战斗流程提示("#P(嗜血幡)#R" ..
										self.参战单位[编号].名称 .. "#W对#R" .. self.参战单位[目标].名称 .. "#W进行了额外攻击")
									end
								end
							end
						end

						for i = 1, #怒击判定 do
							if 怒击判定[i] == true then
								怒击 = true

								break
							end
						end

						if self.参战单位[编号].怒击效果 and 怒击 and self:取攻击状态(self.执行对象[n]) then
							目标 = self:取单个敌方目标(编号)

							if 目标 ~= 0 then
								self.参战单位[self.执行对象[n]].指令.目标 = 目标

								self:添加战斗流程提示("#P(苍鸾怒击)#R" ..
								self.参战单位[编号].名称 .. "#W触发了#R苍鸾怒击#W、将要对#R" .. self.参战单位[目标].名称 .. "#W进行#S额外攻击")
								self:普通攻击计算(self.执行对象[n], 1, nil, false, {
									怒击 = 1
								})
								self:触发套装效果(编号, self.参战单位[self.执行对象[n]].指令.目标)
								self:嗜血追击判定(编号, n)
							end
						end

						if 编号 ~= nil and self:取奇经八脉是否有(编号, "风刃妖风") then
							目标 = self.参战单位[self.执行对象[n]].指令.目标

							self:物理溅射攻击(编号, 目标, {
								类型 = 2,
								伤害 = 1000
							}, 10)
						end
					end

					self:助攻判断(编号, 目标1)
					self:法术助攻判断(编号, 目标1)
				elseif self.参战单位[编号].指令.类型 == "法术" then
					local 允许执行 = true

					if self.参战单位[编号].顾盼生姿 ~= nil and self.参战单位[编号].主人或助战 ~= nil then
						self.参战单位[编号].顾盼生姿计算 = 1
					end

					if self.参战单位[编号].模型 == "牛幺" or self.参战单位[编号].标记 == 100080 or 装备特技[self.参战单位[编号].指令.参数] == nil and self:取法术状态(self.执行对象[n], self.参战单位[编号].指令.参数) or 装备特技[self.参战单位[编号].指令.参数] ~= nil and self:取特技状态(self.执行对象[n]) then
						local 名称 = self.参战单位[编号].指令.参数

						if 名称 == "狮搏" or 名称 == "鹰击" or 名称 == "连环击" or 名称 == "象形" or 名称 == "最佳搭档" and self.参战单位[编号].无需变身 == nil then
							if self.参战单位[编号].法术状态.变身 == nil then
								self.参战单位[编号].指令.参数 = "变身"

								self:法术计算(self.执行对象[n])
								self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/没有变身效果，本回合自动变身")

								允许执行 = false
							end
						else
							local 名称 = self.参战单位[编号].指令.参数

							if (名称 == "狮搏" or 名称 == "鹰击" or 名称 == "连环击" or 名称 == "象形") and self.参战单位[编号].法术状态.变身 == true then
								self.参战单位[编号].指令.参数 = self.参战单位[编号].主动技能[i].名称

								self:法术计算(self.执行对象[n])
							end
						end

						if self.参战单位[编号].指令.参数 == "兵解符" then
							self:逃跑计算(编号, 0)
						end

						if self.参战单位[编号].模型 == "牛幺" or self.参战单位[编号].标记 == 100080 then
							if self.参战单位[编号].主动技能[1] ~= nil then
								self.参战单位[编号].指令.参数 = self.参战单位[编号].主动技能[math.random(1, #self.参战单位[编号].主动技能)]
							end

							local 名称 = self.参战单位[编号].指令.参数

							if 名称 == "狮搏" or 名称 == "鹰击" or 名称 == "连环击" or 名称 == "象形" then
								if self.参战单位[编号].法术状态.鹰击 ~= nil then
									允许执行 = false
								elseif self.参战单位[编号].法术状态.变身 == nil then
									self.参战单位[编号].指令.参数 = "变身"
								end
							end
						end

						if 允许执行 then
							if 名称 == "观照万象" then
								if self.参战单位[编号].观照万象 ~= nil and self.参战单位[编号][名称] > 0 then
									常规提示(self.参战单位[编号].玩家id, "#Y/该技能当前处于冷却中还需：" .. self.参战单位[编号].观照万象 .. "回合后才可使用")

									允许执行 = false
								elseif #self.参战单位[编号].主动技能 <= 0 then
									常规提示(self.参战单位[编号].玩家id, "#Y/该召唤兽没有可以释放的主动技能")

									允许执行 = false
								elseif self:取玩家战斗() then
									常规提示(self.参战单位[编号].玩家id, "#Y/该技能无法在玩家战斗之间使用")

									允许执行 = false
								else
									self.参战单位[编号].观照万象 = 技能冷却列表[名称]
								end
							elseif 技能冷却列表[名称] ~= nil then
								if self.参战单位[编号][名称] ~= nil and self.参战单位[编号][名称] > 0 then
									if self.参战单位[编号].玩家id ~= 0 then
										常规提示(self.参战单位[编号].玩家id, "#Y/该技能当前处于冷却中还需：" .. self.参战单位[编号][名称] .. "回合后才可使用")

										允许执行 = false
									end
								elseif 技能冷却列表[名称] > 0 then
									self.参战单位[编号][名称] = 技能冷却列表[名称]

									if 名称 == "秘传飞砂走石" or 名称 == "秘传三昧真火" then
										if self:取奇经八脉是否有(编号, "固基") then
											self.参战单位[编号][名称] = self.参战单位[编号][名称] - 2
										end

										if self:取奇经八脉是否有(编号, "蔽日") and self.回合数 >= 10 then
											self.参战单位[编号][名称] = self.参战单位[编号][名称] - qz(self.回合数 / 10)
										end
									end
								end
							elseif 神通技能列表[名称] ~= nil and self.参战单位[编号].神通技能 ~= nil and self.参战单位[编号].神通技能[名称] == nil then
								常规提示(self.参战单位[编号].玩家id, "#P[" .. 名称 .. "]#Y当前回合无法使用")

								允许执行 = false
							end

							if 允许执行 then
								self.月光减伤 = {}

								if 名称 == "观照万象" then
									for i = 1, #self.参战单位[编号].主动技能 do
										if self.参战单位[编号].主动技能[i].名称 ~= "观照万象" and (技能冷却列表[self.参战单位[编号].主动技能[i].名称] == nil or self.参战单位[编号][self.参战单位[编号].主动技能[i].名称] == nil or self.参战单位[编号][self.参战单位[编号].主动技能[i].名称] <= 0) then
											if 技能冷却列表[self.参战单位[编号].主动技能[i].名称] ~= nil then
												self.参战单位[编号][self.参战单位[编号].主动技能[i].名称] = 技能冷却列表
												[self.参战单位[编号].主动技能[i].名称]
											end

											if 法术只给自己列表[self.参战单位[编号].主动技能[i].名称] ~= nil then
												self.参战单位[编号].指令.目标 = 编号
											end

											self.参战单位[编号].指令.参数 = self.参战单位[编号].主动技能[i].名称

											self:法术计算(self.执行对象[n])

											if self.参战单位[编号].指令.参数 == "月光" then
												for i = 1, math.min(qz(self.参战单位[编号].等级 / 30), 3) do
													self.参战单位[编号].指令.目标 = self:取单个敌方目标(编号)

													if self.参战单位[编号].指令.目标 ~= 0 then
														self:法攻技能计算(编号, self.参战单位[编号].指令.参数,
															self:取技能等级(编号, self.参战单位[编号].指令.参数), 1, 1)
													end
												end
											end
										end
									end
								else
									self:法术计算(self.执行对象[n])

									if self.参战单位[编号].指令.参数 == "月光" then
										for i = 1, math.min(qz(self.参战单位[编号].等级 / 30), 3) do
											self.参战单位[编号].指令.目标 = self:取单个敌方目标(编号)

											if self.参战单位[编号].指令.目标 ~= 0 then
												self:法攻技能计算(编号, self.参战单位[编号].指令.参数, self:取技能等级(编号, self.参战单位[编号].指令.参数),
													1, 1)
											end
										end
									end
								end

								self.月光减伤 = {}

								if self:物攻技能(名称) then
									local 次数 = 0
									local 提示次数 = {}

									if self:法宝判断("嗜血幡", 编号) ~= false then
										local 法宝名称 = "嗜血幡"

										for i = 1, #self.参战单位[编号].法宝列表[法宝名称] do
											local 法宝位置 = self.参战单位[编号].法宝列表[法宝名称][i]
											local 境界 = self:法宝概率判断(法宝名称, 编号, 法宝位置, 1, 1)

											if 境界 ~= false then
												次数 = 次数 + 1
												提示次数[#提示次数 + 1] = 次数

												self:扣除法宝灵气(编号, 法宝位置, 1)
											end
										end
									end

									if 次数 >= 1 then
										for i = 1, 次数 do
											目标 = self:取单个敌方目标(编号, self.参战单位[self.执行对象[n]].指令.目标)

											if 目标 ~= 0 then
												self.参战单位[self.执行对象[n]].指令.目标 = 目标
												self.战斗流程[#self.战斗流程].返回 = false
												怒击 = self:普通攻击计算(self.执行对象[n], 1)

												if i == 提示次数[1] then
													self:添加战斗流程提示("#P(嗜血幡)#R" ..
													self.参战单位[编号].名称 .. "#W对#R" .. self.参战单位[目标].名称 .. "#W进行了额外攻击")
													table.remove(提示次数, 1)
												end

												if 怒击 and self.参战单位[编号].怒击效果 then
													目标 = self:取单个敌方目标(编号, self.参战单位[self.执行对象[n]].指令.目标)

													if self:取目标状态(self.执行对象[n], 目标, 1) and self:取行动状态(self.执行对象[n]) then
														self.参战单位[self.执行对象[n]].指令.目标 = 目标
														self.战斗流程[#self.战斗流程].返回 = false

														self:普通攻击计算(self.执行对象[n], 1)
													end
												end
											end
										end
									end
								end
							end
						end
					end

					if self.参战单位[编号].允许助攻 ~= nil and self:物攻技能(self.参战单位[编号].指令.参数) or self:法攻技能(self.参战单位[编号].指令.参数) then
						self:助攻判断(编号, self.参战单位[编号].指令.目标)
						self:法术助攻判断(编号, self.参战单位[编号].指令.目标)
					end

					self.参战单位[编号].允许助攻 = nil
					self.参战单位[编号].顾盼生姿计算 = nil
				elseif self.参战单位[编号].指令.类型 == "道具" and self.参战单位[编号].法术状态.煞气诀 == nil and self.参战单位[编号].陌宝 == nil then
					self:道具计算(self.执行对象[n], 1)

					if self.使用道具助攻 ~= nil then
						self:助攻判断(编号, self.参战单位[编号].指令.目标)
						self:法术助攻判断(编号, self.参战单位[编号].指令.目标)

						self.使用道具助攻 = nil
					end
				elseif self.参战单位[编号].指令.类型 == "同门飞镖" then
					local 目标 = self.参战单位[编号].指令.目标

					if self:取目标状态(编号, 目标, 1) then
						self:飞镖计算(编号, {
							{
								伤害 = 500,
								id = 目标
							}
						})
					end

					self:助攻判断(编号, self.参战单位[编号].指令.目标)
					self:法术助攻判断(编号, self.参战单位[编号].指令.目标)
				elseif self.参战单位[编号].指令.类型 == "特技" then
					if self:取特技状态(self.执行对象[n]) then
						self:法术计算(self.执行对象[n], 1)
					end

					if self:物攻技能(self.参战单位[编号].指令.参数) or self:法攻技能(self.参战单位[编号].指令.参数) then
						self:助攻判断(编号, self.参战单位[编号].指令.目标)
						self:法术助攻判断(编号, self.参战单位[编号].指令.目标)
					end
				elseif self.参战单位[编号].指令.类型 == "捕捉" and self.参战单位[编号].类型 == "角色" then
					self:捕捉计算(self.执行对象[n])
				elseif self.参战单位[编号].指令.类型 == "召唤" and self.参战单位[编号].类型 == "角色" then
					self:召唤计算(self.执行对象[n])
				elseif self.参战单位[编号].指令.类型 == "逃跑" then
					if self.参战单位[编号].类型 == "角色" and self.参战单位[编号].助战明细 ~= nil and #self.参战单位[编号].助战明细 > 0 then
						for i = 1, #self.参战单位[编号].助战明细 do
							self.参战单位[self.参战单位[编号].助战明细[i]].指令.类型 = "逃跑"
						end
					end

					self:逃跑计算(self.执行对象[n], 50)
				elseif self.参战单位[编号].指令.类型 == "防御" and self.参战单位[编号].愈勇 ~= nil then
					self.参战单位[编号].愈勇 = 0
				end
			end
		end

		local aa = {}

		for i = 1, #self.参战单位 do
			if self.参战单位[i].九黎浮空 ~= nil and (n == #self.执行对象 or self.参战单位[i].九黎浮空 ~= self.执行对象[n + 1]) then
				aa[#aa + 1] = {
					取消浮空 = 1,
					挨打方 = i
				}
				self.参战单位[i].九黎浮空 = nil
			end
		end

		if #aa > 0 then
			self:流程处理状态(1, aa)
		end
	end

	for n = 1, #self.执行对象 do
		local 编号 = self.执行对象[n]

		if self.参战单位[编号].复仇标记 ~= nil and self:取目标状态(self.执行对象[n], self.参战单位[编号].复仇标记, 1) and self.参战单位[编号].气血 >= 10 then
			self.参战单位[self.执行对象[n]].指令.目标 = self.参战单位[编号].复仇标记

			self:普通攻击计算(self.执行对象[n], 1)
		end
	end

	for n = 1, #self.参战单位 do
		if self.战斗类型 == 134481.2 then
			if self.参战单位[n].名称 == "翕兹" and self.参战单位[n].死亡状态 == 2 and self:取阵营数量(0) > 0 then
				self.参战单位[n].死亡状态 = nil
				self.参战单位[n].气血 = qz(self.参战单位[n].最大气血 * 0.5)
				self.参战单位[n].气血上限 = self.参战单位[n].最大气血 + 0

				if self.参战单位[n].类型 == "bb" then
					self.参战单位[n].气血上限 = nil
				end

				self:流程处理状态(n, {
					{
						挨打方 = n,
						复活 = {
							气血 = self.参战单位[n].气血 + 0
						}
					}
				})
			end
		elseif self.战斗类型 == 134481.4 then
			if self.参战单位[n].名称 == "强良" and self:取目标状态(n, n, 2) then
				local 封印单位 = {}

				for i = 1, #self.参战单位 do
					if self.参战单位[i].队伍 == 0 and self:取封印状态(i) then
						封印单位[#封印单位 + 1] = i
					end
				end

				if #封印单位 > 0 then
					local 解封单位 = 封印单位[ygsj(#封印单位)]

					self:流程解封单位(解封单位)
					self:添加战斗流程提示("#P强良#W解除了#R" .. self.参战单位[解封单位].名称 .. "#W#的#S封印状态")
				else
					local 封印单位 = self:取单个敌方可封印目标(n)

					self:流程封印单位(n, 封印单位, "日月乾坤")

					if self.参战单位[封印单位] ~= nil then
						self:添加战斗流程提示("#Y" .. self.参战单位[封印单位].名称 .. "#W被#P强良#封印了")
					end
				end
			end
		elseif self.战斗类型 == 134481.6 and self.参战单位[n].队伍 == 0 and self.参战单位[n].名称 == "后土" and self.回合数 >= 2 and self:取目标状态(n, n, 2) then
			if self.回合数 % 2 == 0 then
				self:执行怪物召唤(n, 10.3, 0, 2)
			end
		elseif self.战斗类型 == 134481.7 and self.参战单位[n].队伍 == 0 then
			if self.参战单位[n].名称 == "帝江" and self.回合数 >= 1 then
				if self:取目标状态(n, n, 2) then
					self.参战单位[n].指令 = {
						参数 = "镜之阳",
						目标 = self:取单个友方目标(n)
					}
					self.不施法 = true

					if self.回合数 % 2 == 1 then
						self.参战单位[n].指令.参数 = "镜之阴"
					end

					self:法术计算(n, 1)
				end

				local 封印 = false

				for i = 1, #self.参战单位 do
					if self.参战单位[i].队伍 == 0 and self.参战单位[i].法术状态.镜之阴 ~= nil then
						封印 = true

						break
					end
				end

				if 封印 == true then
					local 封印单位 = self:取单个敌方可封印目标(n)

					self:流程封印单位(n, 封印单位, "日月乾坤")

					if self.参战单位[封印单位] ~= nil then
						self:添加战斗流程提示("#Y" .. self.参战单位[封印单位].名称 .. "#W被封印了")
					end
				end
			end
		elseif self.战斗类型 == 134481.8 and self.参战单位[n].队伍 == 0 and self.参战单位[n].名称 == "蓐收" then
			self.蓐收光环 = nil
			self.蓐收光环流程 = nil

			if self:取目标状态(n, n, 2) then
				local sl = self:取阵营倒地单位数量(0)

				if sl < 3 then
					self.蓐收光环 = {
						吸血 = 0.5,
						单位 = n
					}
				else
					local 次数 = math.min(sl - 2, 5)
					local 排除 = {}

					for i = 1, 次数 do
						目标 = self:取单个敌方目标(n, nil, 排除)

						if 目标 ~= 0 then
							排除[#排除 + 1] = 目标 + 0
							self.参战单位[n].指令.目标 = 目标

							if self:取目标状态(n, 目标, 1) then
								self:普通攻击计算(n, 1)
							end
						end
					end
				end
			end
		elseif self.战斗类型 == 134481.9 and self.参战单位[n].队伍 == 0 and self.参战单位[n].名称 == "句芒" then
			if self:取目标状态(n, n, 2) and self.回合数 >= 1 and self.回合数 % 2 == 0 then
				self.参战单位[n].指令 = {
					参数 = "句芒光环",
					目标 = n
				}
				self.不施法 = true

				self:法术计算(n, 1)
			end
		elseif self.战斗类型 == 134481.11 and self.参战单位[n].队伍 == 0 and self.参战单位[n].名称 == "玄冥" then
			if self:取目标状态(n, n, 2) and self.回合数 >= 1 and self.回合数 % 2 == 0 then
				self.参战单位[n].指令 = {
					参数 = "草木同根",
					目标 = n
				}

				self:法术计算(n, 1)
			end
		elseif self.战斗类型 == 134481.12 and self.参战单位[n].队伍 == 0 and self.参战单位[n].名称 == "共工" then
			self.共工光环 = nil

			if self:取目标状态(n, n, 2) then
				local sl = self:取阵营数量(0)

				if sl % 2 == 0 then
					self.共工光环 = 2
				else
					self.共工光环 = 1
				end
			end
		elseif self.战斗类型 == 100008.2 and self.参战单位[n].队伍 == 0 and self:取目标状态(n, n, 2) and self.参战单位[n].名称 == "梦靥夜叉" then
			if self.参战单位[n].特殊标记 == "画魂" then
				if self:取阵营数量(0) < 10 then
					self.战斗发言数据[#self.战斗发言数据 + 1] = {
						内容 = "有本事就把喽啰换成同一种类型#28",
						id = n
					}

					self:执行怪物召唤(n, 9.1, 0, 10 - self:取阵营数量(0))
				end

				local 怪物类型 = nil
				local 通过 = true

				for i = 1, #self.参战单位 do
					if self.参战单位[i].队伍 == 0 and self:取目标状态(i, i, 2) and self.参战单位[i].名称 ~= "梦靥夜叉" then
						if 怪物类型 == nil then
							怪物类型 = self.参战单位[i].名称
						end

						if self.参战单位[i].名称 ~= 怪物类型 then
							通过 = false

							break
						end
					end
				end

				if 通过 then
					任务数据[self.任务id].画魂奖励 = true
				end
			elseif self.参战单位[n].特殊标记 == "龙龟" then
				if self.龙龟召唤数量 == nil then
					self.龙龟召唤数量 = 15
				end

				if self:取阵营数量(0) < 10 and self.龙龟召唤数量 > 0 then
					self.战斗发言数据[#self.战斗发言数据 + 1] = {
						内容 = "带有宝贝的不要露脸了，小心宝贝被他们抢走！",
						id = n
					}

					self:执行怪物召唤(n, 9.2, 0, math.min(10 - self:取阵营数量(0), self.龙龟召唤数量))
				end
			elseif self.参战单位[n].特殊标记 == "厉鬼" and self.回合数 <= 2 and self:取阵营数量(0) < 10 then
				self:执行怪物召唤(n, 9.3, 0, 10 - self:取阵营数量(0))
			end
		end

		if self.参战单位[n].死亡状态 == 2 and self.参战单位[n].法术状态 ~= nil and self.参战单位[n].法术状态.九幽除名 ~= nil and self.参战单位[n].法术状态.九幽除名.复活 ~= nil then
			self.参战单位[n].死亡状态 = nil
			self.参战单位[n].气血 = qz(self.参战单位[n].法术状态.九幽除名.复活)
			self.参战单位[n].气血上限 = math.min(qz(self.参战单位[n].法术状态.九幽除名.复活 * 3), self.参战单位[n].最大气血)

			if self.参战单位[n].类型 == "bb" then
				self.参战单位[n].气血上限 = nil
			end

			self:流程处理状态(n, {
				{
					挨打方 = n,
					复活 = {
						气血 = self.参战单位[n].气血 + 0
					}
				}
			})
			self:添加战斗流程提示("#P(九幽除名)#R" .. self.参战单位[n].名称 .. "#W复活了")
		end

		if self.参战单位[n].法术状态 ~= nil and self.参战单位[n].法术状态.八戒上身 ~= nil and self.参战单位[n].法术状态.八戒上身.回合 == 1 then
			self:取消状态("八戒上身", self.参战单位[n])
			self:还原单位模型(n)
		end

		if self.参战单位[n].法术状态 ~= nil and self.参战单位[n].法术状态.金蟾 ~= nil and self.参战单位[n].法术状态.金蟾.回合 == 1 then
			local 金蟾境界 = self.参战单位[n].法术状态.金蟾.境界 + 0

			self:金蟾回血(n, 金蟾境界, 0.25)
		end

		if self:取奇经八脉是否有(n, "锻炼", "通天行者") and (self.参战单位[n].连续神通 or 0) >= 3 and ygsj() <= 10 and self.参战单位[n].法术状态.铜头铁臂 == nil then
			local aa = {
				self.参战单位[n].指令.参数,
				self.参战单位[n].指令.目标
			}
			self.参战单位[n].指令.参数 = "铜头铁臂"
			self.参战单位[n].指令.目标 = n

			self:法术计算(n)

			self.参战单位[n].指令.目标 = nil
			self.参战单位[n].指令.参数 = aa
		end
	end

	for n = 1, #self.参战单位 do
		if self.参战单位[n].气血 > 0 and self.参战单位[n].法术状态 ~= nil and self.参战单位[n].法术状态.天狐之舞 ~= nil then
			self.参战单位[n].法术状态.天狐之舞 = nil

			self:流程退场处理(n, "天狐之舞")
		end
	end
end

