function 战斗处理类:法宝计算(编号)
	local id = self.参战单位[编号].玩家id
	local 目标 = self.参战单位[编号].指令.目标
	local 道具 = self.参战单位[编号].指令.参数
	local 道具1 = 玩家数据[id].角色.数据.法宝[道具]
	local 名称 = 玩家数据[id].道具.数据[道具1].名称

	if 玩家数据[id].道具.数据[道具1].回合 ~= nil then
		if self.回合数 < 玩家数据[id].道具.数据[道具1].回合 then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/该法宝在当前回合无法使用")

			return
		end
	elseif self.参战单位[目标].气血 < 0 then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/目标已处于死亡状态，无法对其使用法宝")

		return
	elseif 玩家数据[id].道具.数据[道具1].魔法 < 5 then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/法宝灵气不足、使用失败！")

		return
	elseif self.参战单位[编号].法术状态.掌心雷 ~= nil then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "#P/(掌心雷)#Y当前角色无法使用主动法宝")

		return
	elseif self.参战单位[编号].法术状态.无字经 ~= nil then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "#P/(无字经)#Y使用主动法宝失败！")

		return
	end

	local 法宝类型 = 取法宝类型(名称)
	local 五行 = 玩家数据[id].道具.数据[道具1].五行
	local 法宝境界 = 玩家数据[id].道具.数据[道具1].气血

	if 法宝五行加成[法宝类型] ~= nil and 法宝五行加成[法宝类型][五行] ~= nil then
		法宝境界 = 法宝境界 + 法宝五行加成[法宝类型][五行]
	end

	local 临时物品 = 取物品数据(名称)
	self.执行等待 = self.执行等待 + 10
	玩家数据[id].道具.数据[道具1].魔法 = 玩家数据[id].道具.数据[道具1].魔法 - 5

	发送数据(玩家数据[id].连接id, 38, {
		内容 = "你的" .. 名称 .. "法宝减少了5点灵气"
	})

	if 名称 == "干将莫邪" or 名称 == "神木宝鼎" or 名称 == "苍白纸人" or 名称 == "五彩娃娃" or 名称 == "混元伞" or 名称 == "乾坤玄火塔" or 名称 == "天煞" or 名称 == "赤焰" or 名称 == "罗汉珠" or 名称 == "九梵清莲" or 名称 == "苍灵雪羽" or 名称 == "烽火狼烟" or 名称 == "璞玉灵钵" or 名称 == "铸兵锤" or 名称 == "金蟾" then
		if 名称 == "天煞" and self.参战单位[编号].门派 ~= "凌波城" then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/你无法使用#R凌波城#Y的门派法宝")

			return
		elseif 名称 == "神木宝鼎" and self.参战单位[编号].门派 ~= "神木林" then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/你无法使用#R神木林#Y的门派法宝")

			return
		elseif 名称 == "赤焰" and self.参战单位[编号].门派 ~= "魔王寨" then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/你无法使用#R魔王寨#Y的门派法宝")

			return
		elseif 名称 == "罗汉珠" and self.参战单位[编号].门派 ~= "化生寺" then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/你无法使用#R化生寺#Y的门派法宝")

			return
		elseif 名称 == "铸兵锤" and self.参战单位[编号].门派 ~= "九黎城" then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/你无法使用#R九黎城#Y的门派法宝")

			return
		elseif 名称 == "金蟾" and self.参战单位[编号].门派 ~= "无底洞" then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/你无法使用#R无底洞#Y的门派法宝")

			return
		end

		self:增益技能计算(编号, 名称, 0, nil, 1, 1, 法宝境界)
	elseif 名称 == "惊魂铃" or 名称 == "鬼泣" or 名称 == "摄魂" or 名称 == "断线木偶" or 名称 == "无魂傀儡" or 名称 == "缚妖索" or 名称 == "捆仙绳" or 名称 == "舞雪冰蝶" then
		self:减益技能计算(编号, 名称, 法宝境界, nil, 1, 法宝境界)
	elseif 名称 == "无字经" or 名称 == "发瘟匣" or 名称 == "无尘扇" then
		self:单体封印技能计算(编号, 名称, 法宝境界, true)
	elseif 名称 == "清心咒" or 名称 == "紫火如意" then
		self:恢复技能计算(编号, 名称, 法宝境界, true)
	end

	玩家数据[id].道具.数据[道具1].回合 = self.回合数 + 临时物品[7]

	if self:取奇经八脉是否有(编号, "神念") then
		self:增加愤怒(编号, 10)
	end
end

function 战斗处理类:道具计算(编号)
	if self.参战单位[编号].道具类型 == "法宝" or self.参战单位[编号].指令.附加 == "法宝" then
		if self.参战单位[编号].愈勇 ~= nil then
			self.参战单位[编号].愈勇 = 0
		end

		self:法宝计算(编号)

		return
	end

	local id = self.参战单位[编号].玩家id
	local 目标 = self.参战单位[编号].指令.目标
