		五龙丹 = 1,
		八角莲叶 = 1,
		草果 = 1,
		硫磺草 = 1
	}
	local 加魔道具 = {
		曼陀罗花 = 1,
		血珊瑚 = 1,
		紫丹罗 = 1,
		佛跳墙 = 1,
		旋复花 = 1,
		十香返生丸 = 1,
		鬼切草 = 1,
