	}
	local 使用类型 = nil

	if 加血道具[名称] ~= nil then
		使用类型 = 1
	elseif 加魔道具[名称] ~= nil then
		使用类型 = 2
	elseif 复活道具[名称] ~= nil then
		使用类型 = 3
	elseif 酒类道具[名称] ~= nil then
		使用类型 = 4
	elseif 名称 == "乾坤袋" then
		使用类型 = 5
	elseif 道具数据.总类 == 2000 then
		使用类型 = 6
		self.使用道具助攻 = 1
	elseif 名称 == "洞冥草" then
		使用类型 = 7
	end

	if 使用类型 == nil then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/此类道具无法在战斗中使用")

		return
	end

	self.执行等待 = self.执行等待 + 8
	local 药性 = 道具数据.药性
	local 阶品 = 道具数据.阶品
	local 药性倍愈 = 1

	if 药性 ~= nil then
		if 药性 == "倍愈" and ygsj(100) <= 25 then
