			self:添加战斗流程提示("#P(药性·倍愈)#R" .. self.参战单位[目标].名称 .. "#W本次获得#R双倍回复#W效果")
		elseif 药性 == "藏神" and ygsj(100) <= 60 then
			local hd = self:添加护盾(目标, 阶品 * 6 + 75, 编号)

			if (hd or 0) > 0 then
				self:添加战斗流程提示("#P(药性·藏神)#R" .. self.参战单位[目标].名称 .. "#W获得#R" .. hd .. "#W护盾")
			end
		elseif 药性 == "提气" and ygsj(100) <= 50 and self.参战单位[目标].法术状态.提气 == nil then
			self:添加状态("提气", self.参战单位[目标], self.参战单位[编号], 阶品 * 1, 编号)
			self:添加战斗流程提示("#P(药性·提气)#R" .. self.参战单位[目标].名称 .. "#W获得了#Y2#W回合#R提气#W效果")
		elseif 药性 == "守魂" and ygsj(100) <= 50 and self.参战单位[目标].法术状态.守魂 == nil then
			self:添加状态("守魂", self.参战单位[目标], self.参战单位[编号], qz1(阶品 * 0.4), 编号)
			self:添加战斗流程提示("#P(药性·守魂)#R" .. self.参战单位[目标].名称 .. "#W获得了#Y2#W回合#R守魂#W效果")
		elseif 药性 == "益疗" and ygsj(100) <= 50 and self.参战单位[目标].法术状态.益疗 == nil then
			self:添加状态("益疗", self.参战单位[目标], self.参战单位[编号], 阶品 * 1, 编号)
			self:添加战斗流程提示("#P(药性·益疗)#R" .. self.参战单位[目标].名称 .. "#W获得了#Y2#W回合#R益疗#W效果")
		end
	end

	if self:取奇经八脉是否有(目标, "执念") and 名称 ~= "金疮药" and 名称 ~= "百炼金乌丸" and 三级药列表1[名称] ~= nil and self.参战单位[目标].召唤兽 == 编号 then
		self:刷新五行珠(目标, self.参战单位[编号].攻击五行)
	end

	if self:取奇经八脉是否有(目标, "丹香") and 三级药列表1[名称] ~= nil then
		self:增加愤怒(目标, 2)
	end

	if 使用类型 == 1 then
		local 临时数值 = 玩家数据[id].道具:取加血道具1(名称, 道具1)

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "不坏") and self.参战单位[编号].气血 <= qz(self.参战单位[编号].最大气血 * 0.3) then
			临时数值 = qz(临时数值 * 1.3)
		end

		if self.参战单位[目标].气血 <= 0 then
