			}
			local 精准战斗流程 = #self.战斗流程 + 0
			local 气血 = self:取恢复气血(编号, 目标, 临时数值, "药品") * 药性倍愈

			if self.参战单位[目标].识药特性 ~= nil then
				气血 = qz(气血 * (1 + self.参战单位[目标].识药特性 * 0.05))
			end

			if self.参战单位[目标].神农 ~= nil and self.参战单位[目标].神农 == 1 then
				气血 = qz(气血 * 1.1)
			end

			self:增加气血(目标, 气血)

			self.战斗流程[精准战斗流程].挨打方[1].恢复气血 = 气血
			使用 = true

			if 名称 == "五龙丹" then
				self.战斗流程[精准战斗流程].挨打方[1].解除状态 = self:解除状态结果(self.参战单位[目标], self:取异常状态法术(), 名称)

				if #self.战斗流程[精准战斗流程].挨打方[1].解除状态 == 0 and self:负面技能施加判断(目标, "催眠符") then
