		if self.参战单位[目标].识药特性 ~= nil then
			临时数值 = qz(临时数值 * (1 + self.参战单位[目标].识药特性 * 0.05))
		end

		if self.参战单位[目标].气血 <= 0 then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "当前状态无法使用物品")

			return
		else
			self.战斗流程[#self.战斗流程 + 1] = {
				流程 = 60,
				攻击方 = 编号,
				挨打方 = {
					{
