						解除状态 = {},
						特效 = {
							"加蓝"
						}
					}
				},
				提示 = {
					类型 = "法术",
					允许 = true,
					名称 = self.参战单位[编号].名称 .. "使用了" .. 名称
				}
			}
			local 精准战斗流程 = #self.战斗流程 + 0

			if self.参战单位[目标].神农 ~= nil and self.参战单位[目标].神农 == 1 then
				临时数值 = qz(临时数值 * 1.1)
			end

			self:增加魔法(目标, 临时数值)

			使用 = true
		end
	elseif 使用类型 == 3 then
		local 临时数值 = 玩家数据[id].道具:取加血道具1(名称, 道具1) * 药性倍愈

		if self.参战单位[目标].类型 ~= "角色" and self.参战单位[目标].驯兽 == nil or self.参战单位[目标].法术状态.死亡召唤 or self.参战单位[目标].法术状态.锢魂术 or self.参战单位[目标].气血 > 0 then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "当前状态无法使用物品")

			return
		else
			self.战斗流程[#self.战斗流程 + 1] = {
				流程 = 60,
				攻击方 = 编号,
				挨打方 = {
					{
						挨打方 = 目标,
						解除状态 = {},
						特效 = {
							"加血"
						}
					}
				},
