			self.战斗流程[精准战斗流程].挨打方[1].复活 = true
			使用 = true
			self.执行中复活单位[#self.执行中复活单位 + 1] = 目标
			self.回合中复活 = true

			if self.参战单位[目标].驯兽 ~= nil and self.参战单位[编号].召唤兽 == 目标 and self:取奇经八脉是否有(编号, "回光") and ygsj() <= 50 and self:取法术状态(目标) then
				self:添加战斗流程提示("#P(回光)#R" .. self.参战单位[目标].名称 .. "#W将使用一次#Y幼狮之搏")
				self:物攻技能计算(目标, "幼狮之搏", self:取技能等级(目标, "幼狮之搏"))
			end
		end
	elseif 使用类型 == 4 then
