					self.参战单位[目标].法术状态.催眠符.回合 = 取随机数(2, 3)
					self.战斗流程[精准战斗流程1].挨打方[1].添加状态 = "催眠符"
				end
			elseif 名称 == "蛇胆酒" then
				self.参战单位[目标].防御 = self.参战单位[目标].防御 - qz(临时数值 * 1.5)
			elseif 名称 == "百味酒" then
				if ygsj() <= 50 then
					if self:负面技能施加判断(目标, "催眠符") then
						self.战斗流程[#self.战斗流程 + 1] = {
							流程 = 207,
							攻击方 = 编号,
							挨打方 = {
								{
									增加状态 = "催眠符",
									挨打方 = 目标,
									特效 = {
										"加血"
									}
								}
							}
						}
						local 精准战斗流程1 = #self.战斗流程 + 0

						self:添加状态("催眠符", self.参战单位[目标], self.参战单位[编号], 150, 编号)

						self.参战单位[目标].法术状态.催眠符.回合 = 取随机数(2, 3)
						self.战斗流程[精准战斗流程1].挨打方[1].添加状态 = "催眠符"
					end
				elseif self:负面技能施加判断(目标, "毒") then
					self.战斗流程[#self.战斗流程 + 1] = {
						流程 = 207,
						攻击方 = 编号,
						挨打方 = {
							{
								增加状态 = "毒",
								挨打方 = 目标,
								特效 = {
									"加血"
								}
							}
						}
					}
					local 精准战斗流程1 = #self.战斗流程 + 0

					self:添加状态("毒", self.参战单位[目标], self.参战单位[编号], 150, 编号)

					self.参战单位[目标].法术状态.毒.回合 = 5
					self.战斗流程[精准战斗流程1].挨打方[1].添加状态 = "毒"
				end
			elseif 名称 == "醉生梦死" or 名称 == "虎骨酒" then
				self.战斗流程[#self.战斗流程 + 1] = {
					流程 = 207,
					攻击方 = 编号,
					挨打方 = {
						{
							增加状态 = "疯狂",
							挨打方 = 目标,
							特效 = {
								"加血"
							}
						}
					}
				}
				local 精准战斗流程1 = #self.战斗流程 + 0

				self:添加状态("疯狂", self.参战单位[目标], self.参战单位[编号], 150, 编号)

				self.参战单位[目标].法术状态.疯狂.回合 = 取随机数(2, 3)
			end
		end
	elseif 使用类型 == 5 then
		if self.参战单位[目标].乾坤袋 == nil then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/你无法对此类目标使用乾坤袋")

			return
		elseif self.参战单位[编号].类型 ~= "角色" then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/只有角色才可以使用此道具")

			return
		else
			self.战斗流程[#self.战斗流程 + 1] = {
				流程 = 56,
				攻击方 = 编号,
				挨打方 = {},
				提示 = {
					类型 = "法术",
					允许 = true,
					名称 = self.参战单位[编号].名称 .. "使用了" .. 名称
				}
			}
			local 精准战斗流程 = #self.战斗流程 + 0
			self.战斗流程[精准战斗流程].挨打方[1] = {
				挨打方 = 目标,
				特效 = {
					"金甲仙衣_敌方"
				}
			}
			local 百分比 = qz1(100 - self.参战单位[编号].气血 / self.参战单位[编号].最大气血 * 100)
			百分比 = 百分比 + 20

			if ygsj() <= 百分比 then
				self.战斗流程[精准战斗流程].挨打方[1].气血 = self.参战单位[目标].气血
				self.战斗流程[精准战斗流程].挨打方[1].死亡 = self:减少气血(目标, self.参战单位[目标].气血, 编号, nil, nil, nil, 1)
				任务数据[self.任务id].乾坤袋 = true

				玩家数据[self.参战单位[编号].玩家id].角色:刷新任务跟踪()
			end
		end
	elseif 使用类型 == 6 then
		local 等级 = self:取技能等级(编号, "满天花雨")
		local 人数 = 1
		local 等级伤害 = 0
		local 伤害 = 道具数据.分类
		local 暗器伤害 = 0
		人数 = math.floor(等级 / 20) + 1

		if 等级 == 0 then
			等级 = 30
		end

		等级伤害 = math.floor(等级 / 40) * 伤害
		暗器伤害 = (self.参战单位[编号].暗器技巧 or 0) * 2

		if self.战斗类型 == 110009 and self.参战单位[目标].模型 == "星灵仙子" then
			伤害 = 伤害 * 50
		end

		local 目标组 = self:取多个敌方目标(编号, 目标, 人数)
		伤害 = 伤害 * 0.7 + 暗器伤害 / 2 + 等级伤害 * 0.5

		if self.参战单位[编号].门派 == "女儿村" then
			伤害 = 伤害 + 50
		end

		if self.参战单位[编号].固定伤害 ~= nil then
			伤害 = 伤害 + qz(self.参战单位[编号].固定伤害)
		end

		if self:取奇经八脉是否有(编号, "暗刃") then
			伤害 = 伤害 * 1.18
		end

		local gl = 10

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "独尊") then
			gl = gl - 4
		end

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "重明") then
			gl = gl - 4
		end

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "杏花") then
			gl = gl + 4
		end

		if 编号 ~= nil and self:取敌方拥有指定状态人数(编号, "毒", "暗器毒") == 0 then
			gl = gl + 6
		end

		if #目标组 > 0 then
			self.战斗流程[#self.战斗流程 + 1] = {
				流程 = 611,
				攻击方 = 编号,
				挨打方 = {},
				提示 = {
					类型 = "法术",
					允许 = true,
					名称 = self.参战单位[编号].名称 .. "使用了" .. 名称
				}
			}
			local 精准战斗流程 = #self.战斗流程 + 0

			for n = 1, #目标组 do
				if self.参战单位[编号].门派 == "女儿村" and ygsj() <= gl then
					self:添加暗器毒(目标组[n], 编号)
				end

				self.战斗流程[精准战斗流程].挨打方[n] = {
					挨打方 = 目标组[n],
					伤害 = self:取固伤结果(编号, 伤害, 目标组[n])
				}
				self.战斗流程[精准战斗流程].挨打方[n].死亡 = self:减少气血(目标组[n], self.战斗流程[精准战斗流程].挨打方[n].伤害, 编号, 名称, nil, nil, 1)
			end

			玩家数据[id].道具.数据[道具1].耐久 = 玩家数据[id].道具.数据[道具1].耐久 - 1

			if 玩家数据[id].道具.数据[道具1].耐久 <= 0 then
				玩家数据[id].道具.数据[道具1] = nil
				玩家数据[id].角色.数据.道具[道具] = nil
			end

			return
		end
	elseif 使用类型 == 7 then
		self:增益技能计算(编号, "知己知彼")
	end

	if 使用 then
		if 道具数据.数量 ~= nil then
			玩家数据[id].道具.数据[道具1].数量 = 玩家数据[id].道具.数据[道具1].数量 - 1
		end

		if 玩家数据[id].道具.数据[道具1].数量 == nil or 玩家数据[id].道具.数据[道具1].数量 < 1 then
			玩家数据[id].道具.数据[道具1] = nil
			玩家数据[id].角色.数据.道具[道具] = nil
		end
	end
end

function 战斗处理类:兵解符计算(编号)
	local id = self.参战单位[编号].玩家id
	local 编号 = 0

	for n = 1, #self.参战玩家 do
		if self.参战玩家[n].id == id then
			self.参战玩家[n].断线 = false
			self.参战玩家[n].断线等待 = true
			self.参战玩家[n].连接id = 玩家数据[id].连接id
			编号 = n
		end
	end

	if 玩家数据[id].角色.数据.地图数据.编号 >= 6010 and 玩家数据[id].角色.数据.地图数据.编号 <= 6019 then
		常规提示(id, "该地图无法传送")

		return
	end

	战斗准备类.战斗盒子[玩家数据[id].战斗]:结束战斗1(0, id)
	发送数据(玩家数据[id].连接id, 1501, self.发送数据)
	地图处理类:跳转地图(id, 1135, 72, 63)
end

function 战斗处理类:逃跑计算(编号, 附加几率)
	if 附加几率 ~= nil then
		几率 = 附加几率
	end

	local 成功 = false
	local 几率 = 30

	if self.参战单位[编号].法术状态.捆仙绳 ~= nil and (self.战斗类型 == 410005 or self.战斗类型 == 200004 or self.战斗类型 == 200005 or self.战斗类型 == 200006) then
		几率 = 100

		self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/比武不能逃跑！")
	end

	if self.参战单位[编号].法术状态.捆仙绳 ~= nil then
		几率 = 几率 + self.参战单位[编号].法术状态.捆仙绳.逃跑概率
	end

	if self.参战单位[编号].法术状态.缚妖索 ~= nil then
		几率 = 几率 + self.参战单位[编号].法术状态.缚妖索.逃跑概率
	end

	if self.参战单位.迷踪 ~= nil and self.参战单位.迷踪 == 1 then
		几率 = 几率 - 10
	end

	if self.参战单位[编号].指令.参数 == "兵解符" then
		几率 = 0
	end

	if 几率 <= ygsj() or self.参战单位[编号].必定逃跑 == 1 then
		成功 = true
		self.参战单位[编号].必定逃跑 = nil
	end

	if self.参战单位[编号].类型 == "角色" and self.参战单位[编号].助战编号 ~= nil then
		成功 = true
	end

	self.执行等待 = self.执行等待 + 10
	local 结束 = false

	if 成功 and self.参战单位[编号].类型 == "角色" and self.参战单位[编号].助战编号 == nil then
		结束 = true

		if #self.参战玩家 == 1 then
			self.全局结束 = true
		end
	end

	if 成功 then
		self.参战单位[编号].逃跑 = true
	end

	if self.参战单位[编号].队伍 == 0 then
		self.战斗流程[#self.战斗流程 + 1] = {
			id = 0,
			流程 = 601,
			攻击方 = 编号,
			挨打方 = {
				{
					挨打方 = 1
				}
			},
			成功 = 成功,
			结束 = 结束
		}

		if self.参战单位[编号].捉鬼变异 then
			任务数据[self.任务id].变异奖励 = true
		end

		return
	else
		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 601,
			攻击方 = 编号,
			id = self.参战单位[编号].玩家id,
			挨打方 = {
				{
					挨打方 = 1
				}
			},
			成功 = 成功,
			结束 = 结束
		}
	end

	local 精准战斗流程 = #self.战斗流程 + 0

	if 成功 then
		local id = self.参战单位[编号].玩家id
		local 临时编号 = 0

		if self.参战单位[编号].类型 ~= "角色" then
			发送数据(玩家数据[id].连接id, 18, 玩家数据[id].角色.数据.参战宝宝)
		elseif self.参战单位[编号].召唤兽 ~= nil and self.参战单位[self.参战单位[编号].召唤兽] ~= nil then
			self.战斗流程[精准战斗流程].追加 = self.参战单位[编号].召唤兽
			self.参战单位[self.参战单位[编号].召唤兽].逃跑 = true
		end
	end
end

function 战斗处理类:更新召唤数量(编号, 召唤兽编号)
	local 更新助战 = false
	local 主人编号 = 0
	self.参战单位[编号].召唤数量[#self.参战单位[编号].召唤数量 + 1] = 召唤兽编号

	if self.参战单位[编号].助战编号 ~= nil then
		if self.队长单位[self.参战单位[编号].队伍] == self.参战单位[编号].主人 then
			更新助战 = true
			主人编号 = self.参战单位[编号].主人
			self.参战单位[主人编号].召唤总数量[#self.参战单位[主人编号].召唤总数量 + 1] = 召唤兽编号
		end
	else
		self.参战单位[编号].召唤总数量[#self.参战单位[编号].召唤总数量 + 1] = 召唤兽编号
	end
end

function 战斗处理类:召唤计算(编号)
	local id = self.参战单位[编号].召唤兽 or 编号 + 1
	local 目标 = self.参战单位[编号].指令.目标
	local 玩家id = self.参战单位[编号].玩家id
	self.参战单位[编号].肝胆 = nil

	if self:取奇经八脉是否有(编号, "肝胆") and self:取目标状态(id, id, 2) == false then
		self.参战单位[编号].肝胆 = 1
	end

	self.薪火相传血量 = 0

	if id ~= nil and self.参战单位[id] ~= nil and self.参战单位[id].气血 > 0 then
		self.薪火相传血量 = self.参战单位[id].气血
	end

	if self:取奇经八脉是否有(编号, "长啸") and (self.参战单位[id].死亡状态 ~= nil or self.参战单位[id].逃跑 == true) then
		self.参战单位[编号].长啸 = 1
	end

	if self.参战单位[id].逃跑 ~= true and self.参战单位[id].死亡状态 ~= 1 and self.参战单位[id].遗志 ~= nil and self.参战单位[id].遗志 > 0 then
		self.遗志层数 = self.参战单位[id].遗志
	end

	if 玩家数据[玩家id] == nil then
		print("玩家数据玩家ID为NIL,玩家ID为" .. 玩家id)
	elseif 玩家数据[玩家id].召唤兽.数据[目标] == nil then
		print("召唤兽为NIL,目标为" .. 目标)
	elseif 玩家数据[玩家id].召唤兽.数据[目标].等级 == nil then
		print("召唤时等级为NIL,召唤目标为" .. 目标)
	end

	local 召唤主人 = self.参战单位[编号]

	if self.参战单位[编号].助战编号 ~= nil then
		召唤主人 = self.参战单位[self.参战单位[编号].主人]
	end

	召唤主人.召唤数量 = 召唤主人.召唤数量 or {}
	local 高于等级 = 召唤兽参战高于等级

	if 玩家数据[玩家id].角色.数据.飞升 == true then
		高于等级 = 召唤兽参战高于等级 + 飞升高于等级
	end

	if #self.参战单位[编号].召唤数量 >= 7 then
		self:添加提示(召唤主人.玩家id, 编号, "#Y/你在本次战斗中可召唤的召唤兽数量已达上限")

		return
	elseif 玩家数据[玩家id].召唤兽.数据[目标].等级 > 玩家数据[玩家id].角色.数据.等级 + 高于等级 then
		self:添加提示(召唤主人.玩家id, 编号, "#Y/以你目前的实力还无法驾驭该等级的召唤兽")

		return
	end

	for n = 1, #召唤主人.召唤总数量 do
		if 召唤主人.召唤总数量[n] == 目标 then
			self:添加提示(召唤主人.玩家id, 编号, "#Y/这只召唤兽已经出战过了")

			return
		end
	end

	self.执行等待 = self.执行等待 + 2

	if id == nil then
		self:设置队伍区分(self.参战单位[编号].队伍)

		id = 编号 + 1
	end

	self.参战单位[id] = {}
	local master = nil

	for k, v in pairs(self.参战单位) do
		if v.玩家id and v.玩家id == self.参战单位[编号].玩家id and v.助战编号 == nil then
			master = k

			break
		end
	end

	self.参战单位[id] = table.loadstring(玩家数据[玩家id].召唤兽:获取指定数据(目标))

	self:加载单位通用属性(id)

	self.参战单位[编号].召唤兽 = id + 0
	self.参战单位[id].队伍 = self.参战单位[编号].队伍
	self.参战单位[id].位置 = self.参战单位[编号].位置 + 5
	self.参战单位[id].类型 = "bb"
	self.参战单位[id].主人 = master
	self.参战单位[id].玩家id = 玩家id
	self.参战单位[id].附加阵法 = self.参战单位[编号].附加阵法

	if self.参战单位[id].法伤 == nil then
		self.参战单位[id].法伤 = self.参战单位[id].灵力
	else
		self.参战单位[id].法伤 = self.参战单位[id].法伤
	end

	self.参战单位[id].灵伤差 = self.参战单位[id].法伤 - self.参战单位[id].灵力

	if self.参战单位[id].法防 == nil then
		self.参战单位[id].法防 = self.参战单位[id].灵力
	else
		self.参战单位[id].法防 = self.参战单位[id].法防
	end

	self.参战单位[id].命中 = self.参战单位[id].伤害
	self.参战单位[id].躲避 = self.参战单位[id].躲避 or 0
	self.参战单位[id].自动战斗 = self.参战单位[master].自动战斗
	self.参战单位[编号].召唤兽 = id

	self:更新召唤数量(编号, 目标)

	self.参战单位[id].指令 = {
		参数 = "",
		敌我 = 0,
		附加 = "",
		类型 = "",
		目标 = 0,
		下达 = false
	}
	self.参战单位[id].攻击修炼 = 玩家数据[self.参战单位[id].玩家id].角色.数据.bb修炼.攻击控制力[1]
	self.参战单位[id].法术修炼 = 玩家数据[self.参战单位[id].玩家id].角色.数据.bb修炼.法术控制力[1]
	self.参战单位[id].防御修炼 = 玩家数据[self.参战单位[id].玩家id].角色.数据.bb修炼.防御控制力[1]
	self.参战单位[id].抗法修炼 = 玩家数据[self.参战单位[id].玩家id].角色.数据.bb修炼.抗法控制力[1]
	self.参战单位[id].驱怪 = 0
	self.参战单位[id].慈悲效果 = 0
	self.参战单位[id].怒击效果 = false
	self.参战单位[id].猎术修炼 = 0
	self.参战单位[id].毫毛次数 = 0
	self.参战单位[id].攻击五行 = self.参战单位[id].五行 or 取五行()
	self.参战单位[id].防御五行 = self.参战单位[id].五行 or 取五行()

	if self.参战单位[编号].助战编号 then
		self.参战单位[master].助战明细[#self.参战单位[master].助战明细 + 1] = id
	else
		local 临时技能 = {}
		self.参战单位[编号].召唤还原 = 1
		玩家数据[玩家id].角色.数据.参战宝宝 = {}
		玩家数据[玩家id].角色.数据.参战宝宝 = table.loadstring(table.tostring(玩家数据[玩家id].召唤兽:取存档数据(目标)))
	end

	发送数据(玩家数据[玩家id].连接id, 18, 玩家数据[玩家id].角色.数据.参战宝宝)

	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 600,
		攻击方 = 编号,
		挨打方 = {
			{
				挨打方 = id,
				队伍 = self.参战单位[编号].队伍,
				数据 = self:取加载信息(id)
			}
		}
	}

	self:单独重置属性(id)

	if self.参战单位[id].隐身 ~= nil then
		self:添加状态("修罗隐身", self.参战单位[id], self.参战单位[id], self.参战单位[id].等级)

		if self.参战单位[id].法术状态.修罗隐身 ~= nil then
			self.参战单位[id].法术状态.修罗隐身.回合 = self.参战单位[id].隐身
		end

		self:客户端添加状态(id, "修罗隐身")
	end

	if self.参战单位[id].盾气 ~= nil then
		self:添加状态("盾气", self.参战单位[id], self.参战单位[id], self.参战单位[id].等级, id, self.参战单位[id].盾气)

		if self.参战单位[id].法术状态.盾气 ~= nil then
			self.参战单位[id].法术状态.盾气.回合 = 5
		end

		self:客户端添加状态(id, "盾气")
	end

	if self.参战单位[id].与生俱来 ~= nil then
		self:添加护盾(id, self.参战单位[id].最大气血 * self.参战单位[id].与生俱来, id, 1)
		self:客户端添加状态(id, "护盾")
	end

	if self.参战单位[id].遗志 ~= nil then
		self.参战单位[id].遗志 = self.参战单位[id].遗志 + 1 + (self.遗志层数 or 0)

		if self.参战单位[id].超级遗志 ~= nil then
			self.参战单位[id].遗志 = math.min(self.参战单位[id].遗志, 3)
		else
			self.参战单位[id].遗志 = math.min(self.参战单位[id].遗志, 2)
		end

		self:添加状态("遗志", self.参战单位[id], self.参战单位[id], self.参战单位[id].遗志, id, self.参战单位[id].遗志系数)
		常规提示(self.参战单位[id].玩家id, "#P(遗志)#R" .. self.参战单位[id].名称 .. "#W继承#G前人遗志#W、获得了#Y" .. self.参战单位[id].遗志 .. "#W层遗志效果")
	end

	self.遗志层数 = nil

	if self.参战单位[id].薪火相传 ~= nil and self.薪火相传血量 > 0 then
		local hd = self:添加状态("护盾", self.参战单位[id], self.参战单位[id], self.薪火相传血量)

		if hd > 0 then
			常规提示(self.参战单位[id].玩家id, "#P(薪火相传)#R" .. self.参战单位[id].名称 .. "#W获得#G" .. hd .. "#W点护盾")
		end

		self:客户端添加状态(id, "薪火相传")
	end

	if self:取技能重复(self.参战单位[id], "峰回路转") then
		self:恢复技能计算(id, "峰回路转", self.参战单位[id].等级)
	end

	if self.参战单位[id].逍遥游 ~= nil and self:取是否有主动技能(self.参战单位[id].主动技能, "扶摇万里") == true then
		local 鲲鹏数量 = self:取在场单位指定模型数量("鲲鹏") + self:取在场单位指定模型数量("进阶鲲鹏")

		if 判断模型是否是(self.参战单位[id], "鲲鹏") then
			鲲鹏数量 = 鲲鹏数量 - 1
		end

		if 鲲鹏数量 < 1 then
			self.逍遥游增伤 = 2.5
		end

		self:法攻技能计算(id, "扶摇万里1", self.参战单位[id].等级, 1)

		self.逍遥游增伤 = 0
	end

	if self.参战单位[id].逍遥游 ~= nil and self:取是否有主动技能(self.参战单位[id].主动技能, "水击三千") == true then
		local 鲲鹏数量 = self:取在场单位指定模型数量("鲲鹏") + self:取在场单位指定模型数量("进阶鲲鹏")

		if 判断模型是否是(self.参战单位[id], "鲲鹏") then
			鲲鹏数量 = 鲲鹏数量 - 1
		end

		if 鲲鹏数量 < 1 then
			self.逍遥游增伤 = 2.5
		end

		self:物攻技能计算(id, "水击三千1", self.参战单位[id].等级)

		self.逍遥游增伤 = 0
	end

	if self.回合数 >= 2 then
		if self.参战单位[id].特性 ~= nil then
			self:添加状态特性(id)
		end

		if self.参战单位[id].进击必杀 ~= nil then
			self.召唤加回合 = 1

			self:添加状态("进击必杀", self.参战单位[id], self.参战单位[id], self.参战单位[id].进击必杀, id, 1)
		end

		if self.参战单位[id].进击法爆 ~= nil then
			self.召唤加回合 = 1

			self:添加状态("进击法爆", self.参战单位[id], self.参战单位[id], self.参战单位[id].进击法爆, id, 1)
		end
	end

	if self.参战单位[编号].肝胆 ~= nil then
		self.参战单位[编号].肝胆鹰击 = 1.55
		self.参战单位[编号].肝胆连环击 = 1.55
	end

	if self:取奇经八脉是否有(编号, "伴舞") then
		self:添加状态("乐韵", self.参战单位[编号])
	end

	if self.参战单位[编号].长啸 ~= nil then
		self:添加状态("狂怒", self.参战单位[编号])

		self.参战单位[编号].法术状态.狂怒.回合 = 3

		self:客户端添加状态(编号, "狂怒")
	end

	self.参战单位[编号].长啸 = nil
end

function 战斗处理类:取是否有被动技能(编号, 名称)
	if self.参战单位[编号].已加技能 ~= nil and self.参战单位[编号].已加技能[名称] ~= nil then
		return true
	else
		return false
	end
end

function 战斗处理类:取是否有师门技能(编号, 名称)
	if self.参战单位[编号].被动技能 ~= nil and self.参战单位[编号].被动技能[名称] ~= nil then
		return true
	else
		return false
	end
end

function 战斗处理类:取是否有主动技能(技能列表, 名称)
	local 列表1 = {}

	for i = 1, #技能列表 do
		列表1[i] = 技能列表[i].名称
	end

	return 取列表中是否存在内容(列表1, 名称)
end

function 战斗处理类:取在场单位指定模型数量(模型)
	local n = 0

	for i = 1, #self.参战单位 do
		if self.参战单位[i].模型 == 模型 and self.参战单位[i].逃跑 ~= true and self.参战单位[i].死亡状态 ~= 1 then
			n = n + 1
		end
	end

	return n
end

function 战斗处理类:召唤孩子计算(编号)
	local id = self.参战单位[编号].召唤兽 or 编号 + 1
	local 玩家id = self.参战单位[编号].玩家id
	local 目标 = self.参战单位[编号].指令.目标 - #玩家数据[玩家id].召唤兽.数据

	if 玩家数据[玩家id] == nil then
		print("玩家数据玩家ID为NIL,玩家ID为" .. 玩家id)
	elseif 玩家数据[玩家id].召唤兽.数据[目标] == nil then
		print("孩子为NIL,目标为" .. 目标)
	elseif 玩家数据[玩家id].召唤兽.数据[目标].等级 == nil then
		print("召唤时等级为NIL,召唤目标为" .. 目标)
	end

	self.薪火相传血量 = 0

	if id ~= nil and self.参战单位[id].气血 > 0 then
		self.薪火相传血量 = self.参战单位[id].气血
	end

	local 高于等级 = 召唤兽参战高于等级

	if 玩家数据[玩家id].角色.数据.飞升 == true then
		高于等级 = 召唤兽参战高于等级 + 飞升高于等级
	end

	if id ~= nil and self.参战单位[id].法术状态.复活 ~= nil then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/你有召唤兽尚在复活中，暂时无法召唤新的召唤兽")

		return
	elseif 玩家数据[玩家id].召唤兽.数据[目标].等级 > 玩家数据[玩家id].角色.数据.等级 + 召唤兽参战高于等级 then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/以你目前的实力还无法驾驭该等级的孩子")

		return
	end

	local 召唤主人 = self.参战单位[编号]

	if self.参战单位[编号].助战编号 ~= nil then
		召唤主人 = self.参战单位[self.参战单位[编号].主人]
	end

	召唤主人.召唤数量 = 召唤主人.召唤数量 or {}
	local 高于等级 = 召唤兽参战高于等级

	if 玩家数据[玩家id].角色.数据.飞升 == true then
		高于等级 = 召唤兽参战高于等级 + 飞升高于等级
	end

	if #self.参战单位[编号].召唤数量 >= 10 then
		self:添加提示(召唤主人.玩家id, 编号, "#Y/你在本次战斗中可召唤的数量已达上限")

		return
	elseif 玩家数据[玩家id].召唤兽.数据[目标].参战信息 then
		self:添加提示(召唤主人.玩家id, 编号, "#Y/这只孩子已经出战了")

		return
	elseif 玩家数据[玩家id].召唤兽.数据[目标].等级 > 玩家数据[玩家id].角色.数据.等级 + 高于等级 then
		self:添加提示(召唤主人.玩家id, 编号, "#Y/以你目前的实力还无法驾驭该等级的孩子")

		return
	end

	召唤主人.召唤总数量 = 召唤主人.召唤总数量 or {}

	for n = 1, #召唤主人.召唤总数量 do
		if 召唤主人.召唤总数量[n] == 目标 then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/这只孩子已经出战过了")

			return
		end
	end

	self.执行等待 = self.执行等待 + 2

	if id == nil then
		self:设置队伍区分(self.参战单位[编号].队伍)

		id = #self.参战单位 + 1
	end

	self.参战单位[id] = {}
	self.参战单位[id] = table.loadstring(玩家数据[玩家id].召唤兽:获取指定数据(目标))

	self:加载单位通用属性(id)

	self.参战单位[id].队伍 = self.参战单位[编号].队伍
	self.参战单位[id].位置 = self.参战单位[编号].位置 + 5
	self.参战单位[id].类型 = "孩子"
	self.参战单位[id].主人 = 编号
	self.参战单位[id].玩家id = 玩家id
	self.参战单位[编号].召唤兽 = id + 0
	self.参战单位[id].附加阵法 = self.参战单位[编号].附加阵法

	if self.参战单位[id].法伤 == nil then
		self.参战单位[id].法伤 = self.参战单位[id].灵力
	else
		self.参战单位[id].法伤 = self.参战单位[id].法伤
	end

	self.参战单位[id].灵伤差 = self.参战单位[id].法伤 - self.参战单位[id].灵力

	if self.参战单位[id].法防 == nil then
		self.参战单位[id].法防 = self.参战单位[id].灵力
	else
		self.参战单位[id].法防 = self.参战单位[id].法防
	end

	self.参战单位[id].命中 = self.参战单位[id].伤害
	self.参战单位[id].躲避 = self.参战单位[id].躲避 or 0
	self.参战单位[id].自动战斗 = self.参战单位[编号].自动战斗
	self.参战单位[编号].召唤兽 = id

	self:更新召唤数量(编号, 目标 - #玩家数据[玩家id].召唤兽.数据)

	self.参战单位[id].指令 = {
		参数 = "",
		敌我 = 0,
		附加 = "",
		类型 = "",
		目标 = 0,
		下达 = false
	}
	self.参战单位[id].攻击修炼 = 玩家数据[self.参战单位[id].玩家id].角色.数据.bb修炼.攻击控制力[1]
	self.参战单位[id].法术修炼 = 玩家数据[self.参战单位[id].玩家id].角色.数据.bb修炼.法术控制力[1]
	self.参战单位[id].防御修炼 = 玩家数据[self.参战单位[id].玩家id].角色.数据.bb修炼.防御控制力[1]
	self.参战单位[id].抗法修炼 = 玩家数据[self.参战单位[id].玩家id].角色.数据.bb修炼.抗法控制力[1]
	self.参战单位[id].驱怪 = 0
	self.参战单位[id].慈悲效果 = 0
	self.参战单位[id].怒击效果 = false
	self.参战单位[id].猎术修炼 = 0
	self.参战单位[id].毫毛次数 = 0
	self.参战单位[id].攻击五行 = self.参战单位[id].五行 or 取五行()
	self.参战单位[id].防御五行 = self.参战单位[id].五行 or 取五行()

	for n = 1, #玩家数据[玩家id].召唤兽.数据 do
		if 玩家数据[玩家id].召唤兽.数据[n].认证码 == 玩家数据[玩家id].角色.数据.参战宝宝.认证码 then
			玩家数据[玩家id].召唤兽.数据[n].参战信息 = nil
		end
	end

	玩家数据[玩家id].角色.数据.参战宝宝 = {}
	玩家数据[玩家id].角色.数据.参战信息 = nil
	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 600,
		攻击方 = 编号,
		挨打方 = {
			{
				挨打方 = id,
				队伍 = self.参战单位[编号].队伍,
				数据 = self:取加载信息(id)
			}
		}
	}

	self:单独重置属性(id)

	if self.参战单位[id].隐身 ~= nil then
		self:添加状态("修罗隐身", self.参战单位[id], self.参战单位[id], self.参战单位[id].等级)

		if self.参战单位[id].法术状态.修罗隐身 ~= nil then
			self.参战单位[id].法术状态.修罗隐身.回合 = self.参战单位[id].隐身
		end

		self:客户端添加状态(id, "修罗隐身")
	end

	if self.参战单位[id].盾气 ~= nil then
		self:添加状态("盾气", self.参战单位[id], self.参战单位[id], self.参战单位[id].等级, id, self.参战单位[id].盾气)

		if self.参战单位[id].法术状态.盾气 ~= nil then
			self.参战单位[id].法术状态.盾气.回合 = 5
		end

		self:客户端添加状态(id, "盾气")
	end

	if self.参战单位[id].与生俱来 ~= nil then
		self:添加护盾(id, self.参战单位[id].最大气血 * self.参战单位[id].与生俱来, id, 1)
		self:客户端添加状态(id, "护盾")
	end

	if self.参战单位[id].薪火相传 ~= nil and self.薪火相传血量 > 0 then
		local hd = self:添加状态("护盾", self.参战单位[id], self.参战单位[id], self.薪火相传血量)

		if hd > 0 then
			常规提示(self.参战单位[id].玩家id, "#P(薪火相传)#R" .. self.参战单位[id].名称 .. "#W获得#G" .. hd .. "#W点护盾")
		end

		self:客户端添加状态(id, "薪火相传")
	end

	if self:技能是否存在(id, "峰回路转") then
		self:恢复技能计算(id, "峰回路转", self.参战单位[id].等级)
	end
end

function 战斗处理类:单独重置属性(n)
	self.参战单位[n].法术状态 = {}
	self.参战单位[n].奇经八脉 = {}
	self.参战单位[n].追加法术 = {}
	self.参战单位[n].附加状态 = {}
	self.参战单位[n].攻击修炼 = 0
	self.参战单位[n].法术修炼 = 0
	self.参战单位[n].防御修炼 = 0
	self.参战单位[n].抗法修炼 = 0
	self.参战单位[n].猎术修炼 = 0

	if self.参战单位[n].主动技能 == nil then
		self.参战单位[n].主动技能 = {}
	end

	self.参战单位[n].特技技能 = {}
	self.参战单位[n].战意 = 0
	self.参战单位[n].法暴 = 基础法暴率 + 0
	self.参战单位[n].必杀 = 基础暴击率 + 0
	self.参战单位[n].攻击五行 = self.参战单位[n].攻击五行 or self.参战单位[n].五行 or 取五行()
	self.参战单位[n].防御五行 = self.参战单位[n].防御五行 or self.参战单位[n].五行 or 取五行()
	self.参战单位[n].修炼数据 = {
		猎术 = 0,
		抗法 = 0,
		攻击 = 0,
		法修 = 0
	}

	if self.参战单位[n].命中 == nil then
		self.参战单位[n].命中 = self.参战单位[n].伤害
	end

	for i = 1, #灵饰战斗属性 do
		self.参战单位[n][灵饰战斗属性[i]] = self.参战单位[n][灵饰战斗属性[i]] or 0
	end

	if self.参战单位[n].类型 == "bb" then
		self:加载召唤兽加成属性(n)
		self:添加BB技能属性(n)
	end
end

function 战斗处理类:捕捉计算(编号)
	if self.战斗类型 ~= 100001 and self.战斗类型 ~= 100005 and self.战斗类型 ~= 100007 and self.战斗类型 ~= 100221 and self.战斗类型 ~= 100225 then
		return
	end

	local 目标 = self.参战单位[编号].指令.目标

	if self:取目标状态(编号, 目标, 1) == false then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/目标当前无法被捕获")

		return
	elseif self.参战单位[目标].类型 == "角色" or self.参战单位[目标].类型 == "召唤" then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/目标当前无法被捕获!")

		return
	elseif self.参战单位[目标].精灵 then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/你无法捕获这样的目标")

		return
	elseif self.参战单位[目标].队伍 ~= 0 then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/你无法捕获这样的目标")

		return
	elseif self.参战单位[编号].魔法 < qz(self.参战单位[目标].等级 * 0.5) then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/你没有足够的魔法")

		return
	elseif 玩家数据[self.参战单位[编号].玩家id].角色:取新增宝宝数量() == false then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/你当前无法携带更多的召唤兽")

		return
	end

	self.执行等待 = self.执行等待 + 15
	self.参战单位[编号].魔法 = self.参战单位[编号].魔法 - qz(self.参战单位[目标].等级 * 0.5 + 20)
	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 300,
		攻击方 = 编号,
		挨打方 = {
			{
				挨打方 = 目标
			}
		}
	}
	local 精准战斗流程 = #self.战斗流程 + 0
	local 初始几率 = 捕捉概率
	初始几率 = 初始几率 + qz(math.min(self.参战单位[目标].最大气血 / self.参战单位[目标].气血 * 10, 60)) + qz((self.参战单位[编号].猎术修炼 or 0) * 5)

	if self:取符石组合效果(编号, "心灵手巧") then
		初始几率 = 初始几率 + self:取符石组合效果(编号, "心灵手巧")
	end

	self.战斗流程[精准战斗流程].宝宝 = 玩家数据[self.参战单位[编号].玩家id].角色.数据.宠物.模型
	self.战斗流程[精准战斗流程].名称 = 玩家数据[self.参战单位[编号].玩家id].角色.数据.宠物.名称

	if 取随机数(1, 10000) <= 初始几率 * 100 then
		self.战斗流程[精准战斗流程].捕捉成功 = true

		if self.战斗类型 == 100225 then
			local 物法 = "法系"

			if ygsj() <= 50 then
				物法 = nil
			end

			玩家数据[self.参战单位[编号].玩家id].召唤兽:添加召唤兽(self.参战单位[目标].模型, false, false, true, self.参战单位[目标].等级, 物法, nil, nil, nil,
				nil, 野外神兽绑定)
		else
			玩家数据[self.参战单位[编号].玩家id].召唤兽:添加召唤兽(self.参战单位[目标].模型, self.参战单位[目标].分类, self.参战单位[目标].分类, false,
				self.参战单位[目标].等级, nil, nil, nil, self.参战单位[目标].技能)
		end

		self.参战单位[目标].气血 = 0
		self.参战单位[目标].捕捉 = true

		self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/你成功捕获了#R/" .. self.参战单位[目标].名称)
	end
end

function 战斗处理类:加入助攻列表(单位)
	self.助攻列表[单位.队伍] = self.助攻列表[单位.队伍] or {}
	self.助攻列表[单位.队伍][#self.助攻列表[单位.队伍] + 1] = 单位.战斗编号

	删除重复(self.助攻列表[单位.队伍])
end

function 战斗处理类:助攻判断(编号, 目标)
	if self.参战单位[编号] ~= nil and self.参战单位[编号].出手 == 1 and self.助攻列表[self.参战单位[编号].队伍] ~= nil and #self.助攻列表[self.参战单位[编号].队伍] >= 1 and self.参战单位[目标] ~= nil and self.参战单位[编号].队伍 ~= self.参战单位[目标].队伍 then
		local 助攻列表 = self.助攻列表[self.参战单位[编号].队伍]

		for i = 1, #助攻列表 do
			if 助攻列表[i] ~= 编号 and self.参战单位[助攻列表[i]].助攻 ~= nil and 取随机数(1, 10000) <= self.参战单位[助攻列表[i]].助攻 * 100 and self:取攻击状态(助攻列表[i], 1) and self:取行动状态(助攻列表[i]) and (self.参战单位[助攻列表[i]].助攻次数 or 0) < 每回合助攻次数限制 then
				self:普通攻击计算(助攻列表[i], 1, nil, nil, {
					助攻 = 1,
					助攻目标 = 目标
				})

				self.参战单位[助攻列表[i]].助攻次数 = (self.参战单位[助攻列表[i]].助攻次数 or 0) + 1
			end
		end
	end
end

function 战斗处理类:加入法术助攻列表(单位)
	self.法术助攻列表[单位.队伍] = self.法术助攻列表[单位.队伍] or {}
	self.法术助攻列表[单位.队伍][#self.法术助攻列表[单位.队伍] + 1] = 单位.战斗编号

	删除重复(self.法术助攻列表[单位.队伍])
end

function 战斗处理类:法术助攻判断(编号, 目标)
	if self.参战单位[编号] ~= nil and self.参战单位[编号].出手 == 1 and self.法术助攻列表[self.参战单位[编号].队伍] ~= nil and #self.法术助攻列表[self.参战单位[编号].队伍] >= 1 and self.参战单位[目标] ~= nil and self.参战单位[编号].队伍 ~= self.参战单位[目标].队伍 then
		local 法术助攻列表 = self.法术助攻列表[self.参战单位[编号].队伍]

		for i = 1, #法术助攻列表 do
			if 法术助攻列表[i] ~= 编号 and self.参战单位[法术助攻列表[i]].法术助攻 ~= nil and 取随机数(1, 10000) <= self.参战单位[法术助攻列表[i]].法术助攻 * 100 and self:取法术状态(法术助攻列表[i], nil, 1) and self:取行动状态(法术助攻列表[i]) and (self.参战单位[法术助攻列表[i]].法术助攻次数 or 0) < 每回合法术助攻次数限制 then
				self:法攻技能计算(法术助攻列表[i], 魔法反击小法列表[ygsj(#魔法反击小法列表)], self.参战单位[法术助攻列表[i]].等级, 1, nil, {
					助攻目标 = 目标
				})

				self.参战单位[法术助攻列表[i]].法术助攻次数 = (self.参战单位[法术助攻列表[i]].法术助攻次数 or 0) + 1
			end
		end
	end
end

function 战斗处理类:添加临时属性(编号, 属性, 数值)
	self.临时属性[编号][属性] = (self.临时属性[编号][属性] or 0) + 数值
end

function 战斗处理类:法术计算(编号, 不法连)
	local 名称 = self.参战单位[编号].指令.参数
	local 目标 = self.参战单位[编号].指令.目标
	local 等级 = self:取技能等级(编号, 名称)
	local 施法耐久 = 0

	if 等级 == 0 and 装备特技[名称] == nil then
		return
	end

	if self:物攻技能(名称) then
		self:物攻技能计算(编号, 名称, 等级)

		if self.参战单位[编号].法术状态.佛法无边 ~= nil and ygsj() <= self.参战单位[编号].法术状态.佛法无边.概率 and 佛法无边生效技能[名称] ~= nil then
			self:物攻技能计算(编号, 名称, 等级)
		end
	elseif self:封印技能(名称) then
		self:单体封印技能计算(编号, 名称, 等级)
	elseif self:群体封印技能(名称) then
		self:群体封印技能计算(编号, 名称, 等级)
	elseif self:增益技能(名称) then
		self:增益技能计算(编号, 名称, 等级)
	elseif self:减益技能(名称) then
		self:减益技能计算(编号, 名称, 等级)
	elseif self:法攻技能(名称) then
		self:法攻技能计算(编号, 名称, 等级, 1)
		local flcs = math.min(math.floor((self.参战单位[编号].单人闯关 or 0) / 35), 5) ---/30次数触发),5最高次数)
		if flcs >= 1 and (名称 == "龙卷雨击" or 名称 == "龙腾" or 名称 == "落叶萧萧" or 名称 == "飞砂走石" or 名称 == "雷霆万钧") then
			for n = 1, flcs do
				self:法攻技能计算(编号, 名称, 等级, 1)
				--self:添加战斗流程提示("#P(秘传法术)#R" .. self.参战单位[编号].名称 .. "#W使用#Y" .. 名称 .. "#W直接击杀了#G" .. self.参战单位[目标].名称)
			end
		end
		local flcs = math.min(math.floor((self.参战单位[编号].单1闯关 or 0) / 30), 5) ---/30次数触发),5最高次数)
		if flcs >= 1 and (名称 == "龙卷雨击" or 名称 == "龙腾" or 名称 == "破釜沉舟" or 名称 == "飞砂走石" or 名称 == "天雷斩") then
			for n = 1, flcs do
				self:法攻技能计算(编号, 名称, 等级, 1)
			end
		end
		if 不法连 == nil then
			if self.参战单位[编号].法术状态.佛法无边 ~= nil and ygsj() <= self.参战单位[编号].法术状态.佛法无边.概率 and 佛法无边生效技能[名称] ~= nil then
				self:法攻技能计算(编号, 名称, 等级, 1)
			elseif self.参战单位[编号].法术状态.佛法无边 ~= nil and 名称 == "唧唧歪歪" and self.参战单位[编号].无量 ~= nil and ygsj() <= self.参战单位[编号].无量 then
				self:法攻技能计算(编号, 名称, 等级, 1)
			end

			if 名称 == "摇头摆尾" and self:取奇经八脉是否有(编号, "连营") then
				local bl = 0.4
				self.不施法 = true

				while ygsj() <= 30 do
					self:法攻技能计算(编号, 名称, 等级, bl, "无消耗", {
						随机目标 = true
					})
					self:添加战斗流程提示("#P(连营)#R" .. self.参战单位[编号].名称 .. "#W触发了#G连营#W效果")

					bl = bl * 0.4
				end

				self.不施法 = false
			elseif self.参战单位[编号].重光 ~= nil and 名称 ~= "风卷残云" and 名称 ~= "凋零之歌" then
				local bl = 0.4

				if ygsj() <= self.参战单位[编号].重光 + (self.参战单位[编号].苍埃 or 0) then
					self.参战单位[编号].苍埃 = nil

					if 名称 == "落叶萧萧" then
						if self:取奇经八脉是否有(编号, "追击") and self.参战单位[编号].风灵 ~= nil and self.参战单位[编号].法术状态.风灵 ~= nil then
							self:刷新风灵(编号, -1)

							bl = bl + 0.3
						end

						if self:取奇经八脉是否有(编号, "啸风") and qz(self.天气) == 1 then
							bl = bl + 0.2
						end
					elseif 名称 == "蛊木迷瘴" and self:取奇经八脉是否有(编号, "伏毒") and self.参战单位[编号].风灵 ~= nil and self.参战单位[编号].法术状态.风灵 ~= nil then
						self:刷新风灵(编号, -1)

						self.参战单位[编号].伏毒 = 10
					end

					self:法攻技能计算(编号, 名称, 等级, bl, "无消耗")
					self:添加战斗流程提示("#P(门派特色)#R" .. self.参战单位[编号].名称 .. "#W触发了#G重光#W效果")

					self.参战单位[编号].伏毒 = nil
				end
			end

			if 名称 ~= "月光" and 物攻群法技能列表[名称] == nil and 技能冷却列表[名称] == nil then
				local 法连连续判定 = true
				local 法连倍率 = 低级法连倍率 + 0

				if self.参战单位[编号].高级法连 ~= nil then
					法连倍率 = 高级法连倍率 + 0
				end

				if self.参战单位[编号].超级法连 ~= nil then
					法连倍率 = 超级法连倍率 + 0
				end

				while 法连连续判定 do
					法连连续判定 = false

					if self.参战单位[编号].特效法连 ~= nil and ygsj() <= self.参战单位[编号].特效法连 then
						self:法攻技能计算(编号, 名称, 等级, 1)

						if 名称 == "摇头摆尾" and self:取奇经八脉是否有(编号, "连营") then
							local bl = 0.4
							self.不施法 = true

							while ygsj() <= 30 do
								self:法攻技能计算(编号, 名称, 等级, bl, "无消耗", {
									随机目标 = true
								})
								self:添加战斗流程提示("#P(连营)#R" .. self.参战单位[编号].名称 .. "#W触发了#G连营#W效果")

								bl = bl * 0.4
							end

							self.不施法 = false
						end

						self:添加战斗流程提示("#P(特效)#R" .. self.参战单位[编号].名称 .. "#W触发了#G法连#W效果")
					elseif 取随机数(1, 10000) <= ((self.参战单位[编号].法连 or 0) + (self.临时属性[编号].法连 or 0) + (self.参战单位[编号].大快朵颐法连 or 0)) * 100 then
						if 名称 == "叱咤风云" then
							法连倍率 = 法连倍率 + 0.5
							法连连续判定 = true
							self.不施法 = true
						end

						if not self.参战单位[编号].双星爆 then
							self.参战单位[编号].双星爆 = 0
						end

						法连倍率 = 法连倍率 + self.参战单位[编号].双星爆

						if (self.参战单位[编号].柳暗花明 or 0) > 0 then
							法连倍率 = 法连倍率 + self.参战单位[编号].柳暗花明 * 0.5
							self.参战单位[编号].柳暗花明 = 0
						end

						self:法攻技能计算(编号, 名称, 等级, 法连倍率, "无消耗")

						if 名称 == "摇头摆尾" and self:取奇经八脉是否有(编号, "连营") then
							local bl = 法连倍率 * 0.4
							self.不施法 = true

							while ygsj() <= 30 do
								self:法攻技能计算(编号, 名称, 等级, bl, "无消耗", {
									随机目标 = true
								})
								self:添加战斗流程提示("#P(连营)#R" .. self.参战单位[编号].名称 .. "#W触发了#G连营#W效果")

								bl = bl * 0.4
							end

							self.不施法 = false
						end

						self:添加战斗流程提示("#P(法术连击)#R" .. self.参战单位[编号].名称 .. "#W触发了#G法术连击#Y")

						self.不施法 = false
					elseif self.参战单位[编号].柳暗花明 ~= nil and self.参战单位[编号].柳暗花明防多次 == nil then
						self.参战单位[编号].柳暗花明 = math.min(self.参战单位[编号].柳暗花明 + 1, 2)
						self.参战单位[编号].柳暗花明防多次 = 1
					end

					if (self.参战单位[编号].法连 or 0) + (self.临时属性[编号].法连 or 0) <= 0 then
						break
					end
				end
			end

			if 五行固伤法术[名称] ~= nim and self.参战单位[编号].缘起 ~= nil then
				local sl = self:取敌方拥有指定状态人数(编号, "紧箍咒")

				if ygsj() <= sl * 8 then
					self:法攻技能计算(编号, 名称, 等级)
					self:添加战斗流程提示("#P(缘起)#R" .. self.参战单位[编号].名称 .. "#W额外释放了1次#G" .. 名称)
				end
			end
		end
	elseif self:恢复技能(名称) then
		self:恢复技能计算(编号, 名称, 等级)
	elseif 名称 == "妙手空空" then
		self:妙手空空计算(编号, 名称, 等级)
	end

	self.临时属性[编号] = {}

	if self.战斗类型 == 134481.6 and self.回合数 % 2 == 0 and self.参战单位[编号].队伍 == 0 and (self.参战单位[编号].名称 == "舍身取义·惧法" or self.参战单位[编号].名称 == "金刚不坏·惧物") and self.参战单位[编号].气血 > 0 then
		self:减少气血(编号, self.参战单位[编号].最大气血 + 99999, nil, nil, 1)

		self.参战单位[编号].死亡状态 = 1

		self:流程处理状态(编号, {
			{
				直接击退 = true,
				挨打方 = 编号
			}
		})
	end
end

function 战斗处理类:添加提示(id, 攻击方, 内容)
	if self.参战单位[攻击方].队伍 == 0 then
		return
	end

	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 900,
		攻击方 = 攻击方,
		id = id,
		内容 = 内容
	}
end

function 战斗处理类:添加提示1(id, 攻击方, 内容)
	if self.参战单位[攻击方].队伍 == 0 then
		return
	end

	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 901,
		攻击方 = 攻击方,
		id = id,
		内容 = 内容
	}
end

function 战斗处理类:添加提示2(id, 编号, 内容)
	if self.参战单位[编号].队伍 == 0 then
		return
	end

	发送数据(玩家数据[id].连接id, 38, 内容)
end

function 战斗处理类:飞镖计算(编号, id组)
	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 611,
		攻击方 = 编号,
		挨打方 = {}
	}
	local 精准战斗流程 = #self.战斗流程 + 0
	self.执行等待 = self.执行等待 + 10

	for n = 1, #id组 do
		if self:取目标状态(编号, id组[n].id, 1) then
			self.战斗流程[精准战斗流程].挨打方[#self.战斗流程[精准战斗流程].挨打方 + 1] = {
				挨打方 = id组[n].id,
				伤害 = id组[n].伤害
			}
			self.战斗流程[精准战斗流程].挨打方[#self.战斗流程[精准战斗流程].挨打方].死亡 = self:减少气血(id组[n].id, id组[n].伤害, 编号, 名称, nil, nil, 1)
		end
	end
end

function 战斗处理类:妙手空空计算(编号, 名称, 等级)
	local 目标 = self.参战单位[编号].指令.目标

	if 目标 == nil or self.参战单位[目标].气血 <= 0 then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/对方已经死了，你忍心从尸体上偷东西？")

		return
	elseif self.战斗类型 ~= 100001 and self.战斗类型 ~= 100007 then
		return
	elseif self.参战单位[目标].偷盗 then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/对方身上已经没有宝物了")

		return
	elseif self:技能消耗(self.参战单位[编号], self.参战单位[目标].等级, 名称, 编号) == false then
		return
	end

	self:施法统一计算(编号, "妙手空空")

	self.执行等待 = self.执行等待 + 1
	local id = self.参战单位[编号].玩家id

	if self.参战单位[目标].精灵 == nil then
		if ygsj() <= 等级 * 10 then
			local 随机金钱 = 取随机数(10, 100)

			玩家数据[id].角色:添加银子(随机金钱, "[战斗]妙手空空从" .. self.参战单位[目标].名称 .. "、" .. self.参战单位[目标].模型 .. "身上盗取")
			self:添加提示1(self.参战单位[编号].玩家id, 编号, "你得到了" .. 随机金钱 .. "金钱")

			self.参战单位[目标].偷盗 = true

			return
		else
			self:添加提示1(self.参战单位[编号].玩家id, 编号, "对方发觉了你这个行为，机灵地躲过去了！")
		end
	elseif self.参战单位[目标].精灵 then
		if ygsj() <= 等级 * 10 then
			local 奖励参数 = ygsj()

			if 奖励参数 <= 5 then
				if 变身卡数据[self.参战单位[目标].模型] ~= nil then
					玩家数据[id].道具:给予道具(id, "怪物卡片", self.参战单位[目标].模型)
					self:添加提示1(self.参战单位[编号].玩家id, 编号, "你得到了#R/怪物卡片")
				end
			elseif 奖励参数 <= 60 then
				self:添加提示1(self.参战单位[编号].玩家id, 编号, "对方发觉了你这个行为，机灵地躲过去了！")
			elseif 奖励参数 <= 80 then
				self:添加提示1(self.参战单位[编号].玩家id, 编号, "对方发觉了你这个行为，机灵地躲过去了！")
			else
				self:添加提示1(self.参战单位[编号].玩家id, 编号, "对方发觉了你这个行为，机灵地躲过去了！")
			end

			self.参战单位[目标].偷盗 = true

			return
		else
			self:添加提示1(self.参战单位[编号].玩家id, 编号, "对方发觉了你这个行为，机灵地躲过去了！")
		end
	end
end

function 战斗处理类:恢复技能计算(编号, 名称, 等级, 指定目标)
	local 目标 = 指定目标 or self.参战单位[编号].指令.目标
	local 目标数 = 0
	local 法爆 = 0
	local 法爆几率 = self.参战单位[编号].法术暴击等级 * 0.1

	if self:取敌方是否全部死亡(编号) == true then
		return
	end

	if 名称 == "自在心法" and self.参战单位[编号].道衍 ~= nil then
		self.参战单位[编号].道衍 = self:取我方拥有指定状态人数(编号, "普渡众生")
	end

	if 名称 == "紫火如意" then
		self.参战单位[编号].出手 = 1
		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 60,
			攻击方 = 编号,
			挨打方 = {},
			提示 = {
				类型 = "法术",
				允许 = true,
				名称 = self.参战单位[编号].名称 .. "使用了" .. 名称
			}
		}
		local 精准战斗流程 = #self.战斗流程 + 0
		self.执行等待 = self.执行等待 + 10
		local 目标数 = self:取全体敌友方目标(编号)
		local hp = 0

		for i = 1, #目标数 do
			self.战斗流程[精准战斗流程].挨打方[i] = {
				挨打方 = 目标数[i],
				特效 = {
					名称
				}
			}
			hp = hp + self.参战单位[目标数[i]].气血
		end

		hp = qz1(hp * (等级 * 2 + 68) / 100 / #目标数)

		for i = 1, #目标数 do
			self.参战单位[目标数[i]].气血 = math.min(self.参战单位[目标数[i]].气血上限 or self.参战单位[目标数[i]].最大气血, hp)
			self.战斗流程[精准战斗流程].挨打方[i].恢复气血 = hp
			self.战斗流程[精准战斗流程].挨打方[i].解除状态 = {}
		end

		return
	elseif 名称 == "草木同根" then
		if self.参战单位[编号].名称 ~= "玄冥" or self.参战单位[编号].队伍 ~= 0 then
			return
		end

		self.参战单位[编号].出手 = 1
		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 60,
			攻击方 = 编号,
			挨打方 = {},
			提示 = {
				类型 = "法术",
				允许 = true,
				名称 = self.参战单位[编号].名称 .. "使用了" .. 名称
			}
		}
		local 精准战斗流程 = #self.战斗流程 + 0
		self.执行等待 = self.执行等待 + 10
		local 复活单位 = {}

		if self.参战单位[编号].气血 <= self.参战单位[编号].最大气血 * 0.5 then
			for n = 1, #self.参战单位 do
				if self.参战单位[n].队伍 == self.参战单位[编号].队伍 and self.参战单位[n].死亡状态 == 2 and self.参战单位[n].鬼混 == nil then
					self.参战单位[n].死亡状态 = nil
					复活单位[n] = 1
					self.参战单位[n].气血 = 1
				end
			end
		end

		local 目标数 = self:取全体敌友方目标(编号)
		local hp = 0

		for i = 1, #目标数 do
			self.战斗流程[精准战斗流程].挨打方[i] = {
				挨打方 = 目标数[i],
				特效 = {
					名称
				}
			}
			hp = hp + self.参战单位[目标数[i]].气血

			if 复活单位[目标数[i]] ~= nil then
				self.战斗流程[精准战斗流程].挨打方[i].复活 = true
				self.执行中复活单位[#self.执行中复活单位 + 1] = 目标数[i]
				self.回合中复活 = true
			end
		end

		hp = qz1(hp / #目标数)
		local 溢出 = 0

		for i = 1, #目标数 do
			if self.参战单位[目标数[i]].最大气血 < hp then
				溢出 = 溢出 + hp - self.参战单位[目标数[i]].最大气血
				self.参战单位[目标数[i]].气血 = self.参战单位[目标数[i]].最大气血
			else
				self.参战单位[目标数[i]].气血 = hp
			end

			self.战斗流程[精准战斗流程].挨打方[i].恢复气血 = hp
			self.战斗流程[精准战斗流程].挨打方[i].解除状态 = {}
		end

		if 溢出 > 0 then
			self:增加气血(1, 溢出)
		end

		return
	end

	if 名称 == "七宝玲珑灯" then
		目标 = self:取友方法宝异常状态单位(编号)
	end

	if 名称 == "归元咒" or 名称 == "乾天罡气" or 名称 == "三花聚顶" or 名称 == "移星换斗" or 名称 == "气归术" or 名称 == "命归术" or 名称 == "凝神诀" or 名称 == "凝气诀" then
		目标 = 编号
	elseif 名称 == "活血" and 目标 == 编号 then
		local aa = 1

		while 目标 == 编号 and aa < 10 do
			目标 = self:取单个友方目标(编号)
			aa = aa + 1
		end

		if 目标 == 0 or 目标 == 编号 then
			return
		end
	elseif 名称 == "驯兽重生" then
		目标 = self.参战单位[编号].召唤兽

		if 目标 == nil then
			return
		end
	end

	if 名称 ~= "我佛慈悲" and 名称 ~= "慈航普渡" and 名称 ~= "还魂咒" and 名称 ~= "杨柳甘露" and 名称 ~= "起死回生" and 名称 ~= "回魂咒" and 名称 ~= "还阳术" and 名称 ~= "莲花心音" and 名称 ~= "由己渡人" and 名称 ~= "驯兽重生" then
		目标数 = self:取目标数量(self.参战单位[编号], 名称, 等级, 编号)
		目标 = self:取多个友方目标(编号, 目标, 目标数, 名称)

		if 名称 == "地涌金莲" and self.队伍救人 ~= nil and self.队伍救人[self.参战单位[编号].队伍] ~= nil then
			local aa = 列表模式转换(目标)
			local lb = self.队伍救人[self.参战单位[编号].队伍]

			删除重复(lb)

			for i = 1, #lb do
				if self.参战单位[lb[i]] ~= nil and aa[lb[i]] == nil and (self.参战单位[lb[i]].法术状态.明光宝烛 ~= nil and self.参战单位[lb[i]].法术状态.明光宝烛.救人 ~= nil or self.参战单位[lb[i]].法术状态.金身舍利 ~= nil and self.参战单位[lb[i]].法术状态.金身舍利.救人 ~= nil) then
					目标[#目标 + 1] = lb[i]
				end
			end
		end
	elseif 名称 == "慈航普渡" then
		目标 = self:取我方可复活(编号)
		local 移除 = {}

		for i = 1, #目标 do
			if self.参战单位[目标[i]].气血 > 0 or self.参战单位[目标[i]].法术状态.死亡召唤 ~= nil or self.参战单位[目标[i]].法术状态.锢魂术 ~= nil then
				移除[#移除 + 1] = i
			end
		end

		if #移除 > 0 then
			目标 = 无错误删除列表多个元素(目标, 移除)
		end
	else
		if self.参战单位[目标].法术状态.困兽 ~= nil then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/友方存在#P【困兽】#Y状态,技能使用失败")

			return
		elseif self.参战单位[目标].法术状态.秘术 ~= nil then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/友方存在#P【秘术】#Y状态,技能使用失败")

			return
		elseif self.参战单位[目标].法术状态.死亡召唤 ~= nil or self.参战单位[目标].法术状态.锢魂术 ~= nil then
			if 名称 ~= "杨柳甘露" and 名称 ~= "由己渡人" or self.参战单位[目标].法术状态.死亡召唤 ~= nil and self.参战单位[目标].法术状态.死亡召唤.回合 > 2 or self.参战单位[目标].法术状态.锢魂术 ~= nil and self.参战单位[目标].法术状态.锢魂术.回合 > 2 then
				self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/友方存在不可复活BUFF,技能使用失败")

				return
			elseif 名称 == "由己渡人" and (not self:取奇经八脉是否有(编号, "灵通", "妙谛金莲") or not self:取是否有指定状态(编号, 编号, "燃血术·妙谛金莲")) then
				self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/友方存在不可复活BUFF,技能使用失败")

				return
			end
		elseif self.参战单位[目标].法术状态.泼天乱棒 ~= nil or self.参战单位[目标].法术状态.意马心猿 ~= nil then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/友方存在不可复活状态,技能使用失败")
		end

		if 复活技能[名称] ~= nil and self.参战单位[目标].气血 > 0 then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/友方没有死亡，技能使用失败")

			return
		end

		if 名称 == "莲花心音" then
			if self.参战单位[目标].类型 == "角色" or self.参战单位[目标].鬼魂 == nil then
				self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/该技能只能对鬼魂生物生效")

				return
			end
		elseif self.参战单位[目标].鬼魂 ~= nil then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/该技能对鬼魂生物无效")

			return
		elseif self.参战单位[目标].类型 == "bb" and self.参战单位[目标].驯兽 == nil then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/该技能只能对角色生效")

			return
		end

		if 名称 == "杨柳甘露" and (self.参战单位[目标].法术状态.死亡召唤 ~= nil or self.参战单位[目标].法术状态.锢魂术 ~= nil) and self:取奇经八脉是否有(编号, "甘露") then
			self.参战单位[编号].甘露 = 1
		elseif 名称 == "由己渡人" and (self.参战单位[目标].法术状态.死亡召唤 ~= nil or self.参战单位[目标].法术状态.锢魂术 ~= nil) then
			if self:取是否有指定状态(编号, 编号, "燃血术·妙谛金莲") then
				self.参战单位[编号].法术状态["燃血术·妙谛金莲"].层数 = self.参战单位[编号].法术状态["燃血术·妙谛金莲"].层数 - 1

				if self.参战单位[编号].法术状态["燃血术·妙谛金莲"].层数 < 1 then
					self:取消状态("燃血术·妙谛金莲", self.参战单位[编号])
				end
			end

			self.参战单位[编号].灵通 = 2.5
		end

		目标 = {
			目标
		}
	end

	local 移除 = {}

	for i = 1, #目标 do
		if self.参战单位[目标[i]] == nil then
			移除[#移除 + 1] = i
		end
	end

	if #移除 > 0 then
		目标 = 无错误删除列表多个元素(目标, 移除)
	end

	if #目标 == 0 then
		return
	end

	目标数 = #目标

	if 消耗 == nil and self:技能消耗(self.参战单位[编号], 目标数, 名称, 编号) == false then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "未到达技能消耗要求,技能使用失败")

		if 技能冷却列表[名称] ~= nil then
			self.参战单位[编号][名称] = 0
		end

		return
	end

	if 名称 == "焕生咒" then
		self.参战单位[编号].焕生咒加成 = 0
		local aa = {}

		for i = 1, #self.参战单位 do
			if self.参战单位[i].队伍 == self.参战单位[编号].队伍 and self.参战单位[i].气血 == self.参战单位[i].最大气血 then
				aa[#aa + 1] = i

				self:减少气血(i, 30)
			end
		end

		self.参战单位[编号].焕生咒加成 = #aa * 0.15
	end

	self:施法统一计算(编号, 名称)

	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 60,
		攻击方 = 编号,
		挨打方 = {},
		提示 = {
			类型 = "法术",
			允许 = true,
			名称 = self.参战单位[编号].名称 .. "使用了" .. 名称
		}
	}
	self.恢复回合 = #self.战斗流程 + 0
	self.执行等待 = self.执行等待 + 10
	local 气血 = 0

	for n = 1, 目标数 do
		local 状态名称 = {}
		self.战斗流程[self.恢复回合].挨打方[n] = {
			挨打方 = 目标[n],
			特效 = {
				名称
			}
		}

		if 名称 == "驱尸" or 名称 == "解毒" or 名称 == "清心" or 名称 == "百毒不侵" then
			状态名称 = self:解除状态结果(self.参战单位[目标[n]], {
				"尸腐毒",
				"毒",
				"猛毒",
				"雾杀"
			}, 名称)

			if 名称 == "百毒不侵" then
				self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号)

				self.战斗流程[self.恢复回合].挨打方[n].添加状态 = 名称
			end
		elseif 名称 == "无穷妙道" then
			状态名称 = self:解除状态结果(self.参战单位[目标[n]], self:取门派封印法术("无底洞"), 名称)

			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号)

			self.战斗流程[self.恢复回合].挨打方[n].添加状态 = 名称
		elseif 名称 == "寡欲令" then
			状态名称 = self:解除状态结果(self.参战单位[目标[n]], self:取门派封印法术("盘丝洞"), 名称)

			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号)

			self.战斗流程[self.恢复回合].挨打方[n].添加状态 = 名称
		elseif 名称 == "复苏" then
			状态名称 = self:解除状态结果(self.参战单位[目标[n]], self:取门派封印法术("天宫"), 名称)

			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号)

			self.战斗流程[self.恢复回合].挨打方[n].添加状态 = 名称
		elseif 名称 == "解封" or 名称 == "宁心" then
			状态名称 = self:解除状态结果(self.参战单位[目标[n]], self:取门派封印法术("女儿村"), 名称)

			if 名称 == "宁心" then
				self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号)

				self.战斗流程[self.恢复回合].挨打方[n].添加状态 = 名称
			end
		elseif 名称 == "水清诀" or 名称 == "玉清诀" then
			if 名称 == "玉清诀" and self:取奇经八脉是否有(编号, "暗潮") then
				状态名称 = self:解除状态结果(self.参战单位[目标[n]], self:取异常封印法术状态(), 名称)

				if n == 1 then
					local hp = qz(self.参战单位[编号].气血 * 0.1)

					self:减少气血(编号, hp)
				end
			else
				if 名称 == "水清诀" and self.参战单位[编号].噬魂 ~= nil then
					self:添加状态("噬魂", self.参战单位[目标[n]], self.参战单位[编号], 1, 编号)
				end

				状态名称 = self:解除状态结果(self.参战单位[目标[n]], self:取异常状态法术(), 名称)
			end

			if self:取奇经八脉是否有(编号, "花护") then
				self:添加状态("花护", self.参战单位[目标[n]])
			end
		elseif 名称 == "七宝玲珑灯" and 取随机数(1, 10000) <= (等级 * 2 + 20) * 100 then
			状态名称 = self:解除状态结果(self.参战单位[目标[n]], self:取法宝异常法术(), 名称)
		elseif 名称 == "清心咒" then
			状态名称 = self:解除状态结果(self.参战单位[目标[n]], self:取法宝异常法术(), 名称)
