			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			self:增加气血(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复气血 = 气血

			if self:取奇经八脉是否有(编号, "花护") then
				self:添加状态("花护", self.参战单位[目标[n]])
			end

			if self.参战单位[编号].噬魂 ~= nil then
				self:添加状态("噬魂", self.参战单位[目标[n]], self.参战单位[编号], 1, 编号)
			end
		elseif 名称 == "净世煌火" then
			状态名称 = self:解除状态结果(self.参战单位[目标[n]], self:取异常状态法术(), 名称)
			气血 = qz(self.参战单位[目标[n]].最大气血 * 0.25)
			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			self:增加气血(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复气血 = 气血
		elseif 名称 == "晶清诀" then
			状态名称 = self:解除状态结果(self.参战单位[目标[n]], self:取异常状态法术(), 名称)
			气血 = qz(self.参战单位[目标[n]].最大气血 * 0.15)
			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			self:增加气血(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复气血 = 气血

			if self:取奇经八脉是否有(编号, "花护") then
				self:添加状态("花护", self.参战单位[目标[n]])
			end
		elseif 名称 == "其徐如林" then
			状态名称 = self:解除状态结果(self.参战单位[目标[n]], self:取异常状态法术(), 名称)
			气血 = qz(self.参战单位[目标[n]].最大气血 * 0.05)
			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			self:增加气血(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复气血 = 气血
			self.战斗流程[self.恢复回合].流程 = 160
		elseif 名称 == "仙人指路" then
			状态名称 = self:解除状态结果(self.参战单位[目标[n]], self:取异常状态法术(), 名称)
			气血 = qz(self.参战单位[目标[n]].最大气血 * 0.1)
			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			self:增加气血(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复气血 = 气血
		elseif 名称 == "气疗术" then
