			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			self:增加气血(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复气血 = 气血
		elseif 名称 == "命疗术" then
			气血 = qz(self.参战单位[目标[n]].最大气血 * 0.09 + 600)
			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			self:增加气血(目标[n], 气血)

