			气血 = self.参战单位[目标[n]].最大气血

			self:恢复伤势(目标[n], 气血)
			self:增加气血(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复伤势 = 气血
			self.战斗流程[self.恢复回合].挨打方[n].伤势类型 = 2
			self.战斗流程[self.恢复回合].挨打方[n].恢复气血 = 气血
			self.战斗流程[self.恢复回合].挨打方[n].复活 = true
			self.战斗流程[self.恢复回合].扣除气血 = self.参战单位[编号].气血 - 1
			self.参战单位[编号].魔法 = 1

			self:减少气血(编号, self.战斗流程[self.恢复回合].扣除气血)

			self.执行中复活单位[#self.执行中复活单位 + 1] = 目标
			self.回合中复活 = true
		elseif 名称 == "舍身取义" or 名称 == "牺牲·舍身取义" then
			气血 = self.参战单位[目标[n]].气血上限 or self.参战单位[目标[n]].最大气血

			if 名称 == "舍身取义" then
				local 次数 = 1

				if self.参战单位[编号].法术状态.舍身取义 ~= nil then
					次数 = self.参战单位[编号].法术状态.舍身取义.次数 + 1

					self:取消状态("舍身取义", self.参战单位[编号])
				end

				self:添加状态("舍身取义", self.参战单位[编号], self.参战单位[编号], nil, 编号, 次数)
			end

			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			self:增加气血(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复气血 = 气血
		elseif 名称 == "杨柳甘露" then
			气血 = 等级 * 3 + math.max(self.参战单位[编号].灵力, self.参战单位[编号].法伤) * 0.2

			if n == 1 and self.参战单位[编号].气血 <= self.参战单位[编号].最大气血 * 0.3 and self:取奇经八脉是否有(编号, "劳心") then
				气血 = 气血 * 2
			end

			if self.参战单位[编号].莲动 ~= nil and self.参战单位[编号].莲动 > 0 then
				气血 = 气血 * 4
				self.参战单位[编号].莲动 = self.参战单位[编号].莲动 - 1
			end

			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			self:恢复伤势(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复伤势 = 气血
			self.战斗流程[self.恢复回合].挨打方[n].伤势类型 = 2

			self:增加气血(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复气血 = 气血
			self.战斗流程[self.恢复回合].挨打方[n].复活 = true

			if 编号 ~= nil and self:取奇经八脉是否有(编号, "甘露") and (self.参战单位[编号].甘露 ~= nil or ygsj() <= 50) then
				self:添加状态("普渡众生", self.参战单位[目标[n]], self.参战单位[编号], self:取技能等级(编号, "普渡众生"), 编号)

				self.参战单位[目标[n]].法术状态.普渡众生.回合 = 4
				self.战斗流程[self.恢复回合].挨打方[n].添加状态 = "普渡众生"
			end

			self.参战单位[编号].甘露 = nil
			self.执行中复活单位[#self.执行中复活单位 + 1] = 目标
			self.回合中复活 = true
		elseif 名称 == "还魂咒" or 名称 == "驯兽重生" then
			气血 = qz(等级 * 5) + math.max(self.参战单位[编号].灵力, self.参战单位[编号].法伤) * 0.2
			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			self:恢复伤势(目标[n], qz(气血 * 1.5))

			self.战斗流程[self.恢复回合].挨打方[n].恢复伤势 = qz(气血 * 1.5)
			self.战斗流程[self.恢复回合].挨打方[n].伤势类型 = 2

			self:增加气血(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复气血 = 气血
			self.战斗流程[self.恢复回合].挨打方[n].复活 = true
			self.执行中复活单位[#self.执行中复活单位 + 1] = 目标
			self.回合中复活 = true

			if 名称 == "驯兽重生" then
				self:添加状态("驯兽重生", self.参战单位[目标[n]])
				self:客户端添加状态(目标[n], "驯兽重生")

				if self:取奇经八脉是否有(编号, "回光") and ygsj() <= 50 and self:取法术状态(目标[n]) then
					self:添加战斗流程提示("#P(回光)#R" .. self.参战单位[目标[n]].名称 .. "#W将使用一次#Y幼狮之搏")
					self:物攻技能计算(目标[n], "幼狮之搏", self:取技能等级(目标[n], "幼狮之搏"))
				end
			end
		elseif 名称 == "起死回生" then
			气血 = qz(self.参战单位[目标[n]].最大气血 * 0.5)

			if 气血 > self.参战单位[目标[n]].等级 * 20 then
				气血 = self.参战单位[目标[n]].等级 * 20 + 100
			end

			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			self:恢复伤势(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复伤势 = 气血
			self.战斗流程[self.恢复回合].挨打方[n].伤势类型 = 2

			self:增加气血(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复气血 = 气血
			self.战斗流程[self.恢复回合].挨打方[n].复活 = true
			self.执行中复活单位[#self.执行中复活单位 + 1] = 目标
			self.回合中复活 = true
		elseif 名称 == "还阳术" then
			气血 = qz(self.参战单位[目标[n]].最大气血 * 0.5)

			if 气血 > self.参战单位[目标[n]].等级 * 20 then
				气血 = self.参战单位[目标[n]].等级 * 20 + 100
			end

			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			self:恢复伤势(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复伤势 = 气血
			self.战斗流程[self.恢复回合].挨打方[n].伤势类型 = 2

			self:增加气血(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复气血 = 气血

			if self.参战单位[目标[n]].还阳术1 == nil then
				self.参战单位[目标[n]].防御 = qz(self.参战单位[目标[n]].防御 * 0.9)
				self.参战单位[目标[n]].伤害 = qz(self.参战单位[目标[n]].伤害 * 1.1)
				self.参战单位[目标[n]].还阳术1 = true
			end

			self.战斗流程[self.恢复回合].挨打方[n].复活 = true
			self.执行中复活单位[#self.执行中复活单位 + 1] = 目标
			self.回合中复活 = true
		elseif 名称 == "回魂咒" then
			气血 = qz(self.参战单位[目标[n]].最大气血 * 0.1)
			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			self:恢复伤势(目标[n], self.参战单位[目标[n]].最大气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复伤势 = self.参战单位[目标[n]].最大气血
			self.战斗流程[self.恢复回合].挨打方[n].伤势类型 = 2

			self:增加气血(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复气血 = 气血
			self.战斗流程[self.恢复回合].挨打方[n].复活 = true
			self.执行中复活单位[#self.执行中复活单位 + 1] = 目标
			self.回合中复活 = true
		elseif 名称 == "自在心法" or 名称 == "自在心法1" then
			if self.参战单位[目标[n]].法术状态.普渡众生 ~= nil then
				local 编号1 = self.参战单位[目标[n]].法术状态.普渡众生.攻击编号
				local 恢复量 = self.参战单位[目标[n]].法术状态.普渡众生.等级 * 2 + self.参战单位[编号1].灵力 * 0.1
				local 剩余回合 = self.参战单位[目标[n]].法术状态.普渡众生.回合

				if 剩余回合 > 4 then
					剩余回合 = 4
				end

				if 名称 == "自在心法" and self.参战单位[编号].道衍 ~= nil and self.参战单位[编号].道衍 > 0 then
					local aa = 0.06

					if qz(self.天气) == 2 then
						aa = 0.07
					end

					气血 = self:取恢复气血(编号, 目标[n], 恢复量 * 剩余回合 * (1 + self.参战单位[编号].道衍 * aa), 名称, n)
				else
					气血 = self:取恢复气血(编号, 目标[n], 恢复量 * 剩余回合, 名称, n)
				end

				if 名称 == "自在心法1" then
					气血 = qz(气血 * 0.8)
				end

				self:恢复伤势(目标[n], 气血)
				self:增加气血(目标[n], 气血)

				self.战斗流程[self.恢复回合].挨打方[n].恢复气血 = 气血
				self.战斗流程[self.恢复回合].挨打方[n].恢复伤势 = 气血
				self.战斗流程[self.恢复回合].挨打方[n].伤势类型 = 2

				self:取消状态("普渡众生", self.参战单位[目标[n]])

				if 名称 == "自在心法" and n == 1 and self.参战单位[编号].道衍 ~= nil and self.参战单位[编号].道衍 > 0 then
					self:添加状态("普渡众生", self.参战单位[目标[n]], self.参战单位[编号], self:取技能等级(编号, "普渡众生"), 编号)

					if qz(self.天气) == 2 then
						self.参战单位[目标[n]].法术状态.普渡众生.回合 = math.min(self.参战单位[编号].道衍 + 1, 8)
					else
						self.参战单位[目标[n]].法术状态.普渡众生.回合 = math.min(self.参战单位[编号].道衍, 8)
					end
				else
					状态名称 = {
						[1.0] = "普渡众生"
					}
				end
			end
		elseif 名称 == "莲花心音" then
			气血 = qz(self.参战单位[目标[n]].最大气血 * 0.6)
			local 魔法 = self:增加魔法(目标[n], qz1(self.参战单位[目标[n]].魔法 * 0.48) - self.参战单位[目标[n]].魔法)
			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			self:恢复伤势(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复伤势 = 气血
			self.战斗流程[self.恢复回合].挨打方[n].伤势类型 = 2

			self:增加气血(目标[n], 气血)

			self.战斗流程[self.恢复回合].挨打方[n].恢复气血 = 气血
			self.战斗流程[self.恢复回合].挨打方[n].复活 = true
			self.执行中复活单位[#self.执行中复活单位 + 1] = 目标
			self.回合中复活 = true
		end

		self.战斗流程[self.恢复回合].挨打方[n].解除状态 = 状态名称
	end

	if 聚气生效法术[名称] ~= nil then
		self.参战单位[编号].聚气加成 = nil
	end

	if 名称 == "推拿" or 名称 == "推气过宫" or 名称 == "救死扶伤" then
		self.参战单位[编号].法术状态.仁心 = nil
	end

	if 名称 == "救死扶伤" then
		if self:取奇经八脉是否有(编号, "心韧") and self.参战单位[编号].心韧 == nil then
			self.参战单位[编号].心韧 = 技能冷却列表.心韧 + 0
		end
	elseif 名称 == "由己渡人" then
		self.参战单位[编号].灵通 = nil
	elseif 名称 == "地涌金莲" then
		self.参战单位[编号].陷阱 = nil

		if self:取是否有指定状态(编号, 编号, "燃血术·妙谛金莲") then
			self.参战单位[编号].法术状态["燃血术·妙谛金莲"].层数 = self.参战单位[编号].法术状态["燃血术·妙谛金莲"].层数 - 1

			if self.参战单位[编号].法术状态["燃血术·妙谛金莲"].层数 < 1 then
				self:取消状态("燃血术·妙谛金莲", self.参战单位[编号])
			end
		end
	elseif 名称 == "推气过宫" then
		self.参战单位[编号].佛佑 = nil
	elseif 名称 == "活血" then
		if self:取奇经八脉是否有(编号, "化瘀") and self.参战单位[编号].化瘀 == nil then
			self.参战单位[编号].化瘀 = 技能冷却列表.化瘀 + 0
		end
	elseif 名称 == "推拿" and self:取奇经八脉是否有(编号, "化瘀") and self.参战单位[编号].化瘀 == nil then
		self.参战单位[编号].化瘀 = 技能冷却列表.化瘀 + 0
	end
end

