function 战斗处理类:解除状态结果(单位, 名称, 技能名称)
	local 解除 = {}

	for n = 1, #名称 do
		if 单位.法术状态[名称[n]] ~= nil and 名称[n] ~= "象形" then
			self:取消状态(名称[n], 单位, nil, 技能名称)

			解除[#解除 + 1] = 名称[n]
		end
	end

	return 解除
end

function 战斗处理类:取符石组合效果(编号, 名称)
	if type(编号) == "table" then
		if 编号.符石技能效果 == nil and 编号.符石技能效果[名称] == nil then
			return false
		end

		return 编号.符石技能效果[名称]
	else
		if self.参战单位[编号].符石技能效果 == nil and self.参战单位[编号].符石技能效果[名称] == nil then
			return false
		end

		return self.参战单位[编号].符石技能效果[名称]
	end
end

