function 战斗处理类:减少技能冷却(编号, 技能名称, 减少回合)
	if 编号 == nil or self.参战单位[编号] == nil or self.参战单位[编号][技能名称] == nil then
		return
	else
		self.参战单位[编号][技能名称] = self.参战单位[编号][技能名称] - 减少回合

		if self.参战单位[编号][技能名称] <= 0 then
			self.参战单位[编号][技能名称] = nil
		end
	end
end

function 战斗处理类:取符咒种类(编号)
	if 编号 == nil or self.参战单位[编号] == nil or self.参战单位[编号].法术状态.咒符 == nil then
		return
	end

	local zt = self.参战单位[编号].法术状态.咒符
	local 种类 = {}
	local aa = {
		崩裂 = (zt.崩裂 or 0) + 0,
		震煞 = (zt.震煞 or 0) + 0,
		坤伏 = (zt.坤伏 or 0) + 0,
		轰天 = (zt.轰天 or 0) + 0,
		翻天 = (zt.翻天 or 0) + 0,
		倒海 = (zt.倒海 or 0) + 0
	}

	for k, v in pairs(aa) do
		if v > 0 then
			种类[#种类 + 1] = k
		end
	end

	return 种类
end

function 战斗处理类:符咒消耗(编号, 技能名称)
	if 编号 == nil or self.参战单位[编号] == nil or self.参战单位[编号].法术状态.咒符 == nil then
		return
	end

	local zt = self.参战单位[编号].法术状态.咒符
	local aa = {
		崩裂 = (zt.崩裂 or 0) + 0,
		震煞 = (zt.震煞 or 0) + 0,
		坤伏 = (zt.坤伏 or 0) + 0,
		轰天 = (zt.轰天 or 0) + 0,
		翻天 = (zt.翻天 or 0) + 0,
		倒海 = (zt.倒海 or 0) + 0
	}
	local 加成 = {}
	local 种类 = {}

	for k, v in pairs(aa) do
		if v > 0 then
			种类[#种类 + 1] = k
		end
	end

	if #种类 >= 3 and self:取奇经八脉是否有(编号, "雷暴") and zt.层数 > 0 and 技能名称 == "五雷正法" then
		local aa = 种类[取随机数(1, #种类)]
		zt[aa] = zt[aa] + zt.层数
		zt.层数 = 0
	end

	if #种类 > 0 then
		加成.种类 = DeepCopy(种类)
		加成.种类数量 = #种类 + 0
	end

	zt.回合 = 999

	if (zt.崩裂 or 0) > 0 then
		加成.主目标 = 0.32 * zt.崩裂
	elseif (zt.震煞 or 0) > 0 then
		加成.数量 = zt.震煞 + 0
	elseif (zt.坤伏 or 0) > 0 then
		加成.承伤数量 = zt.坤伏 + 0
	elseif (zt.轰天 or 0) > 0 then
		加成.驱散概率 = 15 * zt.轰天
	elseif (zt.翻天 or 0) > 0 then
		加成.非角色 = 0.35 * zt.翻天
	elseif (zt.倒海 or 0) > 0 then
		加成.角色 = 0.35 * zt.倒海
	end

	for k, v in pairs(aa) do
		zt[k] = 0
	end

	return 加成
end

function 战斗处理类:符咒转换(编号, 类型)
	if 编号 == nil or self.参战单位[编号] == nil or self.参战单位[编号].法术状态.咒符 == nil or (self.参战单位[编号].法术状态.咒符.层数 or 0) <= 0 then
		return
	end

	local aa = {
		坤伏 = 3,
		轰天 = 4,
		崩裂 = 1,
		倒海 = 6,
		翻天 = 5,
		震煞 = 2
	}

	if 类型 == nil or aa[类型] == nil then
		return
	end

	local cs = self.参战单位[编号].法术状态.咒符.层数 + 0
	local 叠加 = false

	if cs < 3 and self:取奇经八脉是否有(编号, "雷衍") then
		叠加 = true
	end

	if self:取奇经八脉是否有(编号, "奇门") then
		local tq = qz(self.天气)

		if tq == 1 then
			if 类型 == "坤伏" or 类型 == "震煞" then
				cs = cs + 1
			end
		elseif tq == 2 then
			if 类型 == "崩裂" or 类型 == "倒海" then
				cs = cs + 1
			end
		elseif tq == 3 and (类型 == "翻天" or 类型 == "轰天") then
			cs = cs + 1
		end
	end

	if 叠加 then
		self.参战单位[编号].法术状态.咒符[类型] = math.min((self.参战单位[编号].法术状态.咒符[类型] or 0) + cs, math.max(5, cs))
	else
		self.参战单位[编号].法术状态.咒符[类型] = cs
	end

	if self:取奇经八脉是否有(编号, "符威") then
		self:增加愤怒(编号, cs * 1)
	end

	self.参战单位[编号].法术状态.咒符.层数 = 0
	self.参战单位[编号].法术状态.咒符.回合 = 999
end

function 战斗处理类:法攻技能计算(编号, 名称, 等级, 伤害系数, 消耗, 参数列表)
	local 魔反目标, 助攻目标, 随机目标, 拘魂目标 = nil

	if 参数列表 ~= nil then
		魔反目标 = 参数列表.魔反目标
		助攻目标 = 参数列表.助攻目标
		随机目标 = 参数列表.随机目标
		拘魂目标 = 参数列表.拘魂目标
	end

	local 名称1 = ""
	local 目标 = self.参战单位[编号].指令.目标

	if 魔反目标 ~= nil then
		目标 = 魔反目标

		if self:取目标状态(编号, 目标, 1) == false then
			self.战斗流程[#self.战斗流程].返回 = true

			return
		end
	elseif 助攻目标 ~= nil then
		目标 = 助攻目标

		if self:取目标状态(编号, 目标, 1) == false then
			return
		end
	elseif 拘魂目标 ~= nil then
		目标 = 拘魂目标
	elseif 随机目标 ~= nil then
		目标 = self:取单个敌方目标(编号)
	end

	if 名称 == "扶摇万里1" then
		目标 = self:取对方气血百分比最低(编号)
		名称 = "扶摇万里"
		名称1 = "扶摇万里1"
	end

	local 目标数 = self:取目标数量(self.参战单位[编号], 名称, 等级, 编号)

	if 名称 == "摇头摆尾" then
		if ygsj() <= 70 then
			名称 = "摇头摆尾"

			if 编号 ~= nil and self:取奇经八脉是否有(编号, "震怒") then
				目标数 = 目标数 + 1
			end
		else
			名称 = "三昧真火"
			目标数 = math.min(目标数, 2)

			if 编号 ~= nil and self:取奇经八脉是否有(编号, "神炎") then
				目标数 = 目标数 + 1
			end
		end

		名称1 = "摇头摆尾"
		self.参战单位[编号].摇头摆尾1 = 1
	elseif 雷法技能[名称] ~= nil and self.参战单位[编号].魔法 > 30 then
		self.参战单位[编号].五雷正法加成 = nil

		if 名称 == "五雷正法" then
			self.参战单位[编号].五雷正法加成 = self:符咒消耗(编号, 名称)
			local jc = self.参战单位[编号].五雷正法加成

			if jc ~= nil and not 判断是否为空表(jc) then
				目标数 = 目标数 + (self.参战单位[编号].五雷正法加成.数量 or 0)
			end
		elseif self.参战单位[编号].法术状态.雷法真身 ~= nil then
			self.参战单位[编号].五雷正法加成 = self:符咒消耗(编号, 名称)

			self:符咒转换(编号, string.gsub(名称, "雷法·", ""))

			local jc = self.参战单位[编号].五雷正法加成

			if jc ~= nil and not 判断是否为空表(jc) then
				目标数 = 目标数 + (self.参战单位[编号].五雷正法加成.数量 or 0)
			end
		end
	end

	local 目标 = self:取多个敌方目标(编号, 目标, 目标数)

	if #目标 > 0 and 名称 == "六道无量" and 目标数 > 1 then
		local 新目标 = 列表2加入到列表1({
			目标[1]
		}, self.参战单位[编号].六道无量可选)

		删除重复(新目标)

		while 目标数 < #新目标 do
			table.remove(新目标, 取随机数(2, #新目标))
		end

		目标 = DeepCopy(新目标)
	end

	if 名称 == "上古灵符" then
		local 灵符随机 = {
			"上古灵符(怒雷)",
			"上古灵符(流沙)",
			"上古灵符(心火)"
		}
		名称 = 灵符随机[ygsj(#灵符随机)]
	end

	if 消耗 ~= "无消耗" then
	end

	if #目标 == 0 then
		return
	end

	local 目标重置 = {}

	for n = 1, #目标 do
		if self.参战单位[目标[n]].法术状态.分身术 ~= nil and self.参战单位[目标[n]].法术状态.分身术.破解 == nil then
			self.参战单位[目标[n]].法术状态.分身术.破解 = 1
			self.参战单位[编号].出手 = 1

			self:添加战斗流程提示("#P(分身术)#R" .. self.参战单位[编号].名称 .. "#W的攻击被#R" .. self.参战单位[目标[n]].名称 .. "#W的#Y分身术#W躲过去了！")
		else
			目标重置[#目标重置 + 1] = 目标[n]
		end
	end

	目标 = DeepCopy(目标重置)

	if #目标 == 0 then
		return
	end

	目标数 = #目标

	if 消耗 == nil and self:技能消耗(self.参战单位[编号], 目标数, 名称, 编号) == false then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "未到达技能消耗要求,技能使用失败")

		if 技能冷却列表[名称] ~= nil then
			self.参战单位[编号][名称] = 0
		end

		return
	end

	self:施法统一计算(编号, 名称)

	local 返回 = nil
	local 重复攻击 = false
	local 起始伤害 = 1
	local 叠加伤害 = 0
	local 重复提示 = false
	local 允许保护 = true
	local 增加伤害 = 0
	local 伤害参数 = 0
	local 结尾气血 = 0
	local 防御减少 = 0

	if 名称 == "匠心·破击" then
		if self.参战单位[编号].零件 == nil then
			self.参战单位[编号].零件 = 0
		end

		if self.参战单位[编号].守之械 == nil then
			self.参战单位[编号].守之械 = 0
		end

		if self.参战单位[编号].零件 < 3 and self.参战单位[编号].法术状态.据守 == nil and self.参战单位[编号].法术状态.巨锋 == nil and self.参战单位[编号].法术状态.战复 == nil then
			self.参战单位[编号].零件 = self.参战单位[编号].零件 + 1
			self.参战单位[编号].守之械 = self.参战单位[编号].守之械 + 1
		end

		if self.参战单位[编号].守之械 > 1 then
			self:取消状态("守之械" .. self.参战单位[编号].守之械 - 1, self.参战单位[编号])
		end

		self:添加状态("守之械" .. self.参战单位[编号].守之械, self.参战单位[编号], self.参战单位[目标[1]], self.参战单位[编号].守之械, 编号, nil)

		if self.参战单位[编号].守之械 >= 3 and self.参战单位[编号].零件 >= 3 then
			self:取消状态("守之械" .. self.参战单位[编号].守之械, self.参战单位[编号])

			self.参战单位[编号].零件 = 0
			self.参战单位[编号].守之械 = 0

			self:添加状态("据守", self.参战单位[编号])
		end

		if self.参战单位[编号].守之械 >= 1 and self.参战单位[编号].零件 >= 3 and self.参战单位[编号].攻之械 >= 1 then
			self:取消状态("守之械" .. self.参战单位[编号].守之械, self.参战单位[编号])
			self:取消状态("攻之械" .. self.参战单位[编号].攻之械, self.参战单位[编号])

			self.参战单位[编号].零件 = 0
			self.参战单位[编号].攻之械 = 0
			self.参战单位[编号].守之械 = 0

			self:添加状态("战复", self.参战单位[编号])
		end
	end

	if 名称 == "五行制化" then
		local 随机法术 = {
			"苍茫树",
			"靛沧海",
			"日光华",
			"巨岩破",
			"地裂火"
		}
		名称 = 随机法术[ygsj(#随机法术)]
		伤害系数 = 1.1
		self.参战单位[编号].五行回合 = self.回合数

		if self.战斗类型 == 110009 and self.参战单位[编号].模型 == "星灵仙子" then
			伤害系数 = 100.3
		end
	end

	if self.不施法 then
		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 200,
			攻击方 = 编号,
			技能 = 名称,
			挨打方 = {},
			提示 = {
				类型 = "法术",
				名称 = "",
				允许 = true
			}
		}
	elseif 名称 == "焰火烁星" and self.参战单位[编号].焰火烁星 ~= nil then
		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 200,
			攻击方 = 编号,
			技能 = 名称,
			挨打方 = {},
			提示 = {
				类型 = "法术",
				允许 = true,
				名称 = self.参战单位[编号].名称 .. "使用了超级" .. 名称
			}
		}
	else
		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 200,
			攻击方 = 编号,
			技能 = 名称,
			挨打方 = {},
			提示 = {
				类型 = "法术",
				允许 = true,
				名称 = self.参战单位[编号].名称 .. "使用了" .. 名称
			}
		}
	end

	local 精准战斗流程 = #self.战斗流程 + 0

	if 魔反目标 ~= nil then
		self.普攻被反击流程 = 精准战斗流程 + 0
	end

	if 名称 == "风云变色" then
		名称1 = "风云变色"
		名称 = "飞砂走石"
		self.参战单位[编号].风云变色1 = 1

		if self:取奇经八脉是否有(编号, "魔焱") then
			self:添加状态("炙烤", self.参战单位[编号])

			self.参战单位[编号].法术状态.炙烤.回合 = 4
		end

		if self:取奇经八脉是否有(编号, "燃魂") and ygsj() <= 50 then
			if self.参战单位[编号].法术状态.燃魂 == nil then
				self:添加战斗流程提示("#P(燃魂)#R" .. self.参战单位[编号].名称 .. "#W进入了#Y燃魂#W状态")
			end

			self:添加状态("燃魂", self.参战单位[编号])

			self.参战单位[编号].法术状态.燃魂.回合 = math.max(self.参战单位[编号].法术状态.燃魂.回合, 2)
		end
	elseif 名称 == "五雷咒" then
		if self.参战单位[编号].怒霆 ~= nil then
			if self.参战单位[编号].怒霆 >= 5 then
				self.参战单位[编号].怒霆 = self.参战单位[编号].怒霆 - 5
			end

			self.参战单位[编号].怒霆 = self.参战单位[编号].怒霆 + 1
		end
	elseif 雷法技能[名称] ~= nil then
		if 名称 ~= "五雷正法" and self.参战单位[编号].法术状态.雷法真身 == nil then
			self:符咒转换(编号, string.gsub(名称, "雷法·", ""))
		end

		local jc = self.参战单位[编号].五雷正法加成

		if jc ~= nil and jc.承伤数量 ~= nil then
			jc.承伤目标 = {}

			for i = 1, jc.承伤数量 do
				local aa = 取随机数(1, #目标)
				jc.承伤目标[目标[aa]] = (jc.承伤目标[目标[aa]] or 0) + 1
			end
		end
	end

	if 魔反目标 ~= nil then
		if 名称 == "烈焰斩" then
			self:添加战斗流程提示("#P(烈焰斩)#R" .. self.参战单位[编号].名称 .. "#W对#R" .. self.参战单位[目标[1]].名称 .. "#W追加使用了#R烈焰斩")
		elseif 名称 == "影袭" then
			self:添加战斗流程提示("#P(影袭)#R" .. self.参战单位[编号].名称 .. "#W对#R" .. self.参战单位[目标[1]].名称 .. "#W追加使用了#R影袭")
		else
			self:添加战斗流程提示("#P(魔法反击)#R" .. self.参战单位[编号].名称 .. "#W对#R" .. self.参战单位[目标[1]].名称 .. "#W使用了#G" .. 名称)
		end
	elseif 拘魂目标 ~= nil then
		self:添加战斗流程提示("#P(拘魂索命)#R" .. self.参战单位[编号].名称 .. "#W触发了#R拘魂索命#W对" .. self.参战单位[目标[1]].名称 .. "#W使用了#G" .. 名称)
	elseif 助攻目标 ~= nil then
		self:添加战斗流程提示("#P(法术助攻)#R" .. self.参战单位[编号].名称 .. "#W对#R" .. self.参战单位[目标[1]].名称 .. "#W使用了#G" .. 名称)
	end

	if 名称 == "飞砂走石" then
		self:添加临时属性(编号, "法暴", 5)

		if self.参战单位[编号].魔冥 ~= nil then
			self:添加状态("魔冥", self.参战单位[编号])

			self.参战单位[编号].法术状态.魔冥.回合 = 4
			self.参战单位[编号].法术状态.魔冥.层数 = math.min((self.参战单位[编号].法术状态.魔冥.层数 or 0) + 1, 4)
		end
	elseif 名称 == "谆谆教诲" then
		if self:取奇经八脉是否有(编号, "修习") then
			self.参战单位[编号].修习 = (self.参战单位[编号].修习 or 0) + 1

			self:添加临时属性(编号, "法连", 25 + self.参战单位[编号].修习 * 5)
		end
	elseif 名称 == "唧唧歪歪" then
		if self:取奇经八脉是否有(编号, "诵经") then
			if self.参战单位[编号].法术状态.诵经 == nil then
				self:添加状态("诵经", self.参战单位[编号])
			else
				self.参战单位[编号].法术状态.诵经.层数 = math.min(self.参战单位[编号].法术状态.诵经.层数 + 1, 5)
				self.参战单位[编号].法术状态.诵经.回合 = 999
			end
		end

		if self:取奇经八脉是否有(编号, "解惑") then
			self:减少技能冷却(编号, "谆谆教诲", 3)
		end
	elseif 名称 == "龙卷雨击" then
		if self:取奇经八脉是否有(编号, "龙駭") and ygsj() <= 25 then
			self:添加状态("龙駭·龙腾", self.参战单位[编号])
		end
	elseif 名称 == "龙腾" then
		if self:取奇经八脉是否有(编号, "龙駭") and ygsj() <= 25 then
			self:添加状态("龙駭·龙卷雨击", self.参战单位[编号])
		end

		if self:取奇经八脉是否有(编号, "龍骇") then
			local 触发概率 = 25
			local 额外概率 = 0

			if self:取奇经八脉是否有(编号, "傲岸") then
				额外概率 = 额外概率 + 60
			end

			if self:取奇经八脉是否有(编号, "云魂") and self.参战单位[编号].法术状态.龍魂 ~= nil then
				额外概率 = 额外概率 + 100
			end

			触发概率 = 触发概率 + 额外概率

			if ygsj() <= 触发概率 then
				self:添加状态("龍骇", self.参战单位[编号])

				self.参战单位[编号].法术状态.龍骇.层数 = math.min((self.参战单位[编号].法术状态.龍骇.层数 or 0) + 1, 龍骇最高层数)

				if self:取奇经八脉是否有(编号, "盘龙") then
					self.参战单位[编号].盘龙 = (self.参战单位[编号].盘龙 or 1) + 0.02
				end
			end
		end
	elseif 名称 == "三昧真火" or 名称 == "秘传三昧真火" then
		self:添加临时属性(编号, "法暴", 10)
	elseif 名称 == "摇头摆尾" then
		self:添加临时属性(编号, "法暴", 10)
	elseif 名称 == "风卷残云" then
		if self.参战单位[编号].风灵 ~= nil and self.参战单位[编号].法术状态.风灵 ~= nil then
			cs = self.参战单位[编号].法术状态.风灵.层数 + 0
			self.参战单位[编号].风灵增伤 = (self.参战单位[编号].风灵增伤 or 1) + cs * 0.16

			self:取消状态("风灵", self.参战单位[编号])
		end

		if self:法宝判断("月影", 编号) then
			self.参战单位[编号].风灵增伤 = (self.参战单位[编号].风灵增伤 or 1) + 0.2
		end
	end

	if 目标数 > 0 then
		self:法术吸血判定(名称, 目标数, 精准战斗流程)
	end

	if 重复攻击 == true then
		local 临时目标 = 目标[1]

		for n = 1, 目标数 do
			目标[n] = 临时目标
		end
	end

	if 物攻群法技能列表[名称] ~= nil then
		for n = 1, 目标数 do
			self:物攻群法计算1(编号, 名称, 等级, 目标[n], 目标数, n, 伤害系数, 精准战斗流程)
		end
	else
		if 名称 == "龙腾" then
			if self:取奇经八脉是否有(编号, "惊鸿") then
				self.参战单位[编号].惊鸿 = 1
			end
		elseif 名称 == "雷霆万钧" then
			if self.参战单位[编号].怒电 ~= nil then
				self:添加状态("天雷灌注", self.参战单位[编号])

				self.参战单位[编号].法术状态.天雷灌注.层数 = 1
				self.参战单位[编号].怒电 = self.参战单位[编号].怒电 - 1

				if self.参战单位[编号].怒电 <= 0 then
					self.参战单位[编号].怒电 = nil
				end
			end
		elseif 名称 == "琴音三叠" then
			if self:取奇经八脉是否有(编号, "琴魂") then
				self.参战单位[编号].琴魂 = 1
			end

			if self:取奇经八脉是否有(编号, "抚琴") then
				self.参战单位[编号].抚琴 = 1.2
			end

			if self:取奇经八脉是否有(编号, "穿透") then
				self.参战单位[编号].穿透 = 1.35
			end
		end

		for n = 1, 目标数 do
			if 重复攻击 and self.参战单位[目标[n]].气血 <= 0 then
				break
			end

			self:法攻技能计算1(编号, 名称, 等级, 目标[n], 目标数, n, 伤害系数, 精准战斗流程)
		end

		if 名称 == "龙腾" and self:取奇经八脉是否有(编号, "惊鸿") then
			self.参战单位[编号].惊鸿 = nil
		elseif 名称 == "琴音三叠" then
			self.参战单位[编号].琴魂 = nil
			self.参战单位[编号].抚琴 = nil
			self.参战单位[编号].穿透 = nil
		end

		if self.参战单位[编号].拘魂索命 ~= nil then
			self.参战单位[编号].拘魂索命 = self.参战单位[编号].拘魂索命 + 1

			if self.参战单位[编号].拘魂索命 >= 4 then
				self.参战单位[编号].拘魂索命 = 0

				self:法攻技能计算(编号, 名称, 等级, 0.8, nil, {
					拘魂目标 = self:取对方气血百分比最低(编号)
				})
			end
		end
	end

	if 参数列表 ~= nil and 参数列表.返回 ~= nil then
		self.战斗流程[精准战斗流程].返回 = 参数列表.返回
	end

	if 名称 == "自爆" then
		self.战斗流程[精准战斗流程].流程 = 500
		self.战斗流程[精准战斗流程].伤害 = self.参战单位[编号].气血
		self.参战单位[编号].气血 = 0
	end

	local 上一次流程 = DeepCopy(self.战斗流程[精准战斗流程])

	for n = 1, 目标数 do
		for i = 1, #上一次流程.挨打方 do
			if 目标[n] == 上一次流程.挨打方[i].挨打方 then
				if self.参战单位[编号].气血 > 0 and self.参战单位[目标[n]].法术状态.混元伞 ~= nil then
					local 反弹伤害 = qz(上一次流程.挨打方[i].伤害 * (self.参战单位[目标[n]].法术状态.混元伞.境界 * 混元伞反弹比例 + 0.1))
					self.战斗流程[#self.战斗流程 + 1] = {
						流程 = 104,
						气血 = 反弹伤害,
						攻击方 = 目标[n],
						挨打方 = {
							挨打方 = 编号,
							特效 = {},
							死亡 = self:减少气血(编号, 反弹伤害, 目标[n], nil, nil, nil, 1)
						},
						提示 = {
							允许 = false
						}
					}
				end

				if self.参战单位[编号].气血 > 0 and self.参战单位[目标[n]].法术状态.幻镜术 ~= nil and ygsj() <= 40 then
					local 反弹伤害 = qz(上一次流程.挨打方[i].伤害 * 1)
					self.战斗流程[#self.战斗流程 + 1] = {
						流程 = 135,
						气血 = 反弹伤害,
						攻击方 = 目标[n],
						挨打方 = {
							挨打方 = 编号,
							特效 = {},
							死亡 = self:减少气血(编号, 反弹伤害, 目标[n], nil, nil, nil, 1)
						},
						提示 = {
							允许 = false
						}
					}
				end

				if self.参战单位[编号].气血 > 0 and self.参战单位[目标[n]].法术状态.天衣无缝 ~= nil then
					local 反弹伤害 = qz(上一次流程.挨打方[i].伤害 * 0.5)
					self.战斗流程[#self.战斗流程 + 1] = {
						流程 = 134,
						气血 = 反弹伤害,
						攻击方 = 目标[n],
						挨打方 = {
							挨打方 = 编号,
							特效 = {},
							死亡 = self:减少气血(编号, 反弹伤害, 目标[n], nil, nil, nil, 1)
						},
						提示 = {
							允许 = false
						}
					}
				end
			end
		end
	end

	self.临时属性[编号].法暴 = nil

	if 名称 == "龙卷雨击" then
		self.参战单位[编号].法术状态["龙駭·龙卷雨击"] = nil
		self.参战单位[编号].法术状态.龍骇 = nil
	elseif 名称 == "龙腾" then
		self.参战单位[编号].法术状态["龙駭·龙腾"] = nil
	elseif 名称 == "谆谆教诲" then
		self.参战单位[编号].法术状态.诵经 = nil
	elseif 名称 == "三昧真火" or 名称 == "魔焰滔天" then
		self.参战单位[编号].法术状态.魔冥 = nil
	elseif 名称 == "秘传三昧真火" or 名称 == "秘传飞砂走石" then
		self.参战单位[编号].不忿 = nil
	end

	if 名称 == "三昧真火" or 名称 == "飞砂走石" and self:取奇经八脉是否有(编号, "咒言") then
		self:减少技能冷却(编号, "秘传三昧真火", 1)
		self:减少技能冷却(编号, "秘传飞砂走石", 1)
	end

	if 名称1 == "风云变色" then
		self.参战单位[编号].风云变色1 = nil
	elseif 名称1 == "摇头摆尾" then
		self.参战单位[编号].摇头摆尾1 = nil
	elseif 名称 == "雷霆汹涌" then
		self.参战单位[编号].天雷灌注雷霆汹涌 = nil
	elseif 名称 == "雷霆万钧" then
		self.参战单位[编号].天雷灌注雷霆万钧 = nil
	elseif 名称 == "五雷咒" then
		self.参战单位[编号].灵能 = nil
	elseif 名称 == "判官令" then
		self.参战单位[编号].阎罗 = nil
	elseif 名称 == "六道无量" then
		self.参战单位[编号].阎罗 = nil

		self:取消状态("噬毒·六道无量", self.参战单位[编号])
	elseif 名称 == "夺命咒" then
		if self.参战单位[编号].深刻 ~= nil then
			self.参战单位[编号].深刻 = "追魂刺"
		end

		if self:取是否有指定状态(编号, 编号, "燃血术·幽冥巫煞") then
			self.参战单位[编号].法术状态["燃血术·幽冥巫煞"].层数 = self.参战单位[编号].法术状态["燃血术·幽冥巫煞"].层数 - 1

			if self.参战单位[编号].法术状态["燃血术·幽冥巫煞"].层数 < 1 then
				self:取消状态("燃血术·幽冥巫煞", self.参战单位[编号])
			end
		end
	elseif 名称 == "兴风作浪" or 名称 == "棒掀北斗" then
		if self.参战单位[编号].通天威仪 ~= nil then
			self.参战单位[编号].通天威仪 = 名称
		end
	elseif 名称 == "追魂刺" then
		if self.参战单位[编号].深刻 ~= nil then
			self.参战单位[编号].深刻 = "夺命咒"
		end

		if self:取是否有指定状态(编号, 编号, "燃血术·幽冥巫煞") then
			self.参战单位[编号].法术状态["燃血术·幽冥巫煞"].层数 = self.参战单位[编号].法术状态["燃血术·幽冥巫煞"].层数 - 1

			if self.参战单位[编号].法术状态["燃血术·幽冥巫煞"].层数 < 1 then
				self:取消状态("燃血术·幽冥巫煞", self.参战单位[编号])
			end
		end
	end

	self.参战单位[编号].风灵增伤 = nil
end

function 战斗处理类:取固伤结果(编号, 伤害)
	local 目标 = self.参战单位[编号].指令.目标
	local 修炼差 = 1

	if self.参战单位[编号].法术修炼 == nil then
		self.参战单位[编号].法术修炼 = 0
	end

	if self.参战单位[目标].抗法修炼 == nil then
		self.参战单位[目标].抗法修炼 = 0
	end

	local 修炼差 = 1 + self.参战单位[编号].法术修炼 * 0.025 - self.参战单位[目标].抗法修炼 * 0.025
	local 加成 = 0

	if self.参战单位[编号].敏捷 ~= nil and self.参战单位[编号].类型 == "角色" and self.参战单位[编号].武器伤害 ~= nil then
		伤害 = math.max((伤害 + 加成 + self.参战单位[编号].敏捷 * 0.3 + self.参战单位[编号].武器伤害 * 0.46) * 修炼差,
			(伤害 + self.参战单位[编号].速度 * 0.25) * 修炼差)
	else
		伤害 = (伤害 + self.参战单位[编号].速度 * 0.25) * 修炼差
	end

	if self.参战单位[编号].固伤加成 ~= nil then
		伤害 = 伤害 * self.参战单位[编号].固伤加成
	end

	if self.参战单位[编号].法术状态.莲心剑意 ~= nil then
		伤害 = 伤害 * (1 + self.参战单位[编号].法术修炼 * 0.03)
	end

	return math.floor(伤害)
end

