function 战斗处理类:法术躲避计算(编号, 目标, 名称)
	local 躲避率 = 0

	if self.参战单位[编号].门派 == "龙宫" or 装备特技[名称] ~= nil or 固伤法术列表[名称] ~= nil or 必中法术列表[名称] ~= nil or self.参战单位[编号].法术状态.晕眩 ~= nil then
		return false
		--elseif 名称 == "毁灭之光" and 毁灭之光测试通杀 then
		--	return false
	elseif 名称 == "百爪狂杀" then
		return false
	end

	if 目标 ~= nil or self.参战单位[目标] ~= nil then
		return false
	elseif self.参战单位[目标].门派 == "天宫" then
		躲避率 = 躲避率 + 15
	end

	躲避率 = 躲避率 + (self.参战单位[目标].法术躲避率 or 0)

	if 取随机数(1, 10000) <= 躲避率 * 100 then
		return true
	end

	return false
end

function 战斗处理类:法攻技能计算1(编号, 名称, 等级, 目标, 目标数, 执行数, 伤害系数, 精准流程)
	self.战斗流程[精准流程].挨打方[执行数] = {
		特效 = {},
		挨打方 = 目标
	}
	local 精准战斗流程 = 精准流程 + 0

	if self.参战单位[编号].武器伤害 == nil then
		self.参战单位[编号].武器伤害 = 0
	end

	local 临时灵力 = 0

	if self:取符石组合效果(self.参战单位[编号], "隔山打牛") and ygsj() <= 20 then
		临时灵力 = 临时灵力 + self:取符石组合效果(self.参战单位[编号], "隔山打牛")
	end

	if self.参战单位[编号].通灵法 ~= nil then
		临时灵力 = 临时灵力 + (self.参战单位[目标].法防 or self.参战单位[目标].灵力) * 0.04 * self.参战单位[编号].通灵法
	end

	if 编号 ~= nil and self:取奇经八脉是否有(编号, "唤雨") then
		临时灵力 = 临时灵力 + math.min(1 - self.参战单位[目标].魔法 / math.max(self.参战单位[目标].最大魔法, 1), 1) * 0.08 * self.参战单位[编号].法伤
	end

	if (名称 == "唧唧歪歪" or 名称 == "谆谆教诲") and 编号 ~= nil then
		if self:取奇经八脉是否有(编号, "授业") then
			临时灵力 = 临时灵力 + 80
		end

		if self.参战单位[编号].无量尊者舍利 ~= nil then
			临时灵力 = 临时灵力 + self.参战单位[编号].无量尊者舍利
		end

		if self.参战单位[编号].销武 ~= nil then
			if self.参战单位[编号].法术状态.销武 == nil then
				self:添加状态("销武", self.参战单位[编号])
			else
				self.参战单位[编号].法术状态.销武.回合 = 999
			end
		end
	end

	if 名称 == "唧唧歪歪" and 编号 ~= nil then
	elseif (名称 == "龙腾" or 名称 == "亢龙归海") and 编号 ~= nil then
		if self:取奇经八脉是否有(编号, "波涛") then
			临时灵力 = 临时灵力 + math.max(self.参战单位[编号].灵力, self.参战单位[编号].法伤) * 0.1
		end

		if self:取奇经八脉是否有(编号, "雨魄") then
			临时灵力 = 临时灵力 + math.max(self.参战单位[编号].灵力, self.参战单位[编号].法伤) * 0.15
		end
	elseif (名称 == "龙卷雨击" or 名称 == "雷浪穿云") and 编号 ~= nil then
		if self:取奇经八脉是否有(编号, "逐浪") then
			临时灵力 = 临时灵力 + self.参战单位[编号].法伤 * 0.15
		end

		if self:取奇经八脉是否有(编号, "狂浪") and ygsj() <= 50 then
			临时灵力 = 临时灵力 + 80
		end

		if self:取奇经八脉是否有(编号, "波涛") then
			临时灵力 = 临时灵力 + math.max(self.参战单位[编号].灵力, self.参战单位[编号].法伤) * 0.05
		end
	elseif 名称 == "落叶萧萧" and self:取奇经八脉是否有(编号, "狂叶") and self.参战单位[编号].法术状态.风灵 == nil then
		临时灵力 = 临时灵力 + 90
	end

	if 编号 ~= nil and ygsj() <= 5 and self:取奇经八脉是否有(编号, "天龙") then
		临时灵力 = 临时灵力 + 等级 * 10
	end

	if 编号 ~= nil and self.参战单位[编号].义薄云天 ~= nil then
		临时灵力 = 临时灵力 + self.参战单位[编号].义薄云天
	end

	if 编号 ~= nil and self.参战单位[编号].龙慑 ~= nil and self.参战单位[目标].玩家id == 0 then
		临时灵力 = 临时灵力 + 50 * self.参战单位[编号].龙慑
	end

	临时灵力 = qz(临时灵力)
	local 基础伤害 = qz(self:取灵力伤害(self.参战单位[编号], self.参战单位[目标], 临时灵力, 名称))
	local 灵力系数 = 1
	local 增加伤害 = 0
	local 结尾气血 = 0
	local 附加状态, 吸收, 弱点, 伤势 = nil
	local 伤势类型 = 1
	local 灵力 = true
