			if self:取符石组合效果(编号, "福泽天下") then
				基础伤害 = qz(基础伤害 + self:取符石组合效果(编号, "福泽天下"))
			end
		elseif 名称 == "罗汉悟道" then
			灵力系数 = 分灵系数.门派单法系数 + 0.6
		elseif 名称 == "谆谆教诲" then
			灵力系数 = 分灵系数.门派单法系数

			if self:取符石组合效果(编号, "福泽天下") then
				基础伤害 = qz(基础伤害 + self:取符石组合效果(编号, "福泽天下"))
			end
		elseif 名称 == "笑里藏刀" then
			灵力系数 = 0
		elseif 名称 == "绝幻魔音" then
			灵力系数 = 0
			self.战斗流程[精准战斗流程].流程 = 205
		elseif 名称 == "紫气东来" then
			灵力系数 = 1

			if self.参战单位[目标].门派 == "普陀山" then
				基础伤害 = 等级 * 5 + qz(self.参战单位[目标].最大气血 * 等级 / 600)
				基础伤害 = self:取固伤结果(编号, 基础伤害)
				灵力 = false
			end
		elseif 名称 == "天诛地灭" then
