				self:添加状态(名称, self.参战单位[目标], self.参战单位[编号], 等级, 编号)
			end
		elseif 名称 == "摧心术" then
			if self:取封印成功(名称, 等级, self.参战单位[编号], self.参战单位[目标]) then
				附加状态 = "摧心术"

				self:添加状态(名称, self.参战单位[目标], self.参战单位[编号], 等级, 编号)
			end
		elseif 名称 == "摇头摆尾" then
			基础伤害 = 基础伤害 + 等级 * 1
			灵力系数 = math.max(分灵系数.门派单法系数 - 目标数 * 0.1, 分灵系数[3])

			if 编号 ~= nil and ygsj() <= 20 then
				附加状态 = "摇头摆尾"

				self:添加状态("摇头摆尾", self.参战单位[目标], self.参战单位[编号], self.参战单位[编号].等级, 编号)
			end

			self.战斗流程[精准战斗流程].流程 = 205
		elseif 雷法技能[名称] ~= nil then
			if 属性吸收无限制 ~= nil and 属性吸收无限制 == 1 then
				吸收 = 属性吸收类型[1]
				弱点 = 属性吸收类型[1]
			end

			基础伤害 = 基础伤害 + 等级 * 1
			灵力系数 = 分灵系数.门派单法系数

			if 名称 == "五雷正法" or self.参战单位[编号].法术状态.雷法真身 ~= nil then
				local jc = self.参战单位[编号].五雷正法加成

				if jc ~= nil and not 判断是否为空表(jc) then
					local 伤害加成 = 0

					if 执行数 == 1 then
						if 伤害叠加模式 == 1 then
							灵力系数 = 灵力系数 * (1 + (jc.主目标 or 0))
						else
							伤害加成 = 伤害加成 + (jc.主目标 or 0) * 灵力系数
						end

						if jc.驱散概率 ~= nil and ygsj() <= jc.驱散概率 then
							self:驱散目标状态(目标, 编号)
						end
					end

					if self:取奇经八脉是否有(编号, "天箓") and jc.种类数量 ~= nil and jc.种类数量 >= 3 then
						if 伤害叠加模式 == 1 then
							灵力系数 = 灵力系数 * 1.16
						else
							伤害加成 = 伤害加成 + 0.16 * 灵力系数
						end
					end

					if self.参战单位[目标].类型 == "bb" then
						if 伤害叠加模式 == 1 then
							灵力系数 = 灵力系数 * (1 + (jc.非角色 or 0))
						else
							伤害加成 = 伤害加成 + (jc.非角色 or 0) * 灵力系数
						end
					elseif 伤害叠加模式 == 1 then
						灵力系数 = 灵力系数 * (1 + (jc.角色 or 0))
					else
						伤害加成 = 伤害加成 + (jc.角色 or 0) * 灵力系数
					end

					if 伤害叠加模式 ~= 1 then
						灵力系数 = 灵力系数 + 伤害加成
					end

					if jc.承伤目标 ~= nil and jc.承伤目标[目标] ~= nil then
						if self.参战单位[目标].法术状态["雷法·坤伏"] == nil then
							self:添加状态("雷法·坤伏", self.参战单位[目标], self.参战单位[编号], jc.承伤目标[目标], 编号)
						else
							self.参战单位[目标].法术状态["雷法·坤伏"].受到法术伤害 = self.参战单位[目标].法术状态["雷法·坤伏"].受到法术伤害 + 5 * jc.承伤目标[目标]
							self.参战单位[目标].法术状态["雷法·坤伏"].受到物理伤害 = self.参战单位[目标].法术状态["雷法·坤伏"].受到物理伤害 + 5 * jc.承伤目标[目标]
						end

						self:更新单个法术状态(目标, "雷法·坤伏")
					end
				end
			end
		elseif 名称 == "五雷咒" then
			if 属性吸收无限制 ~= nil and 属性吸收无限制 == 1 then
				吸收 = 属性吸收类型[1]
				弱点 = 属性吸收类型[1]
			end

			基础伤害 = 基础伤害 + 等级 * 1
			灵力系数 = 分灵系数.门派单法系数
		elseif 名称 == "落雷符" then
			if 属性吸收无限制 ~= nil and 属性吸收无限制 == 1 then
				吸收 = 属性吸收类型[1]
				弱点 = 属性吸收类型[1]
			end

			基础伤害 = 基础伤害 + 等级 * 0.5
			灵力系数 = math.max(分灵系数.门派群法系数 - 目标数 * 0.1, 分灵系数[3])

			if self.参战单位[目标].鬼魂 ~= nil then
				灵力系数 = 灵力系数 + 0.2
			end

			if self:取符石组合效果(编号, "石破天惊") then
				基础伤害 = qz(基础伤害 + self:取符石组合效果(编号, "石破天惊"))
			end
		elseif 名称 == "飞符炼魂" then
			基础伤害 = 基础伤害 + 等级 * 3
			灵力系数 = math.max(分灵系数.门派单法系数 - 目标数 * 0.1, 分灵系数[3]) * 2

			if self.参战单位[目标].鬼魂 ~= nil then
				灵力系数 = 灵力系数 + 0.6
			end

			self.参战单位[编号].飞符回合 = self.回合数

			if 编号 ~= nil and self:取奇经八脉是否有(编号, "飞符炼魂") then
				附加状态 = "落魄符"

				self:添加状态("落魄符", self.参战单位[目标], self.参战单位[编号], self.参战单位[编号].等级, 编号)
