				end
			elseif 名称 == "棒掀北斗" then
				法术暴伤最终倍率 = 法术暴伤最终倍率 + 0.5
			elseif (名称 == "冰川怒" or 名称 == "荆棘舞" or 名称 == "尘土刃") and self:取奇经八脉是否有(编号, "破杀") then
				法术暴伤最终倍率 = 法术暴伤最终倍率 + 0.2
			end

			if self:取奇经八脉是否有(目标, "神躯") then
				法术暴伤最终倍率 = 法术暴伤最终倍率 - 0.2
			end

			if self:取奇经八脉是否有(目标, "灵身") then
				法术暴伤最终倍率 = 法术暴伤最终倍率 - 0.4
			end

			if self.参战单位[目标].逍遥游 ~= nil then
				法术暴伤最终倍率 = 法术暴伤最终倍率 - 0.5
			end

			if self.参战单位[目标].幸运 ~= nil then
				法术暴伤最终倍率 = 法术暴伤最终倍率 - (1 - self.参战单位[目标].幸运)
			end

			if self.参战单位[编号].灵身 ~= nil then
				法术暴伤最终倍率 = 法术暴伤最终倍率 + 0.07 * self.参战单位[编号].灵身
			end

			伤害 = 伤害 * 法术暴伤最终倍率
		elseif not 灵力 and (五行固伤法术[名称] ~= nil or 名称 == "相灭相生") and self:取奇经八脉是否有(编号, "法咒") then
			local gl = 15

			if 执行数 == 1 and self.参战单位[编号].法术状态.莲心剑意 ~= nil then
				gl = 40
			end

			if ygsj() <= gl then
				法爆成功 = true
			end

			伤害 = 伤害 * 1.5
		end

		local 伤害类型 = 1

		if 弱点 ~= nil then
			if 弱点 == "土" and (self.参战单位[目标].弱点土 ~= nil or self.参战单位[目标].法术状态.弱点土 ~= nil) then
				伤害 = 伤害 * 1.5
			elseif 弱点 == "雷" and (self.参战单位[目标].弱点雷 ~= nil or self.参战单位[目标].法术状态.弱点雷 ~= nil) then
				伤害 = 伤害 * 1.5
			elseif 弱点 == "火" and (self.参战单位[目标].弱点火 ~= nil or self.参战单位[目标].法术状态.弱点火 ~= nil) then
				伤害 = 伤害 * 1.5
			elseif 弱点 == "水" and (self.参战单位[目标].弱点水 ~= nil or self.参战单位[目标].法术状态.弱点水 ~= nil) then
				伤害 = 伤害 * 1.5
			end
		end

		if 伤势 ~= nil and 伤害类型 ~= 2 and 伤害 > 0 then
			if self.参战单位[目标].类型 == "角色" and self.参战单位[目标].助战编号 == nil then
				self.战斗流程[精准战斗流程].挨打方[执行数].伤势 = 伤势
				self.战斗流程[精准战斗流程].挨打方[执行数].伤势类型 = 伤势类型
			else
				伤势 = nil
			end
		end

		self.战斗流程[精准战斗流程].挨打方[执行数].类型 = 伤害类型
		self.战斗流程[精准战斗流程].挨打方[执行数].特效[1] = 名称
		self.战斗流程[精准战斗流程].挨打方[执行数].状态 = 附加状态
		self.战斗流程[精准战斗流程].挨打方[执行数].取消状态 = 取消状态
		self.战斗流程[精准战斗流程].结尾气血 = 结尾气血
		self.战斗流程[精准战斗流程].不施法 = self.不施法

		if 灵力 and 伤害类型 ~= 2 and 伤害 > 0 then
			if self:法宝判断("降魔斗篷", 目标) ~= false then
				local 法宝名称 = "降魔斗篷"

				for i = 1, #self.参战单位[目标].法宝列表[法宝名称] do
					local 法宝位置 = self.参战单位[目标].法宝列表[法宝名称][i]
					local 境界 = self:法宝概率判断(法宝名称, 目标, 法宝位置, 1)

					if 境界 ~= false then
						伤害 = qz(伤害 * 0.45)
						self.战斗流程[精准战斗流程].挨打方[执行数].伤害 = 伤害
						self.战斗流程[精准战斗流程].挨打方[执行数].特效[#self.战斗流程[精准战斗流程].挨打方[执行数].特效 + 1] = "降魔斗篷"
					end
				end
			end

			if self:法宝判断("蟠龙玉璧", 目标) ~= false then
				local 法宝名称 = "蟠龙玉璧"

				for i = 1, #self.参战单位[目标].法宝列表[法宝名称] do
					local 法宝位置 = self.参战单位[目标].法宝列表[法宝名称][i]
					local 境界 = self:法宝概率判断(法宝名称, 目标, 法宝位置, 1)

					if 境界 ~= false then
						local 减伤效果 = 1 - (境界 * 0.015 + 0.13)
						伤害 = qz(伤害 * 减伤效果)
						伤害 = math.max(伤害, 0)
						self.战斗流程[精准战斗流程].挨打方[执行数].伤害 = 伤害
						self.战斗流程[精准战斗流程].挨打方[执行数].特效[#self.战斗流程[精准战斗流程].挨打方[执行数].特效 + 1] = "降魔斗篷"
					end
				end
			end

			if self:法宝判断("澄空净铃", 目标) ~= false then
				local 法宝名称 = "澄空净铃"

				for i = 1, #self.参战单位[目标].法宝列表[法宝名称] do
					local 法宝位置 = self.参战单位[目标].法宝列表[法宝名称][i]
					local 境界 = self:法宝概率判断(法宝名称, 目标, 法宝位置, 1)

					if 境界 ~= false then
						local 减伤效果 = 1 - (境界 * 0.015 + 0.03)

						if self.天气 == 0 then
							减伤效果 = 1 - (境界 * 0.025 + 0.1)
						end

						伤害 = qz(伤害 * 减伤效果)
						伤害 = math.max(伤害, 0)
						self.战斗流程[精准战斗流程].挨打方[执行数].伤害 = 伤害
						self.战斗流程[精准战斗流程].挨打方[执行数].特效[#self.战斗流程[精准战斗流程].挨打方[执行数].特效 + 1] = "降魔斗篷"
					end
				end
			end
		end

		local 最终结果1 = nil

		if 灵力 then
			最终结果1 = self:新增状态处理("法术", 编号, 目标, 伤害, 伤害类型, 执行数, 名称, 吸收, 等级, 精准战斗流程 + 0)
		else
			最终结果1 = self:新增状态处理("固伤", 编号, 目标, 伤害, 伤害类型, 执行数, 名称, nil, 等级, 精准战斗流程 + 0)
		end

		伤害 = qz(最终结果1.伤害)
		伤害类型 = 最终结果1.类型

		if 五行固伤法术[名称] ~= nil and self:取五行克制(五行固伤法术[名称], self.参战单位[目标].防御五行) then
			self:造成伤势(目标, 伤害)

			self.战斗流程[精准战斗流程].挨打方[1].伤势 = 伤害 + 0

			if self.参战单位[目标].气血上限 ~= nil and self.参战单位[目标].气血上限 == 0 and self:取奇经八脉是否有(编号, "秘术") then
				self:添加状态("秘术", self.参战单位[目标])
				self:更新单个法术状态(目标, "秘术")
				self:添加战斗流程提示("#P(秘术)#R" .. self.参战单位[目标].名称 .. "#W气血上限为#R0#W、立即死亡且当回合无法复活。")

				伤害 = self.参战单位[目标].最大气血 + 99999
			end
		end

		if self.参战单位[目标].法术状态.天地同寿 ~= nil then
			伤害 = 1
			伤害类型 = 2
			self.战斗流程[精准战斗流程].挨打方[执行数].特效[#self.战斗流程[精准战斗流程].挨打方[执行数].特效 + 1] = "天地同寿"
		end

		if self.参战单位[目标].法术状态.波澜不惊 ~= nil and self.参战单位[目标].法术状态.波澜不惊.层数 >= 1 and 伤害 > 1 and 伤害类型 ~= 2 then
			local 编号1 = self.参战单位[目标].法术状态.波澜不惊.攻击编号
			local 最大吸收 = self.参战单位[目标].法术状态.波澜不惊.等级 * 4 + self.参战单位[编号1].灵力 * 0.1
			最大吸收 = self:取恢复气血(编号1, 目标, 最大吸收, "普渡众生", 1) * 2
			local 吸收血量 = 0

			if 伤害 <= 最大吸收 then
				吸收血量 = 伤害
				伤害类型 = 2
			else
				吸收血量 = 最大吸收
				伤害 = 伤害 - 最大吸收
				self.战斗流程[精准战斗流程].挨打方[执行数].恢复气血 = 吸收血量
			end

			self:增加气血(目标, 吸收血量)

			self.战斗流程[精准战斗流程].挨打方[执行数].特效[#self.战斗流程[精准战斗流程].挨打方[执行数].特效 + 1] = "波澜不惊"
			self.参战单位[目标].法术状态.波澜不惊.层数 = self.参战单位[目标].法术状态.波澜不惊.层数 - 1
		end

		self.战斗流程[精准战斗流程].挨打方[执行数].护盾掉血值 = nil

		if (伤害类型 == 1 or 伤害类型 == 3 or 伤害类型 == 4) and self.参战单位[目标].法术状态.护盾 ~= nil and self.参战单位[目标].法术状态.护盾.护盾值 ~= nil then
			if 伤害 < self.参战单位[目标].法术状态.护盾.护盾值 then
				self.参战单位[目标].法术状态.护盾.护盾值 = self.参战单位[目标].法术状态.护盾.护盾值 - 伤害
				self.战斗流程[精准战斗流程].挨打方[执行数].护盾掉血值 = 伤害
				伤害 = 0
			else
				self.战斗流程[精准战斗流程].挨打方[执行数].护盾掉血值 = self.参战单位[目标].法术状态.护盾.护盾值
				伤害 = 伤害 - self.参战单位[目标].法术状态.护盾.护盾值

				self:取消状态("护盾", self.参战单位[目标])

				self.战斗流程[精准战斗流程].挨打方[执行数].取消状态 = "护盾"
			end
		end

		self.战斗流程[精准战斗流程].挨打方[执行数].类型 = 伤害类型
		self.战斗流程[精准战斗流程].挨打方[执行数].伤害 = 伤害

		if 执行数 == 1 and 名称 == "雷浪穿云" then
			self:添加状态("雷浪穿云", self.参战单位[目标])

			self.参战单位[目标].法术状态.雷浪穿云.受到法术伤害 = 30
		end

		if 伤害类型 == 2 then
			self:增加气血(目标, 伤害)
		else
			self.凝光炼彩护盾 = true

			if 名称 == "龙腾" and self:取奇经八脉是否有(编号, "清吟") and (self.参战单位[目标].气血 < self.参战单位[目标].最大气血 * 0.3 or self.参战单位[目标].魔法 < self.参战单位[目标].最大魔法 * 0.3) then
				self:添加状态("清吟", self.参战单位[目标])

				self.参战单位[目标].法术状态.清吟.受到法术伤害 = 15
			end

			self.战斗流程[精准战斗流程].挨打方[执行数].死亡 = self:减少气血(目标, 伤害, 编号, 名称, nil, nil, 1)

			if 名称 == "飞砂走石" and qz(self.天气) == 1 and self:取奇经八脉是否有(编号, "吹牛") and self.参战单位[编号].被动技能.牛逼神功 ~= nil then
				self.战斗流程[精准战斗流程].挨打方[执行数].伤害 = 伤害 + self.参战单位[编号].被动技能.牛逼神功 * 10
			elseif 名称 == "尘土刃" and self.参战单位[目标].气血上限 ~= nil and self.参战单位[目标].类型 ~= "bb" then
				伤势 = qz(伤害 * 0.5)
				伤势类型 = 1

				if self.参战单位[编号].苍埃 then
					伤势 = qz(伤势 + 伤害 * 0.5)
				end
			end

			if 名称 == "龙腾" then
				if self:取奇经八脉是否有(编号, "凛然") and self.战斗流程[精准战斗流程].挨打方[执行数].死亡 ~= nil then
					self:添加状态("龍骇", self.参战单位[编号])

					self.参战单位[编号].法术状态.龍骇.层数 = math.min((self.参战单位[编号].法术状态.龍骇.层数 or 0) + 3, 龍骇最高层数)
				end

				if self:取奇经八脉是否有(编号, "摧意") and 伤害 >= self.参战单位[目标].最大气血 * 0.08 then
					self:减少魔法(目标, 300)
				end

				if self:取奇经八脉是否有(编号, "龙啸") and ygsj() <= 20 then
					self:添加状态("龙啸", self.参战单位[目标])

					self.参战单位[目标].法术状态.龙啸.受到法术伤害 = 15
				end

				if self:取奇经八脉是否有(编号, "沐雨") and self.参战单位[目标].魔法 == 0 then
					local 可取消状态 = self:驱散目标状态(目标, 编号)
					self.战斗流程[精准战斗流程].挨打方[执行数].取消状态 = 可取消状态
				end
			end

			if 目标 ~= nil and self:取奇经八脉是否有(目标, "飞龙") and 伤害 >= self.参战单位[目标].最大气血 * 0.2 and ygsj() <= 75 then
				self:添加状态("神龙摆尾", self.参战单位[目标], self.参战单位[目标], 等级, 目标)

				附加状态 = "神龙摆尾"
			end

			if self.参战单位[目标].法术状态.催眠符 and 伤害 > (self.参战单位[目标].法术状态.催眠符.黄粱 or 0) then
				self:取消状态("催眠符", self.参战单位[目标])

				self.战斗流程[精准战斗流程].挨打方[执行数].取消状态 = "催眠符"
			end
		end

		if 伤害类型 ~= 2 and 伤害 > 0 then
			if 法爆成功 and 伤害类型 ~= 2 then
				self.战斗流程[精准战斗流程].挨打方[执行数].特效[2] = "法暴"
				self.战斗流程[精准战斗流程].挨打方[执行数].类型 = 3
			end

			if 伤势 ~= nil then
				if 伤势类型 == 1 then
					self:造成伤势(目标, 伤势)
				elseif 伤势类型 == 2 then
					self:恢复伤势(目标, 伤势)
				end
			end

			if 目标 ~= nil and self:取奇经八脉是否有(目标, "养生") and self.参战单位[目标].气血 <= qz(self.参战单位[目标].最大气血 * 0.7) and self.参战单位[目标].法术状态.生命之泉 == nil then
				self:添加状态("生命之泉", self.参战单位[目标], self.参战单位[目标], self.参战单位[目标].等级, 目标)

				self.战斗流程[精准战斗流程].挨打方[执行数].状态 = "生命之泉"
			end

			if self.参战单位[编号].法术状态.诡蝠之刑 ~= nil and self:取目标状态(编号, 编号, 2) then
				local 气血 = qz(伤害 * 0.1)

				if 气血 <= 1 then
					气血 = 1
				end

				self.战斗流程[#self.战斗流程 + 1] = {
					气血 = 0,
					流程 = 102,
					攻击方 = 编号,
					挨打方 = {}
				}
				local 精准战斗流程1 = #self.战斗流程 + 0
				self.战斗流程[精准战斗流程1].死亡 = self:减少气血(编号, 气血, nil, nil, nil, nil, 1)
				self.战斗流程[精准战斗流程1].气血 = 气血
			end
		end
	else
		self.战斗流程[精准战斗流程].挨打方[执行数].类型 = 2
		self.战斗流程[精准战斗流程].挨打方[执行数].伤害 = 0
		self.战斗流程[精准战斗流程].挨打方[执行数].躲避 = true
		self.战斗流程[精准战斗流程].挨打方[执行数].特效[1] = 名称
		self.战斗流程[精准战斗流程].不施法 = self.不施法

		if 执行数 == 目标数 then
			if 流程200[名称] ~= nil then
				self.战斗流程[精准战斗流程].流程 = 200
			elseif 流程205[名称] ~= nil then
				self.战斗流程[精准战斗流程].流程 = 205
			end
		end
	end

	if self.法术吸血流程[精准流程] ~= nil and self.法术吸血流程[精准流程].执行 == 执行数 then
		local 吸血伤害 = qz(self.法术吸血流程[精准流程].伤害值 * self.法术吸血流程[精准流程].比例)

		if 吸血伤害 > 0 then
			if 名称 == "饕餮盛宴·觉醒" and self.参战单位[编号].最大气血 < self.参战单位[编号].气血 + 吸血伤害 then
				local hd = self.参战单位[编号].气血 + 吸血伤害 - self.参战单位[编号].最大气血
				hd = self:添加护盾(编号, hd, 编号)

				if hd > 0 then
					self:添加战斗流程提示("#P(饕餮盛宴·觉醒)#R" .. self.参战单位[编号].名称 .. "#W将溢出的吸收气血转化为#R" .. hd .. "点护盾")
				end
			end

			self:增加气血(编号, 吸血伤害)

			self.战斗流程[精准流程].法术吸血 = 吸血伤害
		end

		self.法术吸血流程[精准流程] = nil
	end

	if 名称 == "笑里藏刀" then
		self:增加愤怒(目标, -70)
	elseif 名称 == "绝幻魔音" then
		self:增加愤怒(目标, -20)
	end

	if 名称 == "琴音三叠" and self:取目标状态(编号, 目标, 1) == true then
		self.不施法 = true

		self:法攻技能计算(编号, "琴音三叠2", self.参战单位[编号].等级, 1, nil)

		if self:取目标状态(编号, 目标, 1) == true then
			self:法攻技能计算(编号, "琴音三叠3", self.参战单位[编号].等级, 1, nil)
		end

		self.不施法 = false
	end
end

function 战斗处理类:取五行克制(攻击, 挨打)
	if 挨打 == "木" and 攻击 == "金" then
		return true
	elseif 挨打 == "土" and 攻击 == "木" then
		return true
	elseif 挨打 == "水" and 攻击 == "土" then
		return true
	elseif 挨打 == "火" and 攻击 == "水" then
		return true
	elseif 挨打 == "金" and 攻击 == "火" then
		return true
	end

	return false
end

function 战斗处理类:增益技能计算(编号, 名称, 等级, 附加, 消耗, 指定, 境界)
	local 目标 = self.参战单位[编号].指令.目标
	local 后发目标 = nil
	local 法爆 = 0
	local 法爆几率 = self.参战单位[编号].法术暴击等级 * 0.1

	if self:取敌方是否全部死亡(编号) == true then
		return
	end

	if 指定 ~= nil or 法术只给自己列表[名称] ~= nil then
		目标 = 编号
	elseif 名称 == "佛法无边" and self:取奇经八脉是否有(编号, "慧定") then
		目标 = 编号
	elseif 名称 == "蜜润" and self:取奇经八脉是否有(编号, "滋润") then
		目标 = 编号
	end

	if self.参战单位[编号].聚气 ~= nil and self.参战单位[编号].聚气[名称] ~= nil then
		local gl = 15

		if self:取奇经八脉是否有(编号, "磅礴") then
			gl = 60
		end

		if ygsj() <= gl then
			local 加成 = 0.3

			if self:取奇经八脉是否有(编号, "聚念") then
				加成 = 0.8
			end

			self.参战单位[编号].聚气加成 = 1 + 加成
		end
	end

	if 名称 == "后发制人" then
		后发目标 = 目标
	end

	local 目标数 = self:取目标数量(self.参战单位[编号], 名称, 等级, 编号)

	if self.回合进程 == "加载回合" then
		目标数 = 1
	elseif 名称 == "韦陀护法" and self:取奇经八脉是否有(编号, "无碍") then
		目标数 = 1
	end

	if 名称 == "河东狮吼" or 名称 == "放下屠刀" or 名称 == "破甲术" or 名称 == "碎甲术" or 名称 == "知己知彼" or 名称 == "凝滞术" or 名称 == "停陷术" or 名称 == "魂飞魄散" or 名称 == "瘴气" then
		目标 = self:取多个敌方目标(编号, 目标, 目标数)
	else
		目标 = self:取多个友方目标(编号, 目标, 目标数, 名称)
	end

	local fbsx = {}
	local 主动群体法宝 = false

	if 名称 == "九梵清莲" then
		目标 = self:取全体敌友方目标(编号, nil, nil, "角色")
		fbsx = {
			类型 = 1,
			回合 = 2,
			说明 = 境界 * 1.5 + 13
		}
		主动群体法宝 = true
	elseif 名称 == "苍灵雪羽" then
		目标 = self:取全体敌友方目标(编号)
		fbsx = {
			类型 = 2,
			回合 = 1,
			造成法术伤害 = 境界 * 0.5 + 1,
			受到法术伤害 = 境界 * 0.5 + 2.4
		}
		主动群体法宝 = true
	elseif 名称 == "烽火狼烟" then
		目标 = self:取全体敌友方目标(编号)
		fbsx = {
			类型 = 2,
			回合 = 1,
			造成物理伤害 = 境界 * 0.5 + 1,
			受到物理伤害 = 境界 * 0.5 + 2.4
		}
		主动群体法宝 = true
	elseif 名称 == "璞玉灵钵" then
		目标 = self:取全体敌友方目标(编号)
		fbsx = {
			类型 = 1,
			回合 = 1,
			说明 = 境界 * 0.5 + 11
		}
		主动群体法宝 = true
	end

	if 主动群体法宝 then
		self.参战单位[编号].出手 = 1
		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 53,
			不施法 = self.不施法,
			攻击方 = 编号,
			挨打方 = {},
			提示 = {
				类型 = "法术",
				允许 = true,
				名称 = "【法宝】" .. self.参战单位[编号].名称 .. "使用了" .. 名称
			}
		}
		local 精准战斗流程 = #self.战斗流程 + 0
		self.执行等待 = self.执行等待 + 10

		for n = 1, #目标 do
			self.战斗流程[精准战斗流程].挨打方[n] = {
				挨打方 = 目标[n],
				特效 = {
					名称
				}
			}

			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)

			for i, v in pairs(fbsx) do
				self.参战单位[目标[n]].法术状态[名称][i] = v
			end
		end

		self:施法统一计算(编号, 名称)

		return
	end

	if 名称 == "魍魉追魂" then
		local mb = self.参战单位[编号].指令.目标

		if self.参战单位[mb].死亡状态 ~= 2 then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#P(魍魉追魂)#R" .. self.参战单位[mb].名称 .. "#Y未倒地,技能使用失败")

			return
		else
			目标 = {
				mb + 0
			}
		end
	end

	if #目标 == 0 then
		return
	end

	目标数 = #目标

	if 名称 == "超级永恒" then
		self.参战单位[编号].超级永恒记录 = {
			气血 = self.参战单位[编号].气血 + 0,
			魔法 = self.参战单位[编号].魔法 + 0
		}

		self:添加战斗流程提示("#P(超级永恒)#R" .. self.参战单位[编号].名称 .. "#W本回合结束后、气血魔法将恢复至#Y当前状态")
	elseif (名称 == "碎星诀" or 名称 == "镇魂诀") and self.参战单位[编号].战意 >= 0 and 目标[1] == 编号 and self:取奇经八脉是否有(编号, "战诀") then
		self:刷新战意(编号, 1)
	elseif 名称 == "天眼神通" then
		if (self.参战单位[编号].战意 or 0) < 1 then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/你的战意不足#R1#Y点、技能使用失败。")

			return
		end
	elseif 名称 == "天魔解体" then
		if self.参战单位[编号].气血 <= self.参战单位[编号].最大气血 * 0.1 then
			return
		else
			结尾气血 = qz(self.参战单位[编号].最大气血 * 0.1)

			self:减少气血(编号, 结尾气血)
		end
	elseif 昼夜参数 == 1 and 名称 == "修罗隐身" and self.参战单位[编号].类型 ~= "bb" then
		常规提示(self.参战单位[编号].玩家id, "#Y/修罗隐身只能白天使用！")

		return
	end

	if 消耗 == nil and 名称 ~= "炎魂" and self:技能消耗(self.参战单位[编号], 目标数, 名称, 编号) == false then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "未到达技能消耗要求,技能使用失败")

		if 技能冷却列表[名称] ~= nil then
			self.参战单位[编号][名称] = 0
		end

		return
	end

	if 名称 == "天眼神通" then
		self:刷新战意(编号, -1, 名称)
		self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/当前剩余战意#R" .. self.参战单位[编号].战意 .. "#Y点。")
	end

	self:施法统一计算(编号, 名称)

	self.参战单位[编号].出手 = 1
	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 53,
		不施法 = self.不施法,
		攻击方 = 编号,
		挨打方 = {},
		提示 = {
			类型 = "法术",
			允许 = true,
			名称 = self.参战单位[编号].名称 .. "使用了" .. 名称
		}
	}
	local 精准战斗流程 = #self.战斗流程 + 0
	self.执行等待 = self.执行等待 + 10

	for n = 1, 目标数 do
		self.战斗流程[精准战斗流程].挨打方[n] = {
			挨打方 = 目标[n],
			特效 = {
				名称
			}
		}

		if 名称 == "后发制人" then
			self:添加状态(名称, self.参战单位[编号], self.参战单位[编号], 等级, 编号)

			self.参战单位[编号].法术状态.后发制人.目标 = 后发目标
			self.战斗流程[精准战斗流程].挨打方[n].挨打方 = 编号
		elseif 名称 == "炎护" then
			self:添加状态(名称, self.参战单位[编号], self.参战单位[编号], 等级, 编号)

			self.战斗流程[精准战斗流程].挨打方[n].挨打方 = 编号
		elseif 名称 == "杀气诀" then
			if 编号 ~= nil and self:取奇经八脉是否有(编号, "风刃") then
				local 状态 = "风魂"

				if self.参战单位[编号].门派 == "大唐官府" then
					self:添加状态(状态, self.参战单位[目标[n]], self.参战单位[编号], 等级 + 10, 编号)
					self:添加状态("杀气诀", self.参战单位[目标[n]], self.参战单位[编号], 等级 + 10, 编号)
				end
			end

			self:添加状态("杀气诀", self.参战单位[目标[n]], self.参战单位[编号], 等级 + 10, 编号)
		elseif 名称 == "钟馗论道" then
			self:添加状态(名称, self.参战单位[编号], self.参战单位[编号], 等级, 编号)

			结尾气血 = self.参战单位[目标[n]].气血 - 1

			self:减少气血(目标[n], 结尾气血)

			self.战斗流程[精准战斗流程].结尾气血 = 结尾气血
		elseif 名称 == "燃血术·妙谛金莲" then
			local 使用成功 = false

			if self.参战单位[目标[n]].法术状态[名称] == nil then
				self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)

				使用成功 = true
			elseif self:取奇经八脉是否有(编号, "血潮", "妙谛金莲") then
				self:取消状态(名称, self.参战单位[目标[n]])
				self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)

				使用成功 = true
			end

			if 使用成功 then
				local hp = qz(self.参战单位[编号].最大气血 * 0.1)

				if self:取奇经八脉是否有(编号, "血潮", "妙谛金莲") then
					hp = qz(self.参战单位[编号].最大气血 * 0.2)
				end

				self:减少气血(编号, hp)
				self:造成伤势(编号, hp)
			end
		elseif 名称 == "燃血术·摄魂迷影" then
			if self:取奇经八脉是否有(编号, "血潮", "摄魂迷影") then
				self:添加状态("血潮", self.参战单位[编号], self.参战单位[编号], 等级, 编号)
			end

			if self.参战单位[目标[n]].法术状态[名称] == nil then
				self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)

				local hp = qz(self.参战单位[编号].最大气血 * 0.1)

				self:减少气血(编号, hp)
				self:造成伤势(编号, hp)
			end
		elseif 名称 == "燃血术·幽冥巫煞" then
			local 使用成功 = false

			if self.参战单位[目标[n]].法术状态[名称] == nil then
				self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)

				使用成功 = true
			elseif self:取奇经八脉是否有(编号, "血潮", "幽冥巫煞") and self.参战单位[目标[n]].法术状态[名称].层数 < 2 then
				self.参战单位[目标[n]].法术状态[名称].层数 = self.参战单位[目标[n]].法术状态[名称].层数 + 1
				使用成功 = true
			end

			if 使用成功 then
				if self:取奇经八脉是否有(编号, "盛怒", "幽冥巫煞") then
					self:增加愤怒(编号, 20)
				else
					local hp = qz(self.参战单位[编号].最大气血 * 0.1)

					self:减少气血(编号, hp)
					self:造成伤势(编号, hp)
				end

				if self:取奇经八脉是否有(编号, "夺血", "幽冥巫煞") then
					self.参战单位[编号].固定伤害 = self.参战单位[编号].固定伤害 + 8
				end
			end
		elseif 名称 == "天眼神通" then
			self:取消状态(名称, self.参战单位[编号])
			self:添加状态(名称, self.参战单位[编号], self.参战单位[编号], 等级, 编号)
		elseif 名称 == "天魔解体" then
			self:添加状态(名称, self.参战单位[编号], self.参战单位[编号], 等级, 编号)

			self.战斗流程[精准战斗流程].结尾气血 = 结尾气血
		elseif 名称 == "其疾如风" then
			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)

			self.战斗流程[精准战斗流程].流程 = 153
		elseif 名称 == "不动如山 " then
			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)

			self.战斗流程[精准战斗流程].流程 = 153
		elseif 名称 == "侵掠如火" then
			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)

			self.战斗流程[精准战斗流程].流程 = 153
		elseif 名称 == "知己知彼" then
			if 编号 ~= nil and self:取奇经八脉是否有(编号, "洞察", {
					踏雷天尊 = 1,
					镇妖神使 = 1
				}) then
				self:取消状态("洞察", self.参战单位[编号])
				self:添加状态("洞察", self.参战单位[编号], self.参战单位[编号], self.参战单位[编号].等级 * 2, 编号)
			end

			if 编号 ~= nil and self.参战单位[编号].霹雳洞察 ~= nil then
				self.参战单位[编号].霹雳洞察[目标[n]] = 1
			end

			local 获取名称 = self.参战单位[目标[n]].名称
			local 获取气血值 = self.参战单位[目标[n]].气血 or 0
			local 获取最大气血值 = self.参战单位[目标[n]].最大气血 or 0
			local 获取魔法值 = self.参战单位[目标[n]].魔法 or 0
			local 获取最大魔法值 = self.参战单位[目标[n]].最大魔法 or 0
			local 获取目标愤怒 = self.参战单位[目标[n]].愤怒 or 0
			local 获取目标类型 = self.参战单位[目标[n]].类型 or 0
			local 获取目标伤害 = self.参战单位[目标[n]].伤害 or 0
			local 获取目标法伤 = self.参战单位[目标[n]].法伤 or 0
			local 获取目标防御 = self.参战单位[目标[n]].防御 or 0
			local 获取目标灵力 = self.参战单位[目标[n]].灵力 or 0
			local 获取目标法防 = self.参战单位[目标[n]].法防 or 0
			local 获取目标速度 = self.参战单位[目标[n]].速度 or 0
			local 获取目标躲避 = self.参战单位[目标[n]].躲避 or 0

			self:添加提示2(self.参战单位[编号].玩家id, 编号, {
				内容 = format([=[
#Y/使用技能#R/[知己知彼]#Y/获取到对方信息如下
 #Y/名称:[%s]
 #Y/气血值:[%s/%s]
 #Y/魔法值:[%s/%s]
 #Y/愤怒:[%s]
 #Y/类型:[%s]
 #Y/攻/防:[%s/%s]
 #Y/灵力:[%s]
 #Y/法攻/法防:[%s/%s]
 #Y/速度:[%s]
 #Y/躲避:[%s]]=], 获取名称, 获取气血值, 获取最大气血值, 获取魔法值, 获取最大魔法值, 获取目标愤怒, 获取目标类型, 获取目标伤害, 获取目标防御, 获取目标灵力, 获取目标法伤, 获取目标法防, 获取目标速度,
					获取目标躲避)
			})
		elseif 名称 == "魂飞魄散" then
			local cs = 1

			if n == 1 and self:取奇经八脉是否有(编号, "魂飞") then
				self.参战单位[目标[n]].魂飞 = 编号 + 0
			end

			if self:取奇经八脉是否有(编号, "扼命") and self:取封印状态(目标[n]) then
				cs = cs + 3
			end

			for i = 1, cs do
				self:驱散目标状态1(目标[n], 编号)
			end
		elseif 名称 == "同舟共济" then
			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)
		elseif 名称 == "金刚怒目" then
			self:增加愤怒(目标[n], 80)
		elseif 名称 == "牺牲·菩提心佑" then
			self:添加护盾(目标[n], self.参战单位[编号].等级 * 30, 编号, 1)
		elseif 名称 == "菩提心佑" then
			self:添加护盾(目标[n], self.参战单位[编号].等级 * 15, 编号, 1)
		elseif 名称 == "镜之阳" then
			local hd = self:添加护盾(目标[n], self.参战单位[编号].等级 * 30, 编号, 1)

			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, hd)
		elseif 名称 == "镜之阴" then
			local hd = self:添加护盾(目标[n], self.参战单位[编号].等级 * 15, 编号, 1)

			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, hd)
		elseif 名称 == "句芒光环" then
			local aa = nil

			if self:取是否有指定状态(编号, 目标[n], "句芒光环") then
				aa = self.参战单位[目标[n]].法术状态.句芒光环.光环 + 0

				self:取消状态("句芒光环", self.参战单位[目标[n]])
			end

			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[目标[n]], 等级, 编号, aa)
		elseif 名称 == "铜头铁臂" then
			local hd = self:添加护盾(目标[n], math.min(self.参战单位[编号].等级 * 15, qz(self.参战单位[编号].最大气血 / 3)), 编号, 1)

			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, hd)
		elseif 名称 == "无所遁形" then
			if self:刷新无所遁形(编号, 等级) == true then
				self:客户端添加状态(编号, "无所遁形")
			end
		elseif 名称 == "诸天看护" then
			local 层数 = 1

			if self.参战单位[目标[n]].法术状态.诸天看护 ~= nil then
				层数 = 1 + self.参战单位[目标[n]].法术状态.诸天看护.层数

				self:取消状态("诸天看护", self.参战单位[目标[n]])
			end

			if self.参战单位[目标[n]].法术状态.金刚护法 ~= nil and self.参战单位[目标[n]].法术状态.金刚护法.攻击编号 == 编号 then
				self:取消状态("金刚护法", self.参战单位[目标[n]])

				层数 = 层数 + 1
			end

			if self.参战单位[目标[n]].法术状态.金刚护体 ~= nil and self.参战单位[目标[n]].法术状态.金刚护体.攻击编号 == 编号 then
				self:取消状态("金刚护体", self.参战单位[目标[n]])

				层数 = 层数 + 1
			end

			if self.参战单位[目标[n]].法术状态.一苇渡江 ~= nil and self.参战单位[目标[n]].法术状态.一苇渡江.攻击编号 == 编号 then
				self:取消状态("一苇渡江", self.参战单位[目标[n]])

				层数 = 层数 + 1
			end

			if 层数 > 20 then
				层数 = 20
			end

			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 层数, 编号, 境界)
			self:更新单个法术状态(目标[n], "诸天看护")
		elseif 名称 == "烈焰真诀" then
			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)
		elseif 名称 == "无畏布施" then
			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)
			self:添加状态("无畏布施1", self.参战单位[编号], self.参战单位[编号], 等级, 编号, 境界)
		elseif 名称 == "炼气化神" then
			if self:取奇经八脉是否有(编号, "行气") and 目标[1] == 编号 then
				self.参战单位[编号].行气 = 1
			end

			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)
		elseif 名称 == "心随意动" then
			if self.参战单位[目标[n]].法术状态.心随意动 ~= nil then
				self:取消状态(名称, self.参战单位[目标[n]])
				self:添加战斗流程提示("#P(心随意动)#R" .. self.参战单位[目标[n]].名称 .. "#W关闭了#S" .. 名称)
			else
				self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)
				self:添加战斗流程提示("#P(心随意动)#R" .. self.参战单位[目标[n]].名称 .. "#W开启了#S" .. 名称)
			end
		elseif 名称 == "天雷灌注" then
			local cs = 1

			if self.参战单位[目标[n]].雷吞 ~= nil then
				cs = cs + self.参战单位[目标[n]].雷吞
			end

			if self.参战单位[目标[n]].法术状态.天雷灌注 == nil then
				self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)

				self.参战单位[目标[n]].法术状态.天雷灌注.层数 = cs
			else
				self.参战单位[目标[n]].法术状态.天雷灌注.回合 = 999

				if self:取奇经八脉是否有(目标[n], "天劫") then
					self.参战单位[目标[n]].法术状态.天雷灌注.层数 = math.min(self.参战单位[目标[n]].法术状态.天雷灌注.层数 + cs, 3)
				else
					self.参战单位[目标[n]].法术状态.天雷灌注.层数 = cs
				end
			end

			if self.参战单位[编号].经脉流派 == "霹雳真君" then
				self.参战单位[目标[n]].法术状态.天雷灌注.霹雳真君 = 1
				self.参战单位[目标[n]].法术状态.天雷灌注.说明1 = "强化下一个技能【风雷斩·霹雳有几率额外攻击一次；风雷斩·飞霆额外攻击3个单位】"
			else
				self.参战单位[目标[n]].法术状态.天雷灌注.说明1 = "强化下一个雷霆万钧技能"
			end
		elseif 名称 == "霹雳弦惊" or 名称 == "雷怒霆激" then
			self:取消状态("雷怒霆激", self.参战单位[目标[n]])
			self:取消状态("霹雳弦惊", self.参战单位[目标[n]])
			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 3447)

			if self.参战单位[编号].啸傲 ~= nil and self.参战单位[编号].啸傲 < 20 then
				self.参战单位[编号].啸傲 = self.参战单位[编号].啸傲 + 1
				self.参战单位[编号].伤害 = self.参战单位[编号].伤害 + 15
			end
		elseif 名称 == "五雷·挪移" then
			self:添加状态("雷法真身", self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)

			self.战斗流程[精准战斗流程].挨打方[n].特效 = {
				"雷法真身"
			}
		elseif 名称 == "韦陀护法" then
			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)

			if self:取奇经八脉是否有(编号, "感念", "护法金刚") and self.参战单位[目标[n]].法术状态.韦陀护法.攻击编号 == 编号 then
				self.参战单位[目标[n]].法术状态.韦陀护法.回合 = 1
			end
		elseif 名称 == "烈火真言" then
			local aa = {
				名称 = "",
				等级 = 0,
				替换 = "",
				位置 = 0
			}

			for i = 1, #self.参战单位[目标[n]].主动技能 do
				if self.参战单位[目标[n]].主动技能[i].名称 == "秘传三昧真火" or self.参战单位[目标[n]].主动技能[i].名称 == "秘传飞砂走石" then
					aa.名称 = self.参战单位[目标[n]].主动技能[i].名称 .. ""
					aa.等级 = self.参战单位[目标[n]].主动技能[i].等级 + 0
					aa.位置 = i + 0

					if self.参战单位[目标[n]].主动技能[i].名称 == "秘传飞砂走石" then
						aa.替换 = "秘传三昧真火"

						break
					end

					aa.替换 = "秘传飞砂走石"

					break
				end
			end

			if aa.位置 ~= 0 then
				table.remove(self.参战单位[目标[n]].主动技能, aa.位置)
				self:添加主动技能(self.参战单位[目标[n]], aa.替换, aa.等级)
				self:添加战斗流程提示("#P(烈火真言)#R" .. self.参战单位[目标[n]].名称 .. "#W将#S" .. aa.名称 .. "#W切换为了#Y" .. aa.替换)

				self.参战单位[目标[n]][aa.名称] = nil
				self.参战单位[编号][aa.替换] = 技能冷却列表[aa.替换]

				发送数据(玩家数据[self.参战单位[目标[n]].玩家id].连接id, 5518, {
					id = 目标[n],
					主动技能 = self.参战单位[目标[n]].主动技能
				})
			end
		elseif 名称 == "金蟾" then
			if 编号 ~= nil and self:取奇经八脉是否有(编号, "风墙") then
				local 气血 = qz(self.参战单位[编号].气血 * 0.5)
				local 护盾 = math.min(qz(气血 * (境界 * 4 + 1) / 100), self.参战单位[编号].等级 * 16)
				local bb = {}
				bb[#bb + 1] = {
					气血类型 = 1,
					挨打方 = 编号,
					气血 = 气血
				}

				self:流程处理气血魔法(编号, bb)
				self:减少气血(编号, 气血)

				local 目标组 = self:取全体敌友方目标(编号, nil, 1)

				if 目标组 ~= 0 and not 判断是否为空表(目标组) then
					for i = 1, #目标组 do
						if self.参战单位[目标组[i]].召唤物 == nil then
							local hd = self:添加护盾(目标组[i], 护盾, 编号, 1)
						end
					end
				end

				self:添加战斗流程提示("#P(风墙)#W#R" .. self.参战单位[编号].名称 .. "#W为队友附加了#R" .. 护盾 .. "点护盾", 流程)
			end

			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)
		else
			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号, 境界)
		end

		if 名称 == "生命之泉" then
			local 气血 = 0
			气血 = 等级 * 0.5 + math.max(self.参战单位[编号].灵力, self.参战单位[编号].法伤) * 0.1

			if 编号 ~= nil and self:取奇经八脉是否有(编号, "体恤") and self.参战单位[目标[n]].气血 <= qz(self.参战单位[目标[n]].最大气血 * 0.3) then
				气血 = 气血 + 150
			end

			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			if self:取奇经八脉是否有(编号, "运转") then
				气血 = qz(气血 * 1.3)
			end

			self:增加气血(目标[n], 气血)

			self.战斗流程[精准战斗流程].挨打方[n].恢复气血 = 气血
		elseif 名称 == "煞气诀1" then
			local 气血 = 0
			气血 = 等级 + 15
			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			self:增加气血(目标[n], 气血)

			self.战斗流程[精准战斗流程].挨打方[n].恢复气血 = 气血
		elseif 名称 == "普渡众生" then
			local 气血 = 0
			气血 = 等级 * 4 + self.参战单位[编号].灵力 * 0.1

			if self.参战单位[编号].气血 <= self.参战单位[编号].最大气血 * 0.3 and self:取奇经八脉是否有(编号, "劳心") then
				气血 = 气血 * 2
			end

			if ygsj() <= self.参战单位[编号].法暴 + 法爆几率 then
				气血 = qz(气血 * self.参战单位[编号].治疗暴伤)
				self.战斗流程[精准战斗流程].挨打方[n].特效[2] = "法暴"
				self.战斗流程[精准战斗流程].挨打方[n].伤害类型 = 5
			end

			气血 = self:取恢复气血(编号, 目标[n], 气血, 名称, n)

			self:恢复伤势(目标[n], 气血)
			self:增加气血(目标[n], 气血)

			self.战斗流程[精准战斗流程].挨打方[n].恢复气血 = 气血
			self.战斗流程[精准战斗流程].挨打方[n].恢复伤势 = 气血
			self.战斗流程[精准战斗流程].挨打方[n].伤势类型 = 2
		elseif 名称 == "炼气化神" then
			气血 = 30
			self.参战单位[编号].气血 = self.参战单位[编号].气血 - 气血
			self.战斗流程[精准战斗流程].扣除气血 = 气血

			self:增加魔法(目标[n], qz(等级 / 2))
		elseif 名称 == "达摩护体" then
			气血 = self.参战单位[目标[n]].等级 * 2.5 + math.max(self.参战单位[目标[n]].灵力, self.参战单位[目标[n]].法伤) * 0.2

			self:恢复伤势(目标[n], 气血)
			self:增加气血(目标[n], 气血)

			self.战斗流程[精准战斗流程].挨打方[n].恢复气血 = 气血
		elseif 名称 == "魔息术" then
			if 编号 ~= nil and self:取奇经八脉是否有(编号, "魔息") then
				self:增加魔法(目标[n], qz(等级 / 2) * 1.5)
			else
				self:增加魔法(目标[n], qz(等级 / 2))
			end
		elseif 名称 == "牛劲" then
			if 编号 ~= nil and self:取奇经八脉是否有(编号, "充沛") then
				self.参战单位[目标[n]].牛劲感知 = 1
			end
		elseif 名称 == "铸兵锤" then
			if self.参战单位[编号].法术状态.怒哮 == nil then
				self:添加状态("怒哮", self.参战单位[编号])
			end
		elseif 名称 == "天煞" then
			self:增加魔法(目标[n], qz(50 + self.参战单位[目标[n]].等级 * (0.6 + 境界 * 0.2)))
		elseif 名称 == "赤焰" then
			local 魔法 = qz(80 + self.参战单位[目标[n]].等级 * (0.6 + 境界 * 0.25))

			self:增加魔法(目标[n], 魔法)

			if self:取奇经八脉是否有(目标[n], "赤暖") then
				local 气血 = 魔法 * 2
				self.战斗流程[精准战斗流程].挨打方[n].恢复气血 = self:增加气血(目标[n], 气血)
			end
		end
	end

	if self.不走流程 == true then
		table.remove(self.战斗流程, 精准战斗流程)
	end
end

function 战斗处理类:负面技能施加判断(目标, 状态名称, 编号)
	if 状态名称 == "象形" or 状态名称 == "冰川怒" or 状态名称 == "冰川怒伤" then
		return true
	elseif self.参战单位[目标].超级神迹 ~= nil then
		return false
	elseif self.参战单位[目标].鬼魂 ~= nil and (not self:封印技能(状态名称) or self.参战单位[目标].鬼念 == nil) or self.参战单位[目标].信仰 ~= nil then
		return false
	elseif self.参战单位[目标].神迹 == 2 and 状态名称 ~= "日月乾坤" then
		return false
	elseif self.参战单位[目标].精神 ~= nil and (self:封印技能(状态名称) or self:群体封印技能(状态名称)) then
		return false
	end

	if 毒状态列表1[状态名称] ~= nil and self.参战单位[目标].高级毒 ~= nil then
		if 编号 ~= nil and self:取奇经八脉是否有(编号, "杏花") and ygsj() >= 50 then
			return true
		elseif 状态名称 == "尸腐毒" and 编号 ~= nil and self:取奇经八脉是否有(编号, "冥毒") then
			return true
		end

		return false
	end

	return true
end

function 战斗处理类:减益技能计算(编号, 名称, 等级, 类型, 消耗, 境界)
	local 目标 = self.参战单位[编号].指令.目标

	if self:取敌方是否全部死亡(编号) == true then
		return
	end

	if 目标 == 0 then
		目标 = self:取单个敌方目标(编号)
	elseif self:取目标状态(编号, 目标, 1) == false then
		if not self:取奇经八脉是否有(编号, "拘魄") or self.参战单位[目标].死亡状态 ~= 2 then
			目标 = self:取单个敌方目标(编号)
		end
	elseif self.参战单位[编号].指令.取消 then
		return
	end

	if 目标 == 0 then
		return
	elseif 名称 ~= "尸腐毒" and 法宝列表1[名称] == nil and not self:负面技能施加判断(目标, 名称, 编号) then
		self:添加提示(self.参战单位[编号].玩家id, 编号, self.参战单位[目标].名称 .. "可能有鬼魂、否定信仰、高级神迹，免疫负面状态,技能使用失败")

		return
	elseif 名称 ~= "尸腐毒" and self.参战单位[目标].法术状态[名称] ~= nil then
		return
	end

	if self.参战单位[目标].法术状态.分身术 ~= nil and self.参战单位[目标].法术状态.分身术.破解 == nil then
		self.参战单位[目标].法术状态.分身术.破解 = 1
		self.参战单位[编号].出手 = 1

		self:添加战斗流程提示("#P(分身术)#R" .. self.参战单位[编号].名称 .. "#W的法术被#R" .. self.参战单位[目标].名称 .. "#W的#Y分身术#W躲过去了！")

		return
	end

	if 消耗 == nil and self:技能消耗(self.参战单位[编号], 1, 名称, 编号) == false then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "未到达技能消耗要求,技能使用失败")

		if 技能冷却列表[名称] ~= nil then
			self.参战单位[编号][名称] = 0
		end

		return
	end

	self:施法统一计算(编号, 名称)

	self.参战单位[编号].出手 = 1
	self.执行等待 = self.执行等待 + 10
	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 56,
		攻击方 = 编号,
		挨打方 = {},
		提示 = {
			类型 = "法术",
			允许 = true,
			名称 = self.参战单位[编号].名称 .. "使用了" .. 名称
		}
	}
	local 精准战斗流程 = #self.战斗流程 + 0
	self.战斗流程[精准战斗流程].挨打方[1] = {
		挨打方 = 目标,
		特效 = {
			名称
		}
	}

	if 名称 == "尸腐毒" then
		local 目标数 = self:取目标数量(self.参战单位[编号], 名称, 等级, 编号)
		local 目标1 = {
			目标
		}

		if 目标数 > 1 then
			local 目标2 = self:取敌方未中毒目标(编号, 目标)

			for i = 1, 目标数 - 1 do
				if not 判断是否为空表(目标2) then
					local aa = ygsj(#目标2)
					目标1[#目标1 + 1] = 目标2[aa]

					table.remove(目标2, aa)
				end
			end
		end

		for n = 1, #目标1 do
			local 精准战斗流程1 = 精准战斗流程 + 0

			if n > 1 then
				self.战斗流程[#self.战斗流程 + 1] = {
					流程 = 56,
					攻击方 = 编号,
					挨打方 = {}
				}
				精准战斗流程1 = #self.战斗流程 + 0
				self.战斗流程[精准战斗流程1].挨打方[1] = {
					挨打方 = 目标1[n],
					特效 = {
						名称
					}
				}
				self.战斗流程[精准战斗流程1].不施法 = true
			end

			local 气血 = qz(等级 * 1.36 + self.参战单位[编号].法伤 * 0.1 + (self.参战单位[编号].固定伤害 or 0) * 0.3 +
			math.min(self.参战单位[目标1[n]].气血 * 0.1, self.参战单位[目标1[n]].等级 * 15))

			self:造成伤势(目标1[n], qz(气血 * 0.3))

			self.战斗流程[精准战斗流程1].挨打方[1].死亡 = self:减少气血(目标1[n], 气血, 编号, 名称, nil, nil, 1)
			self.战斗流程[精准战斗流程1].挨打方[1].气血 = 气血
			self.战斗流程[精准战斗流程1].挨打方[1].伤势 = qz(气血 * 0.3)
			self.战斗流程[精准战斗流程1].挨打方[1].状态 = 名称

			if self:负面技能施加判断(目标1[n], 名称, 编号) then
				self:添加状态(名称, self.参战单位[目标1[n]], self.参战单位[编号], 等级, 编号)
			end

			if self:法宝判断("九幽", 编号) ~= false then
				local 法宝名称 = "九幽"

				for i = 1, #self.参战单位[编号].法宝列表[法宝名称] do
					local 法宝位置 = self.参战单位[编号].法宝列表[法宝名称][i]
					local 境界 = self:法宝概率判断(法宝名称, 编号, 法宝位置, 1)

					if 境界 ~= false then
						local 目标 = self:取多个友方目标(编号, 编号, 10, "尸腐毒")

						if #目标 == 0 then
							return
						end

						local 目标数 = #目标
						self.战斗流程[精准战斗流程1].受益方 = {}

						for i = 1, 目标数 do
							local 气血 = 0
							local 法宝层数 = 境界 + 1
							气血 = qz(self.战斗流程[精准战斗流程1].挨打方[1].气血 * (0.08 + 法宝层数 * 0.02))
							气血 = self:取恢复气血(编号, 目标[i], 气血, "九幽", i)
							self.战斗流程[精准战斗流程1].受益方[i] = {
								受益方 = 目标[i],
								伤害 = 气血
							}

							self:增加气血(目标[i], 气血)
						end
					end
				end
			end

			if self.参战单位[目标1[n]].轻霜 ~= nil and ygsj() <= 30 and self.参战单位[编号].法术状态.机巧 == nil and self.参战单位[编号].法术状态.轻霜 == nil and self:负面技能施加判断(编号, "轻霜", 目标1[n]) then
				self:添加状态("轻霜", self.参战单位[编号], self.参战单位[目标1[n]], self.参战单位[目标1[n]].等级, 目标1[n])

				local hp = math.min(self.参战单位[编号].法术状态.轻霜.等级, self.参战单位[编号].气血 - 1)
				local 死亡 = self:减少气血(编号, hp, nil, nil, nil, nil, 1)
				self.战斗流程[#self.战斗流程 + 1] = {
					流程 = 1021,
					攻击方 = 编号,
					气血 = hp,
					死亡 = 死亡,
					挨打方 = {}
				}

				self:添加战斗流程提示("#P(轻霜)#R" ..
				self.参战单位[编号].名称 .. "#W企图攻击#R" .. self.参战单位[目标1[n]].名称 .. "#W、被其附加了#R4#W回合的#S轻霜#W状态")
			end
		end
	elseif 名称 == "断线木偶" or 名称 == "无魂傀儡" then
		self:添加状态(名称, self.参战单位[目标], self.参战单位[编号], 等级, 编号, 境界)

		self.战斗流程[精准战斗流程].挨打方[1].状态 = 名称
	elseif 名称 == "惊魂铃" or 名称 == "鬼泣" then
