			self:添加提示(self.参战单位[编号].玩家id, 编号, "你是没脑子吗?")

			return
		end

		self:添加状态(名称, self.参战单位[目标], self.参战单位[编号], 等级, 编号, 境界)
	elseif 名称 == "缚妖索" or 名称 == "捆仙绳" then
