	elseif 名称 == "摄魂" or 名称 == "舞雪冰蝶" then
		self:添加状态(名称, self.参战单位[目标], self.参战单位[编号], 等级, 编号, 境界)

		if 名称 == "舞雪冰蝶" then
			self.参战单位[目标].法术状态[名称].类型 = 2
			self.参战单位[目标].法术状态[名称].造成伤害 = -(境界 * 2 + 14)
			self.参战单位[目标].法术状态[名称].承受伤害 = 境界 * 1.5 + 18
		elseif 名称 == "摄魂" then
			self.参战单位[目标].法术状态[名称].类型 = 2
			self.参战单位[目标].法术状态[名称].造成伤害 = -(境界 * 1.5 + 12)
			self.参战单位[目标].法术状态[名称].承受伤害 = 境界 * 1 + 8

			if self:取奇经八脉是否有(编号, "聚魂", {
