					诛刑毒师 = 1,
					六道魍魉 = 1
				}) then
				self.参战单位[目标].法术状态[名称].造成伤害 = qz1(self.参战单位[目标].法术状态[名称].造成伤害 * 1.045)
				self.参战单位[目标].法术状态[名称].承受伤害 = qz1(self.参战单位[目标].法术状态[名称].承受伤害 * 1.045)
			end

			if self:取奇经八脉是否有(编号, "入魂") then
				self:添加状态("入魂", self.参战单位[编号], self.参战单位[编号], 等级, 编号, 境界)
			end

			if self.参战单位[目标].死亡状态 == 2 then
				self:添加状态("拘魄", self.参战单位[目标], self.参战单位[编号], 等级, 编号, 境界)
			end
		end

		self.战斗流程[精准战斗流程].挨打方[1].状态 = 名称
	elseif 名称 == "紧箍咒" then
		local 目标数 = self:取目标数量(self.参战单位[编号], 名称, 等级, 编号)
		local 目标1 = {
			目标
		}

		if 目标数 > 1 then
			目标1 = self:取多个敌方目标(编号, 目标, 目标数)
		end

		for n = 1, #目标1 do
			local 精准战斗流程1 = 精准战斗流程 + 0

			if n > 1 then
				self.战斗流程[#self.战斗流程 + 1] = {
