					气血 = hp,
					死亡 = 死亡,
					挨打方 = {}
				}

				self:添加战斗流程提示("#P(轻霜)#R" ..
				self.参战单位[编号].名称 .. "#W企图攻击#R" .. self.参战单位[目标1[n]].名称 .. "#W、被其附加了#R4#W回合的#S轻霜#W状态")
			end
		end
	elseif 名称 == "尸腐毒 " then
		local 气血 = qz(等级 * 10000)

		self:造成伤势(目标, qz(气血 * 0.3))

		self.战斗流程[精准战斗流程].挨打方[1].死亡 = self:减少气血(目标, 气血, 编号, 名称, nil, nil, 1)
		self.战斗流程[精准战斗流程].挨打方[1].气血 = 气血
		self.战斗流程[精准战斗流程].挨打方[1].伤势 = qz(气血 * 0.3)
		self.战斗流程[精准战斗流程].挨打方[1].状态 = 名称
	elseif 名称 == "催化" then
		local jc = 1

		if self:取玩家战斗() == false then
			jc = 3
		end

		if self.参战单位[编号].风灵 ~= nil and self.参战单位[编号].法术状态.风灵 ~= nil then
			self:刷新风灵(编号, -1)

			for i = 1, #self.参战单位 do
				if self.参战单位[i].法术状态.雾杀 ~= nil and self.参战单位[i].法术状态.雾杀.攻击编号 == 编号 then
					self.参战单位[i].法术状态.雾杀.伤害比例 = (self.参战单位[i].法术状态.雾杀.伤害比例 or 1) + jc
					self.参战单位[i].法术状态.雾杀.催化 = 1
				end
			end
		elseif self.参战单位[目标].法术状态.雾杀 ~= nil and self.参战单位[目标].法术状态.雾杀.攻击编号 == 编号 then
			self.参战单位[目标].法术状态.雾杀.伤害比例 = (self.参战单位[目标].法术状态.雾杀.伤害比例 or 1) + jc
			self.参战单位[目标].法术状态.雾杀.催化 = 1
		end
	elseif 名称 == "雾杀" then
