			local 气血 = qz((等级 * 2 + self.参战单位[编号].法伤 * 0.2) * self.参战单位[目标].法术状态.雾杀.层数 * self.参战单位[目标].法术状态.雾杀.伤害比例)
			self.战斗流程[精准战斗流程].挨打方[1].死亡 = self:减少气血(目标, 气血, 编号, 名称, nil, nil, 1)
			self.战斗流程[精准战斗流程].挨打方[1].气血 = 气血
			self.战斗流程[精准战斗流程].挨打方[1].状态 = 名称
		end
	elseif 名称 == "勾魂" then
		local 气血 = 等级 * 5
		local 命中躲避差 = self.参战单位[编号].命中 - (self.参战单位[目标].躲避 or 100)
		local gl = 50 + 命中躲避差 / 10

		if self.参战单位[编号].绝媚 ~= nil and self.参战单位[编号].绝媚 <= 0 then
			gl = 100
			气血 = 气血 * 2
			self.参战单位[编号].绝媚 = 技能冷却列表.绝媚 + 0
		end

		if ygsj() <= gl or self:取奇经八脉是否有(编号, "媚态") then
			self.战斗流程[精准战斗流程].挨打方[1].死亡 = self:减少气血(目标, 气血, 编号, 名称, nil, nil, 1)
			self.战斗流程[精准战斗流程].挨打方[1].气血 = 气血
			self.战斗流程[精准战斗流程].挨打方[1].击退 = true
			local 恢复气血 = qz(气血 / 2)

			self:增加气血(编号, 恢复气血)

			self.战斗流程[精准战斗流程].增加气血 = 恢复气血
		end
	elseif 名称 == "八戒上身" then
