			攻击方 = 编号,
			挨打方 = {}
		}
		local 精准战斗流程1 = #self.战斗流程 + 0

		for n = 1, #目标1 do
			self:驱散目标状态(目标1[n], 编号)
			self:添加状态("八戒上身", self.参战单位[目标1[n]], self.参战单位[编号])

			self.战斗流程[精准战斗流程1].挨打方[#self.战斗流程[精准战斗流程1].挨打方 + 1] = {
				参数 = "小猪",
				挨打方 = 目标1[n]
			}
		end
	elseif 名称 == "偷龙转凤" then
		local 魔法 = self:减少魔法(目标, self.参战单位[目标].魔法)

		self:添加状态("偷龙转凤", self.参战单位[目标], self.参战单位[编号], 魔法, 编号)
	elseif 名称 == "魔音摄魂" then
		local 等级差 = 等级 - self.参战单位[目标].等级
		local gl = 等级差 + 60

		if self:取奇经八脉是否有(编号, "鼓乐") then
			gl = gl + 20
		end

		if self:取奇经八脉是否有(编号, "忘川") and self:取是否有指定状态(编号, 目标, "瘴气") then
			gl = gl + 10
		end

		if ygsj() <= gl then
			self.战斗流程[精准战斗流程].挨打方[1].状态 = "魔音摄魂"

			self:添加状态("魔音摄魂", self.参战单位[目标], self.参战单位[编号], 等级, 编号)
		end
	elseif 名称 == "姐妹同心" then
