		local gl = 等级差 + 70
		local 气血 = 等级 * 5
		local 加成 = 0

		if self:取奇经八脉是否有(编号, "怜心") then
			加成 = 加成 + qz(气血 * 0.1)
			gl = gl + 12
		end

		if self:取奇经八脉是否有(编号, "魔瘴") then
			加成 = 加成 + qz(气血 * 0.12)
		end

		if ygsj() <= gl or self.参战单位[编号].怜心 ~= nil then
			self.参战单位[编号].怜心 = nil
			气血 = 气血 + 加成
			local 魔法 = self:减少魔法(目标, 气血)
