	elseif 名称 == "诡蝠之刑" then
		self:添加状态(名称, self.参战单位[目标], self.参战单位[编号], 等级, 编号)
	elseif 名称 == "摄魄" and self.参战单位[目标].魔法 >= 1 then
		local 魔法 = 等级 * 2
		local 命中躲避差 = self.参战单位[编号].命中 - (self.参战单位[目标].躲避 or 100)
		local gl = 50 + 命中躲避差 / 10

		if self.参战单位[编号].绝媚 ~= nil and self.参战单位[编号].绝媚 <= 0 then
			gl = 100
			魔法 = 魔法 * 2
			self.参战单位[编号].绝媚 = 技能冷却列表.绝媚 + 0
		end

		if ygsj() <= gl or self:取奇经八脉是否有(编号, "媚态") then
			local mp = self:减少魔法(目标, 魔法)
			self.战斗流程[精准战斗流程].挨打方[1].击退 = true

			self:增加魔法(编号, mp)
		end
	end

	if 名称 ~= "紧箍咒" and 名称 ~= "尸腐毒" and self.参战单位[目标].轻霜 ~= nil and ygsj() <= 30 and self.参战单位[编号].法术状态.机巧 == nil and self.参战单位[编号].法术状态.轻霜 == nil and self:负面技能施加判断(编号, "轻霜", 目标) then
		self:添加状态("轻霜", self.参战单位[编号], self.参战单位[目标], self.参战单位[目标].等级, 目标)

		local hp = math.min(self.参战单位[编号].法术状态.轻霜.等级, self.参战单位[编号].气血 - 1)
		local 死亡 = self:减少气血(编号, hp, nil, nil, nil, nil, 1)
		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 1021,
			攻击方 = 编号,
			气血 = hp,
			死亡 = 死亡,
			挨打方 = {}
		}

		self:添加战斗流程提示("#P(轻霜)#R" .. self.参战单位[编号].名称 .. "#W企图攻击#R" .. self.参战单位[目标].名称 .. "#W、被其附加了#R4#W回合的#S轻霜#W状态")
	end
end

function 战斗处理类:取恢复气血(编号, 目标, 气血, 名称, 执行数)
	local 法修 = 1
	local 已翻倍 = false

	if self.参战单位[编号] == nil then
		print(tostring(编号) .. tostring(名称))
	end

	法修 = 1 + self.参战单位[编号].法术修炼 * 0.02

	if self.参战单位[编号].治疗能力 == nil then
		self.参战单位[编号].治疗能力 = 0
	end

	if self.参战单位[目标].气血回复效果 == nil then
		self.参战单位[目标].气血回复效果 = 0
	end

	local 五行相生 = self:取五行相生(编号, 目标)
	local 额外治疗能力 = 0

	if 名称 == "地涌金莲" then
		额外治疗能力 = 额外治疗能力 + self.参战单位[编号].治疗能力 * 1
	end

	if self:取奇经八脉是否有(编号, "施他") and self:取是否有增益状态(编号) then
		额外治疗能力 = 额外治疗能力 + 40
	end

	if self:取奇经八脉是否有(编号, "灵照", "妙谛金莲") and self.参战单位[编号].武器伤害 ~= nil then
		local aa = 0

		for i = 1, #self.参战单位 do
			if self.参战单位[i].召唤物 == nil and self:取是否有增益状态(i) then
				aa = aa + 1
			end
		end

		额外治疗能力 = 额外治疗能力 + qz(self.参战单位[编号].武器伤害 * 0.03 * aa)
	end

	if self:取奇经八脉是否有(编号, "护法", "妙谛金莲") and self.参战单位[编号].武器伤害 ~= nil then
		local aa = 0

		for i = 1, #self.参战单位 do
			if self.参战单位[i].召唤物 == nil and self.参战单位[i].法术状态.护盾 ~= nil then
				aa = aa + 1
			end
		end

		额外治疗能力 = 额外治疗能力 + qz(self.参战单位[编号].武器伤害 * 0.04 * aa)
	end

	local 慈悲加成 = 1

	if 治疗加成模式 == 1 then
		慈悲加成 = 0
	end

	if self.参战单位[编号].门派 == "化生寺" and self:法宝判断("慈悲", 编号) ~= false then
		local 法宝名称 = "慈悲"

		for i = 1, #self.参战单位[编号].法宝列表[法宝名称] do
			local 法宝位置 = self.参战单位[编号].法宝列表[法宝名称][i]
			local 境界 = self:法宝概率判断(法宝名称, 编号, 法宝位置, 1)

			if 境界 ~= false then
				额外治疗能力 = 额外治疗能力 + 境界 * 12

				if 取随机数(1, 10000) <= 境界 * 100 then
					if 治疗加成模式 == 1 then
						慈悲加成 = 1
					else
						慈悲加成 = 2
					end
				end
			end
		end
	end

	local 效果 = qz((self.参战单位[编号].治疗能力 + self.参战单位[目标].气血回复效果 + 气血 + 额外治疗能力) * 法修 * 五行相生)

	if 名称 == "舍身取义" or 名称 == "牺牲·舍身取义" then
		local 舍身上限 = qz((self:取技能等级(编号, "舍身取义") * 50 + (self.参战单位[编号].治疗能力 + self.参战单位[目标].气血回复效果 + 额外治疗能力) * 3) * 法修 *
		五行相生)

		if 舍身上限 < 效果 then
			效果 = 舍身上限 + 0
		end
	end

	local 加成 = 1

	if 治疗加成模式 == 1 then
		加成 = 加成 + 慈悲加成
	else
		效果 = 效果 * 慈悲加成
	end

	if self:取奇经八脉是否有(编号, "佛缘") and self.参战单位[目标].类型 == "角色" then
		local 加成1 = 0

		if self:取是否五行相生(self.参战单位[编号].攻击五行, self.参战单位[目标].攻击五行) then
			加成1 = 加成1 + 0.05
		end

		if self:取是否五行相生(self.参战单位[编号].攻击五行, self.参战单位[目标].防御五行) then
			加成1 = 加成1 + 0.05
		end

		if 治疗加成模式 == 1 then
			加成 = 加成 + 加成1
		else
			效果 = 效果 * (1 + 加成1)
		end
	end

	if self.参战单位[编号].治疗效果 ~= nil then
		if 治疗加成模式 == 1 then
			加成 = 加成 + self.参战单位[编号].治疗效果 / 100 - 1
		else
			效果 = 效果 * self.参战单位[编号].治疗效果 / 100
		end
	end

	if 聚气生效法术[名称] ~= nil then
		if self.参战单位[编号].聚气加成 ~= nil then
			if 治疗加成模式 == 1 then
				加成 = 加成 + self.参战单位[编号].聚气加成 - 1
			else
				效果 = 效果 * self.参战单位[编号].聚气加成
			end
		end

		if self.参战单位[编号].法术状态.销武 ~= nil then
			if 治疗加成模式 == 1 then
				加成 = 加成 - 0.5
			else
				效果 = 效果 * 0.5
			end
		end
	end

	if self.参战单位[编号].法术状态.仁心 ~= nil and (名称 == "活血" or 名称 == "推拿") then
		if 治疗加成模式 == 1 then
			加成 = 加成 + 0.75 * self.参战单位[编号].法术状态.仁心.层数
		else
			效果 = 效果 * (1 + 0.75 * self.参战单位[编号].法术状态.仁心.层数)
		end
	end

	if 名称 == "活血" then
		if self:取奇经八脉是否有(编号, "化瘀") and self.参战单位[编号].化瘀 == nil then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 1.2
			else
				效果 = 效果 * 2.2
			end
		end

		if self:取奇经八脉是否有(编号, "妙手") then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 0.25
			else
				效果 = 效果 * 1.25
			end
		end
	elseif 名称 == "推拿" then
		if self:取奇经八脉是否有(编号, "化瘀") and self.参战单位[编号].化瘀 == nil then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 1.2
			else
				效果 = 效果 * 2.2
			end
		end

		if self:取奇经八脉是否有(编号, "妙手") then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 0.25
			else
				效果 = 效果 * 1.25
			end
		end
	elseif 名称 == "我佛慈悲" then
		if self:取奇经八脉是否有(编号, "佛性") then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 0.2
			else
				效果 = 效果 * 1.2
			end
		end
	elseif 名称 == "推气过宫" then
		if self:取奇经八脉是否有(编号, "圣手") and 执行数 == 1 then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 0.5
			else
				效果 = 效果 * 1.5
			end
		end

		if self:取奇经八脉是否有(编号, "天照") then
			self:添加状态("天照", self.参战单位[目标], self.参战单位[编号], 1, 编号)
			self:更新单个法术状态(目标, "天照")
		end

		if self.参战单位[编号].佛佑 ~= nil then
			self:添加状态("金刚护体", self.参战单位[目标], self.参战单位[编号], self:取技能等级(编号, "金刚护体"), 编号)

			self.参战单位[目标].法术状态.金刚护体.回合 = 3

			self:客户端添加状态(目标, "金刚护体")
		end
	elseif 名称 == "救死扶伤" then
		if self:取奇经八脉是否有(编号, "心韧") and self.参战单位[编号].心韧 == nil then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 1
			else
				效果 = 效果 * 2
			end
		end

		if self:取奇经八脉是否有(编号, "天照") then
			self:添加状态("天照", self.参战单位[目标], self.参战单位[编号], 1, 编号)
			self:更新单个法术状态(目标, "天照")
		end
	elseif 名称 == "地涌金莲" and self.参战单位[编号].陷阱 ~= nil then
		if 治疗加成模式 == 1 then
			加成 = 加成 - 0.3
		else
			效果 = 效果 * 0.7
		end
	end

	if (名称 == "地涌金莲" or 名称 == "焕生咒") and self:取奇经八脉是否有(编号, "疗愈") and self.参战单位[编号].防御五行 == self.参战单位[目标].防御五行 and self:取是否玩家角色(目标) then
		if 治疗加成模式 == 1 then
			加成 = 加成 + 0.08
		else
			效果 = 效果 * 1.08
		end
	end

	if self.参战单位[编号].治疗能力百分比 ~= nil then
		if 治疗加成模式 == 1 then
			加成 = 加成 + self.参战单位[编号].治疗能力百分比 / 100
		else
			效果 = qz(效果 * (1 + self.参战单位[编号].治疗能力百分比 / 100))
		end
	end

	if 编号 ~= nil and self:取奇经八脉是否有(编号, "劳心") and self.参战单位[编号].气血 <= qz(self.参战单位[编号].最大气血 * 0.3) then
		if 治疗加成模式 == 1 then
			加成 = 加成 + 1
		else
			效果 = 效果 * 2
		end
	end

	if self.参战单位[编号].法术状态.莲心剑意 ~= nil then
		if 治疗加成模式 == 1 then
			加成 = 加成 - 0.1
		else
			效果 = 效果 * 0.9
		end
	end

	if self.参战单位[目标].法术状态.重创 ~= nil then
		if 治疗加成模式 == 1 then
			加成 = 加成 - 0.5
		else
			效果 = 效果 * 0.5
		end
	end

	if self.参战单位[编号].队伍 == 0 then
		if self.参战单位[编号].名称 == "酒肉和尚帮凶" and (self.战斗类型 == 100223 or self.战斗类型 == 110010) then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 2
			else
				效果 = 效果 * 3
			end

			已翻倍 = true
		elseif self.参战单位[编号].名称 == "守门天将" and (self.战斗类型 == 100224 or self.战斗类型 == 110008) then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 2
			else
				效果 = 效果 * 3
			end

			已翻倍 = true
		elseif self.参战单位[编号].名称 == "飞升守护者" and (self.战斗类型 == 100050 or self.战斗类型 == 100051 or self.战斗类型 == 100052 or self.战斗类型 == 100053 or self.战斗类型 == 100054) then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 2
			else
				效果 = 效果 * 3
			end

			已翻倍 = true
		elseif self.战斗类型 == 100055 and (self.参战单位[编号].名称 == "护驾亲兵 " or self.参战单位[编号].名称 == "云霄仙子 " or self.参战单位[编号].名称 == "勾魂使者 " or self.参战单位[编号].名称 == "泼法金刚 " or self.参战单位[编号].名称 == "护法枷蓝 ") then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 2
			else
				效果 = 效果 * 3
			end

			已翻倍 = true
		elseif self.战斗类型 == 100056 and self.参战单位[编号].类型 ~= "角色" then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 2
			else
				效果 = 效果 * 3
			end

			已翻倍 = true
		elseif self.战斗类型 == 110007 and self.参战单位[编号].名称 == "赌徒喽罗" then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 4
			else
				效果 = 效果 * 5
			end

			已翻倍 = true
		elseif self.战斗类型 == 100237 and self.参战单位[编号].名称 == "派大星" then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 4
			else
				效果 = 效果 * 5
			end

			已翻倍 = true
		elseif self.战斗类型 == 100257 and self.参战单位[编号].名称 == "花妖喽罗" then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 9
			else
				效果 = 效果 * 10
			end

			已翻倍 = true
		elseif self.战斗类型 == 100258 and self.参战单位[编号].名称 == "天兵喽罗" then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 9
			else
				效果 = 效果 * 10
			end

			已翻倍 = true
		elseif self.战斗类型 == 100259 and self.参战单位[编号].名称 == "虾兵喽啰" then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 9
			else
				效果 = 效果 * 10
			end

			已翻倍 = true
		elseif self.战斗类型 == 100261 and (self.参战单位[编号].名称 == "空度禅师" or self.参战单位[编号].名称 == "地涌夫人") then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 14
			else
				效果 = 效果 * 15
			end

			已翻倍 = true
		elseif self.战斗类型 == 100262 and self.参战单位[编号].名称 == "空慈方丈" then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 14
			else
				效果 = 效果 * 15
			end

			已翻倍 = true
		end
	end

	if self.参战单位[目标].法术状态.谜毒之缚 ~= nil then
		if 治疗加成模式 == 1 then
			加成 = 加成 - 0.2
		else
			效果 = 效果 * 0.8
		end
	end

	if self.参战单位[编号].明光 ~= nil and (名称 == "我佛慈悲" or 名称 == "推气过宫" or 名称 == "推拿" or 名称 == "妙悟" or 名称 == "舍身取义" or 名称 == "活血" or 名称 == "救死扶伤" or 名称 == "妙手回春") then
		local 触发 = false
		local 加成1 = 2

		if self:取奇经八脉是否有(编号, "归气") then
			加成1 = 1.6

			if ygsj() <= 18 then
				触发 = true
			end
		end

		if self.参战单位[编号].法术状态.佛显 ~= nil and (名称 == "推气过宫" or 名称 == "救死扶伤") then
			触发 = true
			self.参战单位[编号].法术状态.佛显 = nil
		elseif ygsj() <= 18 then
			触发 = true
		end

		if 触发 then
			if 治疗加成模式 == 1 then
				加成 = 加成 + 加成1 - 1
			else
				效果 = qz(效果 * 加成1)
			end
		end
	end

	if self.参战单位[目标].法术状态.腾雷 ~= nil then
		if 治疗加成模式 == 1 then
			加成 = 加成 - 0.5
		else
			效果 = 效果 * 0.5
		end
	end

	if self.参战单位[目标].法术状态.瘴气 ~= nil then
		local 减益 = 0.5

		if self.参战单位[目标].法术状态.瘴气.情劫 ~= nil then
			减益 = 减益 * 1.25
		end

		if self.参战单位[目标].法术状态.瘴气.连绵 ~= nil and self:取封印状态(目标) == false then
			减益 = 减益 * 1.4
		end

		if 治疗加成模式 == 1 then
			加成 = 加成 - 减益
		else
			效果 = 效果 * (1 - 减益)
		end
	end

	if self.参战单位[目标].法术状态.迷意 ~= nil then
		if 治疗加成模式 == 1 then
			加成 = 加成 - 0.3
		else
			效果 = 效果 * 0.7
		end
	end

	if 名称 ~= nil and self.参战单位[目标].法术状态.佛眷 ~= nil and self.参战单位[目标].法术状态.佛眷.攻击编号 == 编号 then
		if 治疗加成模式 == 1 then
			加成 = 加成 + 0.3
		else
			效果 = 效果 * 1.3
		end
	elseif 名称 == "药品" and self.参战单位[目标].法术状态.佛眷 ~= nil then
		if 治疗加成模式 == 1 then
			加成 = 加成 + 0.3
		else
			效果 = 效果 * 1.3
		end
	end

	if self:取奇经八脉是否有(编号, "弥愤") or self:取奇经八脉是否有(编号, "魂守") or self:取奇经八脉是否有(编号, "刺骨") then
		if 治疗加成模式 == 1 then
			加成 = 加成 - 0.3
		else
			效果 = 效果 * 0.7
		end
	end

	if 治疗加成模式 == 1 then
		效果 = 效果 * math.max(加成, 0.1)
	end

	if 编号 ~= nil and self:取符石组合效果(编号, "万丈霞光") then
		效果 = qz(效果 + self:取符石组合效果(编号, "万丈霞光"))
	end

	if 编号 ~= nil and 名称 == "普渡众生" then
		if self:取奇经八脉是否有(编号, "化戈") then
			效果 = 效果 + self.参战单位[编号].武器伤害 * 0.18
		end

		if self:取奇经八脉是否有(编号, "玉帛") then
			效果 = 效果 + qz1((self.参战单位[编号].被动技能.护法金刚 or self.参战单位[编号].等级) * 2.5 * 0.1)
		end
	elseif 名称 == "地涌金莲" and 执行数 == 1 and self:取奇经八脉是否有(编号, "涌泉") then
		效果 = 效果 + (self.参战单位[编号].被动技能.地冥妙法 or 0) * 6
	end

	if self.参战单位[目标].法术状态.魔音摄魂 ~= nil then
		if self:取封印状态(目标) == false then
			效果 = qz(效果 * 0)
		else
			效果 = qz(效果 * 0.4)
		end
	end

	if 名称 ~= nil and self:取玩家战斗() == false and self.参战单位[编号].玩家id == 0 and 已翻倍 == false then
		效果 = 效果 * 5
	end

	if self.共工光环 == 2 and self.参战单位[编号].队伍 == 0 then
		效果 = 效果 * 1.5
	end

	return qz1(效果)
end

function 战斗处理类:施法统一计算(编号, 名称, 物攻)
	if 物攻 == nil then
		self.参战单位[编号].施法耐久 = (self.参战单位[编号].施法耐久 or 0) + 1
	end

	if self.参战单位[编号].被动技能.龍魂 ~= nil then
		self.参战单位[编号].龍魂 = (self.参战单位[编号].龍魂 or 0) + 1
	end

	if 装备特技[名称] ~= nil then
		if self:取奇经八脉是否有(编号, "静心", "妙舞佳人") and self.参战单位[编号].法术状态.乐韵 == nil then
			self:添加状态("乐韵", self.参战单位[编号])
		end

		if self:取奇经八脉是否有(编号, "鬼火") and 装备特技[名称].消耗 <= 90 then
			self.参战单位[编号].待回复愤怒 = (self.参战单位[编号].待回复愤怒 or 0) + 16
		end

		if self:取奇经八脉是否有(编号, "催迫") then
			self.参战单位[编号].催迫增伤 = 1.12
		end

		if self:取奇经八脉是否有(编号, "聚气") and 装备特技[名称].消耗 >= 60 then
			self:刷新战意(编号, 1)
		end

		if self:取奇经八脉是否有(编号, "灵能", "伏魔天师") then
			self.参战单位[编号].灵能 = qz1(装备特技[名称].消耗 / 1.5)
		end

		if self:取奇经八脉是否有(编号, "空灵") then
			self:取消状态("空灵", self.参战单位[编号])
			self:添加状态("空灵", self.参战单位[编号])
		end

		if self.参战单位[编号].自矜 ~= nil and self:取奇经八脉是否有(编号, "重明") and self.参战单位[编号].法术状态.自矜 == nil then
			self:添加状态("自矜", self.参战单位[编号])
		end

		if self:取奇经八脉是否有(编号, "趁虚") then
			self:取消状态("趁虚", self.参战单位[编号])
			self:添加状态("趁虚", self.参战单位[编号])
		end

		if self:取奇经八脉是否有(编号, "亢强") then
			self.参战单位[编号].亢强 = 1
		end

		if self:取奇经八脉是否有(编号, "不忿") then
			self.参战单位[编号].不忿 = 1
		end

		if self:取奇经八脉是否有(编号, "烬藏") then
			self.参战单位[编号].秘传飞砂走石 = nil
			self.参战单位[编号].秘传三昧真火 = nil
		end

		if self:取奇经八脉是否有(编号, "存雄") then
			self:取消状态("存雄", self.参战单位[编号])
			self:添加状态("存雄", self.参战单位[编号])
		end
	else
		self.参战单位[编号].允许助攻 = true

		if self.参战单位[编号].顾盼生姿计算 ~= nil and self.参战单位[编号].顾盼生姿 ~= nil then
			self.参战单位[编号].顾盼生姿计算 = nil
			self.参战单位[编号].顾盼生姿 = math.min(self.参战单位[编号].顾盼生姿 + 1, 4)

			if self.参战单位[编号].法术状态.顾盼生姿 == nil or self.参战单位[编号].法术状态.顾盼生姿.层数 < self.参战单位[编号].顾盼生姿 then
				self:取消状态("顾盼生姿", self.参战单位[编号])
				self:添加状态("顾盼生姿", self.参战单位[编号], self.参战单位[编号], self.参战单位[编号].等级, 编号, self.参战单位[编号].顾盼生姿)
				self:流程处理状态(编号, {
					{
						增加状态 = "顾盼生姿",
						挨打方 = 编号,
						状态 = {
							"顾盼生姿"
						}
					}
				})
			end
		end
	end
end

function 战斗处理类:单体封印技能计算(编号, 名称, 等级, 指定目标, 消耗)
	if self:取敌方是否全部死亡(编号) == true then
		return
	end

	if 名称 == "碎玉弄影" then
		if 指定目标 == nil then
			self.参战单位[编号].碎玉弄影次数 = 1
		else
			self.参战单位[编号].碎玉弄影次数 = nil
		end
	end

	local 目标 = 指定目标 or self.参战单位[编号].指令.目标

	if self:取目标状态(编号, 目标, 1) == false then
		目标 = self:取单个敌方目标(编号)
	end

	if 目标 == 0 then
		return
	end

	if 法宝 ~= nil and self:取法宝封印状态(目标) then
		return
	elseif 名称 ~= "掌心雷" and self:取封印状态(目标) then
		return
	end

	if self.参战单位[目标].法术状态.分身术 ~= nil and self.参战单位[目标].法术状态.分身术.破解 == nil then
		self.参战单位[目标].法术状态.分身术.破解 = 1
		self.参战单位[编号].出手 = 1

		self:添加战斗流程提示("#P(分身术)#R" .. self.参战单位[编号].名称 .. "#W的法术被#R" .. self.参战单位[目标].名称 .. "#W的#Y分身术#W躲过去了！")

		return
	end

	if 消耗 == nil and self:技能消耗(self.参战单位[编号], 1, 名称, 编号) == false then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "未到达技能消耗要求,技能使用失败")

		if 技能冷却列表[名称] ~= nil then
			self.参战单位[编号][名称] = 0
		end

		return
	end

	self:施法统一计算(编号, 名称)

	self.参战单位[编号].出手 = 1
	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 50,
		攻击方 = 编号,
		挨打方 = {
			{
				挨打方 = 目标,
				特效 = {
					名称
				},
				提示 = {
					类型 = "法术",
					允许 = true,
					名称 = self.参战单位[编号].名称 .. "使用了" .. 名称
				}
			}
		}
	}
	local 精准战斗流程 = #self.战斗流程 + 0
	self.执行等待 = self.执行等待 + 10

	if self:取封印成功(名称, 等级, self.参战单位[编号], self.参战单位[目标], 编号) then
		self:添加状态(名称, self.参战单位[目标], self.参战单位[编号], 等级, 编号)

		self.战斗流程[精准战斗流程].挨打方[1].添加状态 = 名称

		if 名称 == "锋芒毕露" then
			self:添加状态("锋芒毕露", self.参战单位[目标], self.参战单位[编号], self:取技能等级(编号, "锋芒毕露"), 编号)
		elseif 名称 == "似玉生香" then
			if self:取奇经八脉是否有(编号, "倾国") and ygsj() <= 25 then
				if self.参战单位[编号].法术状态.倾国 == nil then
					self:添加状态("倾国", self.参战单位[编号])
				else
					self.参战单位[编号].法术状态.倾国.层数 = self.参战单位[编号].法术状态.倾国.层数 + 1
				end
			end
		elseif 名称 == "碎玉弄影" then
			if self.参战单位[编号].碎玉弄影次数 == 1 then
				self:单体封印技能计算(编号, "碎玉弄影", 等级, self:取单个敌方目标(编号, nil, 目标), "无消耗")
			end
		elseif 名称 == "诱袭" then
			self:添加状态("诱袭", self.参战单位[目标], self.参战单位[编号], self:取技能等级(编号, "诱袭"), 编号)
		end
	elseif 名称 == "碎玉弄影" and self.参战单位[编号].碎玉弄影次数 == 1 then
		self:单体封印技能计算(编号, "碎玉弄影", 等级, 目标, "无消耗")
	end

	if self.参战单位[目标].轻霜 ~= nil and ygsj() <= 30 and self.参战单位[编号].法术状态.机巧 == nil and self.参战单位[编号].法术状态.轻霜 == nil and self:负面技能施加判断(编号, "轻霜", 目标) then
		self:添加状态("轻霜", self.参战单位[编号], self.参战单位[目标], self.参战单位[目标].等级, 目标)

		local hp = math.min(self.参战单位[编号].法术状态.轻霜.等级, self.参战单位[编号].气血 - 1)
		local 死亡 = self:减少气血(编号, hp, nil, nil, nil, nil, 1)
		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 1021,
			攻击方 = 编号,
			气血 = hp,
			死亡 = 死亡,
			挨打方 = {}
		}

		self:添加战斗流程提示("#P(轻霜)#R" .. self.参战单位[编号].名称 .. "#W企图攻击#R" .. self.参战单位[目标].名称 .. "#W、被其附加了#R4#W回合的#S轻霜#W状态")
	end
end

function 战斗处理类:群体封印技能计算(编号, 名称, 等级, 法宝)
	if self:取敌方是否全部死亡(编号) == true then
		return
	end

	local 目标 = self.参战单位[编号].指令.目标

	if 额外目标 ~= nil then
		目标 = 额外目标
	end

	local 目标数 = self:取目标数量(self.参战单位[编号], 名称, 等级, 编号)
	local 目标 = self:取多个敌方目标(编号, 目标, 目标数)

	if #目标 == 0 then
		return
	end

	local 目标重置 = {}

	for n = 1, #目标 do
		if self.参战单位[目标[n]].法术状态.分身术 ~= nil and self.参战单位[目标[n]].法术状态.分身术.破解 == nil then
			self.参战单位[目标[n]].法术状态.分身术.破解 = 1
			self.参战单位[编号].出手 = 1

			self:添加战斗流程提示("#P(分身术)#R" .. self.参战单位[编号].名称 .. "#W的法术被#R" .. self.参战单位[目标[n]].名称 .. "#W的#Y分身术#W躲过去了！")
		else
			目标重置[#目标重置 + 1] = 目标[n]
		end
	end

	目标 = DeepCopy(目标重置)

	if #目标 == 0 then
		return
	end

	目标数 = #目标

	if 消耗 == nil and self:技能消耗(self.参战单位[编号], 目标数, 名称, 编号) == false then
		self:添加提示(self.参战单位[编号].玩家id, 编号, "未到达技能消耗要求,技能使用失败")

		if 技能冷却列表[名称] ~= nil then
			self.参战单位[编号][名称] = 0
		end

		return
	end

	self.参战单位[编号].出手 = 1

	self:施法统一计算(编号, 名称)

	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 209,
		攻击方 = 编号,
		挨打方 = {},
		提示 = {
			类型 = "法术",
			允许 = true,
			名称 = self.参战单位[编号].名称 .. "使用了" .. 名称
		}
	}
	local 精准战斗流程 = #self.战斗流程 + 0
	self.执行等待 = self.执行等待 + 10

	if 名称 == "日月同辉" then
		名称 = "日月乾坤"
	end

	for n = 1, 目标数 do
		self.战斗流程[精准战斗流程].挨打方[n] = {
			挨打方 = 目标[n],
			特效 = {
				名称
			}
		}

		if 名称 == "河东狮吼" or 名称 == "停陷术" or 名称 == "碎甲术" then
			self.战斗流程[精准战斗流程].流程 = 213
		elseif 名称 == "凝滞术" or 名称 == "破甲术" or 名称 == "放下屠刀" then
			self.战斗流程[精准战斗流程].流程 = 215
		elseif 名称 == "瘴气" then
			if self:取奇经八脉是否有(编号, "媚态") then
				self:取消状态("寡欲令", self.参战单位[目标[n]], "媚态")
			end
		elseif 名称 == "夺魄令" then
			if 编号 ~= nil and self:取奇经八脉是否有(编号, "追魂") then
				self:添加状态("夺魄令1", self.参战单位[目标[n]], self.参战单位[编号], self.参战单位[编号].等级, 编号)

				self.战斗流程[精准战斗流程].挨打方[n].添加状态 = "夺魄令1"
			end
		elseif 名称 == "飞花摘叶" then
			local 魔法 = 等级 * 2

			if self.参战单位[编号].飞花 ~= nil and self.参战单位[编号].飞花 <= 0 then
				魔法 = 魔法 * 2
			end

			if self.参战单位[目标[n]].魔法 < 魔法 then
				魔法 = self.参战单位[目标[n]].魔法 + 0
			end

			self:减少魔法(目标[n], 魔法)

			local 恢复目标 = self:取多个友方目标(编号, 编号, 3, 名称)

			for w = 1, #恢复目标 do
				self:增加魔法(恢复目标[w], qz(魔法 / #恢复目标))
			end
		end

		if 法宝 ~= nil and self:取法宝封印状态(目标[n]) then
			return
		elseif self:取封印状态(目标[n]) then
			return
		end

		local 成功 = false

		if self:取封印成功(名称, 等级, self.参战单位[编号], self.参战单位[目标[n]], 编号, n) then
			成功 = true

			self:添加状态(名称, self.参战单位[目标[n]], self.参战单位[编号], 等级, 编号)

			self.战斗流程[精准战斗流程].挨打方[n].添加状态 = 名称
		end

		if self.参战单位[目标[n]].轻霜 ~= nil and ygsj() <= 30 and self.参战单位[编号].法术状态.机巧 == nil and self.参战单位[编号].法术状态.轻霜 == nil and self:负面技能施加判断(编号, "轻霜", 目标[n]) then
			self:添加状态("轻霜", self.参战单位[编号], self.参战单位[目标[n]], self.参战单位[目标[n]].等级, 目标[n])

			local hp = math.min(self.参战单位[编号].法术状态.轻霜.等级, self.参战单位[编号].气血 - 1)
			local 死亡 = self:减少气血(编号, hp, nil, nil, nil, nil, 1)
			self.战斗流程[#self.战斗流程 + 1] = {
				流程 = 1021,
				攻击方 = 编号,
				气血 = hp,
				死亡 = 死亡,
				挨打方 = {}
			}

			self:添加战斗流程提示("#P(轻霜)#R" ..
			self.参战单位[编号].名称 .. "#W企图攻击#R" .. self.参战单位[目标[n]].名称 .. "#W、被其附加了#R4#W回合的#S轻霜#W状态")
		end
	end

	if 名称 == "飞花摘叶" then
		if self.参战单位[编号].飞花 ~= nil and self.参战单位[编号].飞花 <= 0 then
			self.参战单位[编号].飞花 = 技能冷却列表.飞花 + 0
		end
	elseif 名称 == "夺魄令" and self:取是否有指定状态(编号, 编号, "燃血术·摄魂迷影") then
		self.参战单位[编号].法术状态["燃血术·摄魂迷影"].层数 = self.参战单位[编号].法术状态["燃血术·摄魂迷影"].层数 - 1

		if self.参战单位[编号].法术状态["燃血术·摄魂迷影"].层数 < 1 then
			self:取消状态("燃血术·摄魂迷影", self.参战单位[编号])
		end
	end
end

function 战斗处理类:击退处理()
	if not 判断是否为空表(self.击退列表) then
		for k, v in pairs(self.击退列表) do
			self:直接击退处理(k)
		end

		self.击退列表 = {}
	end
end

function 战斗处理类:直接击退处理(目标)
	if self.参战单位[目标] ~= nil then
		self.参战单位[目标].气血 = 0
		self.参战单位[目标].死亡状态 = 1
		self.参战单位[目标].法术状态 = {}

		for w = 1, #self.参战玩家 do
			发送数据(self.参战玩家[w].连接id, 5508.1, {
				id = 目标
			})
			常规提示(self.参战玩家[w].id, "#P狸#Y被#S封印#Y后逃跑了……")
		end

		for i, v in pairs(self.观战玩家) do
			if 玩家数据[i] ~= nil then
				发送数据(玩家数据[i].连接id, 5508.1, {
					id = 目标
				})
			end
		end
	end
end

function 战斗处理类:浮空处理(目标)
	if self.参战单位[目标] ~= nil then
		for w = 1, #self.参战玩家 do
			发送数据(self.参战玩家[w].连接id, 5508.3, {
				id = 目标
			})
			常规提示(self.参战玩家[w].id, "#P" .. self.参战单位[目标].名称 .. "浮空了！")
		end

		for i, v in pairs(self.观战玩家) do
			if 玩家数据[i] ~= nil then
				发送数据(玩家数据[i].连接id, 5508.3, {
					id = 目标
				})
			end
		end
	end
end

function 战斗处理类:取是否有抗封技能(编号, 门派)
	if 编号 == nil or self.参战单位[编号] == nil then
		return
	end

	local 所有 = {
		清静菩提 = 1,
		幻境术 = 1,
		幽冥鬼眼 = 1
	}
	local aa = {
		女儿村 = {
			解封 = 1,
			宁心 = 1
		},
		方寸山 = {
			驱魔 = 1
		},
		盘丝洞 = {
			寡欲令 = 1
		},
		天宫 = {
			复苏 = 1
		},
		无底洞 = {
			无穷妙道 = 1
		}
	}

	for k, v in pairs(self.参战单位[编号].法术状态) do
		if 所有[k] ~= nil or 门派 ~= nil and aa[门派] ~= nil and aa[门派][k] ~= nil then
			return true
		end
	end

	return false
end

function 战斗处理类:取封印成功(名称, 等级, 攻击方, 挨打方, 编号, 执行数)
	if 攻击方 ~= nil and 编号 == nil then
		编号 = 攻击方.战斗编号
	end

	if self:取奇经八脉是否有(攻击方.战斗编号, "毒雾") and (名称 == "似玉生香" or 名称 == "莲步轻舞" or 名称 == "如花解语" or 名称 == "娉婷袅娜" or 名称 == "碎玉弄影" or 名称 == "一笑倾城") and ygsj() <= 30 then
		self:添加暗器毒(挨打方.战斗编号, 攻击方.战斗编号)
	end

	if self:取奇经八脉是否有(挨打方.战斗编号, "忍辱") then
		self:增加愤怒(挨打方.战斗编号, 15)
	end

	if 名称 == "画地为牢" or 名称 == "河东狮吼" or 名称 == "碎甲符" or 名称 == "锢魂术" or 名称 == "飞花摘叶" or 名称 == "放下屠刀" or 名称 == "凝滞术" or 名称 == "停陷术" or 名称 == "破甲术" or 名称 == "碎甲术" or 名称 == "魑魅缠身" then
		return true
	end

	if 名称 == "瘴气" then
		return true
	end

	if 名称 == "摧心术" then
		return true
	end

	if 名称 == "煞气诀" and self:取奇经八脉是否有(攻击方.战斗编号, "烈煞") and 挨打方.法术状态.夺魄令 ~= nil then
		return true
	end

	if 挨打方.法术状态.乾坤妙法 ~= nil then
		return false
	end

	if 挨打方.不可封印 or not self:负面技能施加判断(挨打方.战斗编号, 名称) or self:法术躲避计算(攻击方.战斗编号, 挨打方.战斗编号, 名称) then
		return false
	end

	if 名称 == "摄魂" or 名称 == "无尘扇" or 名称 == "断线木偶" or 名称 == "无魂傀儡" then
		return true
	end

	if 名称 == "发瘟匣" then
		if 取随机数(1, 10000) <= (等级 * 1.5 + 22) * 100 then
			return true
		else
			return false
		end
	elseif 名称 == "无字经" then
		if 取随机数(1, 10000) <= (等级 * 3 + 35) * 100 then
			return true
		else
			return false
		end
	elseif 名称 == "番天印" then
		if 取随机数(1, 10000) <= (等级 * 5 + 25) * 100 then
			return true
		else
			return false
		end
	end

	if 毒状态列表1[名称] ~= nil and 挨打方.法术状态.百毒不侵 then
		return false
	end

	if 名称 == "雾杀" and 挨打方.法术状态.百毒不侵 then
		return false
	end

	if 名称 == "雷浪穿云" or 名称 == "落花成泥" or 名称 == "凋零之歌" then
		return true
	end

	if (名称 == "似玉生香" or 名称 == "莲步轻舞" or 名称 == "如花解语" or 名称 == "碎玉弄影") and 挨打方.法术状态.宁心 then
		return false
	end

	if 名称 == "含情脉脉" and 挨打方.法术状态.寡欲令 then
		return false
	end

	if (名称 == "催眠符" or 名称 == "失心符" or 名称 == "落魄符" or 名称 == "失忆符" or 名称 == "追魂符" or 名称 == "离魂符" or 名称 == "定身符") and 挨打方.法术状态.驱魔 then
		return false
	end

	if 名称 == "威慑" and 挨打方.类型 == "角色" then
		return false
	elseif 名称 == "反间之计" and 挨打方.类型 == "角色" and (self.战斗类型 == 200003 or self.战斗类型 == 200004 or self.战斗类型 == 200005 or self.战斗类型 == 200006 or self.战斗类型 == 200007 or self.战斗类型 == 200008) then
		return false
	end

	local 临时封印命中等级 = 0

	if 攻击方.法术状态.神符 ~= nil and 名称 == 攻击方.法术状态.神符.加成技能 then
		临时封印命中等级 = 临时封印命中等级 + 500

		self:取消状态("神符", 攻击方)
	end

	local 顾盼生姿 = false

	if 攻击方.召唤兽 ~= nil and self.参战单位[攻击方.召唤兽].法术状态.顾盼生姿 ~= nil then
		临时封印命中等级 = 临时封印命中等级 + self.参战单位[攻击方.召唤兽].法术状态.顾盼生姿.等级
		顾盼生姿 = true
	end

	if self:取奇经八脉是否有(编号, "阴魅") and 攻击方.武器伤害 ~= nil then
		local aa = true

		for i = 1, #self.参战单位 do
			if self.参战单位[i].队伍 ~= 攻击方.队伍 and self:取封印状态(i) then
				aa = false

				break
			end
		end

		if aa then
			临时封印命中等级 = 临时封印命中等级 + qz(攻击方.武器伤害 * 0.15)
		end
	end

	if 名称 == "夺魄令" and 攻击方.法术状态["燃血术·摄魂迷影"] ~= nil then
		临时封印命中等级 = 临时封印命中等级 + 120
	end

	if self:取奇经八脉是否有(编号, "萦魄") and 攻击方.武器伤害 ~= nil then
		local gs = self:取是否有增益状态(编号, "取个数")

		if gs ~= false and gs > 2 then
			临时封印命中等级 = 临时封印命中等级 + qz(攻击方.武器伤害 * 0.15)
		end
	end

	local 等级影响 = 攻击方.等级 + 等级 - 挨打方.等级 * 2
	local 基础几率 = math.max(
	50 + 等级影响 + (攻击方.法术修炼 - 挨打方.抗法修炼) * 2 + (攻击方.封印命中率 or 0) - (挨打方.封印抵抗率 or 0) +
	(攻击方.封印命中等级 + 临时封印命中等级) / (攻击方.等级 + 25) * 10 - 挨打方.抵抗封印等级 / (挨打方.等级 + 25) * 10, 5 + 等级 / 2000)
	local 基础加成 = 0

	if 名称 == "日月乾坤" then
		基础几率 = 基础几率 - 日月乾坤封印减少值

		if self:取奇经八脉是否有(编号, "玄机") and self:取是否有异常状态(挨打方.战斗编号) then
			基础加成 = 基础加成 + 8
		end
	elseif 名称 == "惊魂掌" then
		if self:取奇经八脉是否有(攻击方.战斗编号, "持戒", {
				妙谛金莲 = 1,
				摄魂迷影 = 1
			}) then
			基础加成 = 基础加成 + 基础几率 * 2
		end
	elseif 名称 == "天罗地网" then
		基础几率 = 基础几率 - 35

		if 攻击方.百媚粘附 ~= nil then
			基础加成 = 基础加成 + 基础几率 * 1
		end

		if self:取奇经八脉是否有(编号, "迷瘴") then
			基础加成 = 基础加成 + 基础几率 * 0.2
		end
	end

	if 攻击方.法术状态.自矜 ~= nil then
		基础加成 = 基础加成 + 基础几率 * (攻击方.法术状态.自矜.加成 - 1)
	end

	if 名称 == "锢魂术" then
		if self:取奇经八脉是否有(编号, "索魂") then
			基础加成 = 基础加成 + 6 + self.回合数 * 0.1
		end

		if self:取奇经八脉是否有(编号, "伤魂", "勾魂阎罗") and self:取是否有异常状态(挨打方.战斗编号) then
			基础加成 = 基础加成 + 20
		end
	end

	if self:取奇经八脉是否有(编号, "弥愤") or self:取奇经八脉是否有(编号, "魂守") or self:取奇经八脉是否有(编号, "刺骨") then
		基础加成 = 基础加成 - 基础几率 * 0.3
	end

	if self:取奇经八脉是否有(挨打方.战斗编号, "百爪狂杀") then
		基础加成 = 基础加成 + 基础几率 * 0.2
	end

	if 名称 == "一笑倾城" and self:取奇经八脉是否有(编号, "嫣然") and 执行数 == 1 then
		基础加成 = 基础加成 + 8
	end

	if 攻击方.抑怒 ~= nil then
		基础加成 = 基础加成 + 基础几率 * (攻击方.抑怒 - 1)

		if 名称 == "娉婷袅娜" then
			基础加成 = 基础加成 + 10
		end
	end

	if qz(self.天气) == 1 then
		if self:取奇经八脉是否有(挨打方.战斗编号, "风姿") then
			基础加成 = 基础加成 - 基础几率 * 0.2
		end
	elseif qz(self.天气) == 2 then
	elseif qz(self.天气) == 3 then
	end

	if (名称 == "似玉生香" or 名称 == "莲步轻舞" or 名称 == "如花解语" or 名称 == "娉婷袅娜" or 名称 == "碎玉弄影" or 名称 == "一笑倾城") and 挨打方.法术状态.飞花摘叶 ~= nil then
		基础加成 = 基础加成 + 5
	end

	if 攻击方.返璞 ~= nil then
		基础加成 = 基础加成 - 10
	end

	if 挨打方.合纵 ~= nil or 挨打方.高级合纵 ~= nil or 挨打方.超级合纵 ~= nil then
		基础加成 = 基础加成 + 10
	end

	if 挨打方.独行 ~= nil then
		基础加成 = 基础加成 - 挨打方.独行
	end

	if self:取符石组合效果(挨打方, "百无禁忌") then
		基础加成 = 基础加成 - self:取符石组合效果(挨打方, "百无禁忌")
	end

	if 攻击方.法术状态.凝神术 ~= nil then
		基础加成 = 基础加成 + 10
	end

	if 挨打方.法术状态.狂怒 ~= nil and self:取奇经八脉是否有(挨打方.战斗编号, "不羁") then
		基础加成 = 基础加成 - 50
	end

	if 编号 ~= nil and self:取奇经八脉是否有(编号, "乾坤") and 名称 == "日月乾坤" then
		基础加成 = 基础加成 + 10
	end

	if 编号 ~= nil and self:取奇经八脉是否有(编号, "制约") then
		if 名称 == "催眠符" then
			基础加成 = 基础加成 - 5
		else
			基础加成 = 基础加成 + 5
		end
	end

	if 挨打方.慧心 ~= nil then
		基础加成 = 基础加成 - 6 * 挨打方.慧心
	end

	if 攻击方.奔雷 ~= nil then
		基础加成 = 基础加成 - 攻击方.奔雷
	end

	if 挨打方.门派 == "五庄观" then
		基础加成 = 基础加成 - 5
	end

	if 挨打方.法术状态.燃魂 ~= nil then
		基础加成 = 基础加成 - 20
	end

	if 挨打方.法术状态.还丹 ~= nil and 挨打方.法术状态.还丹.层数 >= 3 and self:取奇经八脉是否有(挨打方.战斗编号, "三元") then
		基础加成 = 基础加成 - 15
	end

	基础加成 = 基础加成 + (攻击方.特效封印 or 0) - (挨打方.特效抗封 or 0)

	if 攻击方.法术状态 ~= nil and 攻击方.法术状态.四面埋伏 ~= nil and 攻击方.气血 <= 攻击方.最大气血 * 0.8 then
		基础加成 = 基础加成 + 基础几率 * 0.1100000000000001
	end

	if 编号 ~= nil and self:取奇经八脉是否有(编号, "回敬") and 攻击方.气血 <= qz(攻击方.最大气血 * 0.5) then
		基础加成 = 基础加成 + 基础几率 * 0.1499999999999999
	elseif 编号 ~= nil and self:取奇经八脉是否有(编号, "不倦") and 名称 == "催眠符" then
		基础加成 = 基础加成 + 基础几率 * 0.19999999999999996
	elseif 名称 == "含情脉脉" and 编号 ~= nil and self:取奇经八脉是否有(编号, "忘川") and self:取是否有指定状态(编号, 目标, "瘴气") then
		基础加成 = 基础加成 + 10
	end

	if 挨打方.门派 == "阴曹地府" then
		基础加成 = 基础加成 + 基础几率 * -0.30000000000000004
	end

	if 挨打方.门派 == "化生寺" and (攻击方.门派 == "女儿村" or 攻击方.门派 == "盘丝岭") then
		基础加成 = 基础加成 + 基础几率 * -0.5
	end

	if 挨打方.战意 ~= nil and 挨打方.怒意 == nil and 挨打方.战意被动 ~= nil then
		基础加成 = 基础加成 - 挨打方.战意 * 挨打方.战意 / 2
	end

	if 挨打方.法术状态.花护 ~= nil then
		基础加成 = 基础加成 + 基础几率 * -0.5
	end

	if self:取奇经八脉是否有(挨打方.战斗编号, "兽王") then
		local aa = self:取友方召唤兽数量(挨打方.战斗编号)
		基础加成 = 基础加成 - 基础几率 * 0.02 * aa
	end

	基础几率 = math.max(基础几率 + 基础加成, 5 + 等级 / 2000)
	local 上限 = 90

	if 名称 == "日月乾坤" then
		上限 = 70
	elseif 名称 == "似玉生香" or 名称 == "含情脉脉" then
		上限 = 80
	end

	基础几率 = math.min(基础几率, 上限)

	if 名称 == "妖风四起" then
		基础几率 = 50
	end

	if 攻击方.名称 == "章鱼哥 " and self.战斗类型 == 100237 then
		基础几率 = 100
	end

	if 攻击方.必果 ~= nil then
		local aa = self:取是否有抗封技能(挨打方.战斗编号, "方寸山")

		if aa == false then
			基础几率 = 100
		end

		攻击方.必果 = 攻击方.必果 - 1

		if 攻击方.必果 <= 0 then
			攻击方.必果 = nil
		end
	end

	if 名称 == "顺势而为" and self:取是否有抗封技能(挨打方.战斗编号, "方寸山") == false then
		基础几率 = 100
	end

	if 取随机数(1, 10000) <= 基础几率 * 100 then
		if 攻击方.法术状态.自矜 ~= nil then
			self:取消状态("自矜", self.参战单位[编号])
		end

		if 攻击方.神符 ~= nil and 门派封印法术.方寸山[名称] ~= nil then
			攻击方.神符 = 攻击方.神符 + 1

			if 攻击方.神符 >= 3 and 攻击方.法术状态.神符 == nil then
				self:添加状态("神符", 攻击方)
				self:添加战斗流程提示("#P(神符)#R" .. 攻击方.名称 .. "#W使用门派封印法术连续三回合命中目标、获得了#R神符#W效果")

				攻击方.神符 = 0
			end
		end

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "陌宝") and 名称 == "日月乾坤" then
			挨打方.陌宝 = true
		end

		if 名称 == "日月乾坤" and 攻击方.法术状态.心随意动 ~= nil and 攻击方.法术状态.心随意动.清心羽客 ~= nil then
			攻击方.日月乾坤 = 2
		end

		if self:取奇经八脉是否有(编号, "迷梦") and 挨打方.法术状态.瘴气 == nil and ygsj() <= 60 and 攻击方.主动技能1.瘴气 ~= nil then
			self:添加状态("瘴气", 挨打方, 攻击方, self:取技能等级(编号, "瘴气"), 编号)
			self:流程处理状态(编号, {
				{
					增加状态 = "瘴气",
					挨打方 = 挨打方.战斗编号,
					状态 = {
						"瘴气"
					}
				}
			})
		end

		if self:取奇经八脉是否有(挨打方.战斗编号, "迷梦") and 攻击方.法术状态.瘴气 == nil and ygsj() <= 60 and 挨打方.主动技能1.瘴气 ~= nil then
			self:添加状态("瘴气", 攻击方, 挨打方, self:取技能等级(挨打方.战斗编号, "瘴气"), 挨打方.战斗编号)
			self:流程处理状态(编号, {
				{
					增加状态 = "瘴气",
					挨打方 = 编号,
					状态 = {
						"瘴气"
					}
				}
			})
		end

		if 顾盼生姿 then
			self:取消状态("顾盼生姿", self.参战单位[攻击方.召唤兽])
		end

		return true
	else
		if 攻击方.神符 ~= nil and 门派封印法术.方寸山[名称] ~= nil then
			攻击方.神符 = 0
		end

		if 攻击方.法术状态.自矜 == nil and self.参战单位[编号].自矜 ~= nil and ygsj() <= 40 then
			self:添加状态("自矜", self.参战单位[编号], nil, nil, 编号)
		end

		return false
	end
end

function 战斗处理类:刷新雾杀(目标, 获得数量, 编号, 等级)
	if self:负面技能施加判断(目标, "雾杀", 编号) then
		local n = 目标

		if self.参战单位[n].法术状态.雾杀 == nil then
			self:添加状态("雾杀", self.参战单位[n], self.参战单位[编号], 等级, 编号, 获得数量)
			self:流程处理状态(n, {
				{
					增加状态 = "雾杀",
					挨打方 = n
				}
			})
		else
			self.参战单位[n].法术状态.雾杀.层数 = math.min(self.参战单位[n].法术状态.雾杀.层数 + 获得数量, 3)
		end
	end
end

function 战斗处理类:刷新风灵(编号, 获得数量, 突破上限)
	获得数量 = 获得数量 or 1

	if self.参战单位[编号].风灵 == nil then
		return
	end

	local n = 编号

	if self.参战单位[n].法术状态.风灵 == nil then
		if 获得数量 > 0 then
			self:添加状态("风灵", self.参战单位[n], self.参战单位[n], 获得数量, n)
		end
	else
		local cs = math.min(self.参战单位[n].法术状态.风灵.层数 + 获得数量, 6)

		self:取消状态("风灵", self.参战单位[n])

		if cs > 0 then
			self:添加状态("风灵", self.参战单位[n], self.参战单位[n], cs, n)
		end

		if 获得数量 < 0 and self:取奇经八脉是否有(编号, "风魂") then
			self:添加护盾(编号, self.参战单位[n].等级 * 2 * -获得数量, n)
		end
	end
end

function 战斗处理类:刷新狮魂(编号, 获得数量, 突破上限)
	获得数量 = 获得数量 or 1

	if self.参战单位[编号].狮魂 == nil or self.参战单位[编号].召唤兽 == nil then
		return
	end

	local n = self.参战单位[编号].召唤兽

	if self.参战单位[n].法术状态.狮魂 == nil then
		self:添加状态("狮魂", self.参战单位[n], nil, nil, nil, 获得数量)
	else
		self.参战单位[n].法术状态.狮魂.回合 = 999
		local cs = self.参战单位[n].法术状态.狮魂.层数 + 获得数量

		if 突破上限 == nil then
			cs = math.min(cs, math.max(3, self.参战单位[n].法术状态.狮魂.层数))
		end

		self.参战单位[n].法术状态.狮魂.层数 = cs
	end

	self.参战单位[n].法术状态.狮魂.主人 = 编号

	self:更新单个法术状态(n, "狮魂")

	if self:取奇经八脉是否有(编号, "护盾") and self.参战单位[编号].被动技能.狂兽诀 ~= nil then
		self:添加护盾(n, self.参战单位[编号].被动技能.狂兽诀 * 3, 编号)
	end
end

function 战斗处理类:刷新人参娃娃(编号, 获得数量)
	获得数量 = 获得数量 or 1

	if self.参战单位[编号].法术状态.还丹 == nil then
		self:添加状态("还丹", self.参战单位[编号], nil, nil, nil, 获得数量)
	else
		local cs = self.参战单位[编号].法术状态.还丹.层数 + 获得数量

		self:取消状态("还丹", self.参战单位[编号])
		self:添加状态("还丹", self.参战单位[编号], nil, nil, nil, cs)
	end
end

function 战斗处理类:刷新无所遁形(编号, 等级)
	local 加成 = 0

	if self:取奇经八脉是否有(编号, "添威", "通天行者") and ygsj() <= 20 then
		加成 = 1
	end

	if self.参战单位[编号].法术状态.无所遁形 == nil then
		self:添加状态("无所遁形", self.参战单位[编号], self.参战单位[编号], 等级, 编号, 2 + 加成)

		return true
	elseif self.参战单位[编号].法术状态.无所遁形.层数 > 5 then
		return
	else
		local cs = math.min(self.参战单位[编号].法术状态.无所遁形.层数 + 1 + cs, 5)
		local hh = self.参战单位[编号].法术状态.无所遁形.回合 + 0

		self:取消状态("无所遁形", self.参战单位[编号])
		self:添加状态("无所遁形", self.参战单位[编号], self.参战单位[编号], 等级, 编号, cs)

		self.参战单位[编号].法术状态.无所遁形.回合 = hh

		return true
	end
end

function 战斗处理类:添加暗器毒(目标, 编号)
	if self:负面技能施加判断(目标, "毒") then
		local 等级 = math.max(self.参战单位[编号].等级, 1)

		self:添加状态("毒", self.参战单位[目标], self.参战单位[编号], 等级, 编号)

		self.参战单位[目标].法术状态.毒.回合 = qz(等级 / 40) + 4
		self.参战单位[目标].法术状态.毒.暗器毒 = 1

		self:刷新淬芒(编号, 1)

		if self:取奇经八脉是否有(编号, "天香") then
			self:增加愤怒(编号, 6)
		end

		return true
	end

	return false
end

function 战斗处理类:刷新淬芒(编号, 获得数量)
	if 编号 ~= nil and self:取奇经八脉是否有(编号, "淬芒") then
		if self.参战单位[编号].法术状态.淬芒 == nil then
			self:添加状态("淬芒", self.参战单位[编号], self.参战单位[编号], 1)
		else
			cs = self.参战单位[编号].法术状态.淬芒.层数 + 0
			cs = math.min(cs + 1, 2)

			self:取消状态("淬芒", self.参战单位[编号])
			self:添加状态("淬芒", self.参战单位[编号], self.参战单位[编号], cs)
		end
	end
end

function 战斗处理类:刷新五行珠(编号, 获得五行)
	if self.参战单位[编号].五行珠 == nil then
		return
	end

	if self.参战单位[编号].法术状态.五行珠 == nil then
		self:添加状态("五行珠", self.参战单位[编号])
	end

	if (self.参战单位[编号].法术状态.五行珠[获得五行] or 0) < 1 then
		if self:取奇经八脉是否有(编号, "顿悟") then
			self:增加愤怒(编号, (self.参战单位[编号].法术状态.五行珠.层数 or 0) + 1)
		end

		if self:取奇经八脉是否有(编号, "无尽") then
			self.参战单位[编号].伤害 = self.参战单位[编号].伤害 + 6
		end
	end

	self.参战单位[编号].法术状态.五行珠[获得五行] = 1
	self.参战单位[编号].法术状态.五行珠.回合 = 999
	local cs = 0
	local 五行 = {
		"土",
		"木",
		"火",
		"金",
		"水"
	}
	self.参战单位[编号].法术状态.五行珠.消耗五行 = {}

	for i = 1, #五行 do
		if self.参战单位[编号].法术状态.五行珠[五行[i]] ~= nil and self.参战单位[编号].法术状态.五行珠[五行[i]] > 0 then
			cs = cs + self.参战单位[编号].法术状态.五行珠[五行[i]]
			self.参战单位[编号].法术状态.五行珠.消耗五行[五行[i]] = self.参战单位[编号].法术状态.五行珠[五行[i]]
		end
	end

	self.参战单位[编号].法术状态.五行珠.层数 = cs + 0

	self:更新单个法术状态(编号, "五行珠")
end

function 战斗处理类:消耗乐韵(编号, 消耗数量)
	if self.参战单位[编号].法术状态.乐韵 ~= nil then
		self.参战单位[编号].法术状态.乐韵.层数 = self.参战单位[编号].法术状态.乐韵.层数 - 1

		if self.参战单位[编号].法术状态.乐韵.层数 <= 0 then
			self:取消状态("乐韵", self.参战单位[编号])
		end

		if self.参战单位[编号].夺目 ~= nil then
			if self.参战单位[编号].法术状态.夺目 == nil then
				self:添加状态("夺目", self.参战单位[编号])

				self.参战单位[编号].法术状态.夺目.层数 = 1
			else
				self.参战单位[编号].法术状态.夺目.层数 = self.参战单位[编号].法术状态.夺目.层数 + 1
				self.参战单位[编号].法术状态.夺目.回合 = 3
			end
		end
	end
end

function 战斗处理类:刷新战意(编号, 获得战意, 技能名称, 指定超级战意, 不提示)
	if (获得战意 or 0) == 0 then
		return
	end

	local 涡流 = false
	local 原本 = (self.参战单位[编号].战意 or 0) + (self.参战单位[编号].超级战意 or 0)
	local 详情 = {
		战意 = self.参战单位[编号].战意 or 0,
		超级战意 = self.参战单位[编号].超级战意 or 0
	}
	self.参战单位[编号].消耗超级战意 = nil

	if 获得战意 > 0 then
		if self:取奇经八脉是否有(编号, "超级战意") then
			for i = 1, 获得战意 do
				if 取随机数() <= 20 or 指定超级战意 ~= nil then
					if qz(self.天气) == 1 and self:取奇经八脉是否有(编号, "涡流") then
						涡流 = true
					end

					if 详情.超级战意 < 3 then
						详情.超级战意 = 详情.超级战意 + 1
					else
						详情.战意 = 详情.战意 + 1
					end
				else
					详情.战意 = 详情.战意 + 1
				end
			end
		else
			详情.战意 = 详情.战意 + 获得战意
		end
	elseif 技能名称 ~= "天眼神通" then
		if math.abs(获得战意) <= 详情.超级战意 then
			详情.超级战意 = 详情.超级战意 + 获得战意
			self.参战单位[编号].消耗超级战意 = (self.参战单位[编号].消耗超级战意 or 0) + math.abs(获得战意)
		else
			获得战意 = 获得战意 + 详情.超级战意
			self.参战单位[编号].消耗超级战意 = 详情.超级战意 + 0
			详情.超级战意 = 0
			详情.战意 = 详情.战意 + 获得战意
		end
	elseif math.abs(获得战意) <= 详情.战意 then
		详情.战意 = 详情.战意 + 获得战意
	else
		获得战意 = 获得战意 + 详情.战意
		详情.战意 = 0
		self.参战单位[编号].消耗超级战意 = math.min(math.abs(获得战意), 详情.超级战意)
		详情.超级战意 = 详情.超级战意 + 获得战意
	end

	详情.战意 = math.min(math.max(详情.战意, 0), 6)
	详情.超级战意 = math.max(详情.超级战意, 0)

	if 涡流 then
		详情.超级战意 = 详情.超级战意 + 详情.战意
		详情.战意 = 0
	end

	self.参战单位[编号].战意 = 详情.战意 + 0
	self.参战单位[编号].超级战意 = 详情.超级战意 + 0
	local 战意差 = (self.参战单位[编号].战意 or 0) + (self.参战单位[编号].超级战意 or 0) - 原本

	if 战意差 < 0 then
		if self:取奇经八脉是否有(编号, "拍岸") then
			self:减少技能冷却(编号, "天眼神通", math.abs(战意差))
			self:减少技能冷却(编号, "风云再现", math.abs(战意差))
		end

		if self:取奇经八脉是否有(编号, "煞气") then
			self.参战单位[编号].煞气 = 1.06
		end

		if self:取奇经八脉是否有(编号, "天泽") and (self.参战单位[编号].战意 or 0) + (self.参战单位[编号].超级战意 or 0) == 0 and ygsj() <= 20 then
			self:刷新战意(编号, 1, 技能名称, nil, "不提示")
		end

		if (self.参战单位[编号].消耗超级战意 or 0) > 0 and self:取奇经八脉是否有(编号, "乘势") then
			if self.参战单位[编号].法术状态.强袭 == nil then
				self:添加状态("强袭", self.参战单位[编号], self.参战单位[编号], self.参战单位[编号].等级, 编号)
			else
				self.参战单位[编号].法术状态.强袭.回合 = 3
			end
		end
	end

	if (self.参战单位[编号].消耗超级战意 or 0) <= 0 then
		self.参战单位[编号].消耗超级战意 = nil
	end

	if 不提示 == nil then
		if (self.参战单位[编号].超级战意 or 0) > 0 then
			self:添加提示(self.参战单位[编号].玩家id, 编号,
				"#S" ..
				self.参战单位[编号].名称 .. "#Y/当前可使用：战意#R/" .. self.参战单位[编号].战意 .. "#Y/点、超级战意#R" .. self.参战单位[编号].超级战意 .. "#Y/点")
		else
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#S" .. self.参战单位[编号].名称 .. "#Y/当前可使用：战意#R/" .. self.参战单位[编号].战意 .. "#Y/点")
		end
	end
end

function 战斗处理类:物攻技能计算(编号, 名称, 等级, 其他)
	self.参战单位[编号].煞气 = nil
	self.参战单位[编号].消耗超级战意 = nil
	local 名称1 = ""
	local 指定目标, 不保护, 消耗 = nil

	if 其他 ~= nil then
		指定目标 = 其他.指定目标
		不保护 = 其他.不保护
		消耗 = 其他.消耗

		if 其他.消耗战意 ~= nil then
			self:刷新战意(编号, 其他.消耗战意)
		end
	end

	if 名称 == "后发制人" then
		if self:取行动状态(编号) == false or self:取目标状态(编号, self.参战单位[编号].法术状态.后发制人.目标, 1) == false then
			self:取消状态(名称, self.参战单位[编号])

			self.战斗流程[#self.战斗流程 + 1] = {
				状态 = "后发制人",
				流程 = 610,
				攻击方 = 编号,
				挨打方 = {
					{
						挨打方 = 1
					}
				}
			}

			return
		else
			self.参战单位[编号].指令.目标 = self.参战单位[编号].法术状态.后发制人.目标
		end
	end

	local 目标 = 指定目标 or self.参战单位[编号].指令.目标

	if 名称 == "水击三千1" then
		名称1 = "水击三千1"
		目标 = self:取对方气血百分比最低(编号)
		名称 = "水击三千"
	elseif 名称 == "披挂上阵" then
		名称1 = "披挂上阵"
		名称 = "横扫千军"
		self.参战单位[编号].披挂上阵 = 1
	elseif 名称 == "风云再现" then
		名称1 = "风云再现"
		local aa = {
			"浪涌",
			"裂石",
			"惊涛怒",
			"断岳势",
			"翻江搅海",
			"天崩地裂"
		}
		名称 = aa[取随机数(1, #aa)]
	elseif 名称 == "风雷斩" then
		self.参战单位[编号].电光 = nil

		if self.参战单位[编号].法术状态.雷怒霆激 == nil and self.参战单位[编号].法术状态.霹雳弦惊 == nil and self:取奇经八脉是否有(编号, "电光") and ygsj() <= 50 then
			local aa = ygsj()

			if aa <= 45 then
				self:添加状态("雷怒霆激", self.参战单位[编号], self.参战单位[编号], 等级, 编号)

				self.参战单位[编号].法术状态.雷怒霆激.回合 = 1
				self.参战单位[编号].电光 = "#P(电光)#R" .. self.参战单位[编号].名称 .. "#W获得了临时1回合的#S雷怒霆激#W状态！"
			elseif aa <= 90 then
				self:添加状态("霹雳弦惊", self.参战单位[编号], self.参战单位[编号], 等级, 编号)

				self.参战单位[编号].法术状态.霹雳弦惊.回合 = 1
				self.参战单位[编号].电光 = "#P(电光)#R" .. self.参战单位[编号].名称 .. "#W获得了临时1回合的#S霹雳弦惊#W状态！"
			else
				self:添加状态("雷怒霆激", self.参战单位[编号], self.参战单位[编号], 等级, 编号)

				self.参战单位[编号].法术状态.雷怒霆激.回合 = 1

				self:添加状态("霹雳弦惊", self.参战单位[编号], self.参战单位[编号], 等级, 编号)

				self.参战单位[编号].法术状态.霹雳弦惊.回合 = 1
				self.参战单位[编号].电光 = "#P(电光)#R" .. self.参战单位[编号].名称 .. "#W获得了临时1回合的#S霹雳弦惊和雷怒霆激#W状态！"
			end
		end
	end

	local 目标数 = self:取目标数量(self.参战单位[编号], 名称, 等级, 编号)
	local 目标 = self:取多个敌方目标(编号, 目标, 目标数)

	if #目标 > 0 and self.参战单位[编号].九黎法术列表 ~= nil then
		if self.参战单位[编号].九黎记录目标 == nil or self:取目标状态(编号, self.参战单位[编号].九黎记录目标, 1) == false then
			self.参战单位[编号].九黎记录目标 = 目标[1] + 0
		end

		if 目标[1] ~= 指定目标 and 目标[1] ~= self.参战单位[编号].指令.目标 and #目标 == 1 and 目标[1] ~= self.参战单位[编号].九黎记录目标 and self:取目标状态(编号, self.参战单位[编号].九黎记录目标, 1) then
			目标[1] = self.参战单位[编号].九黎记录目标 + 0
		end
	end

	if 名称 == "牵魂蛛丝" and #目标 > 0 then
		if self.参战单位[目标[1]].法术状态.天罗地网 == nil then
			self:添加状态("天罗地网", self.参战单位[目标[1]], self.参战单位[编号], 等级, 编号)

