				if self.参战单位[编号].三荒尽灭可选["编号" .. self.参战单位[编号].三荒尽灭可选[aa]] == nil then
					table.remove(self.参战单位[编号].三荒尽灭可选, aa)
				else
					aa = aa + 1
				end
			end

			for i = 1, #待定 do
				if i <= #self.参战单位[编号].三荒尽灭可选 then
					目标[待定[i]] = self.参战单位[编号].三荒尽灭可选[i]
				else
					break
				end
			end
		end
	elseif 名称 == "力辟苍穹" then
