			gl = gl + 4
		end

		if 编号 ~= nil and self:取敌方拥有指定状态人数(编号, "毒", "暗器毒") == 0 then
			gl = gl + 6
		end

		for n = 1, #目标 do
			if ygsj() <= gl then
				self:添加暗器毒(目标[n], 编号)
			end
		end
	end

	if self.反击挨打返回 == 1 and self:取目标状态(编号, 编号, 3) and self.物攻流程 < self.普攻被反击流程 then
		self.战斗流程[self.普攻被反击流程].挨打返回 = true
		self.反击挨打返回 = 0
	else
		self.反击挨打返回 = 0
	end

	if 名称1 == "披挂上阵" then
		self.参战单位[编号].披挂上阵 = nil
	elseif 名称1 == "最佳搭档" then
		local bb = self.参战单位[编号].召唤兽

		if bb ~= nil and self.参战单位[bb] ~= nil and self:取目标状态(bb, 目标[1], 1) then
			self.参战单位[bb].最佳搭档 = 编号

			self:物攻技能计算(bb, "幼狮之搏", self:取技能等级(bb, "幼狮之搏"), {
				不保护 = true,
				指定目标 = 目标[1]
			})
		end

		self.参战单位[编号].最佳搭档 = nil
		self.参战单位[bb].最佳搭档 = nil
	end

	if 名称 == "破血狂攻" or 名称 == "破碎无双" or 名称 == "弱点击破" then
		if self:取奇经八脉是否有(编号, "变奏") then
			self:消耗乐韵(编号, 1)
		end
	elseif self.参战单位[编号].踏歌 ~= nil and self.参战单位[编号].踏歌.重拍技能[名称] ~= nil then
		self:消耗乐韵(编号, 1)
	end

	if 名称 == "破釜沉舟" and self.参战单位[编号].执剑 == nil and self:取奇经八脉是否有(编号, "执剑") and (self.同门派减伤[self.参战单位[编号].队伍].大唐官府 or 0) <= 1 then
		self.参战单位[编号].执剑 = 1
	elseif 名称 == "破血狂攻" then
		if self:取奇经八脉是否有(编号, "蓄势") then
			self:刷新战意(编号, 1)
		end
	elseif 名称 == "连环击" then
		self.参战单位[编号].肝胆连环击 = 1
	elseif 名称 == "鹰击" then
		self.参战单位[编号].死地 = nil
		self.参战单位[编号].肝胆鹰击 = 1
	elseif 名称 == "剑意莲心" then
		self.参战单位[编号].消耗五行 = nil
	elseif 名称 == "威仪九霄" then
		self.参战单位[编号].威仪九霄 = 0
	elseif 名称 == "风雷斩" then
		self.参战单位[编号].天雷灌注霹雳 = nil
	elseif 名称 == "百爪狂杀" then
		self:取消状态("噬毒·百爪狂杀", self.参战单位[编号])
	elseif 名称 == "天神怒斩" then
		self.参战单位[编号].天神怒斩次数 = (self.参战单位[编号].天神怒斩次数 or 0) + 1
	elseif 名称 == "天崩地裂" or 名称 == "翻江搅海" then
		self:减少技能冷却(编号, "天神怒斩", 1)
	elseif 名称1 == "风云再现" then
		local 消耗战意 = 取随机数(1, 5)

		if 消耗战意 <= self.参战单位[编号].战意 then
			self:添加战斗流程提示("#P(风云再现)#W本次随机到了#Y" .. 消耗战意 .. "#W、#R" .. self.参战单位[编号].名称 .. "#W消耗相应战意继续攻击。")
			self:物攻技能计算(编号, 名称1, 等级, {
				消耗 = "不消耗",
				消耗战意 = 消耗战意
			})
		else
			self:添加战斗流程提示("#P(风云再现)#W本次随机到了#Y" .. 消耗战意 .. "#W、#R" .. self.参战单位[编号].名称 .. "#W战意不足。")
		end
	end

	self.参战单位[编号].煞气 = nil
	self.参战单位[编号].消耗超级战意 = nil
end

function 战斗处理类:召唤状态加回合()
	if (self.回合数 or 0) >= 1 and self.召唤加回合 == 1 then
		self.召唤加回合 = 0

		return 1
	end

	self.召唤加回合 = 0

	return 0
end

function 战斗处理类:添加状态(名称, 攻击方, 挨打方, 等级, 攻击编号, 境界)
	if 攻击方 == nil then
		return
	end

	if 攻击编号 == nil then
		if 挨打方 == nil then
			攻击编号 = 攻击方.战斗编号
		else
			攻击编号 = 挨打方.战斗编号
		end
	end

	等级 = math.max(等级 or 攻击方.等级, 1)

	if 名称 == "莲心剑意" and 攻击方.法术状态[名称] ~= nil then
		攻击方.法术状态[名称] = nil

		return
	elseif self:取是否增益状态(名称) == true and 攻击方.信仰 ~= nil then
		攻击方.法术状态[名称] = {
			回合 = 1,
			信仰不生效 = 1,
			攻击编号 = 攻击编号,
			境界 = 境界
		}

		if self.待消除状态[攻击方.战斗编号] == nil then
			self.待消除状态[攻击方.战斗编号] = {}
		end

		self.待消除状态[攻击方.战斗编号][名称] = 1

		return
	end

	local 回合修正 = 0

	if 毒状态列表1[名称] ~= nil then
		self:取消所有毒状态(攻击方.战斗编号)
	end

	if 攻击方.法术状态[名称] ~= nil then
		return
	elseif 名称 == "碎星诀" and 攻击方.法术状态.镇魂诀 ~= nil then
		return
	elseif 名称 == "镇魂诀" and 攻击方.法术状态.碎星诀 ~= nil then
		return
	end

	攻击方.法术状态[名称] = {
		攻击编号 = 攻击编号,
		境界 = 境界
	}

	if 攻击编号 ~= nil and self.参战单位[攻击编号].机巧 ~= nil and (self:群体封印技能(名称) or self:封印技能(名称)) then
		攻击方.法术状态[名称].机巧 = 1
	end

	if 攻击方.普攻躲避率 == nil then
		攻击方.普攻躲避率 = 0
	end

	local 普攻躲避率1 = 攻击方.普攻躲避率
	local 伤害1 = 攻击方.伤害
	local 防御1 = 攻击方.防御
	local 速度1 = 攻击方.速度
	local 法防1 = 攻击方.法防
	local 躲避1 = 攻击方.躲避
	local 命中1 = 攻击方.命中
	local 灵力1 = 攻击方.灵力
	local 法伤1 = 攻击方.法伤
	local 最大气血1 = 攻击方.最大气血
	local 最大魔法1 = 攻击方.最大魔法
	local 治疗能力1 = 攻击方.治疗能力
	local 回合 = 2
	local 伤害 = 0
	local 防御 = 0
	local 速度 = 0
	local 法防 = 0
	local 躲避 = 0
	local 类型 = 1
	local 命中 = 0
	local 灵力 = 0
	local 法伤 = 0
	local 最大气血 = 0
	local 最大魔法 = 0
	local 法术躲避率 = 0
	local 四系法术吸收概率 = 0
	local 抵抗封印等级 = 0
	local 治疗能力 = 0
	local 封印命中等级 = 0
	local 封印抵抗率 = 0
	local 封印命中率 = 0
	local 治疗效果 = 0
	local 物理暴击等级 = 0
	local 法术暴击等级 = 0
	local 抗物理暴击等级 = 0
	local 抗法术暴击等级 = 0
	local 穿刺等级 = 0
	local 狂暴等级 = 0
	local 格挡值 = 0
	local 愤怒 = 0
	local 魔法回复 = 0
	local 气血回复 = 0
	local 魔法消耗 = 0
	local 逃跑概率 = 0
	local 概率逃跑 = 0
	local 说明 = 0
	local 护盾值 = 0
	local 普攻躲避率 = 0
	local 物理暴伤 = 0
	local 法术暴伤 = 0
	local 必杀 = 0
	local 法暴 = 0
	local 法连 = 0
	local 连击 = 0
	local 编号 = 攻击编号

	if 名称 == "横扫千军" then
		回合 = 2

		if 攻击方.门派 == "大唐官府" and 攻击编号 ~= nil and self:取奇经八脉是否有(攻击编号, "连破") and self:取玩家战斗() and ygsj() <= 30 then
			回合 = 回合 - 1
		end

		if 攻击方.门派 == "大唐官府" and 攻击编号 ~= nil and self:取奇经八脉是否有(攻击编号, "连破") then
			回合 = 回合 - 1
		end

		if 攻击方.门派 == "大唐官府" and 攻击编号 ~= nil and self:取奇经八脉是否有(攻击编号, "連破") then
			local aa = 0

			if qz(self.天气) == 2 and self:取奇经八脉是否有(攻击编号, "勇念") then
				aa = aa + 15
			end

			if self:取奇经八脉是否有(攻击编号, "熟练") and (self.同门派减伤[self.参战单位[攻击编号].队伍].大唐官府 or 0) <= 1 then
				aa = aa + 17
			end

			if self.参战单位[攻击编号].破势 ~= nil then
				aa = aa + 40
			end

			if self.参战单位[攻击编号].孤勇 ~= nil then
				aa = aa + 25
				self.参战单位[攻击编号].孤勇 = nil
			end

			if ygsj() <= 5 + aa or self:取奇经八脉是否有(攻击编号, "勇进") and 攻击方.勇进 == nil or 攻击方.亢强 ~= nil then
				回合 = 回合 - 1
				攻击方.勇进 = 1
				攻击方.亢强 = nil
			end
		end
	elseif 名称 == "天狐之舞" then
		回合 = 1
		类型 = 2
	elseif 名称 == "荡魔" then
		回合 = 2
		类型 = 2
		攻击方.法术状态[名称].造成伤害 = 12
	elseif 名称 == "齐天神通" then
		回合 = 4
		类型 = 2
		封印抵抗率 = -30
	elseif 名称 == "九幽除名" then
		回合 = 1
		类型 = 2
		攻击方.法术状态[名称].复活概率 = 30 + self:取技能等级(攻击方.战斗编号, "九幽除名") * 0.33

		if 攻击方.斗志 ~= nil then
			攻击方.法术状态[名称].复活概率 = 攻击方.法术状态[名称].复活概率 * 1.06
		end

		攻击方.法术状态[名称].当前气血 = 攻击方.气血 + 0
	elseif 名称 == "铸兵锤" then
		回合 = 2
		类型 = 2
		封印抵抗率 = 境界 * 1 + 3
	elseif 名称 == "舍身取义" then
		回合 = 999
		类型 = 1
		防御 = 防御1 * 境界 * 0.05
		法防 = 法防1 * 境界 * 0.05
		攻击方.法术状态[名称].次数 = 境界 + 0
	elseif 名称 == "炎魂" then
		回合 = 1
		类型 = 2
		local jc = qz(防御1 * (500 + ygsj(500)) / 10000)
		伤害 = jc
		防御 = -jc

		if self:取奇经八脉是否有(攻击编号, "魂力") then
			伤害 = qz(伤害 * 1.6)
		end
	elseif 名称 == "怒哮" then
		回合 = 999
		类型 = 2
	elseif 名称 == "焰火烁星" then
		回合 = 999
		类型 = 2
		攻击方.法术状态[名称].说明1 = "赐福：焰火烁星攻击目标数翻倍"
	elseif 名称 == "顾盼生姿" then
		回合 = 999
		类型 = 2
		攻击方.法术状态[名称].层数 = 境界 + 0
		攻击方.法术状态[名称].等级 = 境界 * 等级 * 0.5
		攻击方.法术状态[名称].说明1 = "提升主人" .. 攻击方.法术状态[名称].等级 .. "封印命中等级"
	elseif 名称 == "好梦连连" then
		回合 = 999
		类型 = 2

		if 等级 == 1 then
			攻击方.法术状态[名称].惊梦 = 1
			攻击方.法术状态[名称].造成伤害 = 30
			攻击方.法术状态[名称].等级 = 1
		else
			攻击方.法术状态[名称].造成伤害 = -5
			攻击方.法术状态[名称].睡梦 = 1
			攻击方.法术状态[名称].等级 = 2
		end
	elseif 名称 == "凋零之歌" then
		回合 = 2
		类型 = 2
		攻击方.法术状态[名称].受到法术伤害 = 16

		if 攻击编号 ~= nil and self.参战单位[攻击编号].风灵 ~= nil and self.参战单位[攻击编号].法术状态.风灵 ~= nil then
			local cs = self.参战单位[攻击编号].法术状态.风灵.层数 + 0
			攻击方.法术状态[名称].受到法术伤害 = 攻击方.法术状态[名称].受到法术伤害 + 2 * cs

			for i = 1, qz(3 + cs * 0.5) do
				local mb = self:取单个敌方目标(攻击编号)

				self:刷新雾杀(mb, 1, 攻击编号, self:取技能等级(攻击编号, "雾杀"))
			end

			self:取消状态("风灵", self.参战单位[攻击编号])
		end
	elseif 名称 == "蔓延" then
		回合 = 2
		类型 = 2
		攻击方.法术状态[名称].造成伤害 = 20
	elseif 名称 == "迅风出击" then
		回合 = 999
		类型 = 2
		攻击方.法术状态[名称].层数 = 取随机数(1, 2)

		if qz(self.天气) == 1 then
			攻击方.法术状态[名称].层数 = 2
		end
	elseif 名称 == "佛眷" then
		回合 = 3
		类型 = 2
		攻击方.法术状态[名称].说明1 = "受到药品或来自" .. self.参战单位[攻击编号].名称 .. "的治疗量提高30%"
	elseif 名称 == "噬魂" then
		回合 = 1
		类型 = 2
		攻击方.法术状态[名称].造成物理伤害 = 10
		攻击方.法术状态[名称].造成法术伤害 = 10
	elseif 名称 == "陷阱" then
		回合 = 1
		类型 = 1
		伤害 = qz((挨打方.被动技能.阴风绝章 or 0) * 1.5)
		法伤 = qz((挨打方.被动技能.阴风绝章 or 0) * 1.5)
	elseif 名称 == "绝处逢生" then
		回合 = 3
		类型 = 2
		速度 = qz1(速度1 * 0.1)
	elseif 名称 == "血潮" then
		回合 = 3
		类型 = 2
		封印命中等级 = 200
	elseif 名称 == "燃血术·妙谛金莲" then
		回合 = 999
		类型 = 2
		攻击方.法术状态[名称].层数 = 1

		if 攻击编号 ~= nil and self:取奇经八脉是否有(攻击编号, "血潮", "妙谛金莲") then
			攻击方.法术状态[名称].层数 = 2
		end
	elseif 名称 == "燃血术·摄魂迷影" then
		回合 = 999
		类型 = 2
		攻击方.法术状态[名称].层数 = 1
	elseif 名称 == "燃血术·幽冥巫煞" then
		回合 = 999
		类型 = 2
		攻击方.法术状态[名称].层数 = 1
	elseif 名称 == "魂魄" then
		回合 = 4

		if 攻击编号 ~= nil and self:取奇经八脉是否有(攻击编号, "踏魄") then
			攻击方.法术状态[名称].造成物理伤害 = -6
			攻击方.法术状态[名称].造成法术伤害 = -6
		end

		if 境界 ~= nil and 境界 == 3447 then
			攻击方.法术状态[名称].攻击编号 = nil
		end
	elseif 名称 == "强袭" then
		回合 = 3
		类型 = 2
		攻击方.法术状态[名称].造成物理伤害 = 16
	elseif 名称 == "天眼神通" then
		回合 = 5
		类型 = 2
		local aa = ygsj()
		local ys = 1
		local gl = {
			50,
			85
		}

		if 攻击编号 ~= nil and self:取奇经八脉是否有(攻击编号, "盛势") then
			gl[1] = gl[1] * 0.5
		end

		if 攻击编号 ~= nil and self:取奇经八脉是否有(攻击编号, "天眼") then
			local aa1 = qz((100 - gl[2]) * 0.8)
			gl[1] = gl[1] - qz(aa1 / (gl[1] / gl[2]))
			gl[2] = gl[2] - aa1
		end

		if gl[2] < aa then
			ys = 3
		elseif gl[1] < aa then
			ys = 2
		end

		攻击方.法术状态[名称].层数 = ys
		攻击方.法术状态[名称].智眼 = 1

		if ys >= 2 then
			攻击方.法术状态[名称].怒眼 = 1

			if ys >= 3 then
				攻击方.法术状态[名称].天眼 = 1
				必杀 = 30

				if 攻击编号 ~= nil and self:取奇经八脉是否有(攻击编号, "怒眼") then
					必杀 = qz(必杀 * 1.32)
				end
			end
		end
	elseif 名称 == "八戒上身" then
		回合 = 1
	elseif 名称 == "偷龙转凤" then
		回合 = 8
		类型 = 2
		攻击方.法术状态[名称].魔法 = qz(等级 / 10)
		攻击方.法术状态[名称].说明1 = "每回合恢复" .. qz(等级 / 10) .. "点魔法"
	elseif 名称 == "魍魉追魂" then
		回合 = 999
		local gs = self:取我方拥有指定状态人数(攻击方.战斗编号, "魍魉追魂")
		攻击方.法术状态[名称].造成物理伤害 = 4 + gs * 2
		攻击方.法术状态[名称].造成法术伤害 = 4 + gs * 2
	elseif 名称 == "噬毒" then
		回合 = 2
		防御 = 50
	elseif 名称 == "噬毒·六道无量" then
		回合 = 999
	elseif 名称 == "噬毒·百爪狂杀" then
		回合 = 999
	elseif 名称 == "六道无量" then
