		伤害 = qz(防御1 * 0.53 ^ math.min(1 + math.max(防御1 - 500, 0) / 防御1, 1.44))
		防御 = -防御1 * 0.3
	end

	if 攻击方.永恒 ~= nil and self:取是否增益状态(名称, true) == true then
		回合 = 回合 + math.min((回合 - 回合修正) * 攻击方.永恒, 攻击方.永恒 * 6)
	end

	if 命中 > 0 then
		伤害 = 伤害 + qz1(命中 / 3)
	end

	攻击方.法术状态[名称].伤害 = 伤害
	攻击方.法术状态[名称].防御 = 防御
	攻击方.法术状态[名称].速度 = 速度
	攻击方.法术状态[名称].法防 = 法防
	攻击方.法术状态[名称].躲避 = 躲避
	攻击方.法术状态[名称].回合 = 回合
