		攻击方.最大魔法 = 攻击方.最大魔法 - 最大魔法
		攻击方.物理暴伤 = (攻击方.物理暴伤 or 2) - 物理暴伤
		攻击方.法术暴伤 = (攻击方.法术暴伤 or 2) - 法术暴伤
		攻击方.必杀 = (攻击方.必杀 or 基础暴击率) - 必杀
		攻击方.法暴 = (攻击方.法暴 or 基础法暴率) - 法暴
		攻击方.法连 = (攻击方.法连 or 0) - 法连
		攻击方.连击 = (攻击方.连击 or 0) - 连击
		攻击方.治疗能力 = (攻击方.治疗能力 or 0) - 治疗能力
		攻击方.治疗效果 = (攻击方.治疗效果 or 100) - 治疗能力
		攻击方.封印抵抗率 = (攻击方.封印抵抗率 or 0) - 封印抵抗率
		攻击方.封印命中率 = (攻击方.封印命中率 or 0) - 封印命中率
		攻击方.普攻躲避率 = (攻击方.普攻躲避率 or 0) - 普攻躲避率
		攻击方.法术躲避率 = (攻击方.法术躲避率 or 0) - 法术躲避率
		攻击方.抵抗封印等级 = (攻击方.抵抗封印等级 or 0) - 抵抗封印等级
		攻击方.封印命中等级 = (攻击方.封印命中等级 or 0) - 封印命中等级
		攻击方.物理暴击等级 = (攻击方.物理暴击等级 or 0) - 物理暴击等级
		攻击方.法术暴击等级 = (攻击方.法术暴击等级 or 0) - 法术暴击等级
		攻击方.抗物理暴击等级 = (攻击方.抗物理暴击等级 or 0) - 抗物理暴击等级
		攻击方.抗法术暴击等级 = (攻击方.抗法术暴击等级 or 0) - 抗法术暴击等级
		攻击方.穿刺等级 = (攻击方.穿刺等级 or 0) - 穿刺等级
		攻击方.狂暴等级 = (攻击方.狂暴等级 or 0) - 狂暴等级
		攻击方.格挡值 = (攻击方.格挡值 or 0) - 格挡值
		攻击方.四系法术吸收概率 = (攻击方.四系法术吸收概率 or 0) - 四系法术吸收概率
	elseif 类型 == 2 then
		攻击方.伤害 = 攻击方.伤害 + 伤害
		攻击方.防御 = 攻击方.防御 + 防御
		攻击方.速度 = 攻击方.速度 + 速度
		攻击方.法防 = 攻击方.法防 + 法防
		攻击方.躲避 = 攻击方.躲避 + 躲避
		攻击方.命中 = 攻击方.命中 + 命中
		攻击方.灵力 = 攻击方.灵力 + 灵力
		攻击方.法伤 = 攻击方.法伤 + 法伤
		攻击方.最大气血 = 攻击方.最大气血 + 最大气血
		攻击方.最大魔法 = 攻击方.最大魔法 + 最大魔法
		攻击方.物理暴伤 = (攻击方.物理暴伤 or 2) + 物理暴伤
		攻击方.法术暴伤 = (攻击方.法术暴伤 or 2) + 法术暴伤
		攻击方.必杀 = (攻击方.必杀 or 基础暴击率) + 必杀
		攻击方.法暴 = (攻击方.法暴 or 基础法暴率) + 法暴
		攻击方.法连 = (攻击方.法连 or 0) + 法连
		攻击方.连击 = (攻击方.连击 or 0) + 连击
		攻击方.治疗能力 = (攻击方.治疗能力 or 0) + 治疗能力
		攻击方.治疗效果 = (攻击方.治疗效果 or 100) + 治疗能力
		攻击方.封印抵抗率 = (攻击方.封印抵抗率 or 0) + 封印抵抗率
		攻击方.封印命中率 = (攻击方.封印命中率 or 0) + 封印命中率
		攻击方.普攻躲避率 = (攻击方.普攻躲避率 or 0) + 普攻躲避率
		攻击方.法术躲避率 = (攻击方.法术躲避率 or 0) + 法术躲避率
		攻击方.抵抗封印等级 = (攻击方.抵抗封印等级 or 0) + 抵抗封印等级
		攻击方.封印命中等级 = (攻击方.封印命中等级 or 0) + 封印命中等级
		攻击方.物理暴击等级 = (攻击方.物理暴击等级 or 0) + 物理暴击等级
		攻击方.法术暴击等级 = (攻击方.法术暴击等级 or 0) + 法术暴击等级
		攻击方.抗物理暴击等级 = (攻击方.抗物理暴击等级 or 0) + 抗物理暴击等级
		攻击方.抗法术暴击等级 = (攻击方.抗法术暴击等级 or 0) + 抗法术暴击等级
		攻击方.穿刺等级 = (攻击方.穿刺等级 or 0) + 穿刺等级
		攻击方.狂暴等级 = (攻击方.狂暴等级 or 0) + 狂暴等级
		攻击方.格挡值 = (攻击方.格挡值 or 0) + 格挡值
		攻击方.四系法术吸收概率 = (攻击方.四系法术吸收概率 or 0) + 四系法术吸收概率
	end

	if 攻击方.最大气血 < 攻击方.气血 then
		攻击方.气血 = 攻击方.最大气血
	end

	if 名称 == "日月乾坤" then
		self:日月乾坤结束战斗()
	end

	if self.击退列表[攻击方.战斗编号] == nil and self.参战单位[攻击方.战斗编号].名称 == "狸" and self.参战单位[攻击方.战斗编号].模型 == "花妖" and self.参战单位[攻击方.战斗编号].变异 == true and self:取封印状态(攻击方.战斗编号) then
		self.参战单位[攻击方.战斗编号].气血 = 0
		self.参战单位[攻击方.战斗编号].死亡状态 = 1
		self.击退列表[攻击方.战斗编号] = 1
	end
end

function 战斗处理类:取消状态(名称, 攻击方, 正常消除, 技能名称)
	if 攻击方.法术状态 == nil then
		print("1" .. 名称 .. tostring(攻击方.名称))

		return
	end

	if 攻击方.法术状态[名称] == nil then
		return
	end

	if 正常消除 == nil then
		if 名称 == "雾杀" then
			if 攻击方.法术状态[名称].咒术 ~= nil and 攻击方.法术状态[名称].等级 ~= nil then
				local 施法者 = 攻击方.法术状态[名称].咒术
				local 雾痕层数 = 1

				if self.参战单位[施法者].法术状态.雾痕 ~= nil and self.参战单位[施法者].法术状态.雾痕.层数 ~= nil then
					雾痕层数 = self.参战单位[施法者].法术状态.雾痕.层数 + 1
				end

				self:取消状态("雾痕", self.参战单位[施法者])
				self:添加状态("雾痕", self.参战单位[施法者], self.参战单位[施法者], 雾痕层数, 施法者)
			end
		elseif 名称 == "摄魂" then
			local bh = 攻击方.法术状态[名称].攻击编号

			if self:取奇经八脉是否有(bh, "狱火") and ygsj() <= 50 then
				return
			end
		elseif 名称 == "乐韵" then
		elseif 名称 == "蜜润" then
			if 攻击方.法术状态[名称].滋养 ~= nil and 攻击方.被动技能 ~= nil and 攻击方.被动技能.驭灵咒 ~= nil then
				local 编号 = 攻击方.法术状态[名称].攻击编号
				local hp = 攻击方.被动技能.驭灵咒 * 攻击方.法术状态[名称].回合数

				self:增加气血(编号, hp)
			end
		elseif 名称 == "天罗地网" then
			local 编号 = 攻击方.法术状态[名称].攻击编号

			if self:取奇经八脉是否有(编号, "附骨") and (技能名称 == "玉清诀" or 技能名称 == "晶清诀") and ygsj() <= 50 then
				return
			end
		elseif 名称 == "尸腐毒" then
			local 编号 = 攻击方.法术状态[名称].攻击编号

			if self:取奇经八脉是否有(编号, "入骨") then
				气血 = qz(攻击方.气血 * 0.05)
				self.战斗流程[#self.战斗流程 + 1] = {
					流程 = 1021,
					攻击方 = 攻击方.战斗编号,
					气血 = 气血,
					挨打方 = {}
				}
				精准战斗流程 = #self.战斗流程 + 0
				self.战斗流程[精准战斗流程].死亡 = self:减少气血(攻击方.战斗编号, 气血, nil, nil, nil, nil, 1)
			end
		elseif 名称 == "毒" and 攻击方.法术状态.毒.暗器毒 ~= nil then
			local bh = 攻击方.法术状态.毒.攻击编号

			if self:取奇经八脉是否有(bh, "毒引") then
				local hp = 600

				if 攻击方.气血 <= 600 then
					hp = 攻击方.气血 - 1
				end

				self.战斗流程[#self.战斗流程 + 1] = {
					流程 = 1021,
					攻击方 = 攻击方.战斗编号,
					气血 = hp,
					挨打方 = {}
				}
				self.战斗流程[#self.战斗流程].死亡 = self:减少气血(攻击方.战斗编号, hp, bh, nil, nil, nil, 1)
			end
		elseif 名称 == "明光宝烛" or 名称 == "金身舍利" and 攻击方.法术状态[名称].救人 ~= nil then
			self:添加护盾(攻击方.战斗编号, 攻击方.法术状态[名称].回合 * 攻击方.等级)
		elseif 名称 == "夺魄令" then
			local 编号 = 攻击方.法术状态[名称].攻击编号

			if self:取奇经八脉是否有(编号, "陷阱") then
				self:添加状态("陷阱", 攻击方, self.参战单位[编号], 1, 编号)

				self.参战单位[编号].陷阱 = math.min((self.参战单位[编号].陷阱 or 0) + 1, 7)
			end
		end

		if (技能名称 == "晶清诀" or 技能名称 == "玉清诀") and 攻击方.法术状态[名称].绝殇 ~= nil and self.回合数 == 攻击方.法术状态[名称].绝殇 then
			return
		end
	end

	if 判断护盾值状态[名称] == 1 then
		if 攻击方.法术状态[名称].护盾值 ~= nil and 攻击方.法术状态[名称].护盾值 > 1 then
			self:扣除护盾(攻击方.战斗编号, 攻击方.法术状态[名称].护盾值, 1)
		end

		if 名称 == "镜之阳" and self.镜之阳 ~= nil and self.镜之阳[攻击方.队伍] ~= nil then
			self.镜之阳[攻击方.队伍][攻击方.战斗编号] = nil

			if 判断是否为空表(self.镜之阳[攻击方.队伍]) then
				self.镜之阳[攻击方.队伍] = nil
			end
		end
	end

	if 攻击方.法术状态[名称].类型 == 2 then
		攻击方.伤害 = 攻击方.伤害 - (攻击方.法术状态[名称].伤害 or 0)
		攻击方.防御 = 攻击方.防御 - (攻击方.法术状态[名称].防御 or 0)
		攻击方.速度 = 攻击方.速度 - (攻击方.法术状态[名称].速度 or 0)
		攻击方.法防 = 攻击方.法防 - (攻击方.法术状态[名称].法防 or 0)
		攻击方.躲避 = 攻击方.躲避 - (攻击方.法术状态[名称].躲避 or 0)
		攻击方.命中 = 攻击方.命中 - (攻击方.法术状态[名称].命中 or 0)
		攻击方.灵力 = 攻击方.灵力 - (攻击方.法术状态[名称].灵力 or 0)
		攻击方.法伤 = 攻击方.法伤 - (攻击方.法术状态[名称].法伤 or 0)
		攻击方.最大气血 = 攻击方.最大气血 - (攻击方.法术状态[名称].最大气血 or 0)
		攻击方.最大魔法 = 攻击方.最大魔法 - (攻击方.法术状态[名称].最大魔法 or 0)
		攻击方.法连 = (攻击方.法连 or 0) - (攻击方.法术状态[名称].法连 or 0)
		攻击方.连击 = (攻击方.连击 or 0) - (攻击方.法术状态[名称].连击 or 0)
		攻击方.必杀 = (攻击方.必杀 or 基础暴击率) - (攻击方.法术状态[名称].必杀 or 0)
		攻击方.法暴 = (攻击方.法暴 or 基础法暴率) - (攻击方.法术状态[名称].法暴 or 0)
		攻击方.物理暴伤 = (攻击方.物理暴伤 or 2) - (攻击方.法术状态[名称].物理暴伤 or 0)
		攻击方.法术暴伤 = (攻击方.法术暴伤 or 2) - (攻击方.法术状态[名称].法术暴伤 or 0)
		攻击方.法暴 = (攻击方.法暴 or 基础法暴率) - (攻击方.法术状态[名称].法暴 or 0)
		攻击方.治疗能力 = (攻击方.治疗能力 or 0) - (攻击方.法术状态[名称].治疗能力 or 0)
		攻击方.治疗效果 = (攻击方.治疗效果 or 100) - (攻击方.法术状态[名称].治疗效果 or 0)
		攻击方.封印抵抗率 = (攻击方.封印抵抗率 or 0) - (攻击方.法术状态[名称].封印抵抗率 or 0)
		攻击方.封印命中率 = (攻击方.封印命中率 or 0) - (攻击方.法术状态[名称].封印命中率 or 0)
		攻击方.抵抗封印等级 = (攻击方.抵抗封印等级 or 0) - (攻击方.法术状态[名称].抵抗封印等级 or 0)
		攻击方.封印命中等级 = (攻击方.封印命中等级 or 0) - (攻击方.法术状态[名称].封印命中等级 or 0)
		攻击方.法术躲避率 = (攻击方.法术躲避率 or 0) - (攻击方.法术状态[名称].法术躲避率 or 0)
		攻击方.普攻躲避率 = (攻击方.普攻躲避率 or 0) - (攻击方.法术状态[名称].普攻躲避率 or 0)
		攻击方.物理暴击等级 = (攻击方.物理暴击等级 or 0) - (攻击方.法术状态[名称].物理暴击等级 or 0)
		攻击方.法术暴击等级 = (攻击方.法术暴击等级 or 0) - (攻击方.法术状态[名称].法术暴击等级 or 0)
		攻击方.抗物理暴击等级 = (攻击方.抗物理暴击等级 or 0) - (攻击方.法术状态[名称].抗物理暴击等级 or 0)
		攻击方.抗法术暴击等级 = (攻击方.抗法术暴击等级 or 0) - (攻击方.法术状态[名称].抗法术暴击等级 or 0)
		攻击方.穿刺等级 = (攻击方.穿刺等级 or 0) - (攻击方.法术状态[名称].穿刺等级 or 0)
		攻击方.狂暴等级 = (攻击方.狂暴等级 or 0) - (攻击方.法术状态[名称].狂暴等级 or 0)
		攻击方.格挡值 = (攻击方.格挡值 or 0) - (攻击方.法术状态[名称].格挡值 or 0)
		攻击方.四系法术吸收概率 = (攻击方.四系法术吸收概率 or 0) - (攻击方.法术状态[名称].四系法术吸收概率 or 0)
	elseif 攻击方.法术状态[名称].类型 == 1 then
		攻击方.伤害 = 攻击方.伤害 + (攻击方.法术状态[名称].伤害 or 0)
		攻击方.防御 = 攻击方.防御 + (攻击方.法术状态[名称].防御 or 0)
		攻击方.速度 = 攻击方.速度 + (攻击方.法术状态[名称].速度 or 0)
		攻击方.法防 = 攻击方.法防 + (攻击方.法术状态[名称].法防 or 0)
		攻击方.躲避 = 攻击方.躲避 + (攻击方.法术状态[名称].躲避 or 0)
		攻击方.命中 = 攻击方.命中 + (攻击方.法术状态[名称].命中 or 0)
		攻击方.灵力 = 攻击方.灵力 + (攻击方.法术状态[名称].灵力 or 0)
		攻击方.法伤 = 攻击方.法伤 + (攻击方.法术状态[名称].法伤 or 0)
		攻击方.最大气血 = 攻击方.最大气血 + (攻击方.法术状态[名称].最大气血 or 0)
		攻击方.最大魔法 = 攻击方.最大魔法 + (攻击方.法术状态[名称].最大魔法 or 0)
		攻击方.法连 = (攻击方.法连 or 0) + (攻击方.法术状态[名称].法连 or 0)
		攻击方.连击 = (攻击方.连击 or 0) + (攻击方.法术状态[名称].连击 or 0)
		攻击方.必杀 = (攻击方.必杀 or 基础暴击率) + (攻击方.法术状态[名称].必杀 or 0)
		攻击方.法暴 = (攻击方.法暴 or 基础法暴率) + (攻击方.法术状态[名称].法暴 or 0)
		攻击方.物理暴伤 = (攻击方.物理暴伤 or 2) + (攻击方.法术状态[名称].物理暴伤 or 0)
		攻击方.法术暴伤 = (攻击方.法术暴伤 or 2) + (攻击方.法术状态[名称].法术暴伤 or 0)
		攻击方.治疗能力 = (攻击方.治疗能力 or 0) + (攻击方.法术状态[名称].治疗能力 or 0)
		攻击方.治疗效果 = (攻击方.治疗效果 or 100) + (攻击方.法术状态[名称].治疗效果 or 0)
		攻击方.封印抵抗率 = (攻击方.封印抵抗率 or 0) + (攻击方.法术状态[名称].封印抵抗率 or 0)
		攻击方.封印命中率 = (攻击方.封印命中率 or 0) + (攻击方.法术状态[名称].封印命中率 or 0)
		攻击方.抵抗封印等级 = (攻击方.抵抗封印等级 or 0) + (攻击方.法术状态[名称].抵抗封印等级 or 0)
		攻击方.封印命中等级 = (攻击方.封印命中等级 or 0) + (攻击方.法术状态[名称].封印命中等级 or 0)
		攻击方.法术躲避率 = (攻击方.法术躲避率 or 0) + (攻击方.法术状态[名称].法术躲避率 or 0)
		攻击方.普攻躲避率 = (攻击方.普攻躲避率 or 0) + (攻击方.法术状态[名称].普攻躲避率 or 0)
		攻击方.物理暴击等级 = (攻击方.物理暴击等级 or 0) + (攻击方.法术状态[名称].物理暴击等级 or 0)
		攻击方.法术暴击等级 = (攻击方.法术暴击等级 or 0) + (攻击方.法术状态[名称].法术暴击等级 or 0)
		攻击方.抗物理暴击等级 = (攻击方.抗物理暴击等级 or 0) + (攻击方.法术状态[名称].抗物理暴击等级 or 0)
		攻击方.抗法术暴击等级 = (攻击方.抗法术暴击等级 or 0) + (攻击方.法术状态[名称].抗法术暴击等级 or 0)
		攻击方.穿刺等级 = (攻击方.穿刺等级 or 0) + (攻击方.法术状态[名称].穿刺等级 or 0)
		攻击方.狂暴等级 = (攻击方.狂暴等级 or 0) + (攻击方.法术状态[名称].狂暴等级 or 0)
		攻击方.格挡值 = (攻击方.格挡值 or 0) + (攻击方.法术状态[名称].格挡值 or 0)
		攻击方.四系法术吸收概率 = (攻击方.四系法术吸收概率 or 0) + (攻击方.法术状态[名称].四系法术吸收概率 or 0)
	end

	if 攻击方.最大气血 < 攻击方.气血 then
		攻击方.气血 = 攻击方.最大气血
	end

	if 名称 == "魔音摄魂" and 攻击方.法术状态[名称].绵密 ~= nil then
		local bh = 攻击方.法术状态[名称].攻击编号 + 0

		self:添加状态("瘴气", 攻击方, self.参战单位[bh], self:取技能等级(bh, "瘴气"), bh)

		攻击方.法术状态.瘴气.回合 = 3
	end

	攻击方.法术状态[名称] = nil
end

function 战斗处理类:取消状态显示(编号, 状态名称)
	if self.参战单位[编号] ~= nil and self.参战单位[编号].法术状态 ~= nil and self.参战单位[编号].法术状态[状态名称] ~= nil then
		local 观战状态 = {}

		for w = 1, #self.参战玩家 do
			发送数据(self.参战玩家[w].连接id, 5507, {
				id = 编号,
				名称 = 状态名称
			})
		end

		观战状态[#观战状态 + 1] = {
			序号 = 5507,
			id = 编号,
			名称 = 状态名称
		}

		self:取消状态(状态名称, self.参战单位[编号])

		for n = 1, #观战状态 do
			for i, v in pairs(self.观战玩家) do
				if 玩家数据[i] ~= nil then
					发送数据(玩家数据[i].连接id, 观战状态[n].序号, 观战状态[n])
				end
			end
		end
	end
end

function 战斗处理类:取消所有毒状态(编号)
	if self.参战单位[编号] ~= nil and self.参战单位[编号].法术状态 ~= nil then
		for i = 1, #毒状态列表 do
			if self.参战单位[编号].法术状态[毒状态列表[i]] ~= nil then
				self:取消状态(毒状态列表[i], self.参战单位[编号])
			end
		end
	end
end

function 战斗处理类:取消所有状态(编号)
	if self.参战单位[编号] ~= nil and self.参战单位[编号].法术状态 ~= nil then
		for k, v in pairs(self.参战单位[编号].法术状态) do
			self:取消状态(k, self.参战单位[编号])
		end
	end
end

function 战斗处理类:取是否五行相克(五行1, 五行2)
	local aa = 战斗五行克制[五行1][五行2] or 1

	if aa > 1 then
		return true
	end

	return false
end

function 战斗处理类:取是否五行相生(五行1, 五行2)
	local aa = 战斗五行相生[五行1][五行2] or 1

	if aa > 1 then
		return true
	end

	return false
end

function 战斗处理类:取五行相克(编号, 目标, 技能名称)
	local 攻击五行 = self.参战单位[编号].攻击五行
	local 额外 = 0
	local 克制 = 1

	if self.参战单位[编号].克敌五行 ~= nil and (战斗五行克制[self.参战单位[编号].克敌五行][self.参战单位[目标].防御五行] or 1) > 1 then
		额外 = 额外 + 0.7
	end

	if 技能名称 ~= nil then
		if 五行物攻法术[技能名称] ~= nil then
			攻击五行 = 五行物攻法术[技能名称]
			克制 = 战斗五行克制[攻击五行][self.参战单位[目标].防御五行] or 1

			if 克制 > 1 then
				if self.参战单位[编号].五行感应 ~= nil then
					额外 = 额外 + 0.5
				end

				if self:取奇经八脉是否有(编号, "因缘") then
					额外 = 额外 + 0.1
				end
			end

			if self:取奇经八脉是否有(编号, "万象") and self.参战单位[编号].法术状态.颠倒五行 ~= nil and 克制 > 1 then
				额外 = 额外 + 0.2
			end

			return 克制 + 额外
		elseif 克制所有五行法术[技能名称] ~= nil then
			克制 = 五行系数1

			if 技能名称 == "剑意莲心" then
				if self.参战单位[编号].消耗五行 ~= nil and self.参战单位[编号].消耗五行[self.参战单位[目标].防御五行] ~= nil then
					额外 = 额外 + 0.5
				end
			elseif 技能名称 == "相灭相生" then
				克制 = 克制 + 0.2
			end

			if self:取奇经八脉是否有(编号, "万象") and self.参战单位[编号].法术状态.颠倒五行 ~= nil then
				额外 = 额外 + 0.2
			end

			return 克制 + 额外
		elseif 五行固伤法术[技能名称] ~= nil then
			return 1
		end
	end

	克制 = 战斗五行克制[攻击五行][self.参战单位[目标].防御五行] or 1

	if self:取奇经八脉是否有(编号, "万象") and self.参战单位[编号].法术状态.颠倒五行 ~= nil and 克制 > 1 then
		额外 = 额外 + 0.2
	end

	return 克制 + 额外
end

function 战斗处理类:取五行相生(编号, 目标)
	if self.参战单位[编号].攻击五行 == nil or self.参战单位[目标].防御五行 == nil then
		return 1
	else
		return 战斗五行相生[self.参战单位[编号].攻击五行][self.参战单位[目标].防御五行] or 1
	end
end

function 战斗处理类:驱散目标状态1(目标, 编号)
	local 驱散状态 = self:取对方可偷取增益技能1(目标)

	if 驱散状态 ~= nil then
		if 驱散状态 == "普渡众生" and self.参战单位[目标].法术状态.普渡众生.雨润 ~= nil then
			self:恢复技能计算(目标, "自在心法1", self.参战单位[目标].法术状态.普渡众生.等级, 目标)
		end

		self:取消状态(驱散状态, self.参战单位[目标])
		self:添加战斗流程提示("#R" .. self.参战单位[编号].名称 .. "#W驱散了#R" .. self.参战单位[目标].名称 .. "#W的#S" .. 驱散状态 .. "#W状态")
		self:客户端取消状态(目标, 驱散状态)

		return 驱散状态
	end
end

function 战斗处理类:驱散目标状态(目标, 编号, 特殊)
	local 驱散状态 = self:取对方可偷取增益技能(目标, 特殊)

	if 驱散状态 ~= nil then
		if 驱散状态 == "普渡众生" and self.参战单位[目标].法术状态.普渡众生.雨润 ~= nil then
			self:恢复技能计算(目标, "自在心法1", self.参战单位[目标].法术状态.普渡众生.等级, 目标)
		end

		self:取消状态(驱散状态, self.参战单位[目标])
		self:添加战斗流程提示("#R" .. self.参战单位[编号].名称 .. "#W驱散了#R" .. self.参战单位[目标].名称 .. "#W的#S" .. 驱散状态 .. "#W状态")
		self:客户端取消状态(目标, 驱散状态)

		return 驱散状态
	end
end

function 战斗处理类:秘传技能击杀判定(编号, 目标, 技能)
	if self.参战单位[编号] == nil or self.参战单位[目标] == nil then
		return false
	end

	技能 = 技能 or 1
	local 法伤 = self.参战单位[编号].法伤
	local lv = math.max(self.参战单位[编号].等级, 10)
	local 气血 = self.参战单位[目标].气血
	local 比例 = self.参战单位[目标].气血 / self.参战单位[目标].最大气血
	local 几率 = 0.5

	if 技能 == 1 then
		几率 = (1 - 比例) * 4 * math.min(法伤 / 30 * lv, 1) + math.max((math.min(10000, self.参战单位[目标].最大气血) - 气血) / 1000, 0)
	else
		几率 = (1 - 比例) * 10 * math.min(法伤 / 30 * lv, 1) + math.max((math.min(10000, self.参战单位[目标].最大气血) - 气血) / 1000, 0)
	end

	if self:取奇经八脉是否有(编号, "不滅") then
		几率 = 几率 * 1.1
	end

	if self:取奇经八脉是否有(编号, "碾压") and self.参战单位[目标].类型 == "bb" then
		几率 = 几率 * 1.4
	end

	if ygsj(1000) <= 几率 * 10 then
		return true
	else
		return false
	end
end

function 战斗处理类:取是否召唤兽(目标)
	if self.参战单位[目标].类型 == "bb" and self.参战单位[目标].召唤物 == nil and self.参战单位[目标].主人或助战 ~= nil then
		return true
	end

	return false
end

function 战斗处理类:取是否玩家角色(目标)
	if self.参战单位[目标].召唤物 == nil and (self:取玩家战斗() and self.参战单位[目标].类型 ~= "bb" or self.参战单位[目标].玩家id ~= 0 and self.参战单位[目标].类型 == "角色") then
		return true
	end

	return false
end

function 战斗处理类:取是否有指定状态(编号, 目标, 状态, 来自编号)
	if 编号 == nil or 目标 == nil or 状态 == nil or self.参战单位[编号] == nil or self.参战单位[目标] == nil then
		return
	end

	if self.参战单位[目标].法术状态[状态] == nil then
		return false
	elseif 来自编号 == nil then
		return true
	elseif self.参战单位[目标].法术状态[状态].攻击编号 == 来自编号 then
		return true
	end

	return false
end

判断模型是否是 = function(宝宝数据, 造型, 排除最初模型)
	if 宝宝数据 == nil or 宝宝数据.模型 == nil then
		return false
	else
		local 判断模型 = ""

		if 宝宝数据.最初模型 == nil or 排除最初模型 ~= nil then
			判断模型 = string.gsub(宝宝数据.模型, "_睡梦", "")
		else
			判断模型 = string.gsub(宝宝数据.最初模型, "_睡梦", "")
		end

		if 判断模型 == 造型 or 判断模型 == "进阶" .. 造型 then
			return true
		end
	end

	return false
end

function 战斗处理类:新增状态处理(物法, 编号, 目标, 伤害值, 类型, 执行数, 名称, 吸收, 等级, 流程)
	self:去除待消除状态(编号)
	self:去除待消除状态(目标)

	local 攻击流程 = 流程 + 0
	local 天气 = qz(self.天气)

	if 执行数 == nil then
		执行数 = 1
	end

	if 等级 == nil then
		等级 = self.参战单位[编号].等级
	end

	local 临时计算属性 = {}
	self.参战单位[编号].出手 = 1

	if self.参战单位[目标].轻霜 ~= nil and ygsj() <= 30 and self.参战单位[编号].法术状态.机巧 == nil and self.参战单位[编号].法术状态.轻霜 == nil and self:负面技能施加判断(编号, "轻霜", 目标) then
		self:添加状态("轻霜", self.参战单位[编号], self.参战单位[目标], self.参战单位[目标].等级, 目标)

		local hp = math.min(self.参战单位[编号].法术状态.轻霜.等级, self.参战单位[编号].气血 - 1)
		local 死亡 = self:减少气血(编号, hp, nil, nil, nil, nil, 1)
		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 1021,
			攻击方 = 编号,
			气血 = hp,
			死亡 = 死亡,
			挨打方 = {}
		}

		self:添加战斗流程提示("#P(轻霜)#R" .. self.参战单位[编号].名称 .. "#W企图攻击#R" .. self.参战单位[目标].名称 .. "#W、被其附加了#R4#W回合的#S轻霜#W状态")
	end

	if 类型 ~= 2 then
		if 名称 == "棒打雄风" or 名称 == "意马心猿" then
			self:驱散目标状态(目标, 编号, "最短")

			if 名称 == "意马心猿" and self:取奇经八脉是否有(编号, "逞胜", "通天行者") and self:取封印状态(目标) then
				self:驱散目标状态(目标, 编号, "最短")
			end
		end

		if 伤害叠加模式 ~= 1 then
			local aa = {
				"造成伤害",
				"造成物理伤害",
				"造成法术伤害"
			}
			local aa1 = {
				"承受伤害",
				"受到法术伤害",
				"受到物理伤害"
			}
			临时计算属性 = {
				造成伤害 = 1,
				造成物理伤害 = 1,
				造成法术伤害 = 1,
				受到法术伤害 = 1,
				受到物理伤害 = 1,
				承受伤害 = 1
			}

			for k, v in pairs(self.参战单位[编号].法术状态) do
				for i = 1, #aa do
					if v[aa[i]] ~= nil then
						临时计算属性[aa[i]] = 临时计算属性[aa[i]] + v[aa[i]] / 100
					end
				end
			end

			for k, v in pairs(self.参战单位[目标].法术状态) do
				for i = 1, #aa1 do
					if v[aa1[i]] ~= nil then
						临时计算属性[aa1[i]] = 临时计算属性[aa1[i]] + v[aa1[i]] / 100
					end
				end
			end
		end

		local 恐怖加成 = 0

		if 昼夜参数 == 1 and self.参战单位[编号].恐怖 ~= nil then
			恐怖加成 = self.参战单位[编号].恐怖
		end

		if self.参战单位[目标].勇敢 == nil and self.参战单位[编号].恐怖 ~= nil and self.参战单位[目标].法术状态.恐怖 == nil and self.参战单位[目标].恐怖判定 ~= true then
			self.参战单位[目标].恐怖判定 = true

			if ygsj(恐怖概率基数) <= self.参战单位[编号].恐怖 + 恐怖加成 then
				self:添加状态("恐怖", self.参战单位[目标], self.参战单位[编号], self.参战单位[编号].等级, 编号)

				self.战斗流程[攻击流程].挨打方[执行数].添加状态 = "恐怖"

				self:添加战斗流程提示("#P(恐怖)#R" .. self.参战单位[目标].名称 .. "#W被#R" .. self.参战单位[编号].名称 .. "#G恐怖，#W下回合将被迫执行#R防御")
			end
		end

		if self.参战单位[目标].神武盾气 ~= nil and self.参战单位[目标].法术状态.神武盾气 == nil and ygsj() <= self.参战单位[目标].神武盾气 then
			self:添加状态("神武盾气", self.参战单位[目标], self.参战单位[编号], self.参战单位[编号].等级, 编号)

			self.战斗流程[攻击流程].挨打方[执行数].添加状态 = "神武盾气"

			if self.参战单位[目标].神武盾气 == 30 then
				self:添加战斗流程提示("#P(神武盾气)#R" .. self.参战单位[目标].名称 .. "#W触发了#G神武盾气，#W效果持续到本回合结束")
			else
				self:添加战斗流程提示("#P(高级神武盾气)#R" .. self.参战单位[目标].名称 .. "#W触发了#G高级神武盾气，#W效果持续到本回合结束")
			end
		end

		if self.参战单位[编号].气势 ~= nil and ygsj() <= self.参战单位[编号].气势 and self.参战单位[编号].法术状态.气势 == nil then
			self:添加状态("气势", self.参战单位[编号], self.参战单位[目标])

			self.战斗流程[攻击流程].添加状态 = "气势"

			if self.参战单位[编号].气势 == 20 then
				self:添加战斗流程提示("#P(气势)#R" .. self.参战单位[编号].名称 .. "#W触发了#G气势，#W效果持续到下回合结束")
			else
				self:添加战斗流程提示("#P(气势)#R" .. self.参战单位[编号].名称 .. "#W触发了#G高级气势，#W效果持续到下回合结束")
			end
		end

		if self.参战单位[编号].震摄 ~= nil and ygsj() <= self.参战单位[编号].震摄 and self.参战单位[编号].法术状态.震摄 == nil then
			self:添加状态("震摄", self.参战单位[编号], self.参战单位[目标])

			self.战斗流程[攻击流程].添加状态 = "震摄"

			if self.参战单位[编号].震摄 == 20 then
				self:添加战斗流程提示("#P(震摄)#R" .. self.参战单位[编号].名称 .. "#W触发了#G震摄，#W效果持续到下回合结束")
			else
				self:添加战斗流程提示("#P(震摄)#R" .. self.参战单位[编号].名称 .. "#W触发了#G高级震摄，#W效果持续到下回合结束")
			end
		end

		if self.参战单位[编号].逆击 ~= nil then
			if self:取对方可偷取增益技能(目标) ~= nil then
				伤害值 = 伤害值 * self.参战单位[编号].逆击

				self:添加战斗流程提示("#P(逆击)#R" .. self.参战单位[目标].名称 .. "#W有增益状态、#R" .. self.参战单位[编号].名称 .. "触发了#G逆击#W效果")
			end

			if self.参战单位[目标].出手 ~= 1 then
				伤害值 = 伤害值 * self.参战单位[编号].逆击增伤

				self:添加战斗流程提示("#P(逆击)#R" .. self.参战单位[目标].名称 .. "#W本回合未出手、#R" .. self.参战单位[编号].名称 .. "触发了#G逆击#W增伤")
			end
		end

		local 五行克制 = self:取五行相克(编号, 目标, 名称)

		if 五行克制 ~= 1 then
			伤害值 = 伤害值 * 五行克制
		end

		if 伤害叠加模式 == 1 then
			if 天气 == 1 then
				if self:取奇经八脉是否有(编号, "风姿") then
					伤害值 = 伤害值 * 1.1
				end

				if self.参战单位[编号].清风之华 ~= nil then
					伤害值 = 伤害值 * 1.1
				end

				if self.参战单位[目标].清风之华 ~= nil then
					伤害值 = 伤害值 * 0.8
				end
			elseif 天气 == 2 then
				if (名称 == "裂石" or 名称 == "断岳势" or 名称 == "天崩地裂") and self:取奇经八脉是否有(编号, "砥石") then
					伤害值 = 伤害值 * 1.1
				end

				if self.参战单位[编号].雨露之泽 ~= nil then
					伤害值 = 伤害值 * 1.2
				end

				if self.参战单位[目标].雨露之泽 ~= nil then
					伤害值 = 伤害值 * 0.9
				end
			elseif 天气 == 3 then
			elseif self:取奇经八脉是否有(编号, "奇门") then
				伤害值 = 伤害值 * 1.03
			end

			if self.参战单位[编号].法术状态.天狐之舞 ~= nil and 物法 ~= "普攻" and 物法 ~= "普攻连击" then
				伤害值 = 伤害值 * 1.1
			end

			if self.战斗类型 >= 134481 and self.战斗类型 < 134482 then
				if self.参战单位[编号].队伍 == 0 and self.参战单位[编号].名称 == "祝融" and self.参战单位[编号].气血 > self.参战单位[编号].最大气血 * 0.5 then
					伤害值 = 伤害值 * 1.65
				elseif self.参战单位[目标].队伍 == 0 and self.参战单位[目标].名称 == "祝融" and self.参战单位[目标].气血 <= self.参战单位[目标].最大气血 * 0.5 then
					伤害值 = 伤害值 * 0.5
				elseif self.参战单位[目标].队伍 == 0 and self.共工光环 == 1 then
					伤害值 = 伤害值 * 0.7
				end
			end

			if 物法 ~= "固伤" and self.镜之阳 ~= nil and self.镜之阳[self.参战单位[编号].队伍] ~= nil and not 判断是否为空表(self.镜之阳[self.参战单位[编号].队伍]) then
				伤害值 = 伤害值 * 1.5
			end

			if self.参战单位[编号].法术状态.攻伐 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.攻伐.造成伤害 / 100)
			end

			if self.参战单位[编号].法术状态.杀威铁棒 ~= nil and 目标 == self.参战单位[编号].法术状态.杀威铁棒.攻击编号 then
				伤害值 = 伤害值 * self.参战单位[编号].法术状态.杀威铁棒.减伤
			end

			if self.参战单位[编号].压邪 ~= nil and (self.参战单位[编号].连续神通 or 0) >= 3 then
				伤害值 = 伤害值 * 1.1
			end

			if self.参战单位[编号].法术状态.无所遁形 ~= nil and self.参战单位[编号].法术状态.铜头铁臂 ~= nil then
				伤害值 = 伤害值 * 1.12
			end

			if self.参战单位[目标].角色减少 ~= nil and self:取是否玩家角色(编号) then
				伤害值 = 伤害值 * self.参战单位[目标].角色减少
			end

			if self.参战单位[目标].召唤减少 ~= nil and self.参战单位[编号].主人或助战 ~= nil then
				伤害值 = 伤害值 * self.参战单位[目标].召唤减少
			end

			if self.参战单位[编号].法术状态.嗜血 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.嗜血.造成伤害 / 100)
			end

			if self.参战单位[编号].法术状态.蔓延 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.蔓延.造成伤害 / 100)
			end

			if self.参战单位[编号].法术状态.好梦连连 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.好梦连连.造成伤害 / 100)
			end

			if self.参战单位[编号].法术状态.狂怒 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.狂怒.造成伤害 / 100)
			end

			if 名称 ~= nil and self.参战单位[编号].踏歌 ~= nil and self.参战单位[编号].踏歌.重拍技能[名称] ~= nil and self.参战单位[编号].法术状态.乐韵 ~= nil then
				伤害值 = 伤害值 * self.参战单位[编号].法术状态.乐韵.加成
			end

			if self.参战单位[编号].法术状态.摄魂 ~= nil then
				伤害值 = qz(伤害值 * (1 + self.参战单位[编号].法术状态.摄魂.造成伤害 / 100))
			end

			if self.参战单位[编号].法术状态.舞雪冰蝶 ~= nil then
				伤害值 = qz(伤害值 * (1 + self.参战单位[编号].法术状态.舞雪冰蝶.造成伤害 / 100))
			end

			if self.参战单位[编号].法术状态.遗志 ~= nil then
				伤害值 = qz(伤害值 * (1 + self.参战单位[编号].法术状态.遗志.造成伤害 / 100))
			end

			if self.参战单位[目标].法术状态.落花成泥 ~= nil and self.参战单位[目标].法术状态.落花成泥.回合 == 1 then
				伤害值 = 伤害值 * 1.24
			end

			if self.参战单位[目标].风灵 ~= nil and self.参战单位[目标].法术状态.风灵 ~= nil and self:取奇经八脉是否有(目标, "灵佑") then
				伤害值 = 伤害值 * 0.98
			end

			if self:取奇经八脉是否有(编号, "迷缚") and self.参战单位[目标].法术状态.雾杀 ~= nil and self.参战单位[目标].法术状态.雾杀.攻击编号 == 编号 then
				伤害值 = 伤害值 * 0.97
			end

			if self:取奇经八脉是否有(编号, "威震", "斗战真神") and self:取是否召唤兽(目标) then
				伤害值 = 伤害值 * (1 + (self.参战单位[编号].神通数 or 0) * 0.07)
			end

			if self:取奇经八脉是否有(编号, "大圣", "通天行者") and self:取是否召唤兽(目标) then
				伤害值 = 伤害值 * 1.3
			end

			if self.队伍战神[self.参战单位[编号].队伍] ~= nil and self.参战单位[编号].队伍 ~= self.参战单位[目标].队伍 then
				伤害值 = 伤害值 * self.队伍战神[self.参战单位[编号].队伍]
			end

			if self:取奇经八脉是否有(编号, "难保") and self.参战单位[目标].九黎浮空 == 编号 then
				伤害值 = 伤害值 * 1.1
			end

			if self.参战单位[编号].朝拜 ~= nil then
				伤害值 = 伤害值 * self.参战单位[编号].朝拜
			end

			if self.参战单位[编号].扑袭 ~= nil then
				伤害值 = 伤害值 * 1.4
			end

			if self.参战单位[编号].族魂 ~= nil and self.参战单位[目标].类型 ~= "bb" and self.参战单位[目标].门派 ~= "九黎城" and 门派名称1[self.参战单位[目标].门派] ~= nil then
				伤害值 = 伤害值 * self.参战单位[编号].族魂
			end

			if self.参战单位[编号].逞凶 ~= nil and self.参战单位[目标].类型 == "bb" then
				伤害值 = 伤害值 * self.参战单位[编号].逞凶
			end

			if self.参战单位[编号].飞扬增伤 ~= nil then
				伤害值 = 伤害值 * self.参战单位[编号].飞扬增伤
			end

			if self.参战单位[编号].风灵增伤 ~= nil then
				伤害值 = 伤害值 * self.参战单位[编号].风灵增伤
			end

			if self:取奇经八脉是否有(编号, "穿石") and self.参战单位[目标].类型 == "bb" then
				伤害值 = 伤害值 * 1.15
			end

			if self.参战单位[目标].玲珑 ~= nil and ygsj() <= 15 then
				伤害值 = 伤害值 * self.参战单位[目标].玲珑

				if (self.参战单位[目标].玲珑愤怒 or 0) < 2 then
					self:增加愤怒(目标, 10)

					self.参战单位[目标].玲珑愤怒 = (self.参战单位[目标].玲珑愤怒 or 0) + 1
				end
			end

			if self:取奇经八脉是否有(目标, "魔音") and self:取是否有指定状态(目标, 编号, "魔音摄魂") then
				伤害值 = 伤害值 * 0.82
			end

			if self:取是否有指定状态(编号, 编号, "天眼神通") and self:取奇经八脉是否有(编号, "威震", "风云战将") then
				伤害值 = 伤害值 * 1.04
			end

			if self:取奇经八脉是否有(目标, "叶护") and ygsj() <= 12 and self:与全部队友比较属性(目标, "速度", "角色", 1.5) then
				伤害值 = 伤害值 * 0.7
			end

			if self:取奇经八脉是否有(编号, "雷鸣") and self.参战单位[目标].气血 <= self.参战单位[目标].最大气血 * 0.5 then
				伤害值 = 伤害值 * 1.03
			end

			if self.参战单位[编号].门派 == "方寸山" then
				if self.参战单位[目标].门派 == "阴曹地府" then
					伤害值 = 伤害值 * 1.1
				end

				if self.参战单位[目标].鬼魂 ~= nil and 物法 ~= "固伤" then
					伤害值 = 伤害值 * 2
				end
			end

			if self.参战单位[编号].炼魂经脉 ~= nil and self.参战单位[编号].炼魂经脉 > 0 and self.参战单位[目标].法术状态.炼魂 == nil and self.参战单位[目标].类型 == "角色" and self.参战单位[目标].玩家id ~= 0 then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].炼魂经脉 * 0.05)
			end

			if self:取奇经八脉是否有(编号, "毒慑") and self:取敌方拥有指定状态人数(编号, "尸腐毒") > 0 then
				伤害值 = 伤害值 * 1.06
			end

			if self:取奇经八脉是否有(编号, "破印") and self.参战单位[目标].类型 == "bb" then
				伤害值 = 伤害值 * 1.1
			end

