				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.噬魂.造成物理伤害 / 100)
			end

			if self.参战单位[编号].法术状态.魂魄 ~= nil and self.参战单位[编号].法术状态.魂魄.造成物理伤害 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.魂魄.造成物理伤害 / 100)
			end

			if self.参战单位[编号].法术状态.魍魉追魂 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.魍魉追魂.造成物理伤害 / 100)
			end

			if self.参战单位[编号].法术状态.烽火狼烟 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.烽火狼烟.造成物理伤害 / 100)
			end

			if self.参战单位[编号].法术状态.金刚镯 ~= nil and self.参战单位[编号].法术状态.金刚镯.造成物理伤害 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.金刚镯.造成物理伤害 / 100)
			end

			if self.参战单位[编号].力大无穷 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].力大无穷)
			end

			if self.参战单位[目标].力大无穷 ~= nil then
				伤害值 = 伤害值 * (1 - self.参战单位[目标].力大无穷)
			end

			if self.参战单位[目标].五行健壮 ~= nil then
				伤害值 = 伤害值 * self.参战单位[目标].五行健壮
			end

			if 物法 ~= "物理" and self:取奇经八脉是否有(编号, "罗网") then
				伤害值 = 伤害值 * 1.1

				if self.参战单位[目标].法术状态.天罗地网 == nil then
					self:添加状态("天罗地网", self.参战单位[目标], self.参战单位[编号], self:取技能等级(编号, "天罗地网"), 编号)

					self.战斗流程[攻击流程].挨打方[执行数].添加状态 = "天罗地网"
				end
			end

			if self.参战单位[编号].粘附 ~= nil and self:取是否有指定状态(编号, 目标, "天罗地网", 编号) and (物法 == "普攻" or 物法 == "普攻连击" or 名称 ~= nil and 装备特技[名称] ~= nil) then
				伤害值 = 伤害值 * 1.5
			end

			if self.参战单位[编号].斩魔 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].斩魔 / 100)
			end

			if self.参战单位[编号].法术状态.轻歌飘舞 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.轻歌飘舞.造成物理伤害 / 100)
			end

			if self.参战单位[编号].法术状态.入魂 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.入魂.造成物理伤害 / 100)
			end

			if self.参战单位[编号].法术状态.存雄 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.存雄.造成物理伤害 / 100)
			end

			if self.参战单位[编号].法术状态.霹雳弦惊 ~= nil and self.参战单位[编号].法术状态.霹雳弦惊.造成物理伤害 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.霹雳弦惊.造成物理伤害 / 100)
			end

			if self.参战单位[编号].法术状态.雷怒霆激 ~= nil and self.参战单位[编号].法术状态.雷怒霆激.造成物理伤害 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.雷怒霆激.造成物理伤害 / 100)
			end

			if self.参战单位[编号].煞气 ~= nil and 名称 ~= nil then
				伤害值 = 伤害值 * self.参战单位[编号].煞气
			end

			if self.参战单位[编号].消耗超级战意 ~= nil and 名称 ~= nil and self:取奇经八脉是否有(编号, "妙得") == false then
				local jc = 0.2 + (self.参战单位[编号].惊涛 or 0) / 100
				伤害值 = 伤害值 * (1 + self.参战单位[编号].消耗超级战意 * jc)
			end

			if self.参战单位[目标].法术状态.天罗地网 ~= nil and self:取奇经八脉是否有(编号, "杀戮") then
				伤害值 = 伤害值 * 1.1
			end

			if self:取奇经八脉是否有(编号, "伤魂", "六道魍魉") and self:取是否有异常状态(目标) then
				伤害值 = 伤害值 * 1.06
			end

			if self.参战单位[编号].物伤增加 ~= nil then
				伤害值 = 伤害值 * self.参战单位[编号].物伤增加
			end

			if self.参战单位[编号].返璞 ~= nil and 名称 ~= nil and self.参战单位[编号].返璞[名称] ~= nil then
				伤害值 = 伤害值 * 1.1
			end

			if self.参战单位[编号].法术状态.真阳令旗 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.真阳令旗.造成物理伤害 / 100)
			end

			if self.参战单位[编号].返璞 ~= nil then
				伤害值 = 伤害值 * 1.1
			end

			if self.参战单位[编号].女儿矫健 ~= nil and self.参战单位[目标].类型 == "bb" and self.参战单位[编号].气血 >= self.参战单位[编号].最大气血 * 0.9 then
				伤害值 = 伤害值 * 1.1
			end

			if self.参战单位[目标].法术状态.烽火狼烟 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[目标].法术状态.烽火狼烟.受到物理伤害 / 100)
			end

			if self.参战单位[目标].法术状态.明光宝烛 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[目标].法术状态.明光宝烛.受到物理伤害 / 100)
			end

			if self.参战单位[目标].法术状态["雷法·坤伏"] ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[目标].法术状态["雷法·坤伏"].受到物理伤害 / 100)
			end
		else
			if self.参战单位[编号].力大无穷 ~= nil then
				临时计算属性.造成物理伤害 = 临时计算属性.造成物理伤害 + self.参战单位[编号].力大无穷
			end

			if self.参战单位[目标].力大无穷 ~= nil then
				临时计算属性.造成物理伤害 = 临时计算属性.造成物理伤害 - self.参战单位[目标].力大无穷
			end

			if self.参战单位[目标].五行健壮 ~= nil then
				临时计算属性.造成物理伤害 = 临时计算属性.造成物理伤害 + self.参战单位[目标].五行健壮 - 1
			end

			if self.参战单位[编号].煞气 ~= nil and 名称 ~= nil then
				临时计算属性.造成物理伤害 = 临时计算属性.造成物理伤害 + self.参战单位[编号].煞气 - 1
			end

			if self.参战单位[编号].消耗超级战意 ~= nil and 名称 ~= nil then
				local jc = 0.2 + (self.参战单位[编号].惊涛 or 0) / 100
				临时计算属性.造成物理伤害 = 临时计算属性.造成物理伤害 + self.参战单位[编号].消耗超级战意 * jc
			end

			if self.参战单位[目标].法术状态.天罗地网 ~= nil and self:取奇经八脉是否有(编号, "杀戮") then
				临时计算属性.造成物理伤害 = 临时计算属性.造成物理伤害 + 1.1 - 1
			end

			if 物法 ~= "物理" and self:取奇经八脉是否有(编号, "罗网") then
				临时计算属性.造成物理伤害 = 临时计算属性.造成物理伤害 + 1.1 - 1

				if self.参战单位[目标].法术状态.天罗地网 == nil then
					self:添加状态("天罗地网", self.参战单位[目标], self.参战单位[编号], self:取技能等级(编号, "天罗地网"), 编号)

					self.参战单位[目标].法术状态.天罗地网.回合 = 1
					self.战斗流程[攻击流程].挨打方[执行数].添加状态 = "天罗地网"
				end
			end

			if self.参战单位[编号].粘附 ~= nil and self:取是否有指定状态(编号, 目标, "天罗地网", 编号) and (物法 == "普攻" or 物法 == "普攻连击" or 名称 ~= nil and 装备特技[名称] ~= nil) then
				临时计算属性.造成物理伤害 = 临时计算属性.造成物理伤害 + 1.5 - 1
			end

			if self.参战单位[编号].斩魔 ~= nil then
				临时计算属性.造成物理伤害 = 临时计算属性.造成物理伤害 + self.参战单位[编号].斩魔 / 100
			end

			if self:取奇经八脉是否有(编号, "伤魂", "六道魍魉") and self:取是否有异常状态(目标) then
				临时计算属性.造成物理伤害 = 临时计算属性.造成物理伤害 + 1.06 - 1
			end

			if self.参战单位[编号].物伤增加 ~= nil then
				临时计算属性.造成物理伤害 = 临时计算属性.造成物理伤害 + self.参战单位[编号].物理增加 - 1
			end

			if self.参战单位[编号].返璞 ~= nil and 名称 ~= nil and self.参战单位[编号].返璞[名称] ~= nil then
				临时计算属性.造成物理伤害 = 临时计算属性.造成物理伤害 + 0.1
			end

			if self.参战单位[编号].女儿矫健 ~= nil and self.参战单位[目标].类型 == "bb" and self.参战单位[编号].气血 >= self.参战单位[编号].最大气血 * 0.9 then
				临时计算属性.造成物理伤害 = 临时计算属性.造成物理伤害 + 0.1
			end

			伤害值 = 伤害值 * 临时计算属性.造成物理伤害 * 临时计算属性.受到物理伤害
		end

		if self.参战单位[编号].法术状态.灵刃 ~= nil then
			if self.参战单位[目标].鬼魂 ~= nil or self.参战单位[目标].神佑 ~= nil then
				伤害值 = qz(伤害值 * 1.1)
			else
				伤害值 = qz(伤害值 * 1.5)
			end
		end

		if self.参战单位[目标].法术状态.风沙之盾 ~= nil and 天气 == 1 then
			伤害值 = 伤害值 * 0.6
		end

		if self.参战单位[编号].法术状态.骤雨 ~= nil then
			local aa = 2

			if self:取奇经八脉是否有(编号, "滂沱") then
				aa = 5

				if 天气 == 2 then
					aa = aa * 1.4
				end
			end

			伤害值 = 伤害值 * (1 + aa * (self.参战单位[编号].法术状态.骤雨.层数 or 1) / 100)
		end

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "协战") and self:取目标状态(编号 + 1, 编号 + 1, 2) then
			伤害值 = 伤害值 * 1.07
		end

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "突进") then
			self.参战单位[编号].伤害 = self.参战单位[编号].伤害 + 2
		end

		if 编号 ~= nil and self.参战单位[目标].气血 < self.参战单位[编号].气血 and self:取奇经八脉是否有(编号, "纯青") then
			伤害值 = 伤害值 * 1.1
		end

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "战神") then
			伤害值 = qz(伤害值 * 1.08)
		end

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "陌宝") then
			伤害值 = 伤害值 * 0.85
		end

		if self.参战单位[编号].法术状态.修罗隐身 ~= nil then
			local 隐匿击倍率 = 0

			if self.参战单位[编号].隐匿击 ~= nil and self.参战单位[编号].隐匿击 > 0 then
				隐匿击倍率 = 隐匿击倍率 + 0.02 * self.参战单位[编号].隐匿击
			end

			if self.参战单位[编号].神出鬼没 ~= nil then
				伤害值 = 伤害值 * (self.参战单位[编号].神出鬼没 + 隐匿击倍率)
			elseif self.参战单位[编号].隐身减伤 ~= nil then
				伤害值 = 伤害值 * (self.参战单位[编号].隐身减伤 + 隐匿击倍率)
			end
		elseif self.参战单位[编号].隐身减伤 ~= nil and self.参战单位[编号].神出鬼没 == nil then
			伤害值 = 伤害值 * self.参战单位[编号].隐身减伤
		end

		if self.参战单位[目标].防御判定 ~= nil and self.参战单位[编号].强力 ~= nil and self.参战单位[编号].强力 <= self.参战单位[目标].防御判定 then
			伤害值 = 伤害值 * 0.8
		end

		if self.参战单位[目标].招架 ~= nil and (self.参战单位[编号].强力 == nil or self.参战单位[目标].招架 > self.参战单位[编号].强力) then
			伤害值 = 伤害值 * self.参战单位[目标].招架减伤
		end

		local 物理简单判定倍率 = {
			"精神",
			"偷袭",
			"法术抵抗",
			"蛮劲",
			"超级夜战",
			"超级合纵",
			"超级飞行"
		}
		local 物理简单判定倍率1 = {}

		for i = 1, #物理简单判定倍率 do
			if self.参战单位[编号][物理简单判定倍率[i]] ~= nil then
				伤害值 = 伤害值 * self.参战单位[编号][物理简单判定倍率[i]]
			end
		end

		for i = 1, #物理简单判定倍率1 do
			if self.参战单位[目标][物理简单判定倍率1[i]] ~= nil then
				伤害值 = 伤害值 * self.参战单位[目标][物理简单判定倍率1[i]]
			end
		end

		if 物法 == "普攻" and (self.参战单位[编号].理直气壮 ~= nil or self.参战单位[编号].高级连击 ~= nil or self.参战单位[编号].超级连击 ~= nil or self:取技能重复(self.参战单位[编号], "连击") == true) then
			local 连击减伤 = {}

			if self.参战单位[编号].理直气壮 ~= nil then
				连击减伤[#连击减伤 + 1] = 理直气壮攻击系数
			end

			if self.参战单位[编号].超级连击 ~= nil then
				连击减伤[#连击减伤 + 1] = 超级连击攻击系数
			end

			if self.参战单位[编号].高级连击 ~= nil then
				连击减伤[#连击减伤 + 1] = 高级连击攻击系数
			end

			if self:取技能重复(self.参战单位[编号], "连击") == true then
				连击减伤[#连击减伤 + 1] = 连击攻击系数
			end

			伤害值 = 伤害值 * (取列表最大值(连击减伤) or 1)
		end

		if self.逍遥游增伤 > 0 and self.参战单位[编号].逍遥游 ~= nil then
			伤害值 = 伤害值 * self.逍遥游增伤
		end

		if self.参战单位[目标].逍遥游 ~= nil and self.参战单位[目标].逍遥游 == 1 then
			伤害值 = 伤害值 * 0.8

			self:添加战斗流程提示("#P(逍遥游)#R" .. self.参战单位[目标].名称 .. "#W本回合首次被攻击、抵御了#R" .. self.参战单位[编号].名称 .. "#W对其造成的#R20%#W伤害")

			self.参战单位[目标].逍遥游 = 0
		end

		if self.参战单位[目标].物伤减少 ~= nil then
			local kx = 最终抗性结果(self.参战单位[目标].物伤减少 - (self.参战单位[目标].特效物理防护 or 0) / 100)

			if self.参战单位[编号].物穿 ~= nil and kx < 1 then
				kx = 1 - (1 - kx) * (100 - self.参战单位[编号].物穿) / 100
			end

			伤害值 = 伤害值 * kx
		end

		if self.参战单位[编号].物伤加成百分比 ~= nil then
			伤害值 = 伤害值 * (1 + self.参战单位[编号].物伤加成百分比 / 100)
		end

		if self.参战单位[目标].物理减少百分比 ~= nil then
			local kx = 最终抗性结果(1 - self.参战单位[目标].物理减少百分比 / 100)

			if self.参战单位[编号].物穿 ~= nil and kx < 1 then
				kx = 1 - (1 - kx) * (100 - self.参战单位[编号].物穿) / 100
			end

			伤害值 = 伤害值 * kx
		end

		if 名称 == "荒古破击" and self.参战单位[目标].类型 ~= "角色" and self.参战单位[目标].速度 < self.参战单位[编号].速度 then
			伤害值 = 伤害值 * 1.4
		end

		if self.参战单位[编号].逆击 == nil and self.参战单位[目标].法术状态.神武盾气 ~= nil then
			伤害值 = 伤害值 * self.参战单位[目标].神武盾气减伤
		end

		if self.参战单位[目标].勇敢 == nil and self.参战单位[编号].法术状态.气势 ~= nil then
			伤害值 = 伤害值 * self.参战单位[编号].气势增伤
		end

		if self.参战单位[编号].物理加成 ~= nil then
			伤害值 = 伤害值 * self.参战单位[编号].物理加成
		end

		if 物攻群法技能列表[名称] == nil and self.参战单位[编号].从天而降 ~= nil and ygsj() <= 30 then
			伤害值 = 伤害值 * 1.3

			if 执行数 == nil then
				self:添加战斗流程提示("#P(从天而降)#R" .. self.参战单位[编号].名称 .. "#Y成功#R从天而降")
			end
		elseif self.参战单位[编号].从天而降 ~= nil and 执行数 == nil then
			self:添加战斗流程提示("#P(从天而降)#R" .. self.参战单位[编号].名称 .. "#G腾空失败#Y")
		end

		if self.参战单位[目标].法术状态.九梵清莲 ~= nil and self.参战单位[编号].类型 == "bb" then
			伤害值 = 伤害值 * (1 - self.参战单位[目标].法术状态.九梵清莲.说明 / 100)
		end

		if (self.参战单位[编号].物理伤害结果 or 0) > 0 then
			伤害值 = qz(伤害值 + self.参战单位[编号].物理伤害结果)
		end

		if self:取符石组合效果(编号, "百步穿杨") and ygsj() <= 20 then
			伤害值 = qz(伤害值 + self:取符石组合效果(编号, "百步穿杨"))
		end

		if self:取符石组合效果(目标, "心随我动") and ygsj() <= 20 then
			伤害值 = qz(伤害值 - self:取符石组合效果(目标, "心随我动"))
		end

		if 名称 == "连环击" and 编号 ~= nil and self:取奇经八脉是否有(编号, "乱破") then
			伤害值 = 伤害值 + qz(self.参战单位[编号].等级 * 5)
		end

		if 物法 == "普攻连击" and self.参战单位[编号].阴伤 ~= nil then
			伤害值 = 伤害值 + self.参战单位[编号].阴伤
		end

		if self.参战单位[编号].撞击 ~= nil and self.参战单位[编号].撞击 > 0 then
