		end

		if self.参战单位[编号].舍身击 ~= nil and self.参战单位[编号].舍身击 > 0 then
			伤害值 = qz(伤害值 + (self.参战单位[编号].力量 - self.参战单位[编号].等级) * 0.05 * self.参战单位[编号].舍身击)
		end

		if self.参战单位[目标].法术状态.爪印 ~= nil and self.参战单位[目标].法术状态.爪印.层数 ~= nil and self.参战单位[目标].爪印判定 == nil then
			伤害值 = qz(伤害值 + self.参战单位[编号].等级 * self.参战单位[目标].法术状态.爪印.层数)
			self.参战单位[目标].爪印判定 = 1
		end

		if 物法 == "普攻" or 物攻群法技能列表[名称] == nil then
			if self.参战单位[编号].狂化 ~= nil and ygsj() <= 12 and self.参战单位[self.参战单位[编号].狂化].法术状态.变身 ~= nil then
				伤害值 = 伤害值 * 2
			end

			if self:取奇经八脉是否有(目标, "爪印") or self:取奇经八脉是否有(编号, "爪印") then
				local 施加目标 = 目标 + 0
				local 爪印层数 = 1

				if self:取奇经八脉是否有(编号, "爪印") then
					施加目标 = 目标 + 0
					爪印层数 = 1

					if self.参战单位[施加目标].法术状态.爪印 == nil then
						self:添加状态("爪印", self.参战单位[施加目标], self.参战单位[施加目标], 爪印层数, 施加目标)

						self.参战单位[施加目标].法术状态.爪印.施加编号 = 编号 + 0

						self:客户端添加状态(施加目标, "爪印")
					else
						self.参战单位[施加目标].法术状态.爪印.层数 = self.参战单位[施加目标].法术状态.爪印.层数 + 爪印层数
						self.参战单位[施加目标].法术状态.爪印.回合 = 5
					end
				end

				if self:取奇经八脉是否有(目标, "爪印") then
					施加目标 = 编号 + 0
					爪印层数 = 1

					if self.参战单位[施加目标].法术状态.爪印 == nil then
						self:添加状态("爪印", self.参战单位[施加目标], self.参战单位[施加目标], 爪印层数, 施加目标)
						self:客户端添加状态(施加目标, "爪印")
					else
						self.参战单位[施加目标].法术状态.爪印.层数 = self.参战单位[施加目标].法术状态.爪印.层数 + 爪印层数
						self.参战单位[施加目标].法术状态.爪印.回合 = 5
					end
				end
			end
		end

		if 名称 ~= nil and 法术认证列表[名称] == nil and 新加普攻被动单法技能[名称] == nil and self.参战单位[编号].类型 == "bb" and self.参战单位[编号].主人 ~= nil then
			伤害值 = 伤害值 * 召唤兽门派技能减伤
		end

		if self.参战单位[编号].门派 == "九黎城" then
			伤害值 = 伤害值 - self.参战单位[目标].格挡值 * 0.3
		else
			伤害值 = 伤害值 - self.参战单位[目标].格挡值
		end

		if self.参战单位[目标].超级精神集中 ~= nil then
			伤害值 = 伤害值 * 90 / 100
		else
			伤害值 = 伤害值 * 取随机数(90, 110) / 100
		end

		if qz(伤害值) < 1 then
			伤害值 = 1
		end

		if self.参战单位[目标].物伤免疫 ~= nil then
			伤害值 = qz(math.max(伤害值 * self.参战单位[目标].物伤免疫, 1))
		end

		if 名称 == "超级壁垒击破" then
			self:添加状态("超级壁垒击破", self.参战单位[目标], self.参战单位[目标], self.参战单位[目标].等级, 目标, 1)
			self:添加战斗流程提示("#P(超级壁垒击破)#R" ..
			self.参战单位[编号].名称 .. "#W减少了#R" .. self.参战单位[目标].名称 .. "#W的#G防御力#W、效果持续到#Y本回合结束")
		end

		if 名称 == "舍身一搏" then
			local 舍身扣血 = 伤害值 * 0.2

			if self.参战单位[编号].气血 <= 舍身扣血 then
				舍身扣血 = self.参战单位[编号].气血 - 1
			end

			self:减少气血(编号, 舍身扣血)

			self.战斗流程[攻击流程].舍身扣血 = 舍身扣血
		end

		if self.参战单位[目标].鬼魂 == nil and (物法 == "普攻" or 物攻群法技能列表[名称] == nil) then
			local 吸血 = self.参战单位[编号].吸血

			if self:取奇经八脉是否有(编号, "化血") and ygsj() <= 30 then
				吸血 = (吸血 or 0) + 0.16
			end

			if 吸血 == nil and self.参战单位[编号].法术状态.移魂化骨 ~= nil then
				吸血 = self.参战单位[编号].法术状态.移魂化骨.等级 / 250
			end

			if 吸血 ~= nil or 名称 == "生杀予夺" then
				if 名称 == "生杀予夺" then
					local 吸血伤害 = qz1(伤害值)

					if 吸血伤害 <= 0 then
						吸血伤害 = 1
					end

					self:增加气血(编号, 吸血伤害)

					self.战斗流程[攻击流程].吸血伤害 = (self.战斗流程[攻击流程].吸血伤害 or 0) + 吸血伤害
				else
					local 吸血伤害 = qz1(伤害值 * 吸血)

					if 吸血伤害 <= 0 then
						吸血伤害 = 1
					end

					self:增加气血(编号, 吸血伤害)

					self.战斗流程[攻击流程].吸血伤害 = (self.战斗流程[攻击流程].吸血伤害 or 0) + 吸血伤害

					if self.参战单位[编号].低级吸血 ~= nil and self.参战单位[编号].法术状态.毒 == nil and self:负面技能施加判断(编号, "毒") and self:取是否有异常状态(目标) then
						self:添加状态("毒", self.参战单位[编号], self.参战单位[目标], self.参战单位[目标].等级, 目标)

