						local hd = qz1((self.参战单位[编号].气血 + 吸血伤害 - self.参战单位[编号].最大气血) * 0.5)
						hd = self:添加护盾(编号, hd, 编号)

						if hd > 0 then
							self:添加战斗流程提示("#P(超级吸血)#R" .. self.参战单位[编号].名称 .. "#W将溢出的吸收气血转化为#R" .. hd .. "点护盾")
						end
					end
				end
			end
		end

		if (物法 == "普攻" or 物法 == "普攻连击") and 伤害值 >= self.参战单位[目标].最大气血 * 0.05 and self.参战单位[编号].千钧一怒 ~= nil and self.参战单位[编号].类型 == "bb" and self.参战单位[编号].主人 ~= nil and self.参战单位[self.参战单位[编号].主人] ~= nil then
			local bh = self.参战单位[编号].主人或助战 or self.参战单位[编号].主人

			self:增加愤怒(bh, 30)
		end

		if self.参战单位[编号].毒 ~= nil and ygsj(毒概率基数) <= self.参战单位[编号].毒 and self:负面技能施加判断(目标, "毒", 编号) and self:负面技能施加判断(目标, "猛毒", 编号) then
			if self.参战单位[编号].超级毒 ~= nil and ygsj() <= 25 then
