				if 物法 == "法术" or 物法 == "固伤" or 名称 ~= nil and 物攻群法技能列表[名称] ~= nil then
					self.战斗流程[攻击流程].挨打方[执行数].添加状态 = "猛毒"
				else
					self.战斗流程[攻击流程].挨打方[执行数].添加状态 = "猛毒"
				end

				self:添加战斗流程提示("#P(猛毒)#R" .. self.参战单位[编号].名称 .. "#W对#R" .. self.参战单位[目标].名称 .. "#W施加了#G猛毒")
			else
				self:添加状态("毒", self.参战单位[目标], self.参战单位[编号], self.参战单位[编号].等级, 编号)

				if 物法 == "法术" or 物法 == "固伤" or 名称 ~= nil and 物攻群法技能列表[名称] ~= nil then
					self.战斗流程[攻击流程].挨打方[执行数].添加状态 = "毒"
				else
					self.战斗流程[攻击流程].挨打方[执行数].添加状态 = "毒"
				end

				self:添加战斗流程提示("#P(毒)#R" .. self.参战单位[编号].名称 .. "#W对#R" .. self.参战单位[目标].名称 .. "#W施加了#G毒")
			end
		end

		if (名称 == nil or 物攻群法技能列表[名称] == nil) and self.参战单位[编号].超级强力 ~= nil and ygsj() <= self.参战单位[编号].超级强力 and self:负面技能施加判断(目标, "晕眩") and self.参战单位[目标].不可封印 ~= true and self.参战单位[目标].法术状态.晕眩 == nil then
			self:添加状态("晕眩", self.参战单位[目标], self.参战单位[编号], self.参战单位[编号].等级, 编号)

			if 物法 == "法术" or 物法 == "固伤" or 名称 ~= nil and 物攻群法技能列表[名称] ~= nil then
				self.战斗流程[攻击流程].挨打方[执行数].添加状态 = "晕眩"
			else
				self.战斗流程[攻击流程].挨打方[执行数].添加状态 = "晕眩"
			end

