			self.参战单位[编号].名称 .. "#W重拳出击、对#G" .. self.参战单位[目标].名称 .. "#W造成了#G晕眩#W效果，使之当前回合#Y无法正常行动")
		end

		if self.参战单位[编号].冲击 ~= nil and ygsj(冲击概率基数) <= self.参战单位[编号].冲击 and 伤害值 > self.参战单位[目标].等级 * 5 and self.参战单位[目标].不可封印 ~= true and self.参战单位[目标].法术状态.冲击 == nil then
			self:添加状态("冲击", self.参战单位[目标], self.参战单位[编号], self.参战单位[编号].等级, 编号)

			if 物法 == "法术" or 物法 == "固伤" or 名称 ~= nil and 物攻群法技能列表[名称] ~= nil then
				self.战斗流程[攻击流程].挨打方[执行数].添加状态 = "冲击"
			else
				self.战斗流程[攻击流程].挨打方[执行数].添加状态 = "冲击"
			end

			self:添加战斗流程提示("#P(冲击)#R" .. self.参战单位[编号].名称 .. "#W对#R" .. self.参战单位[目标].名称 .. "#W造成了#G冲击#W，使之当前回合#Y无法行动")
		end

		if self.参战单位[目标].勇敢 == nil and self.参战单位[编号].恐吓 ~= nil and ygsj(恐吓概率基数) <= self:取新增技能触发几率("恐吓", 编号, 目标) and 伤害值 > self.参战单位[目标].等级 * 5 and self.参战单位[目标].不可封印 ~= true and self.参战单位[目标].类型 ~= "角色" and self:负面技能施加判断(目标, "恐吓") then
			self.恐吓击飞 = 1

			self:添加战斗流程提示("#P(恐吓)#R" .. self.参战单位[目标].名称 .. "#W被#R" .. self.参战单位[编号].名称 .. "#G恐吓，#W退出了战斗")
		end

		if self.参战单位[目标].上善若水 ~= nil and self:取目标状态(编号, 目标, 2) then
