		end

		if 名称 == "泼天乱棒" and 伤害值 < self.参战单位[目标].气血 then
			local 溅射人数 = math.min(qz(self:取技能等级(编号, "泼天乱棒") / 45) + 1, 3)

			self:物理溅射攻击(编号, 目标, {
				类型 = 2,
				伤害 = 伤害值 * 0.4
			}, 溅射人数)
		end

		if self.参战单位[编号].溅射 ~= nil and self.参战单位[编号].溅射 ~= 0 and self.参战单位[编号].逐胜 == nil then
