			local 方式 = "普攻"

			if 物法 ~= "普攻" and 物法 ~= "普攻连击" then
				方式 = "物理"

				if self:取奇经八脉是否有(编号, "风刃") then
					溅射人数 = 溅射人数 - 3
				end

				if self.参战单位[编号].溅射记录 == true then
					-- 溅射人数 = 0
				end

				if self.参战单位[编号].无心插柳 ~= nil and 名称 == "横扫千军" and self:取奇经八脉是否有(编号, "扶阵") and self:取玩家战斗() == false then
					溅射人数 = 溅射人数 + 2
				end
			elseif self.参战单位[编号].溅射记录 == true and self.参战单位[编号].无心插柳 ~= nil then
				-- 溅射人数 = 溅射人数 - 2
			end

			if 溅射人数 > 0 then
				self.参战单位[编号].溅射记录 = true

				self:物理溅射攻击(编号, 目标, {
					类型 = 1,
					伤害 = 伤害值
				}, 溅射人数, 方式)
			end
		end

		self.溅射排除单位 = {}
	elseif 物法 == "法术" and 类型 ~= 2 then
		if self.参战单位[编号].炼魂经脉 ~= nil and self.参战单位[目标].类型 == "角色" and self.参战单位[目标].玩家id ~= 0 then
			self.参战单位[目标].炼魂 = 编号
		end

		if 伤害叠加模式 == 1 then
			if self.参战单位[编号].法术状态.苍灵雪羽 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.苍灵雪羽.造成法术伤害 / 100)
			end

			if self.参战单位[编号].法术状态.真阳令旗 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.真阳令旗.造成法术伤害 / 100)
			end

			if self.参战单位[编号].法术状态.龙潜 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.龙潜.造成法术伤害 / 100)
			end

			if self.参战单位[编号].法术状态.蜜润 ~= nil and self.参战单位[编号].法术状态.蜜润.造成法术伤害 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.蜜润.造成法术伤害 / 100)
			end

			if self.参战单位[编号].法术状态.龍魂 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.龍魂.造成法术伤害 / 100)
			end

			if self.参战单位[编号].法术状态.魍魉追魂 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.魍魉追魂.造成法术伤害 / 100)
			end

			if self.参战单位[编号].法术状态.噬魂 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.噬魂.造成法术伤害 / 100)
			end

			if self.参战单位[编号].法术状态.魂魄 ~= nil and self.参战单位[编号].法术状态.魂魄.造成法术伤害 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.魂魄.造成法术伤害 / 100)
			end

			if self.参战单位[编号].法术状态.龙魂 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].法术状态.龙魂.造成法术伤害 / 100)
			end

			if self.参战单位[编号].返璞 ~= nil then
				伤害值 = 伤害值 * 0.9
			end

			if self.参战单位[编号].映雪棱镜 ~= nil and 判断模型是否是(self.参战单位[编号], "司雪") then
				伤害值 = 伤害值 * 1.17
			end

			if self.参战单位[编号].法伤增加 ~= nil then
				伤害值 = 伤害值 * self.参战单位[编号].法伤增加
			end

			if 天气 == 3 then
				if self:取奇经八脉是否有(编号, "霜雷") then
					伤害值 = 伤害值 * 1.1
				end
			elseif 天气 == 1 and self.参战单位[目标].法术状态.风沙之盾 ~= nil then
				伤害值 = 伤害值 * 0.6
			end

			if self.参战单位[目标].真灵 ~= nil then
				伤害值 = 伤害值 * self.参战单位[目标].真灵
			end

			if self.参战单位[目标].万物之灵 ~= nil then
				伤害值 = 伤害值 * (1 - self.参战单位[目标].万物之灵)
			end

			if self.参战单位[编号].万物之灵 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[编号].万物之灵)
			end

			if self:取奇经八脉是否有(编号, "批亢") and self.参战单位[编号].法术状态.分身术 ~= nil then
				伤害值 = 伤害值 * 1.2
			end

			if self.参战单位[目标].类型 == "角色" and self.参战单位[目标].玩家id ~= 0 and self:取奇经八脉是否有(编号, "顺势") then
				local bb = self.参战单位[目标].召唤兽

				if bb == nil or self:取目标状态(bb, bb, 2) == false then
					伤害值 = 伤害值 * 1.12
				end
			end

			if self.参战单位[目标].法术状态.雷浪穿云 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[目标].法术状态.雷浪穿云.受到法术伤害 / 100)
			end

			if self.参战单位[目标].法术状态.金身舍利 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[目标].法术状态.金身舍利.受到法术伤害 / 100)
			end

			if self.参战单位[目标].法术状态.龙啸 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[目标].法术状态.龙啸.受到法术伤害 / 100)
			end

			if self.参战单位[目标].法术状态.清吟 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[目标].法术状态.清吟.受到法术伤害 / 100)
			end

			if self.参战单位[目标].法术状态.苍灵雪羽 ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[目标].法术状态.苍灵雪羽.受到法术伤害 / 100)
			end

			if self.参战单位[目标].法术状态["雷法·坤伏"] ~= nil then
				伤害值 = 伤害值 * (1 + self.参战单位[目标].法术状态["雷法·坤伏"].受到法术伤害 / 100)
			end

			if 名称 == "雷霆万钧" and self.参战单位[目标].法术状态.电芒 ~= nil then
				local jc = 0.08

				if self:取奇经八脉是否有(编号, "惊曜") then
					jc = 0.1
				end

				伤害 = 伤害 * (1 + jc)
			end
		else
			if 天气 == 3 then
				if self:取奇经八脉是否有(编号, "霜雷") then
					临时计算属性.造成法术伤害 = 临时计算属性.造成法术伤害 + 0.1
				end
			elseif 天气 == 1 and self.参战单位[目标].法术状态.风沙之盾 ~= nil then
				临时计算属性.受到法术伤害 = 临时计算属性.受到法术伤害 - 0.4
			end

			if self.参战单位[目标].真灵 ~= nil then
				临时计算属性.受到法术伤害 = 临时计算属性.受到法术伤害 + self.参战单位[目标].真灵 - 1
			end

			if self.参战单位[目标].万物之灵 ~= nil then
				临时计算属性.受到法术伤害 = 临时计算属性.受到法术伤害 - self.参战单位[目标].万物之灵
			end

			if self.参战单位[编号].万物之灵 ~= nil then
				临时计算属性.造成法术伤害 = 临时计算属性.造成法术伤害 + self.参战单位[编号].万物之灵
			end

			if self:取奇经八脉是否有(编号, "批亢") and self.参战单位[编号].法术状态.分身术 ~= nil then
				临时计算属性.造成法术伤害 = 临时计算属性.造成法术伤害 + 1.2 - 1
			end

			if self.参战单位[编号].法伤增加 ~= nil then
				临时计算属性.造成法术伤害 = 临时计算属性.造成法术伤害 + self.参战单位[编号].法伤增加 - 1
			end

			if self.参战单位[目标].类型 == "角色" and self.参战单位[目标].玩家id ~= 0 and self:取奇经八脉是否有(编号, "顺势") then
				local bb = self.参战单位[目标].召唤兽

				if bb == nil or self:取目标状态(bb, bb, 2) == false then
					临时计算属性.造成法术伤害 = 临时计算属性.造成法术伤害 + 1.12 - 1
				end
			end

			if 名称 == "雷霆万钧" and self.参战单位[目标].法术状态.电芒 ~= nil then
				local jc = 0.08

				if self:取奇经八脉是否有(编号, "惊曜") then
					jc = 0.1
				end

				临时计算属性.造成法术伤害 = 临时计算属性.造成法术伤害 + jc
			end

			if self.参战单位[编号].返璞 ~= nil then
				临时计算属性.造成法术伤害 = 临时计算属性.造成法术伤害 - 0.1
			end

			if self.参战单位[编号].映雪棱镜 ~= nil and 判断模型是否是(self.参战单位[编号], "司雪") then
				临时计算属性.造成法术伤害 = 临时计算属性.造成法术伤害 + 0.17
			end

			伤害值 = 伤害值 * 临时计算属性.造成法术伤害 * 临时计算属性.受到法术伤害
		end

		if self.参战单位[编号].云霄 ~= nil then
			self:减少魔法(目标, 50)
		end

		if 名称 == "二龙戏珠" and self:取奇经八脉是否有(编号, "云变") then
			self:减少魔法(目标, self:取目标异常状态数量(目标) * 90)
		end

		if self:取奇经八脉是否有(目标, "守中") then
			伤害值 = 伤害值 * 0.94
		end

		if 法术认证列表[名称] == nil and 新加普攻被动单法技能[名称] == nil and self.参战单位[编号].类型 == "bb" and self.参战单位[编号].主人 ~= nil then
			伤害值 = 伤害值 * 召唤兽门派技能减伤
		end

		if 名称 == "月光" then
			if self.月光减伤 == nil then
				self.月光减伤 = {}
			end

			if self.月光减伤[目标] == nil then
				self.月光减伤[目标] = 1
			else
				伤害值 = 伤害值 * 0.5
			end
		elseif 超级技能群法列表[名称] ~= nil and 执行数 == 1 then
			伤害值 = 伤害值 * 1.1

			if ygsj() <= 25 then
				self:添加状态(超级技能群法列表[名称], self.参战单位[目标], self.参战单位[目标], self.参战单位[编号].等级, 编号, 2)
				self:添加战斗流程提示("#P(" ..
				名称 ..
				")#R" .. self.参战单位[编号].名称 .. "#W对#R" .. self.参战单位[目标].名称 .. "#W附加了#G2回合#W的#R" .. 超级技能群法列表[名称] .. "#W效果")
			end
		end

		if self.参战单位[编号].冰霜 ~= nil and self.参战单位[目标].法术状态.冰霜 == nil and ygsj() <= self:取新增技能触发几率("冰霜", 编号, 目标) and self:负面技能施加判断(目标, "冰霜") then
			self:添加状态("冰霜", self.参战单位[目标], self.参战单位[编号], self.参战单位[编号].等级, 编号, self.参战单位[编号].冰霜)
			self:添加战斗流程提示("#P(冰霜)#R" ..
			self.参战单位[编号].名称 .. "#W对#R" .. self.参战单位[目标].名称 .. "#W造成了#G冰霜#W，使之#R4#W回合内速度降低#R" .. self.参战单位[编号].冰霜 .. "%")
		end

		if self.参战单位[编号].门派 == "魔王寨" then
			local 触发 = false
			local 基础几率 = 2

			if self.参战单位[编号].法术状态.炙烤 ~= nil then
				基础几率 = 基础几率 + 20
			end

			if self.参战单位[编号].摇头摆尾1 ~= nil and self:取奇经八脉是否有(编号, "狂劲") then
				基础几率 = 基础几率 + 8
			end

			if self:取奇经八脉是否有(编号, "升温") then
				基础几率 = 基础几率 + 0.8 * self.回合数
			end

			if ygsj(1000) <= 基础几率 * 10 then
				触发 = true
			end

			if not 触发 and self:法宝判断("五火神焰印", 编号) ~= false then
				local 法宝名称 = "五火神焰印"

				for i = 1, #self.参战单位[编号].法宝列表[法宝名称] do
					local 法宝位置 = self.参战单位[编号].法宝列表[法宝名称][i]
					local 境界 = self:法宝概率判断(法宝名称, 编号, 法宝位置, 1)

					if 境界 ~= false then
						local 概率 = 境界 * 0.5

						if self:取奇经八脉是否有(编号, "神焰") then
							概率 = 概率 + 6
						end

						if self.参战单位[编号].焰星 ~= nil then
							概率 = 概率 + 5 * self.参战单位[编号].焰星
						end

						if ygsj() <= 概率 then
							触发 = true

							break
						end
					end
				end
			end

			if 触发 then
				local 倍率 = 1.4

				if self:取奇经八脉是否有(编号, "火神") and (名称 == "三昧真火" or 名称 == "飞砂走石") then
					倍率 = 倍率 + 0.14
				end

				if self:取奇经八脉是否有(编号, "威吓", {
						盖世魔君 = 1,
						平天大圣 = 1
					}) and self.参战单位[目标].类型 == "bb" then
					倍率 = 倍率 + 0.45
				end

				if self:取奇经八脉是否有(编号, "焰威") and (self.参战单位[编号].焰威 or 0) < 2 then
					self:增加愤怒(编号, 3)

					self.参战单位[编号].焰威 = (self.参战单位[编号].焰威 or 0) + 1
				end

				伤害值 = 伤害值 * 倍率

				self:添加战斗流程提示("#P(门派特色)#R" ..
				self.参战单位[编号].名称 .. "#W触发了#G神焰#W本次法术攻击对#R" .. self.参战单位[目标].名称 .. "#W造成的伤害增加#Y" .. (倍率 - 1) * 100 .. "%")

				if self:取奇经八脉是否有(编号, "折服") and (名称 == "三昧真火" or 名称 == "飞砂走石" and ygsj() <= 25) then
					local 可取消状态 = self:驱散目标状态(目标, 编号)
					self.战斗流程[攻击流程].挨打方[执行数].取消状态 = 可取消状态
				end
			end
		end

		if self.参战单位[编号].法术状态.蚀天 ~= nil then
			伤害值 = 伤害值 * 1.15
		end

		if self.参战单位[编号].悲悯 ~= nil then
			伤害值 = 伤害值 * self.参战单位[编号].悲悯
		end

		if self.参战单位[目标].勇敢 == nil and self.参战单位[编号].法术状态.震摄 ~= nil then
			伤害值 = 伤害值 * self.参战单位[编号].震摄增伤
		end

		if self.参战单位[目标].蛮劲 ~= nil then
			伤害值 = 伤害值 * 1.1
		end

		if 名称 == "琴音三叠2" or 名称 == "琴音三叠3" or 名称 == "琴音三叠" then
			if self.参战单位[编号].抚琴 ~= nil then
				伤害值 = 伤害值 * self.参战单位[编号].抚琴
			end

			if self.参战单位[编号].穿透 ~= nil and self.参战单位[目标].类型 == "bb" then
				伤害值 = 伤害值 * self.参战单位[编号].穿透
			end

			if self:取奇经八脉是否有(编号, "仙音") and self.参战单位[目标].法术状态.电芒 ~= nil then
				伤害值 = 伤害值 * 1.16
			end

			if self:取奇经八脉是否有(编号, "金睛", "通天行者") and self:取五行克制(self.参战单位[编号].攻击五行, self.参战单位[目标].防御五行) then
				伤害值 = 伤害值 * 1.5
			end
		end

		if self.逍遥游增伤 > 0 and self.参战单位[编号].逍遥游 ~= nil then
			伤害值 = 伤害值 * self.逍遥游增伤
		end

		if self.参战单位[目标].逍遥游 ~= nil and self.参战单位[目标].逍遥游 == 1 then
			伤害值 = 伤害值 * 0.8

			self:添加战斗流程提示("#P(逍遥游)#R" .. self.参战单位[目标].名称 .. "#W本回合首次被攻击、抵御了#R" .. self.参战单位[编号].名称 .. "#W对其造成的#R20%#W伤害")

			self.参战单位[目标].逍遥游 = 0
		end

		if self.参战单位[目标].法伤减少 ~= nil then
			local kx = 最终抗性结果(self.参战单位[目标].法伤减少 - (self.参战单位[目标].特效法术防护 or 0) / 100)

			if self.参战单位[编号].法穿 ~= nil and kx < 1 then
				local aa = 100

				if self.参战单位[编号].琴魂 ~= nil then
					aa = aa - 10
				end

				if self.参战单位[编号].惊鸿 ~= nil then
					aa = aa - 12
				end

				if self.参战单位[编号].汹涌 ~= nil then
					aa = aa - 8
				end

				kx = 1 - (1 - kx) * math.max(aa - self.参战单位[编号].法穿, 0) / 100
			end

			伤害值 = 伤害值 * kx
		end

		if self.参战单位[编号].法伤加成百分比 ~= nil then
			伤害值 = 伤害值 * (1 + self.参战单位[编号].法伤加成百分比 / 100)
		end

		if self.参战单位[目标].法术减少百分比 ~= nil then
			local kx = 最终抗性结果(1 - self.参战单位[目标].法术减少百分比 / 100)

			if self.参战单位[编号].法穿 ~= nil and kx < 1 then
				kx = 1 - (1 - kx) * (100 - self.参战单位[编号].法穿) / 100
			end

			伤害值 = 伤害值 * kx
		end

		if 名称 == "翻江倒海" then
			if self.参战单位[编号].法术状态.衰弱 == nil and self.参战单位[编号].翻江倒海回合 ~= nil and self.回合数 == self.参战单位[编号].翻江倒海回合 + 1 then
				self:添加状态("衰弱", self.参战单位[编号])

				self.战斗流程[攻击流程].添加状态 = "衰弱"
			end

			if self.参战单位[编号].法术状态.衰弱 ~= nil then
				伤害值 = 伤害值 * 0.7

				if 执行数 == 1 then
					self:添加战斗流程提示("#P(翻江倒海)#R" .. self.参战单位[编号].名称 .. "#W处于#R衰弱#W状态、#R翻江倒海#W造成的伤害将减少#R30%#W")
				end
			end

			self.参战单位[编号].翻江倒海回合 = self.回合数 + 0
		end

		if self:取符石组合效果(self.参战单位[目标], "云随风舞") and ygsj() <= 20 then
			伤害值 = 伤害值 - self:取符石组合效果(self.参战单位[目标], "云随风舞")
		end

		伤害值 = 伤害值 + self.参战单位[编号].法术伤害结果

		if self.参战单位[编号].类型 ~= "bb" and self:法宝判断("失心钹", 目标) ~= false then
			local 法宝名称 = "失心钹"

			for i = 1, #self.参战单位[目标].法宝列表[法宝名称] do
				local 法宝位置 = self.参战单位[目标].法宝列表[法宝名称][i]
				local 境界 = self:法宝概率判断(法宝名称, 目标, 法宝位置, 1)

				if 境界 ~= false then
					伤害值 = 伤害值 - 境界 * 15
					伤害值 = math.max(伤害值, 0)
				end
			end
		end

		伤害值 = 伤害值 * 取随机数(90, 110) / 100

		if qz(伤害值) < 1 then
			伤害值 = 1
		end

		if 名称 == "天外飞剑" then
			if ygsj() <= 30 then
				伤害值 = 1
			else
				伤害值 = math.floor(self.参战单位[目标].气血 * 0.1)
			end
		end

		if self.参战单位[目标].法伤免疫 ~= nil then
			伤害值 = qz(math.max(伤害值 * self.参战单位[目标].法伤免疫, 1))
		end

		if 名称 == "意马心猿" and 伤害值 < self.参战单位[目标].气血 then
			local 溅射人数 = 3

			self:物理溅射攻击(编号, 目标, {
				类型 = 2,
				伤害 = 伤害值 * 0.4
			}, 溅射人数)
		end

		if 吸收 ~= nil then
			local 触发 = nil
			local bb = false

			if 吸收 == "土" and self.参战单位[目标].雷吸 == 1 or 吸收 == "雷" and self.参战单位[目标].土吸 == 1 or 吸收 == "水" and self.参战单位[目标].火吸 == 1 or 吸收 == "火" and self.参战单位[目标].水吸 == 1 then
				伤害值 = 伤害值 * 1.3
			end

			if 吸收 == "土" and self.参战单位[目标].土吸 ~= nil then
				触发 = self.参战单位[目标].土吸
				bb = true
			elseif 吸收 == "水" and self.参战单位[目标].水吸 ~= nil then
				触发 = self.参战单位[目标].水吸
				bb = true
			elseif 吸收 == "火" and self.参战单位[目标].火吸 ~= nil then
				触发 = self.参战单位[目标].火吸
				bb = true
			elseif 吸收 == "雷" and self.参战单位[目标].雷吸 ~= nil then
				触发 = self.参战单位[目标].雷吸
				bb = true
			end

			if self.参战单位[目标].四系法术吸收概率 ~= nil then
				触发 = 触发 or 1
			end

			if 触发 ~= nil then
				local 基础几率 = 0
				基础几率 = bb and 50 + (self.参战单位[目标].四系法术吸收概率 or 0) or self.参战单位[目标].四系法术吸收概率 or 0

				if self.参战单位[目标].法术状态.颠倒五行 ~= nil then
					基础几率 = self.参战单位[目标].四系法术吸收概率
					触发 = math.max(1, 触发)

					if 编号 ~= nil and self:取奇经八脉是否有(编号, "法印") then
						触发 = 触发 * 1.15
					end
				end

				if 触发 == 3 then
					基础几率 = 100
				end

				if 取随机数(1, 10000) <= 基础几率 * 100 then
					伤害值 = 伤害值 * 0.5 * math.min(触发, 2)
					类型 = 2
				elseif 触发 == 2 then
					伤害值 = 伤害值 * 0.7
				end
			end
		end
	elseif 物法 == "固伤" and 类型 ~= 2 then
		if self.参战单位[编号].云霄 ~= nil then
			self:减少魔法(目标, 50)
		end

		if 名称 == "雨落寒沙" and 编号 ~= nil and self:取奇经八脉是否有(编号, "暗伤") and self:取玩家战斗() == false then
			伤害值 = 伤害值 + self.参战单位[编号].武器伤害 * 0.18
		end

		if 名称 ~= nil and 五行固伤法术[名称] ~= nil and self:取奇经八脉是否有(编号, "慧眼") and self.参战单位[目标].类型 == "bb" and self.参战单位[目标].玩家id ~= 0 and self:取五行克制(五行固伤法术[名称], self.参战单位[目标].防御五行) then
			伤害值 = 伤害值 * 1.6

			if ygsj() <= 60 then
				self:添加状态("慧眼", self.参战单位[目标])
				self:更新单个法术状态(目标, "慧眼")
			end
		end

		if 名称 == "判官令" then
			if self.参战单位[编号].阎罗 ~= nil then
				伤害值 = 伤害值 * 1.5
			end
		elseif 名称 == "阎罗令" then
			if self:取玩家战斗() == false and self:取奇经八脉是否有(编号, "阎罗") and self.参战单位[编号].装备属性 ~= nil then
				伤害值 = 伤害值 + self.参战单位[编号].装备属性.伤害 * 0.15
			end
		elseif 名称 == "追魂刺" then
			if self:取奇经八脉是否有(编号, "刺骨") and self:取是否玩家角色(目标) then
				伤害值 = 伤害值 * 1.12
			end

			if self:取奇经八脉是否有(编号, "鬼袭") and self:取玩家战斗() and self.参战单位[目标].类型 == "bb" then
				伤害值 = 伤害值 * 1.6
			end

			if self:取是否有指定状态(编号, 目标, "魂魄") then
				伤害值 = 伤害值 * 2
				local aa = self.参战单位[目标].法术状态.魂魄.攻击编号

				if aa ~= nil then
					self.参战单位[aa].裂魂 = self.参战单位[aa].裂魂 - 1
				end

				self:取消状态("魂魄", self.参战单位[目标])
			end
		elseif 名称 == "夺命咒" and 编号 ~= nil then
			if self:取是否有指定状态(编号, 目标, "魂魄") then
				伤害值 = 伤害值 * 2
				local aa = self.参战单位[目标].法术状态.魂魄.攻击编号

				if aa ~= nil then
					self.参战单位[aa].裂魂 = self.参战单位[aa].裂魂 - 1
				end

				self:取消状态("魂魄", self.参战单位[目标])
			end

			if self:取奇经八脉是否有(编号, "内伤") and self.参战单位[编号].武器伤害 ~= nil then
				伤害值 = 伤害值 + self.参战单位[编号].武器伤害 * 0.15
			end

			if self:取奇经八脉是否有(编号, "追魂") then
				local 人物敏捷 = self.参战单位[编号].敏捷

				if qz(self.参战单位[编号].等级 * 2.2) <= 人物敏捷 then
					伤害值 = 伤害值 + (self.参战单位[编号].被动技能.枯骨心法 or self.参战单位[编号].等级)
				end
			end
		end

		if self:取奇经八脉是否有(编号, "冥煞") and ygsj() <= 5 then
			伤害值 = 伤害值 * 2
		end

		if self.参战单位[编号].金莲 ~= nil then
			伤害值 = 伤害值 * 0.7
		end

		if self.参战单位[编号].裂魂 ~= nil then
			local gl = 40
			local gljc = 0
			local 判定 = false

			if 名称 == "夺命咒" and self:取玩家战斗() and self:取奇经八脉是否有(编号, "余咒", "幽冥巫煞") then
				gl = gl * 0.3
				判定 = true
			elseif 名称 == "追魂刺" then
				判定 = true
			end

			if 判定 then
				if 编号 ~= nil and self:取奇经八脉是否有(编号, "聚魂", "幽冥巫煞") then
					gl = gl * 0.5
				end

				if 名称 == "追魂刺" and self:取是否有指定状态(编号, 编号, "燃血术·幽冥巫煞") then
					gljc = gljc + gl * 0.8
				end

				if ygsj() <= gl + gljc then
					if self:取奇经八脉是否有(编号, "纠缠") then
						self:增加愤怒(编号, 4)
					end

					if self:取是否玩家角色(目标) then
						local sx = 1

						if self.参战单位[编号].独一 ~= nil then
							sx = 2
						end

						if self.参战单位[编号].裂魂 < sx then
							self.参战单位[编号].裂魂 = self.参战单位[编号].裂魂 + 1

							self:添加状态("魂魄", self.参战单位[目标], self.参战单位[编号], 等级, 编号)
							self:添加战斗流程提示("#P(裂魂)#R" .. self.参战单位[编号].名称 .. "#W击出了#R" .. self.参战单位[目标].名称 .. "#的#S魂魄",
								攻击流程)
						end
					else
						local jc = 1.3

						if self:取奇经八脉是否有(编号, "魂守") then
							jc = jc + 0.05
						end

						if self:取奇经八脉是否有(编号, "羽裂") then
							jc = jc + 0.06
						end

						伤害值 = 伤害值 * jc
					end
				end
			end
		end

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "聚魂", "幽冥巫煞") then
			伤害值 = 伤害值 * 1.08
		end

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "攻云") then
			伤害值 = qz(伤害值 * 1.4)
		end

		if self.参战单位[编号].固定伤害百分比 ~= nil then
			伤害值 = 伤害值 * (1 + self.参战单位[编号].固定伤害百分比 / 100)
		end
	end

	if self.参战单位[目标].磐石 ~= nil then
		if self.参战单位[目标].磐石.单位[编号] == nil then
			self.参战单位[目标].磐石.单位[编号] = self.参战单位[目标].磐石.伤害 + 0
			self.参战单位[目标].磐石.伤害 = self.参战单位[目标].磐石.伤害 + 55
		end

		伤害值 = math.max(伤害值 - self.参战单位[目标].磐石.单位[编号], 1)
	end

	if (物法 == "法术" or 物法 == "固伤") and self:取奇经八脉是否有(目标, "回旋") then
		伤害值 = math.max(伤害值 - 65, 1)
	end

	if 类型 ~= 2 and self.参战单位[目标].超级幸运 ~= nil and ygsj() <= self.参战单位[目标].超级幸运 then
		伤害值 = 0
		类型 = 2

		self:添加战斗流程提示("#P(超级幸运)#R" .. self.参战单位[目标].名称 .. "#W免疫了#R" .. self.参战单位[编号].名称 .. "#W本次的攻击。")
	end

	if 类型 ~= 2 then
		if 名称 == "刀背打" and self.参战单位[目标].气血 <= 伤害值 then
			伤害值 = self.参战单位[目标].气血 - 1

			if 伤害值 < 0 then
				伤害值 = 0
			end

			self:添加战斗流程提示("#P(刀背打)#R" .. self.参战单位[编号].名称 .. "#W保住了#R" .. self.参战单位[目标].名称 .. "#W的性命。")
		end

		self.真实伤害 = 伤害值
	else
		self.真实伤害 = nil
	end

	if 类型 ~= 2 then
		if self.法术吸血流程[流程] ~= nil and self.参战单位[目标].鬼魂 == nil and 名称 ~= nil and 法术吸血技能[名称] ~= nil then
			self.法术吸血流程[流程].伤害值 = self.法术吸血流程[流程].伤害值 + 伤害值
		end

		if self.参战单位[编号].秘传击杀 == nil then
			self.参战单位[目标].夜光复活神佑判定 = false

			if self.参战单位[目标].鬼魂 == nil and self.参战单位[目标].神佑 ~= nil and 伤害值 >= self.参战单位[目标].气血 + self:取护盾值(目标) then
				self:取消状态("护盾", self.参战单位[目标])

				if ygsj() <= self.参战单位[目标].神佑 then
					if self.参战单位[编号].审判 ~= nil then
						self:添加战斗流程提示("#P(审判)#R" ..
						self.参战单位[目标].名称 .. "#W想要#R神佑复生#W、但被" .. self.参战单位[编号].名称 .. "#Y审判#W击飞了")
					elseif self.参战单位[编号].超级信仰 ~= nil then
						self:添加战斗流程提示("#P(超级否定信仰)#R" ..
						self.参战单位[目标].名称 .. "#W想要#R神佑复生#W、但被" .. self.参战单位[编号].名称 .. "#W否定了#Y信仰")
					elseif self.参战单位[编号].法术状态.灵断 ~= nil then
						self:添加战斗流程提示("#P(灵断)#R" ..
						self.参战单位[目标].名称 .. "#W想要#R神佑复生#W、但被" .. self.参战单位[编号].名称 .. "#Y灵断#W打断了")
					else
						if self.参战单位[目标].高级神佑 ~= nil then
							伤害值 = self.参战单位[目标].气血 - self.参战单位[目标].最大气血 * 高级神佑气血

							if self.参战单位[目标].超级神佑 ~= nil then
								local hd = self:添加护盾(目标, self.参战单位[目标].最大气血 * 0.4)

								self:添加战斗流程提示("#P(超级神柚复生)#R" .. self.参战单位[目标].名称 .. "#Y神柚复生#W啦、并获得了" .. hd .. "#点护盾。")
							end
						else
							伤害值 = self.参战单位[目标].气血 - self.参战单位[目标].最大气血 * 神佑气血
						end

						if 伤害值 <= 0 then
							伤害值 = -伤害值
							类型 = 2
						end

						self.参战单位[目标].神佑效果 = true
						self.参战单位[目标].夜光复活神佑判定 = true

						self:添加战斗流程提示("#P(神佑)#R" .. self.参战单位[目标].名称 .. "#G神佑复生#Y了")
					end
				end
			end

			if self.参战单位[目标].神佑 == nil and self.参战单位[目标].保命 ~= nil and self.参战单位[目标].气血 <= 伤害值 and 取随机数(1, 保命概率基数 * 100) <= self.参战单位[目标].保命 * 100 then
				local 保留气血 = self.参战单位[目标].等级 * 保命气血

				if self.参战单位[目标].高级保命 ~= nil then
					保留气血 = self.参战单位[目标].等级 * 高级保命气血
				end

				if 保留气血 < 1 then
					保留气血 = 1
				end

				伤害值 = self.参战单位[目标].气血 - 保留气血

				if 伤害值 <= 0 then
					伤害值 = -伤害值
					类型 = 2
				end

				self.参战单位[目标].夜光复活神佑判定 = true

				self:添加战斗流程提示("#P(保命)#R" .. self.参战单位[目标].名称 .. "#W触发了#G保命")
			end

			if self.参战单位[目标].夜光复活 ~= nil and ygsj() <= self.参战单位[目标].夜光复活 and self.参战单位[目标].夜光复活神佑判定 == false and self.参战单位[目标].气血 <= 伤害值 then
				伤害值 = qz(self.参战单位[目标].气血 - self.参战单位[目标].最大气血 * 0.5)

				if 伤害值 <= 0 then
					伤害值 = -伤害值
					类型 = 2
				end

				self.参战单位[目标].神佑效果 = true
				self.参战单位[目标].夜光复活神佑判定 = 1
				self.参战单位[目标].夜光复活 = self.参战单位[目标].夜光复活 - 25

				self:添加战斗流程提示("#P(出其不意)#R" .. self.参战单位[目标].名称 .. "#W触发了#G出其不意#W，半血复活！")
			end
		end
	end

	if 类型 ~= 2 then
		if (物法 == "物理" or 物法 == "普攻" or 物法 == "普攻连击") and 编号 ~= nil and self:取奇经八脉是否有(编号, "摧心") then
			self.参战单位[目标].摧心 = 编号
		end

		if self.参战单位[目标].法术状态.炎护 ~= nil then
			local 临时伤害值 = qz(伤害值 * 0.5)

			if 临时伤害值 > 1 then
				if 临时伤害值 < self.参战单位[目标].魔法 then
					self.参战单位[目标].魔法 = self.参战单位[目标].魔法 - 临时伤害值
					临时伤害值 = 0
				else
					临时伤害值 = 临时伤害值 - self.参战单位[目标].魔法
					self.参战单位[目标].魔法 = 0
				end

				伤害值 = qz(伤害值 * 0.5) + 临时伤害值
			end
		end

		if 目标 ~= nil and self:取奇经八脉是否有(目标, "不舍") and qz(self.参战单位[目标].最大气血 * 0.2) < 伤害值 and self.参战单位[目标].气血 >= 1 then
			local 血量 = qz1((self.参战单位[目标].被动技能.归元心法 or self.参战单位[目标].等级) * 2 +
			math.max(self.参战单位[目标].灵力, self.参战单位[目标].法伤) * 0.1)

			self:增加气血(目标, 血量)

			self.战斗流程[攻击流程].挨打方[执行数].恢复气血 = 血量
			self.战斗流程[攻击流程].挨打方[执行数].特效[#self.战斗流程[攻击流程].挨打方[执行数].特效 + 1] = "归元咒"
		end
	end

	--	if 名称 == "毁灭之光" and self.参战单位[编号].玩家id ~= 0 and 毁灭之光测试通杀 then
	--	类型 = 1
	--伤害值 = self.参战单位[目标].气血 + 9999
	--elseif self.参战单位[编号].秘传击杀 ~= nil then
	--self:添加战斗流程提示("#P(秘传法术)#R" .. self.参战单位[编号].名称 .. "#W使用#Y" .. 名称 .. "#W直接击杀了#G" .. self.参战单位[目标].名称)

	--类型 = 1
	--伤害值 = self.参战单位[目标].气血 + 9999
	--	end

	self.参战单位[编号].秘传击杀 = nil

	if self.参战单位[编号].队伍 == 0 and self.蓐收光环 ~= nil then
		if 执行数 == 1 then
			self.战斗流程[#self.战斗流程 + 1] = {
				流程 = 1024,
				攻击方 = 编号,
				挨打方 = {}
			}
			self.蓐收光环流程 = #self.战斗流程 + 0
			self.战斗流程[self.蓐收光环流程].挨打方[1] = {
				气血类型 = 2,
				气血 = 0
			}

			if 编号 == self.蓐收光环.单位 then
				self.战斗流程[self.蓐收光环流程].挨打方[1].挨打方 = self:取单个存活友方目标(编号)
			else
				self.战斗流程[self.蓐收光环流程].挨打方[1].挨打方 = self.蓐收光环.单位
			end
		end

		if 类型 ~= 2 then
			local jx = qz(伤害值 * self.蓐收光环.吸血)

			self:增加气血(self.战斗流程[self.蓐收光环流程].挨打方[1].挨打方, jx)

			self.战斗流程[self.蓐收光环流程].挨打方[1].气血 = (self.战斗流程[self.蓐收光环流程].挨打方[1].气血 or 0) + jx
		end
	elseif self.参战单位[编号].队伍 == 0 and self.参战单位[编号].法术状态.句芒光环 ~= nil and self.参战单位[编号].法术状态.句芒光环.光环 == 3 and self.参战单位[编号].名称 == "句芒" then
		if 执行数 == 1 then
			self.战斗流程[#self.战斗流程 + 1] = {
				流程 = 1024,
				攻击方 = 编号,
				挨打方 = {}
			}
			self.句芒光环流程 = #self.战斗流程 + 0
			self.战斗流程[self.句芒光环流程].挨打方[1] = {
				气血类型 = 2,
				气血 = 0,
				挨打方 = self:取我方气血最低(编号)
			}
		end

		if 类型 ~= 2 then
			local jx = qz(伤害值 * 0.5)

			self:增加气血(self.战斗流程[self.句芒光环流程].挨打方[1].挨打方, jx)

			self.战斗流程[self.句芒光环流程].挨打方[1].气血 = (self.战斗流程[self.句芒光环流程].挨打方[1].气血 or 0) + jx
		end
	end

	return {
		伤害 = 伤害值,
		类型 = 类型
	}
end

function 战斗处理类:取新增技能触发几率(名称, 编号, 目标)
	local 名称1, js1, js2, js3 = nil

	if 名称 == "冰霜" then
		js2 = 5
		js3 = 20

		if self.参战单位[编号].高级冰霜 ~= nil then
			js2 = 8
			js3 = 35
		end

		js1 = self.参战单位[编号].魔力 or 0

		if js1 <= self.参战单位[编号].等级 then
			return js2
		elseif self.参战单位[编号].魔力 >= self.参战单位[编号].等级 * 5 then
			return js3
		else
			return qz1(js2 + (js3 - js2) * self.参战单位[编号].魔力 / (self.参战单位[编号].等级 * 5))
		end
	elseif 名称 == "恐吓" then
		js2 = 恐吓最低概率
		js3 = 恐吓最高概率

		if self.参战单位[编号].恐吓 == 2 then
			js2 = 高级恐吓最低概率
			js3 = 高级恐吓最高概率
		end

		js1 = self.参战单位[编号].力量 or self.参战单位[编号].等级

		if js1 <= self.参战单位[编号].等级 then
			return js2
		elseif self.参战单位[编号].力量 >= self.参战单位[编号].等级 * 5 then
			return js3
		else
			return qz1(js2 + (js3 - js2) * js1 / (self.参战单位[编号].等级 * 5))
		end
	elseif 名称 == "八凶法阵" then
		js2 = 八凶法阵最低概率
		js3 = 八凶法阵最高概率
		js1 = self.参战单位[编号].魔力 or self.参战单位[编号].等级

		if js1 <= self.参战单位[编号].等级 then
			return js2
		elseif self.参战单位[编号].魔力 >= self.参战单位[编号].等级 * 5 then
			return js3
		else
			return qz1(js2 + (js3 - js2) * js1 / (self.参战单位[编号].等级 * 5))
		end
	elseif 名称 then
	end
end

function 战斗处理类:添加战斗流程提示(内容1, 流程)
	if self.战斗流程 == nil or 判断是否为空表(self.战斗流程) then
		return
	end

	if 流程 == nil then
		流程 = #self.战斗流程 + 0
	end

	if self.战斗流程[流程].提示1 == nil or self.战斗流程[流程].提示1.内容 == nil then
		self.战斗流程[流程].提示1 = {
			内容 = 内容1
		}
	else
		self.战斗流程[流程].提示1.内容 = self.战斗流程[流程].提示1.内容 .. "\n" .. 内容1
	end
end

function 战斗处理类:物理溅射攻击(编号, 目标, 伤害, 数量, 方式)
	if 数量 == nil then
		数量 = 1
	end

	if 伤害 == nil then
		伤害 = 1
	end

	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 613,
		攻击方 = 编号,
		挨打方 = {}
	}
	local 精准战斗流程 = #self.战斗流程 + 0
	self.执行等待 = 0
	local 目标组 = {}

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 ~= self.参战单位[编号].队伍 and self:取目标状态(编号, n, 1) and n ~= 目标 and self.溅射排除单位[n] == nil then
			目标组[#目标组 + 1] = n
		end
	end

	if #目标组 == 0 then
		return
	end

	if 数量 < #目标组 then
		随机排序(目标组)

		local 临时目标组 = 目标组
		目标组 = {}

		for i = 1, 数量 do
			目标组[i] = 临时目标组[i]
		end
	end

	local 溅射伤害 = 伤害

	for i = 1, #目标组 do
		local 伤害1 = 溅射伤害.伤害 + 0

		if 溅射伤害.类型 == 1 then
			if 编号 ~= nil and 方式 == "普攻" and self:取奇经八脉是否有(编号, "风刃") and i <= 3 then
				if self.参战单位[编号].法术状态.风魂 ~= nil then
					伤害1 = self.参战单位[编号].等级 * 3 + 1000
				else
					伤害1 = self.参战单位[编号].等级 * 3
				end
			else
				伤害1 = 伤害1 * math.max(self.参战单位[编号].溅射 or 0, 0.15)
			end
		end

		if self:取玩家战斗() then
			伤害1 = qz1(伤害1 * 0.5)
		else
			伤害1 = qz1(伤害1)
		end

		local 最终结果1 = nil
		x挨打 = #self.战斗流程[精准战斗流程].挨打方 + 1
		self.战斗流程[精准战斗流程].挨打方[x挨打] = {
			挨打方 = 目标组[i]
		}
		最终结果1 = self:新增状态处理("固伤", 编号, 目标, 伤害1, 1, i, nil, nil, nil, 精准战斗流程 + 0)
		self.战斗流程[精准战斗流程].挨打方[x挨打].伤害 = 最终结果1.伤害
		self.战斗流程[精准战斗流程].挨打方[x挨打].类型 = 最终结果1.类型

		if 最终结果1 ~= 2 then
			self.战斗流程[精准战斗流程].挨打方[x挨打].死亡 = self:减少气血(目标组[i], 最终结果1.伤害, 编号, 名称, nil, nil, 1)
		end
	end

	self.溅射排除单位 = {}
end

function 战斗处理类:物攻群法计算1(编号, 名称, 等级, 目标, 目标数, 执行数, 伤害系数, 物攻群法流程)
	self.战斗流程[物攻群法流程].挨打方[执行数] = {
		特效 = {},
		挨打方 = 目标
	}
	self.执行等待 = self.执行等待 + 10
	local 待加特效 = {}
	local 必杀 = false
	local 防御 = false
	local 伤害 = self:取基础物理伤害(编号, 目标, 名称) * 1
	local 伤害系数1 = nil

	if 名称 == "剑气四射" or 名称 == "剑气四射·觉醒" then
		伤害 = 伤害 + 等级 * 0.5
		伤害系数1 = 0.9

		if 目标数 == 1 then
			伤害系数1 = math.max(分灵系数.单法系数, 伤害系数1)
		end

		if 名称 == "剑气四射·觉醒" then
			伤害系数1 = 伤害系数1 + 0.1
		end
	elseif 名称 == "六道无量" then
		伤害 = 伤害 + 等级 * 0.5
		伤害系数1 = 1
	end

	local 伤害值 = {}
	local 最终伤害 = {}
	local 躲避 = self:法术躲避计算(编号, 目标, 名称)

	if not 躲避 then
		最终伤害 = self:取最终物理伤害(编号, 目标, 伤害, 名称)
		伤害值 = 最终伤害
		必杀 = 最终伤害.暴击 or false

		if 伤害值.类型 ~= 2 then
			if 执行数 == 1 then
				伤害系数1 = 伤害系数1 + 0.1
			end

			伤害值.伤害 = qz(伤害值.伤害 * 伤害系数 * 伤害系数1)
		end

		local 最终结果1 = self:新增状态处理("物理", 编号, 目标, 伤害值.伤害, 伤害值.类型, 执行数, 名称, nil, 等级, 物攻群法流程 + 0)
		伤害值.伤害 = qz(最终结果1.伤害)
		伤害值.类型 = 最终结果1.类型

		if self.参战单位[目标].法术状态.波澜不惊 ~= nil and self.参战单位[目标].法术状态.波澜不惊.层数 >= 1 and 伤害值.伤害 > 1 and 伤害值.类型 ~= 2 then
			local 编号1 = self.参战单位[目标].法术状态.波澜不惊.攻击编号
			local 最大吸收 = self.参战单位[目标].法术状态.波澜不惊.等级 * 4 + self.参战单位[编号1].灵力 * 0.1
			最大吸收 = self:取恢复气血(编号1, 目标, 最大吸收, "普渡众生", 1) * 2
			local 吸收血量 = 0

			if 伤害值.伤害 <= 最大吸收 then
				吸收血量 = 伤害值.伤害
				伤害值.类型 = 2
			else
				吸收血量 = 最大吸收
				伤害值.伤害 = 伤害值.伤害 - 最大吸收
				self.战斗流程[物攻群法流程].挨打方[执行数].恢复气血 = 吸收血量
			end

			self:增加气血(目标, 吸收血量)

			待加特效[#待加特效 + 1] = "波澜不惊"
			self.参战单位[目标].法术状态.波澜不惊.层数 = self.参战单位[目标].法术状态.波澜不惊.层数 - 1
		end

		self.战斗流程[物攻群法流程].挨打方[执行数].护盾掉血值 = nil

		if (伤害值.类型 == 1 or 伤害值.类型 == 3 or 伤害值.类型 == 4) and self.参战单位[目标].法术状态.护盾 ~= nil and self.参战单位[目标].法术状态.护盾.护盾值 ~= nil then
			if 伤害值.伤害 < self.参战单位[目标].法术状态.护盾.护盾值 then
				self.参战单位[目标].法术状态.护盾.护盾值 = self.参战单位[目标].法术状态.护盾.护盾值 - 伤害值.伤害
				self.战斗流程[物攻群法流程].挨打方[执行数].护盾掉血值 = 伤害值.伤害
				伤害值.伤害 = 0
			else
				self.战斗流程[物攻群法流程].挨打方[执行数].护盾掉血值 = self.参战单位[目标].法术状态.护盾.护盾值
				伤害值.伤害 = 伤害值.伤害 - self.参战单位[目标].法术状态.护盾.护盾值

				self:取消状态("护盾", self.参战单位[目标])

				self.战斗流程[物攻群法流程].挨打方[执行数].取消状态 = "护盾"
			end
		end
	else
		self.战斗流程[物攻群法流程].挨打方[执行数].躲避 = true
		self.真实伤害 = nil
		伤害值.伤害 = 0
		伤害值.类型 = 2
	end

	self.战斗流程[物攻群法流程].挨打方[执行数].伤害 = 伤害值.伤害
	self.战斗流程[物攻群法流程].挨打方[执行数].伤害类型 = 伤害值.类型
	self.战斗流程[物攻群法流程].挨打方[执行数].类型 = 伤害值.类型
	self.战斗流程[物攻群法流程].挨打方[执行数].特效[1] = 名称

	if self.法术吸血流程[物攻群法流程] ~= nil and self.法术吸血流程[物攻群法流程].执行 == 执行数 then
		local 吸血伤害 = qz(self.法术吸血流程[物攻群法流程].伤害值 * self.法术吸血流程[物攻群法流程].比例)

		if 吸血伤害 > 0 then
			self:增加气血(编号, 吸血伤害)

			self.战斗流程[物攻群法流程].法术吸血 = 吸血伤害
		end

		self.法术吸血流程[物攻群法流程] = nil
	end

	if 伤害值.类型 == 2 then
		self:增加气血(目标, 伤害值.伤害)
	else
		if self.恐吓击飞 == 1 then
			伤害值.伤害 = self.参战单位[目标].气血 + 99999
			self.恐吓击飞 = 0
		end

		self.凝光炼彩护盾 = true
		self.战斗流程[物攻群法流程].挨打方[执行数].死亡 = self:减少气血(目标, 伤害值.伤害, 编号, nil, nil, nil, 1)

		if self.参战单位[目标].法术状态.催眠符 and 伤害值.伤害 > (self.参战单位[目标].法术状态.催眠符.黄粱 or 0) then
			self:取消状态("催眠符", self.参战单位[目标])

			self.战斗流程[物攻群法流程].挨打方[执行数].取消状态 = "催眠符"
		end

		if 名称 == "六道无量" and self.参战单位[目标].类型 ~= "bb" and self:取玩家战斗() then
			local 防御差 = math.min(math.abs(self.参战单位[目标].防御 - self.参战单位[编号].防御), qz(self.参战单位[编号].等级 * 1.6 + 70))

			self:添加状态("六道无量", self.参战单位[目标], self.参战单位[编号], 防御差, 编号)
			self:添加状态("六道无量", self.参战单位[编号], self.参战单位[编号], 防御差, 编号)
		end
	end

	if 伤害值.类型 ~= 2 and 伤害值.伤害 > 0 then
		if 必杀 then
			待加特效[#待加特效 + 1] = "法暴"
		end

		if self.参战单位[编号].气血 > 0 and 伤害值.伤害 > 0 and self.参战单位[目标].法术状态.混元伞 ~= nil then
			local 反弹伤害 = qz(伤害值.伤害 * (self.参战单位[目标].法术状态.混元伞.境界 * 混元伞反弹比例 + 0.1))

			if self.战斗流程[物攻群法流程].反震伤害 == nil then
				self.战斗流程[物攻群法流程].反震伤害 = 反弹伤害
			else
				self.战斗流程[物攻群法流程].反震伤害 = self.战斗流程[物攻群法流程].反震伤害 + 反弹伤害
			end

			self.战斗流程[物攻群法流程].反震死亡 = self:减少气血(编号, 反弹伤害, 目标, nil, nil, nil, 1)
			self.战斗流程[物攻群法流程].挨打方[执行数].特效[#self.战斗流程[物攻群法流程].挨打方[执行数].特效 + 1] = "混元伞"
		end

		if self.参战单位[编号].气血 > 0 and 伤害值.伤害 > 0 and self.参战单位[目标].法术状态.修罗咒 ~= nil then
			local 反弹伤害 = qz(伤害值.伤害 * 0.5)

			if self.战斗流程[物攻群法流程].反震伤害 == nil then
				self.战斗流程[物攻群法流程].反震伤害 = 反弹伤害
			else
				self.战斗流程[物攻群法流程].反震伤害 = self.战斗流程[物攻群法流程].反震伤害 + 反弹伤害
			end

			self.战斗流程[物攻群法流程].反震死亡 = self:减少气血(编号, 反弹伤害, 目标, nil, nil, nil, 1)
			self.战斗流程[物攻群法流程].挨打方[执行数].特效[#self.战斗流程[物攻群法流程].挨打方[执行数].特效 + 1] = "修罗咒"
		end

		if 目标 ~= nil and self:取奇经八脉是否有(目标, "养生") and self.参战单位[目标].气血 <= qz(self.参战单位[目标].最大气血 * 0.7) and self.参战单位[目标].法术状态.生命之泉 == nil then
			self:添加状态("生命之泉", self.参战单位[目标], self.参战单位[目标], self.参战单位[目标].等级, 目标)

			self.战斗流程[物攻群法流程].挨打方[执行数].添加状态 = "生命之泉"
		end
	end

	if not 躲避 then
		for i = 1, #最终伤害.特效 do
			self.战斗流程[物攻群法流程].挨打方[执行数].特效[#self.战斗流程[物攻群法流程].挨打方[执行数].特效 + 1] = 最终伤害.特效[i]
		end

		for i = 1, #待加特效 do
			self.战斗流程[物攻群法流程].挨打方[执行数].特效[#self.战斗流程[物攻群法流程].挨打方[执行数].特效 + 1] = 待加特效[i]
		end
	end

	if not 单机设置 and 执行数 == 目标数 then
		if 流程200[名称] ~= nil then
			self.战斗流程[物攻群法流程].流程 = 200
		elseif 执行数 == 目标数 and 流程205[名称] ~= nil then
			self.战斗流程[物攻群法流程].流程 = 205
		end
	end
end

function 战斗处理类:九黎城连击数处理(编号, 次数)
	次数 = 次数 or 0

	if 次数 < 1 or 编号 == nil or self.参战单位[编号] == nil or self.参战单位[编号].门派 ~= "九黎城" or self.参战单位[编号].被动技能 == nil or self.参战单位[编号].被动技能.黎魂 == nil or self.参战单位[编号].被动技能.战鼓 == nil then
		return
	else
		self.参战单位[编号].九黎连击次数 = (self.参战单位[编号].九黎连击次数 or 0) + 次数
	end
end

function 战斗处理类:自动保护计算(编号, 伤害, 攻击)
	if 战斗自动保护开关 == false then
		return 0
	end

	local 类型 = {
		角色 = 1,
		系统角色 = 2,
		系统PK角色 = 2
	}

	if self.参战单位[编号] == nil or 类型[self.参战单位[编号].类型] == nil then
		return 0
	else
		if self.参战单位[编号].法术状态 ~= nil and self.参战单位[编号].法术状态[惊魂掌] ~= nil and self.参战单位[编号].法术状态[惊魂掌].持戒 ~= nil then
			return 0
		end

		if 类型[self.参战单位[编号].类型] == 2 then
			for i = 1, #self.参战单位 do
				if i ~= 编号 and i ~= 攻击 and self.参战单位[编号].队伍 == self.参战单位[i].队伍 and 类型[self.参战单位[i].类型] ~= nil and self.参战单位[i].自动保护 == nil and self.参战单位[i].气血 > self.参战单位[i].最大气血 * 0.3 and self.参战单位[i].气血 - 伤害 * 0.55 > self.参战单位[i].最大气血 * 0.1 then
					local 保护概率 = 系统角色自动保护概率 + 0

					if self.参战单位[编号].九黎浮空 == 攻击 and self:取奇经八脉是否有(攻击, "难保") then
						保护概率 = 保护概率 - 20
					end

					if ygsj() <= 保护概率 then
						self.参战单位[i].自动保护 = true

						return i
					end
				end
			end
		elseif 类型[self.参战单位[编号].类型] == 1 and self.参战单位[编号].玩家id ~= 0 then
			for i = 1, #self.参战单位 do
				if i ~= 编号 and i ~= 攻击 and self.参战单位[编号].队伍 == self.参战单位[i].队伍 and 类型[self.参战单位[i].类型] ~= nil and self.参战单位[i].自动保护 == nil and self.参战单位[i].玩家id ~= 0 and self.参战单位[i].气血 > self.参战单位[i].最大气血 * 0.5 and self.参战单位[i].气血 - 伤害 * 0.55 > self.参战单位[i].最大气血 * 0.3 then
					local 判断1 = 0
					local 判断2 = 0

					if self.参战单位[编号].助战编号 == nil then
						判断1 = self.参战单位[编号].认证码
					else
						判断1 = self.参战单位[编号].玩家id
					end

					if self.参战单位[i].助战编号 == nil then
						判断2 = self.参战单位[i].认证码
					else
						判断2 = self.参战单位[i].玩家id
					end

					local 好友度 = 0
					local 保护概率 = 0

					if self.好友度列表[判断1] ~= nil and self.好友度列表[判断1][判断2] ~= nil then
						好友度 = self.好友度列表[判断1][判断2] + 0
					end

					if 好友度 <= 100 then
						保护概率 = 5
					elseif 好友度 <= 500 then
						保护概率 = 10 + 5 * (好友度 - 100) / 400
					elseif 好友度 <= 1000 then
						保护概率 = 15 + 5 * (好友度 - 500) / 500
					elseif 好友度 <= 2000 then
						保护概率 = 20 + 5 * (好友度 - 1000) / 2000
					elseif 好友度 <= 5000 then
						保护概率 = 25 + 5 * (好友度 - 2000) / 3000
					elseif 好友度 <= 10000 then
						保护概率 = 30 + 5 * (好友度 - 5000) / 5000
					else
						保护概率 = 35
					end

					if self.参战单位[编号].九黎浮空 == 攻击 and self:取奇经八脉是否有(攻击, "难保") then
						保护概率 = 保护概率 - 20
					end

					if 取随机数(1, 10000) <= 保护概率 * 100 then
						self.参战单位[i].自动保护 = true

						return i
					end
				end
			end
		end

		return 0
	end
end

function 战斗处理类:物攻技能计算1(编号, 目标, 起始伤害, 叠加伤害, 返回, 允许保护, 次数, 技能名称, 流程, 挨打序号)
	if self.参战单位[编号].电光 ~= nil then
		self:添加战斗流程提示(self.参战单位[编号].电光)

		self.参战单位[编号].电光 = nil
	end

	挨打序号 = 挨打序号 or 1
	local 浮空概率 = 0

	if 技能名称 == "三荒尽灭" then
		浮空概率 = 45

		if self:取奇经八脉是否有(编号, "乘风") and qz(self.天气) == 1 then
			浮空概率 = 浮空概率 + 10
		end
	elseif 技能名称 == "一斧开天" then
		浮空概率 = 45

		if self:取奇经八脉是否有(编号, "乘风") and qz(self.天气) == 1 then
			浮空概率 = 100
		end
	end

	if 浮空概率 > 0 and self:取是否有指定状态(编号, 编号, "怒哮") then
		浮空概率 = 浮空概率 + 30
	end

	if self:取奇经八脉是否有(编号, "识破", "铁火战魔") and self:取是否五行相克(self.参战单位[编号].攻击五行, self.参战单位[目标].防御五行) then
		浮空概率 = 浮空概率 + 10
	end

	if self.参战单位[目标].九黎浮空 == nil then
		if 浮空概率 > 0 and ygsj() <= 浮空概率 then
			self.参战单位[编号].浮空人数 = (self.参战单位[编号].浮空人数 or 0) + 1
			self.参战单位[目标].九黎浮空 = 编号

			self:流程处理状态(目标, {
				{
					浮空 = 1,
					挨打方 = 目标
				}
			})

			self.参战单位[编号].取消怒哮 = 1

			if self.参战单位[编号].飞扬生效 ~= nil and self.参战单位[编号].浮空人数 == 5 and (self.参战单位[编号].飞扬次数 or 0) < 3 then
				self.参战单位[编号].飞扬增伤 = (self.参战单位[编号].飞扬增伤 or 1) + 0.06
				self.参战单位[编号].飞扬次数 = (self.参战单位[编号].飞扬次数 or 0) + 1
			end

			if 技能名称 == "一斧开天" then
				self.战斗流程[流程].致使浮空 = true
			end
		elseif 技能名称 == "一斧开天" then
			self.战斗流程[流程].未浮空 = true
			local gl = 26

			if self:取奇经八脉是否有(编号, "震怒", "铁火战魔") then
				gl = gl * 2
			end

			if ygsj() <= gl then
				self:添加状态("怒哮", self.参战单位[编号])
			end
		end
	end

	self.物攻流程 = 流程 + 0

	if 装备特技[技能名称] ~= nil then
		self.战斗流程[self.物攻流程].特技名称 = 技能名称
	end

	if 返回 then
		self.执行等待 = self.执行等待 + 10
	else
		self.执行等待 = self.执行等待 + 5
	end

	local 保护 = false
	local 保护编号 = 0
	local 躲避 = self:法术躲避计算(编号, 目标, 技能名称)
	local 伤害值 = {}
	self.参战单位[编号].临时增伤 = 0

	if 技能名称 == "长驱直入" then
		允许保护 = false
	elseif 技能名称 == "天崩地裂" and 次数 == 3 then
		允许保护 = false
	end

	if not 躲避 then
		if 允许保护 then
			for n = 1, #self.参战单位 do
				if 保护编号 == 0 and self:取行动状态(n) and self.参战单位[目标].法术状态.惊魂掌 == nil and self.参战单位[n].指令.类型 == "保护" and self.参战单位[n].队伍 == self.参战单位[目标].队伍 and self.参战单位[n].指令.目标 == 目标 then
					保护编号 = n
					保护 = true
					self.参战单位[n].指令.类型 = ""
					self.执行等待 = self.执行等待 + 5

					break
				end
			end
		end

		if 技能名称 == "舍身一搏" then
			local 舍身系数 = 0.5
			local 伤害差 = 0

			if self.参战单位[目标].出手 ~= 1 and self.参战单位[编号].力量 ~= nil then
				伤害差 = math.max(self.参战单位[编号].力量 * 0.3, 0)

				self:添加战斗流程提示(
				"#P(舍身一搏)#R" ..
				self.参战单位[目标].名称 .. "#W本回合未出手、#R" .. self.参战单位[编号].名称 .. "#W本次攻击获得#G" .. qz(伤害差) .. "#W点#Y额外攻击力#W加成#W",
					self.物攻流程)
			end

			self.参战单位[编号].临时增伤 = self.参战单位[编号].临时增伤 + self.参战单位[编号].伤害 * 舍身系数 + 伤害差
		elseif 技能名称 == "蚩尤之搏" then
			self.忽视防御 = 0.6
			self.参战单位[编号].临时增伤 = self.参战单位[编号].临时增伤 + self.参战单位[编号].伤害 * 0.3
		elseif 技能名称 == "荒古破击" then
			local 伤害差 = nil

			if self.参战单位[编号].力量 == nil or self.参战单位[编号].力量 < 100 then
				伤害差 = 100
			else
				伤害差 = self.参战单位[编号].力量
			end

			self.参战单位[编号].临时增伤 = self.参战单位[编号].临时增伤 + 伤害差 * 1.1
		elseif 技能名称 == "敲金击玉" then
			if self:取奇经八脉是否有(编号, "木摧") then
				self.参战单位[编号].临时增伤 = self.参战单位[编号].临时增伤 + self.参战单位[编号].伤害 * 0.05
			end
		elseif 技能名称 == "破釜沉舟" and self:取奇经八脉是否有(编号, "破空") then
			self.参战单位[编号].临时增伤 = self.参战单位[编号].临时增伤 + self.参战单位[目标].防御 * 0.3
		elseif 技能名称 == "横扫千军" and self:取奇经八脉是否有(编号, "历战") then
			self.参战单位[编号].临时增伤 = self.参战单位[编号].临时增伤 + self.参战单位[目标].防御 * 0.3
		elseif 技能名称 == "连环击" and self:取奇经八脉是否有(编号, "乱击") then
			self.参战单位[编号].临时增伤 = self.参战单位[编号].临时增伤 + (self.参战单位[编号].被动技能.狂兽诀 or self.参战单位[编号].等级)
		elseif 技能名称 == "鸿渐于陆" and self.参战单位[编号].武器伤害 ~= nil then
			self.参战单位[编号].临时增伤 = self.参战单位[编号].临时增伤 + self.参战单位[编号].武器伤害 * 1.3
		end

		local 必杀 = false
		local 防御 = false
		local 伤害 = self:取基础物理伤害(编号, 目标, 技能名称) * (起始伤害 + 叠加伤害 * 次数)

		if 技能名称 == "力劈华山" then
			local 力劈系数 = 1.8
			local 伤害差 = self.参战单位[编号].伤害 - self.参战单位[目标].伤害

			if 伤害差 < 0 then
				伤害差 = 0
				力劈系数 = 0.8
			end

			伤害 = qz((伤害 + 伤害差) * 力劈系数)
		elseif 技能名称 == "水击三千" then
			local 伤害系数 = 1.5
			伤害 = qz(伤害 * 伤害系数)
		elseif 技能名称 == "刀背打" then
			local 伤害系数 = 1.1
			伤害 = qz(伤害 * 伤害系数)
		elseif 技能名称 == "蚩尤之搏" then
			local 伤害系数 = 1.2
			伤害 = qz(伤害 * 伤害系数)
		elseif 技能名称 == "荒古破击" then
			local 伤害系数 = 1.1
			local 伤害差 = 1 - self.参战单位[编号].气血 / self.参战单位[编号].最大气血

			if 伤害差 <= 0.5 then
				伤害系数 = 伤害系数 + 伤害差 * 1.3
			else
				伤害系数 = 伤害系数 + 伤害差 * 2
			end

			伤害 = qz(伤害 * 伤害系数)
		end

		local 最终伤害 = self:取最终物理伤害(编号, 目标, 伤害, 技能名称)
		伤害值 = 最终伤害

		if 技能名称 == "善恶有报" then
			if 取随机数(1, 10000) >= 8000 then
				伤害值.伤害 = qz(伤害值.伤害 * 0.5)
				伤害值.类型 = 2
			elseif 伤害值.类型 ~= 2 then
				伤害值.伤害 = qz(伤害值.伤害 * 2)
			end
		end

		if 伤害值.类型 ~= 2 then
			if 保护 == true then
			elseif 允许保护 == true and self.参战单位[目标].气血 - 伤害值.伤害 < self.参战单位[目标].最大气血 * 0.3 then
				保护编号 = self:自动保护计算(目标, 伤害值.伤害, 编号)
			end

			if 保护编号 ~= 0 and self.参战单位[保护编号] ~= nil then
				local 保护伤害 = math.floor(伤害值.伤害 * 0.55)
				local 保护死亡 = self:减少气血(保护编号, 保护伤害, nil, nil, nil, nil, 1)
				伤害值.伤害 = math.floor(伤害值.伤害 * 0.3)
				self.战斗流程[self.物攻流程].保护数据 = {
					编号 = 保护编号,
					伤害 = 保护伤害,
					死亡 = 保护死亡
				}
			end

			if self.参战单位[编号].法术状态.谜毒之缚 ~= nil then
				伤害值.伤害 = qz(伤害值.伤害 * 0.65 * 0.8)
			end

			if 伤害值.伤害 < 1 and 最终伤害.暴击 == true then
				伤害值.伤害 = 取随机数(self.参战单位[编号].伤害 * 0.15, self.参战单位[编号].伤害 * 0.25)
			elseif 伤害值.伤害 < 1 then
				伤害值.伤害 = 取随机数(self.参战单位[编号].伤害 * 0.1, self.参战单位[编号].伤害 * 0.15)
			end

			if 技能名称 == "翩鸿一击" then
				if 编号 ~= nil and (self:取奇经八脉是否有(编号, "翩鸿") or self:取奇经八脉是否有(编号, "翩鸿一击")) then
					伤害值.伤害 = qz(伤害值.伤害 * 1.35)
					local 可取消状态 = self:驱散目标状态(目标, 编号)
					self.战斗流程[self.物攻流程].挨打方[挨打序号].取消状态 = 可取消状态
				end
			elseif 技能名称 == "长驱直入" then
				if 编号 ~= nil and self:取奇经八脉是否有(编号, "长驱直入") and ygsj() <= 30 then
					伤害值.伤害 = qz(伤害值.伤害 * 2)
				end
			elseif 技能名称 == "狮搏" then
				if 编号 ~= nil and self:取奇经八脉是否有(编号, "狮吼") then
					伤害值.伤害 = qz(伤害值.伤害 * 1.15)
				end
			elseif 技能名称 == "翻江搅海" then
				if 编号 ~= nil and self:取奇经八脉是否有(编号, "抗击") then
					伤害值.伤害 = qz(伤害值.伤害 * 1.12)
				end
			elseif 技能名称 == "浪涌" and 编号 ~= nil and self:取奇经八脉是否有(编号, "战诀") and self:取玩家战斗() == false then
				伤害值.伤害 = qz(伤害值.伤害 * 1.3)
			end

			if self.参战单位[编号].碎甲刃 ~= nil and self.参战单位[编号].碎甲刃 > 0 and ygsj() <= 30 then
				self:添加状态("碎甲刃", self.参战单位[目标], self.参战单位[编号], self.参战单位[编号].碎甲刃, 编号)

				self.战斗流程[self.物攻流程].挨打方[挨打序号].添加状态 = "碎甲刃"
			end
		end

		local 最终结果1 = self:新增状态处理("物理", 编号, 目标, 伤害值.伤害, 伤害值.类型, 挨打序号, 技能名称, nil, 等级, self.物攻流程 + 0)
		伤害值.伤害 = qz(最终结果1.伤害)
		伤害值.类型 = 最终结果1.类型

		if 技能名称 == "后发制人" then
			self.战斗流程[self.物攻流程].挨打方[挨打序号].特效[#self.战斗流程[self.物攻流程].挨打方[挨打序号].特效 + 1] = "横扫千军"
		else
			self.战斗流程[self.物攻流程].挨打方[挨打序号].特效[#self.战斗流程[self.物攻流程].挨打方[挨打序号].特效 + 1] = 技能名称
		end

		self.战斗流程[self.物攻流程].挨打方[挨打序号].动作 = 最终伤害.动作
		self.战斗流程[self.物攻流程].挨打方[挨打序号].特效 = 列表2加入到列表1(self.战斗流程[self.物攻流程].挨打方[挨打序号].特效, 最终伤害.特效)
		self.战斗流程[self.物攻流程].伤害 = 最终伤害.攻击伤害

		if #最终伤害.特效 == 0 then
		end

		if 技能名称 == "横扫千军" and 编号 ~= nil and self:取奇经八脉是否有(编号, "风刃") and ygsj() <= 50 then
			self:添加状态("风魂", self.参战单位[编号], nil, nil, 编号)

			self.参战单位[编号].法术状态.风魂.回合 = 3
		end

		if self.参战单位[目标].法术状态.波澜不惊 ~= nil and self.参战单位[目标].法术状态.波澜不惊.层数 >= 1 and 伤害值.伤害 > 1 and 伤害值.类型 ~= 2 then
			local 编号1 = self.参战单位[目标].法术状态.波澜不惊.攻击编号
			local 最大吸收 = self.参战单位[目标].法术状态.波澜不惊.等级 * 4 + self.参战单位[编号1].灵力 * 0.1
			最大吸收 = self:取恢复气血(编号1, 目标, 最大吸收, "普渡众生", 1) * 2
			local 吸收血量 = 0

			if 伤害值.伤害 <= 最大吸收 then
				吸收血量 = 伤害值.伤害
				伤害值.类型 = 2
			else
				吸收血量 = 最大吸收
				伤害值.伤害 = 伤害值.伤害 - 最大吸收
				self.战斗流程[self.物攻流程].挨打方[挨打序号].恢复气血 = 吸收血量
			end

			self:增加气血(目标, 吸收血量)

			self.战斗流程[self.物攻流程].挨打方[挨打序号].特效[#self.战斗流程[self.物攻流程].挨打方[挨打序号].特效 + 1] = "波澜不惊"
			self.参战单位[目标].法术状态.波澜不惊.层数 = self.参战单位[目标].法术状态.波澜不惊.层数 - 1
		end

		self.战斗流程[self.物攻流程].挨打方[挨打序号].护盾掉血值 = nil

		if (伤害值.类型 == 1 or 伤害值.类型 == 3 or 伤害值.类型 == 4) and self.参战单位[目标].法术状态.护盾 ~= nil and self.参战单位[目标].法术状态.护盾.护盾值 ~= nil then
			if 伤害值.伤害 < self.参战单位[目标].法术状态.护盾.护盾值 then
				self.参战单位[目标].法术状态.护盾.护盾值 = self.参战单位[目标].法术状态.护盾.护盾值 - 伤害值.伤害
				self.战斗流程[self.物攻流程].挨打方[挨打序号].护盾掉血值 = 伤害值.伤害
				伤害值.伤害 = 0
			else
				self.战斗流程[self.物攻流程].挨打方[挨打序号].护盾掉血值 = self.参战单位[目标].法术状态.护盾.护盾值
				伤害值.伤害 = 伤害值.伤害 - self.参战单位[目标].法术状态.护盾.护盾值

				self:取消状态("护盾", self.参战单位[目标])

				self.战斗流程[self.物攻流程].挨打方[挨打序号].取消状态 = "护盾"
			end
		end

		local csjc = 0

		if self:取奇经八脉是否有(编号, "狂暴") then
			for w = 1, #最终伤害.特效 do
				if 最终伤害.特效[i] == "暴击" then
					csjc = csjc + 1
				end
			end
		end

		self:九黎城连击数处理(编号, 1 + csjc)
	else
		self.战斗流程[self.物攻流程].躲避 = true
		伤害值.伤害 = 0
		伤害值.类型 = 2
	end

	if 伤害值.类型 == 2 then
		self:增加气血(目标, 伤害值.伤害)
	else
		if self.恐吓击飞 == 1 then
			伤害值.伤害 = self.参战单位[目标].气血 + 99999
			self.恐吓击飞 = 0
		end

		self.凝光炼彩护盾 = true
		self.战斗流程[self.物攻流程].挨打方[挨打序号].死亡 = self:减少气血(目标, 伤害值.伤害, 编号, 技能名称, nil, nil, 1)

		if (self:取奇经八脉是否有(编号, "育养") or self.参战单位[编号].报恩 ~= nil) and ygsj() <= 30 then
			local 吸血伤害 = qz(伤害值.伤害 * 0.18)
			local bb = self.参战单位[编号].召唤兽

			if self.参战单位[编号].报恩 ~= nil then
				bb = self.参战单位[编号].报恩

				if bb ~= nil and self:取目标状态(bb, bb, 2) then
					self.战斗流程[self.物攻流程].友方回血 = bb + 0
					self.战斗流程[self.物攻流程].友方回血值 = (self.战斗流程[self.物攻流程].友方回血值 or 0) + 吸血伤害

					self:增加气血(bb, 吸血伤害)
					self:添加战斗流程提示("#P(报恩)#R" .. self.参战单位[bb].名称 .. "#W吸取了#S" .. 吸血伤害 .. "#W点气血", self.物攻流程)
				end
			else
				bb = self.参战单位[编号].召唤兽

				if bb ~= nil and self:取目标状态(bb, bb, 2) then
					self.战斗流程[self.物攻流程].友方回血 = bb + 0
					self.战斗流程[self.物攻流程].友方回血值 = (self.战斗流程[self.物攻流程].友方回血值 or 0) + 吸血伤害

					self:增加气血(bb, 吸血伤害)
					self:添加战斗流程提示("#P(育养)#R" .. self.参战单位[bb].名称 .. "#W吸取了#S" .. 吸血伤害 .. "#W点气血", self.物攻流程)
				end
			end
		end

		if 技能名称 == "横扫千军" and self.战斗流程[self.物攻流程].挨打方[挨打序号].死亡 ~= nil and self:取奇经八脉是否有(编号, "孤勇") and (self.参战单位[目标].玩家id == 0 or self.参战单位[目标].类型 == "bb") and (self.同门派减伤[self.参战单位[编号].队伍].大唐官府 or 0) <= 1 then
			self.参战单位[编号].孤勇 = 1
		elseif 技能名称 == "狮搏" and self.参战单位[编号].嗜血 ~= nil and self.参战单位[编号].驯兽 ~= nil and self.参战单位[目标].类型 ~= "bb" and self.战斗流程[self.物攻流程].挨打方[挨打序号].死亡 ~= nil then
			if self.参战单位[编号].法术状态.嗜血 == nil then
				self:添加状态("嗜血", self.参战单位[编号])
			else
				self.参战单位[编号].法术状态.嗜血.回合 = 3
			end

			self:更新单个法术状态(编号, "嗜血", "万兽之王")
		elseif 技能名称 == "困兽之斗" and self.战斗流程[self.物攻流程].挨打方[挨打序号].死亡 ~= nil then
			self.参战单位[编号].困兽之斗 = 1
		end

		if self.参战单位[目标].法术状态.催眠符 and 伤害值.伤害 > (self.参战单位[目标].法术状态.催眠符.黄粱 or 0) then
			self:取消状态("催眠符", self.参战单位[目标])

			self.战斗流程[self.物攻流程].挨打方[挨打序号].取消状态 = "催眠符"
		end

		if 技能名称 == "惊心一剑" then
			self:减少魔法(目标, qz(伤害值.伤害 * 0.2))
		elseif 技能名称 == "破碎无双" then
			self:减少魔法(目标, qz(伤害值.伤害))
		end
	end

	self.战斗流程[self.物攻流程].挨打方[挨打序号].伤害 = 伤害值.伤害
	self.战斗流程[self.物攻流程].挨打方[挨打序号].伤害类型 = 伤害值.类型
	self.战斗流程[self.物攻流程].返回 = 返回

	if 伤害值.类型 ~= 2 and 伤害值.伤害 > 0 then
		if self.参战单位[编号].气血 > 0 and 伤害值.伤害 > 0 and self.参战单位[目标].法术状态.混元伞 ~= nil then
			local 反弹伤害 = qz(伤害值.伤害 * (self.参战单位[目标].法术状态.混元伞.境界 * 混元伞反弹比例 + 0.1))

			if self.战斗流程[self.物攻流程].反震伤害 == nil then
				self.战斗流程[self.物攻流程].反震伤害 = 反弹伤害
			else
				self.战斗流程[self.物攻流程].反震伤害 = self.战斗流程[self.物攻流程].反震伤害 + 反弹伤害
			end

			self.战斗流程[self.物攻流程].反震死亡 = self:减少气血(编号, 反弹伤害, 目标, nil, nil, nil, 1)
			self.战斗流程[self.物攻流程].挨打方[挨打序号].特效[#self.战斗流程[self.物攻流程].挨打方[挨打序号].特效 + 1] = "混元伞"
		end

		if self.参战单位[编号].气血 > 0 and 伤害值.伤害 > 0 and self.参战单位[目标].法术状态.修罗咒 ~= nil then
			local 反弹伤害 = qz(伤害值.伤害 * 0.5)

			if self.战斗流程[self.物攻流程].反震伤害 == nil then
				self.战斗流程[self.物攻流程].反震伤害 = 反弹伤害
			else
				self.战斗流程[self.物攻流程].反震伤害 = self.战斗流程[self.物攻流程].反震伤害 + 反弹伤害
			end

			self.战斗流程[self.物攻流程].反震死亡 = self:减少气血(编号, 反弹伤害, 目标, nil, nil, nil, 1)
			self.战斗流程[self.物攻流程].挨打方[挨打序号].特效[#self.战斗流程[self.物攻流程].挨打方[挨打序号].特效 + 1] = "修罗咒"
		end

		if 目标 ~= nil and self:取奇经八脉是否有(目标, "养生") and self.参战单位[目标].气血 <= qz(self.参战单位[目标].最大气血 * 0.7) and self.参战单位[目标].法术状态.生命之泉 == nil then
			self:添加状态("生命之泉", self.参战单位[目标], self.参战单位[目标], self.参战单位[目标].等级, 目标)

			self.战斗流程[self.物攻流程].挨打方[挨打序号].添加状态 = "生命之泉"
		end

		if self.参战单位[编号].法术状态.诡蝠之刑 ~= nil and self:取目标状态(编号, 编号, 2) then
			local 气血 = qz(伤害值.伤害 * 0.1)

			if 气血 <= 1 then
				气血 = 1
			end

			self.战斗流程[#self.战斗流程 + 1] = {
				气血 = 0,
				流程 = 102,
				攻击方 = 编号,
				挨打方 = {}
			}
			self.物攻流程 = #self.战斗流程 + 0
			self.战斗流程[self.物攻流程].死亡 = self:减少气血(编号, 气血, nil, nil, nil, nil, 1)
			self.战斗流程[self.物攻流程].气血 = 气血
		end
	end

	if self.参战单位[目标].九黎浮空 == nil and self.参战单位[目标].法术状态.火甲术 ~= nil and self.参战单位[目标].气血 > 0 and 不受反震反击技能[技能名称] == nil then
		local fjsh = 0.5

		if 目标 ~= nil and self:取奇经八脉是否有(目标, "返火") then
			fjsh = fjsh * 2
		end

		self.战斗流程[self.物攻流程].返回 = false

		self:法攻技能计算(目标, "三昧真火", self:取技能等级(目标, "三昧真火") or self.参战单位[目标].等级, fjsh, nil, {
			魔反目标 = 编号
		})

		self.反击挨打返回 = 1
	end

	if 不受反震反击技能[技能名称] == nil and self.参战单位[目标].九黎浮空 == nil then
		self:反震反击处理(编号, 目标, 保护, nil, self.真实伤害, self.物攻流程, {
			攻击方式 = "物攻技能"
		})

		if self.参战单位[编号].队伍 ~= self.参战单位[目标].队伍 and self.参战单位[目标 + 1] ~= nil and self.参战单位[目标 + 1].超级反击 ~= nil and self.参战单位[目标 + 1].超级反击 > 0 then
			self:反震反击处理(编号, 目标 + 1, 保护, nil, nil, self.物攻流程, {
				必定反击 = true,
				攻击方式 = "物攻技能"
			})

			self.参战单位[目标 + 1].超级反击 = self.参战单位[目标 + 1].超级反击 - 1
		end
	end
end

function 战斗处理类:魔法消耗(攻击方, 数值, 数量, 额外消耗)
	数量 = 数量 or 1
	local 编号 = 攻击方.战斗编号
	local 临时消耗 = qz(数值 * 数量 + (额外消耗 or 0))

	if 攻击方.慧根 ~= nil then
		临时消耗 = qz(临时消耗 * 攻击方.慧根)
	end

	if self:取符石组合效果(攻击方, "飞檐走壁") then
		临时消耗 = qz(临时消耗 * (1 - self:取符石组合效果(攻击方, "飞檐走壁") / 100))
	end

	if 攻击方.法术状态.雷浪穿云 ~= nil then
		临时消耗 = 临时消耗 * 2 + 30
	end

	if 攻击方.专注 ~= nil and 攻击方.专注 == 1 and ygsj() <= 15 then
		临时消耗 = 0
	elseif 攻击方.超级慧根 ~= nil and ygsj() <= 攻击方.超级慧根 then
		临时消耗 = 0
	elseif 攻击方.法术状态.罗汉珠 ~= nil then
		临时消耗 = qz(临时消耗 * (100 - (攻击方.法术状态.罗汉珠.境界 * 5 + 20)) / 100)
	end

	if 攻击方.魔法 < 临时消耗 then
		攻击方.魔法不足 = 1

		if self.参战单位[编号].连续神通判断 ~= nil then
			self.参战单位[编号].连续神通 = 0
			self.参战单位[编号].连续神通判断 = nil
		end

		return false
	else
		if 临时消耗 > 0 then
			self:减少魔法(攻击方.战斗编号, 临时消耗)
		end

		if self.参战单位[编号].连续神通判断 ~= nil then
			if self.参战单位[编号].愈勇 ~= nil then
				self.参战单位[编号].愈勇 = math.min(self.参战单位[编号].愈勇 + 1, 3)
			end

			self.参战单位[编号].连续神通 = (self.参战单位[编号].连续神通 or 0) + 1
			self.参战单位[编号].连续神通判断 = nil
		end

		return true
	end
end

function 战斗处理类:增加愤怒(编号, 数值)
	if self.参战单位[编号] == nil or self.参战单位[编号].愤怒 == nil or (数值 or 0) == 0 then
		return 0
	end

	local aa = self.参战单位[编号].愤怒 + 0
	self.参战单位[编号].愤怒 = math.max(self.参战单位[编号].愤怒, 0)
	self.参战单位[编号].愤怒 = math.max(self.参战单位[编号].愤怒 + 数值, 0)

	if self.参战单位[编号].愤怒 >= 150 and 服务端参数.愤怒超限 ~= 1 and self.参战单位[编号].玩家id ~= 0 then
		self.参战单位[编号].愤怒 = 150
	end

	self:流程更新气血魔法愤怒(编号, 3)

	return self.参战单位[编号].愤怒 - aa
end

function 战斗处理类:愤怒消耗(数值, 攻击方, 编号, 名称, 只判定不消耗)
	local 消耗 = tonumber(数值 or 0)

	if 编号 ~= nil and self:取奇经八脉是否有(编号, "慈心") and 名称 == "慈航普渡" then
		消耗 = 消耗 - 40
	elseif 编号 ~= nil and self:取奇经八脉是否有(编号, "花护") then
		if 名称 == "水清诀" or 名称 == "冰清诀" or 名称 == "晶清诀" or 名称 == "玉清诀" then
			消耗 = 消耗 - 8
		end
	elseif 编号 ~= nil and self:取奇经八脉是否有(编号, "静气") and 名称 == "罗汉金钟" then
		消耗 = 消耗 - 16
	end

	if 编号 ~= nil and self:取奇经八脉是否有(编号, "傲娇") then
		消耗 = 消耗 - 4

		if 名称 == "笑里藏刀" then
			消耗 = 消耗 - 4
		end
	end

	if 编号 ~= nil and 攻击方.显圣 ~= nil then
		if 名称 == "晶清诀" or 名称 == "罗汉金钟" then
			消耗 = 消耗 - 8
			攻击方.显圣 = 999
		end
	elseif 编号 ~= nil and self:取奇经八脉是否有(编号, "天威") then
		if 名称 == "金刚怒目" then
			消耗 = 消耗 - 8
		end
	elseif 编号 ~= nil and self:取奇经八脉是否有(编号, "暗潮") then
		if 名称 == "玉清诀" then
			消耗 = 消耗 - 30
		end
	elseif 编号 ~= nil and self.参战单位[编号].噬魂 ~= nil and (名称 == "水清诀" or 名称 == "冰清诀") then
		消耗 = qz(消耗 * 0.5)
	end

	if 编号 ~= nil and self:取奇经八脉是否有(编号, "罗汉") and 名称 == "罗汉金钟" then
		消耗 = 消耗 - 4
	end

	if 攻击方.愤怒腰带 ~= nil then
		消耗 = qz(消耗 * 愤怒效果)

		if 攻击方.超级愤怒腰带 ~= nil then
			消耗 = qz(消耗 * 超级愤怒效果)
		end
	elseif 攻击方.超级愤怒腰带 ~= nil then
		消耗 = qz(消耗 * 超级愤怒效果)
	end

	if 消耗 <= 0 then
		消耗 = 0
	end

	if 攻击方.愤怒 == nil then
		return true
	end

	if 攻击方.愤怒 <= 0 then
		攻击方.愤怒 = 0
	end

	if 攻击方.愤怒 >= 150 and 服务端参数.愤怒超限 ~= 1 and 攻击方.玩家id ~= 0 then
		攻击方.愤怒 = 150
	end

	local 成功 = false

	if 攻击方.愤怒 < 消耗 then
		if 名称 ~= "慈航普渡" and 攻击方.修心 == nil and self:取奇经八脉是否有(编号, "修心") then
			local 不足愤怒 = 消耗 - 攻击方.愤怒

			if 攻击方.魔法 >= 不足愤怒 * 20 then
				if 只判定不消耗 == nil then
					攻击方.愤怒 = 0

					self:减少魔法(攻击方.战斗编号, 不足愤怒 * 20)

					攻击方.修心 = 1

					self:添加战斗流程提示("#P(修心)#R" ..
					self.参战单位[编号].名称 .. "#W消耗#Y" .. 不足愤怒 * 20 .. "#W点魔法代替#Y" .. 不足愤怒 .. "#W点愤怒、成功使用了特技#S" .. 名称)
				end

				self:流程更新气血魔法愤怒(攻击方.战斗编号, 3)

				成功 = true
			end
		end

		return false
	else
		if 只判定不消耗 == nil then
			攻击方.愤怒 = 攻击方.愤怒 - 消耗

			self:流程更新气血魔法愤怒(攻击方.战斗编号, 3)
		end

		成功 = true
	end

	if 成功 == true then
		if 攻击方.显圣 == 999 then
			攻击方.显圣 = 1
		end

		return 成功
	end
end

function 战斗处理类:技能消耗(攻击方, 数量, 名称, 编号)
	if 装备特技[名称] ~= nil then
		return self:愤怒消耗(装备特技[名称].消耗, 攻击方, 编号, 名称)
	end

	if 神通技能列表[名称] ~= nil then
		self.参战单位[编号].连续神通判断 = 1
	end

	if self.参战单位[编号].踏歌 ~= nil then
		if self.参战单位[编号].踏歌.轻拍技能[名称] ~= nil then
			if self.回合数 % 2 == 1 and (not self:取奇经八脉是否有(编号, "即兴") or self.回合数 > 4) then
				return false
			end
		elseif self.参战单位[编号].踏歌.重拍技能[名称] ~= nil and self.回合数 % 2 == 0 and (not self:取奇经八脉是否有(编号, "即兴") or self.回合数 > 4) then
			return false
		end
	end

	if 数量 == nil then
		数量 = 1
	end

	self.技能名称 = 名称

	if self.技能名称 == "自爆" or self.技能名称 == "盾气" or self.技能名称 == "与生俱来" then
		return true
	end

	if self.技能名称 == "呼子唤孙" then
		if (self.参战单位[编号].呼子唤孙 or 0) < 5 then
			local 神猿存在 = {
				0,
				0
			}

			for n = 1, #self.参战单位 do
				if self.参战单位[n].队伍 == self.参战单位[编号].队伍 and self.参战单位[n].模型 == "巨力神猿" and self.参战单位[n].名称 == "巨力神猿" and self.参战单位[n].召唤物 == true and self.参战单位[n].气血 > 0 then
					神猿存在[1] = 神猿存在[1] + 1

					if self.参战单位[n].召唤主人 == 编号 then
						神猿存在[2] = 神猿存在[2] + 1
					end
				end
			end

			if 神猿存在[1] < 5 and 神猿存在[2] < 2 then
				return self:魔法消耗(攻击方, 30, 1)
			end
		end

		return false
	elseif self.技能名称 == "无敌牛妖" then
		local 牛妖存在 = 0

		for n = 1, #self.参战单位 do
			if self.参战单位[n].队伍 == self.参战单位[编号].队伍 and self.参战单位[n].模型 == "牛幺" and self.参战单位[n].名称 == "牛幺" then
				牛妖存在 = 牛妖存在 + 2
			end
		end

		if 牛妖存在 <= 1 or self:取玩家战斗() then
			return self:魔法消耗(攻击方, 150, 1)
		else
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/只能存在一个相同的#G/宠物")

			return false
		end
	elseif self.技能名称 == "无敌牛虱" then
		local 牛虱存在 = 0

		for n = 1, #self.参战单位 do
