function 战斗处理类:取多个友方目标(编号, 目标, 数量, 名称)
	if self.参战单位[目标] == nil or self.参战单位[目标].队伍 ~= self.参战单位[编号].队伍 then
		目标 = self:取单个友方目标(编号)
	elseif 名称 == "活血" and 目标 == 编号 then
		local aa = 1

		while 目标 == 编号 and aa < 10 do
			目标 = self:取单个友方目标(编号)
			aa = aa + 1
		end
	end

	local 目标删除 = false
	local 目标组 = {
		目标
	}

	if self:取目标状态(编号, 目标, 2) == false then
		目标删除 = true
		目标组 = {}
	end

	if 名称 == "慈航普渡" or 名称 == "峰回路转" then
		目标组 = {}
	end

	if 数量 <= #目标组 then
		return 目标组
	end

	if 名称 ~= "慈航普渡" and 名称 ~= "峰回路转" then
		for n = 1, #self.参战单位 do
			if n ~= 目标 and self.参战单位[n].队伍 == self.参战单位[编号].队伍 and self:取目标状态(编号, n, 1) and self.参战单位[n].法术状态[名称] == nil then
				目标组[#目标组 + 1] = n
			end
		end

		if 数量 < #目标组 then
			if 目标 ~= nil and 目标删除 == false then
				table.remove(目标组, 1)
			end

			if 名称 == "金刚护法" then
				table.sort(目标组, function(a, b)
					return self.参战单位[b].伤害 < self.参战单位[a].伤害
				end)
			elseif 名称 == "金刚护体" then
				table.sort(目标组, function(a, b)
					return self.参战单位[a].防御 < self.参战单位[b].防御
				end)
			elseif 名称 == "韦陀护法" then
				table.sort(目标组, function(a, b)
					return self.参战单位[b].法伤 < self.参战单位[a].法伤
				end)
			elseif 名称 == "一苇渡江" then
				table.sort(目标组, function(a, b)
					return self.参战单位[b].速度 < self.参战单位[a].速度
				end)
			elseif 名称 == "生命之泉" or 名称 == "普渡众生" or 名称 == "推气过宫" or 名称 == "地涌金莲" or 名称 == "救死扶伤" or 名称 == "活血" then
				table.sort(目标组, function(a, b)
					return self.参战单位[a].气血 / self.参战单位[a].最大气血 < self.参战单位[b].气血 / self.参战单位[b].最大气血
				end)
			elseif 名称 == "妙手回春" then
				table.sort(目标组, function(a, b)
					return (self.参战单位[a].气血上限 or 999999) / self.参战单位[a].最大气血 <
					(self.参战单位[a].气血上限 or 999999) / self.参战单位[a].最大气血
				end)
			elseif 名称 == "炼气化神" then
				table.sort(目标组, function(a, b)
					return self.参战单位[a].魔法 / self.参战单位[a].最大魔法 < self.参战单位[b].魔法 / self.参战单位[b].最大魔法
				end)
			end

			if 目标 ~= nil and 目标删除 == false then
				table.insert(目标组, 1, 目标)
			end

			for i = 1, #目标组 - 数量 do
				table.remove(目标组, #目标组)
			end
		end
	else
		for n = 1, #self.参战单位 do
			if 数量 > #目标组 and n ~= 目标 and n ~= 编号 and string.find(self.参战单位[n].类型, "角色") and self.参战单位[n].队伍 == self.参战单位[编号].队伍 and not self:取目标状态(编号, n, 1) then
				目标组[#目标组 + 1] = n
			end
		end
	end

	return 目标组
end

function 战斗处理类:取多个敌方目标(编号, 目标, 数量, 不包括自己本身)
	local 目标组 = {
		目标
	}

	if self:取目标状态(编号, 目标, 1) == false then
		目标组 = {}
	elseif self.参战单位[目标].队伍 == self.参战单位[编号].队伍 then
		目标组 = {}
	end

	if 数量 <= #目标组 then
		return 目标组
	end

	local 临时目标组 = {}

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 ~= self.参战单位[编号].队伍 and self:取目标状态(编号, n, 1) then
			local 添加 = true

			for j = 1, #目标组 do
				if 目标组[j] == n then
					添加 = false
				end
			end

			if 添加 then
				临时目标组[#临时目标组 + 1] = {
					a = n,
					b = 取随机数(1, 999999)
				}
			end
		end
	end

	table.sort(临时目标组, function(a, b)
		return b.b < a.b
	end)

	if 不包括自己本身 then
		目标组 = {}
	end

	for n = 1, #临时目标组 do
		if 数量 > #目标组 then
			if 不包括自己本身 and 临时目标组[n].a ~= 目标 then
				目标组[#目标组 + 1] = 临时目标组[n].a
			else
				目标组[#目标组 + 1] = 临时目标组[n].a
			end
		end
	end

	return 目标组
end

function 战斗处理类:取玩家战斗()
	if self.战斗类型 == 200001 or self.战斗类型 == 200002 or self.战斗类型 == 200003 or self.战斗类型 == 200004 or self.战斗类型 == 200005 or self.战斗类型 == 200006 or self.战斗类型 == 200003 or self.战斗类型 == 200007 or self.战斗类型 == 200008 or self.战斗类型 == 110001 or self.战斗类型 == 410005 then
		return true
	else
		return false
	end
end

根据技能等级取数量 = function(技能等级, 关系列表)
	if type(关系列表) ~= "table" then
		return 0
	end

	for i = 1, #关系列表 do
		if 关系列表[#关系列表 - i + 1] <= 技能等级 then
			return #关系列表 - i + 1
		end
	end

	return 0
end

function 战斗处理类:取目标数量(攻击方, 技能名称, 等级, 编号)
	local aa = {}

	if 技能名称 == "金刚护法" and (self.战斗开始 == false or self.回合进程 == "加载回合") then
		return 3
	end

	self.临时等级 = 等级
	self.临时人数 = 1

	if 技能名称 == "八戒上身" then
		self.临时人数 = 1
	elseif 技能名称 == "牺牲·舍身取义" then
