			end
		end

		if (攻击方.名称 == "天罡星" or 攻击方.名称 == "蜘蛛女王" or 攻击方.名称 == "沙僧的心魔") and 攻击方.队伍 == 0 then
			self.临时人数 = 10
		end
	elseif 技能名称 == "鹰击" then
