		self.临时人数 = math.floor(self.临时等级 / 30) + 1
	elseif 技能名称 == "五雷咒" then
		self.临时人数 = 1

		if 编号 ~= nil and self.参战单位[编号].奔雷 ~= nil then
			self.临时人数 = self.临时人数 + 1
		end

		if self.参战单位[编号].怒霆 ~= nil and self.参战单位[编号].怒霆 >= 5 then
			self.临时人数 = self.临时人数 + 3
		end

		if self.参战单位[编号].炼魂经脉 ~= nil and self:取玩家战斗() then
