		if 群法最高数量 < self.临时人数 then
			self.临时人数 = 群法最高数量
		end
	elseif 技能名称 == "天降灵葫" then
		self.临时人数 = 取随机数(2, 群法最高数量 + 1)
	elseif 技能名称 == "叱咤风云" or 技能名称 == "食指大动" then
		self.临时人数 = 群法最高数量
	elseif 技能名称 == "秘传飞砂走石" then
		self.临时人数 = math.floor(self.临时等级 / 35) + 1
	elseif 技能名称 == "飞砂走石" or 技能名称 == "风云变色" then
		self.临时人数 = math.floor(self.临时等级 / 35) + 1

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "震怒") then
			self.临时人数 = self.临时人数 + 1
		end

		if 技能名称 == "风云变色" then
			self.临时人数 = self.临时人数 + 1
		end
	elseif 技能名称 == "超级三昧真火" then
		self.临时人数 = 1
	elseif 技能名称 == "秘传三昧真火" then
		self.临时人数 = 1
	elseif 技能名称 == "三昧真火" then
		self.临时人数 = 1

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "神炎") then
			self.临时人数 = self.临时人数 + 1
		end
	elseif 技能名称 == "摇头摆尾" then
		self.临时人数 = math.floor(self.临时等级 / 35) + 1
	elseif 技能名称 == "炽火流离" then
		self.临时人数 = 1
	elseif 技能名称 == "腾雷" then
		self.临时人数 = 1
	elseif 技能名称 == "峰回路转" then
		self.临时人数 = 10
	elseif 技能名称 == "流沙轻音" then
		self.临时人数 = math.min(math.max(math.floor(self.临时等级 / 20), 1), 5)
	elseif 技能名称 == "焚天陨火" then
		self.临时人数 = math.min(math.floor(self.临时等级 / 30) + 1, 3)
	elseif 技能名称 == "泰山压顶" or 技能名称 == "水漫金山" or 技能名称 == "地狱烈火" or 技能名称 == "奔雷咒" or 超级技能群法列表[技能名称] ~= nil then
		self.临时人数 = math.floor(self.临时等级 / 15) + 1

		if 群法最高数量 < self.临时人数 then
			self.临时人数 = 群法最高数量
		end

		if 技能名称 == "地狱烈火" and self.参战单位[编号].神来气旺 ~= nil then
			if ygsj() <= self.参战单位[编号].神来气旺 then
				self.临时人数 = self.临时人数 + 1
				self.参战单位[编号].神来气旺 = math.max(self.参战单位[编号].神来气旺 - 50, 50)
			else
				self.参战单位[编号].神来气旺 = self.参战单位[编号].神来气旺 + 50
			end
		end

		if qz(self.天气) == 3 and self.参战单位[编号].映雪棱镜 ~= nil then
			self.临时人数 = self.临时人数 + 1
		end
	elseif 技能名称 == "谜毒之缚" or 技能名称 == "诡蝠之刑" or 技能名称 == "怨怖之泣" then
		self.临时人数 = math.floor(self.临时等级 / 40) + 1

		if self.临时人数 >= 5 then
			self.临时人数 = 5
		end

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "灵诅") then
			self.临时人数 = self.临时人数 + 1
		end
	elseif 技能名称 == "神针撼海" then
		local lv = {
			25,
			45,
			75,
			125
		}
		self.临时人数 = 根据技能等级取数量(self.临时等级, lv) + 1
	else
		self.临时人数 = 1
	end

	return self:NPC_AI目标数量(攻击方, 技能名称, 等级, self.战斗类型) or math.min(self.临时人数, 10)
end

