function 战斗处理类:取异常封印法术状态()
	return 封印状态列表.全部
end

function 战斗处理类:取封印状态(编号, 是否)
	local 临时名称 = 封印状态列表.全部1

	for i, v in pairs(self.参战单位[编号].法术状态) do
		if 临时名称[i] ~= nil then
			if 是否 ~= nil then
				return i
			end

			return true
		end
	end

	return false
end

function 战斗处理类:取封印状态1(数量)
	local 数量 = 0

	for n = 1, #self.参战单位 do
		if self.参战单位[n].气血 >= 1 and self.参战单位[n].队伍 == self.队伍区分[2] and self:取封印状态(n, 是否) then
			数量 = 数量 + 1
		end
	end

	return 数量
end

function 战斗处理类:取隐身单位比例()
	local 数量 = 0
	local 总数量 = 0

	for n = 1, #self.参战单位 do
		if self.参战单位[n].气血 >= 1 and self.参战单位[n].队伍 == self.队伍区分[1] then
			总数量 = 总数量 + 1

			if self.参战单位[n].法术状态 ~= nil and self.参战单位[n].法术状态.修罗隐身 ~= nil then
				数量 = 数量 + 1
			end
		end
	end

	if 总数量 > 0 and 数量 > 1 and (数量 / 总数量 >= 0.5 or 数量 >= 5) then
		return true
	end

	return false
end

function 战斗处理类:取技能等级(编号, 名称)
	if self.参战单位[编号].队伍 == 0 or self.参战单位[编号].名称 == "牛幺" or self.参战单位[编号].标记 == 100080 then
		return self.参战单位[编号].等级 + 10
	end

	for n = 1, #self.参战单位[编号].主动技能 do
		if self.参战单位[编号].主动技能[n].名称 == 名称 then
			return self.参战单位[编号].主动技能[n].等级
		end
	end

	for n = 1, #self.参战单位[编号].附加状态 do
		if self.参战单位[编号].附加状态[n].名称 == 名称 then
			return self.参战单位[编号].附加状态[n].等级
		end
	end

	for n = 1, #self.参战单位[编号].追加法术 do
		if self.参战单位[编号].追加法术[n].名称 == 名称 then
			return self.参战单位[编号].追加法术[n].等级
		end
	end

	if self:取孩子技能等级(名称) then
		return self.参战单位[编号].等级
	end

	return self.参战单位[编号].等级
end

function 战斗处理类:取孩子技能等级(名称)
	local 临时名称 = {
		"四面埋伏"
	}

	for n = 1, #临时名称 do
		if 临时名称[n] == 名称 then
			return true
		end
	end

	return false
end

function 战斗处理类:取行动状态(编号)
	if self.参战单位[编号].气血 <= 0 or self.参战单位[编号].捕捉 or self.参战单位[编号].逃跑 then
		return false
	elseif self.参战单位[编号].法术状态.横扫千军 ~= nil then
		return false
	elseif self.参战单位[编号].法术状态.誓血之祭 ~= nil then
		return false
	elseif self.参战单位[编号].法术状态.破釜沉舟 ~= nil then
		return false
	elseif self.参战单位[编号].法术状态.乾坤妙法 ~= nil then
		return false
	elseif self.参战单位[编号].法术状态.失心 ~= nil then
		return false
	elseif self.参战单位[编号].法术状态.落花成泥 ~= nil and self.参战单位[编号].法术状态.落花成泥.回合 == 1 then
		return false
	elseif self.参战单位[编号].法术状态.亢龙归海 ~= nil then
		return false
	elseif self.参战单位[编号].法术状态.血雨 ~= nil then
		return false
	elseif self.参战单位[编号].法术状态.催眠符 ~= nil and self.参战单位[编号].指令.类型 ~= "召唤" then
		return false
	elseif self.参战单位[编号].精灵 and self.回合数 == 1 then
		return false
	elseif self.参战单位[编号].不攻击 ~= nil then
		return false
	end

	return true
end

function 战斗处理类:取行动状态1(编号)
	if self.参战单位[编号].气血 <= 0 then
		return false
	end

	return true
end

function 战斗处理类:取攻击状态(编号, 不判定机巧)
	local 技能名称 = 封印状态列表.不可攻击

	for i, v in pairs(self.参战单位[编号].法术状态) do
		if 技能名称[i] ~= nil then
			if v.机巧 ~= nil and self.参战单位[编号].法术状态.机巧 == nil and self.参战单位[编号].法术状态.轻霜 == nil and self:负面技能施加判断(编号, "机巧", v.攻击编号) and 不判定机巧 == nil then
				local bh = v.攻击编号

				self:添加状态("机巧", self.参战单位[编号], self.参战单位[bh], self.参战单位[bh].等级, bh)

				local hp = math.min(self.参战单位[编号].法术状态.机巧.等级, self.参战单位[编号].气血 - 1)
				local 死亡 = self:减少气血(编号, hp, nil, nil, nil, nil, 1)
				self.战斗流程[#self.战斗流程 + 1] = {
					流程 = 1021,
					攻击方 = 编号,
					气血 = hp,
					死亡 = 死亡,
					挨打方 = {}
				}

				self:添加战斗流程提示("#P(机巧)#R" ..
				self.参战单位[bh].名称 .. "#W的封印导致#R" .. self.参战单位[编号].名称 .. "#W行动失效、为其附加了#R4#W回合的#S机巧#W状态")
			end

			return false
		end
	end

	return true
end

function 战斗处理类:取法术状态(编号, 名称, 不判定机巧)
	if 编号 ~= nil and self:取奇经八脉是否有(编号, "花影") and 名称 == "雨落寒沙" then
		return true
	end

	local 技能名称 = 封印状态列表.不可法术

	for i, v in pairs(self.参战单位[编号].法术状态) do
		if 技能名称[i] ~= nil then
			if v.机巧 ~= nil and self.参战单位[编号].法术状态.机巧 == nil and self.参战单位[编号].法术状态.轻霜 == nil and self:负面技能施加判断(编号, "机巧", v.攻击编号) and 不判定机巧 == nil then
				local bh = v.攻击编号

				self:添加状态("机巧", self.参战单位[编号], self.参战单位[bh], self.参战单位[bh].等级, bh)

				local hp = math.min(self.参战单位[编号].法术状态.机巧.等级, self.参战单位[编号].气血 - 1)
				local 死亡 = self:减少气血(编号, hp, nil, nil, nil, nil, 1)
				self.战斗流程[#self.战斗流程 + 1] = {
					流程 = 1021,
					攻击方 = 编号,
					气血 = hp,
					死亡 = 死亡,
					挨打方 = {}
				}

				self:添加战斗流程提示("#P(机巧)#R" ..
				self.参战单位[bh].名称 .. "#W的封印导致#R" .. self.参战单位[编号].名称 .. "#W行动失效、为其附加了#R4#W回合的#S机巧#W状态")
			end

			return false
		end
	end

	return true
end

function 战斗处理类:取特技状态(编号, 不判定机巧)
	local 技能名称 = 封印状态列表.不可特技

	for i, v in pairs(self.参战单位[编号].法术状态) do
		if 技能名称[i] ~= nil then
			if v.机巧 ~= nil and self.参战单位[编号].法术状态.机巧 == nil and self.参战单位[编号].法术状态.轻霜 == nil and self:负面技能施加判断(编号, "机巧", v.攻击编号) and 不判定机巧 == nil then
				local bh = v.攻击编号

				self:添加状态("机巧", self.参战单位[编号], self.参战单位[bh], self.参战单位[bh].等级, bh)

				local hp = math.min(self.参战单位[编号].法术状态.机巧.等级, self.参战单位[编号].气血 - 1)
				local 死亡 = self:减少气血(编号, hp, nil, nil, nil, nil, 1)
				self.战斗流程[#self.战斗流程 + 1] = {
					流程 = 1021,
					攻击方 = 编号,
					气血 = hp,
					死亡 = 死亡,
					挨打方 = {}
				}

				self:添加战斗流程提示("#P(机巧)#R" ..
				self.参战单位[bh].名称 .. "#W的封印导致#R" .. self.参战单位[编号].名称 .. "#W行动失效、为其附加了#R4#W回合的#S机巧#W状态")
			end

			return false
		end
	end

	return true
end

function 战斗处理类:取休息状态(编号)
	local 技能名称 = 封印状态列表.休息状态

	for n = 1, #技能名称 do
		if self.参战单位[编号].法术状态[技能名称[n]] ~= nil then
			return true
		end
	end

	return false
end

function 战斗处理类:取中毒状态(编号)
	if self.参战单位[编号] ~= nil and self.参战单位[编号].法术状态 ~= nil then
		local 技能名称 = 封印状态列表.毒状态

		for n = 1, #技能名称 do
			if self.参战单位[编号].法术状态[技能名称[n]] ~= nil then
				return true
			end
		end
	end

	return false
end

function 战斗处理类:躲避判断(编号, 目标)
	if self.参战单位[编号].法术状态.晕眩 ~= nil or self.参战单位[编号].类型 == "角色" and self.参战单位[编号].必中 ~= nil then
		return false
	end

	local 躲避 = false

	if self.参战单位[目标].普攻躲避率 == nil then
		self.参战单位[目标].普攻躲避率 = 0
	end

	if self.参战单位[目标].躲避 == nil then
		self.参战单位[目标].躲避 = 0
	end

	if self.参战单位[编号].躲避 == nil then
		self.参战单位[编号].躲避 = 0
	end

	if self.参战单位[目标].命中 == nil then
		self.参战单位[目标].命中 = self.参战单位[目标].伤害
	end

	if self.参战单位[编号].命中 == nil then
		self.参战单位[编号].命中 = self.参战单位[编号].伤害
	end

	local 躲避1 = self.参战单位[目标].躲避 + 0
	local 命中1 = self.参战单位[编号].命中 + 0

	if 昼夜参数 == 1 and self.参战单位[目标].夜战 == 2 then
		躲避1 = qz(躲避1 * 1.2)
	end

	local 躲避概率 = qz(math.min(self.参战单位[目标].普攻躲避率 * 10 + math.floor(1000 - ((命中1 - 躲避1) / 500 * 0.049 + 0.95) * 1000), 990))

	if 取随机数(1, 1000) <= 躲避概率 then
		躲避 = true
	end

	return 躲避
end

function 战斗处理类:普通攻击计算(编号, 伤害系数, 友伤, 不返回, 参数列表)
	local 泡泡相伴, 反击目标, 连击, 助攻, 助攻目标, 怒击, 追击, 乘胜追击 = nil

	if 参数列表 ~= nil then
		泡泡相伴 = 参数列表.泡泡相伴
		反击目标 = 参数列表.反击目标
		助攻 = 参数列表.助攻
		助攻目标 = 参数列表.助攻目标
		连击 = 参数列表.连击
		怒击 = 参数列表.怒击
		追击 = 参数列表.追击
		乘胜追击 = 参数列表.乘胜追击
	end

	self.参战单位[编号].可追击 = nil
	local 目标 = self.参战单位[编号].指令.目标

	if 反击目标 ~= nil then
		目标 = 反击目标

		if self:取目标状态(编号, 目标, 1) == false then
			return
		end
	end

	if 助攻 ~= nil and 助攻目标 ~= nil then
		目标 = 助攻目标

		if 目标 == nil or self.参战单位[目标] == nil or self.参战单位[目标].名称 == nil or self:取目标状态(编号, 目标, 1) == false then
			目标 = self:取单个敌方目标(编号)
		end

		if 目标 == 0 or self.参战单位[目标] == nil then
			return
		end

		self:添加战斗流程提示("#P(助攻)#R" .. self.参战单位[编号].名称 .. "#W对#R" .. self.参战单位[目标].名称 .. "#W进行了#Y助攻攻击")

		if self.参战单位[编号].狂莽一击 ~= nil and ygsj() <= 50 then
			self.参战单位[编号].狂莽一击 = 目标 + 0
			目标 = self:取单个敌方目标(编号, nil, 目标)

			if 目标 == 0 then
				目标 = self.参战单位[编号].狂莽一击 + 0
			end
		end
	end

	local 目标数 = self:取目标数量(self.参战单位[编号], 名称, 等级, 编号)

	if 目标 == 0 or 目标 == nil then
		目标 = self:取单个敌方目标(编号)
	elseif self:取目标状态(编号, 目标, 1) == false then
		目标 = self:取单个敌方目标(编号)
	elseif self.参战单位[编号].指令.取消 then
		return
	end

	if 目标 == 0 then
		return
	end

	if self.参战单位[目标].法术状态.分身术 ~= nil and self.参战单位[目标].法术状态.分身术.破解 == nil then
		self.参战单位[目标].法术状态.分身术.破解 = 1
		self.参战单位[编号].出手 = 1

		self:添加战斗流程提示("#P(分身术)#R" .. self.参战单位[编号].名称 .. "#W的攻击被#R" .. self.参战单位[目标].名称 .. "#W的#Y分身术#W躲过去了！")

		return
	end

	self.战斗流程[#self.战斗流程 + 1] = {
		流程 = 1,
		攻击方 = 编号,
		挨打方 = {
			{
				挨打方 = 目标,
				特效 = {}
			}
		}
	}
	local 普攻流程 = #self.战斗流程 + 0

	if 反击目标 ~= nil then
		self.普攻被反击流程 = 普攻流程 + 0

		if 参数列表.必定反击 ~= nil then
			self:添加战斗流程提示(
			"#P(超级反击)#R" .. self.参战单位[编号].名称 .. "#W一声大吼：#G“犯吾主者，绝不姑息！”#W、旋即对#R" .. self.参战单位[目标].名称 .. "#W进行了#Y反击", 普攻流程)
		else
			self:添加战斗流程提示("#P(反击)#R" .. self.参战单位[编号].名称 .. "#W对#R" .. self.参战单位[目标].名称 .. "#W进行了#Y反击", 普攻流程)
		end
	end

	if 不返回 ~= true then
		self.参战单位[编号].返回流程 = #self.战斗流程 + 0
	else
		self.参战单位[编号].返回流程 = nil
	end

	local 躲避 = self:躲避判断(编号, 目标)

	if 反击目标 ~= nil then
		躲避 = false
	end

	self.执行等待 = self.执行等待 + 10
	local 保护 = false
	local 保护编号 = 0

	if not 躲避 then
		for n = 1, #self.参战单位 do
			if 保护编号 == 0 and self:取行动状态(n) and self.参战单位[目标].法术状态.惊魂掌 == nil and self.参战单位[n].指令.类型 == "保护" and self.参战单位[n].队伍 == self.参战单位[目标].队伍 and self.参战单位[n].指令.目标 == 目标 then
				保护编号 = n
				保护 = true
				self.参战单位[n].指令.类型 = ""
				self.执行等待 = self.执行等待 + 3
			end
		end
	end

	local 必杀 = false
	local 防御 = false
	local 伤害 = self:取基础物理伤害(编号, 目标)
	local 最终伤害 = self:取最终物理伤害(编号, 目标, 伤害)
	local 招财进宝 = false
	local 伤害值 = 最终伤害

	if not 躲避 then
		if self.参战单位[编号].傀儡 == 1 and (self.参战单位[编号].法术状态.无魂傀儡 ~= nil or self.参战单位[编号].法术状态.断线木偶 ~= nil) then
			伤害值.伤害 = 0
			伤害值.类型 = 2
			self.真实伤害 = nil
			self.参战单位[编号].傀儡 = nil
			self.战斗流程[普攻流程].挨打方[1].动作 = 最终伤害.动作
			self.战斗流程[普攻流程].挨打方[1].特效 = 最终伤害.特效

			if #最终伤害.特效 == 0 then
				self.战斗流程[普攻流程].挨打方[1].特效 = {
					"被击中"
				}
			end
		end

		if 伤害值.类型 ~= 2 then
			if self.参战单位[编号].法术状态.谜毒之缚 ~= nil then
				伤害值.伤害 = qz(伤害值.伤害 * 0.7 * 0.8)
			end

			if 伤害系数 == nil then
				伤害系数 = 1
			end

			伤害值.伤害 = 伤害值.伤害 * 伤害系数

			if 最终伤害.暴击 ~= true and self.参战单位[编号].招财进宝 ~= nil and 取随机数(1, 10000) <= self.参战单位[编号].招财进宝 * 100 then
				伤害值.伤害 = 伤害值.伤害 * 4
				招财进宝 = true
			end

			if self.参战单位[编号].狂莽一击 ~= nil then
				伤害值.伤害 = 伤害值.伤害 * 1.25
			end

			local 最终结果1 = nil

			if 连击 ~= nil then
				最终结果1 = self:新增状态处理("普攻连击", 编号, 目标, 伤害值.伤害, 伤害值.类型, 1, nil, nil, nil, 普攻流程 + 0)
			else
				最终结果1 = self:新增状态处理("普攻", 编号, 目标, 伤害值.伤害, 伤害值.类型, 1, nil, nil, nil, 普攻流程 + 0)
			end

			伤害值.伤害 = qz(最终结果1.伤害)
			伤害值.类型 = 最终结果1.类型

			if 伤害值.类型 ~= 2 then
				if 保护 == true then
				elseif self.参战单位[目标].气血 - 伤害值.伤害 < self.参战单位[目标].最大气血 * 0.3 then
					保护编号 = self:自动保护计算(目标, 伤害值.伤害, 编号)
				end

				if 保护编号 ~= 0 and self.参战单位[保护编号] ~= nil then
					local 保护伤害 = math.floor(伤害值.伤害 * 0.55)
					local 保护死亡 = self:减少气血(保护编号, 保护伤害, nil, nil, nil, nil, 1)
					伤害值.伤害 = math.floor(伤害值.伤害 * 0.3)
					self.战斗流程[普攻流程].保护数据 = {
						编号 = 保护编号,
						伤害 = 保护伤害,
						死亡 = 保护死亡
					}
				end

				if 友伤 ~= nil then
					伤害值.伤害 = 伤害值.伤害 * 0.11111
					self.参战单位[编号].指令.类型 = ""
					self.参战单位[编号].指令.参数 = ""
					self.参战单位[编号].指令.下达 = true
					友伤 = nil
				end

				伤害值.伤害 = qz(伤害值.伤害)
			end

			if self.参战单位[编号].碎甲刃 ~= nil and self.参战单位[编号].碎甲刃 > 0 and ygsj() <= 30 then
				self:添加状态("碎甲刃", self.参战单位[目标], self.参战单位[编号], self.参战单位[编号].碎甲刃, 编号)

				self.战斗流程[普攻流程].挨打方[1].增加状态 = "碎甲刃"
			end
		end

		if self.参战单位[目标].法术状态.波澜不惊 ~= nil and self.参战单位[目标].法术状态.波澜不惊.层数 >= 1 and 伤害值.伤害 > 1 and 伤害值.类型 ~= 2 then
			local 编号1 = self.参战单位[目标].法术状态.波澜不惊.攻击编号
			local 最大吸收 = self.参战单位[目标].法术状态.波澜不惊.等级 * 4 + self.参战单位[编号1].灵力 * 0.1
			最大吸收 = self:取恢复气血(编号1, 目标, 最大吸收, "普渡众生", 1) * 2
			local 吸收血量 = 0

			if 伤害值.伤害 <= 最大吸收 then
				吸收血量 = 伤害值.伤害
				伤害值.类型 = 2
			else
				吸收血量 = 最大吸收
				伤害值.伤害 = 伤害值.伤害 - 最大吸收
				self.战斗流程[普攻流程].挨打方[1].恢复气血 = 吸收血量
			end

			self:增加气血(目标, 吸收血量)

			self.战斗流程[普攻流程].挨打方[1].特效[#self.战斗流程[普攻流程].挨打方[1].特效 + 1] = "波澜不惊"
			self.参战单位[目标].法术状态.波澜不惊.层数 = self.参战单位[目标].法术状态.波澜不惊.层数 - 1
		end

		self.战斗流程[普攻流程].挨打方[1].护盾掉血值 = nil

		if (伤害值.类型 == 1 or 伤害值.类型 == 3 or 伤害值.类型 == 4) and self.参战单位[目标].法术状态.护盾 ~= nil and self.参战单位[目标].法术状态.护盾.护盾值 ~= nil then
			if 伤害值.伤害 < self.参战单位[目标].法术状态.护盾.护盾值 then
				self.参战单位[目标].法术状态.护盾.护盾值 = self.参战单位[目标].法术状态.护盾.护盾值 - 伤害值.伤害
				self.战斗流程[普攻流程].挨打方[1].护盾掉血值 = 伤害值.伤害
				伤害值.伤害 = 0
			else
				self.战斗流程[普攻流程].挨打方[1].护盾掉血值 = self.参战单位[目标].法术状态.护盾.护盾值
				伤害值.伤害 = 伤害值.伤害 - self.参战单位[目标].法术状态.护盾.护盾值

				self:取消状态("护盾", self.参战单位[目标])

				self.战斗流程[普攻流程].挨打方[1].取消状态 = "护盾"
			end
		end

		self.战斗流程[普攻流程].挨打方[1].动作 = 最终伤害.动作
		self.战斗流程[普攻流程].挨打方[1].特效 = 最终伤害.特效

		if #最终伤害.特效 == 0 then
			self.战斗流程[普攻流程].挨打方[1].特效 = {
				"被击中"
			}
		end

		if 招财进宝 == true then
			self.战斗流程[普攻流程].挨打方[1].特效[#self.战斗流程[普攻流程].挨打方[1].特效 + 1] = "招财进宝"
		end
	else
		伤害值.伤害 = 0
		伤害值.类型 = 2
		self.真实伤害 = nil
	end

	if 躲避 then
		self.战斗流程[普攻流程].躲避 = true
	end

	self.战斗流程[普攻流程].挨打方[1].伤害 = 伤害值.伤害 + 0
	self.战斗流程[普攻流程].挨打方[1].伤害类型 = 伤害值.类型
	self.战斗流程[普攻流程].返回 = true

	if 不返回 ~= nil and 不返回 == true then
		self.战斗流程[普攻流程].返回 = false
	end

	if 伤害值.类型 == 2 then
		self:增加气血(目标, 伤害值.伤害)
	else
		if self.参战单位[目标].类型 ~= "角色" and ygsj() <= 10 and self.参战单位[目标].气血 - 伤害值.伤害 <= self.参战单位[编号].等级 * 50 and self.参战单位[编号].绝杀 ~= nil and self.参战单位[目标].不可封印 ~= true and 伤害值.伤害 > 0 and not self:取玩家战斗() then
			伤害值.伤害 = 伤害值.伤害 + self.参战单位[目标].气血

			self:添加战斗流程提示("#P(绝杀)#R" .. self.参战单位[编号].名称 .. "#W对#R" .. self.参战单位[目标].名称 .. "#W造成了#R绝杀", 普攻流程)
		elseif self.参战单位[编号].赶尽杀绝 ~= nil and ygsj() <= self.参战单位[编号].赶尽杀绝 and self.参战单位[目标].类型 ~= "角色" and self.参战单位[目标].气血 - 伤害值.伤害 <= self.参战单位[编号].等级 * 25 and self.参战单位[目标].不可封印 ~= true and not self:取玩家战斗() and 伤害值.伤害 > 0 then
			伤害值.伤害 = 伤害值.伤害 + self.参战单位[目标].气血

			self:添加战斗流程提示("#P(赶尽杀绝)#R" .. self.参战单位[编号].名称 .. "#W对#R" .. self.参战单位[目标].名称 .. "#W进行了#R赶尽杀绝", 普攻流程)
		end

		if self.恐吓击飞 == 1 then
			伤害值.伤害 = self.参战单位[目标].气血 + 99999
			self.恐吓击飞 = 0
		end

		self.凝光炼彩护盾 = true
		self.战斗流程[普攻流程].挨打方[1].死亡 = self:减少气血(目标, 伤害值.伤害, 编号, nil, nil, nil, 1)

		if self.战斗流程[普攻流程].挨打方[1].死亡 ~= nil and (泡泡相伴 == nil or 泡泡相伴是否触发嗜血追击) and self.参战单位[编号].不追击 ~= true and 助攻 == nil and 反击目标 == nil then
			self.参战单位[编号].可追击 = true
		end

		if (self:取奇经八脉是否有(编号, "育养") or self.参战单位[编号].报恩 ~= nil) and ygsj() <= 30 then
			local 吸血伤害 = qz(伤害值.伤害 * 0.18)
			local bb = self.参战单位[编号].召唤兽

			if self.参战单位[编号].报恩 ~= nil then
				bb = self.参战单位[编号].报恩

				if bb ~= nil and self:取目标状态(bb, bb, 2) then
					self.战斗流程[普攻流程].友方回血 = bb + 0
					self.战斗流程[普攻流程].友方回血值 = (self.战斗流程[普攻流程].友方回血值 or 0) + 吸血伤害

					self:增加气血(bb, 吸血伤害)
					self:添加战斗流程提示("#P(报恩)#R" .. self.参战单位[bb].名称 .. "#W吸取了#S" .. 吸血伤害 .. "#W点气血", 普攻流程)
				end
			else
				bb = self.参战单位[编号].召唤兽

				if bb ~= nil and self:取目标状态(bb, bb, 2) then
					self.战斗流程[普攻流程].友方回血 = bb + 0
					self.战斗流程[普攻流程].友方回血值 = (self.战斗流程[普攻流程].友方回血值 or 0) + 吸血伤害

					self:增加气血(bb, 吸血伤害)
					self:添加战斗流程提示("#P(育养)#R" .. self.参战单位[bb].名称 .. "#W吸取了#S" .. 吸血伤害 .. "#W点气血", 普攻流程)
				end
			end
		end

		if self.参战单位[目标].法术状态.催眠符 and 伤害值.伤害 > (self.参战单位[目标].法术状态.催眠符.黄粱 or 0) then
			self:取消状态("催眠符", self.参战单位[目标])

			self.战斗流程[普攻流程].挨打方[1].取消状态 = "催眠符"
		end
	end

	if 伤害值.类型 ~= 2 and 伤害值.伤害 > 0 then
		if self.参战单位[编号].气血 > 0 and self.参战单位[目标].法术状态.混元伞 ~= nil then
			local 反弹伤害 = qz(self.战斗流程[普攻流程].挨打方[1].伤害 * (self.参战单位[目标].法术状态.混元伞.境界 * 混元伞反弹比例 + 0.1))
			self.战斗流程[普攻流程 + 1] = {
				流程 = 104,
				气血 = 反弹伤害,
				攻击方 = 目标,
				挨打方 = {
					挨打方 = 编号,
					特效 = {},
					死亡 = self:减少气血(编号, 反弹伤害, 目标, nil, nil, nil, 1)
				},
				提示 = {
					允许 = false
				}
			}
		end

		if self.参战单位[编号].气血 > 0 and self.参战单位[目标].法术状态.修罗咒 ~= nil then
			local 反弹伤害 = qz(self.战斗流程[普攻流程].挨打方[1].伤害 * 0.5)
			self.战斗流程[普攻流程 + 1] = {
				流程 = 124,
				气血 = 反弹伤害,
				攻击方 = 目标,
				挨打方 = {
					挨打方 = 编号,
					特效 = {},
					死亡 = self:减少气血(编号, 反弹伤害, 目标, nil, nil, nil, 1)
				},
				提示 = {
					允许 = false
				}
			}
		end

		if self.参战单位[编号].法术状态.诡蝠之刑 ~= nil and self:取目标状态(编号, 编号, 2) then
			local 气血 = qz(伤害值.伤害 * 0.1)

			if 气血 <= 1 then
				气血 = 1
			end

			self.战斗流程[普攻流程 + 1] = {
				气血 = 0,
				流程 = 102,
				攻击方 = 编号,
				挨打方 = {}
			}
			self.战斗流程[普攻流程].死亡 = self:减少气血(编号, 气血, nil, nil, nil, nil, 1)
			self.战斗流程[普攻流程].气血 = 气血
		end

		if 目标 ~= nil and self:取奇经八脉是否有(目标, "养生") and self.参战单位[目标].气血 <= qz(self.参战单位[目标].最大气血 * 0.7) and self.参战单位[目标].法术状态.生命之泉 == nil then
			self:添加状态("生命之泉", self.参战单位[目标], self.参战单位[目标], self.参战单位[目标].等级, 目标)

			self.战斗流程[普攻流程].挨打方[1].添加状态 = "生命之泉"
		end
	end

	if 最终伤害.暴击 ~= nil and not 躲避 and self.参战单位[编号].傀儡 == nil then
		必杀 = true

		if self.参战单位[编号].泡泡相伴 ~= nil and 泡泡相伴 == nil and 助攻 == nil and 乘胜追击 == nil and self:取攻击状态(编号) and self:取目标状态(编号, 目标, 1) == true then
			self.战斗流程[普攻流程].返回 = false

			self:添加战斗流程提示("#P(泡泡相伴)#R" .. self.参战单位[编号].名称 .. "#W触发了#R泡泡相伴", 普攻流程)

			self.参战单位[编号].临时增伤 = self.参战单位[编号].伤害 * 0.05

			self:普通攻击计算(编号, 1, nil, 不返回, {
				泡泡相伴 = 1
			})
		end
	end

	if self.参战单位[目标].九黎浮空 == nil and self.参战单位[目标].法术状态.火甲术 ~= nil and self.参战单位[目标].气血 > 0 then
		local fjsh = 0.5

		if 目标 ~= nil and self:取奇经八脉是否有(目标, "返火") then
			fjsh = fjsh * 2
		end

		self.战斗流程[普攻流程].返回 = false

		self:法攻技能计算(目标, "三昧真火", self:取技能等级(目标, "三昧真火") or self.参战单位[目标].等级, fjsh, nil, {
			魔反目标 = 编号
		})

		self.反击挨打返回 = 1

		if self.参战单位[编号].返回流程 ~= nil and self.参战单位[编号].返回流程 <= #self.战斗流程 then
			self.战斗流程[#self.战斗流程].挨打返回 = true
			self.战斗流程[#self.战斗流程].返回 = true
		end
	end

	if self.参战单位[编号].傀儡 == nil then
		if 反击目标 == nil then
			self:反震反击处理(编号, 目标, 保护, nil, self.真实伤害, 普攻流程, {
				攻击方式 = "普攻"
			})

			if self.参战单位[编号].队伍 ~= self.参战单位[目标].队伍 and self.参战单位[目标 + 1] ~= nil and self.参战单位[目标 + 1].超级反击 ~= nil and self.参战单位[目标 + 1].超级反击 > 0 then
				self:反震反击处理(编号, 目标 + 1, 保护, nil, nil, 普攻流程, {
					必定反击 = true,
					攻击方式 = "普攻"
				})

				self.参战单位[目标 + 1].超级反击 = self.参战单位[目标 + 1].超级反击 - 1
			end
		else
			self:反震反击处理(编号, 目标, 保护, 1, self.真实伤害, 普攻流程, {
				攻击方式 = "普攻"
			})

			if self.参战单位[编号].队伍 ~= self.参战单位[目标].队伍 and self.参战单位[目标 + 1] ~= nil and self.参战单位[目标 + 1].超级反击 ~= nil and self.参战单位[目标 + 1].超级反击 > 0 then
				if self.参战单位[目标].返回流程 ~= nil and self.参战单位[目标].返回流程 <= #self.战斗流程 then
					self.战斗流程[#self.战斗流程].挨打返回 = true
					self.战斗流程[#self.战斗流程].返回 = true
				end

				self:反震反击处理(编号, 目标 + 1, 保护, nil, nil, 普攻流程, {
					必定反击 = true,
					返回 = true,
					攻击方式 = "普攻"
				})

				self.参战单位[目标 + 1].超级反击 = self.参战单位[目标 + 1].超级反击 - 1
			end
		end
	end

	local zj = {}

	if 怒击 == nil and 泡泡相伴 == nil and 乘胜追击 == nil and self:取目标状态(编号, 目标, 1) == true and self.参战单位[编号].傀儡 == nil then
		if self.参战单位[编号].烈焰斩 ~= nil and ygsj() <= self.参战单位[编号].烈焰斩 then
			zj[#zj + 1] = "烈焰斩"
		end

		if self.参战单位[编号].影袭 ~= nil and ygsj() <= self.参战单位[编号].影袭 then
			zj[#zj + 1] = "影袭"
		end
	end

	if #zj > 0 then
		self.战斗流程[普攻流程].返回 = false
		local 返回判断 = true

		if 不返回 ~= nil then
			返回判断 = not 不返回
		end

		for i = 1, #zj do
			local 返回判断1 = false

			if i == #zj then
				返回判断1 = 返回判断
			end

			self:法攻技能计算(编号, zj[i], self.参战单位[编号].等级, 1, nil, {
				魔反目标 = 目标,
				返回 = 返回判断1
			})
		end
	end

	if self.参战单位[编号].乘胜追击 ~= nil and 乘胜追击 == nil then
		self.参战单位[编号].乘胜追击 = self.参战单位[编号].乘胜追击 + 1

		if self.参战单位[编号].乘胜追击 >= 4 then
			self.战斗流程[普攻流程].返回 = false
		end
	end

	if self.参战单位[目标].气血 <= 0 and self.参战单位[编号].气血 > 0 then
		if self.参战单位[编号].自恋特性 ~= nil and self.参战单位[编号].自恋次数 == nil and 取随机数(1, 20) <= self.参战单位[编号].自恋特性 * 20 then
			self.参战单位[编号].自恋次数 = 1
			self.战斗发言数据[#self.战斗发言数据 + 1] = {
				内容 = "我这一顿乱打下去，神仙都扛不住#24",
				id = 编号
			}
		end

		if self.参战单位[编号].嗜血追击 ~= nil and self.参战单位[编号].可追击 == true and self:取单个敌方目标(编号) ~= 0 then
			self.战斗流程[普攻流程].返回 = false
		else
			self.战斗流程[普攻流程].返回 = true
		end
	elseif self.参战单位[编号].气血 <= 0 then
		self.战斗流程[普攻流程].返回 = false
	end

	if self.连击判定 ~= true and (self.参战单位[编号].乘胜追击 == nil or self.参战单位[编号].乘胜追击 < 4) and self.反击挨打返回 == 1 and self:取目标状态(编号, 编号, 3) and self.战斗流程[self.普攻被反击流程] ~= nil and self.普攻被反击流程 <= #self.战斗流程 then
		self.战斗流程[self.普攻被反击流程].挨打返回 = true
		self.反击挨打返回 = 0
	else
		self.反击挨打返回 = 0
	end

	if 必杀 and self.参战单位[编号].怒击效果 then
		return true
	end
end

function 战斗处理类:反震反击处理(编号, 目标, 保护, 反击判定, 伤害, 流程, 额外参数)
	if self.参战单位[目标].九黎浮空 ~= nil then
		return
	end

	额外参数 = 额外参数 or {}
	local 反震 = self.参战单位[目标].反震
	local 反击 = self:取是否反击(编号, 目标, 额外参数.攻击方式)

	if 流程 == nil then
		流程 = #self.战斗流程 + 0
	end

	if self.参战单位[编号].偷袭 == nil and 反震 ~= nil and ygsj() <= 反震概率 and 保护 == false and 伤害 ~= nil then
		local 反震伤害 = math.floor(伤害 * 反震)

		if 反震伤害 <= 0 then
			反震伤害 = 1
		end

		反震伤害 = 反震伤害 + (self.参战单位[目标].反震1 or 0)
		self.战斗流程[流程].反震伤害 = 反震伤害

		if self.参战单位[目标].超级反震 ~= nil and self.参战单位[编号].气血上限 ~= nil then
			self:造成伤势(编号, 反震伤害)
		end

		self.战斗流程[流程].反震死亡 = self:减少气血(编号, 反震伤害, 目标, nil, nil, nil, 1)
		self.战斗流程[流程].挨打方[1].特效[#self.战斗流程[流程].挨打方[1].特效 + 1] = "反震"
		self.执行等待 = self.执行等待 + 2
	end

	if 额外参数.必定反击 ~= nil or 反击 == true and self.参战单位[目标].气血 > 0 and self.参战单位[编号].偷袭 == nil and 保护 == false and 反击判定 == nil then
		if 额外参数.返回 == nil then
			self.战斗流程[流程].返回 = false
		end

		self:普通攻击计算(目标, self.参战单位[目标].反击 or 1, nil, nil, {
			反击目标 = 编号,
			必定反击 = 额外参数.必定反击
		})

		self.反击挨打返回 = 1
	end

	if self.参战单位[目标].魔法反击 ~= nil and ygsj() <= 魔反概率 and self.参战单位[目标].气血 > 0 and self.参战单位[编号].偷袭 == nil and 保护 == false and 反击判定 == nil then
		self.战斗流程[流程].返回 = false

		self:法攻技能计算(目标, 魔法反击小法列表[ygsj(#魔法反击小法列表)], self.参战单位[目标].等级, self.参战单位[目标].魔法反击, nil, {
			魔反目标 = 编号
		})

		self.反击挨打返回 = 1
	end
end

function 战斗处理类:取是否反击(编号, 目标, 攻击方式)
	local gl = 反击概率

	if self.参战单位[目标].超级反击 ~= nil then
		gl = 超级反击概率
	end

	if (攻击方式 == "普攻" and (self.参战单位[目标].法术状态.极度疯狂 ~= nil or self.参战单位[目标].法术状态.魔王回首 ~= nil) or self.参战单位[编号].法术状态.诱袭 ~= nil or self.参战单位[目标].反击 ~= nil and ygsj() <= gl) and self.参战单位[目标].气血 > 0 then
		return true
	end

	return false
end

function 战斗处理类:减少魔法(编号, 数额)
	if (数额 or 0) <= 0 then
		return
	end

	local 原本 = self.参战单位[编号].魔法 + 0
	self.参战单位[编号].魔法 = self.参战单位[编号].魔法 - 数额

	if self.参战单位[编号].最大魔法 < self.参战单位[编号].魔法 then
		self.参战单位[编号].魔法 = self.参战单位[编号].最大魔法
	elseif self.参战单位[编号].魔法 < 0 then
		self.参战单位[编号].魔法 = 0
	end

	self:流程更新气血魔法愤怒(编号, 2)

	return 原本 - self.参战单位[编号].魔法
end

function 战斗处理类:增加魔法(编号, 数额)
	if (数额 or 0) <= 0 then
		return
	end

	local 原本 = self.参战单位[编号].魔法 + 0

	if self.参战单位[编号].法术状态.魔音摄魂 ~= nil and self.参战单位[编号].法术状态.魔音摄魂.迷意 ~= nil then
		if self:取封印状态(编号) == false then
			self:添加提示(self.参战单位[编号].玩家id, 编号, "#Y/你当前状态无法恢复魔法!")

			return
		else
			数额 = qz(数额 * 0.4)
		end
	end

	if self.参战单位[编号].法术状态.腾雷 ~= nil then
		数额 = qz(数额 * 0.5)
	end

	if self.参战单位[编号].法术状态.瘴气 ~= nil and self.参战单位[编号].法术状态.瘴气.迷意 ~= nil then
		数额 = qz(数额 * 0.7)
	end

	self.参战单位[编号].魔法 = self.参战单位[编号].魔法 + 数额

	if self.参战单位[编号].最大魔法 < self.参战单位[编号].魔法 then
		self.参战单位[编号].魔法 = self.参战单位[编号].最大魔法
	end

	self:流程更新气血魔法愤怒(编号, 2)

	return self.参战单位[编号].魔法 - 原本
end

function 战斗处理类:添加护盾(编号, 数额, 施加方, 无视上限)
	if 数额 == 0 then
		return 0
	end

	if 施加方 ~= nil and self.参战单位[施加方].烛照 ~= nil then
		数额 = 数额 * self.参战单位[施加方].烛照
	end

	数额 = qz(数额)
	local 上限 = qz(self.参战单位[编号].最大气血 * 0.3)

	if 无视上限 ~= nil then
		上限 = 99999999
	end

	if self.参战单位[编号].法术状态.护盾 == nil then
		if 上限 ~= nil and 上限 < 数额 then
			数额 = 上限 + 0
		end

		self:添加状态("护盾", self.参战单位[编号], self.参战单位[编号], 数额)
		self:客户端添加状态(编号, "护盾")

		return 数额
	elseif 上限 ~= nil and 上限 <= (self.参战单位[编号].法术状态.护盾.护盾值 or 0) then
		return 0
	else
		if 上限 ~= nil and 上限 < 数额 + (self.参战单位[编号].法术状态.护盾.护盾值 or 0) then
			数额 = 上限 - (self.参战单位[编号].法术状态.护盾.护盾值 or 0)
		end

		self.参战单位[编号].法术状态.护盾.护盾值 = (self.参战单位[编号].法术状态.护盾.护盾值 or 0) + 数额

		self:更新单个法术状态(编号, "护盾")

		return 数额
	end

	return 0
end

function 战斗处理类:增加气血(编号, 数额, 溢出加护盾, 羁绊)
	local aa = self.参战单位[编号].气血 + 0

	if self.参战单位[编号].类型 ~= "角色" or self.参战单位[编号].玩家id == 0 then
		self.参战单位[编号].气血上限 = nil
	end

	self.参战单位[编号].气血 = self.参战单位[编号].气血 + 数额

	if self.参战单位[编号].死亡状态 ~= nil then
		self.参战单位[编号].死亡状态 = nil
	end

	if math.min(self.参战单位[编号].最大气血, self.参战单位[编号].气血上限 or self.参战单位[编号].最大气血) < self.参战单位[编号].气血 then
		if 溢出加护盾 ~= nil then
			local hd = self.参战单位[编号].气血 - math.min(self.参战单位[编号].最大气血, self.参战单位[编号].气血上限 or self.参战单位[编号].最大气血)

			self:添加护盾(编号, hd)
		end

		self.参战单位[编号].气血 = math.min(self.参战单位[编号].最大气血, self.参战单位[编号].气血上限 or self.参战单位[编号].最大气血)
	end

	if 羁绊 == nil and self.参战单位[编号].羁绊 ~= nil then
		local 羁绊单位 = self.参战单位[编号].羁绊 + 0

		if self.参战单位[羁绊单位] ~= nil and self.参战单位[羁绊单位].气血 > 0 and self.参战单位[羁绊单位].死亡状态 == nil then
			self:增加气血(羁绊单位, qz1(数额 * 0.15), nil, true)
			常规提示(self.参战单位[羁绊单位].玩家id,
				"#P(羁绊)#R" ..
				self.参战单位[编号].名称 .. "#W回血使得#S" .. self.参战单位[羁绊单位].名称 .. "#W也恢复了#R" .. qz1(数额 * 0.15) .. "点气血")
		end
	end

	if aa <= 0 and self.参战单位[编号].气血 > 0 and self:取奇经八脉是否有(编号, "神躯") and (self.参战单位[编号].战意 or 0) <= 1 then
		self:刷新战意(编号, 1)
	end

	self:流程更新气血魔法愤怒(编号, 1)

	return math.max(self.参战单位[编号].气血 - aa, 0)
end

function 战斗处理类:恢复伤势(编号, 数额)
	if self.参战单位[编号].类型 ~= "角色" or self.参战单位[编号].气血上限 == nil then
		return
	end

	self.参战单位[编号].气血上限 = math.max(self.参战单位[编号].气血上限, 0) + 数额

	if self.参战单位[编号].最大气血 < self.参战单位[编号].气血上限 then
		self.参战单位[编号].气血上限 = self.参战单位[编号].最大气血
	end

	self:流程更新气血魔法愤怒(编号, 4)
end

function 战斗处理类:添加即时发言(编号, 文本)
	for n = 1, #self.参战玩家 do
		发送数据(self.参战玩家[n].连接id, 5512, {
			id = 编号,
			文本 = 文本
		})
	end
end

function 战斗处理类:添加危险发言(编号, 类型)
	if self.参战单位[编号].队伍 ~= 0 then
		local 已发言 = false

		for n = 1, #self.参战单位 do
			if 已发言 == false and self.参战单位[n].队伍 == self.参战单位[编号].队伍 and self.参战单位[n].预知特性 ~= nil and self.参战单位[n].预知次数 < 3 and ygsj() <= self.参战单位[n].预知特性 * 7 then
				self.参战单位[n].预知次数 = self.参战单位[n].预知次数 + 1
				self.战斗发言数据[#self.战斗发言数据 + 1] = {
					id = n,
					内容 = self:取危险发言内容(self.参战单位[编号].名称, 类型)
				}
				已发言 = true
			end
		end

		for n = 1, #self.参战玩家 do
			for i = 1, #self.战斗发言数据 do
				发送数据(self.参战玩家[n].连接id, 5512, {
					id = self.战斗发言数据[i].id,
					文本 = self.战斗发言数据[i].内容
				})
			end
		end

		self.战斗发言数据 = {}
	end
end

function 战斗处理类:取危险发言内容(名称, 类型)
	local 发言内容 = {}

	if 类型 == 1 then
		发言内容 = {
			format("#G/%s#W我的直觉告诉我你活不过本回合#74", 名称),
			format("让我们高歌欢舞恭送#G/%s#83", 名称),
			format("唢呐吹起来，锣鼓敲起来，我们的#G/%s#W/倒下来#42", 名称)
		}
	elseif 类型 == 2 then
		发言内容 = {
			format("#G/%s#W看起来伤势很重啊#52", 名称),
			format("#G/%s#W你再不注意加血，当心我在你坟头上蹦迪哈#24", 名称),
			format("#G/%s#W/你是长相有问题还是内心太黑暗呢#55", 名称)
		}
	end

	return 发言内容[ygsj(#发言内容)]
end

function 战斗处理类:造成伤势(编号, 数额)
	if self.参战单位[编号] == nil or self.参战单位[编号].气血上限 == nil then
		return
	end

	self.参战单位[编号].气血上限 = self.参战单位[编号].气血上限 - 数额

	if self.参战单位[编号].气血上限 <= 0 then
		self.参战单位[编号].气血上限 = 0
	end

	self:流程更新气血魔法愤怒(编号, 4)
end

function 战斗处理类:取护盾值(编号)
	if self.参战单位[编号].法术状态.护盾 ~= nil and self.参战单位[编号].法术状态.护盾.护盾值 ~= nil then
		return self.参战单位[编号].法术状态.护盾.护盾值
	end

	return 0
end

function 战斗处理类:金蟾回血(编号, 金蟾境界, 比例, 流程)
	local 目标组 = self:取全体敌友方目标(编号, nil)

	if 目标组 ~= 0 and not 判断是否为空表(目标组) then
		local 气血 = qz1((金蟾境界 * 4 + 15) / 100 * 1500 * 比例)
		local bb = {}

		for i = 1, #目标组 do
			if self.参战单位[目标组[i]].召唤物 == nil then
				bb[#bb + 1] = {
					气血类型 = 2,
					挨打方 = 目标组[i],
					气血 = 气血
				}
			end
		end

		self:流程处理气血魔法(编号, bb)

		for i = 1, #目标组 do
			if self.参战单位[目标组[i]].召唤物 == nil then
				self:增加气血(目标组[i], 气血)
			end
		end

		self:添加战斗流程提示("#P(金蟾)#W#R" .. self.参战单位[编号].名称 .. "#W为所有队友恢复了#R" .. 气血 .. "点气血", 流程)
	end
end

判断护盾值状态 = {
	铜头铁臂 = 1,
	镜之阳 = 1,
	护盾 = 0,
	镜之阴 = 1
}
护盾状态优先级 = {
	"镜之阴",
	"镜之阳",
	"铜头铁臂"
}

function 战斗处理类:扣除护盾(编号, 数额, 取消状态扣除)
	local 护盾值 = self:取护盾值(编号)

	if 护盾值 <= 数额 then
		local 取消状态列表 = {
			"护盾"
		}

		self:取消状态("护盾", self.参战单位[编号])

		if 取消状态扣除 == nil then
			for i = 1, #护盾状态优先级 do
				if self.参战单位[编号].法术状态[护盾状态优先级[i]] ~= nil then
					self:取消状态(护盾状态优先级[i], self.参战单位[编号])

					取消状态列表[#取消状态列表 + 1] = 护盾状态优先级[i]
				end
			end
		end

		self:流程处理状态(编号, {
			{
				挨打方 = 编号,
				取消状态 = 取消状态列表,
				状态 = 取消状态列表
			}
		})
	else
		local 取消状态列表 = {}
		local 更新状态列表 = {
			"护盾"
		}
		self.参战单位[编号].法术状态.护盾.护盾值 = 护盾值 - 数额

		if 取消状态扣除 == nil then
			local aa = 数额 + 0

			for i = 1, #护盾状态优先级 do
				if self.参战单位[编号].法术状态[护盾状态优先级[i]] ~= nil then
					if aa < self.参战单位[编号].法术状态[护盾状态优先级[i]].护盾值 then
						self.参战单位[编号].法术状态[护盾状态优先级[i]].护盾值 = self.参战单位[编号].法术状态[护盾状态优先级[i]].护盾值 - 数额
						更新状态列表[#更新状态列表 + 1] = 护盾状态优先级[i]

						break
					else
						aa = aa - self.参战单位[编号].法术状态[护盾状态优先级[i]].护盾值

						self:取消状态(护盾状态优先级[i], self.参战单位[编号])

						更新状态列表[#更新状态列表 + 1] = 护盾状态优先级[i]
						取消状态列表[#取消状态列表 + 1] = 护盾状态优先级[i]
					end
				end
			end
		end

		self:流程处理状态(编号, {
			{
				挨打方 = 编号,
				取消状态 = 取消状态列表,
				状态 = 更新状态列表
			}
		})
	end
end

function 战斗处理类:减少气血(编号, 数额, 攻击, 名称, 无视护盾, 流程, 攻击流程)
	if 攻击 ~= nil and self:取奇经八脉是否有(攻击, "致命") then
		self.参战单位[编号].致命 = 攻击
	end

	if 攻击 ~= nil and self.参战单位[编号].法术状态.同舟共济 ~= nil and self.参战单位[编号].法术状态.同舟共济.回合 > 0 and self.参战单位[编号].法术状态.同舟共济.层数 >= 1 then
		local bh = self.参战单位[编号].法术状态.同舟共济.攻击编号
		local 死亡 = self:减少气血(bh, 数额, nil, nil, nil, nil, 1)

		self:流程处理气血魔法(编号, {
			{
				气血类型 = 1,
				挨打方 = bh,
				死亡 = 死亡,
				气血 = 数额
			}
		})

		self.参战单位[编号].法术状态.同舟共济.层数 = self.参战单位[编号].法术状态.同舟共济.层数 - 1

		if self.参战单位[编号].法术状态.同舟共济.层数 < 1 then
			self:取消状态("同舟共济", self.参战单位[编号])
		end
	end

	if 攻击 ~= nil and 数额 >= self.参战单位[编号].最大气血 * 0.2 then
		if self:取奇经八脉是否有(编号, "烈焰") then
			if self.参战单位[编号].法术状态.炙烤 == nil then
				self:添加战斗流程提示("#P(烈焰)#R" .. self.参战单位[编号].名称 .. "#W进入了#S炙烤#W状态", 流程)
			end

			self:添加状态("炙烤", self.参战单位[编号])

			self.参战单位[编号].法术状态.炙烤.回合 = math.max(self.参战单位[编号].法术状态.炙烤.回合, 3)
		end

		if self:取奇经八脉是否有(编号, "蚀天") then
			if self.参战单位[编号].法术状态.蚀天 == nil then
				self:添加战斗流程提示("#P(蚀天)#R" .. self.参战单位[编号].名称 .. "#W进入了#S蚀天#W状态", 流程)
			end

			self:添加状态("蚀天", self.参战单位[编号])

			self.参战单位[编号].法术状态.蚀天.回合 = math.max(self.参战单位[编号].法术状态.蚀天.回合, 3)
		end
	end

	if self.参战单位[编号].法术状态.金蟾 ~= nil and 数额 > 0 then
		if 数额 < self.参战单位[编号].法术状态.金蟾.妖风傀儡 then
			self.参战单位[编号].法术状态.金蟾.妖风傀儡 = qz(self.参战单位[编号].法术状态.金蟾.妖风傀儡 - 数额)
		else
			local 金蟾境界 = self.参战单位[编号].法术状态.金蟾.境界 + 0

			self:取消状态("金蟾", self.参战单位[编号])
			self:金蟾回血(编号, 金蟾境界, 1, 流程)
		end
	end

	if 无视护盾 == nil and 数额 > 0 then
		local 护盾值 = self:取护盾值(编号)

		if 护盾值 > 0 then
			if 数额 < 护盾值 then
				self:扣除护盾(编号, 数额)

				数额 = 0

				return
			else
				数额 = 数额 - 护盾值

				self:扣除护盾(编号, 护盾值)
			end
		end
	end

	if self.参战单位[编号].凝光炼彩 ~= nil and ygsj() <= 25 and self.凝光炼彩护盾 == true and 数额 > 1 then
		local hd = qz1(数额 / 2)

		self:添加护盾(编号, hd, 编号)
		self:添加战斗流程提示("#P(凝光炼彩)#R" .. self.参战单位[编号].名称 .. "#W获得了#R" .. hd .. "#W点#Y护盾", 流程)
	end

	self.凝光炼彩护盾 = false
	self.参战单位[编号].气血 = self.参战单位[编号].气血 - 数额

	if self.参战单位[编号].气血 <= self.参战单位[编号].最大气血 * 0.2 then
		self:添加危险发言(编号, 2)
	end

	if self.参战单位[编号].气血 <= 0 and self.参战单位[编号].天狐之舞 ~= nil then
		self:取消所有状态(编号)

		self.参战单位[编号].气血 = qz(self.参战单位[编号].最大气血 * 0.2)
		self.参战单位[编号].天狐之舞 = nil

		self:添加状态("天狐之舞", self.参战单位[编号])
		self:流程处理全部状态({
			编号
		})

		self.战斗流程[#self.战斗流程 + 1] = {
			流程 = 707.3,
			名称 = self.参战单位[编号].名称,
			攻击方 = 编号,
			气血 = self.参战单位[编号].气血,
			挨打方 = {}
		}
	end

	if self.参战单位[编号].类型 == "角色" or self.参战单位[编号].类型 == "系统PK角色" then
		local 临时愤怒 = math.min(math.max(qz(数额 / self.参战单位[编号].最大气血 * 100), 1), 100)

		if self.参战单位[编号].超级暴怒腰带 ~= nil then
			临时愤怒 = qz(临时愤怒 * (1 + 超级暴怒效果))
		elseif self.参战单位[编号].暴怒腰带 ~= nil then
			临时愤怒 = qz(临时愤怒 * (1 + 暴怒效果))
		end

		if 临时愤怒 >= 10 and self:取奇经八脉是否有(编号, "怒气") then
			临时愤怒 = 临时愤怒 + 4
		end

		if 名称 == "紧箍咒" and self.参战单位[编号].法术状态.紧箍咒 ~= nil and self.参战单位[编号].法术状态.紧箍咒.默诵 ~= nil then
			临时愤怒 = 0
		end

		self:增加愤怒(编号, 临时愤怒)
	end

	if self.参战单位[编号].气血 <= 0 then
		self:添加危险发言(编号, 1)

		self.执行等待 = self.执行等待 + 5
		self.参战单位[编号].气血 = 0

		self:造成伤势(编号, 99999999)

		if self.战斗脚本 and self.战斗脚本.单位死亡 then
			__gge.safecall(self.战斗脚本.单位死亡, self, 编号)
		end

		if self.参战单位[编号].同门单位 then
			self.同门死亡 = true
		end

		if self.参战单位[编号].类型 == "角色" or self.参战单位[编号].类型 == "系统PK角色" or self.参战单位[编号].类型 == "系统角色" then
			self:设置复仇对象(编号, 攻击)

			self.参战单位[编号].死亡状态 = 2
			local 临时愤怒 = (self.参战单位[编号].愤怒 or 0) + 0

			if self.参战单位[编号].炽焰丹珠 ~= nil and (self.参战单位[编号].炽焰丹珠次数 or 0) < 3 then
				self.参战单位[编号].愤怒 = qz1(self.参战单位[编号].愤怒 * self.参战单位[编号].炽焰丹珠 / 100)
				self.参战单位[编号].炽焰丹珠次数 = (self.参战单位[编号].炽焰丹珠次数 or 0) + 1
			else
				self.参战单位[编号].愤怒 = 0
			end

			if self.参战单位[编号].舍利 ~= nil and self.参战单位[编号].舍利 < 1 then
				self.参战单位[编号].舍利 = self.参战单位[编号].舍利 + 1
				local 增加愤怒 = qz1((临时愤怒 - self.参战单位[编号].愤怒) * 0.65)

				for i = 1, #self.参战单位 do
					if self.参战单位[i].队伍 == self.参战单位[编号].队伍 and self.参战单位[i].愤怒 ~= nil and self.参战单位[i].愤怒 < 120 then
						self.参战单位[i].愤怒 = math.min(self.参战单位[i].愤怒 + 增加愤怒, 120)
					end
				end
			end

			if self.参战单位[编号].翡翠芝兰 ~= nil and (self.参战单位[编号].翡翠芝兰次数 or 0) < 3 then
