						bb[#bb + 1] = {
							魔法类型 = 2,
							挨打方 = 目标组[i],
							魔法 = 魔法
						}
					end

					self:流程处理气血魔法(编号, bb)

					for i = 1, #目标组 do
						self:增加魔法(目标组[i], 魔法)
					end

					self:添加战斗流程提示("#P(翡翠芝兰)#W#R" .. self.参战单位[编号].名称 .. "#W在倒地前为所有队友恢复了#R" .. 魔法 .. "点魔法", 流程)
				end

				self.参战单位[编号].翡翠芝兰次数 = (self.参战单位[编号].翡翠芝兰次数 or 0) + 1
			end

			if self.参战单位[编号].太虚玉液 ~= nil and (self.参战单位[编号].太虚玉液次数 or 0) < 3 then
