						self.参战单位[n].法术伤害结果 = self.参战单位[n].法术伤害结果 + self.参战单位[n].血债偿
					end
				end

				self.参战单位[编号].死亡状态 = 1
			elseif self.参战单位[编号].法术状态.复活 ~= nil and self.参战单位[编号].法术状态.复活.回合 ~= nil then
