			elseif self.参战单位[攻击].法术状态.灵断 ~= nil then
				self.参战单位[编号].死亡状态 = 1
			elseif 名称 == "五雷咒" or 名称 == "落雷符" then
				self.参战单位[编号].死亡状态 = 1
			elseif self:取符石组合效果(攻击, "风卷残云") and ygsj() <= self:取符石组合效果(攻击, "风卷残云") then
				self.参战单位[编号].死亡状态 = 1
			elseif 攻击 == nil then
				self.参战单位[编号].法术状态.复活 = {
					回合 = self.参战单位[编号].鬼魂
				}
				self.参战单位[编号].死亡状态 = 2
			elseif self.参战单位[攻击].驱鬼 ~= nil or self.参战单位[攻击].审判 ~= nil then
				self.参战单位[编号].死亡状态 = 1
			else
				self.参战单位[编号].法术状态.复活 = {
					回合 = self.参战单位[编号].鬼魂
				}
				self.参战单位[编号].死亡状态 = 2
			end

			if self.参战单位[编号].死亡状态 == 1 and 攻击 ~= nil and self.参战单位[攻击] ~= nil and self:取奇经八脉是否有(攻击, "霊能") then
				self.参战单位[攻击].霊能 = 1
			end
