			end
		elseif self.参战单位[编号].死亡状态 == 1 then
			if self.参战单位[编号].主人或助战 ~= nil and self.参战单位[编号].认证码 ~= nil and 玩家数据[self.参战单位[编号].玩家id] ~= nil then
				玩家数据[self.参战单位[编号].玩家id].召唤兽:死亡处理(self.参战单位[编号].认证码, self.参战单位[编号].玩家id)
			elseif self.战斗类型 == 100008.2 and self.参战单位[编号].队伍 == 0 then
