			if self:取奇经八脉是否有(攻击, "傲視") then
				self:添加状态("傲視", self.参战单位[攻击])

				self.参战单位[攻击].法术状态.傲視.造成物理伤害 = 30
			end

			if 名称 == "剑意莲心" and self:取奇经八脉是否有(攻击, "化用") and ygsj() <= 20 then
				self:刷新五行珠(攻击, self.参战单位[编号].攻击五行)
			end

			if self.参战单位[编号].死亡状态 == 2 and 名称 ~= nil and 五行物攻法术[名称] ~= nil and self:取奇经八脉是否有(攻击, "困兽") and self:取五行克制(五行物攻法术[名称], self.参战单位[编号].防御五行) then
				self:添加状态("困兽", self.参战单位[编号])
			end

			if self.参战单位[编号].类型 ~= "bb" and self.逞凶激活 ~= nil and self.逞凶激活[攻击] ~= nil then
				self.参战单位[攻击].逞凶 = 1.12
				self.参战单位[self.逞凶激活[攻击]].逞凶 = 1.12
			end

			if ygsj() <= 15 and self:取奇经八脉是否有(攻击, "宁息") and self.参战单位[攻击].法术状态.变身 ~= nil then
				self.参战单位[攻击].法术状态.变身.回合 = self.参战单位[攻击].法术状态.变身.回合 + 1

				self:添加战斗流程提示("#P(宁息)#R" .. self.参战单位[攻击].名称 .. "#W击倒了#R" .. self.参战单位[编号].名称 .. "#W变身状态延长#S1#W回合", 流程)
			end
		end

		if self:取奇经八脉是否有(编号, "复仇") and self.参战单位[编号].召唤兽 ~= nil and 攻击 ~= nil then
			local bb = self.参战单位[编号].召唤兽

			if bb ~= 攻击 and self:取目标状态(bb, 攻击, 1) and (self.参战单位[bb].复仇 or 0) < 3 then
				self:物攻技能计算(bb, "幼狮之搏", self:取技能等级(bb, "幼狮之搏"), {
					指定目标 = 攻击
				})

				self.参战单位[bb].复仇 = (self.参战单位[bb].复仇 or 0) + 1

				self:添加战斗流程提示("#P(复仇)#R" .. self.参战单位[bb].名称 .. "#W使用#S幼狮之搏#W对#R" .. self.参战单位[攻击].名称 .. "#W进行了#Y复仇", 流程)
			end
		end

		if self.参战单位[编号].气血 > 0 then
			print(编号 .. self.参战单位[编号].名称 .. "死了又还有血")

			self.参战单位[编号].死亡状态 = nil

			return
		end

		return self.参战单位[编号].死亡状态 + 0
	else
		self:流程更新气血魔法愤怒(编号, 1)

		return
	end
end

function 战斗处理类:设置复仇对象(编号, 攻击)
	local id = self.参战单位[编号].召唤兽

	if id == nil or id == 0 or self.参战单位[id] == nil then
		return
	elseif self.参战单位[id].复仇特性 ~= nil and ygsj(10) <= self.参战单位[id].复仇特性 * 20 then
		self.参战单位[id].复仇标记 = 攻击
	end
end

function 战斗处理类:取可否防御(挨打方)
	local 技能名称 = {
		"横扫千军",
		"催眠符",
		"楚楚可怜",
		"破釜沉舟"
	}

	for i = 1, #技能名称 do
		if self.参战单位[挨打方].法术状态[技能名称[i]] ~= nil then
			return false
		end
	end

	return true
end

function 战斗处理类:取最终物理伤害(攻击方, 挨打方, 伤害, 名称)
	local 特效 = {}
	local 动作 = "挨打"
	local 暴击 = nil

	if self.参战单位[挨打方].指令.类型 == "防御" then
		if self.参战单位[攻击方].指令.参数 == "壁垒击破" then
			伤害 = 伤害 * 1.5
		elseif self.参战单位[攻击方].指令.参数 == "超级壁垒击破" then
			伤害 = 伤害 * 2
		elseif self.参战单位[攻击方].超级偷袭 ~= nil then
			if self.参战单位[攻击方].指令.类型 ~= "攻击" then
				if 名称 == nil then
				end
			end
		elseif self.参战单位[攻击方].指令.参数 == "惊心一剑" then
		elseif self.参战单位[挨打方].超级防御 ~= nil then
			伤害 = 伤害 * 0.25
		else
			伤害 = 伤害 * 0.5
		end

		动作 = "防御"
		特效[#特效 + 1] = "防御"
	end

	local 必杀几率 = (self.临时属性[攻击方].必杀 or 0) + (self.参战单位[攻击方].必杀 or 基础暴击率) +
	(self.参战单位[攻击方].物理暴击等级 - self.参战单位[挨打方].抗物理暴击等级) * 0.1 + (self.参战单位[攻击方].千斗金樽暴击 or 0)

	if self.参战单位[攻击方].门派 == "凌波城" then
		必杀几率 = 必杀几率 + 1
	end

	if self:取奇经八脉是否有(攻击方, "静岳") and self.参战单位[攻击方].法术状态.护盾 ~= nil then
		必杀几率 = 必杀几率 + 4
	end

	if self:取奇经八脉是否有(攻击方, "念心") and (self.参战单位[挨打方].类型 == "角色" and self.参战单位[挨打方].玩家id ~= 0 and self.参战单位[挨打方 + 1] ~= nil and self.参战单位[挨打方 + 1].类型 == "bb" and (self.参战单位[挨打方 + 1].死亡状态 ~= nil or self.参战单位[挨打方 + 1].逃跑 == true) or self.参战单位[挨打方].玩家id == 0 and self.参战单位[挨打方].类型 ~= "bb") then
		必杀几率 = 必杀几率 + 12
	end

	if self:取奇经八脉是否有(攻击方, "执剑") and self.参战单位[攻击方].执剑 == nil and (self.同门派减伤[self.参战单位[攻击方].队伍].大唐官府 or 0) <= 1 then
		必杀几率 = 必杀几率 + 10
	end

	if self.参战单位[攻击方].特效会心 ~= nil then
		必杀几率 = 必杀几率 + self.参战单位[攻击方].特效会心
	end

	if self.参战单位[攻击方].法术状态.骤雨 ~= nil then
		local aa = 2

		if self:取奇经八脉是否有(攻击方, "滂沱") then
			aa = 5

			if qz(self.天气) == 2 then
				aa = aa * 1.4
			end
		end

		必杀几率 = 必杀几率 + aa * (self.参战单位[攻击方].法术状态.骤雨.层数 or 1)
	end

	if self.参战单位[攻击方].法术状态.还丹 ~= nil and self.参战单位[攻击方].法术状态.还丹.层数 >= 3 and 名称 == "敲金击玉" and self:取奇经八脉是否有(攻击方, "归真") then
		必杀几率 = 必杀几率 + 5
	elseif 名称 == "烟雨剑法" and self.参战单位[攻击方].雨杀 ~= nil then
		必杀几率 = 必杀几率 + 20
	elseif 名称 == "狮搏" and self:取奇经八脉是否有(攻击方, "展翅") and qz(self.天气) == 1 and self.参战单位[攻击方].法术状态.变身 ~= nil then
		必杀几率 = 必杀几率 + 10
	elseif 名称 == "六道无量" then
		if self.参战单位[攻击方].法术状态["噬毒·六道无量"] ~= nil then
			必杀几率 = 必杀几率 + 10
		end
	elseif 名称 == "浪涌" or 名称 == "惊涛怒" or 名称 == "翻江搅海" then
		if qz(self.天气) == 3 and self:取奇经八脉是否有(攻击方, "冰爆") then
			必杀几率 = 必杀几率 + 10
		end
	elseif 名称 == "裂石" or 名称 == "断岳势" or 名称 == "天崩地裂" then
		if self.参战单位[攻击方].吞山 ~= nil then
			必杀几率 = 必杀几率 + 5
		end

		if 名称 == "天崩地裂" and self:取奇经八脉是否有(攻击方, "无双") then
			必杀几率 = 必杀几率 + 12
		end
	elseif 名称 == "天神怒斩" then
		必杀几率 = 必杀几率 + 25
	elseif 名称 == "千蛛噬魂" and self:取奇经八脉是否有(攻击方, "狂击") then
		必杀几率 = 必杀几率 + 10
	end

	if self.参战单位[攻击方].法术状态.狂怒 ~= nil and self:取奇经八脉是否有(攻击方, "暴怒") then
		必杀几率 = 必杀几率 + 10
	end

	if 昼夜参数 == 1 and self:取奇经八脉是否有(攻击方, "夜之王者") then
		必杀几率 = 必杀几率 + 10
	end

	if self.参战单位[挨打方].法术状态.尸腐毒 ~= nil and self:取奇经八脉是否有(攻击方, "毒炽") then
		必杀几率 = 必杀几率 + 12
	end

	if self.参战单位[攻击方].消耗超级战意 ~= nil and 名称 ~= nil and self:取奇经八脉是否有(编号, "妙得") then
		必杀几率 = 必杀几率 + self.参战单位[编号].消耗超级战意 * (20 + (self.参战单位[编号].惊涛 or 0))
	end

	if self:取奇经八脉是否有(攻击方, "破击") then
		必杀几率 = 必杀几率 * 2
	end

	if 取随机数(1, 10000) <= 必杀几率 * 100 then
		if self.参战单位[攻击方].法术状态.镇魂诀 ~= nil and self:取奇经八脉是否有(攻击方, "巧变") then
			self:刷新战意(攻击方, 1, nil, nil, true)
		end

		local 物理暴伤最终倍率 = self.参战单位[攻击方].物理暴伤

		if 名称 == "生杀予夺" then
			local pd = false

			for k, v in pairs(self.参战单位[挨打方].法术状态) do
				if 毒状态列表1[k] ~= nil then
					pd = true

					break
				end
			end

			if pd then
				物理暴伤最终倍率 = 物理暴伤最终倍率 + 0.6
			end
		elseif 名称 == "魔神之刃" then
			物理暴伤最终倍率 = 物理暴伤最终倍率 + 1
		end

		if self.参战单位[攻击方].超级必杀 ~= nil and ygsj() <= 15 then
			物理暴伤最终倍率 = 物理暴伤最终倍率 + 1 + ygsj() / 100
		end

		if self.参战单位[攻击方].法术状态.狂怒 ~= nil and self:取奇经八脉是否有(攻击方, "暴怒") then
			物理暴伤最终倍率 = 物理暴伤最终倍率 + 0.2
		end

		if 名称 == "狮搏" and self:取奇经八脉是否有(攻击方, "展翅") and qz(self.天气) == 1 and self.参战单位[攻击方].法术状态.变身 ~= nil then
			物理暴伤最终倍率 = 物理暴伤最终倍率 + 0.2
		end

		if 攻击方 ~= nil and self:取奇经八脉是否有(攻击方, "杀意") then
			物理暴伤最终倍率 = 物理暴伤最终倍率 + 0.2
		end

		if self.参战单位[挨打方].逍遥游 ~= nil then
			物理暴伤最终倍率 = 物理暴伤最终倍率 - 0.5
		end

		if self:取奇经八脉是否有(挨打方, "神躯") then
			物理暴伤最终倍率 = 物理暴伤最终倍率 - 0.2
		end

		if self:取奇经八脉是否有(挨打方, "灵身") then
			物理暴伤最终倍率 = 物理暴伤最终倍率 - 0.4
		end

		if 名称 == "水击三千" then
			物理暴伤最终倍率 = 物理暴伤最终倍率 + 0.3
		end

		if self.参战单位[挨打方].幸运 ~= nil then
			物理暴伤最终倍率 = 物理暴伤最终倍率 - (1 - self.参战单位[挨打方].幸运)
		end

		if self.参战单位[攻击方].特效猛击 ~= nil then
			物理暴伤最终倍率 = 物理暴伤最终倍率 + self.参战单位[攻击方].特效猛击 / 100
		end

		if self:取奇经八脉是否有(攻击方, "破击") then
			物理暴伤最终倍率 = 1 + (物理暴伤最终倍率 - 1) * 0.65
		end

		if self.参战单位[攻击方].凭风借力 ~= nil then
			物理暴伤最终倍率 = 物理暴伤最终倍率 * self.参战单位[攻击方].凭风借力
			self.参战单位[攻击方].凭风借力 = 1
		end

		伤害 = qz(伤害 * 物理暴伤最终倍率)
		特效[#特效 + 1] = "暴击"
		暴击 = true

		if self.参战单位[攻击方].狂怒 ~= nil then
			伤害 = 伤害 + self.参战单位[攻击方].狂怒
		end
	end

	if self.参战单位[攻击方].无畏 ~= nil and self.参战单位[挨打方].反震 ~= nil then
		伤害 = 伤害 * self.参战单位[攻击方].无畏
	end

	if self.参战单位[攻击方].愤恨 ~= nil and self.参战单位[挨打方].幸运 ~= nil then
		伤害 = 伤害 * self.参战单位[攻击方].愤恨
	end

	--遭受物理攻击有5%几率 伤害降低15% / 20% / 25% / 30%
	-- if self:取符石组合效果(挨打方, "点石成金") and ygsj() <= 5 then
		-- 伤害 = qz(伤害 * (100 - self:取符石组合效果(挨打方, "点石成金")) / 100)
		-- 动作 = "防御"
		-- 特效[#特效 + 1] = "点石成金"
	-- end
	--强化：遭受物理攻击有20%几率 伤害降低15% / 20% / 25% / 30%
	if self:取符石组合效果(挨打方, "点石成金") and self:取点石成金触发概率(挨打方) then
		local 点石成金效果 = self:取符石组合效果(挨打方, "点石成金")
		local 点石成金触发概率 = self:取点石成金触发概率(挨打方)
		if ygsj() <= 点石成金触发概率 then
			伤害 = qz(伤害 * (100 - 点石成金效果) / 100)
			动作 = "防御"
			特效[#特效 + 1] = "点石成金"
			-- 常规提示(19681, "点石成金触发了，降低了" .. 点石成金效果 .. "%的伤害" .. "，触发概率为" .. 点石成金触发概率 .. "%")
		end
	end

	if self.参战单位[挨打方].法术状态.天地同寿 ~= nil then
		伤害 = 伤害 * 2
	end

	if self.参战单位[挨打方].玉砥柱 ~= nil and (玉砥柱技能列表[self.参战单位[攻击方].指令.参数] ~= nil or 物攻群法技能列表[self.参战单位[攻击方].指令.参数] ~= nil) then
		伤害 = 伤害 * (1 - self.参战单位[挨打方].玉砥柱)
	end

	if 名称 ~= "杀威铁棒" and self:法宝判断("金甲仙衣", 挨打方) ~= false then
		local 法宝名称 = "金甲仙衣"

		for i = 1, #self.参战单位[挨打方].法宝列表[法宝名称] do
			local 法宝位置 = self.参战单位[挨打方].法宝列表[法宝名称][i]
			local 境界 = self:法宝概率判断(法宝名称, 挨打方, 法宝位置, 1, 1)

			if 境界 ~= false then
				local 减伤效果 = 0.9 - 境界 * 0.05
				伤害 = qz(伤害 * 减伤效果)
				特效[#特效 + 1] = "金甲仙衣"
			end
		end
	end

	if 名称 ~= "杀威铁棒" and self:法宝判断("蟠龙玉璧", 挨打方) ~= false then
		local 法宝名称 = "蟠龙玉璧"

		for i = 1, #self.参战单位[挨打方].法宝列表[法宝名称] do
			local 法宝位置 = self.参战单位[挨打方].法宝列表[法宝名称][i]
			local 境界 = self:法宝概率判断(法宝名称, 挨打方, 法宝位置, 1)

			if 境界 ~= false then
				local 减伤效果 = 1 - (境界 * 0.015 + 0.13)
				伤害 = qz(伤害 * 减伤效果)
				特效[#特效 + 1] = "金甲仙衣"
			end
		end
	end

	if 名称 ~= "杀威铁棒" and self:法宝判断("澄空净铃", 挨打方) ~= false then
		local 法宝名称 = "澄空净铃"

		for i = 1, #self.参战单位[挨打方].法宝列表[法宝名称] do
			local 法宝位置 = self.参战单位[挨打方].法宝列表[法宝名称][i]
			local 境界 = self:法宝概率判断(法宝名称, 挨打方, 法宝位置, 1)

			if 境界 ~= false then
				local 减伤效果 = 1 - (境界 * 0.015 + 0.03)

				if self.天气 == 0 then
					减伤效果 = 1 - (境界 * 0.025 + 0.1)
				end

				伤害 = qz(伤害 * 减伤效果)
				特效[#特效 + 1] = "金甲仙衣"
			end
		end
	end

	if self:取符石组合效果(挨打方, "暗渡陈仓") then
		伤害 = 伤害 * (1 - self:取符石组合效果(挨打方, "暗渡陈仓") / 100)
	end

	if self.参战单位[挨打方].类型 == "bb" and self.参战单位[挨打方].内丹 ~= nil then
		local 内丹1 = {}

		for n = 1, #self.参战单位[挨打方].内丹 do
			内丹1[n] = self.参战单位[挨打方].内丹[n]
		end

		for i = 1, #内丹1 do
			local 等级 = 内丹1[i].等级
			local 技能 = 内丹1[i].技能

			if 技能 == "腾挪劲" then
				local 触发几率 = 等级 * 4

				if ygsj() <= 触发几率 then
					伤害 = qz(伤害 * 0.5)
					特效[#特效 + 1] = "腾挪劲"
				end
			elseif 技能 == "灵身" then
				伤害 = qz(伤害 * 1.5)
			end
		end
	end

	if self.参战单位[攻击方] ~= nil and self.参战单位[攻击方].类型 == "角色" and self.参战单位[攻击方].玩家id ~= 0 then
		local 消耗 = 1

		if 名称 == "百爪狂杀" and self:取奇经八脉是否有(攻击方, "百炼") then
			消耗 = 消耗 * 0.5
		elseif 名称 ~= nil and 九黎城攻击技能[名称] ~= nil then
			消耗 = 消耗 * 0.2
		end

		self.参战单位[攻击方].攻击耐久 = (self.参战单位[攻击方].攻击耐久 or 0) + 消耗
	end

	if self.参战单位[挨打方] ~= nil and self.参战单位[挨打方].类型 == "角色" and self.参战单位[挨打方].玩家id ~= 0 and self.参战单位[挨打方].玩家id ~= 0 then
		self.参战单位[挨打方].防御耐久 = (self.参战单位[攻击方].防御耐久 or 0) + 1
	end

	if self.参战单位[挨打方] ~= nil and self.参战单位[挨打方].玩家id ~= 0 and self.参战单位[挨打方].玩家id ~= 0 and self.参战单位[挨打方].类型 == "bb" and self.参战单位[挨打方].认证码 ~= nil then
		self.参战单位[挨打方].bb耐久 = (self.参战单位[挨打方].bb耐久 or 0) + 1
	end

	if 暴击 then
		return {
			类型 = 3,
			伤害 = qz(伤害),
			动作 = 动作,
			特效 = 特效,
			暴击 = 暴击
		}
	else
		return {
			类型 = 1,
			伤害 = qz(伤害),
			动作 = 动作,
			特效 = 特效,
			暴击 = 暴击
		}
	end
end

function 战斗处理类:取灵力伤害(攻击方, 挨打方, 增幅, 名称)
	local 防御基数 = 1
	local 结果加成 = 1

	if 攻击方.法术修炼 == nil then
		攻击方.法术修炼 = 0
	end

	if 挨打方.抗法修炼 == nil then
		挨打方.抗法修炼 = 0
	end

	local 修炼差 = 攻击方.法术修炼 - 挨打方.抗法修炼
	local 等级差 = 攻击方.等级 - 挨打方.等级
	local ls = 0

	if 攻击方.法伤 == nil then
		攻击方.法伤 = 攻击方.灵力 + (攻击方.灵伤差 or 0)
	end

	if 攻击方.法防 == nil then
		攻击方.法防 = 攻击方.灵力
	end

	if 挨打方.法伤 == nil then
		挨打方.法伤 = 挨打方.灵力 + (挨打方.灵伤差 or 0)
	end

	if 挨打方.法防 == nil then
		挨打方.法防 = 挨打方.法防
	end

	local lsll = 0

	if 攻击方.指令.参数 == "魔火焚世" then
		lsll = 攻击方.法伤 * 0.2
	end

	local 法防 = 挨打方.法防 + 0

	if 攻击方.法穿 ~= nil then
		self.忽视防御 = self.忽视防御 - 攻击方.法穿 / 100
	end

	if 攻击方.汹涌 ~= nil then
		增幅 = (增幅 or 0) + 攻击方.法伤 * 0.08
		self.忽视防御 = self.忽视防御 - 0.08
	end

	if 名称 == "龙腾" then
		if 攻击方.惊鸿 ~= nil then
			增幅 = (增幅 or 0) + 攻击方.法伤 * 0.06
			self.忽视防御 = self.忽视防御 - 0.12
		end
	elseif 攻击方.琴魂 ~= nil and string.find(名称, "琴音三叠") then
		增幅 = (增幅 or 0) + 攻击方.法伤 * 0.1
		self.忽视防御 = self.忽视防御 - 0.1
	end

	if 攻击方.通天降兽 ~= nil and self:取是否召唤兽(挨打方.战斗编号) then
		结果加成 = 结果加成 * 1.15

		if 名称 == "棍打诸神" then
			self.忽视防御 = self.忽视防御 - 0.2
			结果加成 = 结果加成 * 1.2
		end
	end

	if 法防 > 0 then
		法防 = 法防 * self.忽视防御
	end

	法防 = math.max(法防, 0)
	local 波动值 = 0

	if 攻击方.法伤 >= 50 then
		波动值 = -30 + ygsj(60)
	end

	if 攻击方.类型 == "角色" then
		伤害 = (攻击方.法伤 + lsll + (增幅 or 0) - 法防 * 防御基数 + 波动值) * (1 + 修炼差 * 0.02) * 1.33 + 修炼差 * 5 + 等级差 * 3
	else
		伤害 = (攻击方.法伤 + lsll + (增幅 or 0) - 法防 * 防御基数 + 波动值) * (1 + 修炼差 * 0.02) * 1.33 + 修炼差 * 5 + 等级差 * 3
	end

	self.忽视防御 = 1

	return qz1(math.max(伤害 * 结果加成, 1))
end

function 战斗处理类:取基础物理伤害(攻击方, 挨打方, 名称)
	local 结果加成 = 1

	if self.参战单位[攻击方].攻击修炼 == nil then
		self.参战单位[攻击方].攻击修炼 = 0
	end

	if self.参战单位[挨打方].防御修炼 == nil then
		self.参战单位[挨打方].防御修炼 = 0
	end

	local 修炼差 = self.参战单位[攻击方].攻击修炼 - self.参战单位[挨打方].防御修炼
	local 等级差 = self.参战单位[攻击方].等级 - self.参战单位[挨打方].等级
	local 防御 = self.参战单位[挨打方].防御 + self.参战单位[挨打方].防御修炼 * 5

	if self:法宝判断("七杀", 攻击方) ~= false then
		local 法宝名称 = "七杀"

		for i = 1, #self.参战单位[攻击方].法宝列表[法宝名称] do
			local 法宝位置 = self.参战单位[攻击方].法宝列表[法宝名称][i]
			local 境界 = self:法宝概率判断(法宝名称, 攻击方, 法宝位置, 1, 1)

			if 境界 ~= false then
				防御 = 防御 - math.max(qz(self.参战单位[攻击方].等级 * 境界 * 0.08), 0)
			end
		end
	end

	if self.参战单位[攻击方].凭风借力 ~= nil then
		self.参战单位[攻击方].凭风借力 = math.max(self.参战单位[攻击方].凭风借力 + 0.125, 1.5)
	end

	if self.参战单位[攻击方].类型 == "bb" and self:法宝判断("失心钹", 攻击方) ~= false then
		local 法宝名称 = "失心钹"

		for i = 1, #self.参战单位[攻击方].法宝列表[法宝名称] do
			local 法宝位置 = self.参战单位[攻击方].法宝列表[法宝名称][i]
			local 境界 = self:法宝概率判断(法宝名称, 攻击方, 法宝位置, 1, 1)

			if 境界 ~= false then
				防御 = 防御 - math.max(qz(self.参战单位[攻击方].等级 * 境界 * 0.08), 0)
			end
		end
	end

	if self.参战单位[攻击方].焚天陨火 ~= nil then
		self.参战单位[攻击方].焚天陨火 = self.参战单位[攻击方].焚天陨火 + 1

		while self.参战单位[攻击方].焚天陨火 >= 3 do
			self.参战单位[攻击方].焚天陨火 = self.参战单位[攻击方].焚天陨火 - 3

			self:法攻技能计算(攻击方, "焚天陨火", self.参战单位[攻击方].等级, 1)
		end
	end

	if 攻击方 ~= nil and self:取奇经八脉是否有(攻击方, "目空") then
		防御 = 防御 - self.参战单位[挨打方].防御 * 0.1
	end

	if self.参战单位[攻击方].狂暴等级 ~= nil then
		self.参战单位[攻击方].狂暴概率 = (self.参战单位[攻击方].狂暴概率 or 0) + self.参战单位[攻击方].狂暴等级 / 10
	end

	if self.参战单位[攻击方].狂暴概率 ~= nil and 取随机数(1, 10000) <= self.参战单位[攻击方].狂暴概率 * 100 then
		self:添加状态("狂暴", self.参战单位[攻击方])
		self:添加战斗流程提示("#P(狂暴)#R" .. self.参战单位[攻击方].名称 .. "#Y进入了#R狂暴#Y状态(持续到本回合结束)")
	end

	if self.参战单位[攻击方].法术状态.生命之泉 ~= nil and self.参战单位[攻击方].法术状态.炼气化神 and self:取奇经八脉是否有(攻击方, "无极") then
		self.参战单位[攻击方].临时增伤 = (self.参战单位[攻击方].临时增伤 or 0) + self.参战单位[攻击方].伤害 * 0.09
	end

	if self.参战单位[攻击方].气血 >= self.参战单位[攻击方].最大气血 * 0.7 and self:取奇经八脉是否有(攻击方, "混元", {
			万寿真仙 = 1,
			乾坤力士 = 1
		}) then
		self.参战单位[攻击方].临时增伤 = (self.参战单位[攻击方].临时增伤 or 0) + self.参战单位[攻击方].伤害 * 0.05
	end

	if self:取奇经八脉是否有(攻击方, "凝神") and self.参战单位[攻击方].法术状态.还丹 ~= nil then
		self.参战单位[攻击方].临时增伤 = (self.参战单位[攻击方].临时增伤 or 0) + 120
	end

	if self:取奇经八脉是否有(攻击方, "凌弱") and self:取目标异常状态数量(挨打方) >= 2 then
		self.参战单位[攻击方].临时增伤 = (self.参战单位[攻击方].临时增伤 or 0) + 80
	end

	if self.参战单位[攻击方].怒意 ~= nil and (self.参战单位[攻击方].战意 or 0) > 0 then
		self.参战单位[攻击方].临时增伤 = (self.参战单位[攻击方].临时增伤 or 0) + self.参战单位[攻击方].战意 * self.参战单位[攻击方].战意 * 12
	end

	if self.参战单位[攻击方].煞气 ~= nil and 名称 ~= nil then
		self.参战单位[攻击方].临时增伤 = (self.参战单位[攻击方].临时增伤 or 0) + 150
	end

	if 名称 == "剑意莲心" and self:取奇经八脉是否有(攻击方, "莲华") then
		self.参战单位[攻击方].临时增伤 = (self.参战单位[攻击方].临时增伤 or 0) + 160
	elseif 名称 == "六道无量" and self:取奇经八脉是否有(攻击方, "六道") then
		self.参战单位[攻击方].临时增伤 = (self.参战单位[攻击方].临时增伤 or 0) + (self.参战单位[攻击方].被动技能.六道轮回 or 0) * 2
	elseif 名称 == "百爪狂杀" and self:取奇经八脉是否有(攻击方, "百炼") and self.参战单位[攻击方].装备属性 ~= nil and self.参战单位[攻击方].装备属性.命中 ~= nil then
		self.参战单位[攻击方].临时增伤 = (self.参战单位[攻击方].临时增伤 or 0) + qz1(self.参战单位[攻击方].装备属性.命中 * 0.4 / 3)
	end

	if self.参战单位[攻击方].死地 ~= nil and 名称 == "鹰击" then
		self.参战单位[攻击方].临时增伤 = (self.参战单位[攻击方].临时增伤 or 0) + self.参战单位[攻击方].死地
	end

	if self.参战单位[攻击方].压邪 ~= nil and (self.参战单位[攻击方].连续神通 or 0) >= 3 then
		self.参战单位[攻击方].临时增伤 = (self.参战单位[攻击方].临时增伤 or 0) + self.参战单位[攻击方].等级 * 1.5
	end

	local 伤害 = self.参战单位[攻击方].伤害 + (self.参战单位[攻击方].临时增伤 or 0)

	if self:取符石组合效果(攻击方, "天降大任") and self.参战单位[挨打方].类型 == "bb" then
		防御 = qz(防御 * (1 - self:取符石组合效果(攻击方, "天降大任") / 100))
	end

	local 伤害补偿 = 0

	if self.参战单位[攻击方].力破特性 ~= nil then
		if self.参战单位[挨打方].类型 == "角色" then
			防御 = 防御 - (self.参战单位[攻击方].力破特性 * 40 + 40)

			if 防御 <= 0 then
				防御 = 0
			end
		else
			防御 = 防御 * 1.05
		end
	end

	if self.参战单位[攻击方].穿刺等级 ~= nil and self.参战单位[攻击方].穿刺等级 > 0 then
		防御 = math.floor(防御 *
		math.max(0.5 - math.max(self.参战单位[攻击方].穿刺等级 - 1000, 0) / 10000, 0) ^
		(self.参战单位[攻击方].穿刺等级 / (1000 + math.max(self.参战单位[攻击方].穿刺等级 - 1000, 0))))
	end

	if self.参战单位[挨打方].法术状态.天地同寿 ~= nil and self.参战单位[挨打方].法术状态.天地同寿.同辉 ~= nil and self.参战单位[攻击方].类型 == "角色" and self.参战单位[攻击方].玩家id ~= 0 then
		self.忽视防御 = self.忽视防御 - 0.3
	end

	if self.参战单位[攻击方].物穿 ~= nil then
		self.忽视防御 = self.忽视防御 - self.参战单位[攻击方].物穿 / 100
	end

	if self.参战单位[攻击方].不动 ~= nil then
		self.忽视防御 = self.忽视防御 - (1 - self.参战单位[攻击方].气血 / self.参战单位[攻击方].最大气血) / 10
	end

	if 名称 == "破血狂攻" and self:取奇经八脉是否有(攻击方, "怒目") then
		self.忽视防御 = self.忽视防御 - 0.1
	elseif 名称 == "浪涌" or 名称 == "惊涛怒" or 名称 == "翻江搅海" then
		if self.参战单位[攻击方].饮海 ~= nil then
			self.忽视防御 = self.忽视防御 - self.参战单位[攻击方].饮海 / 100
		end
	elseif 名称 == "裂石" or 名称 == "断岳势" or 名称 == "天崩地裂" then
		if qz(self.天气) == 2 and self:取奇经八脉是否有(攻击方, "砥石") then
			self.忽视防御 = self.忽视防御 - 0.1
		end

		if 名称 == "天崩地裂" and self:取奇经八脉是否有(攻击方, "力战") then
			self.忽视防御 = self.忽视防御 - 0.12
		end
	elseif 名称 == "天神怒斩" then
		self.忽视防御 = self.忽视防御 - 0.25
	elseif 名称 == "风雷斩·霹雳" and self.参战单位[攻击方].霹雳洞察 ~= nil and self.参战单位[攻击方].霹雳洞察[挨打方] ~= nil then
		self.忽视防御 = self.忽视防御 - 0.12
	end

	if self.参战单位[攻击方].降兽 ~= nil and self:取是否召唤兽(挨打方) then
		结果加成 = 结果加成 * 1.15

		if 名称 == "杀威铁棒" or 名称 == "棒打雄风" then
			self.忽视防御 = self.忽视防御 - 0.2
			结果加成 = 结果加成 * 1.2
		end
	end

	if 防御 > 0 then
		防御 = 防御 * math.max(self.忽视防御, 0)
	end

	local 伤害力 = math.min(伤害 - 防御, 伤害)
	local 结果 = (伤害力 * (1 + 修炼差 * 0.02) * 1.2 + 修炼差 * 5 + 等级差 * 3) * 结果加成

	if self.参战单位[攻击方].争锋特性 ~= nil then
		if self.参战单位[挨打方].类型 == "bb" then
			结果 = 结果 * (self.参战单位[攻击方].争锋特性 * 0.04 + 1)
		else
			结果 = 结果 * 0.9
		end
	end

	if 昼夜参数 == 1 and self.参战单位[攻击方].夜战 == nil and self.参战单位[攻击方].门派 ~= "阴曹地府" and self.参战单位[攻击方].高级勇敢 == nil and self.参战单位[攻击方].昼伏夜出 == nil then
		结果 = 结果 * 0.8
	end

	self.参战单位[攻击方].临时增伤 = nil
	self.忽视防御 = 1

	return qz(math.max(结果, 1))
end

function 战斗处理类:取抗法特性(队伍)
	if 队伍 == 0 then
		return 1
	end

	local 基础抗性 = 1

	for n = 1, #self.参战单位 do
		if self.参战单位[n].抗法特性 ~= nil then
			local 基础 = 3 + self.参战单位[n].特性几率 * 5
			基础 = 1 - 基础 / 100

			if 基础抗性 > 基础 then
				基础抗性 = 基础
			end
		end
	end

	return 基础抗性
end

function 战斗处理类:取抗物特性(队伍)
	if 队伍 == 0 then
		return 1
	end

	local 基础抗性 = 1

	for n = 1, #self.参战单位 do
		if self.参战单位[n].抗物特性 ~= nil then
			local 基础 = 3 + self.参战单位[n].抗物特性 * 5
			基础 = 1 - 基础 / 100

			if 基础抗性 > 基础 then
				基础抗性 = 基础
			end
		end
	end

	return 基础抗性
end

function 战斗处理类:取单个敌方可封印目标(编号)
	local 目标组 = {}

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 ~= self.参战单位[编号].队伍 and self:取目标状态(编号, n, 1) and self:取封印状态(n) == false then
			目标组[#目标组 + 1] = n
		end
	end

	if #目标组 == 0 then
		return 0
	else
		return 目标组[ygsj(#目标组)]
	end
end

function 战斗处理类:取敌方拥有指定状态人数(编号, 状态, 附加, 结算模式)
	local 数量 = 0

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 ~= self.参战单位[编号].队伍 and self.参战单位[n].法术状态[状态] ~= nil then
			local pd = true

			if 结算模式 ~= nil and 编号 < n and self.参战单位[n].法术状态[状态].回合 <= 1 then
				pd = false
			end

			if pd then
				if 附加 == nil then
					数量 = 数量 + 1
				elseif self.参战单位[n].法术状态[状态][附加] ~= nil then
					数量 = 数量 + 1
				end
			end
		end
	end

	return 数量
end

function 战斗处理类:取我方拥有指定状态人数(编号, 状态, 附加, 结算模式)
	local 数量 = 0

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 == self.参战单位[编号].队伍 and self.参战单位[n].法术状态[状态] ~= nil then
			local pd = true

			if 结算模式 ~= nil and 编号 < n and self.参战单位[n].法术状态[状态].回合 <= 1 then
				pd = false
			end

			if pd then
				if 附加 == nil then
					数量 = 数量 + 1
				elseif self.参战单位[n].法术状态[状态][附加] ~= nil then
					数量 = 数量 + 1
				end
			end
		end
	end

	return 数量
end

