	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 ~= self.参战单位[编号].队伍 and self.参战单位[n].气血 > 0 and self.参战单位[n].逃跑 ~= true then
			return false
		end
	end

	return true
end

function 战斗处理类:取单个敌方指定目标(编号, 指定属性, 最大最小)
	local 目标组 = {}

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 ~= self.参战单位[编号].队伍 and self:取目标状态(编号, n, 1) then
			if #目标组 == 0 then
				目标组[#目标组 + 1] = n
			elseif 最大最小 == "最大" then
				if (self.参战单位[n][指定属性] or 0) > (self.参战单位[目标组[1]][指定属性] or 0) then
					目标组[1] = n + 0
				end
			elseif 最大最小 == "最小" and (self.参战单位[n][指定属性] or 0) < (self.参战单位[目标组[1]][指定属性] or 0) then
				目标组[1] = n + 0
			end
		end
	end

	if #目标组 == 0 then
		return 0
	else
		return 目标组[1]
	end
end

function 战斗处理类:取单个敌方目标(编号, 指定目标, 排除目标)
	local 目标组 = {}
	local 隐身目标 = {}

	if 指定目标 ~= nil and self.参战单位[指定目标] ~= nil and self.参战单位[指定目标].队伍 ~= self.参战单位[编号].队伍 and self:取目标状态(编号, 指定目标, 1) then
		return 指定目标
	end

	local 排除 = {}

	if 排除目标 ~= nil then
		if type(排除目标) == "table" then
			for i = 1, #排除目标 do
				排除[排除目标[i]] = 1
			end
		else
			排除[排除目标] = 1
		end
	end

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 ~= self.参战单位[编号].队伍 and self:取目标状态(编号, n, 1) and 排除[n] == nil then
			目标组[#目标组 + 1] = n

			if self.参战单位[n].法术状态 ~= nil and self.参战单位[n].法术状态.修罗隐身 ~= nil then
				隐身目标[#隐身目标 + 1] = n
			end
		end
	end

	if #目标组 == 0 then
		return 0
	else
		if #隐身目标 > 0 and ygsj() >= 50 then
			return 隐身目标[ygsj(#隐身目标)]
		end

		return 目标组[ygsj(#目标组)]
	end
end

