	local 目标组 = {}

	for n = 1, #self.参战单位 do
		local aa = true

		if 不包含自己 ~= nil and n == 编号 then
			aa = false
		elseif 类型 ~= nil and self.参战单位[n].类型 ~= 类型 then
			aa = false
		elseif 对象 == 1 and self.参战单位[n].队伍 == self.参战单位[编号].队伍 then
			aa = false
		elseif (对象 or 0) == 0 and self.参战单位[n].队伍 ~= self.参战单位[编号].队伍 then
			aa = false
		end

		if aa and self:取目标状态(编号, n, 2) then
			目标组[#目标组 + 1] = n
		end
	end

	if #目标组 == 0 then
		return 0
	else
		return 目标组
	end
end

function 战斗处理类:取目标状态(攻击, 挨打, 类型)
	if self.参战单位[攻击] == nil or self.参战单位[攻击].捕捉 or self.参战单位[攻击].逃跑 or self.参战单位[攻击].死亡状态 == 1 then
		return false
	end

	if self.参战单位[挨打] == nil then
		return false
	end

	if 类型 == 1 then
		if self.参战单位[挨打].气血 <= 0 or self.参战单位[挨打].捕捉 or self.参战单位[挨打].逃跑 then
			return false
		elseif self.参战单位[挨打].法术状态.修罗隐身 ~= nil and self.参战单位[攻击].法术状态.幽冥鬼眼 == nil and self.参战单位[攻击].感知 == nil and (self.参战单位[攻击].牛劲感知 == nil or self.参战单位[攻击].法术状态.牛劲 == nil) and self.参战单位[攻击].法术状态.感知 == nil then
			return false
		elseif self.参战单位[挨打].法术状态.煞气诀 ~= nil then
			return false
		elseif self.参战单位[挨打].气血 <= 0 or self.参战单位[挨打].捕捉 or self.参战单位[挨打].逃跑 then
			return false
		elseif self.参战单位[挨打].法术状态.楚楚可怜 ~= nil and self.参战单位[攻击].感知 == nil then
			return false
		elseif self.参战单位[挨打].法术状态.修罗隐身 ~= nil and self.参战单位[攻击].法术状态.幽冥鬼眼 == nil and self.参战单位[攻击].感知 == nil and (self.参战单位[攻击].牛劲感知 == nil or self.参战单位[攻击].法术状态.牛劲 == nil) and self.参战单位[攻击].法术状态.感知 == nil then
			return false
		elseif self.参战单位[挨打].法术状态.煞气诀 ~= nil then
			return false
		end
	elseif 类型 == 2 then
		if self.参战单位[挨打].气血 <= 0 or self.参战单位[挨打].捕捉 or self.参战单位[挨打].逃跑 or self.参战单位[挨打].死亡状态 == 1 or self.参战单位[挨打].死亡状态 == 2 then
			return false
		end
	elseif 类型 == 3 and self.参战单位[挨打].气血 <= 0 then
		return false
	end

	return true
end

function 战斗处理类:取目标状态1(攻击, 挨打, 类型)
	if self.参战单位[挨打] == nil or self.参战单位[挨打].法术状态 == nil then
		return false
	end

	if 类型 == 1 then
		if self.参战单位[挨打].气血 <= 0 or self.参战单位[挨打].捕捉 or self.参战单位[挨打].逃跑 then
			return false
		elseif self.参战单位[挨打].法术状态.无魂傀儡 ~= nil or self.参战单位[挨打].法术状态.发瘟匣 ~= nil or self.参战单位[挨打].法术状态.断线木偶 ~= nil or self.参战单位[挨打].法术状态.摄魂 ~= nil or self.参战单位[挨打].法术状态.无尘扇 ~= nil or self.参战单位[挨打].法术状态.无字经 ~= nil or self.参战单位[挨打].法术状态.番天印 ~= nil or self.参战单位[挨打].法术状态.尸腐毒 ~= nil or self.参战单位[挨打].法术状态["尸腐毒 "] ~= nil then
			return true
		end
	end

	return false
end

function 战斗处理类:立即发言(编号, 内容)
	for n = 1, #self.参战玩家 do
		发送数据(self.参战玩家[n].连接id, 5512, {
			id = 编号,
			文本 = 内容
		})
	end
end

function 战斗处理类:发送天气数据()
	for w = 1, #self.参战玩家 do
		发送数据(self.参战玩家[w].连接id, 5501.1, {
			天气 = self.天气
		})
	end

	for i, v in pairs(self.观战玩家) do
		if 玩家数据[i] ~= nil then
			发送数据(玩家数据[i].连接id, 5501.1, {
				天气 = self.天气
			})
		end
	end
end

