function 战斗处理类:设置命令回合()
	self.回合数 = self.回合数 + 1

	if self.回合数 % 8 == 0 then
		local aa = qz(self.天气 + 0)

		while qz(self.天气) == aa do
			self.天气 = ygsj(4) - 1

			if self.天气 ~= 0 and ygsj() <= 50 then
				self.天气 = self.天气 + 0.5
			end
		end

		for n = 1, #self.参战单位 do
			if self.参战单位[n].万古坚冰 ~= nil then
				self.参战单位[n].速度 = self.参战单位[n].速度 - self.参战单位[n].万古坚冰[1]
				local 境界 = self.参战单位[n].万古坚冰[2]
				local sd = self:取万古坚冰速度(境界)
				self.参战单位[n].速度 = self.参战单位[n].速度 + sd
				self.参战单位[n].万古坚冰[1] = sd + 0
			end

			if self.参战单位[n].九霄灵息 ~= nil then
				self.参战单位[n].法伤 = self.参战单位[n].法伤 - self.参战单位[n].九霄灵息[1]
				local 境界 = self.参战单位[n].九霄灵息[2]
				local sd = self:取九霄灵息法伤(境界)
				self.参战单位[n].法伤 = self.参战单位[n].法伤 + sd
				self.参战单位[n].九霄灵息[1] = sd + 0
			end

			if self.参战单位[n].驱风宝诰 ~= nil then
				self.参战单位[n].法伤 = self.参战单位[n].法伤 - self.参战单位[n].驱风宝诰[1]
				local 境界 = self.参战单位[n].驱风宝诰[2]
				local sd = self:取驱风宝诰法伤(境界)
				self.参战单位[n].法伤 = self.参战单位[n].法伤 + sd
				self.参战单位[n].驱风宝诰[1] = sd + 0
			end

			if self.参战单位[n].狂飙天爪 ~= nil then
				self.参战单位[n].伤害 = self.参战单位[n].伤害 - self.参战单位[n].狂飙天爪[1]
				local 境界 = self.参战单位[n].狂飙天爪[2]
				local sd = self:取狂飙天爪伤害(境界)
				self.参战单位[n].伤害 = self.参战单位[n].伤害 + sd
				self.参战单位[n].狂飙天爪[1] = sd + 0
			end

			if self.参战单位[n].止风神剑 ~= nil then
				self.参战单位[n].伤害 = self.参战单位[n].伤害 - self.参战单位[n].止风神剑[1]
				local 境界 = self.参战单位[n].止风神剑[2]
				local sd = self:取止风神剑伤害(境界)
				self.参战单位[n].伤害 = self.参战单位[n].伤害 + sd
				self.参战单位[n].止风神剑[1] = sd + 0
			end

			if self.参战单位[n].初诞春芽 ~= nil then
				self.参战单位[n].治疗能力 = self.参战单位[n].治疗能力 - self.参战单位[n].初诞春芽[1]
				local 境界 = self.参战单位[n].初诞春芽[2]
				local sd = self:取初诞春芽治疗能力(境界)
				self.参战单位[n].治疗能力 = self.参战单位[n].治疗能力 + sd
				self.参战单位[n].初诞春芽[1] = sd + 0
			end
		end

		if qz(self.天气) == 1 then
			for n = 1, #self.参战单位 do
				if self.参战单位[n].法术状态.瘴气 ~= nil and self.参战单位[n].法术状态.瘴气.风瘴 ~= nil then
					self.参战单位[n].法术状态.瘴气.回合 = 150
				end
			end
		elseif qz(self.天气) == 3 then
			for n = 1, #self.参战单位 do
				if self:取奇经八脉是否有(n, "妖法") and self.参战单位[n].法宝境界 ~= nil and self.参战单位[n].法宝境界.宝烛 ~= nil then
					local cs = 0

					for i = 1, #self.参战单位[n].法宝境界.宝烛 do
						cs = cs + self.参战单位[n].法宝境界.宝烛[i]
					end

					local jc = qz(self.参战单位[n].速度 * 0.01 * (cs + 3))

					if self.参战单位[n].妖法速度 ~= nil then
						self.参战单位[n].速度 = self.参战单位[n].速度 - self.参战单位[n].妖法速度
					end

					self.参战单位[n].速度 = self.参战单位[n].速度 + jc
					self.参战单位[n].妖法速度 = jc + 0
				end
			end
		end

		self:发送天气数据()
	end

	if self.战斗脚本 and self.战斗脚本.命令回合前 then
		__gge.safecall(self.战斗脚本.命令回合前, self, self.回合数)
	end

	for n = 1, #self.参战玩家 do
		local 编号 = self:取参战编号(self.参战玩家[n].id, "角色")
		local 目标 = {
			编号
		}

		if self.参战单位[编号].召唤兽 ~= nil then
			目标[2] = self.参战单位[编号].召唤兽
		end

		for n = 1, #self.参战单位 do
			if self.参战单位[n].名称 == "大大王" and self.回合数 == 2 and self.战斗类型 == 110002 then
				self.战斗发言数据[#self.战斗发言数据 + 1] = {
					内容 = "上古大神#G明夜君\n你就放心躺好吧\n接下来交给我们#2",
					id = n
				}
			elseif self.参战单位[n].名称 == "地涌夫人" and self.回合数 == 3 and self.战斗类型 == 110002 then
				self.战斗发言数据[#self.战斗发言数据 + 1] = {
					内容 = "大家坚持住\n#G蚩尤#W已经变弱了\n我来给大家加个#YBUFF#1",
					id = n
				}
			elseif self.参战单位[n].名称 == "牛魔王" and self.回合数 == 4 and self.战斗类型 == 110002 then
				self.战斗发言数据[#self.战斗发言数据 + 1] = {
					内容 = "胜利就在眼前了\n#大家加油\n老牛我发威了#4",
					id = n
				}
			elseif self.参战单位[n].名称 == "李彪" and self.回合数 == 5 and self.战斗类型 == 110014 then
				self.战斗发言数据[#self.战斗发言数据 + 1] = {
					内容 = "#Y刘洪#这废物\n留着何用?\n送你#R归西#吧",
					id = n
				}
			end
		end

		if self.参战单位[编号].助战明细 ~= nil then
			for i = 1, #self.参战单位[编号].助战明细 do
				目标[#目标 + 1] = self.参战单位[编号].助战明细[i]
			end
		end

		for i = 1, #目标 do
			self.参战单位[目标[i]].指令 = {
				参数 = "",
				敌我 = 0,
				附加 = "",
				类型 = "",
				目标 = 0,
				下达 = false,
				编号 = 目标[i]
			}
		end

		if 玩家数据[self.参战玩家[n].id] ~= nil and 玩家数据[self.参战玩家[n].id].角色.数据.自动战斗 then
		end

		发送数据(self.参战玩家[n].连接id, 5503, {
			目标,
			self.回合数,
			服务端参数.回合命令时间
		})

		for i = 1, #self.战斗发言数据 do
			发送数据(self.参战玩家[n].连接id, 5512, {
				id = self.战斗发言数据[i].id,
				文本 = self.战斗发言数据[i].内容
			})
		end

		self.战斗发言数据 = {}
	end

	for n = 1, #self.参战单位 do
		if self.参战单位[n].队伍 == 0 then
			self.参战单位[n].指令 = {
				参数 = "",
				敌我 = 0,
				附加 = "",
				类型 = "",
				目标 = 0,
				下达 = false
			}
		elseif self.参战单位[n].指令 ~= nil then
			self.参战单位[n].指令 = {
				参数 = "",
				敌我 = 0,
				附加 = "",
				类型 = "",
				目标 = 0,
				下达 = false,
				编号 = self.参战单位[n].指令.编号
			}
		else
			self.参战单位[n].指令 = {
				参数 = "",
				敌我 = 0,
				附加 = "",
				类型 = "",
				目标 = 0,
				下达 = false,
				编号 = n
			}
		end
	end

	self.加载数量 = #self.参战玩家
	self.等待起始 = os.time()
	self.回合进程 = "命令回合"
end

function 战斗处理类:取参战编号(id, 类型)
	for n = 1, #self.参战单位 do
		if self.参战单位[n].类型 == 类型 and self.参战单位[n].玩家id == id and self.参战单位[n].助战编号 == nil then
			return n
		end
	end
end

function 战斗处理类:逃跑事件处理(id)
	if 战斗准备类.战斗盒子[玩家数据[id].战斗].战斗类型 == 110038 then
		玩家数据[id].角色:取消任务(玩家数据[id].角色:取任务(300))

		玩家数据[id].角色.押镖间隔 = os.time() + 180
		玩家数据[id].角色.数据.跑镖遇怪时间 = 0

		添加最后对话(id, format("任务失败,押镖任务不能逃跑,您三分钟之内无法再次领取押镖任务"))
	end

	if #self.参战玩家 == 1 then
		self.回合进程 = "结束回合"

		if self.任务id ~= nil and 任务数据[self.任务id] ~= nil then
			任务数据[self.任务id].战斗 = nil
		end

		self:还原指定单位属性(id)
		self:失败处理(id, "逃跑")
		self:发送退出信息()

		self.参战玩家 = {}
		self.结束条件 = true
		玩家数据[id].角色.数据.战斗开关 = false

		return
	else
		local 编号 = 0

		for n = 1, #self.参战玩家 do
			if self.参战玩家[n].id == id then
				地图处理类:设置战斗开关(self.参战玩家[n].id)
				table.remove(self.参战玩家, n)

				break
			end
		end

		if self:取玩家战斗() then
			self:发送退出信息()
		end

		self:还原指定单位属性(id)

		玩家数据[id].战斗 = 0
		玩家数据[id].角色.数据.战斗开关 = nil

		玩家数据[id].道具:重置法宝回合(id)
		队伍处理类:退出队伍(id)

		玩家数据[id].遇怪时间 = os.time() + 取随机数(10, 20)

		发送数据(玩家数据[id].连接id, 5505)
	end
end

function 战斗处理类:结束战斗2()
	self:失败处理()
	self:还原单位属性()
	self:发送退出信息()
end

function 战斗处理类:结束战斗(胜利id, 失败id, 系统)
	if 系统 == nil then
		self:胜利处理(胜利id, 失败id)
		self:失败处理(失败id, nil, 胜利id)
	end

	self:还原单位属性()
	self:发送退出信息()
end

function 战斗处理类:结束战斗1(胜利id, 失败id, 系统, id)
	if 系统 == nil then
		self:胜利处理(胜利id, 失败id)
		self:失败处理(失败id, 1, 胜利id)
	end

	self:还原单位属性()
	self:发送退出信息()
end

