通用给奖励 = function(id, 经验银子, 说明, 固定列表, 额外)
	if 额外 ~= "不判断次数" and 不判断次数列表[说明] == nil and 添加活动次数(id, 说明) == false then
		return
	end

	奖励次数[id] = 取奖励次数(id)
	local dj = 取等级标准(id)
	local 等级 = dj[1]
	local 等级标准 = dj[2]
	local 助战倍率 = dj[3]
	local 经验, 银子, 储备 = nil

	if 奖励次数1次列表[说明] ~= nil or 说明 == "福利宝箱" and 额外 == nil or 说明 == "大闹天宫1" and 额外 ~= nil then
		奖励次数[id] = 1 * 全局奖励倍率
		助战倍率 = 1
	end

	if 经验银子 ~= nil and not 判断是否为空表(经验银子) then
		if 经验银子.经验 ~= nil and #经验银子.经验 > 0 then
			经验 = 等级 * qsj(经验银子.经验[1], 经验银子.经验[2] or 经验银子.经验[1])

			玩家数据[id].角色:添加经验(经验, 说明, 1)
			召唤兽添加经验(math.floor(经验 * 0.8), id, 说明)
		end

		if 经验银子.银子 ~= nil and #经验银子.银子 > 0 then
			银子 = 等级 * qsj(经验银子.银子[1], 经验银子.银子[2] or 经验银子.银子[1])

			玩家数据[id].角色:添加银子(银子 * 助战倍率, 说明, 1)
		end

		if 经验银子.储备 ~= nil and #经验银子.储备 > 0 then
			储备 = 等级 * qsj(经验银子.储备[1], 经验银子.储备[2] or 经验银子.储备[1])

			玩家数据[id].角色:添加储备(储备 * 助战倍率, 说明, 1)
		end

		if 经验银子.活跃度 ~= nil then
			添加活跃度(id, 经验银子.活跃度)
		end

		if 经验银子.门贡 ~= nil then
			添加门贡(id, 经验银子.门贡)
		end

		if 经验银子.妖魔积分 ~= nil then
			给妖魔积分(id, 经验银子.妖魔积分 * 助战倍率)
		end

		if 经验银子.种族积分 ~= nil then
			给种族积分(id, 经验银子.种族积分 * 助战倍率)
		end

		if 经验银子.副本积分 ~= nil then
			给副本积分(id, 经验银子.副本积分 * 助战倍率)
		end
	end

	if 说明 == nil then
		return
	elseif 说明 == "降妖伏魔" and 额外 ~= nil then
		说明 = "降妖伏魔1"
	end

	local 活动奖励列表 = {}

	if 固定列表 ~= nil then
		if 固定活动奖励列表[说明] == nil then
			固定活动奖励列表[说明] = 取奖励列表(说明, 等级, 等级标准)
		end

		活动奖励列表 = 固定活动奖励列表[说明]
	else
		活动奖励列表 = 取奖励列表(说明, 等级, 等级标准)
	end

	for i = 1, 奖励次数[id] do
		if 说明 == "突厥精英" then
			if ygsj() <= qz1((等级 + 10) / 1.5) then
				快捷给道具(id, "突厥密函", 1)
			end
		elseif 说明 == "突厥探子" then
			if ygsj() <= qz1(等级 / 3) then
				快捷给道具(id, "突厥密函", 1)
			end
		elseif 说明 == "天降星辰" and 额外 == "亥猪" then
			if ygsj() <= 30 then
				奖励名称[id] = 快捷给道具(id, "百炼晶石碎片", 1)

				广播消息({
					频道 = "xt",
					内容 = format("#S(天降星辰)#R/%s#Y完成了一轮十二元辰挑战，#P游奕灵官#Y甚是满意，特赠送#G/%s#Y以资鼓励！" .. "#" .. 取随机数(1, 110),
						玩家数据[id].角色.数据.名称, 奖励名称[id])
				})
			end
		elseif 说明 == "师门任务" and 额外 == 10 then
			if ygsj() <= 50 then
				奖励名称[id] = 快捷给道具(id, "三界悬赏令", 1)

				广播消息({
					频道 = "xt",
					内容 = format("#S(师门任务)#R/%s#Y在师门任务中表现优异，#Y获得了#P%s#Y奖励的#G%s", 玩家数据[id].角色.数据.名称,
						取门派师傅名称(玩家数据[id].角色.数据.门派), 奖励名称[id])
				})
			end

			给妖魔积分(id, 10)
		elseif 说明 == "知了王" then
			if ygsj() <= 2 then
				快捷给道具(id, "召唤兽装备", 取随机数(7, 13))
			elseif ygsj() <= 1 then
				奖励名称[id] = 快捷给道具(id, "无级别装备", 130)

				广播消息({
					频道 = "xt",
					内容 = format("#S(知了王)#R/%s#Y对着知了王一顿乱打脚踢，打得知了王双手奉上了#G/%s#Y以求活命。" .. "#" .. 取随机数(1, 110),
						玩家数据[id].角色.数据.名称, 奖励名称[id])
