					"#S(雁塔地宫)#R/%s#Y少侠在#P雁塔地宫#Y中不断探寻，并成功通过了#P/%s#Y层地宫守护兽的考验，神秘人将地宫中挖掘出的#G%s#Y赠予其作为奖励，真是羡煞旁人" ..
					"#" .. 取随机数(1, 110), 玩家数据[id].角色.数据.名称, 额外, 奖励名称[id])
				})
			end
		end
	end
end

给副本奖励 = function(id组, 副本等级, 序列, 最大序列, 奖励模版)
	local 奖励经验 = 副本等级 * 副本等级 * 10 * 序列

	for n = 1, #id组 do
		if 队伍处理类:取是否助战(玩家数据[id组[1]].队伍, n) == 0 then
			local id = id组[n]
			local 活动名称 = 奖励模版

			if 奖励模版 == "天蓬娶亲" or 奖励模版 == "白龙闹海" then
				活动名称 = 奖励模版 .. tostring(序列)
			end

			if 添加活动次数(id, 活动名称) then
				玩家数据[id].角色:添加经验(qz(奖励经验 * 取随机数(90, 110) / 100), "副本奖励")
				玩家数据[id].角色:添加银子(qz(奖励经验 * 取随机数(150, 200) / 1000), "副本奖励", "副本奖励")

				奖励次数[id] = 取奖励次数(id)

				for i = 1, 奖励次数[id] do
					local 奖励参数 = ygsj()

					if 奖励模版 == "突厥探子" then
						if i == 1 then
							给种族积分(id, 1 * 奖励次数[id])
						end

						if ygsj() <= qz1(副本等级 / 3) then
							快捷给道具(id, "突厥密函", 1)
						end

						if ygsj() <= qz1(副本等级 / 5) then
							if 副本等级 > 100 then
								奖励名称[id] = 取快捷奖励(id, 副本奖励60)
							else
								奖励名称[id] = 取快捷奖励(id, 副本奖励50)
							end

							奖励广播(id, 奖励名称[id], 奖励模版)
						end
					elseif 奖励模版 == "突厥精英" then
						if i == 1 then
							给种族积分(id, 5 * 奖励次数[id])
						end

						if ygsj() <= qz1((副本等级 + 10) / 1.5) then
							快捷给道具(id, "突厥密函", 1)
						end

						if ygsj() <= qz1((副本等级 + 10) / 3) then
							奖励名称[id] = 取快捷奖励(id, 突厥精英奖励)

							奖励广播(id, 奖励名称[id], 奖励模版)
						end
					elseif qz(奖励参数 / 序列) <= qz(100 / 最大序列) then
						local jl, jf = nil

						if 奖励模版 == "天蓬娶亲" then
							奖励名称[id] = 取快捷奖励(id, 副本奖励50)
							jl = 10
							jf = 15
						elseif 奖励模版 == "白龙闹海" then
							奖励名称[id] = 取快捷奖励(id, 副本奖励60)
							jl = 15
							jf = 20
						end

						奖励广播(id, 奖励名称[id], 奖励模版)

						if 序列 == 最大序列 and jl ~= nil and jf ~= nil then
							快捷给道具(id, "金柳露", 取随机数(jl, jl + 10))
							给副本积分(id, jf)
						end
					end
				end
			end
		end
	end
end

给战宠奖励 = function(id, 战宠, 专用)
	if 战宠奖励[战宠] == nil then
		战宠奖励[战宠] = {}
	end

	if 战宠奖励[战宠][id] == nil then
		快捷给道具(id, "召唤兽蛋", 1, 战宠, 专用)

		战宠奖励[战宠][id] = 1
	else
		常规提示(id, "#Y你已经获得过#R" .. 战宠 .. "#Y的奖励，无法重复获取。")
	end
end

function 战斗处理类:胜利处理(胜利id, 失败id)
	local id组 = {}

	for n = 1, #self.参战玩家 do
		if self.参战玩家[n].队伍 == 胜利id and 玩家数据[self.参战玩家[n].id] ~= nil then
			self:奖励事件(self.参战玩家[n].id)

			id组[#id组 + 1] = self.参战玩家[n].id
		end
	end

	local 队伍id = 玩家数据[self.进入战斗玩家id].队伍

	if 队伍id ~= nil and 队伍id ~= 0 then
		for i = 1, #队伍数据[队伍id].成员数据 do
			id组[i] = 队伍数据[队伍id].成员数据[i]
		end
	end

	if 胜利id ~= 0 or 失败id ~= 0 then
		if self.战斗类型 == 110001 then
			游戏活动类:剑会天下结算处理假人(胜利id, 失败id)
		elseif self.战斗类型 == 410005 then
			游戏活动类:剑会天下结算处理真人(胜利id, 失败id)
		end
	end

	if 胜利id ~= 0 then
		self.玩家胜利 = true
		self.战斗胜利 = true

		if self.战斗脚本 and self.战斗脚本.战斗胜利 then
			__gge.safecall(self.战斗脚本.战斗胜利, self, 胜利id, 失败id)
		end

		if self.战斗类型 == 100004 then
			任务处理类:完成封妖任务(self.任务id, id组)
		elseif self.战斗类型 == 140000 then
			雁塔地宫:战斗胜利处理(id组, self.战斗类型)
		elseif self.战斗类型 >= 130041 and self.战斗类型 <= 130052 then
			天降辰星:战斗胜利处理(id组, self.战斗类型)
		elseif self.战斗类型 >= 130087 and self.战斗类型 <= 130096 then
			长安保卫战:战斗胜利处理(id组, self.战斗类型, self.任务id)
		elseif self.战斗类型 == 100007 or self.战斗类型 == 100008 or self.战斗类型 == 100008.1 or self.战斗类型 == 100008.2 or self.战斗类型 == 100009 or self.战斗类型 == 100010 then
			地图处理类:删除单位(任务数据[self.任务id].地图编号, 任务数据[self.任务id].单位编号)

			任务数据[self.任务id] = nil
		elseif self.战斗类型 == 100006 then
			游戏活动类:科举回答题目(玩家数据[self.进入战斗玩家id].连接id, self.进入战斗玩家id, 答案, 4)
		elseif self.战斗类型 == 100239 then
			任务处理类:一键抓鬼(self.进入战斗玩家id)
		elseif self.战斗类型 == 100240 then
			任务处理类:一键师门(self.进入战斗玩家id)
		elseif self.战斗类型 == 100241 then
			任务处理类:一键官职(self.进入战斗玩家id)
		elseif self.战斗类型 == 100011 then
			local 任务id1 = 玩家数据[self.进入战斗玩家id].角色:取任务(107)
			local 对话门派 = Q_门派编号[任务数据[任务id1].当前序列]
			self.对话数据 = {
				名称 = 任务数据[self.任务id].名称,
				模型 = 任务数据[self.任务id].模型
			}
			local 删除序列 = 0

			for n = 1, #任务数据[任务id1].闯关序列 do
				if 任务数据[任务id1].闯关序列[n] == 任务数据[任务id1].当前序列 then
					删除序列 = n
				end
			end

			table.remove(任务数据[任务id1].闯关序列, 删除序列)

			if #任务数据[任务id1].闯关序列 == 0 then
				self.对话数据.对话 = "恭喜你们完成了本轮门派闯关活动#1"
				local 队伍id = 玩家数据[self.进入战斗玩家id].队伍

				for i = 1, #队伍数据[队伍id].成员数据 do
					if 队伍处理类:取是否助战(玩家数据[self.进入战斗玩家id].队伍, i) == 0 then
						玩家数据[队伍数据[队伍id].成员数据[i]].角色:取消任务(任务id1)
					end
				end
			else
				任务数据[任务id1].当前序列 = 任务数据[任务id1].闯关序列[取随机数(1, #任务数据[任务id1].闯关序列)]
				任务数据[任务id1].地图编号 = 取门派地图(Q_门派编号[任务数据[任务id1].当前序列])[1]
				任务数据[任务id1].x = Q_闯关数据[Q_门派编号[任务数据[任务id1].当前序列]].x
				任务数据[任务id1].y = Q_闯关数据[Q_门派编号[任务数据[任务id1].当前序列]].y
				self.对话数据.对话 = format("你通过了本门派护法的考验，请继续前往下一关#Y/%s#W/接受考验。" .. "#" .. 取随机数(1, 110),
					Q_门派编号[任务数据[任务id1].当前序列])
				local 队伍id = 玩家数据[self.进入战斗玩家id].队伍

				for i = 1, #队伍数据[队伍id].成员数据 do
					if 队伍处理类:取是否助战(玩家数据[self.进入战斗玩家id].队伍, i) == 0 then
						玩家数据[队伍数据[队伍id].成员数据[i]].角色:刷新任务跟踪()
					end
				end
			end
		elseif self.战斗类型 == 100012 then
			任务数据[玩家数据[self.进入战斗玩家id].角色:取任务(109)].战斗 = true
		elseif self.战斗类型 == 100013 then
			任务数据[self.任务id].战斗次数 = 任务数据[self.任务id].战斗次数 + 1

			地图处理类:删除单位(任务数据[self.任务id].地图编号, 任务数据[self.任务id].单位编号)

			if 任务数据[self.任务id].战斗次数 >= 2 then
				任务处理类:完成官职任务(self.进入战斗玩家id, 1)
			else
				local 地图范围 = {
					1001,
					1501,
					1092,
					1070,
					1040,
					1226,
					1208
				}
				local 地图 = 地图范围[取随机数(1, #地图范围)]
				local xy = 地图处理类.地图坐标[地图]:取随机点()
				任务数据[self.任务id].地图编号 = 地图
				任务数据[self.任务id].地图名称 = 取地图名称(地图)
				任务数据[self.任务id].x = xy.x
				任务数据[self.任务id].y = xy.y
				玩家数据[self.进入战斗玩家id].战斗对话 = {
					名称 = "流氓",
					对话 = "打不过我还躲不过嘛，换个地方继续惹事#4",
					模型 = "赌徒"
				}

				地图处理类:添加单位(self.任务id)
				玩家数据[self.进入战斗玩家id].角色:刷新任务跟踪()
			end
		elseif self.战斗类型 == 100014 then
			if 玩家数据[self.进入战斗玩家id].角色:取道具格子() == 0 then
				常规提示(self.进入战斗玩家id, "#Y/你的包裹已经满了，无法获得情报")
			elseif ygsj() <= 66 then
				玩家数据[self.进入战斗玩家id].道具:给予道具(self.进入战斗玩家id, "情报")
				常规提示(self.进入战斗玩家id, "#Y/你得到了#R/情报")

				任务数据[self.任务id].情报 = true

				玩家数据[self.进入战斗玩家id].角色:刷新任务跟踪()
			end
		elseif self.战斗类型 == 100015 then
			任务数据[self.任务id].巡逻 = 任务数据[self.任务id].巡逻 + 1

			if 任务数据[self.任务id].巡逻 == 2 then
				召唤兽添加经验(qz(玩家数据[self.进入战斗玩家id].角色.数据.等级 * 15 * (90 + ygsj(20))), self.进入战斗玩家id, "师门巡逻")
				任务处理类:完成门派任务(self.进入战斗玩家id, 2)
			else
				召唤兽添加经验(qz(玩家数据[self.进入战斗玩家id].角色.数据.等级 * 10 * (90 + ygsj(20))), self.进入战斗玩家id, "师门巡逻")
				常规提示(self.进入战斗玩家id, "#Y/换个地方我继续捣乱，嘿嘿！")
			end
		elseif self.战斗类型 == 100016 then
			地图处理类:删除单位(任务数据[self.任务id].地图编号, 任务数据[self.任务id].单位编号)
			任务处理类:完成门派任务(self.进入战斗玩家id, 5)
		elseif self.战斗类型 == 100017 then
			地图处理类:删除单位(任务数据[self.任务id].地图编号, 任务数据[self.任务id].单位编号)

			if self.同门死亡 then
				常规提示(self.进入战斗玩家id, "#Y/你的师门援助任务失败了")
				玩家数据[self.进入战斗玩家id].角色:取消任务(self.任务id)

				任务数据[self.任务id] = nil
				玩家数据[self.进入战斗玩家id].角色.数据.师门次数 = 0
			else
				任务处理类:完成门派任务(self.进入战斗玩家id, 6)
			end
		elseif self.战斗类型 == 100018 then
			地图处理类:删除单位(任务数据[self.任务id].地图编号, 任务数据[self.任务id].单位编号)

			if not 任务数据[self.任务id].乾坤袋 then
				local xy = 地图处理类.地图坐标[任务数据[self.任务id].地图编号]:取随机点()
				任务数据[self.任务id].y = xy.y
				任务数据[self.任务id].x = xy.x

				玩家数据[self.进入战斗玩家id].角色:刷新任务跟踪()
				地图处理类:添加单位(self.任务id)
			end
		elseif self.战斗类型 == 100019 or self.战斗类型 == 100020 or self.战斗类型 == 100021 or self.战斗类型 == 100022 or self.战斗类型 == 100023 or self.战斗类型 == 100024 or self.战斗类型 == 100026 or self.战斗类型 == 100027 then
			if self.战斗类型 == 100026 then
				玩家数据[self.进入战斗玩家id].角色:取消任务(self.任务id)
				玩家数据[self.进入战斗玩家id].角色:刷新任务跟踪()
			end

			if self.任务id ~= nil then
				地图处理类:删除单位(任务数据[self.任务id].地图编号, 任务数据[self.任务id].单位编号)

				任务数据[self.任务id] = nil
			end
		elseif self.战斗类型 == 100028 then
			local 副本id = 任务数据[self.任务id].副本id
			副本数据.乌鸡国.进行[副本id].木妖数量 = (副本数据.乌鸡国.进行[副本id].木妖数量 or 0) + 1

			if 副本减负.乌鸡国[1] <= 副本数据.乌鸡国.进行[副本id].木妖数量 then
				副本数据.乌鸡国.进行[副本id].进程 = 2

				任务处理类:设置乌鸡国副本(副本id)
			end

			for n = 1, #队伍数据[玩家数据[self.进入战斗玩家id].队伍].成员数据 do
				if 队伍处理类:取是否助战(玩家数据[self.进入战斗玩家id].队伍, n) == 0 then
					local id1 = 队伍数据[玩家数据[self.进入战斗玩家id].队伍].成员数据[n]

					通用给奖励(id1, {
						活跃度 = 1,
						经验 = {
							250,
							350
						},
						银子 = {
							100,
							150
						},
						储备 = {
							150,
							200
						}
					}, "乌鸡国1")
					常规提示(队伍数据[玩家数据[self.进入战斗玩家id].队伍].成员数据[n], "#Y您的副本进度已经更新")
					玩家数据[队伍数据[玩家数据[self.进入战斗玩家id].队伍].成员数据[n]].角色:刷新任务跟踪()
				end
			end

			地图处理类:删除单位(任务数据[self.任务id].地图编号, 任务数据[self.任务id].单位编号)

			任务数据[self.任务id] = nil
		elseif self.战斗类型 > 34482 and self.战斗类型 < 34483 then
			local sy = string.gsub(tostring(self.战斗类型), "34482.", "")
			sy = tonumber(sy)

			for n = 1, #队伍数据[玩家数据[self.进入战斗玩家id].队伍].成员数据 do
				if 队伍处理类:取是否助战(玩家数据[self.进入战斗玩家id].队伍, n) == 0 then
					local dqid = 队伍数据[玩家数据[self.进入战斗玩家id].队伍].成员数据[n]
					local 当前任务 = 玩家数据[dqid].角色.数据.当前剧情

					if sy == 1 and 当前任务.任务 == "女娲神迹" and 当前任务.进程 == 9 then
						玩家数据[dqid].最后对话.名称 = "春十三娘"
						玩家数据[dqid].最后对话.模型 = "春十三娘"

						取快捷对话模版(dqid, 玩家数据[dqid].最后对话.名称, 玩家数据[dqid].最后对话.模型, 玩家数据[dqid].角色.数据.名称, 玩家数据[dqid].角色.数据.模型)
						添加最后对话(dqid, "噗……!", nil, {
							置快捷对话模版(快捷对话模版[dqid][2], "快说，刑天现在到底联系了哪些妖怪，什么时候动手？！"),
							置快捷对话模版(快捷对话模版[dqid][1], "就你这个小毛头也想学人来管闲事，切。"),
							置快捷对话模版(快捷对话模版[dqid][2], "嘴硬是吧，好，我把你带给小紫姑娘去处置"),
							置快捷对话模版(快捷对话模版[dqid][1], "想的美，看我的土遁！"),
							置快捷对话模版(快捷对话模版[dqid][2], "好狡诈的女魔头，我得赶紧回去告诉小紫！")
						})
						xsjc5(dqid, 10)
						玩家数据[dqid].角色:添加剧情点(2)
						玩家数据[dqid].角色:添加经验(35000000, "剧情任务")
						玩家数据[dqid].角色:添加银子(3000000, "剧情任务", 1)
						快捷给道具(dqid, "通灵神戒", 1)

						奖励名称[dqid] = 快捷给道具(dqid, "超级通灵重置丹", 1)

						快捷广播(dqid, "女娲神迹", "剧情任务", "通灵神戒、" .. 奖励名称[dqid])
					elseif sy == 2 and 当前任务.任务 == "八戒悟空" and 当前任务.进程 == 2 then
						玩家数据[dqid].最后对话.名称 = "康太尉"
						玩家数据[dqid].最后对话.模型 = "天兵"

						添加最后对话(dqid, "果然有些功夫门道,小的们,打不过我们跑啊!")
						xsjc6(dqid, 3)
						玩家数据[dqid].角色:添加剧情点(2)
						玩家数据[dqid].角色:添加经验(20000000, "剧情任务")
						玩家数据[dqid].角色:添加银子(2000000, "剧情任务", 1)

						奖励名称[dqid] = 快捷给道具(dqid, "高级召唤兽内丹", 1)

						快捷广播(dqid, "八戒悟空", "剧情任务", 奖励名称[dqid])
