function 战斗处理类:取野外等级差(地图等级, 玩家等级)
	local 等级 = math.abs(地图等级 - 玩家等级)

	if 等级 <= 5 then
		return 1
	elseif 等级 <= 10 then
		return 0.8
	elseif 等级 <= 20 then
		return 0.5
	else
		return 0.2
	end
end

function 战斗处理类:取编号目标气血(编号)
	return self.参战单位[目标].气血
end

function 战斗处理类:取名称目标气血(名称)
	for n = 1, #self.参战单位 do
		if self.参战单位[n].名称 == 名称 then
			return self.参战单位[n].气血
		end
	end
end

取奖励次数 = function(id)
	奖励次数[id] = 1

	if 队伍数据[玩家数据[id].队伍] ~= nil and 队伍数据[玩家数据[id].队伍].成员数据[1] == id and 助战奖励开关 == true then
		local 助战数量 = 0

		for i = 2, 5 do
			if 队伍处理类:取是否助战(玩家数据[id].队伍, i) ~= 0 then
				助战数量 = 助战数量 + 1
			end
		end

		奖励次数[id] = 奖励次数[id] + qz(助战数量 / 助战奖励换算人数)
	else
		奖励次数[id] = 1
	end

	return (奖励次数[id] + 0) * 全局奖励倍率
end

