场景加灵气 = function(id, 地图)
	if 增加法宝灵气地图[地图] == nil then
		return
	end

	local 增加灵气法宝列表 = {}

	if 玩家数据[id].角色.数据.法宝佩戴 ~= nil then
		for i = 1, 法宝最大携带数量 do
			if 玩家数据[id].角色.数据.法宝佩戴[i] ~= nil then
				增加灵气法宝列表[#增加灵气法宝列表 + 1] = {
					玩家数据[id].角色.数据.法宝佩戴[i]
				}
			end
		end
	end

	if 队伍数据[玩家数据[id].队伍] ~= nil and 队伍数据[玩家数据[id].队伍].成员数据[1] == id then
		for i = 2, 5 do
			local 助战编号 = 队伍处理类:取是否助战(玩家数据[id].队伍, i, true)

			if 助战编号 ~= 0 and 玩家数据[id].助战.数据[助战编号].法宝佩戴 ~= nil then
				for i = 1, 法宝最大携带数量 do
					if 玩家数据[id].助战.数据[助战编号].法宝佩戴[i] ~= nil then
						增加灵气法宝列表[#增加灵气法宝列表 + 1] = {
							玩家数据[id].助战.数据[助战编号].法宝佩戴[i],
							"#P(助战)#Y" .. 玩家数据[id].助战.数据[助战编号].名称 .. "#W"
						}
					end
				end
			end
		end
	end

	for i = 1, #增加灵气法宝列表 do
		local 扣除id = 增加灵气法宝列表[i][1]
		local js = "你"

		if 增加灵气法宝列表[i][2] ~= nil then
			js = 增加灵气法宝列表[i][2]
		end

		if 玩家数据[id].道具.数据[扣除id] ~= nil and 玩家数据[id].道具.数据[扣除id].魔法 < 取灵气上限(玩家数据[id].道具.数据[扣除id].分类) then
			玩家数据[id].道具.数据[扣除id].魔法 = 玩家数据[id].道具.数据[扣除id].魔法 + 场景法宝灵气增加数

			发送数据(玩家数据[id].连接id, 38, {
				内容 = js .. "的法宝[#R" .. 玩家数据[id].道具.数据[扣除id].名称 .. "#W]灵气增加了#Y" .. 场景法宝灵气增加数 .. "#W点"
			})
		end
	end
end

function 战斗处理类:奖励事件(id)
	场景加灵气(id, self.战斗地图)

	local 名称 = ""

	if self.战斗类型 == 100001 or self.战斗类型 == 100007 then
		if self.地图等级 <= 3 then
			self.地图等级 = 3
		end

		奖励次数[id] = 取奖励次数(id)
		local 奖励经验 = qz(self.地图等级 * 5 * self.敌人数量)
		local 奖励参数 = self:取野外等级差(self.地图等级, 玩家数据[id].角色.数据.等级)
		奖励经验 = qz(奖励经验 * 奖励参数) * 10

		玩家数据[id].角色:添加经验(奖励经验, "野外")

		if 掉率模式 == 1 then
			if 单机设置 then
				local 野外仙玉数量 = qz(取随机数(self.地图等级 * 0.1, self.地图等级 * 0.2) * self.敌人数量 / 5 * 奖励参数)

				if 野外仙玉数量 <= 0 then
					野外仙玉数量 = 1
				end

				添加仙玉(野外仙玉数量 * 奖励次数[id], 玩家数据[id].账号, id, "野外掉落")
			end

			local 野外银子数量 = qz1(取随机数(self.地图等级 * 30, self.地图等级 * 50) * self.敌人数量 / 10 * 奖励参数)

			玩家数据[id].角色:添加储备(qz1(取随机数(self.地图等级 * 30, self.地图等级 * 50) * self.敌人数量 / 10 * 奖励参数) * 奖励次数[id], "野外", "野外")
			玩家数据[id].角色:添加银子(野外银子数量 * 奖励次数[id], "野外", "野外")
		else
			local 野外仙玉数量 = qz(取随机数(self.地图等级 * 0.2, self.地图等级 * 0.5) * self.敌人数量 / 3 * 奖励参数)

			if 野外仙玉数量 <= 0 then
				野外仙玉数量 = 1
			end

			local 野外银子数量 = qz1(取随机数(self.地图等级 * 10, self.地图等级 * 100) * self.敌人数量 / 10 * 奖励参数)

			添加仙玉(野外仙玉数量, 玩家数据[id].账号, id, "野外掉落")
			玩家数据[id].角色:添加储备(qz1(取随机数(self.地图等级 * 10, self.地图等级 * 100) * self.敌人数量 / 3 * 奖励参数), "野外", "野外")
			玩家数据[id].角色:添加银子(野外银子数量, "野外", "野外")
		end

		召唤兽添加经验(奖励经验, id, "野外", self.地图等级)
		玩家数据[id].角色:坐骑喂养1(奖励经验)

		local 地图名称 = 取地图名称(玩家数据[id].角色.数据.地图数据.编号)

		if 地图名称 == "东海湾" then
			if 成就数据[id].大海龟 == nil then
				成就数据[id].大海龟 = 0
			end

			if 成就数据[id].大海龟 < 101 then
				成就数据[id].大海龟 = 成就数据[id].大海龟 + 1
			end

			if 成就数据[id].大海龟 == 1 then
				local 成就提示 = "我不是李永生"
				local 成就提示1 = "完成1次了大海龟击杀"

				快捷给道具(id, "五宝", 1)
				发送数据(玩家数据[id].连接id, 149, {
					内容 = 成就提示,
					内容1 = 成就提示1
				})
			elseif 成就数据[id].大海龟 == 100 then
				local 成就提示 = "大海龟杀手-李永生"
				local 成就提示1 = "完成100次了大海龟击杀"

				常规提示(id, "#Y/恭喜你获得了1点成就")
				发送数据(玩家数据[id].连接id, 149, {
					内容 = 成就提示,
					内容1 = 成就提示1
				})
				玩家数据[id].角色:添加称谓(id, "大海龟杀手")

				for i = 1, 2 do
					快捷给道具(id, "五宝", 1)
				end
			end
		end

		if 地图名称 == "江南野外" then
			if 成就数据[id].野猪 == nil then
				成就数据[id].野猪 = 0
			end

			成就数据[id].野猪 = 成就数据[id].野猪 + 1

			if 成就数据[id].野猪 == 1 then
				local 成就提示 = "宰的就是你"
				local 成就提示1 = "完成1次了野猪击杀"

				发送数据(玩家数据[id].连接id, 149, {
					内容 = 成就提示,
					内容1 = 成就提示1
				})

				for i = 1, 1 do
					快捷给道具(id, "五宝", 1)
				end
			elseif 成就数据[id].野猪 == 100 then
				local 成就提示 = "荒漠屠夫"
				local 成就提示1 = "完成100次了野猪击杀"
				成就数据[id].成就点 = 成就数据[id].成就点 + 1

				常规提示(id, "#Y/恭喜你获得了1点成就")
				发送数据(玩家数据[id].连接id, 149, {
					内容 = 成就提示,
					内容1 = 成就提示1
				})

				for i = 1, 2 do
					快捷给道具(id, "五宝", 1)
				end
			end

			if 成就数据[id].野猪 == 101 then
				玩家数据[id].角色:添加称谓(id, "荒漠屠夫")

				成就数据[id].野猪 = 成就数据[id].野猪 + 1

				快捷给道具(id, "特赦令牌", 1)
			end
		end

		for i = 1, 奖励次数[id] do
			if ygsj() <= 20 and 玩家数据[id].角色.数据.等级 >= 15 then
				玩家数据[id].道具:给予道具(id, "心魔宝珠", 1)
				常规提示(id, "#Y你获得了心魔宝珠")
			end

			local 奖励参数 = ygsj(1000)

			if 奖励参数 <= 0.3 * self.敌人数量 then
				野外掉落装备(id, self.地图等级)
				常规提示(id, "#Y你获得了一件#R装备")
			elseif 奖励参数 <= 1 * self.敌人数量 then
				玩家数据[id].装备:生成指定召唤兽装备(id,
					取随机数(math.max(1, math.floor(self.地图等级 / 10) - 4), math.min(11, math.floor(self.地图等级 / 10) + 1)),
					召唤兽装备种类[取随机数(1, 300) % 3 + 1])
				常规提示(id, "#Y/你获得了一个宠物装备")
			elseif 奖励参数 <= 5 * self.敌人数量 then
				野外掉落二级药(id, self.地图等级)
			end
		end

		if self.等级下限 <= 玩家数据[id].角色.数据.等级 and 玩家数据[id].角色.数据.等级 <= self.等级上限 and 取随机数(1, 10000) <= 传说物品几率 * 100 then
			系统处理类:设置传说物品(id)
		end

		if 玩家数据[id].角色:取任务("飞升剧情") ~= 0 and 任务数据[玩家数据[id].角色:取任务("飞升剧情")].四法宝 ~= nil and 任务数据[玩家数据[id].角色:取任务("飞升剧情")].四法宝.修篁斧 == false and 任务数据[玩家数据[id].角色:取任务("飞升剧情")].触发 then
			local 地图名称 = 取地图名称(玩家数据[id].角色.数据.地图数据.编号)
			local 任务id = 玩家数据[id].角色:取任务("飞升剧情")

			if 地图名称 == "普陀山" and ygsj() < 10 then
				任务数据[任务id].四法宝.修篁斧 = true

				玩家数据[id].道具:给予道具(id, "修篁斧", 1, nil, nil, "专用")
				常规提示(id, "#Y你获得了修篁斧")
				玩家数据[id].角色:刷新任务跟踪()
			end
		end

		if 玩家数据[id].角色:取任务(6) ~= 0 then
			local 地图名称 = 取地图名称(玩家数据[id].角色.数据.地图数据.编号)
			local 任务id = 玩家数据[id].角色:取任务(6)

