						玩家数据[id].装备:生成指定召唤兽装备(id, 取随机数(4, 6), 召唤兽装备种类[取随机数(1, 300) % 3 + 1])
					elseif 难度 == 1 then
						玩家数据[id].装备:生成指定召唤兽装备(id, 取随机数(1, 4), 召唤兽装备种类[取随机数(1, 300) % 3 + 1])
					end

					常规提示(id, "#Y/你获得了一个宠物装备")
				end

				if 难度 == 1 then
					奖励参数 = 取随机数(25, 150)
				elseif 难度 == 2 then
					奖励参数 = 取随机数(17, 140)
				elseif 难度 == 3 then
					奖励参数 = 取随机数(5, 120)
				elseif 难度 == 4 then
					奖励参数 = 取随机数(0, 120)
				elseif 难度 == 5 then
					奖励参数 = 取随机数(-1, 120)
				end

				if 奖励参数 <= 2 then
					if ygsj() <= 50 then
						奖励名称[id] = 快捷给道具(id, "资质丸", 1)
					else
						奖励名称[id] = 快捷给道具(id, "属性石", 1)
					end
				elseif 奖励参数 <= 8 then
					奖励名称[id] = 快捷给道具(id, "高级魔兽要诀", 1)
				elseif 奖励参数 <= 15 then
					奖励名称[id] = 快捷给道具(id, "特赦令牌", 1)
				elseif 奖励参数 <= 20 then
					奖励名称[id] = 快捷给道具(id, "百炼精铁", 取随机数(9, 11))
				elseif 奖励参数 <= 30 then
					奖励名称[id] = 快捷给道具(id, "五宝", 1)
				elseif 奖励参数 <= 45 then
					奖励名称[id] = 快捷给道具(id, "月华露", 1)
				elseif 奖励参数 <= 55 then
					奖励名称[id] = 快捷给道具(id, "九转金丹", 1, 300)
				elseif 奖励参数 <= 65 then
					奖励名称[id] = 快捷给道具(id, "修炼果", 1, 300)
				elseif 奖励参数 <= 80 then
					通知开关 = false
					奖励名称[id] = 快捷给道具(id, "金银锦盒", 取随机数(难度 * 2, 难度 * 5))
				else
					通知开关 = false
				end

				if 通知开关 == true then
					广播消息({
						频道 = "xt",
						内容 = format("#S(捣乱的水果)#R/%s#Y经过一番激烈的战斗，最终战胜了#R%s#Y，因此获得了其奖励的#G/%s#Y" .. "#" .. 取随机数(1, 110),
							玩家数据[id].角色.数据.名称, 任务数据[self.任务id].名称, 奖励名称[id])
					})
				end
			end

			if ygsj() <= 额外奖励概率 then
				奖励名称[id] = 取快捷奖励(id, 通常奖励)

				广播消息({
					频道 = "xt",
					内容 = format("#P(运气爆棚)#R/%s#Y真乃天选之人，获得了从天而降的额外奖励：#G/%s#Y" .. "#" .. 取随机数(1, 110), 玩家数据[id].角色.数据.名称,
						奖励名称[id])
				})
			end
		end
	elseif self.战斗类型 == 100120 then
		local 主任务id = 任务数据[self.任务id].主任务

		if 任务数据[主任务id] ~= nil then
			if 任务数据[主任务id].阶段 <= 3 then
				任务数据[主任务id].成功操作 = 任务数据[主任务id].成功操作 + 1
			elseif 任务数据[主任务id].阶段 == 4 then
				任务数据[主任务id].次数 = 任务数据[主任务id].次数 + 1
			end

			任务数据[主任务id].刷出强盗 = nil
		end

		地图处理类:删除单位(任务数据[self.任务id].地图编号, 任务数据[self.任务id].单位编号)
		玩家数据[id].角色:取消任务(self.任务id)
	end
end

function 战斗处理类:失败处理(失败id, 是否逃跑, 胜利id)
	if 失败id == 0 then
		return
	end

	if self.战斗类型 == 100008.2 then
		任务数据[self.任务id].画魂奖励 = nil
		任务数据[self.任务id].龙龟奖励 = nil
		任务数据[self.任务id].变异奖励 = nil

		地图处理类:删除单位(任务数据[self.任务id].地图编号, 任务数据[self.任务id].单位编号)
	end

	local id组 = {}
	self.战斗失败 = true

	for n = 1, #self.参战玩家 do
		if self.参战玩家[n].队伍 == 失败id and 玩家数据[self.参战玩家[n].id] ~= nil then
			if 是否逃跑 == nil and self.战斗类型 ~= 200033 and self.战斗类型 ~= 200004 and self.战斗类型 ~= 200005 and self.战斗类型 ~= 200006 and self.战斗类型 ~= 100114 and self.战斗类型 ~= 100115 then
				if self.战斗类型 == 200008 then
					玩家数据[self.参战玩家[n].id].角色:死亡处理()
					玩家数据[self.参战玩家[n].id].角色:刷新信息("1")
					常规提示(失败id, "#Y/灭队了#17灭队了#28！")
				else
					玩家数据[self.参战玩家[n].id].角色:死亡处理()
					玩家数据[self.参战玩家[n].id].角色:刷新信息("1")
					常规提示(失败id, "#Y/灭队了#17灭队了#28！")
				end
			end

			id组[#id组 + 1] = self.参战玩家[n].id
		end
	end

	for i = 1, #id组 do
		if 玩家数据[id组[i]] ~= nil then
			if self.战斗脚本 and self.战斗脚本.战斗失败 then
				__gge.safecall(self.战斗脚本.战斗失败, self, 失败id, 是否逃跑, 胜利id)
			end

			if self.战斗类型 == 100006 then
				游戏活动类:科举回答题目(玩家数据[self.进入战斗玩家id].连接id, self.进入战斗玩家id, 答案, 5)
			elseif self.战斗类型 == 100017 or self.战斗类型 == 100016 then
				地图处理类:删除单位(任务数据[self.任务id].地图编号, 任务数据[self.任务id].单位编号)
				常规提示(self.进入战斗玩家id, "#Y/你的师门任务失败了")
				玩家数据[self.进入战斗玩家id].角色:取消任务(self.任务id)

				任务数据[self.任务id] = nil
				玩家数据[self.进入战斗玩家id].角色.数据.师门次数 = 0

				if 是否逃跑 == nil then
					self:死亡对话(id组[i])
				end
			elseif self.战斗类型 == 100114 or self.战斗类型 == 100115 then
				常规提示(id组[i], "#Y/想要击败我必须找到观音的法宝，哈哈")

				local 副本id = 任务数据[玩家数据[self.进入战斗玩家id].角色:取任务(150)].副本id

				if self.战斗类型 == 100114 then
					副本数据.水陆大会.进行[副本id].翼虎 = true
					任务数据[self.任务id].战斗 = nil
				else
					副本数据.水陆大会.进行[副本id].蝰蛇 = true
					任务数据[self.任务id].战斗 = nil
				end

				if 副本数据.水陆大会.进行[副本id].翼虎 and 副本数据.水陆大会.进行[副本id].蝰蛇 then
					副本数据.水陆大会.进行[副本id].进程 = 5

					任务处理类:设置水陆大会副本(副本id)
					玩家数据[self.进入战斗玩家id].角色:刷新任务跟踪()
				end
			elseif self.战斗类型 == 100235 then
				常规提示(self.进入战斗玩家id, "#Y/黄狮王好强啊!")

				任务数据[玩家数据[self.进入战斗玩家id].角色:取任务(501)].进程 = 18

				玩家数据[self.进入战斗玩家id].角色:刷新任务跟踪()
			elseif self.战斗类型 == 100256 then
				常规提示(self.进入战斗玩家id, "#Y/看来想要打败心魔,必须找到方法才行")

				if 玩家数据[self.进入战斗玩家id].角色:取任务(996) ~= 0 then
					xsjc3(self.进入战斗玩家id, 4)
				else
					return
				end
			elseif self.战斗类型 == 100018 then
				local xy = 地图处理类.地图坐标[任务数据[self.任务id].地图编号]:取随机点()
				任务数据[self.任务id].y = xy.y
				任务数据[self.任务id].x = xy.x

				玩家数据[self.进入战斗玩家id].角色:刷新任务跟踪()
				地图处理类:添加单位(self.任务id)

				if 是否逃跑 == nil then
					self:死亡对话(id组[i])
				end
			elseif self.战斗类型 == 100001 or self.战斗类型 == 100007 then
				if 玩家数据[self.进入战斗玩家id].角色.数据.等级 ~= nil and 玩家数据[self.进入战斗玩家id].角色.数据.等级 > 10 and 是否逃跑 == nil then
					self:死亡对话(id组[i])
				end
			elseif self.战斗类型 ~= 100007 and self.战斗类型 ~= 100001 and self.战斗类型 ~= 200003 and self.战斗类型 ~= 200004 and self.战斗类型 ~= 200005 and self.战斗类型 ~= 200006 and self.战斗类型 >= 100002 or self.战斗类型 <= 100010 then
				if 是否逃跑 == nil then
					self:死亡对话(id组[i])
				end

				if self.战斗类型 == 100027 then
					广播消息({
						频道 = "cw",
						内容 = format("#R听说#G%s#R在挑战知了王时,被打的鼻青脸肿,连他妈都不认识了#24", 玩家数据[id组[i]].角色.数据.名称)
					})
				elseif self.战斗类型 == 100037 then
					广播消息({
						频道 = "cw",
						内容 = format("#R听说#G%s#R在挑战地煞星时,被打的抱头鼠窜,一时成为了三界笑谈#24", 玩家数据[id组[i]].角色.数据.名称)
					})
				elseif self.战斗类型 == 200007 then
					local 胜利队长 = nil

					for n = 1, #self.参战玩家 do
						if self.参战玩家[n].队伍 == 胜利id and 玩家数据[self.参战玩家[n].id] ~= nil and (玩家数据[self.参战玩家[n].id].队长 or 玩家数据[self.参战玩家[n].id].队伍 == 0) then
							胜利队长 = self.参战玩家[n].id
						end
					end

					if 胜利队长 ~= nil and 玩家数据[胜利队长] ~= nil then
						广播消息({
							频道 = "cw",
							内容 = format("#Y听说#G%s#Y在与#R%s#Ypk时,被打的头破血流,从此夹着尾巴做人！#24", 玩家数据[id组[i]].角色.数据.名称,
								玩家数据[胜利队长].角色.数据.名称)
						})
					end
				elseif self.战斗类型 == 200008 then
					local 胜利队长 = nil

					for n = 1, #self.参战玩家 do
						if self.参战玩家[n].队伍 == 胜利id and 玩家数据[self.参战玩家[n].id] ~= nil and (玩家数据[self.参战玩家[n].id].队长 or 玩家数据[self.参战玩家[n].id].队伍 == 0) then
							胜利队长 = self.参战玩家[n].id
						end
					end

					if 玩家数据[id组[i]].角色.数据.强P开关 ~= nil then
						玩家数据[id组[i]].角色.数据.强P开关 = nil

						发送数据(玩家数据[id组[i]].连接id, 94)
						地图处理类:更改强PK(id组[i])

						if 玩家数据[id组[i]].角色.数据.PK开关 ~= nil then
							发送数据(玩家数据[id组[i]].连接id, 93, {
								开关 = true
							})
							地图处理类:更改PK(id组[i], true)
						end
					end

					if 胜利队长 ~= nil and 玩家数据[胜利队长] ~= nil and (玩家数据[id组[i]].队伍 == 0 or 玩家数据[id组[i]].队长) then
						广播消息({
							频道 = "cw",
							内容 = format("#Y听说#G%s#Y被#R%s#Y强行XXXXX,从此结下了血海深仇！#24", 玩家数据[id组[i]].角色.数据.名称,
								玩家数据[胜利队长].角色.数据.名称)
						})
					end
				elseif self.战斗类型 == 110038 then
					玩家数据[self.进入战斗玩家id].角色:取消任务(玩家数据[self.进入战斗玩家id].角色:取任务(300))

					玩家数据[self.进入战斗玩家id].角色.押镖间隔 = os.time() + 180

					添加最后对话(self.进入战斗玩家id, format("任务失败,押镖任务失败,您三分钟之内无法再次领取押镖任务"))

					玩家数据[self.进入战斗玩家id].角色.数据.跑镖遇怪时间 = 0
				end
			end
		end
	end

	if self.任务id == nil or 任务数据[self.任务id] == nil then
		return
	end

	任务数据[self.任务id].战斗 = nil
end

function 战斗处理类:死亡对话(id)
	玩家数据[id].战斗 = 0
	local 传送 = false

	if 玩家数据[id].队长 then
		if 玩家数据[id].角色.数据.等级 > 9 then
			传送 = true
		end
	else
		队伍处理类:退出队伍(id)

		if 玩家数据[id].角色.数据.等级 > 9 then
			传送 = true
		end
	end

	if 传送 == true then
		local wb = {
			"生死有命,请珍惜生命？",
			"胜败乃兵家常事，"
		}
		local xx = {}
		self.临时数据 = {
			"白无常",
			"白无常",
			wb[取随机数(1, #wb)],
			xx
		}
		self.发送数据 = {
			模型 = self.临时数据[1],
			名称 = self.临时数据[2],
			对话 = self.临时数据[3],
			选项 = self.临时数据[4]
		}

		发送数据(玩家数据[id].连接id, 1501, self.发送数据)
		地图处理类:跳转地图(id, 1125, 24, 27)
	end
end

