function 战斗处理类:还原指定单位属性(id)
	self:还原单位属性(id)
end

function 战斗处理类:还原单位属性(指定id)
	local 待发送玩家 = {}

	for n = 1, #self.参战单位 do
		if 指定id == nil or self.参战单位[n].玩家id == 指定id then
			if self.参战单位[n].气血 < 0 then
				self.参战单位[n].气血 = 0
			end

			if self.参战单位[n].魔法 < 0 then
				self.参战单位[n].魔法 = 0
			end

			if self.参战单位[n] ~= nil and self.参战单位[n].队伍 ~= 0 and self.参战单位[n].逃跑 == nil and self.参战单位[n].系统队友 == nil and 玩家数据[self.参战单位[n].玩家id] ~= nil then
				local 玩家id = self.参战单位[n].玩家id

				if self.参战单位[n].类型 == "角色" then
					local 角色数据 = ""

					if self.参战单位[n].助战编号 == nil then
						if self.参战单位[n].召唤还原 ~= nil then
							local 还原编号 = 0

							for i = 1, #玩家数据[玩家id].召唤兽.数据 do
								if 玩家数据[玩家id].召唤兽.数据[i].参战信息 ~= nil then
									还原编号 = i

									break
								end
							end

							if 还原编号 ~= 0 then
								玩家数据[玩家id].角色.数据.参战宝宝 = {}
								玩家数据[玩家id].角色.数据.参战宝宝 = table.loadstring(table.tostring(玩家数据[玩家id].召唤兽:取存档数据(还原编号)))
							end
						end

						if self.参战单位[n].气血 <= 0 and self.战斗失败 == false then
							玩家数据[玩家id].角色:死亡处理()
							玩家数据[玩家id].角色:刷新信息("1")
						else
							玩家数据[玩家id].角色:刷新信息()
						end

						玩家数据[玩家id].角色.数据.气血 = math.max(self.参战单位[n].气血, 1)
						玩家数据[玩家id].角色.数据.气血上限 = self.参战单位[n].气血上限 or self.参战单位[n].气血
						玩家数据[玩家id].角色.数据.魔法 = self.参战单位[n].魔法
						玩家数据[玩家id].角色.数据.愤怒 = self.参战单位[n].愤怒
						角色数据 = 玩家数据[玩家id].角色.数据
					else
						助战编号 = self.参战单位[n].助战编号

						玩家数据[玩家id].助战:刷新信息(助战编号)

						玩家数据[玩家id].助战.数据[助战编号].气血 = math.max(self.参战单位[n].气血, 1)
						玩家数据[玩家id].助战.数据[助战编号].气血上限 = self.参战单位[n].气血上限 or self.参战单位[n].气血
						玩家数据[玩家id].助战.数据[助战编号].魔法 = self.参战单位[n].魔法
						玩家数据[玩家id].助战.数据[助战编号].愤怒 = self.参战单位[n].愤怒 + 0
						角色数据 = 玩家数据[玩家id].助战.数据[助战编号]
					end

					if 玩家数据[玩家id].角色:取任务(10) ~= 0 and self.战斗类型 ~= 100050 and self.战斗类型 ~= 100051 and self.战斗类型 ~= 100052 and self.战斗类型 ~= 100053 and self.战斗类型 ~= 100130 and self.战斗类型 ~= 100131 and self.战斗类型 ~= 100132 and self.战斗类型 ~= 100133 then
						local 恢复id = 玩家数据[玩家id].角色:取任务(10)

						if 角色数据.气血 < 角色数据.最大气血 then
							local 待恢复气血 = 角色数据.最大气血 - 角色数据.气血

							if 任务数据[恢复id].气血 > 0 then
								local 恢复气血 = math.min(任务数据[恢复id].气血, 待恢复气血)
								任务数据[恢复id].气血 = 任务数据[恢复id].气血 - 恢复气血
								角色数据.气血 = 角色数据.气血 + 恢复气血
								角色数据.气血上限 = math.max(角色数据.气血 + 角色数据.气血上限)
							end
						end

						if 角色数据.魔法 < 角色数据.最大魔法 then
							local 待恢复魔法 = 角色数据.最大魔法 - 角色数据.魔法

							if 任务数据[恢复id].魔法 > 0 then
								local 恢复魔法 = math.min(任务数据[恢复id].魔法, 待恢复魔法)
								任务数据[恢复id].魔法 = 任务数据[恢复id].魔法 - 恢复魔法
								角色数据.魔法 = 角色数据.魔法 + 恢复魔法
							end
						end

						角色数据.气血 = qz(math.min(math.max(角色数据.气血, 1), 角色数据.最大气血))
						角色数据.气血上限 = qz(math.min(math.max(角色数据.气血上限, 1), 角色数据.最大气血))
						角色数据.魔法 = qz(math.min(角色数据.魔法, 角色数据.最大魔法))

						if 任务数据[恢复id].气血 <= 0 and 任务数据[恢复id].魔法 <= 0 then
							玩家数据[玩家id].角色:取消任务(恢复id)
						end

						玩家数据[玩家id].角色:刷新任务跟踪()
					end

					if self.参战单位[n].智能目标 ~= nil then
						角色数据.智能目标 = self.参战单位[n].智能目标
					end

					if self.参战单位[n].九黎自动 ~= nil then
						角色数据.九黎自动 = self.参战单位[n].九黎自动
					end

					if self.参战单位[n].九黎组合技能 ~= nil then
						角色数据.九黎组合技能 = DeepCopy(self.参战单位[n].九黎组合技能)
					end

					if self.参战单位[n].助战编号 == nil then
						待发送玩家[#待发送玩家 + 1] = 玩家id + 0
					end
				elseif self.参战单位[n].类型 == "bb" and self.参战单位[n].认证码 ~= nil and self.参战单位[n].预置bb == nil then
					local bh = 玩家数据[玩家id].召唤兽:取编号(self.参战单位[n].认证码)

					if bh ~= 0 then
						local bb数据 = 玩家数据[玩家id].召唤兽.数据[bh]

						if self.参战单位[n].智能目标 ~= nil then
							bb数据.智能目标 = self.参战单位[n].智能目标
						end

						if self.参战单位[n].九黎自动 ~= nil then
							bb数据.九黎自动 = self.参战单位[n].九黎自动
						end

						if self.参战单位[n].九黎组合技能 ~= nil then
							bb数据.九黎组合技能 = DeepCopy(self.参战单位[n].九黎组合技能)
						end

						if self.参战单位[n].气血 <= 0 then
							if self.参战单位[n].死亡状态 == 2 then
								玩家数据[玩家id].召唤兽:死亡处理(self.参战单位[n].认证码, 玩家id)
							end

							玩家数据[玩家id].召唤兽:刷新信息1(self.参战单位[n].认证码, "1")
						else
							玩家数据[玩家id].召唤兽:刷新信息1(self.参战单位[n].认证码)
						end

						bb数据.气血 = math.min(math.max(self.参战单位[n].气血, 1), self.参战单位[n].最大气血)
						bb数据.魔法 = math.min(self.参战单位[n].魔法, self.参战单位[n].魔法)

						if 玩家数据[玩家id].角色:取任务(10) ~= 0 and self.战斗类型 ~= 100050 and self.战斗类型 ~= 100051 and self.战斗类型 ~= 100052 and self.战斗类型 ~= 100053 and self.战斗类型 ~= 100130 and self.战斗类型 ~= 100131 and self.战斗类型 ~= 100132 and self.战斗类型 ~= 100133 then
							local 恢复id = 玩家数据[玩家id].角色:取任务(10)

							if bb数据.气血 < bb数据.最大气血 then
								local 待恢复气血 = bb数据.最大气血 - bb数据.气血

								if 任务数据[恢复id].气血 > 0 then
									local 恢复气血 = math.min(任务数据[恢复id].气血, 待恢复气血)
									任务数据[恢复id].气血 = 任务数据[恢复id].气血 - 恢复气血
									bb数据.气血 = bb数据.气血 + 恢复气血
								end
							end

							if bb数据.魔法 < bb数据.最大魔法 then
								local 待恢复魔法 = bb数据.最大魔法 - bb数据.魔法

								if 任务数据[恢复id].魔法 > 0 then
									local 恢复魔法 = math.min(任务数据[恢复id].魔法, 待恢复魔法)
									任务数据[恢复id].魔法 = 任务数据[恢复id].魔法 - 恢复魔法
									bb数据.魔法 = bb数据.魔法 + 恢复魔法
								end
							end

							bb数据.气血 = qz(math.min(bb数据.气血, bb数据.最大气血))
							bb数据.魔法 = qz(math.min(bb数据.魔法, bb数据.最大魔法))

							if 任务数据[恢复id].气血 <= 0 and 任务数据[恢复id].魔法 <= 0 then
								玩家数据[玩家id].角色:取消任务(恢复id)
							end

							玩家数据[玩家id].角色:刷新任务跟踪()
						end

						if 玩家数据[玩家id].角色.数据.参战宝宝.认证码 == bb数据.认证码 then
							玩家数据[玩家id].角色.数据.参战宝宝.气血 = bb数据.气血
							玩家数据[玩家id].角色.数据.参战宝宝.魔法 = bb数据.魔法
						end
					end
				end
			end

			if self.参战单位[n] ~= nil and self.参战单位[n].类型 == "角色" and self.参战单位[n].玩家id ~= 0 then
				local 玩家id = self.参战单位[n].玩家id

				if self.参战单位[n].助战编号 ~= nil then
					local 助战编号 = self.参战单位[n].助战编号

					角色耐久处理(self.参战单位[n].玩家id, 1, 玩家数据[self.参战单位[n].玩家id].助战.数据[助战编号], 助战编号, 0.05, self.参战单位[n].施法耐久)
					角色耐久处理(self.参战单位[n].玩家id, 1, 玩家数据[self.参战单位[n].玩家id].助战.数据[助战编号], 助战编号, 0.125, self.参战单位[n].攻击耐久)
					角色耐久处理(self.参战单位[n].玩家id, 2, 玩家数据[self.参战单位[n].玩家id].助战.数据[助战编号], 助战编号, 0.1, self.参战单位[n].防御耐久)
				else
					角色耐久处理(self.参战单位[n].玩家id, 1, 玩家数据[self.参战单位[n].玩家id].角色.数据, nil, 0.05, self.参战单位[n].施法耐久)
					角色耐久处理(self.参战单位[n].玩家id, 1, 玩家数据[self.参战单位[n].玩家id].角色.数据, nil, 0.125, self.参战单位[n].攻击耐久)
					角色耐久处理(self.参战单位[n].玩家id, 2, 玩家数据[self.参战单位[n].玩家id].角色.数据, nil, 0.1, self.参战单位[n].防御耐久)
				end

				self.参战单位[n].施法耐久 = 0
				self.参战单位[n].攻击耐久 = 0
				self.参战单位[n].防御耐久 = 0
			end

			if self.参战单位[n] ~= nil and self.参战单位[n].玩家id ~= 0 and self.参战单位[n].玩家id ~= 0 and self.参战单位[n].类型 == "bb" and self.参战单位[n].认证码 ~= nil then
				玩家数据[self.参战单位[n].玩家id].召唤兽:耐久处理(self.参战单位[n].玩家id, self.参战单位[n].认证码, 0.125, self.参战单位[n].bb耐久)

				self.参战单位[n].bb耐久 = 0
			end
		end
	end

	for i = 1, #待发送玩家 do
		发送数据(玩家数据[待发送玩家[i]].连接id, 33, 玩家数据[待发送玩家[i]].角色:取总数据(1))
	end
end

function 战斗处理类:取是否合击(编号, 目标)
	if self.参战单位[目标] == nil or self:取玩家战斗() == true then
		return false
	elseif self.参战单位[编号].队伍 == 0 or self.参战单位[编号].气血 <= 0 then
		return false
	elseif self.参战单位[目标].队伍 == self.参战单位[编号].队伍 then
		return false
	elseif self.参战单位[目标].气血 == 0 or self.参战单位[目标].法术状态.楚楚可怜 ~= nil or self.参战单位[目标].法术状态.催眠符 ~= nil or self.参战单位[目标].法术状态.分身术 ~= nil then
		return false
	elseif self.参战单位[目标].指令.类型 == "防御" then
		return false
	elseif ygsj() <= 10 then
		for n = 1, #self.参战单位 do
			if self:取行动状态(n) and self.参战单位[目标].法术状态.惊魂掌 == nil and self.参战单位[n].指令.类型 == "保护" and self.参战单位[n].队伍 == self.参战单位[目标].队伍 and self.参战单位[n].指令.目标 == 目标 then
				return false
			end
		end

		local 队友组 = {}
		local 队友 = 0

		for n = 1, #self.参战单位 do
			if n ~= 编号 and self:取行动状态(n) and self:取攻击状态(n) and self.参战单位[n].气血 > 0 and self.参战单位[n].队伍 == self.参战单位[编号].队伍 and self.参战单位[n].出手 ~= 1 and self.参战单位[n].指令.类型 == "攻击" and self.参战单位[n].指令.目标 == 目标 then
				队友组[#队友组 + 1] = n
			end
		end

		if #队友组 == 0 then
			return false
		else
			队友 = 队友组[取随机数(1, #队友组)]
			local 伤害 = self:取基础物理伤害(编号, 目标)
			伤害 = math.floor(伤害 + self:取基础物理伤害(队友, 目标) * 0.75)
			self.战斗流程[#self.战斗流程 + 1] = {
				流程 = 700,
				攻击方 = 编号,
				队友 = 队友,
				挨打方 = {
					{
						挨打方 = 目标,
						伤害 = 伤害,
						特效 = {}
					}
				}
			}
			self.战斗流程[#self.战斗流程].挨打方[1].死亡 = self:减少气血(目标, 伤害, 编号)
			self.参战单位[编号].指令.下达 = true
			self.参战单位[编号].指令.类型 = ""
			self.参战单位[队友].指令.下达 = true
			self.参战单位[队友].指令.类型 = ""

			return true
		end
	end

	return false
end

function 战斗处理类:经脉回合开始处理(编号)
	if self.参战单位[编号].奇经八脉 ~= nil then
		if 编号 ~= nil and self:取奇经八脉是否有(编号, "回魔") and self.参战单位[编号].最大魔法 - self.参战单位[编号].灵力 > 0 then
			self:增加魔法(编号, qz((self.参战单位[编号].最大魔法 - self.参战单位[编号].灵力) * 0.05))
		end

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "龙骇") and self.参战单位[编号].龙骇 == nil then
			self.参战单位[编号].法暴 = (self.参战单位[编号].法暴 or 基础法暴率) + 15
			self.参战单位[编号].龙骇 = true
		end

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "战魄") then
			self.参战单位[编号].愤怒 = self.参战单位[编号].愤怒 + 1
		end

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "默诵") then
			self.参战单位[编号].愤怒 = self.参战单位[编号].愤怒 + 3
		end

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "怒火释放") and self.参战单位[编号].怒火释放 == nil then
			if self.参战单位[编号].怒火释放 == nil then
				self.参战单位[编号].怒火释放 = 0
			end

			self.参战单位[编号].伤害 = qz(self.参战单位[编号].伤害 * 1.15)
			self.参战单位[编号].防御 = qz(self.参战单位[编号].防御 * 0.9)
			self.参战单位[编号].怒火释放 = true
		end

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "补缺") and self.参战单位[编号].魔法 <= self.参战单位[编号].最大魔法 * 0.3 and ygsj() <= 35 and self.参战单位[编号].主动技能1.凝神术 ~= nil then
			self:增益技能计算(编号, "凝神术", self:取技能等级(编号, "凝神术"))
		end

		if 编号 ~= nil and self:取奇经八脉是否有(编号, "不惊") and self.参战单位[编号].不惊 == nil then
			if self.参战单位[编号].不惊 == nil then
				self.参战单位[编号].不惊 = 0
			end

			self.参战单位[编号].伤害 = self.参战单位[编号].伤害 + qz(self.参战单位[编号].防御 * 0.1)
			self.参战单位[编号].不惊 = true
		end
	end
end

function 战斗处理类:经脉属性处理(编号)
	if self.参战单位[编号] == nil then
		return
	end

	if self.参战单位[编号].奇经八脉 == nil then
		self.参战单位[编号].奇经八脉 = {}
	end

	if self.参战单位[编号].门派 == "大唐官府" then
		self:添加主动技能(self.参战单位[编号], "翩鸿一击", self.参战单位[编号].被动技能.为官之道 or self.参战单位[编号].等级)

		if self.参战单位[编号].经脉流派 == "虎贲上将" and not self:取奇经八脉是否有(编号, "昂扬") then
			self:添加主动技能(self.参战单位[编号], "披坚执锐", self.参战单位[编号].等级)

			if 披坚执锐模式 ~= 0 and self.参战单位[编号].所有追加法术 ~= nil and #self.参战单位[编号].所有追加法术 > 1 then
				self.参战单位[编号].披坚执锐 = self.参战单位[编号].所有追加法术[ygsj(#self.参战单位[编号].所有追加法术)].名称
			end
		end

		if self.参战单位[编号].经脉流派 == "无双战神" then
			self.参战单位[编号].奇经八脉.連破 = 1
		end
	elseif self.参战单位[编号].门派 == "龙宫" then
		if self:取奇经八脉是否有(编号, "龙駭") then
			self.参战单位[编号].龙駭 = 1
		end

		if self:取奇经八脉是否有(编号, "龍骇") then
			self.参战单位[编号].龍骇 = 1
		end

		if self.参战单位[编号].经脉流派 == "海中蛟虬" or self.参战单位[编号].经脉流派 == "云龙真身" then
			self.参战单位[编号].奇经八脉.龙駭 = 1
		elseif self.参战单位[编号].经脉流派 == "沧海潜龙" then
			self.参战单位[编号].奇经八脉.龍骇 = 1
		end
	elseif self.参战单位[编号].门派 == "五庄观" then
		if self:取奇经八脉是否有(编号, "骤雨") then
			self.参战单位[编号].骤雨 = 1
		end

		if self.参战单位[编号].经脉流派 == "万寿真仙" then
			self:添加主动技能(self.参战单位[编号], "敲金击玉", self.参战单位[编号].被动技能.周易学 or self.参战单位[编号].等级)

			self.参战单位[编号].还丹 = 1
		elseif self.参战单位[编号].经脉流派 == "乾坤力士" then
			self.参战单位[编号].骤雨 = 1
		end
	elseif self.参战单位[编号].门派 == "狮驼岭" then
		if self.参战单位[编号].经脉流派 == "狂怒斗兽" then
			self.参战单位[编号].奇经八脉.狂怒 = 1
		elseif self.参战单位[编号].经脉流派 == "万兽之王" then
			self.参战单位[编号].驯兽师 = 1

			if self.参战单位[编号].召唤兽 ~= nil then
				self.参战单位[self.参战单位[编号].召唤兽].驯兽 = 1

				self:添加主动技能(self.参战单位[self.参战单位[编号].召唤兽], "幼狮之搏", self.参战单位[编号].被动技能.生死搏 or self.参战单位[编号].等级)

				if self.参战单位[self.参战单位[编号].召唤兽].夜战 == nil then
					self.参战单位[self.参战单位[编号].召唤兽].夜战 = 1
				end
			end

			self.参战单位[编号].狮魂 = 1

			self:添加主动技能(self.参战单位[编号], "驯兽重生", self.参战单位[编号].被动技能.训兽诀 or self.参战单位[编号].等级)
		end
	elseif self.参战单位[编号].门派 == "魔王寨" then
		if self:取奇经八脉是否有(编号, "魔冥") then
			self.参战单位[编号].魔冥 = 1
		end

		if self.参战单位[编号].经脉流派 == "盖世魔君" or self.参战单位[编号].经脉流派 == "平天大圣" then
			self.参战单位[编号].魔冥 = 1

			self:添加主动技能(self.参战单位[编号], "风云变色", self.参战单位[编号].被动技能.牛逼神功 or self.参战单位[编号].等级)
		end
	elseif self.参战单位[编号].门派 == "化生寺" then
		if self:取奇经八脉是否有(编号, "明光") then
			self.参战单位[编号].明光 = 18
		end

		if self.参战单位[编号].经脉流派 == "护法金刚" or self.参战单位[编号].经脉流派 == "杏林妙手" then
			self.参战单位[编号].明光 = 18

			if self.参战单位[编号].经脉流派 == "护法金刚" then
				self.参战单位[编号].聚气 = {
					金刚护体 = 1,
					金刚护法 = 1,
					达摩护体 = 1,
					佛法无边 = 1,
					一苇渡江 = 1,
					韦陀护法 = 1
				}
			end

			if self.参战单位[编号].经脉流派 == "杏林妙手" and (self.参战单位[编号].被动技能.小乘佛法 or 0) >= 45 then
				self.参战单位[编号].佛眷 = 1
			end
		end
	elseif self.参战单位[编号].门派 == "普陀山" then
		if self.参战单位[编号].经脉流派 == "落伽神女" then
			self.参战单位[编号].五行珠 = 1

			if self.参战单位[编号].飞升 == true and (self.参战单位[编号].被动技能.五行扭转 or 0) >= 120 then
				self.参战单位[编号].五行感应 = 1
			end

			self:添加主动技能(self.参战单位[编号], "巨岩击", self.参战单位[编号].被动技能.五行学说 or self.参战单位[编号].等级)
			self:添加主动技能(self.参战单位[编号], "苍茫刺", self.参战单位[编号].被动技能.五行学说 or self.参战单位[编号].等级)
