		self.参战单位[编号].法伤 = self.参战单位[编号].法伤 + 60
	end

	if self:取奇经八脉是否有(编号, "震天") and self.参战单位[编号].被动技能.震天诀 ~= nil and self.参战单位[编号].等级 <= self.参战单位[编号].被动技能.震天诀 then
		self.参战单位[编号].法伤 = self.参战单位[编号].法伤 + 60
	end

	if self:取奇经八脉是否有(编号, "灵光") then
		self.参战单位[编号].灵力 = self.参战单位[编号].灵力 + self.参战单位[编号].灵力 * 0.5
		self.参战单位[编号].法伤 = self.参战单位[编号].法伤 + self.参战单位[编号].法伤 * 0.5
	end

	if self:取奇经八脉是否有(编号, "神律") then
		self.参战单位[编号].必杀 = self.参战单位[编号].必杀 + 15
	end

	if self:取奇经八脉是否有(编号, "魔焰滔天") then
		self.参战单位[编号].法暴 = self.参战单位[编号].法暴 + 5
	end

	if self:取奇经八脉是否有(编号, "敛恨") then
		self.参战单位[编号].法防 = qz(self.参战单位[编号].法防 * 1.15)
		self.参战单位[编号].防御 = qz(self.参战单位[编号].防御 * 1.15)
		self.参战单位[编号].法暴 = (self.参战单位[编号].法暴 or 基础法暴率) + 5
	end

	if self:取奇经八脉是否有(编号, "狂狷") then
		self.参战单位[编号].伤害 = self.参战单位[编号].伤害 + self.参战单位[编号].力量 / self.参战单位[编号].耐力 * 16
	end

	if self:取奇经八脉是否有(编号, "烈焰真诀") then
		self.参战单位[编号].法暴 = self.参战单位[编号].法暴 + 10
	end

	if self:取奇经八脉是否有(编号, "归气") then
		if self.参战单位[编号].治疗能力 == nil then
			self.参战单位[编号].治疗能力 = 0
		end

		self.参战单位[编号].治疗能力 = self.参战单位[编号].治疗能力 + qz(math.max(self.参战单位[编号].灵力, self.参战单位[编号].法伤) / 10)
	end

	if self:取奇经八脉是否有(编号, "佛誉") then
		if self.参战单位[编号].治疗能力 == nil then
			self.参战单位[编号].治疗能力 = 0
		end

		self.参战单位[编号].治疗能力 = self.参战单位[编号].治疗能力 + 200
	end

	if self:取奇经八脉是否有(编号, "意境") then
		if self.参战单位[编号].治疗能力 == nil then
			self.参战单位[编号].治疗能力 = 0
		end

		self.参战单位[编号].治疗能力 = self.参战单位[编号].治疗能力 + self.参战单位[编号].武器伤害 * 0.18
	end

	if self:取奇经八脉是否有(编号, "驭意") then
		self.参战单位[编号].速度 = self.参战单位[编号].速度 + qz1(self.参战单位[编号].魔力 * 0.05)
		self.参战单位[编号].法伤 = self.参战单位[编号].法伤 + qz1(self.参战单位[编号].魔力 * 0.1)
		self.参战单位[编号].法防 = self.参战单位[编号].法防 - qz(self.参战单位[编号].魔力 * 0.24)
	end

	if self:取奇经八脉是否有(编号, "神凝") then
		if self.参战单位[编号].抵抗封印等级 == nil then
			self.参战单位[编号].抵抗封印等级 = 0
		end

		self.参战单位[编号].抵抗封印等级 = self.参战单位[编号].抵抗封印等级 + 100
	end

	if self:取奇经八脉是否有(编号, "破击") then
		self.参战单位[编号].必杀 = (self.参战单位[编号].必杀 or 基础暴击率) + 20
	end

	if self:取奇经八脉是否有(编号, "慈心") then
		self.参战单位[编号].防御 = self.参战单位[编号].防御 + 200
	end

	if self:取奇经八脉是否有(编号, "魔息") then
		self.参战单位[编号].防御 = self.参战单位[编号].防御 * 1.3
		self.参战单位[编号].法防 = self.参战单位[编号].法防 * 1.3
	end

	if self:取奇经八脉是否有(编号, "傲视") then
		self.参战单位[编号].伤害 = self.参战单位[编号].伤害 + 200
	end

	if self:取奇经八脉是否有(编号, "锤炼") then
		self.参战单位[编号].伤害 = self.参战单位[编号].伤害 + self.参战单位[编号].武器伤害 * 0.04
	end

	if self:取奇经八脉是否有(编号, "神附") then
		self.参战单位[编号].伤害 = self.参战单位[编号].伤害 + self.参战单位[编号].力量 * 0.08
	end

	if self:取奇经八脉是否有(编号, "海沸") then
		self.参战单位[编号].伤害 = self.参战单位[编号].伤害 + qz1(self.参战单位[编号].力量 * 0.1) + 40
	end

	if self:取奇经八脉是否有(编号, "纯净") then
		self.参战单位[编号].最大气血 = self.参战单位[编号].最大气血 + math.max(self.参战单位[编号].法伤, self.参战单位[编号].法伤) / 2
	end

	if self:取奇经八脉是否有(编号, "护佑") then
		self.参战单位[编号].防御 = self.参战单位[编号].防御 + 50
		self.参战单位[编号].法防 = self.参战单位[编号].法防 + 50
	end

	if self:取奇经八脉是否有(编号, "狂袭") then
		self.参战单位[编号].偷袭 = self.参战单位[编号].偷袭 or 1
		self.参战单位[编号].伤害 = self.参战单位[编号].伤害 + self.参战单位[编号].武器伤害 * 0.18
	end

	if self:取奇经八脉是否有(编号, "风刃") then
		self.参战单位[编号].溅射人数 = self.参战单位[编号].溅射人数 + 3
		self.参战单位[编号].溅射 = (self.参战单位[编号].溅射 or 0) + 0.001
	end

	if self:取奇经八脉是否有(编号, "倩影") then
		self.参战单位[编号].倩影 = {
			恢复速度 = 0,
			初速度 = self.参战单位[编号].速度 + 0
		}
	end
end

function 战斗处理类:发送退出信息()
	for n = 1, #self.参战玩家 do
		if 自动遇怪[self.参战玩家[n].id] ~= nil then
			自动遇怪[self.参战玩家[n].id] = os.time()
		end

		if 自动捉鬼[self.参战玩家[n].id] ~= nil then -------45
			自动捉鬼[self.参战玩家[n].id] = os.time()
		end

		if 玩家数据[self.参战玩家[n].id] ~= nil then
			发送数据(玩家数据[self.参战玩家[n].id].连接id, 5505)

			玩家数据[self.参战玩家[n].id].战斗 = 0
			玩家数据[self.参战玩家[n].id].遇怪时间 = os.time() + 取随机数(10, 20)

			玩家数据[self.参战玩家[n].id].道具:重置法宝回合(self.参战玩家[n].id)

			玩家数据[self.参战玩家[n].id].角色.数据.战斗开关 = nil

			地图处理类:设置战斗开关(self.参战玩家[n].id)

			if 玩家数据[self.参战玩家[n].id].战斗对话 ~= nil then
				发送数据(玩家数据[self.参战玩家[n].id].连接id, 1501, 玩家数据[self.参战玩家[n].id].战斗对话)
			end

			if self.战斗类型 == 100011 then
				发送数据(玩家数据[self.参战玩家[n].id].连接id, 1501, self.对话数据)
			end

			玩家数据[self.参战玩家[n].id].战斗对话 = nil

			if self.参战玩家[n].断线 then
				系统处理类:断开游戏(self.参战玩家[n].id)
			end
		end

		if self.战斗类型 == 100108 and self.战斗失败 == false then
			local id = self.进入战斗玩家id
			if 通天塔数据[id].层数 >= 20000 or 通天塔数据[id].失败 == true then
				添加最后对话(id, "#Y/自动战斗通天塔大于20000层,请重置后在来进行挑战!")
			else
				战斗准备类:创建战斗(id, 100108, 1008609)
			end
		end

		if self.战斗类型 == 100019 and self.玩家胜利 and ygsj() <= 2 then
			local id = self.进入战斗玩家id

			if 玩家数据[id].角色.数据.地图数据.编号 ~= 1620 then
				local 随机递增 = 取随机数(1, 3)
				local 传送地图 = 玩家数据[id].角色.数据.地图数据.编号 + 随机递增

				if 传送地图 > 1620 then
					传送地图 = 1620
				end

				local xy = 地图处理类.地图坐标[传送地图]:取随机点()

				地图处理类:跳转地图(id, 传送地图, xy.x, xy.y)
				常规提示(id, "#Y你击败了迷宫小怪后，意外地发现自己来到了#R" .. 取地图名称(传送地图))
			end
		end
	end

	for i, v in pairs(self.观战玩家) do
		if 玩家数据[i] ~= nil then
			if 自动遇怪[i] ~= nil then
				自动遇怪[i] = os.time()
			end

			if 自动捉鬼[i] ~= nil then
				自动捉鬼[i] = os.time()
			end

			发送数据(玩家数据[i].连接id, 5505)

			玩家数据[i].战斗 = 0
			玩家数据[i].观战 = nil
			玩家数据[i].遇怪时间 = os.time() + 取随机数(10, 20)
		end
	end

	self.结束条件 = true
	local id = self.进入战斗玩家id

	if self.战斗类型 == 100050 and self.战斗失败 == false then
		local id = self.进入战斗玩家id
		local 剑会假人属性 = {}
		local 武器伤害 = 0

		for n = 1, 5 do
			if 玩家数据[id].角色.数据.装备[3] ~= nil then
				local 临时武器 = table.loadstring(table.tostring(玩家数据[id].道具.数据[玩家数据[id].角色.数据.装备[3]]))
				武器伤害 = qz(临时武器.伤害 + 临时武器.命中 / 3)
			end

			剑会假人属性[#剑会假人属性 + 1] = {
				角色分类 = "角色",
				名称 = "飞升守护者",
				模型 = 玩家数据[id].角色.数据.模型,
				等级 = 玩家数据[id].角色.数据.等级,
				气血 = 玩家数据[id].角色.数据.最大气血,
				魔法 = 玩家数据[id].角色.数据.最大魔法,
				伤害 = 玩家数据[id].角色.数据.伤害,
				灵力 = 玩家数据[id].角色.数据.灵力 + 玩家数据[id].角色.数据.灵力,
				法伤 = 玩家数据[id].角色.数据.法伤 + 玩家数据[id].角色.数据.法伤,
				速度 = 玩家数据[id].角色.数据.速度,
				防御 = 玩家数据[id].角色.数据.防御,
				法防 = 玩家数据[id].角色.数据.法防 + 玩家数据[id].角色.数据.法防,
				攻击修炼 = 玩家数据[id].角色.数据.修炼.攻击修炼[1],
				法术修炼 = 玩家数据[id].角色.数据.修炼.法术修炼[1],
				防御修炼 = 玩家数据[id].角色.数据.修炼.防御修炼[1],
				抗法修炼 = 玩家数据[id].角色.数据.修炼.抗法修炼[1],
				门派 = 玩家数据[id].角色.数据.门派,
				五维属性 = {
