function 战斗处理类:更新(dt)
	if self.回合进程 == "命令回合" then
		if 服务端参数.自动战斗等待时间 <= os.time() - self.等待起始 then
			for n = 1, #self.参战单位 do
				if self.参战单位[n].自动战斗 and self.参战单位[n].指令.下达 == false then
					if self.参战单位[n].自动指令 ~= nil and 玩家数据[self.参战单位[n].玩家id] ~= nil and 玩家数据[self.参战单位[n].玩家id].角色.数据.自动战斗 then
						self:自动战斗目标处理(n, {
							类型 = self.参战单位[n].自动指令.类型,
							技能名 = self.参战单位[n].自动指令.参数,
							目标 = self.参战单位[n].自动指令.目标,
							相对目标 = self.参战单位[n].自动指令.相对目标
						})

						if self.参战单位[n].指令.类型 == "法术" then
							if self.参战单位[n].指令.参数 == "" then
								self.参战单位[n].指令.类型 = "攻击"
								self.参战单位[n].指令.目标 = self:取单个敌方目标(n)
							else
								local 临时技能 = 取法术技能(self.参战单位[n].指令.参数)
								local dw = self.参战单位[n].指令.目标

								if 临时技能[3] == 4 then
									if dw == nil or self.参战单位[dw] == nil or self.参战单位[dw].队伍 == self.队伍区分[1] or self:取目标状态(dw, n, 2) == false then
										self.参战单位[n].指令.目标 = self:取单个敌方目标(n)
									end
								elseif dw == nil or self.参战单位[dw] == nil or self.参战单位[dw].队伍 ~= self.队伍区分[1] then
									self.参战单位[n].指令.目标 = self:取单个友方目标(n)
								end
							end
						end

						if self.参战单位[self.参战单位[n].指令.目标] == nil and self.参战单位[n].指令.类型 ~= "防御" and self.参战单位[n].指令.类型 ~= "逃跑" then
							self.参战单位[n].指令.类型 = "攻击"
							self.参战单位[n].指令.目标 = self:取单个敌方目标(n)
						end
					elseif self.参战单位[n].指令.类型 ~= "逃跑" then
						self.参战单位[n].指令.类型 = "攻击"
						self.参战单位[n].指令.目标 = self:取单个敌方目标(n)
					end

					self.参战单位[n].指令.下达 = true

					if 玩家数据 ~= nil and self.参战单位[n].玩家id ~= 0 and 玩家数据[self.参战单位[n].玩家id] ~= nil then
						发送数据(玩家数据[self.参战单位[n].玩家id].连接id, 5511)
					end

					if self.参战单位[n].队伍 ~= 0 and self.参战单位[n].类型 == "角色" and self.参战单位[n].助战编号 == nil then
						self.加载数量 = self.加载数量 - 1
					end
				end
			end
		end

		if self.加载数量 <= 0 then
			self.回合进程 = "计算回合"

			self:设置执行回合()
		end

		if os.time() - self.等待起始 >= 服务端参数.回合命令时间 + 2 then
			self.回合进程 = "计算回合"

			self:设置执行回合()
		end
	elseif self.回合进程 == "执行回合" and self.执行等待 <= os.time() and self.回合进程 ~= "结束回合" then
		self.回合进程 = "结束回合"

		self:结算处理()
	end
end

